    suspicious.forEach(item => {
        report += `[${item.product.name} - ${item.name}] Price: Rp ${Number(item.costPrice).toLocaleString()} / ${item.unit}\n`;
    });

    fs.writeFileSync('scan_report.txt', report);
    console.log('Report written to scan_report.txt');
}

