'use client';

import React, { useEffect, useRef, useState } from 'react';
import HeroSlider from '@/components/HeroSlider';
import Button from '@/components/Button';
import MerchandiseWorkflow from '@/components/MerchandiseWorkflow';

import Link from 'next/link';
import { Shirt, Coffee, PenTool, ShoppingBag, Gift, Package, ArrowRight, Sparkles } from 'lucide-react';
import { analytics } from '@/lib/analytics';

interface HeroSlide {
    id: string;
    title: string;
    subtitle: string;
    mediaType: 'IMAGE' | 'VIDEO';
    imageUrl: string | null;
    videoUrl: string | null;
    ctaLabel: string | null;
    ctaLink: string | null;
    sortOrder: number;
}

interface Collection {
    id: string;
    slug: string;
    name: string;
    heroTitle: string;
    heroSubtitle: string;
    highlights: string[];
    coverImage: string | null;
}

interface MerchSettings {
    heroTitle: string;
    heroSubtitle: string;
    heroTagline: string;
    heroCtaLabel: string;
    heroCtaLink: string;
    highlightLine: string;
    mockupTitle: string;
    mockupSubtitle: string;
    mockupTagline: string;
    mockupEnabled: boolean;
}

export default function MerchandisePage() {
    const [visibleSections, setVisibleSections] = useState<Set<string>>(new Set());

    const [heroSlides, setHeroSlides] = useState<HeroSlide[]>([]);
    const [collections, setCollections] = useState<Collection[]>([]);
    const [settings, setSettings] = useState<MerchSettings | null>(null);
    const [isLoadingSlides, setIsLoadingSlides] = useState(true);
    const [isLoadingCollections, setIsLoadingCollections] = useState(true);
    const [isLoadingSettings, setIsLoadingSettings] = useState(true);
    const sectionRefs = useRef<{ [key: string]: HTMLElement | null }>({});

    // Fetch hero slides
    useEffect(() => {
        const fetchHeroSlides = async () => {
            try {
                const res = await fetch('/api/public/merch/hero-slides');
                const data = await res.json();
                setHeroSlides(Array.isArray(data) ? data : []);
            } catch (error) {
                console.error('Failed to fetch hero slides:', error);
                setHeroSlides([]);
            } finally {
                setIsLoadingSlides(false);
            }
        };

        fetchHeroSlides();
    }, []);

    // Fetch collections
    useEffect(() => {
        const fetchCollections = async () => {
            try {
                console.log('Fetching collections...');
                const res = await fetch('/api/public/merch/collections');
                console.log('Collections response status:', res.status);
                const data = await res.json();
                console.log('Collections data:', data);
                setCollections(Array.isArray(data) ? data : []);
            } catch (error) {
                console.error('Failed to fetch collections:', error);
                setCollections([]);
            } finally {
                setIsLoadingCollections(false);
                console.log('Collections loading complete');
            }
        };

        fetchCollections();
    }, []);

    // Fetch settings
    useEffect(() => {
        const fetchSettings = async () => {
            try {
                const res = await fetch('/api/public/merch/settings');
                const data = await res.json();
                setSettings(data);
            } catch (error) {
                console.error('Failed to fetch settings:', error);
            } finally {
                setIsLoadingSettings(false);
            }
        };

        fetchSettings();
    }, []);

    // Track page view
    useEffect(() => {
        analytics.trackPageView('merch', '/merchandise');
    }, []);


    useEffect(() => {
        const observers: IntersectionObserver[] = [];

        Object.keys(sectionRefs.current).forEach((key) => {
            const element = sectionRefs.current[key];
            if (element) {
                const observer = new IntersectionObserver(
                    (entries) => {
                        entries.forEach((entry) => {
                            if (entry.isIntersecting) {
                                setVisibleSections((prev) => new Set(prev).add(key));
                            }
                        });
                    },
                    { threshold: 0.1 }
                );
                observer.observe(element);
                observers.push(observer);
            }
        });

        return () => {
            observers.forEach((observer) => observer.disconnect());
        };
    }, []);

    const isVisible = (key: string) => visibleSections.has(key);

    // Icon mapping for collections
    const iconMap: Record<string, React.ReactNode> = {
        'Apparel': <Shirt size={32} />,
        'Drinkware': <Coffee size={32} />,
        'Office': <PenTool size={32} />,
        'Bags': <ShoppingBag size={32} />,
        'Hampers': <Gift size={32} />,
        'Gift': <Gift size={32} />
    };

    // Fallback categories if no collections from CMS
    const fallbackCategories = [
        { name: "Apparel", items: "T-shirts, Hoodies, Jackets", icon: <Shirt size={32} />, link: "/merchandise/collections/apparel" },
        { name: "Drinkware", items: "Tumblers, Bottles", icon: <Coffee size={32} />, link: "/merchandise/collections/drinkware" },
        { name: "Office & Stationery Kits", items: "Notebooks, Pens, Desk Organizers", icon: <PenTool size={32} />, link: "/merchandise/collections/office-kits" },
        { name: "Bags", items: "Totebags, Drawstring Bags", icon: <ShoppingBag size={32} />, link: "/merchandise/collections/bags" },
        { name: "Corporate & Event Hampers", items: "Custom Gift Sets", icon: <Gift size={32} />, link: "/merchandise/collections/hampers" },
    ];

    // Use collections from CMS if available, otherwise use fallback
    const displayCategories = collections.length > 0
        ? collections.map(col => ({
            name: col.name,
            items: col.heroSubtitle,
            icon: iconMap[col.name] || <Package size={32} />,
            image: col.coverImage,
            link: `/merchandise/collections/${col.slug}`
        }))
        : fallbackCategories;

    const packages = [
        { title: "Employee Onboarding Kit", desc: "Welcome new hires with a premium kit." },
        { title: "Event & Seminar Pack", desc: "Essentials for your next corporate event." },
        { title: "Premium Corporate Gifts", desc: "High-end gifts for VIP clients." },
    ];

    return (
        <div className="flex flex-col gap-24 pb-20">
            {/* Hero Slider - Dynamic Content from CMS */}
            {!isLoadingSlides && heroSlides.length > 0 && (
                <HeroSlider brandSlug="merch" slides={heroSlides} />
            )}

            {/* Fallback if no slides */}
            {!isLoadingSlides && heroSlides.length === 0 && (
                <section className="bg-amber-50/70 py-20 sm:py-24 md:py-28">
                    <div className="mx-auto max-w-5xl px-4 md:px-6 text-center">
                        <h1 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold text-stone-900 leading-tight tracking-tight">
                            {settings?.heroTitle || 'Modern Brands Deserve Thoughtful Merchandise'}
                        </h1>
                        <p className="mt-6 text-base sm:text-lg md:text-xl text-stone-600 max-w-3xl leading-relaxed mx-auto">
                            {settings?.heroSubtitle || 'ACHIERA Merchandise helps companies create lasting impressions with high-quality products.'}
                        </p>
                        {settings?.heroTagline && (
                            <p className="mt-4 text-sm text-amber-700 font-medium">
                                {settings.heroTagline}
                            </p>
                        )}
                        {settings?.highlightLine && (
                            <div className="mt-8">
                                <span className="inline-block px-4 py-2 bg-amber-100 text-amber-900 rounded-full text-sm font-medium">
                                    {settings.highlightLine}
                                </span>
                            </div>
                        )}
                    </div>
                </section>
            )}



            {/* Categories - Editorial Style - DYNAMIC FROM CMS */}
            <section
                ref={(el) => { sectionRefs.current['categories'] = el; }}
                className="container mx-auto px-4 md:px-6"
            >
                <h2 className={`text-3xl md:text-5xl font-serif italic text-[var(--foreground)] mb-12 text-center transition-all duration-700 transform ${isVisible('categories') ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
                    }`}>
                    Curated Collections
                </h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
                    {displayCategories.map((cat, idx) => (
                        <Link
                            href={cat.link}
                            key={idx}
                            className={`group relative overflow-hidden rounded-xl bg-[var(--background)] border border-[var(--border)] shadow-sm hover:shadow-2xl hover:-translate-y-2 transition-all duration-500 transform ${isVisible('categories') ? 'opacity-100 scale-100' : 'opacity-0 scale-95'
                                }`}
                            style={{ transitionDelay: `${idx * 100 + 200}ms` }}
                        >
                            <div className="aspect-[4/3] bg-[var(--muted)]/50 flex items-center justify-center group-hover:scale-110 transition-transform duration-700 relative">
                                {(cat as any).image ? (
                                    <img
                                        src={(cat as any).image}
                                        alt={cat.name}
                                        className="w-full h-full object-cover"
                                    />
                                ) : (
                                    <div className="text-[var(--primary)] opacity-50 group-hover:opacity-100 transition-opacity duration-500">{cat.icon}</div>
                                )}
                            </div>
                            <div className="p-6">
                                <h3 className="text-2xl font-bold text-[var(--foreground)] mb-2 group-hover:text-[var(--primary)] transition-colors">{cat.name}</h3>
                                <p className="text-[var(--muted-foreground)] mb-4">{cat.items}</p>
                                <div className="flex items-center text-[var(--primary)] font-medium opacity-0 group-hover:opacity-100 transform translate-y-2 group-hover:translate-y-0 transition-all duration-300">
                                    View Collection <ArrowRight size={16} className="ml-2 transition-transform group-hover:translate-x-1" />
                                </div>
                            </div>
                        </Link>
                    ))}
                </div>
            </section>

            {/* Packages - Clean & Minimal */}
            <section
                ref={(el) => { sectionRefs.current['packages'] = el; }}
                className="container mx-auto px-4 md:px-6"
            >
                <div className="bg-[var(--muted)]/20 rounded-3xl p-10 md:p-16 border border-[var(--border)]">
                    <h2 className={`text-3xl md:text-4xl font-bold text-[var(--foreground)] mb-12 text-center transition-all duration-700 transform ${isVisible('packages') ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
                        }`}>
                        Ready-to-Go Packages
                    </h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                        {packages.map((pkg, idx) => (
                            <div
                                key={idx}
                                className={`bg-[var(--background)] p-8 rounded-xl border border-[var(--border)] hover:border-[var(--primary)] hover:-translate-y-1 transition-all duration-500 shadow-sm hover:shadow-lg transform ${isVisible('packages') ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
                                    }`}
                                style={{ transitionDelay: `${idx * 150 + 300}ms` }}
                            >
                                <div className="w-12 h-12 rounded-full bg-[var(--primary)]/10 flex items-center justify-center text-[var(--primary)] mb-6 group-hover:scale-110 transition-transform duration-300">
                                    <Package size={24} />
                                </div>
                                <h3 className="text-xl font-bold text-[var(--foreground)] mb-3">{pkg.title}</h3>
                                <p className="text-[var(--muted-foreground)]">{pkg.desc}</p>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* Workflow - Interactive Process */}
            <MerchandiseWorkflow />

            {/* CTA */}
            <section
                ref={(el) => { sectionRefs.current['cta'] = el; }}
                className="container mx-auto px-4 md:px-6 text-center"
            >
                <div className={`transition-all duration-700 transform ${isVisible('cta') ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
                    }`}>
                    <h2 className="text-3xl md:text-4xl font-bold text-[var(--foreground)] mb-8">Ready to elevate your brand merchandise?</h2>
                    <Link href="/contact">
                        <Button variant="primary" size="lg" className="shadow-xl hover:shadow-2xl hover:scale-105 transition-all duration-300">Request Catalogue</Button>
                    </Link>
                </div>
            </section>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { Loader2, Send, CheckCircle2, Download } from 'lucide-react';
import { toast } from 'sonner';
import Link from 'next/link';

export default function CatalogueRequestPage() {
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isSuccess, setIsSuccess] = useState(false);
    const [formData, setFormData] = useState({
        companyName: '',
        contactName: '',
        email: '',
        phone: '',
        notes: ''
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            const res = await fetch('/api/public/merch/catalogue-request', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData)
            });

            if (!res.ok) throw new Error('Failed to submit request');

            setIsSuccess(true);
            toast.success('Request submitted successfully!');
        } catch (error) {
            console.error(error);
            toast.error('Failed to submit request. Please try again.');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="min-h-screen bg-stone-50 py-20 px-6">
            <div className="max-w-4xl mx-auto">
                <div className="bg-white rounded-2xl shadow-xl overflow-hidden flex flex-col md:flex-row">

                    {/* Left: Info Side */}
                    <div className="md:w-5/12 bg-stone-900 p-10 text-white flex flex-col justify-between relative overflow-hidden">
                        <div className="relative z-10">
                            <h2 className="text-3xl font-bold mb-6 font-display">Achiera Merch Catalogue</h2>
                            <p className="text-stone-300 mb-8 leading-relaxed">
                                Get access to our complete collection of premium corporate merchandise.
                                Discover exclusive items not listed on the public site.
                            </p>

                            <ul className="space-y-4 text-stone-300">
                                <li className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-stone-800 flex items-center justify-center text-amber-500">
                                        <CheckCircle2 className="w-4 h-4" />
                                    </div>
                                    <span>Complete Price List</span>
                                </li>
                                <li className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-stone-800 flex items-center justify-center text-amber-500">
                                        <CheckCircle2 className="w-4 h-4" />
                                    </div>
                                    <span>Volume Discount Tiers</span>
                                </li>
                                <li className="flex items-center gap-3">
                                    <div className="w-8 h-8 rounded-full bg-stone-800 flex items-center justify-center text-amber-500">
                                        <CheckCircle2 className="w-4 h-4" />
                                    </div>
                                    <span>Customization Options</span>
                                </li>
                            </ul>
                        </div>

                        <div className="relative z-10 mt-12">
                            <p className="text-sm text-stone-500">
                                Trusted by 50+ Corporate Partners
                            </p>
                        </div>

                        {/* Abstract Decor */}
                        <div className="absolute top-0 right-0 w-64 h-64 bg-amber-600/20 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
                        <div className="absolute bottom-0 left-0 w-48 h-48 bg-blue-600/10 rounded-full blur-3xl translate-y-1/2 -translate-x-1/2" />
                    </div>

                    {/* Right: Form Side */}
                    <div className="md:w-7/12 p-10 bg-white">
                        {isSuccess ? (
                            <div className="h-full flex flex-col items-center justify-center text-center space-y-6">
                                <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center text-green-600 mb-2">
                                    <CheckCircle2 className="w-8 h-8" />
                                </div>
                                <h3 className="text-2xl font-bold text-stone-900">Request Sent!</h3>
                                <p className="text-stone-500 max-w-sm">
                                    Thank you for your interest. Our team has received your request and will send the catalogue to <b>{formData.email}</b> shortly.
                                </p>
                                <Link
                                    href="/merchandise"
                                    className="px-6 py-2.5 bg-stone-900 text-white rounded-lg hover:bg-stone-800 transition-colors font-medium mt-4"
                                >
                                    Back to Merchandise
                                </Link>
                            </div>
                        ) : (
                            <>
                                <div className="mb-8">
                                    <h3 className="text-xl font-bold text-stone-900">Request Download</h3>
                                    <p className="text-sm text-stone-500">Please fill in your details to receive the PDF.</p>
                                </div>

                                <form onSubmit={handleSubmit} className="space-y-5">
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                        <div>
                                            <label className="block text-sm font-medium text-stone-700 mb-1">Company Name</label>
                                            <input
                                                type="text"
                                                required
                                                className="w-full px-4 py-2 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                                placeholder="e.g. Acme Corp"
                                                value={formData.companyName}
                                                onChange={e => setFormData({ ...formData, companyName: e.target.value })}
                                            />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-stone-700 mb-1">Contact Name</label>
                                            <input
                                                type="text"
                                                required
                                                className="w-full px-4 py-2 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                                placeholder="e.g. John Doe"
                                                value={formData.contactName}
                                                onChange={e => setFormData({ ...formData, contactName: e.target.value })}
                                            />
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                        <div>
                                            <label className="block text-sm font-medium text-stone-700 mb-1">Email Address</label>
                                            <input
                                                type="email"
                                                required
                                                className="w-full px-4 py-2 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                                placeholder="john@example.com"
                                                value={formData.email}
                                                onChange={e => setFormData({ ...formData, email: e.target.value })}
                                            />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium text-stone-700 mb-1">WhatsApp / Phone</label>
                                            <input
                                                type="text"
                                                className="w-full px-4 py-2 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                                placeholder="+62..."
                                                value={formData.phone}
                                                onChange={e => setFormData({ ...formData, phone: e.target.value })}
                                            />
                                        </div>
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-stone-700 mb-1">Notes (Optional)</label>
                                        <textarea
                                            rows={2}
                                            className="w-full px-4 py-2 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none resize-none"
                                            placeholder="Specific needs or event dates..."
                                            value={formData.notes}
                                            onChange={e => setFormData({ ...formData, notes: e.target.value })}
                                        />
                                    </div>

                                    <button
                                        type="submit"
                                        disabled={isSubmitting}
                                        className="w-full py-3 bg-amber-600 hover:bg-amber-700 text-white rounded-lg font-bold shadow-sm transition-all flex items-center justify-center gap-2 group"
                                    >
                                        {isSubmitting ? (
                                            <Loader2 className="w-5 h-5 animate-spin" />
                                        ) : (
                                            <>
                                                <span>Request Catalogue</span>
                                                <Download className="w-4 h-4 group-hover:translate-y-0.5 transition-transform" />
                                            </>
                                        )}
                                    </button>

                                    <p className="text-xs text-center text-stone-400 mt-4">
                                        By downloading, you agree to receive follow-up communication from Achiera Merch.
                                    </p>
                                </form>
                            </>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

import React from 'react';
import Link from 'next/link';
import { prisma } from '@/lib/prisma';

export const dynamic = 'force-dynamic';
export const revalidate = 0;

export default async function RasaIbuAboutPage() {
    // Fetch Brand RASA IBU
    const brand = await prisma.brand.findUnique({
        where: { slug: 'rasa-ibu' },
        include: { brandConfig: true }
    });

    const config = brand?.brandConfig as any;

    // Mapping CMS fields
    const heroTitle = config?.aboutHeroTitle || "Berawal dari Kejujuran Dapur.";
    const heroSubtitle = config?.aboutHeroSubtitle || "Tentang Rasa Ibu";
    const storyTitle = config?.aboutStoryTitle || "Kisah Kami";
    const storyContent = Array.isArray(config?.aboutStoryContent) ? config.aboutStoryContent : [
        "Dimulai dari tahun 2022, saat sang pendiri menyadari betapa sulitnya menemukan makanan siap saji yang tidak mengandalkan pengawet dan penyedap rasa berlebih.",
        "Kami percaya bahwa makanan adalah bahasa cinta paling universal. Namun, rasa sayang itu akan hilang jika makanan yang kita sajikan untuk keluarga mengandung bahan-bahan kimia yang tidak kita pahami.",
        "Itulah mengapa di Rasa Ibu, kami menerapkan prinsip \"Clean Label\". Jika bahan tersebut tidak ada di dapur ibu Anda, maka tidak akan ada di dapur kami."
    ];
    const storyImage = config?.aboutStoryImage || null;

    // Pillars
    const valuesTitle = config?.aboutValuesTitle || "Tiga Pilar Kami";
    const valuesList = config?.aboutValuesList || [
        { title: 'Kualitas Bahan', desc: 'Kami bekerja sama dengan peternak dan petani lokal untuk memastikan setiap potongan daging dan sayur adalah yang terbaik.' },
        { title: 'Higienitas', desc: 'Dapur kami melewati audit kebersihan ketat setiap minggunya. Keamanan pangan adalah prioritas kami.' },
        { title: 'Ketulusan', desc: 'Setiap kemasan Rasa Ibu dibuat dengan doa dan harapan agar meja makan Anda selalu dipenuhi kehangatan.' },
    ];

    // CTA
    const ctaTitle = config?.aboutCtaTitle || "Ingin Kenal Lebih Dekat?";
    const ctaContent = config?.aboutCtaContent || "Kami sangat terbuka untuk mendengar saran, kritik, atau sekadar cerita tentang momen makan malam Anda.";
    const ctaPrimary = config?.aboutCtaPrimary || "Hubungi Kami";
    const ctaPrimaryLink = config?.aboutCtaPrimaryLink || "/rasa-ibu/contact";
    const ctaSecondary = config?.aboutCtaSecondary || "Lihat Menu";
    const ctaSecondaryLink = config?.aboutCtaSecondaryLink || "/rasa-ibu/products";

    return (
        <div className="py-16 md:py-24 space-y-24 md:space-y-32">
            {/* 1. Intro Section */}
            <section className="max-w-7xl mx-auto px-6">
                <div className="max-w-3xl space-y-6 md:space-y-8">
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66]">{heroSubtitle}</span>
                    <h1 className="text-3xl md:text-6xl font-black tracking-tight text-[#1A241A] leading-tight whitespace-pre-line">
                        {heroTitle}
                    </h1>
                </div>
            </section>

            {/* 2. Story Grid */}
            <section className="bg-[#1A241A] text-[#FDFBF7] py-20 md:py-32 px-6">
                <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-2 gap-12 md:gap-24 items-center">
                    <div className="aspect-[4/5] bg-white/5 rounded-[2rem] md:rounded-[3rem] overflow-hidden">
                        {storyImage ? (
                            <img src={storyImage} alt="Kisah Kami" className="w-full h-full object-cover" />
                        ) : (
                            <div className="w-full h-full flex items-center justify-center italic text-white/10 p-12 text-center text-sm">
                                [Pilih gambar di Dashboard &gt; Website Content &gt; About Page]
                            </div>
                        )}
                    </div>
                    <div className="space-y-8 md:space-y-10">
                        <h2 className="text-3xl md:text-4xl font-black tracking-tight">{storyTitle}</h2>
                        <div className="space-y-4 md:space-y-6 text-[#A0A8A0] font-medium leading-relaxed">
                            {storyContent.map((para: string, idx: number) => (
                                <p key={idx} className={idx === storyContent.length - 1 ? "text-[#FDFBF7]" : ""}>
                                    {para}
                                </p>
                            ))}
                        </div>
                    </div>
                </div>
            </section>

            {/* 3. The Pillars */}
            <section className="max-w-7xl mx-auto px-6 py-12">
                <div className="text-center mb-16 md:mb-24 space-y-4">
                    <h2 className="text-3xl md:text-4xl font-black tracking-tight">{valuesTitle}</h2>
                    <div className="h-1 w-20 bg-[#8B7E66] mx-auto"></div>
                </div>

                <div className="flex flex-col md:flex-row flex-wrap justify-center items-center md:items-start gap-12 md:gap-24 lg:gap-32">
                    {valuesList.map((item: any, idx: number) => (
                        <div key={idx} className="space-y-4 md:space-y-6 max-w-sm w-full md:w-[25%] flex flex-col items-center md:items-start text-center md:text-left">
                            <span className="text-3xl md:text-4xl font-serif italic text-[#8B7E66]">0{idx + 1}.</span>
                            <div className="space-y-2">
                                <h3 className="text-lg md:text-xl font-black uppercase tracking-widest">{item.title}</h3>
                                <p className="text-xs md:text-sm text-gray-500 font-medium leading-relaxed whitespace-pre-line">
                                    {item.desc}
                                </p>
                            </div>
                        </div>
                    ))}
                </div>
            </section>

            {/* 4. Contact Hook */}
            <section className="max-w-7xl mx-auto px-6 pb-24 md:pb-40">
                <div className="bg-[#F9F7F2] rounded-[2rem] md:rounded-[3rem] p-8 md:p-16 text-center space-y-8 md:space-y-10">
                    <h2 className="text-2xl md:text-3xl font-black tracking-tight">{ctaTitle}</h2>
                    <p className="text-xs md:text-sm text-gray-500 font-medium max-w-xl mx-auto leading-relaxed whitespace-pre-line">
                        {ctaContent}
                    </p>
                    <div className="flex flex-col sm:flex-row justify-center gap-4 sm:gap-6 pt-4">
                        <Link href={ctaPrimaryLink} className="text-xs font-black uppercase tracking-widest border-b-2 border-[#1A241A] pb-1 hover:text-[#8B7E66] hover:border-[#8B7E66] transition-colors">
                            {ctaPrimary}
                        </Link>
                        <Link href={ctaSecondaryLink} className="text-xs font-black uppercase tracking-widest border-b-2 border-[#1A241A] pb-1 hover:text-[#8B7E66] hover:border-[#8B7E66] transition-colors">
                            {ctaSecondary}
                        </Link>
                    </div>
                </div>
            </section>
        </div>
    );
}

import { prisma } from '@/lib/prisma';
import { notFound } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Calendar, Clock, ShoppingBag, Sparkles, TrendingDown, Truck, CheckCircle2, Zap } from 'lucide-react';
import AddToCartButton from '@/components/commerce/AddToCartButton';
import AddToBundleButton from '@/components/commerce/AddToBundleButton';

// Force dynamic
export const dynamic = 'force-dynamic';
export const revalidate = 0;

export default async function CampaignLandingPage({ params }: { params: { slug: string } }) {
    // 1. Fetch Campaign
    const campaign = await prisma.campaign.findFirst({
        where: {
            slug: params.slug,
            isActive: true
        },
        include: {
            bundles: {
                where: { isActive: true },
                include: {
                    items: {
                        include: { variant: { include: { product: true } } }
                    }
                }
            }
        }
    });

    if (!campaign) return notFound();

    // 2. Format Dates
    const startDate = new Date(campaign.startDate).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
    const endDate = new Date(campaign.endDate).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });

    return (
        <div className="bg-[#FDFBF7] min-h-screen text-[#2D3A2D]">
            {/* HERO SECTION */}
            <div className="relative h-[500px] flex items-center justify-center overflow-hidden bg-gradient-to-r from-[#8B0000] to-[#A52A2A] text-white">
                <div className="absolute inset-0 bg-black/30 z-10"></div>
                {/* Decorative Pattern */}
                <div className="absolute inset-0 opacity-20" style={{ backgroundImage: 'url("https://www.transparenttextures.com/patterns/diagmonds-light.png")' }}></div>

                <div className="relative z-20 text-center max-w-4xl px-6 space-y-6">
                    <span className="inline-block px-4 py-1.5 rounded-full bg-white/20 backdrop-blur-md border border-white/30 text-xs font-bold tracking-[0.2em] uppercase">
                        Campaign Resmi
                    </span>
                    <h1 className="text-5xl md:text-7xl font-black leading-tight drop-shadow-2xl">
                        {campaign.title}
                    </h1>
                    <p className="text-xl md:text-2xl text-white/90 font-medium max-w-2xl mx-auto leading-relaxed">
                        {campaign.description}
                    </p>
                    <div className="flex flex-col md:flex-row items-center justify-center gap-4 md:gap-8 pt-4">
                        <div className="flex items-center gap-2 text-sm font-bold bg-white/10 px-4 py-2 rounded-xl backdrop-blur-sm">
                            <Calendar className="w-5 h-5 text-yellow-400" />
                            <span>{startDate} - {endDate}</span>
                        </div>
                        <div className="flex items-center gap-2 text-sm font-black text-amber-300 animate-pulse">
                            <Zap className="w-5 h-5" />
                            <span>DOUBLE POINTS AKTIF ⚡</span>
                        </div>
                    </div>
                </div>
            </div>

            {/* BUNDLE LIST */}
            <div className="max-w-7xl mx-auto px-6 py-20 -mt-20 relative z-30">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {campaign.bundles.map(bundle => {
                        // Calculate total base price to show savings
                        const savings = Number(bundle.basePrice) - Number(bundle.price);

                        // Construct product object for AddToCartButton (using bundle ID logic)
                        // Note: AddToCartButton normally takes a Product/Variant. 
                        // We might need a specialized "AddToBundleCartButton" or adapt the existing one.
                        // For now, let's create a visual representation first.

                        return (
                            <div key={bundle.id} className="bg-white rounded-3xl p-8 shadow-xl border-2 border-transparent hover:border-[#BD302D]/20 transition-all hover:-translate-y-2 group">
                                <div className="flex justify-between items-start mb-6">
                                    <div className="bg-red-100 text-red-700 font-bold px-4 py-2 rounded-xl text-xs uppercase tracking-wider">
                                        Hemat Rp {savings.toLocaleString('id-ID')}
                                    </div>
                                    <div className="text-right">
                                        <div className="flex items-center justify-end gap-2 mb-1">
                                            <span className="text-[10px] font-black text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full border border-amber-100 flex items-center gap-1">
                                                <Sparkles className="w-3 h-3" />
                                                Dapatkan {Math.floor(Number(bundle.price) * 0.0002).toLocaleString()} Poin*
                                            </span>
                                        </div>
                                        <p className="text-gray-400 line-through text-xs font-medium">Rp {Number(bundle.basePrice).toLocaleString('id-ID')}</p>
                                        <div className="flex items-baseline justify-end gap-1">
                                            <span className="text-xs font-bold text-[#BD302D]">Rp</span>
