                    {featuredProducts.map((product) => (
                        <div key={product.id} className="group cursor-pointer">
                            <div className="aspect-[4/5] bg-gradient-to-br from-[#F9F7F2] to-[#E5E1D8] rounded-3xl mb-6 overflow-hidden relative shadow-sm group-hover:shadow-xl transition-all duration-500">
                                {product.image ? (
                                    <img src={product.image} alt={product.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                                ) : (
                                    <div className="absolute inset-0 flex items-center justify-center italic text-gray-300">[Foto: {product.name}]</div>
                                )}
                                <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>

                                {/* Promo / Flash Sale Badge */}
                                {getProductPrice(product).discount > 0 && (
                                    <PromoBadge type="FLASH_SALE" className="top-4 left-4" />
                                )}
                            </div>
                            <h3 className="text-sm md:text-xl font-black mb-2 tracking-tight line-clamp-1 group-hover:text-[#8B7E66] transition-colors">{product.name}</h3>
                            <p className="text-[10px] md:text-sm text-gray-500 font-medium mb-3 md:mb-4 line-clamp-2 leading-relaxed">{product.description}</p>
                            <div className="flex flex-col gap-3">
                                {getProductPrice(product).discount > 0 ? (
                                    <div>
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className="text-xs text-gray-400 line-through">
                                                Rp {product.price.toLocaleString('id-ID')}
                                            </span>
                                            <span className="px-1.5 py-0.5 bg-red-100 text-red-600 text-[10px] font-black rounded">
                                                -{getProductPrice(product).discount}%
                                            </span>
                                        </div>
                                        <span className="text-sm md:text-lg font-black text-amber-600">
                                            Rp {getProductPrice(product).final.toLocaleString('id-ID')}
                                        </span>
                                    </div>
                                ) : (
                                    <span className="text-sm md:text-lg font-black text-[#8B7E66]">
                                        Rp {product.price.toLocaleString('id-ID')}
                                    </span>
                                )}
                                {product.inStock ? (
                                    <div className="flex flex-col items-end gap-1">
                                        <span className="px-3 py-1 bg-emerald-50 text-emerald-700 text-[10px] md:text-xs font-bold rounded-full">
                                            Tersedia
                                        </span>
                                        {(product.totalStock || 0) > 0 && (product.totalStock || 0) < 15 && (
                                            <span className="text-[9px] md:text-[10px] font-black text-red-600 animate-pulse bg-red-50 px-2 py-0.5 rounded">
                                                Stok Terbatas! ({product.totalStock})
                                            </span>
                                        )}
                                    </div>
                                ) : (
                                    <span className="px-3 py-1 bg-slate-100 text-slate-500 text-[10px] md:text-xs font-bold rounded-full">
                                        Habis
                                    </span>
                                )}
                                <AddToCartButton
                                    product={product}
                                    label="Siapkan"
                                    className="px-4 py-2.5 text-[7px] md:text-[9px] w-full shadow-sm hover:shadow-md"
                                />
                            </div>
                        </div>
                    ))}
                    {featuredProducts.length === 0 && (
                        <div className="col-span-full py-20 text-center text-slate-400 italic">
                            Belum ada menu yang ditampilkan.
                        </div>
                    )}
                </div>
            </section>

            {/* Best Sellers Section */}
            <BestSellersSection products={bestSellers} activeFlashSale={activeFlashSale} />

            {/* Campaign Bundles Section */}
            <CampaignsSection campaigns={activeCampaigns} />

            {CheapestPlanComponent}

            {/* 4. Philosophy Section */}
            <section className="py-20 md:py-32 bg-gradient-to-br from-[#2D3A2D] via-[#1A241A] to-[#2D3A2D] text-[#FDFBF7] relative overflow-hidden">
                {/* Decorative elements */}
                <div className="absolute top-0 right-0 w-96 h-96 bg-[#8B7E66]/10 rounded-full blur-3xl"></div>
                <div className="absolute bottom-0 left-0 w-96 h-96 bg-amber-500/5 rounded-full blur-3xl"></div>

                <div className="max-w-7xl mx-auto px-6 grid grid-cols-1 md:grid-cols-2 gap-12 md:gap-24 items-center relative z-10">
                    <div className="aspect-square bg-white/5 rounded-[3rem] flex items-center justify-center italic text-white/20 overflow-hidden shadow-2xl group">
                        {config?.aboutImage ? <img src={config.aboutImage} alt="Philosophy" className="grayscale opacity-50 group-hover:opacity-70 w-full h-full object-cover transition-opacity duration-500" /> : "[Foto: Ibu dan Anak tertawa di dapur]"}
                    </div>
                    <div className="space-y-10">
                        <span className="inline-block text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66] bg-[#8B7E66]/10 px-4 py-2 rounded-full border border-[#8B7E66]/20">{philosophyTagline}</span>
                        <h2 className="text-4xl md:text-6xl font-black tracking-tight leading-[1.1] whitespace-pre-line">
                            {philosophyTitle}
                        </h2>
                        <div className="space-y-6 text-[#A0A8A0] text-base font-medium leading-relaxed whitespace-pre-line">
                            {philosophyContent}
                        </div>
                        <Link href={philosophyLinkUrl} className="group inline-flex items-center gap-2 border-b-2 border-white/10 hover:border-[#8B7E66] transition-all pb-1 text-xs font-black uppercase tracking-widest">
                            {philosophyLinkText}
                            <svg className="w-4 h-4 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                            </svg>
                        </Link>
                    </div>
                </div>
            </section>

            {/* 5. Platform Links Section */}
            <section className="py-24 border-y border-[#E5E1D8] bg-[#FDFBF7]/50">
                <div className="max-w-7xl mx-auto px-6">
                    <div className="max-w-4xl mx-auto text-center space-y-12">
                        <div className="space-y-4">
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66]">{platformTagline}</span>
                            <h2 className="text-3xl font-black tracking-tight">{platformTitle}</h2>
                            <p className="text-sm text-gray-500 font-medium">{platformSubtitle}</p>
                        </div>

                        <PlatformLinks links={platformLinks} />
                    </div>
                </div>
            </section >

            {/* 6. Final CTA */}
            <section className="py-24 md:py-40 text-center bg-gradient-to-b from-white to-[#FDFBF7] relative overflow-hidden">
                {/* Decorative background elements */}
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-[#8B7E66]/5 rounded-full blur-3xl"></div>

                <div className="max-w-3xl mx-auto px-6 space-y-12 relative z-10">
                    {ctaTagline && <span className="inline-block text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66] bg-[#8B7E66]/5 px-4 py-2 rounded-full">{ctaTagline}</span>}
                    <h2 className="text-4xl md:text-6xl font-black tracking-tight leading-tight">{ctaTitle}</h2>
                    <p className="text-base md:text-lg text-gray-600 font-medium whitespace-pre-line max-w-2xl mx-auto leading-relaxed">
                        {ctaSubtitle}
                    </p>
                    <div className="flex flex-col items-center gap-4 pt-4">
                        <a
                            href="#menu"
                            className="group inline-flex items-center gap-3 px-12 py-6 bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-600 hover:to-amber-700 text-white rounded-full text-sm font-black uppercase tracking-widest hover:scale-105 transition-all duration-300 shadow-2xl shadow-amber-900/20 hover:shadow-amber-900/30 relative overflow-hidden"
                        >
                            <span className="relative z-10">{ctaButton}</span>
                            <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
                        </a>
                        <a
                            href={`https://wa.me/${whatsapp}?text=${encodeURIComponent("Halo, saya butuh bantuan order.")}`}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-stone-400 text-xs font-bold hover:text-amber-600 transition-colors flex items-center gap-1"
                        >
                            Butuh Bantuan ? Chat WhatsApp
                        </a>
                    </div>
                </div>
            </section>
        </div>
    );
}

import Link from 'next/link';
import AddToCartButton from '@/components/commerce/AddToCartButton';
import PlatformLinks from '@/components/commerce/PlatformLinks';
import ProductRecommendations from '@/components/commerce/ProductRecommendations';
import { prisma } from '@/lib/prisma';
import { getRecommendedProducts, incrementProductView } from '@/lib/actions/rasa-ibu/public-products';

// Force dynamic rendering
export const dynamic = 'force-dynamic';
export const revalidate = 0;

export default async function RasaIbuProductDetailPage({ params }: { params: Promise<{ slug: string }> }) {
    const { slug } = await params;

    // Fetch Brand Config
    const brand = await prisma.brand.findUnique({
        where: { slug: 'rasa-ibu' },
        select: { paymentSettings: true }
    });

    // Fetch Product from Database
    const product = await prisma.frozenProduct.findFirst({
        where: {
            slug: slug,
            category: { brand: { slug: 'rasa-ibu' } }
        },
        include: {
            variants: true
        }
    });

    const settings = brand?.paymentSettings as any;
    const whatsapp = settings?.whatsappCrm || '628123456789';

    if (!product) {
        return (
            <div className="py-40 text-center space-y-8">
                <h1 className="text-3xl font-black">Menu Tidak Ditemukan</h1>
                <Link href="/rasa-ibu/products" className="text-sm font-black uppercase text-[#8B7E66] border-b-2 border-[#8B7E66]">Kembali ke Menu</Link>
            </div>
        );
    }

    // Determine derived values
    const primaryVariant = product.variants[0];
    const price = Number(primaryVariant?.price || 0);
    const weight = Number(primaryVariant?.weight || 0);
    const inStock = product.variants.some(v => v.stockOnHand > 0);

    // Parse nutrition if JSON
    let nutritionConfig = {
        calories: '-',
        protein: '-',
        fat: '-',
        carbs: '-'
    };

    if (product.nutrition) {
        const n = product.nutrition as any;
        nutritionConfig = {
            calories: n.calories ? `${n.calories} kcal` : '-',
            protein: n.protein ? `${n.protein}g` : '-',
            fat: n.fat ? `${n.fat}g` : '-',
            carbs: n.carbs ? `${n.carbs}g` : '-'
        };
    }

    const waMessage = `Halo Rasa Ibu, saya ingin pesan ${product.name}. Apakah produknya ready stok?`;
    const waLink = `https://wa.me/${whatsapp}?text=${encodeURIComponent(waMessage)}`;

    // Fetch recommended products (similar products from same category)
    const recommendedProducts = await getRecommendedProducts(product.id, 4);

    // Increment view count (fire and forget)
    incrementProductView(product.id).catch(() => {
        // Silently fail if view tracking fails
    });


    return (
        <div className="py-24 max-w-7xl mx-auto px-6">
            <Link href="/rasa-ibu/products" className="inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-[#8B7E66] transition-colors mb-12">
                ← Kembali ke Semua Menu
            </Link>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-24">
                {/* Left: Image */}
                <div className="aspect-[4/5] bg-[#F9F7F2] rounded-[3rem] overflow-hidden flex items-center justify-center italic text-gray-300">
                    {product.image ? (
                        <img
                            src={product.image}
                            alt={product.name}
                            className="w-full h-full object-cover"
                        />
                    ) : (
                        <span>[Foto Detail: {product.name}]</span>
                    )}
                </div>

                {/* Right: Content */}
                <div className="space-y-12">
                    <div className="space-y-4">
                        <h1 className="text-5xl font-black tracking-tight text-[#1A241A]">{product.name}</h1>
                        <div className="flex items-center gap-6">
                            <span className="text-2xl font-black text-[#8B7E66]">Rp {price.toLocaleString('id-ID')}</span>
                            <span className="h-4 w-px bg-gray-200"></span>
                            <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">
                                {weight > 0 ? `${weight}g` : 'Per Porsi'}
                            </span>
                        </div>
                    </div>

                    <p className="text-lg text-[#4A5D4A] leading-relaxed font-medium">
                        {product.description || 'Hidangan istimewa dari dapur Rasa Ibu, dibuat dengan bahan pilihan terbaik.'}
                    </p>

                    {/* Action */}
                    <div className="flex gap-4">
                        <AddToCartButton
                            product={{
                                id: product.id,
                                name: product.name,
                                price: price,
                                image: product.image || undefined,
                                variantId: primaryVariant?.id,
                                variantName: primaryVariant?.name || 'Porsi Keluarga'
                            }}
                            className="flex-1 bg-[#2D3A2D] text-[#FDFBF7] py-4 rounded-xl font-black uppercase tracking-widest hover:scale-[1.02] transition-transform"
                            label={inStock ? 'Siapkan Untuk Keluarga' : 'Habis Terjual'}
                        />
                        <Link
                            href={waLink}
                            target="_blank"
                            className="px-6 py-4 border border-[#E5E1D8] rounded-xl text-[#2D3A2D] hover:bg-[#F9F7F2] transition-colors"
                        >
                            <svg viewBox="0 0 24 24" className="w-6 h-6 fill-current"><path d="M12.031 6.172c-3.181 0-5.767 2.586-5.768 5.766-.001 1.298.38 2.27 1.019 3.287l-.711 2.598 2.664-.698c.969.585 1.809.891 2.796.891 3.182 0 5.768-2.587 5.768-5.766.001-3.187-2.575-5.77-5.768-5.778zm-1.785 2.158c.119-.265.234-.271.341-.271.096 0 .19 0 .285.006.113.007.262.038.397.33.143.309.489 1.155.53 1.239.041.084.07.181.011.3s-.089.26-.172.356c-.095.107-.2.18-.328.326-.067.078-.142.164-.06.31.082.148.363.593.778.963.535.477.986.626 1.125.685.14.058.22.046.302-.047.083-.093.357-.417.452-.56.096-.143.191-.119.321-.071.131.048.833.393.976.465.143.072.238.107.274.167.036.06.036.345-.131.81-.167.464-.976.845-1.345.881-.357.042-.714.053-2.03-.464-1.637-.643-2.673-2.316-2.756-2.429-.084-.113-1.042-1.387-1.042-2.643 0-1.316.685-1.965.929-2.228.16-.173.35-.22.56-.22zm6.658 3.596c0 2.69-2.19 4.88-4.88 4.88a4.86 4.86 0 0 1-2.436-.65l-2.872.753.766-2.798a4.85 4.85 0 0 1-.77-2.185c0-2.693 2.19-4.882 4.882-4.882 2.69 0 4.88 2.19 4.88 4.882z" /></svg>
                        </Link>
                    </div>

                    <div className="grid grid-cols-2 gap-8 py-8 border-y border-[#F9F7F2]">
                        <div className="space-y-4">
                            <span className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Komposisi (Ingredients)</span>
                            <p className="text-sm text-gray-600 leading-relaxed font-medium">
                                {product.ingredients || 'Informasi bahan belum tersedia.'}
                            </p>
                        </div>
                        <div className="space-y-4">
                            <span className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Nilai Gizi (Per Sajian)</span>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <span className="text-[9px] font-bold text-gray-400">Kalori</span>
                                    <p className="font-black text-[#1A241A]">{nutritionConfig.calories}</p>
                                </div>
                                <div className="space-y-1">
                                    <span className="text-[9px] font-bold text-gray-400">Protein</span>
                                    <p className="font-black text-[#1A241A]">{nutritionConfig.protein}</p>
                                </div>
                                <div className="space-y-1">
                                    <span className="text-[9px] font-bold text-gray-400">Lemak</span>
                                    <p className="font-black text-[#1A241A]">{nutritionConfig.fat}</p>
                                </div>
                                <div className="space-y-1">
                                    <span className="text-[9px] font-bold text-gray-400">Karbo</span>
                                    <p className="font-black text-[#1A241A]">{nutritionConfig.carbs}</p>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="space-y-4">
                        <span className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Saran Penyajian</span>
                        <p className="text-sm text-gray-600 leading-relaxed italic border-l-2 border-[#8B7E66] pl-4">
                            "{product.storageType === 'FROZEN' ? 'Lakukan Thawing (pencairan) di chiller semalaman sebelum dimasak. ' : ''}
                            Panaskan sesuai selera keluarga Bunda."
                        </p>
                    </div>
                </div>
            </div>

            {/* Product Recommendations */}
            <ProductRecommendations products={recommendedProducts} />

            {/* Platform Links */}
            <div className="mt-24 pt-24 border-t border-[#F9F7F2]">
                <PlatformLinks links={settings?.links} />
            </div>
        </div>
    );
}

import React from 'react';
import Link from 'next/link';
import AddToCartButton from '@/components/commerce/AddToCartButton';

import { prisma } from '@/lib/prisma';

// Force dynamic rendering
export const dynamic = 'force-dynamic';
export const revalidate = 0;

export default async function RasaIbuProductListPage() {
    // Fetch Brand RASA IBU
    const brand = await prisma.brand.findUnique({
        where: { slug: 'rasa-ibu' }
    });

    if (!brand) return <div className="py-24 text-center">Brand not found</div>;

    // Fetch real products - ONLY from PUBLIC categories
    const products = await prisma.frozenProduct.findMany({
        where: {
            // Filter products that belong to a Public Category (Menu)
            // and ensure that category is Active
            category: {
                brandId: brand.id,
                isActive: true
            }
        },
        include: {
            category: true,
            variants: true
        },
        orderBy: { name: 'asc' }
    });

    // Map to simple structure for UI
    const mappedProducts = products.map(p => {
        const firstVariant = p.variants[0];
        const totalStock = p.variants.reduce((sum, v) => sum + v.stockOnHand, 0);
        return {
            id: p.id,
            slug: p.slug,
            name: p.name,
            category: p.category?.name || 'Menu',
            price: Number(firstVariant?.price || 0),
            shortDesc: p.description || '',
            inStock: totalStock > 0,
            image: p.image || undefined,
            variantId: firstVariant?.id,
            variantName: firstVariant?.name || 'Porsi Keluarga'
        };
    });

    const settings = brand?.paymentSettings as any;
    const whatsapp = settings?.whatsappCrm || '628123456789';

    return (
        <div className="py-24 max-w-7xl mx-auto px-6">
            {/* Header */}
            <div className="max-w-2xl space-y-6 mb-24">
                <span className="inline-block text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66] bg-[#8B7E66]/5 px-4 py-2 rounded-full">Menu Dapur Kami</span>
                <h1 className="text-5xl md:text-6xl font-black tracking-tight text-[#1A241A] leading-tight">Hidangan Rumah <br /> Untuk Meja Makan Anda.</h1>
                <p className="text-base font-medium text-gray-600 leading-relaxed">
                    Setiap menu dibuat dalam porsi keluarga (2-3 orang). Tanpa pengawet, hanya menggunakan bumbu alami.
                </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-y-24 gap-x-8">
                {mappedProducts.map((product) => (
                    <div key={product.id} className="group space-y-6">
                        <Link
                            href={`/rasa-ibu/products/${product.slug}`}
                            className="block"
                        >
                            <div className="relative aspect-[4/5] bg-gradient-to-br from-[#F9F7F2] to-[#E5E1D8] rounded-[2.5rem] overflow-hidden transition-all duration-500 group-hover:scale-[1.02] shadow-sm group-hover:shadow-xl">
                                {product.image ? (
                                    <img
                                        src={product.image}
                                        alt={product.name}
                                        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700"
                                    />
                                ) : (
                                    <div className="absolute inset-0 flex items-center justify-center italic text-gray-300 font-medium">
                                        [Foto: {product.name}]
                                    </div>
                                )}

                                {/* Overlay gradient on hover */}
                                <div className="absolute inset-0 bg-gradient-to-t from-black/30 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>

                                {!product.inStock && (
                                    <div className="absolute top-6 right-6 px-4 py-2.5 bg-white/95 backdrop-blur-md rounded-full text-[10px] font-black uppercase tracking-widest text-gray-400 shadow-lg">
                                        Habis Terjual
                                    </div>
                                )}

                                <div className="absolute bottom-6 left-6 px-4 py-2.5 bg-white/95 backdrop-blur-md rounded-full text-[9px] font-black uppercase tracking-widest text-[#8B7E66] shadow-lg border border-white/50">
                                    {product.category}
                                </div>
                            </div>

                            <div className="space-y-3 px-2">
                                <div className="flex justify-between items-start gap-4">
                                    <h2 className="text-xl font-black text-[#1A241A] tracking-tight group-hover:text-[#8B7E66] transition-colors leading-tight">{product.name}</h2>
                                    <span className="text-lg font-black text-[#8B7E66] shrink-0">Rp {product.price.toLocaleString('id-ID')}</span>
                                </div>
                                <p className="text-sm text-gray-600 font-medium leading-relaxed line-clamp-2">
                                    {product.shortDesc}
                                </p>
                            </div>
                        </Link>

                        <div className="px-2">
                            <AddToCartButton
                                product={product}
                                className="w-full bg-gradient-to-r from-[#2D3A2D] to-[#1A241A] hover:from-[#3d4d3d] hover:to-[#2D3A2D] text-[#FDFBF7] shadow-md hover:shadow-lg transition-all"
                                label={product.inStock ? 'Siapkan Untuk Keluarga' : 'Dapur Sedang Masak'}
                            />
                        </div>
                    </div>
                ))}
            </div>

            {/* Manual Assistance Footer */}
            <div className="mt-40 p-12 md:p-16 bg-gradient-to-br from-[#F9F7F2] to-[#E5E1D8] rounded-[3rem] text-center space-y-8 shadow-lg relative overflow-hidden">
                {/* Decorative element */}
                <div className="absolute top-0 right-0 w-64 h-64 bg-[#8B7E66]/5 rounded-full blur-3xl"></div>

                <div className="relative z-10 space-y-8">
                    <h3 className="text-3xl md:text-4xl font-black tracking-tight">Butuh Rekomendasi Menu?</h3>
                    <p className="text-base text-gray-600 font-medium max-w-xl mx-auto leading-relaxed">
                        Tanya kami menu apa yang cocok untuk acara spesial atau stok mingguan Anda. Kami siap membantu via WhatsApp.
                    </p>
                    <div className="flex justify-center pt-4">
                        <a
                            href={`https://wa.me/${whatsapp}?text=${encodeURIComponent("Halo Rasa Ibu, bisa bantu rekomendasi menu untuk anak kos?")}`}
                            className="group inline-flex items-center gap-3 border-2 border-[#1A241A] text-[#1A241A] px-10 py-5 rounded-full text-xs font-black uppercase tracking-widest hover:bg-[#1A241A] hover:text-white transition-all duration-300 shadow-md hover:shadow-xl"
                        >
                            Hubungi Assistant
                            <svg className="w-4 h-4 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                            </svg>
                        </a>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useSession } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import { Camera, Loader2, Mail, Phone, MapPin, Lock, ShieldCheck, ArrowLeft, Check } from 'lucide-react';
import Link from 'next/link';

export default function ProfileEditPage() {
    const { data: session, status } = useSession();
    const router = useRouter();

    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    // Profile data
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [phone, setPhone] = useState('');
    const [address, setAddress] = useState('');
    const [profileImage, setProfileImage] = useState('');

    // Password change
    const [showPasswordSection, setShowPasswordSection] = useState(false);
    const [currentPassword, setCurrentPassword] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');

    // OTP for critical changes
    const [showOtpModal, setShowOtpModal] = useState(false);
    const [otpCode, setOtpCode] = useState('');
    const [otpSent, setOtpSent] = useState(false);
    const [otpLoading, setOtpLoading] = useState(false);
    const [otpToken, setOtpToken] = useState('');
    const [pendingChanges, setPendingChanges] = useState<any>(null);

    // Photo upload
    const [uploadingPhoto, setUploadingPhoto] = useState(false);

    useEffect(() => {
        if (status === 'unauthenticated') {
            router.push('/auth/signin?callbackUrl=/rasa-ibu/profile/edit');
        } else if (status === 'authenticated') {
            fetchProfile();
        }
    }, [status]);

    const fetchProfile = async () => {
        try {
            const res = await fetch('/api/user/profile');
            const data = await res.json();
            if (data.success) {
                setName(data.data.name || '');
                setEmail(data.data.email || '');
                setPhone(data.data.phone || '');
                setAddress(data.data.address || '');
                setProfileImage(data.data.profileImage || '');
            }
        } catch (err) {
            setError('Gagal memuat profil');
        } finally {
            setLoading(false);
        }
    };

    const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        if (file.size > 2 * 1024 * 1024) {
            setError('Ukuran foto maksimal 2MB');
            return;
        }

        setUploadingPhoto(true);
        const reader = new FileReader();
        reader.onloadend = async () => {
            const base64 = reader.result as string;
            setProfileImage(base64);

            // Auto-save profile image
            try {
                const res = await fetch('/api/user/profile', {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ profileImage: base64 })
                });
                const data = await res.json();
                if (data.success) {
                    setSuccess('Foto profil berhasil diperbarui!');
                    setTimeout(() => setSuccess(''), 3000);
                }
            } catch (err) {
                setError('Gagal menyimpan foto');
            } finally {
                setUploadingPhoto(false);
            }
        };
        reader.readAsDataURL(file);
    };

    const handleSendOTP = async () => {
        setOtpLoading(true);
        setError('');
        try {
            const res = await fetch('/api/auth/otp/send', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email: session?.user?.email, type: 'OTP_PROFILE_UPDATE' })
            });
            const data = await res.json();
            if (data.success) {
                setOtpSent(true);
            } else {
                setError(data.message || 'Gagal mengirim OTP');
            }
        } catch (err) {
            setError('Terjadi kesalahan saat mengirim OTP');
        } finally {
            setOtpLoading(false);
        }
    };

    const handleVerifyOTP = async () => {
        if (otpCode.length !== 6) return;
        setOtpLoading(true);
        try {
            const res = await fetch('/api/auth/otp/verify', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    email: session?.user?.email,
                    code: otpCode,
                    type: 'OTP_PROFILE_UPDATE'
                })
            });
            const data = await res.json();
            if (data.success) {
                setOtpToken(data.token);
                setShowOtpModal(false);
                // Now save with OTP token
                await saveProfileWithOTP(data.token);
            } else {
                setError(data.message || 'Kode OTP salah');
            }
        } catch (err) {
            setError('Terjadi kesalahan verifikasi');
        } finally {
            setOtpLoading(false);
        }
    };

    const saveProfileWithOTP = async (token: string) => {
        setSaving(true);
        try {
            const res = await fetch('/api/user/profile', {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    ...pendingChanges,
                    otpToken: token
                })
            });
            const data = await res.json();
            if (data.success) {
                setSuccess('Profil berhasil diperbarui!');
                setShowPasswordSection(false);
                setCurrentPassword('');
                setNewPassword('');
                setConfirmPassword('');
                setPendingChanges(null);
                setTimeout(() => {
                    setSuccess('');
                    router.refresh();
                }, 2000);
            } else {
                setError(data.error || 'Gagal memperbarui profil');
            }
        } catch (err) {
            setError('Terjadi kesalahan');
        } finally {
            setSaving(false);
        }
    };

    const handleSaveProfile = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setSuccess('');

        // Validate password if changing
        if (showPasswordSection) {
            if (!currentPassword || !newPassword || !confirmPassword) {
                setError('Semua field password harus diisi');
                return;
            }
            if (newPassword !== confirmPassword) {
                setError('Password baru tidak cocok');
                return;
            }
            if (newPassword.length < 6) {
                setError('Password minimal 6 karakter');
                return;
            }
        }

        const changes: any = {
            name,
            phone,
            address
        };

        if (showPasswordSection) {
            changes.currentPassword = currentPassword;
            changes.newPassword = newPassword;
        }

        // Check if critical changes require OTP
        const needsOTP = showPasswordSection;

        if (needsOTP) {
            setPendingChanges(changes);
            setShowOtpModal(true);
            handleSendOTP();
        } else {
            // Save directly
            setSaving(true);
            try {
                const res = await fetch('/api/user/profile', {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(changes)
                });
                const data = await res.json();
                if (data.success) {
                    setSuccess('Profil berhasil diperbarui!');
                    setTimeout(() => setSuccess(''), 3000);
                } else {
                    setError(data.error || 'Gagal memperbarui profil');
                }
            } catch (err) {
                setError('Terjadi kesalahan');
            } finally {
                setSaving(false);
            }
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-[#FDFBF7] flex items-center justify-center">
                <Loader2 className="w-8 h-8 animate-spin text-[#8B7E66]" />
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#FDFBF7] py-12 px-4">
            <div className="max-w-2xl mx-auto">
                <Link href="/rasa-ibu/profile" className="inline-flex items-center text-xs text-gray-500 hover:text-[#2D3A2D] mb-6 gap-1 group">
                    <ArrowLeft className="w-3 h-3 transition-transform group-hover:-translate-x-1" />
                    Kembali ke Profil
                </Link>

                <div className="bg-white rounded-3xl shadow-xl border border-[#E5E1D8] p-8">
                    <h1 className="text-3xl font-black text-[#2D3A2D] mb-2 font-serif">Edit Profil</h1>
                    <p className="text-sm text-[#8B7E66] mb-8">Perbarui informasi akun Anda</p>

                    {error && (
                        <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-4 font-bold">
                            {error}
                        </div>
                    )}

                    {success && (
                        <div className="bg-green-50 text-green-600 p-3 rounded-lg text-sm mb-4 font-bold flex items-center gap-2">
                            <Check className="w-4 h-4" />
                            {success}
                        </div>
                    )}

                    {/* Profile Photo */}
                    <div className="flex flex-col items-center mb-8">
                        <div className="relative">
                            <div className="w-32 h-32 rounded-full bg-[#E5E1D8] flex items-center justify-center overflow-hidden">
                                {profileImage ? (
                                    <img src={profileImage} alt="Profile" className="w-full h-full object-cover" />
                                ) : (
                                    <span className="text-5xl font-black text-[#8B7E66]">
                                        {name.charAt(0).toUpperCase()}
                                    </span>
                                )}
                            </div>
                            <label className="absolute bottom-0 right-0 w-10 h-10 bg-[#2D3A2D] rounded-full flex items-center justify-center cursor-pointer hover:bg-[#3d4d3d] transition-colors">
                                {uploadingPhoto ? (
                                    <Loader2 className="w-5 h-5 text-white animate-spin" />
                                ) : (
                                    <Camera className="w-5 h-5 text-white" />
                                )}
                                <input
                                    type="file"
                                    accept="image/*"
                                    onChange={handlePhotoUpload}
                                    className="hidden"
                                    disabled={uploadingPhoto}
                                />
                            </label>
                        </div>
                        <p className="text-xs text-gray-400 mt-2">Klik ikon kamera untuk upload foto (Max 2MB)</p>
                    </div>

                    <form onSubmit={handleSaveProfile} className="space-y-6">
                        {/* Name */}
                        <div>
                            <label className="block text-sm font-bold text-[#2D3A2D] mb-1">Nama Lengkap</label>
                            <input
                                type="text"
                                value={name}
                                onChange={(e) => setName(e.target.value)}
                                required
                                className="w-full px-4 py-3 rounded-xl bg-[#F9F7F2] border border-[#E5E1D8] focus:ring-2 focus:ring-[#B2BCA2]"
                            />
                        </div>

                        {/* Email (Read-only) */}
                        <div>
                            <label className="block text-sm font-bold text-[#2D3A2D] mb-1">Email</label>
                            <div className="relative">
                                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                <input
                                    type="email"
                                    value={email}
                                    disabled
                                    className="w-full pl-12 pr-4 py-3 rounded-xl bg-gray-100 border border-[#E5E1D8] text-gray-500 cursor-not-allowed"
                                />
                            </div>
                            <p className="text-xs text-gray-400 mt-1">Email tidak dapat diubah</p>
                        </div>

                        {/* Phone */}
                        <div>
                            <label className="block text-sm font-bold text-[#2D3A2D] mb-1">No. WhatsApp</label>
                            <div className="relative">
                                <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                <input
                                    type="tel"
                                    value={phone}
                                    onChange={(e) => setPhone(e.target.value)}
                                    className="w-full pl-12 pr-4 py-3 rounded-xl bg-[#F9F7F2] border border-[#E5E1D8] focus:ring-2 focus:ring-[#B2BCA2]"
                                    placeholder="0812XXXXXXXX"
                                />
                            </div>
                        </div>

                        {/* Address */}
                        <div>
                            <label className="block text-sm font-bold text-[#2D3A2D] mb-1">Alamat Lengkap</label>
                            <div className="relative">
                                <MapPin className="absolute left-4 top-4 w-4 h-4 text-gray-400" />
                                <textarea
                                    value={address}
                                    onChange={(e) => setAddress(e.target.value)}
                                    rows={3}
                                    className="w-full pl-12 pr-4 py-3 rounded-xl bg-[#F9F7F2] border border-[#E5E1D8] focus:ring-2 focus:ring-[#B2BCA2]"
                                    placeholder="Jalan, Nomor Rumah, RT/RW, Kelurahan..."
                                />
                            </div>
                        </div>

                        {/* Password Change Section */}
                        <div className="pt-6 border-t border-[#E5E1D8]">
                            <button
                                type="button"
                                onClick={() => setShowPasswordSection(!showPasswordSection)}
                                className="flex items-center gap-2 text-sm font-bold text-[#2D3A2D] hover:text-[#BD302D] transition-colors"
                            >
                                <Lock className="w-4 h-4" />
                                {showPasswordSection ? 'Batal Ubah Password' : 'Ubah Password'}
                            </button>

                            {showPasswordSection && (
                                <div className="mt-4 space-y-4 p-4 bg-[#F9F7F2] rounded-xl animate-in slide-in-from-top-2">
                                    <div>
                                        <label className="block text-sm font-bold text-[#2D3A2D] mb-1">Password Saat Ini</label>
                                        <input
                                            type="password"
                                            value={currentPassword}
                                            onChange={(e) => setCurrentPassword(e.target.value)}
                                            className="w-full px-4 py-3 rounded-xl bg-white border border-[#E5E1D8] focus:ring-2 focus:ring-[#B2BCA2]"
                                            placeholder="********"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-[#2D3A2D] mb-1">Password Baru</label>
                                        <input
                                            type="password"
                                            value={newPassword}
                                            onChange={(e) => setNewPassword(e.target.value)}
                                            className="w-full px-4 py-3 rounded-xl bg-white border border-[#E5E1D8] focus:ring-2 focus:ring-[#B2BCA2]"
                                            placeholder="********"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-[#2D3A2D] mb-1">Konfirmasi Password Baru</label>
                                        <input
                                            type="password"
                                            value={confirmPassword}
                                            onChange={(e) => setConfirmPassword(e.target.value)}
                                            className="w-full px-4 py-3 rounded-xl bg-white border border-[#E5E1D8] focus:ring-2 focus:ring-[#B2BCA2]"
                                            placeholder="********"
                                        />
                                    </div>
                                    <p className="text-xs text-amber-600 flex items-center gap-1">
                                        <ShieldCheck className="w-3 h-3" />
                                        Perubahan password memerlukan verifikasi OTP
                                    </p>
                                </div>
                            )}
                        </div>

                        {/* Submit Button */}
                        <button
                            type="submit"
                            disabled={saving}
                            className="w-full py-4 bg-[#BD302D] hover:bg-[#a32826] text-white rounded-xl font-bold transition-all shadow-lg hover:shadow-xl disabled:opacity-50 flex items-center justify-center gap-2"
                        >
                            {saving && <Loader2 className="w-4 h-4 animate-spin" />}
                            Simpan Perubahan
                        </button>
                    </form>
                </div>
            </div>

            {/* OTP Modal */}
            {showOtpModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl p-8 max-w-md w-full animate-in zoom-in duration-200">
                        <h3 className="text-xl font-black text-[#2D3A2D] mb-2">Verifikasi OTP</h3>
                        <p className="text-sm text-gray-600 mb-6">
                            Kode verifikasi telah dikirim ke email Anda
                        </p>

                        <input
                            type="text"
                            maxLength={6}
                            value={otpCode}
                            onChange={(e) => setOtpCode(e.target.value.trim().replace(/\D/g, '').slice(0, 6))}
                            className="w-full text-center text-2xl font-black py-4 rounded-xl bg-[#F9F7F2] border border-[#E5E1D8] focus:ring-2 focus:ring-[#B2BCA2] tracking-[0.5em] mb-4"
                            placeholder="000000"
                        />

                        <div className="flex gap-3">
                            <button
                                onClick={() => {
                                    setShowOtpModal(false);
                                    setOtpCode('');
                                    setOtpSent(false);
                                }}
                                className="flex-1 py-3 border border-gray-300 rounded-xl font-bold text-gray-700 hover:bg-gray-50"
                            >
                                Batal
                            </button>
                            <button
                                onClick={handleVerifyOTP}
                                disabled={otpCode.length !== 6 || otpLoading}
                                className="flex-1 py-3 bg-[#2D3A2D] text-white rounded-xl font-bold hover:bg-[#3d4d3d] disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                {otpLoading && <Loader2 className="w-4 h-4 animate-spin" />}
                                Verifikasi
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import React from 'react';
import Link from 'next/link';
import { useSession } from 'next-auth/react';
import SubscribePageContent from './SubscribeContent';
import { Lock } from 'lucide-react';

interface SubscribeAuthWrapperProps {
    plans: any[];
    existingData?: any;
}

export default function SubscribeAuthWrapper({ plans, existingData }: SubscribeAuthWrapperProps) {
    const { data: session, status } = useSession();

    if (status === 'loading') {
        return <div className="min-h-screen flex items-center justify-center bg-[#FDFBF7]">Loading...</div>;
    }

    // Simplified: Authentication will be handled via OTP inside the content if not logged in
    return <SubscribePageContent user={session?.user} plans={plans} initialData={existingData} isAuthenticated={!!session} />;
}

'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { signIn } from 'next-auth/react';
import { createSubscriptionAction } from '@/lib/actions/commerce/subscriptions';
import { CheckCircle, ShieldCheck, CreditCard, Loader2, ArrowRight, ArrowLeft, User, MapPin, Lock, Utensils, Package, Clock, Star, Heart } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export default function SubscribePageContent({ user, plans, initialData, isAuthenticated }: { user: any, plans: any[], initialData?: any, isAuthenticated: boolean }) {
    const router = useRouter();

    // Form Data State
    const [formData, setFormData] = useState({
        name: initialData?.name || user?.name || '',
        email: initialData?.email || user?.email || '',
        phone: initialData?.phone || user?.phone || '',
        address: initialData?.address || user?.address || '',
        customerNote: ''
    });

    const [paymentMethod, setPaymentMethod] = useState<'QRIS' | 'BANK_TRANSFER'>('BANK_TRANSFER');

    // OTP State
    const [otpCode, setOtpCode] = useState('');
    const [isOtpVerified, setIsOtpVerified] = useState(false);
    const [otpLoading, setOtpLoading] = useState(false);
    const [otpSent, setOtpSent] = useState(false);
    const [showOtpModal, setShowOtpModal] = useState(false);
    const [otpType, setOtpType] = useState<'OTP_REGISTER' | 'OTP_LOGIN'>('OTP_REGISTER');

    // Check if customer data is complete
    const isCustomerDataComplete = formData.name && formData.phone && formData.address && formData.email;

    // Start with DATA step if customer data is incomplete, otherwise PLAN
    const [step, setStep] = useState<'DATA' | 'PLAN' | 'PRODUCTS' | 'DAYS'>(
        isCustomerDataComplete ? 'PLAN' : 'DATA'
    );

    const [selectedPlan, setSelectedPlan] = useState<any>(null);
    const [selectedProducts, setSelectedProducts] = useState<{ variantId: string, quantity: number, note?: string }[]>([]);
    const [loading, setLoading] = useState(false);

    const [selectedDays, setSelectedDays] = useState<{ day: string, timeSlot: string }[]>([]);
    const daysOfWeek = [
        { id: 'SUNDAY', label: 'Minggu' },
        { id: 'MONDAY', label: 'Senin' },
        { id: 'TUESDAY', label: 'Selasa' },
        { id: 'WEDNESDAY', label: 'Rabu' },
        { id: 'THURSDAY', label: 'Kamis' },
        { id: 'FRIDAY', label: 'Jumat' },
        { id: 'SATURDAY', label: 'Sabtu' },
    ];

    const timeSlots = [
        "06:00 - 08:00",
        "10:00 - 12:00",
        "13:00 - 15:00",
        "19:00 - 21:00"
    ];

    const toggleDay = (dayId: string) => {
        setSelectedDays(prev => {
            const exists = prev.find(d => d.day === dayId);
            if (exists) {
                return prev.filter(d => d.day !== dayId);
            } else {
                return [...prev, { day: dayId, timeSlot: timeSlots[0] }];
            }
        });
    };

    const updateTimeSlot = (dayId: string, timeSlot: string) => {
        setSelectedDays(prev => prev.map(d => d.day === dayId ? { ...d, timeSlot } : d));
    };

    // Handle authentication redirect manually if needed
    const handleAuthRedirect = (type: 'signin' | 'register') => {
        router.push(`/auth/${type}?callbackUrl=/rasa-ibu/subscribe`);
    };

    const handleSendOTP = async () => {
        if (!formData.email) {
            alert("Mohon masukkan email untuk verifikasi.");
            return;
        }
        setOtpLoading(true);
        try {
            const sendType = 'OTP_REGISTER';
            let res = await fetch('/api/auth/otp/send', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email: formData.email, type: sendType })
            });
            let result = await res.json();

            // If already registered, try OTP_LOGIN
            if (!result.success && res.status === 409) {
                setOtpType('OTP_LOGIN');
                res = await fetch('/api/auth/otp/send', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ email: formData.email, type: 'OTP_LOGIN' })
                });
                result = await res.json();
            } else {
                setOtpType('OTP_REGISTER');
            }

            if (result.success) {
                setOtpSent(true);
                setShowOtpModal(true);
            } else {
                alert(result.message || "Gagal mengirim OTP.");
            }
        } catch (error) {
            alert("Terjadi kesalahan saat mengirim OTP.");
        } finally {
            setOtpLoading(false);
        }
    };

    const handleVerifyOTP = async () => {
        if (!otpCode || otpCode.length !== 6) return;
        setOtpLoading(true);
        try {
            const res = await fetch('/api/auth/otp/verify', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    email: formData.email,
                    code: otpCode,
                    type: otpType,
                    name: formData.name
                })
            });
            const result = await res.json();
            if (result.success) {
                // Auto login after verification
                await signIn('credentials', {
                    redirect: false,
                    email: formData.email,
                    otpToken: result.token
                });

                setIsOtpVerified(true);
                setShowOtpModal(false);
                setStep('PLAN');
                router.refresh();
            } else {
                alert(result.message || result.error || "Kode OTP salah.");
            }
        } catch (error) {
            alert("Terjadi kesalahan saat verifikasi OTP.");
        } finally {
            setOtpLoading(false);
        }
    };

    const handleNext = (e: React.FormEvent) => {
        e.preventDefault();
        // Simple Validation
        if (!formData.name || !formData.phone || !formData.address || !formData.email) {
            alert("Mohon lengkapi semua data pengiriman.");
            return;
        }

        if (!isAuthenticated && !isOtpVerified) {
            handleSendOTP();
            return;
        }

        setStep('PLAN');
    };

    const handleCheckout = async () => {
        if (!isAuthenticated) return;
        if (!selectedPlan) return;

        setLoading(true);

        const data = {
            userId: user?.id || user?.uid,
            name: formData.name,
            email: formData.email,
            phone: formData.phone,
            address: formData.address,
            customerNote: formData.customerNote || undefined,
            interval: selectedPlan.interval,
            deliveryDays: (selectedPlan.interval === 'WEEKLY' || selectedPlan.isScheduleFlexible) ? selectedDays : undefined,
            planId: selectedPlan.id,
            selectedProducts: selectedProducts.length > 0 ? selectedProducts : undefined,
            paymentMethod: paymentMethod
        };

        const res = await createSubscriptionAction(data as any);

        if (res.success) {
            alert(`Berhasil! Langganan ${selectedPlan.name} Anda kini aktif.`);
            router.push('/rasa-ibu/profile?tab=subscription');
        } else {
            alert("Gagal: " + res.error);
            setLoading(false);
        }
    };

    // Progress Bar Component
    const StepsHeader = () => {
        const showSchedule = selectedPlan?.isScheduleFlexible;
        const showProducts = selectedPlan?.planProducts?.length > 0;

        const allSteps = [
            { id: 'DATA', label: 'Tujuan Antar', icon: MapPin },
            { id: 'PLAN', label: 'Pilih Menu', icon: Utensils },
            ...(showProducts ? [{ id: 'PRODUCTS' as const, label: 'Isi Sajian', icon: Package }] : []),
            ...(showSchedule ? [{ id: 'DAYS' as const, label: 'Jadwal Ibu', icon: Clock }] : []),
        ];

        return (
            <div className="flex items-center justify-center mb-16 gap-4">
                {allSteps.map((s, idx) => {
                    const isActive = step === s.id;
                    const isDone = allSteps.findIndex(x => x.id === step) > idx;

                    return (
                        <React.Fragment key={s.id}>
                            <div className="flex flex-col items-center gap-3 relative">
                                <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 scale-110 ${isActive ? 'border-[#2D3A2D] bg-[#2D3A2D] text-white shadow-xl rotate-[360deg]' : isDone ? 'border-[#B2BCA2] bg-[#B2BCA2] text-white' : 'border-[#E5E1D8] bg-white text-gray-400'}`}>
                                    {isDone ? <CheckCircle className="w-6 h-6" /> : <s.icon className="w-5 h-5" />}
                                </div>
                                <span className={`text-[10px] font-black uppercase tracking-[0.2em] absolute -bottom-8 whitespace-nowrap ${isActive ? 'text-[#2D3A2D]' : 'text-[#8B7E66]/40'}`}>{s.label}</span>
                            </div>
                            {idx < allSteps.length - 1 && (
                                <div className={`w-12 h-[2px] rounded-full transition-all duration-700 ${isDone ? 'bg-[#B2BCA2]' : 'bg-[#E5E1D8]'}`} />
                            )}
                        </React.Fragment>
                    );
                })}
            </div>
        );
    };

    return (
        <div className="min-h-screen bg-[#FDFBF7] py-20">
            <div className="max-w-6xl mx-auto px-6">
                <header className="mb-10 text-center">
                    <h1 className="text-5xl font-black text-[#2D3A2D] mb-4 font-serif italic">Mulai Tradisi Baru</h1>
                    <p className="text-[#8B7E66] font-medium max-w-lg mx-auto">Sajikan kasih sayang di meja makan setiap hari dengan paket katering pilihan Ibu.</p>
                </header>

                <StepsHeader />

                <AnimatePresence mode="wait">
                    {step === 'DATA' ? (
                        <motion.div
                            key="step-data"
                            initial={{ opacity: 0, y: 20 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: -20 }}
                            className="max-w-xl mx-auto"
                        >
                            <div className="bg-white p-10 rounded-[3rem] shadow-[0_30px_80px_rgba(45,58,45,0.08)] border border-[#E5E1D8]/50">
                                <div className="flex justify-between items-center mb-10">
                                    <h2 className="text-2xl font-black flex items-center gap-3 text-[#2D3A2D] font-serif italic">
                                        <MapPin className="w-6 h-6 text-[#8B7E66]" />
                                        Tujuan Antar
                                    </h2>
                                    {!isAuthenticated && (
                                        <button
                                            onClick={() => handleAuthRedirect('signin')}
                                            className="text-[10px] font-black text-[#8B7E66] hover:text-[#2D3A2D] uppercase tracking-widest border-b border-[#E5E1D8] pb-1"
                                        >
                                            Sudah Punya Akun?
                                        </button>
                                    )}
                                </div>
                                <form onSubmit={handleNext} className="space-y-6">
                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase tracking-[0.2em] text-[#8B7E66] ml-2">Email Utama</label>
                                        <div className="relative">
                                            <input
                                                type="email"
                                                value={formData.email}
                                                onChange={e => setFormData({ ...formData, email: e.target.value })}
                                                required
                                                disabled={isAuthenticated}
                                                className="w-full pl-12 pr-6 py-4 rounded-2xl bg-[#F9F7F2] border border-[#E5E1D8]/50 focus:border-[#2D3A2D] focus:ring-4 focus:ring-[#2D3A2D]/5 transition-all disabled:opacity-60 font-bold text-[#2D3A2D]"
                                                placeholder="email@anda.com"
                                            />
                                            <User className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-[#8B7E66]" />
                                        </div>
                                        {!isAuthenticated && <p className="text-[10px] text-[#8B7E66]/60 mt-2 ml-2 italic">Kode verifikasi akan dikirimkan ke email ini.</p>}
                                    </div>

                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-[#8B7E66] ml-2">Nama Lengkap</label>
                                            <input
                                                value={formData.name}
                                                onChange={e => setFormData({ ...formData, name: e.target.value })}
                                                required
                                                className="w-full px-6 py-4 rounded-2xl bg-[#F9F7F2] border border-[#E5E1D8]/50 focus:border-[#2D3A2D] focus:ring-4 focus:ring-[#2D3A2D]/5 transition-all font-bold text-[#2D3A2D]"
                                                placeholder="Nama Anda"
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-[10px] font-black uppercase tracking-[0.2em] text-[#8B7E66] ml-2">No. WhatsApp</label>
                                            <input
                                                value={formData.phone}
                                                onChange={e => setFormData({ ...formData, phone: e.target.value })}
                                                required
                                                className="w-full px-6 py-4 rounded-2xl bg-[#F9F7F2] border border-[#E5E1D8]/50 focus:border-[#2D3A2D] focus:ring-4 focus:ring-[#2D3A2D]/5 transition-all font-bold text-[#2D3A2D]"
                                                placeholder="0812XXXXXXXX"
                                            />
                                        </div>
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase tracking-[0.2em] text-[#8B7E66] ml-2">Alamat Lengkap</label>
                                        <textarea
                                            value={formData.address}
                                            onChange={e => setFormData({ ...formData, address: e.target.value })}
                                            required
                                            rows={3}
                                            className="w-full px-6 py-4 rounded-2xl bg-[#F9F7F2] border border-[#E5E1D8]/50 focus:border-[#2D3A2D] focus:ring-4 focus:ring-[#2D3A2D]/5 transition-all font-bold text-[#2D3A2D] resize-none"
                                            placeholder="Jalan, Nomor Rumah, RT/RW, Kelurahan, Kecamatan..."
                                        ></textarea>
                                    </div>

                                    <div className="space-y-2">
                                        <label className="text-[10px] font-black uppercase tracking-[0.2em] text-[#8B7E66] ml-2">Catatan Khusus (Opsional)</label>
                                        <textarea
                                            value={formData.customerNote}
                                            onChange={e => setFormData({ ...formData, customerNote: e.target.value })}
                                            rows={2}
                                            className="w-full px-6 py-4 rounded-2xl bg-[#F9F7F2] border border-[#E5E1D8]/50 focus:border-[#2D3A2D] focus:ring-4 focus:ring-[#2D3A2D]/5 transition-all font-bold text-[#2D3A2D] resize-none"
                                            placeholder="Alergi, preferensi menu, atau instruksi pengiriman..."
                                        ></textarea>
                                    </div>

                                    <button
                                        type="submit"
                                        disabled={otpLoading}
                                        className="w-full py-5 bg-[#2D3A2D] hover:bg-[#1a231a] text-white rounded-[2rem] text-xs font-black uppercase tracking-[0.3em] transition-all shadow-2xl hover:shadow-[0_20px_40px_rgba(45,58,45,0.3)] flex items-center justify-center gap-4 mt-10 active:scale-95 disabled:opacity-50"
                                    >
                                        {otpLoading ? <Loader2 className="w-6 h-6 animate-spin" /> : (
                                            <>
                                                {(!isAuthenticated && !isOtpVerified) ? 'Kirim Verifikasi' : 'Lanjut Pilih Menu'}
                                                <ArrowRight className="w-6 h-6" />
                                            </>
                                        )}
                                    </button>
                                </form>
                            </div>
                        </motion.div>
                    ) : (
                        <div className="grid grid-cols-1 md:grid-cols-12 gap-8 animate-in fade-in slide-in-from-right-4 duration-500">
                            {/* Plan List / Day Selection */}
                            <div className="md:col-span-7 space-y-4">
                                {step === 'PLAN' ? (
                                    <>
                                        <div className="flex items-center gap-4 mb-8">
                                            <button onClick={() => setStep('DATA')} className="w-10 h-10 rounded-full bg-white border border-[#E5E1D8] flex items-center justify-center text-[#2D3A2D] hover:bg-[#2D3A2D] hover:text-white transition-all shadow-sm">
                                                <ArrowLeft className="w-5 h-5" />
                                            </button>
                                            <div>
                                                <h2 className="text-2xl font-black text-[#2D3A2D] font-serif italic">Paket Harian</h2>
                                                <p className="text-xs text-[#8B7E66] font-medium tracking-widest uppercase">Pilih langganan yang cocok untuk Anda</p>
                                            </div>
                                        </div>

                                        <div className="space-y-6 max-h-[700px] overflow-y-auto pr-4 scrollbar-hide py-2">
                                            {plans.map((plan) => (
                                                <motion.div
                                                    key={plan.id}
                                                    whileHover={{ scale: 1.02 }}
                                                    onClick={() => {
                                                        setSelectedPlan(plan);
                                                        if (plan.planProducts?.length > 0) {
                                                            setStep('PRODUCTS');
                                                            if (plan.type === 'FIXED') {
                                                                setSelectedProducts(plan.planProducts.map((pp: any) => ({
                                                                    variantId: pp.variantId,
                                                                    quantity: pp.quantity
                                                                })));
                                                            } else {
                                                                setSelectedProducts([]);
                                                            }
                                                        } else if (plan.isScheduleFlexible) {
                                                            setStep('DAYS');
                                                        }
                                                    }}
                                                    className={`cursor-pointer group p-8 rounded-[2.5rem] border-2 transition-all relative overflow-hidden ${selectedPlan?.id === plan.id ? 'border-[#2D3A2D] bg-white shadow-[0_20px_50px_rgba(45,58,45,0.1)]' : 'border-[#E5E1D8]/50 bg-white/50 hover:bg-white hover:border-[#2D3A2D]/30'}`}
                                                >
                                                    <div className="flex justify-between items-start mb-6">
                                                        <div>
                                                            <div className="flex items-center gap-2 mb-1">
                                                                <h3 className="font-black text-[#2D3A2D] text-xl font-serif italic">{plan.name}</h3>
                                                                {plan.type === 'FIXED' && <Star className="w-4 h-4 text-amber-500 fill-amber-500" />}
                                                            </div>
                                                            <span className="text-[10px] bg-[#F9F7F2] text-[#8B7E66] px-3 py-1 rounded-full font-black uppercase tracking-widest border border-[#E5E1D8]/50">
                                                                {plan.interval === 'WEEKLY' ? 'Tagihan Mingguan' : 'Tagihan Bulanan'}
                                                            </span>
                                                        </div>
                                                        <div className={`w-8 h-8 rounded-full border-2 flex items-center justify-center transition-all ${selectedPlan?.id === plan.id ? 'bg-[#2D3A2D] border-[#2D3A2D]' : 'border-[#E5E1D8]'}`}>
                                                            {selectedPlan?.id === plan.id && <CheckCircle className="w-5 h-5 text-white" />}
                                                        </div>
                                                    </div>

                                                    <p className="text-sm text-[#8B7E66] mb-8 font-medium leading-relaxed">{plan.description}</p>

                                                    <div className="flex items-baseline gap-2 mb-8">
                                                        <span className="text-3xl font-black text-[#2D3A2D]">Rp {Number(plan.price).toLocaleString('id-ID')}</span>
                                                        <span className="text-xs text-[#8B7E66] font-black uppercase tracking-widest">/ {plan.interval === 'WEEKLY' ? 'minggu' : 'bulan'}</span>
                                                    </div>

                                                    {plan.features && Array.isArray(plan.features) && (
                                                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-6 border-t border-[#E5E1D8]/50">
                                                            {plan.features.map((feat: string, idx: number) => (
                                                                <div key={idx} className="flex items-center gap-3 text-xs text-[#2D3A2D] font-bold">
                                                                    <div className="w-5 h-5 rounded-full bg-[#B2BCA2]/20 flex items-center justify-center flex-shrink-0">
                                                                        <Heart className="w-3 h-3 text-[#2D3A2D]" />
                                                                    </div>
                                                                    {feat}
                                                                </div>
                                                            ))}
                                                        </div>
                                                    )}

                                                    {selectedPlan?.id === plan.id && (
                                                        <div className="absolute -bottom-6 -right-6 w-32 h-32 bg-[#F9F7F2] rounded-full -z-10 blur-2xl" />
                                                    )}
                                                </motion.div>
                                            ))}
                                        </div>
                                    </>
                                ) : (
                                    step === 'PRODUCTS' ? (
                                        <div className="animate-in fade-in slide-in-from-right-4 duration-500">
                                            <div className="flex items-center gap-4 mb-8">
                                                <button onClick={() => setStep('PLAN')} className="w-10 h-10 rounded-full bg-white border border-[#E5E1D8] flex items-center justify-center text-[#2D3A2D] hover:bg-[#2D3A2D] hover:text-white transition-all shadow-sm">
                                                    <ArrowLeft className="w-5 h-5" />
                                                </button>
                                                <div>
                                                    <h2 className="text-2xl font-black text-[#2D3A2D] font-serif italic">
                                                        {selectedPlan.type === 'FIXED' ? 'Isi Paket' : 'Pilih Lauk'}
                                                    </h2>
                                                    <p className="text-xs text-[#8B7E66] font-medium tracking-widest uppercase">Tentukan hidangan favorit Anda</p>
                                                </div>
                                            </div>

                                            <div className="bg-white p-10 rounded-[3rem] border border-[#E5E1D8]/50 shadow-[0_30px_80px_rgba(45,58,45,0.05)]">
                                                <p className="text-sm text-[#8B7E66] mb-10 font-medium">
                                                    {selectedPlan.type === 'FIXED'
                                                        ? 'Paket ini sudah termasuk menu tetap pilihan Ibu:'
                                                        : `Silakan pilih hingga ${selectedPlan.limitItems} hidangan yang Anda inginkan untuk minggu ini:`}
                                                </p>

                                                <div className="space-y-4">
                                                    {selectedPlan.planProducts?.map((pp: any) => {
                                                        const isSelected = selectedProducts.some(p => p.variantId === pp.variantId);
                                                        const currentQty = selectedProducts.find(p => p.variantId === pp.variantId)?.quantity || 0;

                                                        return (
                                                            <motion.div
                                                                key={pp.variantId}
                                                                layout
                                                                className={`p-6 rounded-[2rem] border-2 transition-all flex items-center gap-6 ${isSelected ? 'border-[#2D3A2D] bg-[#F9F7F2]' : 'border-[#E5E1D8]/30 bg-white'}`}
                                                            >
                                                                <div className="w-20 h-20 rounded-2xl overflow-hidden flex-shrink-0 bg-[#FDFBF7] border border-[#E5E1D8]/50 flex items-center justify-center">
                                                                    {pp.variant?.product?.image ? (
                                                                        <img src={pp.variant.product.image} alt={pp.variant?.product?.name} className="w-full h-full object-cover" />
                                                                    ) : (
                                                                        <Utensils className="w-8 h-8 text-[#B2BCA2]" />
                                                                    )}
                                                                </div>

                                                                <div className="flex-1">
                                                                    <div className="font-black text-[#2D3A2D] text-lg font-serif italic">{pp.variant?.product?.name || 'Produk'}</div>
                                                                    <div className="text-[10px] text-[#8B7E66] font-black uppercase tracking-widest mt-1">{pp.variant?.name}</div>

                                                                    {(isSelected || selectedPlan.type === 'FIXED') && (
                                                                        <div className="mt-4">
                                                                            <input
                                                                                type="text"
                                                                                placeholder="Ada catatan khusus untuk menu ini?"
                                                                                value={selectedProducts.find(p => p.variantId === pp.variantId)?.note || ''}
                                                                                onChange={(e) => {
                                                                                    setSelectedProducts(prev => {
                                                                                        const existing = prev.find(p => p.variantId === pp.variantId);
                                                                                        if (existing) return prev.map(p => p.variantId === pp.variantId ? { ...p, note: e.target.value } : p);
                                                                                        if (selectedPlan.type === 'FIXED') return [...prev, { variantId: pp.variantId, quantity: pp.quantity, note: e.target.value }];
                                                                                        return prev;
                                                                                    });
                                                                                }}
                                                                                className="w-full px-4 py-2 text-xs rounded-xl border border-[#E5E1D8] focus:border-[#2D3A2D] focus:ring-4 focus:ring-[#2D3A2D]/5 transition-all bg-white font-medium"
                                                                            />
                                                                        </div>
                                                                    )}
                                                                </div>

                                                                {selectedPlan.type === 'FIXED' ? (
                                                                    <div className="px-5 py-3 bg-[#2D3A2D] text-white rounded-xl font-black text-sm shadow-lg">
                                                                        {pp.quantity} pcs
                                                                    </div>
                                                                ) : (
                                                                    <div className="flex items-center gap-4 bg-white p-2 rounded-2xl border border-[#E5E1D8]">
                                                                        <button
                                                                            onClick={() => {
                                                                                setSelectedProducts(prev => {
                                                                                    const existing = prev.find(p => p.variantId === pp.variantId);
                                                                                    if (!existing) return prev;
                                                                                    if (existing.quantity === 1) return prev.filter(p => p.variantId !== pp.variantId);
                                                                                    return prev.map(p => p.variantId === pp.variantId ? { ...p, quantity: p.quantity - 1 } : p);
                                                                                });
                                                                            }}
                                                                            className="w-8 h-8 rounded-full bg-[#F9F7F2] text-[#2D3A2D] flex items-center justify-center font-black hover:bg-[#2D3A2D] hover:text-white transition-all"
                                                                        >-</button>
                                                                        <span className="w-4 text-center font-black text-[#2D3A2D]">{currentQty}</span>
                                                                        <button
                                                                            onClick={() => {
                                                                                const totalItems = selectedProducts.reduce((sum, p) => sum + p.quantity, 0);
                                                                                if (totalItems >= (selectedPlan.limitItems || 0)) return;
                                                                                setSelectedProducts(prev => {
                                                                                    const existing = prev.find(p => p.variantId === pp.variantId);
                                                                                    if (existing) return prev.map(p => p.variantId === pp.variantId ? { ...p, quantity: p.quantity + 1 } : p);
                                                                                    return [...prev, { variantId: pp.variantId, quantity: 1 }];
                                                                                });
                                                                            }}
                                                                            className="w-8 h-8 rounded-full bg-[#B2BCA2] text-[#2D3A2D] flex items-center justify-center font-black hover:bg-[#2D3A2D] hover:text-white transition-all"
                                                                        >+</button>
                                                                    </div>
                                                                )}
                                                            </motion.div>
                                                        );
                                                    })}
                                                </div>

                                                <div className="mt-12">
                                                    <button
                                                        onClick={() => {
                                                            if (selectedPlan.type === 'CUSTOMIZABLE') {
                                                                const totalItems = selectedProducts.reduce((sum, p) => sum + p.quantity, 0);
                                                                if (totalItems === 0) { alert("Silakan pilih hidangan terlebih dahulu."); return; }
                                                            }
                                                            setStep('DAYS');
                                                        }}
                                                        className="w-full py-5 bg-[#2D3A2D] text-white rounded-[2rem] text-xs font-black uppercase tracking-[0.3em] transition-all shadow-2xl hover:shadow-[0_20px_40px_rgba(45,58,45,0.3)] flex items-center justify-center gap-4"
                                                    >
                                                        Lanjut {selectedPlan.interval === 'WEEKLY' ? 'Pilih Jadwal' : 'Checkout'}
                                                        <ArrowRight className="w-6 h-6" />
                                                    </button>
                                                </div>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="animate-in fade-in slide-in-from-right-4 duration-500">
                                            <div className="flex items-center gap-4 mb-8">
                                                <button
                                                    onClick={() => {
                                                        if (selectedPlan.planProducts?.length > 0) setStep('PRODUCTS');
                                                        else setStep('PLAN');
                                                    }}
                                                    className="w-10 h-10 rounded-full bg-white border border-[#E5E1D8] flex items-center justify-center text-[#2D3A2D] hover:bg-[#2D3A2D] hover:text-white transition-all shadow-sm"
                                                >
                                                    <ArrowLeft className="w-5 h-5" />
                                                </button>
                                                <div>
                                                    <h2 className="text-2xl font-black text-[#2D3A2D] font-serif italic">Waktu Antar</h2>
                                                    <p className="text-xs text-[#8B7E66] font-medium tracking-widest uppercase">Atur jadwal pengiriman Ibu</p>
                                                </div>
                                            </div>

                                            <div className="bg-white p-10 rounded-[3rem] border border-[#E5E1D8]/50 shadow-[0_30px_80px_rgba(45,58,45,0.05)]">
                                                <div className="flex flex-col items-center text-center mb-10">
                                                    <div className="w-20 h-20 bg-[#B2BCA2]/10 rounded-full flex items-center justify-center mb-6 shadow-inner">
                                                        <Clock className="w-10 h-10 text-[#2D3A2D]" />
                                                    </div>
                                                    <h3 className="text-xl font-serif italic text-[#2D3A2D] mb-2">Pilih Hari Penuh Kasih</h3>
                                                    <p className="text-xs text-[#8B7E66] max-w-sm leading-relaxed font-medium">
                                                        Pilih hari apa saja paket katering ingin dikirimkan ke rumah Anda dalam satu minggu.
                                                    </p>
                                                </div>

                                                {!selectedPlan.isScheduleFlexible ? (
                                                    <div className="flex flex-col items-center text-center py-16 px-8 bg-[#F9F7F2] rounded-[3rem] border border-[#E5E1D8]/50 relative overflow-hidden">
                                                        <div className="absolute top-0 right-0 w-32 h-32 bg-[#2D3A2D]/5 rounded-full -mr-16 -mt-16 blur-3xl" />
                                                        <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl">
                                                            <ShieldCheck className="w-12 h-12 text-[#2D3A2D]" />
                                                        </div>
                                                        <h3 className="text-2xl font-serif italic text-[#2D3A2D] mb-4">Jadwal Ditentukan Ibu</h3>
                                                        <p className="text-sm text-[#8B7E66] max-w-sm leading-relaxed mb-10 font-medium">
                                                            Untuk menjaga kesegaran maksimal, jadwal pengiriman diatur sepenuhnya oleh tim Rasa Ibu setiap harinya.
                                                        </p>
                                                        <div className="flex items-center gap-3 text-xs font-black text-white bg-[#2D3A2D] px-6 py-3 rounded-full tracking-widest shadow-xl">
                                                            <CheckCircle className="w-4 h-4 text-amber-500" />
                                                            SIAP DIANTAR KE MEJA MAKAN
                                                        </div>
                                                    </div>
                                                ) : (
                                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                                        {daysOfWeek.map((day) => {
                                                            const isSelected = selectedDays.some(d => d.day === day.id);
                                                            const selectedDayData = selectedDays.find(d => d.day === day.id);

