        // Verify component exists
        const component = await prisma.priceComponent.findUnique({
            where: { id: componentId }
        });

        if (!component) {
            return NextResponse.json(
                { error: 'Component not found' },
                { status: 404 }
            );
        }

        const rule = await prisma.priceRule.create({
            data: {
                componentId,
                scope: scope as PriceScope,
                scopeId: scopeId || null,
                priority: priority || 0,
                currency: currency || 'IDR',
                amount,
                minQty: minQty || null,
                maxQty: maxQty || null,
                minOrderMeter: minOrderMeter || null,
                metadata: metadata || null,
                isActive: isActive !== undefined ? isActive : true,
                startAt: startAt ? new Date(startAt) : null,
                endAt: endAt ? new Date(endAt) : null
            },
            include: {
                component: true
            }
        });

        // Create audit log
        await prisma.priceHistory.create({
            data: {
                ruleId: rule.id,
                action: 'CREATED',
                payload: rule,
                performedBy: null // TODO: Add user ID from session
            }
        });

        return NextResponse.json(rule, { status: 201 });
    } catch (error) {
        console.error('Failed to create rule:', error);
        return NextResponse.json(
            { error: 'Internal server error' },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET(request: NextRequest) {
    const searchParams = request.nextUrl.searchParams;
    const scope = searchParams.get('scope');
    const brandSlug = searchParams.get('brandSlug'); // Optional filtering

    if (!scope) {
        return NextResponse.json({ error: 'Scope required' }, { status: 400 });
    }

    try {
        let items: any[] = [];

        if (scope === 'PRODUCT') {
            items = await prisma.product.findMany({
                where: {
                    collection: brandSlug ? {
                        brand: {
                            slug: brandSlug
                        }
                    } : undefined
                },
                select: {
                    id: true,
                    name: true
                    // Removed 'images' as it does not exist on Product model
                },
                orderBy: { name: 'asc' }
            });
        } else if (scope === 'VARIANT') {
            items = await prisma.productVariant.findMany({
                where: {
                    product: brandSlug ? {
                        collection: {
                            brand: {
                                slug: brandSlug
                            }
                        }
                    } : undefined
                },
                select: {
                    id: true,
                    name: true,
                    product: {
                        select: {
                            name: true
                        }
                    }
                },
                orderBy: {
                    product: {
                        name: 'asc'
                    }
                }
            });
            // Map to friendly name
            items = items.map(i => ({
                id: i.id,
                name: `${i.product.name} - ${i.name}`
            }));
        } else if (scope === 'BRAND') {
            items = await prisma.brand.findMany({
                select: { id: true, name: true }
            });
        }

        return NextResponse.json(items);

    } catch (error) {
        console.error('Error fetching scope options:', error);
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
    }
}

