import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function POST(
    req: NextRequest,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const resolvedParams = await params;
        const { id } = resolvedParams;

        // Verify order exists
        const order = await prisma.order.findUnique({
            where: { id },
            select: { id: true, invoiceNo: true, status: true }
        });

        if (!order) {
            return NextResponse.json({ error: 'Order not found' }, { status: 404 });
        }

        // Only allow cancellation for unpaid statuses
        const cancellableStatuses = ['DIPESAN', 'WAITING_PAYMENT', 'MENUNGGU_VERIFIKASI_QRIS'];
        if (!cancellableStatuses.includes(order.status)) {
            return NextResponse.json({
                error: `Order cannot be cancelled in status: ${order.status}`
            }, { status: 400 });
        }

        // Perform cancellation
        await prisma.$transaction([
            prisma.order.update({
                where: { id: order.id },
                data: { status: 'CANCELLED' }
            }),
            prisma.orderStatusLog.create({
                data: {
                    orderId: order.id,
                    status: 'CANCELLED',
                    message: 'Pesanan dibatalkan oleh pelanggan melalui halaman pelacakan.'
                }
            })
        ]);

        return NextResponse.json({ success: true });

    } catch (error: any) {
        console.error('Cancel order error:', error);
        return NextResponse.json({
            error: 'Internal Server Error',
            details: error?.message || 'Unknown error'
        }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { writeFile } from 'fs/promises';
import { join } from 'path';
import { mkdir } from 'fs/promises';

export async function POST(
    req: NextRequest,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const resolvedParams = await params;
        const { id } = resolvedParams;

        // Verify order exists
        const order = await prisma.order.findUnique({ where: { id } });
        if (!order) {
            return NextResponse.json({ error: 'Order not found' }, { status: 404 });
        }

        const formData = await req.formData();
        const file = formData.get('proof') as File | null;

        if (!file) {
            return NextResponse.json({ error: 'No file uploaded' }, { status: 400 });
        }

        const bytes = await file.arrayBuffer();
        const buffer = Buffer.from(bytes);

        // Ensure directory exists
        const uploadDir = join(process.cwd(), 'public/uploads/proofs');
        await mkdir(uploadDir, { recursive: true });

        // Generate filename
        const filename = `${order.invoiceNo}-proof-${Date.now()}.${file.name.split('.').pop()}`;
        const filepath = join(uploadDir, filename);

        await writeFile(filepath, buffer);

        const publicPath = `/uploads/proofs/${filename}`;

        const paymentType = (formData.get('paymentType') as string) || 'DP';
        const destinationBankId = formData.get('destinationBankId') as string | null;
        const sourceBankName = formData.get('sourceBankName') as string | null;

        console.log(`[ProofUpload] Proceeding with ${paymentType} for order ${order.invoiceNo}`);

        // Determine Payment amount and type
        let amount = Number(order.total) * 0.5;
        let newStatus = order.status;
        let logMessage = 'Payment proof uploaded by customer';

        if (paymentType === 'QRIS') {
            amount = Number(order.total);
            newStatus = 'MENUNGGU_VERIFIKASI_QRIS';
            logMessage = 'Bukti pembayaran QRIS diunggah oleh pelanggan';
        }

        // Validate Status for Enum (OrderStatusLog)
        const validLogStatuses = [
            'DIPESAN', 'MENUNGGU_VERIFIKASI_QRIS', 'DIBAYAR',
            'DISIAPKAN', 'DIKIRIM', 'SELESAI', 'CANCELLED'
        ];
        const safeLogStatus = validLogStatuses.includes(newStatus) ? newStatus : 'DIPESAN';

        await prisma.payment.create({
            data: {
                orderId: order.id,
                amount: amount,
                type: paymentType,
                proofPath: publicPath,
                destinationBankId: (destinationBankId && destinationBankId !== 'undefined') ? destinationBankId : undefined,
                sourceBankName: sourceBankName || undefined,
                isVerified: false
            }
        });

        // Update Order Status if it's QRIS
        if (paymentType === 'QRIS') {
            await prisma.order.update({
                where: { id: order.id },
                data: { status: newStatus }
            });
        }

        await prisma.orderStatusLog.create({
            data: {
                orderId: order.id,
                status: safeLogStatus as any,
                message: logMessage
            }
        });

        // Notify Admin (Async)
        try {
            const { EmailService } = await import('@/lib/services/EmailService');
            await EmailService.sendAdminAlert(
                `Bukti Pembayaran Baru: ${order.invoiceNo}`,
                `Pelanggan baru saja mengunggah bukti pembayaran untuk invoice ${order.invoiceNo}.\n\nSilakan cek di dashboard admin.`
            );
            console.log(`[UploadProof] Notified admin via email about proof for ${order.invoiceNo}`);
        } catch (e) {
            console.error('[UploadProof] Email notification error:', e);
        }

        return NextResponse.json({ success: true, path: publicPath });

    } catch (error: any) {
        console.error('CRITICAL: Upload proof error:', error);
        return NextResponse.json({
            error: 'Internal Server Error',
            details: error?.message || 'Unknown error'
        }, { status: 500 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function GET(
    req: NextRequest,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const resolvedParams = await params;
        const { id } = resolvedParams;

        if (!id) {
            return NextResponse.json({ error: 'Order ID or Invoice required' }, { status: 400 });
        }

        // Common include object
        const includeConfig = {
            brand: {
                select: {
                    name: true,
                    paymentSettings: true
                }
            },
            statusLogs: { orderBy: { createdAt: 'desc' } },
            payments: { orderBy: { createdAt: 'desc' } },
            orderItems: {
                include: {
                    frozenVariant: {
                        include: {
                            product: {
                                include: {
                                    category: true
                                }
                            }
                        }
                    },
                    variant: true
                },
                orderBy: { createdAt: 'asc' }
            }
        } as const;

        // Try finding by ID first
        let order = await prisma.order.findUnique({
            where: { id },
            include: includeConfig
        });

        if (!order) {
            // Fallback to Invoice lookup
            order = await prisma.order.findUnique({
                where: { invoiceNo: id },
                include: includeConfig
            });
        }

        if (!order) {
            return NextResponse.json({ error: 'Order not found' }, { status: 404 });
        }

        const safeOrder = order as any;

        // Process items with self-healing logic for missing data (legacy/broken orders)
        const enrichedItems = await Promise.all(safeOrder.orderItems.map(async (item: any) => {
            let imagePath = item.mockupResultPath;
            let subtotal = Number(item.subtotal);
            let name = item.name;
            let variantName = item.variantName;
            let categorySlug = 'siap-saji'; // Default

            // Enriched info from relations if available
            if (item.frozenVariant) {
                name = item.frozenVariant.product?.name || name;
                variantName = item.frozenVariant.name || variantName;
                imagePath = imagePath || item.frozenVariant.product?.image;
                categorySlug = item.frozenVariant.product?.category?.slug || 'siap-saji';
            } else if (item.variant) {
                variantName = item.variant.name || variantName;
            }

            return {
                id: item.id,
                name: name,
                variantName: variantName,
                quantity: item.quantity,
                subtotal: subtotal,
                mockupResultPath: imagePath,
                categorySlug: categorySlug
            };
        }));

        // Recalculate total if original was 0 (broken order)
        const calculatedTotal = enrichedItems.reduce((acc, item) => acc + item.subtotal, 0);
        const finalTotal = Number(safeOrder.total) === 0 ? calculatedTotal : Number(safeOrder.total);

        // Return safe public data
        return NextResponse.json({
            id: order.id,
            invoiceNo: safeOrder.invoiceNo,
            createdAt: safeOrder.createdAt,
            status: safeOrder.status,
            paymentMethod: safeOrder.paymentMethod,
            customerName: safeOrder.customerName,
            customerNote: safeOrder.customerNote,
            subtotal: Number(safeOrder.subtotal) === 0 ? calculatedTotal : Number(safeOrder.subtotal),
            total: finalTotal,

            // Legacy / Single Item Fields (Fallback for components expecting these)
            productName: enrichedItems[0]?.name,
            variantName: enrichedItems[0]?.variantName,
            variantImage: enrichedItems[0]?.mockupResultPath,

            quantity: safeOrder.quantity,
            logs: safeOrder.statusLogs,
            payments: safeOrder.payments,
            items: enrichedItems,
            paymentSettings: safeOrder.brand?.paymentSettings || { downPaymentPercentage: 50 },
            brandId: safeOrder.brandId,
            brandName: safeOrder.brand?.name || 'ACHIERA',
        });

    } catch (error) {
        console.error('Track order error:', error);
        return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
    }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

export async function POST(req: Request) {
    try {
        const body = await req.json();
        const {
            items, // Array of { productId, variantId, quantity, mockupResultPath, designUploadPath }
            productId, variantId, quantity, // Legacy fallback
            customerName, customerEmail, customerPhone, customerAddress, customerNote,
            mockupResultPath // Legacy fallback
        } = body;

        // Normalize items
        let orderItemsData = [];
        if (items && Array.isArray(items) && items.length > 0) {
            orderItemsData = items;
        } else if (productId && variantId) {
            orderItemsData = [{ productId, variantId, quantity, mockupResultPath }];
        } else {
            return NextResponse.json({ error: 'No items provided' }, { status: 400 });
        }

        console.log(`[OrderAPI] Processing ${orderItemsData.length} items`);

        // 1. Validate & Calculate Totals
        let finalSubtotal = 0;
        let finalTax = 0;
        let finalTotal = 0;
        const processedItems = [];

        for (const item of orderItemsData) {
            // Updated to use ProductVariant (Collection-First Schema)
            const variant = await prisma.productVariant.findUnique({
                where: { id: item.variantId },
                include: { product: true }
            });

            if (!variant || variant.productId !== item.productId) {
                return NextResponse.json({ error: `Invalid product/variant for item ${item.variantId}` }, { status: 400 });
            }

            // If price is provided (e.g. from Bulk Calculator), use it. Otherwise fallback to Base Price.
            // In a strict environment, we should Re-Calculate here using PriceCalculator.
            let price = item.price ? Number(item.price) : Number(variant.basePrice);
            if (isNaN(price)) price = Number(variant.basePrice);

            const { subtotal, tax, total } = calculateOrderTotal(price, item.quantity);

            finalSubtotal += subtotal;
            finalTax += tax;
            finalTotal += total;

            processedItems.push({
                name: variant.product.name,
                variantName: variant.name,
                quantity: item.quantity,
                price: price,
                subtotal: subtotal,
                // Design Meta: Use provided mockup, or fallback to product base image
                mockupResultPath: item.mockupResultPath || variant.product.baseImage,
                designUploadPath: item.designUploadPath || undefined,
                metadata: (item as any).metadata || undefined
            });
        }

        console.log(`[OrderAPI] Total Order Amount: ${finalTotal}`);

        // 2. Generate Invoice No
        let invoiceNo = generateInvoiceNumber();
        let exists = await prisma.order.findUnique({ where: { invoiceNo } });
        while (exists) {
            invoiceNo = generateInvoiceNumber();
            exists = await prisma.order.findUnique({ where: { invoiceNo } });
        }

        // 3. Create Order with Items
        const order = await prisma.order.create({
            data: {
                invoiceNo,
                quantity: processedItems.reduce((acc, i) => acc + i.quantity, 0),
                subtotal: finalSubtotal,
                tax: finalTax,
                total: finalTotal,

                customerName,
                customerEmail,
                customerPhone,
                customerAddress,
                customerNote,
                // Save the "Raw Design" path if provided
                designUploadPath: items[0]?.designUploadPath || null,
                // Legacy Order-level mockup path (optional, can just use first item's or leave null)
                mockupResultPath: processedItems[0]?.mockupResultPath,

                status: 'WAITING_PAYMENT',
                termsAccepted: true,

                orderItems: {
                    create: processedItems
                },

                statusLogs: {
                    create: {
                        status: 'DIPESAN',
                        message: `Order created with ${processedItems.length} items`
                    }
                }
            },
            include: {
                orderItems: true
            }
        });

        // 4. Trigger Async Services
        try {
            const { InvoiceService } = await import('@/lib/services/InvoiceService');
            const { EmailService } = await import('@/lib/services/EmailService');

            await InvoiceService.generateAndSend(order);
            await EmailService.sendOrderConfirmation(order as any);
        } catch (serviceError) {
            console.error('[OrderAPI] Service trigger failed:', serviceError);
        }

        return NextResponse.json({
            success: true,
            invoiceNo: order.invoiceNo,
            total: Number(order.total)
        });

    } catch (error) {
        console.error('Order creation failed:', error);
        // @ts-ignore
        const errorMessage = error?.message || 'Unknown error';
        return NextResponse.json({ error: 'Internal Server Error', details: errorMessage }, { status: 500 });
    }
}

function calculateOrderTotal(price: number, quantity: number) {
    const subtotal = price * quantity;
    const tax = subtotal * 0.11; // 11% Tax
    const total = subtotal + tax;
    return { subtotal, tax, total };
}

function generateInvoiceNumber() {
    const date = new Date();
    const year = date.getFullYear().toString().substr(-2);
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const day = date.getDate().toString().padStart(2, '0');
    const random = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
    return `INV/${year}${month}${day}/${random}`;
}

