'use client';

import React, { useState } from 'react';
import Link from 'next/navigation'; // Using next/navigation but keeping Link as name for simplicity, actually it should be next/link
import LinkNext from 'next/link';
import { signIn } from 'next-auth/react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Loader2, Mail, Lock, ShieldCheck, ArrowRight, Heart, Star } from 'lucide-react';
import { motion } from 'framer-motion';

export default function LoginPage() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const callbackUrl = searchParams.get('callbackUrl') || '/rasa-ibu/profile';
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [loginMethod, setLoginMethod] = useState<'PASSWORD' | 'OTP'>('PASSWORD');
    const [otpSent, setOtpSent] = useState(false);
    const [otpCode, setOtpCode] = useState('');
    const [email, setEmail] = useState('');
    const [timer, setTimer] = useState(0);

    // Timer Effect
    React.useEffect(() => {
        let interval: NodeJS.Timeout;
        if (timer > 0) {
            interval = setInterval(() => {
                setTimer((prev) => prev - 1);
            }, 1000);
        }
        return () => clearInterval(interval);
    }, [timer]);

    const handleSendOTP = async () => {
        if (!email) {
            setError('Masukkan email Anda.');
            return;
        }
        setLoading(true);
        setError('');
        try {
            const res = await fetch('/api/auth/otp/send', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, type: 'OTP_LOGIN' })
            });
            const data = await res.json();
            if (data.success) {
                setOtpSent(true);
                setTimer(60);
            } else {
                setError(data.error || 'Gagal mengirim OTP.');
            }
        } catch (err) {
            setError('Terjadi kesalahan jaringan.');
        } finally {
            setLoading(false);
        }
    };

    const handleVerifyOTP = async () => {
        if (!otpCode || otpCode.length !== 6) return;
        setLoading(true);
        setError('');
        try {
            const res = await fetch('/api/auth/otp/verify', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, code: otpCode, type: 'OTP_LOGIN' })
            });
            const data = await res.json();
            if (data.success) {
                const result = await signIn('credentials', {
                    redirect: false,
                    email,
                    otpToken: data.token,
                });

                if (result?.error) {
                    setError('Gagal masuk setelah verifikasi.');
                } else {
                    router.push(callbackUrl);
                    router.refresh();
                }
            } else {
                setError(data.message || 'OTP tidak valid.');
            }
        } catch (err) {
            setError('Terjadi kesalahan verifikasi.');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (loginMethod === 'OTP') return;

        setLoading(true);
        setError('');

        const formData = new FormData(e.currentTarget);
        const loginEmail = formData.get('email') as string;
        const password = formData.get('password') as string;

        const res = await signIn('credentials', {
            redirect: false,
            email: loginEmail,
            password,
        });

        if (res?.error) {
            setError('Email atau password salah.');
            setLoading(false);
        } else {
            router.push(callbackUrl);
            router.refresh();
        }
    };

    return (
        <div className="min-h-[700px] flex flex-col md:flex-row bg-[#FDFBF7] rounded-[3rem] overflow-hidden shadow-2xl border border-[#E5E1D8]">
            {/* Left side: Brand Message (Desktop Only) */}
            <div className="hidden md:flex md:w-1/2 bg-[#2D3A2D] p-16 flex-col justify-between relative overflow-hidden">
                {/* Background Decorative Elements */}
                <div className="absolute top-0 right-0 w-64 h-64 bg-[#B2BCA2]/10 rounded-full -mr-32 -mt-32 blur-3xl pointer-events-none" />
                <div className="absolute bottom-0 left-0 w-96 h-96 bg-[#8B7E66]/10 rounded-full -ml-48 -mb-48 blur-3xl pointer-events-none" />

                <div className="relative z-10">
                    <LinkNext href="/rasa-ibu">
                        <img src="/images/brand/logo.png" alt="Rasa Ibu" className="h-16 w-auto brightness-0 invert mb-20" />
                    </LinkNext>

                    <div className="space-y-6">
                        <motion.div
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ duration: 0.8 }}
                        >
                            <span className="text-amber-500 font-black uppercase tracking-[0.4em] text-xs">Kembali ke Kehangatan</span>
                            <h1 className="text-5xl font-black text-white leading-tight font-serif italic mt-4">
                                Kejujuran <br /> Dari Dapur Ibu.
                            </h1>
                        </motion.div>

                        <motion.p
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            transition={{ delay: 0.5, duration: 0.8 }}
                            className="text-[#FDFBF7]/70 text-lg max-w-sm leading-relaxed"
                        >
                            Setiap hidangan disiapkan dengan bahan segar pilihan, tanpa pengawet, dan penuh kasih sayang.
                        </motion.p>
                    </div>
                </div>

                <div className="relative z-10 grid grid-cols-2 gap-8 border-t border-white/10 pt-12">
                    <div>
                        <div className="flex gap-1 mb-2">
                            <ShieldCheck className="w-5 h-5 text-amber-500" />
                        </div>
                        <p className="text-white text-sm font-bold">100% Alami</p>
                        <p className="text-white/40 text-[10px] uppercase tracking-widest mt-1">Tanpa Pengawet</p>
                    </div>
                    <div>
                        <div className="w-8 h-8 rounded-full bg-amber-500/20 flex items-center justify-center mb-2">
                            <Heart className="w-4 h-4 text-amber-500 fill-amber-500" />
                        </div>
                        <p className="text-white text-sm font-bold">Resep Asli Ibu</p>
                        <p className="text-white/40 text-[10px] uppercase tracking-widest mt-1">Kasih Sayang Tulus</p>
                    </div>
                </div>
            </div>

            {/* Right side: Login Form */}
            <div className="flex-1 p-8 md:p-16 flex flex-col justify-center bg-white">
                <div className="max-w-md mx-auto w-full">
                    {/* Mobile Logo */}
                    <div className="md:hidden flex justify-center mb-12">
                        <img src="/images/brand/logo.png" alt="Rasa Ibu" className="h-12 w-auto" />
                    </div>

                    <div className="mb-10 text-center md:text-left">
                        <h2 className="text-3xl font-black text-[#2D3A2D] font-serif">Masuk Akun</h2>
                        <p className="text-[#8B7E66] mt-3 font-medium">Selamat datang kembali di Dapur Rasa Ibu.</p>
                    </div>

                    {error && (
                        <motion.div
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            className="bg-red-50 text-red-600 p-4 rounded-2xl text-sm mb-6 font-bold text-center border border-red-100"
                        >
                            {error}
                        </motion.div>
                    )}

                    {/* Method Toggle */}
                    <div className="flex bg-[#F9F7F2] p-1.5 rounded-2xl mb-8 border border-[#E5E1D8]/50">
                        <button
                            onClick={() => { setLoginMethod('PASSWORD'); setError(''); }}
                            className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${loginMethod === 'PASSWORD' ? 'bg-[#2D3A2D] text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}
                        >
                            Password
                        </button>
                        <button
                            onClick={() => { setLoginMethod('OTP'); setError(''); }}
                            className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${loginMethod === 'OTP' ? 'bg-[#2D3A2D] text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}
                        >
                            Email OTP
                        </button>
                    </div>

                    {loginMethod === 'PASSWORD' ? (
                        <form onSubmit={handleSubmit} className="space-y-6">
                            <div className="space-y-2">
                                <label className="block text-xs font-black uppercase tracking-widest text-[#2D3A2D] ml-1">Email</label>
                                <div className="relative group">
                                    <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 group-focus-within:text-[#2D3A2D] transition-colors" />
                                    <input
                                        name="email"
                                        type="email"
                                        required
                                        className="w-full pl-12 pr-4 py-4 rounded-2xl bg-[#F9F7F2] border border-[#E5E1D8] focus:ring-2 focus:ring-[#2D3A2D] focus:bg-white transition-all outline-none font-medium text-[#2D3A2D]"
                                        placeholder="email@contoh.com"
                                    />
                                </div>
                            </div>
                            <div className="space-y-2">
                                <div className="flex justify-between items-center ml-1">
                                    <label className="block text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Password</label>
                                    <LinkNext href="/auth/forgot-password" title="Atur ulang password" className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest hover:text-[#2D3A2D] transition-colors">Lupa?</LinkNext>
                                </div>
                                <div className="relative group">
                                    <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 group-focus-within:text-[#2D3A2D] transition-colors" />
                                    <input
                                        name="password"
                                        type="password"
                                        required
                                        className="w-full pl-12 pr-4 py-4 rounded-2xl bg-[#F9F7F2] border border-[#E5E1D8] focus:ring-2 focus:ring-[#2D3A2D] focus:bg-white transition-all outline-none font-medium text-[#2D3A2D]"
                                        placeholder="********"
                                    />
                                </div>
                            </div>

                            <button
                                disabled={loading}
                                className="w-full py-5 bg-[#2D3A2D] hover:bg-[#1A241A] text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all shadow-xl hover:shadow-[0_20px_40px_rgba(45,58,45,0.2)] disabled:opacity-50 flex items-center justify-center gap-3 active:scale-95"
                            >
                                {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <span>Masuk Sekarang</span>}
                            </button>
                        </form>
                    ) : (
                        <div className="space-y-6">
                            {!otpSent ? (
                                <div className="space-y-6">
                                    <div className="space-y-2">
                                        <label className="block text-xs font-black uppercase tracking-widest text-[#2D3A2D] ml-1">Email Akun</label>
                                        <div className="relative group">
                                            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 group-focus-within:text-[#2D3A2D] transition-colors" />
                                            <input
                                                value={email}
                                                onChange={(e) => setEmail(e.target.value)}
                                                type="email"
                                                className="w-full pl-12 pr-4 py-4 rounded-2xl bg-[#F9F7F2] border border-[#E5E1D8] focus:ring-2 focus:ring-[#2D3A2D] focus:bg-white transition-all outline-none font-medium text-[#2D3A2D]"
                                                placeholder="email@contoh.com"
                                            />
                                        </div>
                                        <p className="text-[10px] text-gray-400 mt-2 ml-1 italic">Kami akan mengirimkan kode verifikasi 6-digit.</p>
                                    </div>
                                    <button
                                        onClick={handleSendOTP}
                                        disabled={loading || !email}
                                        className="w-full py-5 bg-[#8B7E66] hover:bg-[#6D6351] text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all shadow-xl disabled:opacity-50 flex items-center justify-center gap-2 active:scale-95"
                                    >
                                        {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <span>Kirim Kode OTP</span>}
                                    </button>
                                </div>
                            ) : (
                                <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
                                    <div className="space-y-4">
                                        <label className="block text-xs font-black uppercase tracking-widest text-[#2D3A2D] text-center">Masukkan Kode Verifikasi</label>
                                        <input
                                            value={otpCode}
                                            onChange={(e) => setOtpCode(e.target.value.trim().replace(/\D/g, '').slice(0, 6))}
                                            className="w-full text-center text-3xl font-black py-5 rounded-2xl bg-[#F9F7F2] border border-[#E5E1D8] focus:ring-2 focus:ring-[#2D3A2D] focus:bg-white tracking-[0.5em] outline-none text-[#2D3A2D]"
                                            placeholder="000000"
                                            maxLength={6}
                                        />
                                        <div className="text-center space-y-2">
                                            <p className="text-[10px] text-gray-400">
                                                Kode terkirim ke <span className="font-bold text-[#2D3A2D]">{email}</span>.
                                                <button onClick={() => setOtpSent(false)} className="ml-2 text-[#8B7E66] hover:underline font-bold">Ubah?</button>
                                            </p>
                                            <div className="h-6 flex items-center justify-center">
                                                {timer > 0 ? (
                                                    <p className="text-[10px] text-gray-400 italic">Kirim ulang dalam {timer} detik</p>
                                                ) : (
                                                    <button
                                                        onClick={handleSendOTP}
                                                        disabled={loading}
                                                        className="text-[10px] font-black text-[#8B7E66] hover:text-[#2D3A2D] uppercase tracking-widest"
                                                    >
                                                        Kirim Ulang OTP
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                    <button
                                        onClick={handleVerifyOTP}
                                        disabled={loading || otpCode.length !== 6}
                                        className="w-full py-5 bg-[#2D3A2D] hover:bg-[#1A241A] text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all shadow-xl disabled:opacity-50 flex items-center justify-center gap-2 active:scale-95"
                                    >
                                        {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <span>Verifikasi & Masuk</span>}
                                    </button>
                                </div>
                            )}
                        </div>
                    )}

                    <div className="mt-12 pt-8 border-t border-[#E5E1D8]/50 text-center">
                        <p className="text-sm text-gray-500">
                            Belum memiliki akun? {' '}
                            <LinkNext href="/auth/register" className="font-black text-[#8B7E66] hover:text-[#2D3A2D] transition-colors uppercase text-xs tracking-widest">
                                Daftar Sekarang
                            </LinkNext>
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
}

// Audit Page - Audit logs viewer with export functionality
// Filterable log table with CSV/PDF export

'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { LoadingSpinner, EmptyState } from '@/components/autonomous/ui/CoreComponents';

import { useSearchParams } from 'next/navigation';

export default function AuditPage() {
    const searchParams = useSearchParams();
    const brandId = searchParams.get('brandId') || '';
    const [dateRange, setDateRange] = useState<'7days' | '30days' | 'custom'>('7days');
    const [eventTypeFilter, setEventTypeFilter] = useState<string>('all');
    const [selectedLogId, setSelectedLogId] = useState<string | null>(null);

    // Fetch audit logs
    const { data, isLoading } = useQuery({
        queryKey: ['audit-logs', brandId, dateRange, eventTypeFilter],
        queryFn: async () => {
            const params = new URLSearchParams({
                brandId,
                dateRange,
                ...(eventTypeFilter !== 'all' && { eventType: eventTypeFilter })
            });
            const response = await fetch(`/api/autonomous-analytics/audit/logs?${params}`);
            return response.json();
        }
    });

    const handleExportCSV = async () => {
        const response = await fetch(`/api/autonomous-analytics/audit/export/csv?brandId=${brandId}&dateRange=${dateRange}`);
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `audit-logs-${brandId}-${new Date().toISOString()}.csv`;
        a.click();
    };

    const handleExportPDF = async () => {
        const response = await fetch(`/api/autonomous-analytics/audit/export/pdf?brandId=${brandId}&dateRange=${dateRange}`);
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `audit-logs-${brandId}-${new Date().toISOString()}.pdf`;
        a.click();
    };

    const logs = data?.logs || [];
    const selectedLog = logs.find((log: any) => log.id === selectedLogId);

    const eventTypes = [
        { value: 'all', label: 'All Events' },
        { value: 'execution', label: 'Executions' },
        { value: 'approval', label: 'Approvals' },
        { value: 'override', label: 'Overrides' },
        { value: 'rollback', label: 'Rollbacks' }
    ];

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Header */}
            <div className="bg-white shadow">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
                    <div className="flex justify-between items-center">
                        <div>
                            <h1 className="text-2xl font-bold text-gray-900">Audit Logs</h1>
                            <p className="text-sm text-gray-600 mt-1">
                                Complete audit trail of all autonomous actions
                            </p>
                        </div>
                        <div className="flex gap-2">
                            <button
                                onClick={handleExportCSV}
                                className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm font-medium"
                            >
                                Export CSV
                            </button>
                            <button
                                onClick={handleExportPDF}
                                className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 text-sm font-medium"
                            >
                                Export PDF
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {/* Filters */}
                <div className="bg-white rounded-lg shadow p-4 mb-6">
                    <div className="flex flex-wrap gap-4">
                        {/* Date Range Filter */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Date Range
                            </label>
                            <div className="flex gap-2">
                                {[
                                    { value: '7days', label: 'Last 7 Days' },
                                    { value: '30days', label: 'Last 30 Days' }
                                ].map(option => (
                                    <button
                                        key={option.value}
                                        onClick={() => setDateRange(option.value as any)}
                                        className={`px-3 py-1 rounded-md text-sm font-medium ${dateRange === option.value
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                            }`}
                                    >
                                        {option.label}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Event Type Filter */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Event Type
                            </label>
                            <select
                                value={eventTypeFilter}
                                onChange={(e) => setEventTypeFilter(e.target.value)}
                                className="px-3 py-1 border border-gray-300 rounded-md text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                            >
                                {eventTypes.map(type => (
                                    <option key={type.value} value={type.value}>
                                        {type.label}
                                    </option>
                                ))}
                            </select>
                        </div>
                    </div>
                </div>

                {/* Audit Logs Table */}
                <div className="bg-white rounded-lg shadow">
                    {isLoading ? (
                        <div className="p-6">
                            <LoadingSpinner />
                        </div>
                    ) : logs.length === 0 ? (
                        <div className="p-6">
                            <EmptyState
                                title="No audit logs found"
                                description="No logs match the selected filters"
                            />
                        </div>
                    ) : (
                        <div className="overflow-x-auto">
                            <table className="min-w-full divide-y divide-gray-200">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                                            Timestamp
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                                            Event Type
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                                            Performed By
                                        </th>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                                            Details
                                        </th>
                                        <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase">
                                            Actions
                                        </th>
                                    </tr>
                                </thead>
                                <tbody className="bg-white divide-y divide-gray-200">
                                    {logs.map((log: any) => (
                                        <tr key={log.id} className="hover:bg-gray-50">
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                                {new Date(log.timestamp).toLocaleString('id-ID')}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap">
                                                <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                                                    {log.eventType}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                                {log.performedBy}
                                            </td>
                                            <td className="px-6 py-4 text-sm text-gray-600">
                                                {log.summary || 'No details'}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-center text-sm">
                                                <button
                                                    onClick={() => setSelectedLogId(log.id)}
                                                    className="text-blue-600 hover:text-blue-900"
                                                >
                                                    View
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}
                </div>

                {/* Selected Log Details */}
                {selectedLog && (
                    <div className="mt-6 bg-white rounded-lg shadow p-6">
                        <div className="flex justify-between items-start mb-4">
                            <h3 className="text-lg font-semibold text-gray-900">Audit Entry Details</h3>
                            <button
                                onClick={() => setSelectedLogId(null)}
                                className="text-gray-400 hover:text-gray-600"
                            >
                                ✕
                            </button>
                        </div>

                        <div className="space-y-3">
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <div className="text-sm text-gray-600">Timestamp</div>
                                    <div className="text-sm font-medium text-gray-900">
                                        {new Date(selectedLog.timestamp).toLocaleString('id-ID')}
                                    </div>
                                </div>
                                <div>
                                    <div className="text-sm text-gray-600">Event Type</div>
                                    <div className="text-sm font-medium text-gray-900">
                                        {selectedLog.eventType}
                                    </div>
                                </div>
                                <div>
                                    <div className="text-sm text-gray-600">Performed By</div>
                                    <div className="text-sm font-medium text-gray-900">
                                        {selectedLog.performedBy}
                                    </div>
                                </div>
                                <div>
                                    <div className="text-sm text-gray-600">Brand ID</div>
                                    <div className="text-sm font-mono text-gray-900">
                                        {selectedLog.brandId}
                                    </div>
                                </div>
                            </div>

                            <div>
                                <div className="text-sm text-gray-600 mb-2">Metadata</div>
                                <pre className="bg-gray-900 text-green-400 p-4 rounded text-xs overflow-x-auto">
                                    {JSON.stringify(selectedLog.metadata, null, 2)}
                                </pre>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

// Budget Page - Budget consumption tracking and alerts
// Shows daily/weekly consumption and per-rule breakdown

'use client';

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { MetricCard, LoadingSpinner, ProgressBar } from '@/components/autonomous/ui/CoreComponents';

import { useSearchParams } from 'next/navigation';

export default function BudgetPage() {
    const searchParams = useSearchParams();
    const brandId = searchParams.get('brandId') || '';
    // Fetch daily budget
    const { data: dailyData, isLoading: loadingDaily } = useQuery({
        queryKey: ['budget', brandId, 'daily'],
        queryFn: () => fetch(`/api/autonomous-analytics/budget/consumption?brandId=${brandId}&period=daily`).then(r => r.json())
    });

    // Fetch weekly budget
    const { data: weeklyData, isLoading: loadingWeekly } = useQuery({
        queryKey: ['budget', brandId, 'weekly'],
        queryFn: () => fetch(`/api/autonomous-analytics/budget/consumption?brandId=${brandId}&period=weekly`).then(r => r.json())
    });

    // Fetch per-rule consumption
    const { data: perRuleData, isLoading: loadingPerRule } = useQuery({
        queryKey: ['budget', brandId, 'per-rule'],
        queryFn: () => fetch(`/api/autonomous-analytics/budget/per-rule?brandId=${brandId}`).then(r => r.json())
    });

    if (loadingDaily || loadingWeekly) {
        return (
            <div className="flex justify-center items-center h-screen">
                <LoadingSpinner size="lg" />
            </div>
        );
    }

    const daily = dailyData || {};
    const weekly = weeklyData || {};
    const perRule = perRuleData?.rules || [];

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Header */}
            <div className="bg-white shadow">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
                    <h1 className="text-2xl font-bold text-gray-900">Budget Consumption</h1>
                    <p className="text-sm text-gray-600 mt-1">
                        Track autonomous execution budget usage
                    </p>
                </div>
            </div>

            {/* Main Content */}
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {/* Budget Overview */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                    {/* Daily Budget */}
                    <div className="bg-white rounded-lg shadow p-6">
                        <h2 className="text-lg font-semibold text-gray-900 mb-4">Daily Budget</h2>

                        <div className="mb-6">
                            <div className="flex justify-between mb-2">
                                <span className="text-sm text-gray-600">Financial</span>
                                <span className="text-sm font-bold text-gray-900">
                                    Rp {(daily.financial_used / 1000000).toFixed(1)}jt / Rp {(daily.financial_limit / 1000000).toFixed(1)}jt
                                </span>
                            </div>
                            <ProgressBar
                                current={daily.financial_used || 0}
                                max={daily.financial_limit || 5000000}
                                showPercentage={true}
                            />
                        </div>

                        <div className="mb-6">
                            <div className="flex justify-between mb-2">
                                <span className="text-sm text-gray-600">Executions</span>
                                <span className="text-sm font-bold text-gray-900">
                                    {daily.executions_used} / {daily.executions_limit}
                                </span>
                            </div>
                            <ProgressBar
                                current={daily.executions_used || 0}
                                max={daily.executions_limit || 10}
                                showPercentage={true}
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-4 pt-4 border-t border-gray-200">
                            <div>
                                <div className="text-xs text-gray-600">Remaining</div>
                                <div className="text-lg font-bold text-gray-900">
                                    Rp {(daily.financial_remaining / 1000000).toFixed(1)}jt
                                </div>
                            </div>
                            <div>
                                <div className="text-xs text-gray-600">Utilization</div>
                                <div className="text-lg font-bold text-gray-900">
                                    {daily.utilization_percent?.toFixed(0)}%
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Weekly Budget */}
                    <div className="bg-white rounded-lg shadow p-6">
                        <h2 className="text-lg font-semibold text-gray-900 mb-4">Weekly Budget</h2>

                        <div className="mb-6">
                            <div className="flex justify-between mb-2">
                                <span className="text-sm text-gray-600">Financial</span>
                                <span className="text-sm font-bold text-gray-900">
                                    Rp {(weekly.financial_used / 1000000).toFixed(1)}jt / Rp {(weekly.financial_limit / 1000000).toFixed(1)}jt
                                </span>
                            </div>
                            <ProgressBar
                                current={weekly.financial_used || 0}
                                max={weekly.financial_limit || 20000000}
                                showPercentage={true}
                            />
                        </div>

                        <div className="mb-6">
                            <div className="flex justify-between mb-2">
                                <span className="text-sm text-gray-600">Executions</span>
                                <span className="text-sm font-bold text-gray-900">
                                    {weekly.executions_used} / {weekly.executions_limit}
                                </span>
                            </div>
                            <ProgressBar
                                current={weekly.executions_used || 0}
                                max={weekly.executions_limit || 50}
                                showPercentage={true}
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-4 pt-4 border-t border-gray-200">
                            <div>
                                <div className="text-xs text-gray-600">Remaining</div>
                                <div className="text-lg font-bold text-gray-900">
                                    Rp {(weekly.financial_remaining / 1000000).toFixed(1)}jt
                                </div>
                            </div>
                            <div>
                                <div className="text-xs text-gray-600">Utilization</div>
                                <div className="text-lg font-bold text-gray-900">
                                    {weekly.utilization_percent?.toFixed(0)}%
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Per-Rule Consumption */}
                <div className="bg-white rounded-lg shadow p-6 mb-8">
                    <h2 className="text-lg font-semibold text-gray-900 mb-4">Per-Rule Consumption (Daily)</h2>

                    {loadingPerRule ? (
                        <LoadingSpinner />
                    ) : (
                        <div className="overflow-x-auto">
                            <table className="min-w-full divide-y divide-gray-200">
                                <thead className="bg-gray-50">
                                    <tr>
                                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                                            Rule
                                        </th>
                                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                                            Used
                                        </th>
                                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                                            Limit
                                        </th>
                                        <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase">
                                            %
                                        </th>
                                    </tr>
                                </thead>
                                <tbody className="bg-white divide-y divide-gray-200">
                                    {perRule.map((rule: any) => (
                                        <tr key={rule.ruleId}>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                                {rule.ruleName}
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-right text-gray-900">
                                                Rp {(rule.used / 1000).toFixed(0)}k
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-right text-gray-600">
                                                Rp {(rule.limit / 1000).toFixed(0)}k
                                            </td>
                                            <td className="px-6 py-4 whitespace-nowrap text-sm text-right">
                                                <span className={`font-semibold ${rule.percentage >= 90 ? 'text-red-600' :
                                                    rule.percentage >= 70 ? 'text-yellow-600' :
                                                        'text-green-600'
                                                    }`}>
                                                    {rule.percentage.toFixed(0)}%
                                                </span>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    )}
                </div>

                {/* Budget Alerts */}
                {(daily.utilization_percent >= 70 || weekly.utilization_percent >= 70) && (
                    <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
                        <h3 className="text-sm font-semibold text-yellow-900 mb-2">⚠️ Budget Alerts</h3>
                        <ul className="space-y-1 text-sm text-yellow-800">
                            {daily.utilization_percent >= 90 && (
                                <li>• Daily budget 90%+ utilized - approaching limit</li>
                            )}
                            {daily.utilization_percent >= 70 && daily.utilization_percent < 90 && (
                                <li>• Daily budget 70%+ utilized</li>
                            )}
                            {weekly.utilization_percent >= 70 && (
                                <li>• Weekly budget 70%+ utilized</li>
                            )}
                        </ul>
                    </div>
                )}
            </div>
        </div>
    );
}

// Executions Page - Execution history and rollback management
// Timeline view with filters

'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { LoadingSpinner, EmptyState } from '@/components/autonomous/ui/CoreComponents';
import { ExecutionTimeline } from '@/components/autonomous/timelines/ExecutionTimeline';
import { ExecutionDetailsModal } from '@/components/autonomous/modals/ExecutionDetailsModal';

import { useSearchParams } from 'next/navigation';

export default function ExecutionsPage() {
    const searchParams = useSearchParams();
    const brandId = searchParams.get('brandId') || '';
    const [selectedExecutionId, setSelectedExecutionId] = useState<string | null>(null);
    const [dateRange, setDateRange] = useState<'today' | '7days' | '30days'>('7days');
    const [statusFilter, setStatusFilter] = useState<'all' | 'success' | 'rolled_back' | 'failed'>('all');

    // Fetch executions
    const { data, isLoading } = useQuery({
        queryKey: ['executions', brandId, dateRange, statusFilter],
        queryFn: async () => {
            const params = new URLSearchParams({
                brandId,
                dateRange,
                ...(statusFilter !== 'all' && { status: statusFilter })
            });
            const response = await fetch(`/api/autonomous-analytics/executions?${params}`);
            return response.json();
        },
        refetchInterval: 30000 // Refetch every 30 seconds
    });

    // Fetch selected execution details
    const { data: executionDetails } = useQuery({
        queryKey: ['execution-details', selectedExecutionId],
        queryFn: () => fetch(`/api/autonomous-analytics/executions/${selectedExecutionId}`).then(r => r.json()),
        enabled: !!selectedExecutionId
    });

    const executions = data?.executions || [];

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Header */}
            <div className="bg-white shadow">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
                    <h1 className="text-2xl font-bold text-gray-900">Execution History</h1>
                    <p className="text-sm text-gray-600 mt-1">
                        View and manage autonomous execution history
                    </p>
                </div>
            </div>

            {/* Main Content */}
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {/* Filters */}
                <div className="bg-white rounded-lg shadow p-4 mb-6">
                    <div className="flex flex-wrap gap-4">
                        {/* Date Range Filter */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Time Period
                            </label>
                            <div className="flex gap-2">
                                {[
                                    { value: 'today', label: 'Today' },
                                    { value: '7days', label: 'Last 7 Days' },
                                    { value: '30days', label: 'Last 30 Days' }
                                ].map(option => (
                                    <button
                                        key={option.value}
                                        onClick={() => setDateRange(option.value as any)}
                                        className={`px-3 py-1 rounded-md text-sm font-medium ${dateRange === option.value
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                            }`}
                                    >
                                        {option.label}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Status Filter */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Status
                            </label>
                            <div className="flex gap-2">
                                {[
                                    { value: 'all', label: 'All' },
                                    { value: 'success', label: 'Success' },
                                    { value: 'rolled_back', label: 'Rolled Back' },
                                    { value: 'failed', label: 'Failed' }
                                ].map(option => (
                                    <button
                                        key={option.value}
                                        onClick={() => setStatusFilter(option.value as any)}
                                        className={`px-3 py-1 rounded-md text-sm font-medium ${statusFilter === option.value
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                            }`}
                                    >
                                        {option.label}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Execution Timeline */}
                <div className="bg-white rounded-lg shadow p-6">
                    {isLoading ? (
                        <LoadingSpinner />
                    ) : executions.length === 0 ? (
                        <EmptyState
                            title="No executions found"
                            description="No executions match the selected filters"
                        />
                    ) : (
                        <ExecutionTimeline
                            executions={executions}
                            onSelectExecution={setSelectedExecutionId}
                        />
                    )}
                </div>
            </div>

            {/* Execution Details Modal */}
            {selectedExecutionId && executionDetails && (
                <ExecutionDetailsModal
                    execution={executionDetails}
                    onClose={() => setSelectedExecutionId(null)}
                />
            )}
        </div>
    );
}

