'use client';

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { useSearchParams } from 'next/navigation';
import { LoadingSpinner } from '@/components/autonomous/ui/CoreComponents';
import { AssistedFailureLab } from '@/components/autonomous/simulations/AssistedFailureLab';
import { GovernanceReadinessGate } from '@/components/autonomous/governance/GovernanceReadinessGate';

export default function GovernancePage() {
    const searchParams = useSearchParams();
    const brandId = searchParams.get('brandId') || '';

    // Fetch Assisted Action to simulate (just get the latest one for the lab)
    const { data: actionsData, isLoading: loadingActions } = useQuery({
        queryKey: ['assisted-actions', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/assisted-actions?brandId=${brandId}`).then(r => r.json())
    });

    // Fetch Readiness Gate Evaluation
    const { data: gateData, isLoading: loadingGate, refetch: refetchGate } = useQuery({
        queryKey: ['governance-gate', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/governance/readiness-gate?brandId=${brandId}`).then(r => r.json())
    });

    if (loadingActions || loadingGate) {
        return (
            <div className="flex justify-center items-center h-screen bg-gray-50">
                <LoadingSpinner size="lg" />
            </div>
        );
    }

    const latestAction = actionsData?.actions?.[0];

    return (
        <div className="min-h-screen bg-[#fafbfc] pb-20">
            {/* Governance Header */}
            <div className="bg-red-900 text-white border-b border-red-800">
                <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
                    <div className="flex items-center gap-4">
                        <div className="bg-white text-red-900 text-[10px] font-black px-2 py-0.5 rounded">PHASE 4.5</div>
                        <h1 className="text-sm font-black tracking-widest uppercase italic">Assisted Execution Readiness Lab</h1>
                    </div>
                </div>
            </div>

            <main className="max-w-7xl mx-auto px-6 py-10 space-y-12">
                {/* 1. The Readiness Gate (Final Verdict) */}
                <section>
                    <div className="flex items-center gap-4 mb-8">
                        <h2 className="text-sm font-black tracking-[0.3em] uppercase text-gray-400">Governance Clearance</h2>
                        <div className="h-px flex-grow bg-gray-100"></div>
                    </div>
                    <GovernanceReadinessGate response={gateData} />
                </section>

                {/* 2. Failure Simulation Lab */}
                <section>
                    <div className="flex justify-between items-center mb-8">
                        <div className="flex items-center gap-4">
                            <h2 className="text-sm font-black tracking-[0.3em] uppercase text-gray-400">Failure Stress-Testing</h2>
                            <div className="h-px w-32 bg-gray-100"></div>
                        </div>
                        <button
                            onClick={() => refetchGate()}
                            className="text-[10px] font-black text-blue-600 hover:text-blue-800 uppercase tracking-widest"
                        >
                            Refresh Metrics
                        </button>
                    </div>

                    {latestAction ? (
                        <AssistedFailureLab
                            brandId={brandId}
                            actionId={latestAction.id}
                        />
                    ) : (
                        <div className="bg-white border-2 border-dashed border-gray-100 rounded-3xl p-20 text-center">
                            <p className="text-sm font-bold text-gray-300 uppercase tracking-widest">
                                No Assisted Action Template Found for Simulation.
                            </p>
                            <p className="text-[10px] text-gray-400 mt-2">
                                Please promote a suggestion to "Staged Action" first.
                            </p>
                        </div>
                    )}
                </section>

                {/* Audit Disclaimer */}
                <div className="pt-10 border-t border-gray-100 text-center max-w-2xl mx-auto">
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest leading-loose">
                        "Readiness is proven by evidence, not intent."
                        This lab models human failure and verified rollback reliability.
                        No production execution is active. System is in Shadow-Simulation mode only.
                    </p>
                </div>
            </main>
        </div>
    );
}

// Main Navigation Layout - Dashboard navigation wrapper
// Provides consistent navigation across all autonomous pages

'use client';

import React from 'react';
import Link from 'next/link';
import { usePathname, useSearchParams } from 'next/navigation';
import { useQuery } from '@tanstack/react-query';
import { getAutonomousBrandAction } from '@/lib/actions/rasa-ibu/businessIntelligence';

interface AutonomousLayoutProps {
    children: React.ReactNode;
}

export default function AutonomousLayout({ children }: AutonomousLayoutProps) {
    const pathname = usePathname();
    const searchParams = useSearchParams();
    const brandId = searchParams.get('brandId') || '';

    // Fetch Brand Info
    const { data: brandRes } = useQuery({
        queryKey: ['brand-info', brandId],
        queryFn: () => getAutonomousBrandAction(brandId),
        enabled: !!brandId
    });

    const brandName = (brandRes as any)?.data?.name || (brandId === 'test_brand_001' ? 'TEST BRAND' : brandId);

    const navItems = [
        { href: '/autonomous/overview', label: 'Overview', icon: '📊' },
        { href: '/autonomous/rules', label: 'Rules', icon: '📋' },
        { href: '/autonomous/executions', label: 'Executions', icon: '⚡' },
        { href: '/autonomous/approvals', label: 'Approvals', icon: '✓' },
        { href: '/autonomous/trust', label: 'Trust', icon: '🎯' },
        { href: '/autonomous/budget', label: 'Budget', icon: '💰' },
        { href: '/autonomous/audit', label: 'Audit', icon: '📝' },
        { href: '/autonomous/settings', label: 'Settings', icon: '⚙️' }
    ];

    const isActive = (href: string) => pathname?.startsWith(href);

    return (
        <>
            {/* Global Safety Banner */}
            <div className="bg-emerald-500 text-white py-2 px-4 shadow-inner text-center">
                <div className="max-w-7xl mx-auto flex items-center justify-center gap-4">
                    <span className="text-sm font-black tracking-tighter uppercase whitespace-nowrap flex items-center gap-2">
                        <span className="flex h-2 w-2 rounded-full bg-white animate-pulse"></span>
                        SYSTEM STATUS: ACTIVE. EXECUTION ENABLED.
                    </span>
                    <span className="hidden md:inline-block h-4 w-px bg-white opacity-20"></span>
                    <p className="hidden md:block text-[10px] font-bold uppercase tracking-widest opacity-80">
                        CFO INTERLOCK VERIFIED • DETERMINISTIC AUDIT ACTIVE • ALL MUTATIONS PERMITTED
                    </p>
                </div>
            </div>

            {/* Top Navigation */}
            <nav className="bg-white shadow-sm border-b border-gray-200">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <div className="flex items-center justify-between h-16">
                        <div className="flex items-center space-x-8">
                            <h1 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                                <span className="bg-blue-600 text-white p-1 rounded font-black text-xs">A</span>
                                ACHIERA Autonomous
                            </h1>

                            <div className="hidden md:flex space-x-1">
                                {navItems.map((item) => (
                                    <Link
                                        key={item.href}
                                        href={`${item.href}?brandId=${brandId}`}
                                        className={`px-3 py-2 rounded-md text-sm font-medium transition-colors ${isActive(item.href)
                                            ? 'bg-blue-600 text-white'
                                            : 'text-gray-500 hover:bg-gray-100 hover:text-gray-900'
                                            }`}
                                    >
                                        <span className="mr-1">{item.icon}</span>
                                        {item.label}
                                    </Link>
                                ))}
                            </div>
                        </div>

                        <div className="flex items-center space-x-4">
                            <div className="bg-gray-100 border border-gray-200 rounded-full px-4 py-1.5 flex items-center gap-2">
                                <span className="flex h-2 w-2 rounded-full bg-green-500 animate-pulse"></span>
                                <span className="text-xs text-gray-600 font-bold uppercase truncate max-w-[150px]">BRAND: {brandName || 'UNSELECTED'}</span>
                            </div>
                        </div>
                    </div>
                </div>
            </nav>

            {/* Mobile Navigation */}
            <div className="md:hidden bg-white border-b border-gray-200">
                <div className="px-4 py-2 overflow-x-auto">
                    <div className="flex space-x-2">
                        {navItems.map((item) => (
                            <Link
                                key={item.href}
                                href={`${item.href}?brandId=${brandId}`}
                                className={`px-3 py-1.5 rounded-md text-xs font-medium whitespace-nowrap ${isActive(item.href)
                                    ? 'bg-blue-600 text-white'
                                    : 'text-gray-500 hover:bg-gray-100'
                                    }`}
                            >
                                {item.icon} {item.label}
                            </Link>
                        ))}
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {brandId ? children : (
                    <div className="bg-white rounded-xl shadow p-12 text-center">
                        <h2 className="text-2xl font-bold text-gray-800 mb-4">No Brand ID Provided</h2>
                        <p className="text-gray-500 max-w-sm mx-auto">Please select a valid brand from the main account menu to access its Autonomous Analytics cockpit.</p>
                    </div>
                )}
            </main>
        </>
    );
}

// Overview Page - Executive Dashboard
// Main landing page for autonomous analytics

'use client';

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { MetricCard, LoadingSpinner } from '@/components/autonomous/ui/CoreComponents';
import { AutonomyLevelIndicator } from '@/components/autonomous/controls/AutonomyLevelIndicator';
import { SimulationPanel } from '@/components/autonomous/panels/SimulationPanel';
import { DecisionAuditTable } from '@/components/autonomous/tables/DecisionAuditTable';
import { SuggestionInbox } from '@/components/autonomous/suggestions/SuggestionInbox';
import { SuggestionQualityDashboard } from '@/components/autonomous/suggestions/SuggestionQualityDashboard';
import { SuggestionNoisePanel } from '@/components/autonomous/suggestions/SuggestionNoisePanel';
import { ConsistencyWarningCard } from '@/components/autonomous/suggestions/ConsistencyWarningCard';
import { ActionStagingArea } from '@/components/autonomous/actions/ActionStagingArea';
import { useSearchParams } from 'next/navigation';
import { getAutonomousBrandAction } from '@/lib/actions/rasa-ibu/businessIntelligence';

export default function OverviewPage() {
    const searchParams = useSearchParams();
    const brandId = searchParams.get('brandId') || '';

    // Fetch Brand Info
    const { data: brandRes } = useQuery({
        queryKey: ['brand-info', brandId],
        queryFn: () => getAutonomousBrandAction(brandId),
        enabled: !!brandId
    });

    const brandName = (brandRes as any)?.data?.name || (brandId === 'test_brand_001' ? 'Frozen Harvest Co.' : brandId);
    const brandPilot = brandId === 'rasa-ibu' ? 'Pilot: Authentic Indonesian Cuisine' : 'Pilot: Digital Operations';

    // Fetch trust metrics
    const { data: trustMetrics, isLoading: loadingTrust } = useQuery({
        queryKey: ['trust-metrics', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/trust/metrics?brandId=${brandId}`).then(r => r.json())
    });

    // Fetch budget consumption
    const { data: budgetData, isLoading: loadingBudget } = useQuery({
        queryKey: ['budget', brandId, 'daily'],
        queryFn: () => fetch(`/api/autonomous-analytics/budget/consumption?brandId=${brandId}&period=daily`).then(r => r.json())
    });

    // Fetch active rules count
    const { data: rulesData, isLoading: loadingRules } = useQuery({
        queryKey: ['rules', brandId, 'summary'],
        queryFn: () => fetch(`/api/autonomous-analytics/rules/summary?brandId=${brandId}`).then(r => r.json())
    });

    // Fetch recent executions/history
    const { data: historyData, isLoading: loadingHistory, refetch: refetchHistory } = useQuery({
        queryKey: ['executions', brandId, 'recent'],
        queryFn: () => fetch(`/api/autonomous-analytics/executions/recent?brandId=${brandId}`).then(r => r.json())
    });

    // Fetch Suggestion Quality Audit (Phase 3.5)
    const { data: qualityData, isLoading: loadingQuality } = useQuery({
        queryKey: ['suggestion-quality', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/suggestions/quality-audit?brandId=${brandId}`).then(r => r.json())
    });

    // Fetch Assisted Actions (Phase 4.0)
    const { data: actionsData, isLoading: loadingActions, refetch: refetchActions } = useQuery({
        queryKey: ['assisted-actions', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/assisted-actions?brandId=${brandId}`).then(r => r.json())
    });

    if (loadingTrust || loadingRules || loadingHistory || loadingQuality || loadingActions) {
        return (
            <div className="flex justify-center items-center h-64">
                <LoadingSpinner size="lg" />
            </div>
        );
    }

    // Spec-specific KPI Mapping
    const ruleAcceptance = trustMetrics?.rule_acceptance_rate * 100 || 0;
    const aiAgreement = trustMetrics?.ai_agreement_rate * 100 || 0;
    const rollbackRate = trustMetrics?.rollback_frequency * 100 || 0;

    const currentAutonomyLevel = rulesData?.byLevel?.reduce((prev: any, curr: any) =>
        curr.count > 0 ? Math.max(prev, curr.level) : prev, 0) || 0;

    return (
        <div className="space-y-8">
            {/* 1B. Brand Status Header */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-black text-gray-800 tracking-tight">{brandName}</h2>
                    <div className="flex items-center gap-3 mt-1">
                        <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{brandPilot}</span>
                        <span className="h-1 w-1 rounded-full bg-gray-300"></span>
                        <span className="text-xs text-gray-400">Active Rule Set: <span className="text-blue-600 font-mono">Inventory-Ops v1.2</span></span>
                    </div>
                </div>

                <div className="text-right">
                    <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Last Data Ingest</div>
                    <div className="text-sm font-bold text-gray-700">2025-12-18 20:00:00 <span className="text-green-500 ml-1">(Synced)</span></div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* 1C. Autonomy Level Indicator */}
                <div className="lg:col-span-2">
                    <AutonomyLevelIndicator currentLevel={currentAutonomyLevel} />
                </div>

                {/* 1D. Trust Metrics Overview */}
                <div className="space-y-4">
                    <MetricCard
                        title="Rule Acceptance"
                        value={ruleAcceptance}
                        suffix="%"
                        status={ruleAcceptance >= 90 ? 'good' : 'warning'}
                    />
                    <MetricCard
                        title="AI Agreement"
                        value={aiAgreement}
                        suffix="%"
                        status={aiAgreement >= 85 ? 'good' : 'warning'}
                    />
                    <MetricCard
                        title="Rollback Rate"
                        value={rollbackRate}
                        suffix="%"
                        status={rollbackRate <= 2 ? 'good' : 'danger'}
                    />
                </div>
            </div>

            {/* Phase 4.0: Human-Assisted Operations (Staging Area) */}
            <div>
                <ActionStagingArea
                    brandId={brandId}
                    actions={actionsData?.actions || []}
                    onRefresh={() => {
                        refetchActions();
                        refetchHistory();
                    }}
                />
            </div>

            {/* 1E. Suggest Mode Inbox (Advisory Layer) */}
            <div className="mb-10 space-y-8">
                <div className="flex items-center gap-4">
                    <h2 className="text-lg font-black tracking-widest uppercase text-gray-800">Autonomous Operation Center</h2>
                    <div className="h-px flex-grow bg-gray-100"></div>
                    <span className="text-[9px] text-emerald-600 font-bold uppercase tracking-widest bg-emerald-50 px-2 py-1 rounded">Execution Layer Active</span>
                </div>

                {/* Phase 3.5: Quality Audit Dashboard */}
                <SuggestionQualityDashboard report={qualityData} />

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                    <SuggestionNoisePanel alerts={qualityData?.noiseAlerts || []} />
                    <ConsistencyWarningCard warnings={qualityData?.consistencyWarnings || []} />
                </div>

                <SuggestionInbox brandId={brandId} onActionPromoted={refetchActions} />
            </div>

            {/* 3. Simulation Center */}
            <SimulationPanel brandId={brandId} />

            {/* 2. Decision History & Audit Table */}
            <div className="space-y-4">
                <div className="flex justify-between items-end">
                    <div>
                        <h3 className="text-lg font-bold text-gray-800">Decision History & Audit Trail</h3>
                        <p className="text-sm text-gray-500">Immutable log of system evaluations and triggered rules.</p>
                    </div>
                    <div className="flex gap-2">
                        <span className="px-3 py-1 bg-emerald-100 rounded text-[10px] font-bold text-emerald-600 uppercase cursor-help" title="Verified by deterministic controller">Audit Verified</span>
                    </div>
                </div>

                <DecisionAuditTable
                    brandId={brandId}
                    data={historyData?.executions || []}
                    loading={loadingHistory}
                />
            </div>
        </div>
    );
}

// Rules Page - Rule management and performance tracking
// Sortable table with expandable details

'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { StatusBadge, LoadingSpinner, EmptyState } from '@/components/autonomous/ui/CoreComponents';
import { RulesTable } from '@/components/autonomous/tables/RulesTable';
import { RuleDetailsPanel } from '@/components/autonomous/panels/RuleDetailsPanel';

import { useSearchParams } from 'next/navigation';

export default function RulesPage() {
    const searchParams = useSearchParams();
    const brandId = searchParams.get('brandId') || '';
    const [selectedRuleId, setSelectedRuleId] = useState<string | null>(null);
    const [levelFilter, setLevelFilter] = useState<number | 'all'>('all');
    const [statusFilter, setStatusFilter] = useState<string | 'all'>('all');

    // Fetch all rules
    const { data: rulesData, isLoading } = useQuery({
        queryKey: ['rules', brandId, levelFilter, statusFilter],
        queryFn: async () => {
            const params = new URLSearchParams({
                brandId,
                ...(levelFilter !== 'all' && { level: levelFilter.toString() }),
                ...(statusFilter !== 'all' && { status: statusFilter })
            });
            const response = await fetch(`/api/autonomous-analytics/rules?${params}`);
            return response.json();
        }
    });

    // Fetch selected rule details
    const { data: ruleDetails } = useQuery({
        queryKey: ['rule-details', selectedRuleId],
        queryFn: () => fetch(`/api/autonomous-analytics/rules/${selectedRuleId}`).then(r => r.json()),
        enabled: !!selectedRuleId
    });

    if (isLoading) {
        return (
            <div className="flex justify-center items-center h-screen">
                <LoadingSpinner size="lg" />
            </div>
        );
    }

    const rules = rulesData?.rules || [];

    return (
        <div className="min-h-screen bg-gray-50">
            {/* Header */}
            <div className="bg-white shadow">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
                    <h1 className="text-2xl font-bold text-gray-900">Rules Management</h1>
                    <p className="text-sm text-gray-600 mt-1">
                        Manage autonomous decision rules and track performance
                    </p>
                </div>
            </div>

            {/* Main Content */}
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                {/* Filters */}
                <div className="bg-white rounded-lg shadow p-4 mb-6">
                    <div className="flex flex-wrap gap-4">
                        {/* Level Filter */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Autonomy Level
                            </label>
                            <div className="flex gap-2">
                                <button
                                    onClick={() => setLevelFilter('all')}
                                    className={`px-3 py-1 rounded-md text-sm font-medium ${levelFilter === 'all'
                                        ? 'bg-blue-600 text-white'
                                        : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                        }`}
                                >
                                    All
                                </button>
                                {[0, 1, 2, 3].map(level => (
                                    <button
                                        key={level}
                                        onClick={() => setLevelFilter(level)}
                                        className={`px-3 py-1 rounded-md text-sm font-medium ${levelFilter === level
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                            }`}
                                    >
                                        L{level}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Status Filter */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Status
                            </label>
                            <div className="flex gap-2">
                                {['all', 'OK', 'REVIEW', 'PAUSE'].map(status => (
                                    <button
                                        key={status}
                                        onClick={() => setStatusFilter(status)}
                                        className={`px-3 py-1 rounded-md text-sm font-medium ${statusFilter === status
                                            ? 'bg-blue-600 text-white'
                                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                                            }`}
                                    >
                                        {status === 'all' ? 'All' : status}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Rules Table */}
                <div className="bg-white rounded-lg shadow mb-6">
                    {rules.length === 0 ? (
                        <div className="p-6">
                            <EmptyState
                                title="No rules found"
                                description="No rules match the selected filters"
                            />
                        </div>
                    ) : (
                        <RulesTable
                            rules={rules}
                            selectedRuleId={selectedRuleId}
                            onSelectRule={setSelectedRuleId}
                        />
                    )}
                </div>

                {/* Rule Details Panel */}
                {selectedRuleId && ruleDetails && (
                    <RuleDetailsPanel
                        rule={ruleDetails}
                        onClose={() => setSelectedRuleId(null)}
                    />
                )}
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { LoadingSpinner } from '@/components/autonomous/ui/CoreComponents';
import { AutonomyReadinessGauge } from '@/components/autonomous/trust/AutonomyReadinessGauge';
import { RiskConcentrationHeatmap } from '@/components/autonomous/trust/RiskConcentrationHeatmap';
import { PromotionEligibilityGate } from '@/components/autonomous/trust/PromotionEligibilityGate';
import { TrustTrendGrid } from '@/components/autonomous/trust/TrustTrendGrid';
import { useSearchParams } from 'next/navigation';
import { HumanReadinessSummary } from '@/components/autonomous/trust/HumanReadinessSummary';
import { TrustGapRadar } from '@/components/autonomous/trust/TrustGapRadar';
import { DisagreementHeatmap } from '@/components/autonomous/trust/DisagreementHeatmap';
import { TrustVerdictPanel } from '@/components/autonomous/trust/TrustVerdictPanel';
import { ExecutiveConfidenceDashboard } from '@/components/autonomous/trust/ExecutiveConfidenceDashboard';
import { GovernanceSignOffPanel } from '@/components/autonomous/trust/GovernanceSignOffPanel';

export default function TrustPage() {
    const searchParams = useSearchParams();
    const brandId = searchParams.get('brandId') || '';

    // Fetch Verdict (FINAL GATE)
    const { data: verdictData, isLoading: loadingVerdict } = useQuery({
        queryKey: ['trust-verdict', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/trust/verdict?brandId=${brandId}`).then(r => r.json())
    });

    // Fetch Readiness and Trends
    const { data: readinessData, isLoading: loadingReadiness } = useQuery({
        queryKey: ['trust-readiness', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/trust/readiness?brandId=${brandId}`).then(r => r.json())
    });

    // Fetch Risk Clusters
    const { data: clusterData, isLoading: loadingClusters } = useQuery({
        queryKey: ['risk-clusters', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/trust/risk-clusters?brandId=${brandId}`).then(r => r.json())
    });

    // Fetch Calibration Report
    const { data: calibrationData, isLoading: loadingCalibration } = useQuery({
        queryKey: ['calibration-report', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/trust/calibration?brandId=${brandId}`).then(r => r.json())
    });

    // Fetch Executive Confidence Report (Phase 3.75)
    const { data: confidenceData, isLoading: loadingConfidence, refetch: refetchConfidence } = useQuery({
        queryKey: ['executive-confidence', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/trust/confidence?brandId=${brandId}`).then(r => r.json())
    });

    // Temporal snapshots for the grid
    const { data: snapshot7d } = useQuery({
        queryKey: ['snapshot-7d', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/trust/readiness?brandId=${brandId}&period=7d`).then(r => r.json()),
        enabled: !!brandId
    });

    const { data: snapshot14d } = useQuery({
        queryKey: ['snapshot-14d', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/trust/readiness?brandId=${brandId}&period=14d`).then(r => r.json()),
        enabled: !!brandId
    });

    if (loadingReadiness || loadingClusters || loadingCalibration || loadingVerdict || loadingConfidence) {
        return (
            <div className="flex justify-center items-center h-screen bg-gray-50">
                <LoadingSpinner size="lg" />
            </div>
        );
    }

    const { readiness, snapshot: snapshot30d } = readinessData || {};
    const { clusters } = clusterData || {};
    const { report, summary: calibrationSummary } = calibrationData || {};

    const eligibilityItems = [
        {
            label: "30-Day Trust Stability",
            passed: readiness?.score > 60,
            description: "Requires consistent trust scores above 60 for 30 consecutive days."
        },
        {
            label: "Rollback Threshold (< 2%)",
            passed: snapshot30d?.rollback_rate < 0.02,
            description: "Systemic stability check. Any rollback spike > 2% blocks promotion."
        },
        {
            label: "Confidence Floor (≥ 0.85)",
            passed: snapshot30d?.avg_confidence >= 0.85,
            description: "Minimum mean model confidence required for Level 1 proposal."
        },
        {
            label: "CFO Safety Override",
            passed: confidenceData?.aggregated_score >= 85,
            description: "Phase 3.75 Executive Confidence must be >= 85% for promotion eligibility."
        }
    ];

    return (
        <div className="min-h-screen bg-[#fafbfc] pb-20">
            {/* Global Audit Header */}
            <div className="bg-gray-900 text-white border-b border-gray-800">
                <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
                    <div className="flex items-center gap-4">
                        <div className="bg-orange-500 text-black text-[10px] font-black px-2 py-0.5 rounded">OBSERVE MODE</div>
                        <h1 className="text-sm font-black tracking-widest uppercase">CFO & Board Trust Hardening Panel</h1>
                    </div>
                    <div className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">
                        Last Audit: {new Date().toLocaleDateString()}
                    </div>
                </div>
            </div>

            <main className="max-w-7xl mx-auto px-6 py-8">
                {/* FINAL GOVERNANCE GATE (Phase 2.9) */}
                <div className="mb-10">
                    <TrustVerdictPanel verdict={verdictData} />
                </div>

                {/* Executive Summary Row */}
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-10">
                    <div className="lg:col-span-1">
                        <AutonomyReadinessGauge
                            score={readiness?.score || 0}
                            status={readiness?.status || 'NOT_READY'}
                            blockingFactors={readiness?.blocking_factors || []}
                        />
                    </div>
                    <div className="lg:col-span-2">
                        <TrustTrendGrid
                            data7d={snapshot7d?.snapshot}
                            data14d={snapshot14d?.snapshot}
                            data30d={snapshot30d}
                        />
                    </div>
                </div>

                {/* Human Trust Calibration Dashboard (NEW) */}
                <div className="mb-10">
                    <div className="flex items-center gap-4 mb-6">
                        <h2 className="text-lg font-black tracking-widest uppercase text-gray-800">Human Trust Calibration</h2>
                        <div className="h-px flex-grow bg-gray-100"></div>
                        <span className="text-[9px] text-blue-600 font-bold uppercase tracking-widest bg-blue-50 px-2 py-1 rounded">Subjective Alignment Audit</span>
                    </div>

                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                        <HumanReadinessSummary
                            alignment={calibrationSummary?.trust_alignment || 'LOW'}
                            concerns={calibrationSummary?.primary_concerns || []}
                            recommendation={calibrationSummary?.recommendation || 'CONTINUE OBSERVE'}
                        />
                        <TrustGapRadar
                            systemConfidence={report?.system_confidence_avg || 0}
                            humanAgreement={report?.human_agreement_rate || 0}
                        />
                        <DisagreementHeatmap clusters={report?.disagreement_clusters_full || []} />
                    </div>
                </div>

                {/* Executive Confidence Dashboard (Phase 3.75) */}
                <div className="mb-10 grid grid-cols-1 lg:grid-cols-3 gap-8">
                    <div className="lg:col-span-2">
                        <ExecutiveConfidenceDashboard
                            score={confidenceData?.aggregated_score || 0}
                            dimensions={confidenceData?.dimensions || { operational: 0, risk: 0, explainability: 0, psychological: 0 }}
                            status={confidenceData?.status || 'PENDING'}
                        />
                    </div>
                    <div className="lg:col-span-1">
                        <GovernanceSignOffPanel
                            brandId={brandId}
                            onSignOff={refetchConfidence}
                        />
                    </div>
                </div>

                {/* Risk & Eligibility Section */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-10">
                    <RiskConcentrationHeatmap clusters={clusters || []} />
                    <div className="bg-white rounded-xl shadow-lg p-6 border border-gray-100">
                        <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest mb-4">Risk Architecture Advisory</h3>
                        <div className="space-y-4">
                            <div className="p-4 bg-gray-50 rounded-lg border-l-4 border-gray-300">
                                <p className="text-xs text-gray-600 italic">
                                    "The Current readiness score of {readiness?.score.toFixed(0)} reflects a deterministic evaluation of {readiness?.status === 'READY_FOR_REVIEW' ? 'high' : 'low-to-moderate'} structural trust.
                                    {readiness?.blocking_factors.length > 0 ? ' Specific blocking factors must be addressed before suggesting any autonomy escalation.' : ' While metrics are stable, final sign-off is retained by the Risk Architect.'}"
                                </p>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="p-3 bg-blue-50 bg-opacity-30 rounded border border-blue-100">
                                    <span className="text-[9px] font-black text-blue-500 uppercase">Data Sparsity Rank</span>
                                    <p className="text-sm font-bold text-gray-700">OPTIMAL (98th)</p>
                                </div>
                                <div className="p-3 bg-orange-50 bg-opacity-30 rounded border border-orange-100">
                                    <span className="text-[9px] font-black text-orange-500 uppercase">Volitility Index</span>
                                    <p className="text-sm font-bold text-gray-700">MODERATE</p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Promotion Readiness Gate (Crucial Safety Element) */}
                <div className="mt-12">
                    <PromotionEligibilityGate
                        items={eligibilityItems}
                        globalStatus={readiness?.status === 'READY_FOR_REVIEW' ? 'PENDING_REVIEW' : 'LOCKED'}
                    />
                </div>

                {/* Audit Disclaimer */}
                <div className="mt-16 pt-8 border-t border-gray-200 text-center max-w-2xl mx-auto">
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest leading-loose">
                        This report is a read-only artifact of the Autonomous Safety Interlock system.
                        Escalation to Autonomy Level 1 (Suggest Mode) requires a formal motion by the board.
                        No autonomous writes or mutations are active.
                        System is strictly operating on Observe Mode protocol.
                    </p>
                </div>
            </main>
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { BarChart3, TrendingUp, MousePointer, Eye, Sparkles, Users, ExternalLink } from 'lucide-react';
import AnalyticsChart from '@/components/analytics/AnalyticsChart';
import ConversionFunnel from '@/components/analytics/ConversionFunnel';
import DateRangePicker from '@/components/analytics/DateRangePicker';
import ExportButton from '@/components/analytics/ExportButton';

interface AnalyticsData {
    stats: {
        totalPageViews: number;
        totalCollectionClicks: number;
        totalMockupOpens: number;
        totalMockupConfirms: number;
        totalHeroCtaClicks: number;
    };
    conversionRates: {
        viewToClick: number;
        clickToMockup: number;
        mockupToConfirm: number;
        overallConversion: number;
    };
    topCollections: { slug: string; count: number }[];
    topPages: { path: string; count: number }[];
    dailyStats: any[];
    sessionAnalytics: {
        uniqueSessions: number;
        avgEventsPerSession: number;
    };
    topReferrers: { referrer: string; count: number }[];
}

export default function AnalyticsPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const { brandSlug } = use(params);
    const [data, setData] = useState<AnalyticsData | null>(null);
    const [loading, setLoading] = useState(true);
    const [startDate, setStartDate] = useState(() => {
        const date = new Date();
        date.setDate(date.getDate() - 7);
        return date;
    });
    const [endDate, setEndDate] = useState(new Date());

    useEffect(() => {
        fetchAnalytics();
    }, [brandSlug, startDate, endDate]);

    const fetchAnalytics = async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({
                startDate: startDate.toISOString(),
                endDate: endDate.toISOString(),
            });
            const res = await fetch(`/api/admin/${brandSlug}/analytics?${params}`);
            const analyticsData = await res.json();
            setData(analyticsData);
        } catch (error) {
            console.error('Failed to fetch analytics:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleDateChange = (start: Date, end: Date) => {
        setStartDate(start);
        setEndDate(end);
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <div className="text-stone-600">Loading analytics...</div>
            </div>
        );
    }

    if (!data) {
        return (
            <div className="flex items-center justify-center h-full">
                <div className="text-stone-600">Failed to load analytics</div>
            </div>
        );
    }

    // Provide default values if data is missing
    const stats = data?.stats || {
        totalPageViews: 0,
        totalCollectionClicks: 0,
        totalMockupOpens: 0,
        totalMockupConfirms: 0,
        totalHeroCtaClicks: 0,
    };

    const dailyStats = data?.dailyStats || [];
    const conversionRates = data?.conversionRates || {
        viewToClick: 0,
        clickToMockup: 0,
        mockupToConfirm: 0,
        overallConversion: 0,
    };
    const topCollections = data?.topCollections || [];
    const topPages = data?.topPages || [];
    const sessionAnalytics = data?.sessionAnalytics || {
        uniqueSessions: 0,
        avgEventsPerSession: 0,
    };
    const topReferrers = data?.topReferrers || [];

    const funnelSteps = [
        { name: 'Page Views', value: stats.totalPageViews, color: '#3b82f6' },
        { name: 'Collection Clicks', value: stats.totalCollectionClicks, color: '#10b981' },
        { name: 'Mockup Opens', value: stats.totalMockupOpens, color: '#a855f7' },
        { name: 'Mockup Confirms', value: stats.totalMockupConfirms, color: '#f59e0b' },
    ];

    const trendChartData = dailyStats.map((day: any) => ({
        date: new Date(day.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
        'Page Views': day.pageViews,
        'Collection Clicks': day.collectionClicks,
        'Mockup Opens': day.mockupOpens,
        'Mockup Confirms': day.mockupConfirms,
    }));

    const chartDataKeys = [
        { key: 'Page Views', name: 'Page Views', color: '#3b82f6' },
        { key: 'Collection Clicks', name: 'Collection Clicks', color: '#10b981' },
        { key: 'Mockup Opens', name: 'Mockup Opens', color: '#a855f7' },
        { key: 'Mockup Confirms', name: 'Mockup Confirms', color: '#f59e0b' },
    ];


    return (
        <div className="p-8 space-y-8">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Analytics</h1>
                    <p className="text-stone-600">Track user engagement and behavior</p>
                </div>
                <div className="flex items-center gap-3">
                    <DateRangePicker
                        startDate={startDate}
                        endDate={endDate}
                        onDateChange={handleDateChange}
                    />
                    <ExportButton
                        brandSlug={brandSlug}
                        startDate={startDate}
                        endDate={endDate}
                    />
                </div>
            </div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6">
                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="w-12 h-12 rounded-lg bg-blue-100 flex items-center justify-center">
                            <Eye className="w-6 h-6 text-blue-600" />
                        </div>
                    </div>
                    <div className="text-3xl font-bold text-stone-900 mb-1">
                        {stats.totalPageViews.toLocaleString()}
                    </div>
                    <div className="text-sm text-stone-600">Page Views</div>
                </div>

                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="w-12 h-12 rounded-lg bg-green-100 flex items-center justify-center">
                            <MousePointer className="w-6 h-6 text-green-600" />
                        </div>
                    </div>
                    <div className="text-3xl font-bold text-stone-900 mb-1">
                        {stats.totalCollectionClicks.toLocaleString()}
                    </div>
                    <div className="text-sm text-stone-600">Collection Clicks</div>
                </div>

                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="w-12 h-12 rounded-lg bg-purple-100 flex items-center justify-center">
                            <Sparkles className="w-6 h-6 text-purple-600" />
                        </div>
                    </div>
                    <div className="text-3xl font-bold text-stone-900 mb-1">
                        {stats.totalMockupOpens.toLocaleString()}
                    </div>
                    <div className="text-sm text-stone-600">Mockup Opens</div>
                </div>

                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="w-12 h-12 rounded-lg bg-amber-100 flex items-center justify-center">
                            <TrendingUp className="w-6 h-6 text-amber-600" />
                        </div>
                    </div>
                    <div className="text-3xl font-bold text-stone-900 mb-1">
                        {stats.totalMockupConfirms.toLocaleString()}
                    </div>
                    <div className="text-sm text-stone-600">Mockup Confirms</div>
                </div>

                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <div className="flex items-center justify-between mb-4">
                        <div className="w-12 h-12 rounded-lg bg-red-100 flex items-center justify-center">
                            <BarChart3 className="w-6 h-6 text-red-600" />
                        </div>
                    </div>
                    <div className="text-3xl font-bold text-stone-900 mb-1">
                        {stats.totalHeroCtaClicks.toLocaleString()}
                    </div>
                    <div className="text-sm text-stone-600">Hero CTA Clicks</div>
                </div>
            </div>

            {/* Trend Chart */}
            <div className="bg-white rounded-xl border border-stone-200 p-6">
                <h2 className="text-lg font-bold text-stone-900 mb-6">Activity Trends</h2>
                <AnalyticsChart
                    data={trendChartData}
                    type="line"
                    dataKeys={chartDataKeys}
                    height={350}
                />
            </div>

            {/* Conversion Funnel & Session Analytics */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <h2 className="text-lg font-bold text-stone-900 mb-6">Conversion Funnel</h2>
                    <ConversionFunnel steps={funnelSteps} />
                    <div className="mt-6 grid grid-cols-2 gap-4">
                        <div className="bg-stone-50 rounded-lg p-4">
                            <div className="text-sm text-stone-600 mb-1">View → Click</div>
                            <div className="text-2xl font-bold text-stone-900">
                                {conversionRates.viewToClick.toFixed(1)}%
                            </div>
                        </div>
                        <div className="bg-stone-50 rounded-lg p-4">
                            <div className="text-sm text-stone-600 mb-1">Overall</div>
                            <div className="text-2xl font-bold text-stone-900">
                                {conversionRates.overallConversion.toFixed(1)}%
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <h2 className="text-lg font-bold text-stone-900 mb-6">Session Analytics</h2>
                    <div className="space-y-4">
                        <div className="flex items-center gap-4">
                            <div className="w-12 h-12 rounded-lg bg-indigo-100 flex items-center justify-center">
                                <Users className="w-6 h-6 text-indigo-600" />
                            </div>
                            <div>
                                <div className="text-2xl font-bold text-stone-900">
                                    {sessionAnalytics.uniqueSessions.toLocaleString()}
                                </div>
                                <div className="text-sm text-stone-600">Unique Sessions</div>
                            </div>
                        </div>
                        <div className="flex items-center gap-4">
                            <div className="w-12 h-12 rounded-lg bg-cyan-100 flex items-center justify-center">
                                <BarChart3 className="w-6 h-6 text-cyan-600" />
                            </div>
                            <div>
                                <div className="text-2xl font-bold text-stone-900">
                                    {sessionAnalytics.avgEventsPerSession}
                                </div>
                                <div className="text-sm text-stone-600">Avg Events/Session</div>
                            </div>
                        </div>
                    </div>

                    {topReferrers.length > 0 && (
                        <>
                            <h3 className="text-md font-semibold text-stone-900 mt-6 mb-3">Top Referrers</h3>
                            <div className="space-y-2">
                                {topReferrers.map((ref, index) => (
                                    <div key={index} className="flex items-center justify-between p-2 bg-stone-50 rounded-lg">
                                        <div className="flex items-center gap-2 text-sm text-stone-700 truncate">
                                            <ExternalLink className="w-4 h-4 flex-shrink-0" />
                                            <span className="truncate">{ref.referrer}</span>
                                        </div>
                                        <span className="text-sm font-medium text-stone-900">{ref.count}</span>
                                    </div>
                                ))}
                            </div>
                        </>
                    )}
                </div>
            </div>

            {/* Top Collections & Top Pages */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <h2 className="text-lg font-bold text-stone-900 mb-4">Top Collections</h2>
                    {topCollections.length === 0 ? (
                        <p className="text-stone-600 text-center py-8">No collection clicks yet</p>
                    ) : (
                        <div className="space-y-3">
                            {topCollections.map((collection, index) => (
                                <div key={collection.slug} className="flex items-center justify-between p-3 bg-stone-50 rounded-lg">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-full bg-amber-100 text-amber-700 flex items-center justify-center text-sm font-bold">
                                            {index + 1}
                                        </div>
                                        <div className="font-medium text-stone-900 capitalize">
                                            {collection.slug.replace(/-/g, ' ')}
                                        </div>
                                    </div>
                                    <div className="text-sm font-medium text-stone-600">
                                        {collection.count} clicks
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <h2 className="text-lg font-bold text-stone-900 mb-4">Top Pages</h2>
                    {topPages.length === 0 ? (
                        <p className="text-stone-600 text-center py-8">No page views yet</p>
                    ) : (
                        <div className="space-y-3">
                            {topPages.map((page, index) => (
                                <div key={page.path} className="flex items-center justify-between p-3 bg-stone-50 rounded-lg">
                                    <div className="flex items-center gap-3">
                                        <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center text-sm font-bold">
                                            {index + 1}
                                        </div>
                                        <div className="font-medium text-stone-900 text-sm truncate">
                                            {page.path}
                                        </div>
                                    </div>
                                    <div className="text-sm font-medium text-stone-600">
                                        {page.count} views
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

            </div>
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, Eye, EyeOff } from 'lucide-react';

interface CaseStudy {
    id: string;
    slug: string;
    title: string;
    subtitle?: string;
    client?: string;
    industry?: string;
    duration?: string;
    teamSize?: string;
    context?: string;
    challenge?: string;
    solution?: string;
    results?: string;
    techStack: string[];
    images: string[];
    sortOrder: number;
    isPublished: boolean;
}

export default function CaseStudiesPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const { brandSlug } = use(params);
    const [caseStudies, setCaseStudies] = useState<CaseStudy[]>([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [editingCaseStudy, setEditingCaseStudy] = useState<CaseStudy | null>(null);

    useEffect(() => {
        fetchCaseStudies();
    }, [brandSlug]);

    const fetchCaseStudies = async () => {
        try {
            const res = await fetch(`/api/admin/${brandSlug}/case-studies`);
            const data = await res.json();
            setCaseStudies(Array.isArray(data) ? data : []);
        } catch (error) {
            console.error('Failed to fetch case studies:', error);
            setCaseStudies([]);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this case study?')) return;

        try {
            const res = await fetch(`/api/admin/${brandSlug}/case-studies/${id}`, {
                method: 'DELETE',
            });

            if (res.ok) {
                fetchCaseStudies();
            } else {
                alert('Failed to delete case study');
            }
        } catch (error) {
            console.error('Failed to delete case study:', error);
            alert('Failed to delete case study');
        }
    };

    const openEditModal = (caseStudy?: CaseStudy) => {
        setEditingCaseStudy(caseStudy || null);
        setShowModal(true);
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <div className="text-stone-600">Loading case studies...</div>
            </div>
        );
    }

    return (
        <div className="p-8">
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Case Studies</h1>
                    <p className="text-stone-600">Showcase your successful projects</p>
                </div>
                <button
                    onClick={() => openEditModal()}
                    className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
                >
                    <Plus className="w-4 h-4" />
                    Add Case Study
                </button>
            </div>

            {/* Case Studies List */}
            {caseStudies.length === 0 ? (
                <div className="bg-white rounded-xl border border-stone-200 p-12 text-center">
                    <p className="text-stone-600 mb-4">No case studies yet</p>
                    <button
                        onClick={() => openEditModal()}
                        className="text-blue-600 hover:text-blue-700 font-medium"
                    >
                        Create your first case study
                    </button>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {caseStudies.map((study) => (
                        <div
                            key={study.id}
                            className="bg-white rounded-xl border border-stone-200 p-6"
                        >
                            <div className="flex items-start justify-between mb-4">
                                <div className="flex-1">
                                    <h3 className="text-lg font-bold text-stone-900 mb-1">{study.title}</h3>
                                    {study.subtitle && (
                                        <p className="text-sm text-stone-600 mb-2">{study.subtitle}</p>
                                    )}
                                    {study.client && (
                                        <p className="text-sm text-stone-500">Client: {study.client}</p>
                                    )}
                                </div>
                                <div className="flex items-center gap-2">
                                    {study.isPublished ? (
                                        <Eye className="w-4 h-4 text-green-600" title="Published" />
                                    ) : (
                                        <EyeOff className="w-4 h-4 text-stone-400" title="Draft" />
                                    )}
                                </div>
                            </div>

                            {study.industry && (
                                <span className="inline-block px-2 py-1 bg-blue-50 text-blue-700 text-xs rounded mb-3">
                                    {study.industry}
                                </span>
                            )}

                            {study.techStack && study.techStack.length > 0 && (
                                <div className="flex flex-wrap gap-1 mb-4">
                                    {study.techStack.slice(0, 5).map((tech, idx) => (
                                        <span
                                            key={idx}
                                            className="px-2 py-1 bg-stone-100 text-stone-700 text-xs rounded"
                                        >
                                            {tech}
                                        </span>
                                    ))}
                                    {study.techStack.length > 5 && (
                                        <span className="px-2 py-1 text-stone-500 text-xs">
                                            +{study.techStack.length - 5} more
                                        </span>
                                    )}
                                </div>
                            )}

                            <div className="flex items-center gap-2 pt-4 border-t border-stone-200">
                                <button
                                    onClick={() => openEditModal(study)}
                                    className="flex-1 px-3 py-2 text-sm text-stone-700 border border-stone-300 rounded-lg hover:bg-stone-50 transition-colors"
                                >
                                    <Edit2 className="w-4 h-4 inline mr-1" />
                                    Edit
                                </button>
                                <button
                                    onClick={() => handleDelete(study.id)}
                                    className="flex-1 px-3 py-2 text-sm text-red-600 border border-red-300 rounded-lg hover:bg-red-50 transition-colors"
                                >
                                    <Trash2 className="w-4 h-4 inline mr-1" />
                                    Delete
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Modal */}
            {showModal && (
                <CaseStudyModal
                    brandSlug={brandSlug}
                    caseStudy={editingCaseStudy}
                    onClose={() => {
                        setShowModal(false);
                        setEditingCaseStudy(null);
                    }}
                    onSave={() => {
                        fetchCaseStudies();
                        setShowModal(false);
                        setEditingCaseStudy(null);
                    }}
                />
            )}
        </div>
    );
}

function CaseStudyModal({
    brandSlug,
    caseStudy,
    onClose,
    onSave,
}: {
    brandSlug: string;
    caseStudy: CaseStudy | null;
    onClose: () => void;
    onSave: () => void;
}) {
    const [formData, setFormData] = useState({
        title: caseStudy?.title || '',
        subtitle: caseStudy?.subtitle || '',
        client: caseStudy?.client || '',
        industry: caseStudy?.industry || '',
        duration: caseStudy?.duration || '',
        teamSize: caseStudy?.teamSize || '',
        context: caseStudy?.context || '',
        challenge: caseStudy?.challenge || '',
        solution: caseStudy?.solution || '',
        results: caseStudy?.results || '',
        techStack: caseStudy?.techStack?.join('\n') || '',
        isPublished: caseStudy?.isPublished !== undefined ? caseStudy.isPublished : false,
    });
    const [saving, setSaving] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const url = caseStudy
                ? `/api/admin/${brandSlug}/case-studies/${caseStudy.id}`
                : `/api/admin/${brandSlug}/case-studies`;
            const method = caseStudy ? 'PUT' : 'POST';

            const res = await fetch(url, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    ...formData,
                    techStack: formData.techStack.split('\n').filter((t) => t.trim()),
                }),
            });

            if (res.ok) {
                onSave();
            } else {
                alert('Failed to save case study');
            }
        } catch (error) {
            console.error('Failed to save case study:', error);
            alert('Failed to save case study');
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl max-w-4xl w-full max-h-[90vh] overflow-y-auto">
                <div className="p-6 border-b border-stone-200 sticky top-0 bg-white">
                    <h2 className="text-xl font-bold text-stone-900">
                        {caseStudy ? 'Edit Case Study' : 'Add New Case Study'}
                    </h2>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-6">
                    {/* Basic Info */}
                    <div className="grid grid-cols-2 gap-4">
                        <div className="col-span-2">
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Title *
                            </label>
                            <input
                                type="text"
                                value={formData.title}
                                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                                required
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="E-Commerce Platform Modernization"
                            />
                        </div>

                        <div className="col-span-2">
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Subtitle
                            </label>
                            <input
                                type="text"
                                value={formData.subtitle}
                                onChange={(e) => setFormData({ ...formData, subtitle: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="Transforming a legacy system"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Client
                            </label>
                            <input
                                type="text"
                                value={formData.client}
                                onChange={(e) => setFormData({ ...formData, client: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="Company Name"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Industry
                            </label>
                            <input
                                type="text"
                                value={formData.industry}
                                onChange={(e) => setFormData({ ...formData, industry: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="Retail, Healthcare, etc."
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Duration
                            </label>
                            <input
                                type="text"
                                value={formData.duration}
                                onChange={(e) => setFormData({ ...formData, duration: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="6 months"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Team Size
                            </label>
                            <input
                                type="text"
                                value={formData.teamSize}
                                onChange={(e) => setFormData({ ...formData, teamSize: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="8 developers"
                            />
                        </div>
                    </div>

                    {/* Content Sections */}
                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Context
                        </label>
                        <textarea
                            value={formData.context}
                            onChange={(e) => setFormData({ ...formData, context: e.target.value })}
                            rows={3}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="Background and context of the project..."
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Challenge
                        </label>
                        <textarea
                            value={formData.challenge}
                            onChange={(e) => setFormData({ ...formData, challenge: e.target.value })}
                            rows={3}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="What problems needed to be solved..."
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Solution
                        </label>
                        <textarea
                            value={formData.solution}
                            onChange={(e) => setFormData({ ...formData, solution: e.target.value })}
                            rows={4}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="How you solved the problems..."
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Results
                        </label>
                        <textarea
                            value={formData.results}
                            onChange={(e) => setFormData({ ...formData, results: e.target.value })}
                            rows={3}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="Measurable outcomes and impact..."
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Tech Stack (one per line)
                        </label>
                        <textarea
                            value={formData.techStack}
                            onChange={(e) => setFormData({ ...formData, techStack: e.target.value })}
                            rows={4}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="React&#10;Node.js&#10;PostgreSQL&#10;AWS"
                        />
                    </div>

                    <div className="flex items-center gap-2">
                        <input
                            type="checkbox"
                            id="isPublished"
                            checked={formData.isPublished}
                            onChange={(e) => setFormData({ ...formData, isPublished: e.target.checked })}
                            className="w-4 h-4 text-blue-600 border-stone-300 rounded focus:ring-blue-500"
                        />
                        <label htmlFor="isPublished" className="text-sm font-medium text-stone-700">
                            Published (visible on public site)
                        </label>
                    </div>

                    <div className="flex justify-end gap-3 pt-4 border-t border-stone-200">
                        <button
                            type="button"
                            onClick={onClose}
                            className="px-4 py-2 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            disabled={saving}
                            className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors disabled:opacity-50"
                        >
                            {saving ? 'Saving...' : 'Save Case Study'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Loader2, Mail, Phone, Building2, Calendar } from 'lucide-react';

interface CatalogueRequest {
    id: string;
    companyName: string;
    contactName: string;
    email: string;
    phone: string | null;
    notes: string | null;
    status: string;
    createdAt: string;
}

interface PaginationData {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
}

export default function CatalogueRequestsPage() {
    const [requests, setRequests] = useState<CatalogueRequest[]>([]);
    const [pagination, setPagination] = useState<PaginationData>({
        page: 1,
        limit: 20,
        total: 0,
        totalPages: 0
    });
    const [loading, setLoading] = useState(true);
    const [statusFilter, setStatusFilter] = useState<string>('');

    useEffect(() => {
        fetchRequests();
    }, [pagination.page, statusFilter]);

    const fetchRequests = async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({
                page: pagination.page.toString(),
                limit: pagination.limit.toString()
            });
            if (statusFilter) {
                params.append('status', statusFilter);
            }

            const res = await fetch(`/api/admin/merch/catalogue-requests?${params}`);
            const data = await res.json();
            setRequests(data.requests || []);
            setPagination(data.pagination);
        } catch (error) {
            console.error('Failed to fetch requests:', error);
        } finally {
            setLoading(false);
        }
    };

    const formatDate = (dateString: string) => {
        return new Date(dateString).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'NEW':
                return 'bg-blue-100 text-blue-800';
            case 'IN_PROGRESS':
                return 'bg-yellow-100 text-yellow-800';
            case 'DONE':
                return 'bg-green-100 text-green-800';
            default:
                return 'bg-stone-100 text-stone-800';
        }
    };

    if (loading && requests.length === 0) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-8 max-w-7xl mx-auto">
            <div className="mb-8">
                <h1 className="text-2xl font-bold text-stone-900 mb-2">Catalogue Requests</h1>
                <p className="text-stone-600">View and manage catalogue requests from customers</p>
            </div>

            {/* Filters */}
            <div className="mb-6 flex gap-4">
                <select
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                    className="px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                >
                    <option value="">All Status</option>
                    <option value="NEW">New</option>
                    <option value="IN_PROGRESS">In Progress</option>
                    <option value="DONE">Done</option>
                </select>
            </div>

            {/* Requests List */}
            {requests.length === 0 ? (
                <div className="text-center py-12 bg-stone-50 rounded-xl border border-stone-200">
                    <p className="text-stone-600">No catalogue requests yet</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {requests.map((request) => (
                        <div
                            key={request.id}
                            className="bg-white rounded-xl border border-stone-200 shadow-sm p-6 hover:shadow-md transition-shadow"
                        >
                            <div className="flex items-start justify-between mb-4">
                                <div className="flex-1">
                                    <div className="flex items-center gap-3 mb-2">
                                        <h3 className="text-lg font-semibold text-stone-900">
                                            {request.contactName}
                                        </h3>
                                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(request.status)}`}>
                                            {request.status}
                                        </span>
                                    </div>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-sm text-stone-600">
                                        <div className="flex items-center gap-2">
                                            <Building2 className="w-4 h-4" />
                                            {request.companyName}
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <Mail className="w-4 h-4" />
                                            {request.email}
                                        </div>
                                        {request.phone && (
                                            <div className="flex items-center gap-2">
                                                <Phone className="w-4 h-4" />
                                                {request.phone}
                                            </div>
                                        )}
                                        <div className="flex items-center gap-2">
                                            <Calendar className="w-4 h-4" />
                                            {formatDate(request.createdAt)}
                                        </div>
                                    </div>
                                </div>
                            </div>
                            {request.notes && (
                                <div className="mt-4 p-3 bg-stone-50 rounded-lg">
                                    <p className="text-sm text-stone-700">
                                        <span className="font-medium">Notes:</span> {request.notes}
                                    </p>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            )}

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <div className="mt-6 flex items-center justify-between">
                    <p className="text-sm text-stone-600">
                        Showing {((pagination.page - 1) * pagination.limit) + 1} to{' '}
                        {Math.min(pagination.page * pagination.limit, pagination.total)} of{' '}
                        {pagination.total} requests
                    </p>
                    <div className="flex gap-2">
                        <button
                            onClick={() => setPagination({ ...pagination, page: pagination.page - 1 })}
                            disabled={pagination.page === 1}
                            className="px-4 py-2 border border-stone-300 rounded-lg hover:bg-stone-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                        >
                            Previous
                        </button>
                        <button
                            onClick={() => setPagination({ ...pagination, page: pagination.page + 1 })}
                            disabled={pagination.page === pagination.totalPages}
                            className="px-4 py-2 border border-stone-300 rounded-lg hover:bg-stone-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                        >
                            Next
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, Save, Loader2, RefreshCw } from 'lucide-react';
import { useToast } from '@/components/ui/ToastProvider';
import ImageUploadField from '@/components/admin/ImageUploadField';

export default function EditCollectionPage({
    params
}: {
    params: Promise<{ brandSlug: string; id: string }>;
}) {
    const { brandSlug, id } = use(params);
    const router = useRouter();
    const toast = useToast();

    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [formData, setFormData] = useState({
        name: '',
        slug: '',
        description: '',
        heroTitle: '',
        heroSubtitle: '',
        visibility: 'draft',
        coverImage: '',
    });

    useEffect(() => {
        fetchCollection();
    }, [id]);

    const fetchCollection = async () => {
        try {
            const res = await fetch(`/api/admin/collections/${id}`);
            if (res.ok) {
                const data = await res.json();
                setFormData({
                    name: data.name,
                    slug: data.slug,
                    description: data.description || '',
                    heroTitle: data.heroTitle || '',
                    heroSubtitle: data.heroSubtitle || '',
                    visibility: data.visibility || 'draft',
                    coverImage: data.coverImage || '',
                });
            } else {
                toast.error('Failed to load collection');
                router.push(`/dashboard/${brandSlug}/collections`);
            }
        } catch (error) {
            console.error('Error fetching collection:', error);
            toast.error('Failed to load collection');
        } finally {
            setLoading(false);
        }
    };

    const generateSlug = (name: string) => {
        return name
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, '-')
            .replace(/(^-|-$)+/g, '');
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const res = await fetch(`/api/admin/collections/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    ...formData,
                    brandSlug
                })
            });

            if (res.ok) {
                toast.success('Collection updated successfully');
                router.push(`/dashboard/${brandSlug}/collections`);
                router.refresh();
            } else {
                const data = await res.json();
                toast.error(data.error || 'Failed to update collection');
            }
        } catch (error) {
            console.error('Update collection error:', error);
            toast.error('An error occurred');
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-screen">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-6 max-w-4xl mx-auto">
            {/* Header */}
            <div className="flex items-center gap-4 mb-8">
                <Link
                    href={`/dashboard/${brandSlug}/collections`}
                    className="p-2 hover:bg-stone-100 rounded-full transition-colors text-stone-500"
                >
                    <ArrowLeft className="w-6 h-6" />
                </Link>
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Edit Collection</h1>
                    <p className="text-stone-600">Update collection details</p>
                </div>
            </div>

            <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-stone-200 shadow-sm p-6 md:p-8 space-y-8">

                {/* Basic Info */}
                <div className="space-y-6">
                    <h3 className="text-lg font-bold text-stone-900 border-b pb-2">Basic Information</h3>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-stone-700">Collection Name <span className="text-red-500">*</span></label>
                            <input
                                required
                                type="text"
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                placeholder="e.g. Summer Essentials"
                                value={formData.name}
                                onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                            />
                        </div>

                        <div className="space-y-2">
                            <ImageUploadField
                                label="Cover Image"
                                description="Image for collection card/banner"
                                value={formData.coverImage}
                                onChange={(url) => setFormData(prev => ({ ...prev, coverImage: url }))}
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm font-medium text-stone-700">Slug (URL) <span className="text-red-500">*</span></label>
                            <div className="flex gap-2">
                                <input
                                    required
                                    type="text"
                                    className="w-full px-4 py-2 border border-stone-300 rounded-lg bg-stone-50 text-stone-600 focus:ring-2 focus:ring-amber-500 outline-none"
                                    value={formData.slug}
                                    onChange={(e) => setFormData(prev => ({ ...prev, slug: e.target.value }))}
                                />
                                <button
                                    type="button"
                                    onClick={() => setFormData(prev => ({ ...prev, slug: generateSlug(prev.name) }))}
                                    className="p-2 text-stone-500 hover:bg-stone-100 rounded-lg"
                                    title="Regenerate Slug"
                                >
                                    <RefreshCw className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-sm font-medium text-stone-700">Description</label>
                        <textarea
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                            rows={3}
                            placeholder="Brief description of this collection..."
                            value={formData.description}
                            onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                        />
                    </div>
                </div>

                {/* Hero / Display Info */}
                <div className="space-y-6">
                    <h3 className="text-lg font-bold text-stone-900 border-b pb-2">Display Settings</h3>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-stone-700">Hero Title</label>
                            <input
                                type="text"
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                placeholder="Displayed on banner"
                                value={formData.heroTitle}
                                onChange={(e) => setFormData(prev => ({ ...prev, heroTitle: e.target.value }))}
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-stone-700">Hero Subtitle</label>
                            <input
                                type="text"
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                placeholder="Displayed under title"
                                value={formData.heroSubtitle}
                                onChange={(e) => setFormData(prev => ({ ...prev, heroSubtitle: e.target.value }))}
                            />
                        </div>
                    </div>
                </div>

                {/* Status */}
                <div className="flex items-center gap-3 p-4 bg-stone-50 rounded-lg">
                    <input
                        type="checkbox"
                        id="isPublished"
                        className="w-5 h-5 text-amber-600 rounded focus:ring-amber-500"
                        checked={formData.visibility === 'published'}
                        onChange={(e) => setFormData(prev => ({
                            ...prev,
                            visibility: e.target.checked ? 'published' : 'draft'
                        }))}
                    />
                    <label htmlFor="isPublished" className="font-medium text-stone-900 cursor-pointer">
                        Publish Collection (Visible to public)
                    </label>
                    <span className="text-sm text-stone-500 ml-2">
                        {formData.visibility === 'published' ? '(Live)' : '(Hidden)'}
                    </span>
                </div>

                {/* Submit */}
                <div className="flex justify-end pt-4">
                    <button
                        type="submit"
                        disabled={saving}
                        className="flex items-center gap-2 px-6 py-3 bg-amber-600 text-white rounded-xl font-bold hover:bg-amber-700 transition-colors disabled:opacity-50"
                    >
                        {saving ? (
                            <Loader2 className="w-5 h-5 animate-spin" />
                        ) : (
                            <Save className="w-5 h-5" />
                        )}
                        Save Changes
                    </button>
                </div>
            </form >
        </div >
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, Plus, Package, Edit, Trash2, Loader2, Eye } from 'lucide-react';
import { useToast } from '@/components/ui/ToastProvider';

export default function CollectionDetailPage({
    params
}: {
    params: Promise<{ brandSlug: string; id: string }>;
}) {
    const { brandSlug, id } = use(params);
    const router = useRouter();
    const toast = useToast();

    const [collection, setCollection] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [showProductModal, setShowProductModal] = useState(false);

    useEffect(() => {
        fetchCollection();
    }, [id]);

    const fetchCollection = async () => {
        try {
            const res = await fetch(`/api/admin/collections/${id}`);
            if (res.ok) {
                const data = await res.json();
                setCollection(data);
            } else {
                toast.error('Failed to load collection');
            }
        } catch (error) {
            console.error('Error fetching collection:', error);
            toast.error('Failed to load collection');
        } finally {
            setLoading(false);
        }
    };

    const handleDeleteProduct = async (productId: string) => {
        if (!confirm('Are you sure you want to remove this product from the collection?')) return;

        try {
            const res = await fetch(`/api/admin/products/${productId}`, {
                method: 'DELETE'
            });

            if (res.ok) {
                toast.success('Product removed successfully');
                fetchCollection();
            } else {
                toast.error('Failed to remove product');
            }
        } catch (error) {
            console.error('Error deleting product:', error);
            toast.error('Failed to remove product');
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    if (!collection) {
        return (
            <div className="p-6 max-w-7xl mx-auto">
                <div className="text-center py-16">
                    <p className="text-stone-600">Collection not found</p>
                    <Link
                        href={`/dashboard/${brandSlug}/collections`}
                        className="text-amber-600 hover:underline mt-4 inline-block"
                    >
                        Back to Collections
                    </Link>
                </div>
            </div>
        );
    }

    return (
        <div className="p-6 max-w-7xl mx-auto">
            {/* Header */}
            <div className="flex items-center gap-4 mb-6">
                <Link
                    href={`/dashboard/${brandSlug}/collections`}
                    className="p-2 hover:bg-stone-100 rounded-lg transition-colors"
                >
                    <ArrowLeft className="w-5 h-5" />
                </Link>
                <div className="flex-1">
                    <h1 className="text-3xl font-bold text-stone-900">{collection.name}</h1>
                    <p className="text-stone-600 mt-1">{collection.description}</p>
                </div>
                <Link
                    href={`/dashboard/${brandSlug}/collections/${id}/edit`}
                    className="flex items-center gap-2 px-4 py-2 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors"
                >
                    <Edit className="w-5 h-5" />
                    Edit Collection
                </Link>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-amber-100 rounded-lg">
                            <Package className="w-6 h-6 text-amber-600" />
                        </div>
                        <div>
                            <p className="text-sm text-stone-600">Total Products</p>
                            <p className="text-2xl font-bold text-stone-900">
                                {collection._count.products}
                            </p>
                        </div>
                    </div>
                </div>
                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-blue-100 rounded-lg">
                            <Eye className="w-6 h-6 text-blue-600" />
                        </div>
                        <div>
                            <p className="text-sm text-stone-600">Visibility</p>
                            <p className="text-2xl font-bold text-stone-900 capitalize">
                                {collection.visibility}
                            </p>
                        </div>
                    </div>
                </div>
                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-green-100 rounded-lg">
                            <Package className="w-6 h-6 text-green-600" />
                        </div>
                        <div>
                            <p className="text-sm text-stone-600">Status</p>
                            <p className="text-2xl font-bold text-stone-900 capitalize">
                                {collection.status}
                            </p>
                        </div>
                    </div>
                </div>
            </div>

            {/* Products Section */}
            <div className="bg-white rounded-xl border border-stone-200 p-6">
                <div className="flex items-center justify-between mb-6">
                    <h2 className="text-xl font-bold text-stone-900">Products</h2>
                    <Link
                        href={`/dashboard/${brandSlug}/collections/${id}/products/new`}
                        className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                    >
                        <Plus className="w-5 h-5" />
                        Add Product
                    </Link>
                </div>

                {collection.products.length === 0 ? (
                    <div className="text-center py-12 border-2 border-dashed border-stone-300 rounded-lg">
                        <Package className="w-12 h-12 text-stone-400 mx-auto mb-3" />
                        <h3 className="text-lg font-semibold text-stone-900 mb-2">
                            No Products Yet
                        </h3>
                        <p className="text-stone-600 mb-4">
                            Add products to this collection to get started
                        </p>
                        <Link
                            href={`/dashboard/${brandSlug}/collections/${id}/products/new`}
                            className="inline-flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                        >
                            <Plus className="w-5 h-5" />
                            Add Product
                        </Link>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {collection.products.map((product: any) => (
                            <div
                                key={product.id}
                                className="border border-stone-200 rounded-lg p-4 hover:shadow-md transition-shadow"
                            >
                                {/* Product Image */}
                                {product.baseImage ? (
                                    <div className="h-32 bg-stone-100 rounded-lg mb-3">
                                        <img
                                            src={product.baseImage}
                                            alt={product.name}
                                            className="w-full h-full object-cover rounded-lg"
                                        />
                                    </div>
                                ) : (
                                    <div className="h-32 bg-gradient-to-br from-stone-100 to-stone-200 rounded-lg mb-3 flex items-center justify-center">
                                        <Package className="w-12 h-12 text-stone-400" />
                                    </div>
                                )}

                                {/* Product Info */}
                                <h3 className="font-bold text-stone-900 mb-1">{product.name}</h3>
                                <p className="text-sm text-stone-600 mb-2">{product.productType}</p>

                                {/* Stats */}
                                <div className="flex items-center gap-3 text-xs text-stone-600 mb-3">
                                    <span>{product._count.variants} variants</span>
                                    <span className={`px-2 py-1 rounded ${product.status === 'active'
                                            ? 'bg-green-100 text-green-700'
                                            : 'bg-stone-100 text-stone-700'
                                        }`}>
                                        {product.status}
                                    </span>
                                </div>

                                {/* Actions */}
                                <div className="flex gap-2">
                                    <Link
                                        href={`/dashboard/${brandSlug}/products/${product.id}`}
                                        className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors text-sm"
                                    >
                                        <Eye className="w-4 h-4" />
                                        View
                                    </Link>
                                    <button
                                        onClick={() => handleDeleteProduct(product.id)}
                                        className="flex items-center justify-center px-3 py-2 border border-red-300 text-red-600 rounded-lg hover:bg-red-50 transition-colors"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { use, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, Loader2, Save } from 'lucide-react';
import { useToast } from '@/components/ui/ToastProvider';

export default function NewProductPage({
    params
}: {
    params: Promise<{ brandSlug: string; id: string }>;
}) {
    const { brandSlug, id: collectionId } = use(params);
    const router = useRouter();
    const toast = useToast();

    const [saving, setSaving] = useState(false);
    const [isUploading, setIsUploading] = useState(false);
    const [formData, setFormData] = useState({
        name: '',
        slug: '',
        sku: '',
        productType: 'tote-bag',
        description: '',
        baseImage: '',
        isCustomizable: true,
        isFeatured: false,
        status: 'active'
    });

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setIsUploading(true);
        const uploadFormData = new FormData();
        uploadFormData.append('file', file);

        try {
            const res = await fetch('/api/upload', {
                method: 'POST',
                body: uploadFormData
            });

            if (res.ok) {
                const data = await res.json();
                setFormData(prev => ({ ...prev, baseImage: data.url }));
                toast.success('Image uploaded successfully');
            } else {
                toast.error('Failed to upload image');
            }
        } catch (error) {
            console.error('Upload error:', error);
            toast.error('Upload failed');
        } finally {
            setIsUploading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const res = await fetch(`/api/admin/collections/${collectionId}/products`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData)
            });

            if (res.ok) {
                const product = await res.json();
                toast.success('Product created successfully!');
                router.push(`/dashboard/${brandSlug}/products/${product.id}`);
            } else {
                const error = await res.json();
                toast.error(error.error || 'Failed to create product');
            }
        } catch (error) {
            console.error('Error creating product:', error);
            toast.error('Failed to create product');
        } finally {
            setSaving(false);
        }
    };

    const generateSlug = (name: string) => {
        return name
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, '-')
            .replace(/(^-|-$)/g, '');
    };

    const handleNameChange = (name: string) => {
        setFormData(prev => ({
            ...prev,
            name,
            slug: generateSlug(name)
        }));
    };

    return (
        <div className="p-6 max-w-4xl mx-auto">
            {/* Header */}
            <div className="flex items-center gap-4 mb-6">
                <Link
                    href={`/dashboard/${brandSlug}/collections/${collectionId}`}
                    className="p-2 hover:bg-stone-100 rounded-lg transition-colors"
                >
                    <ArrowLeft className="w-5 h-5" />
                </Link>
                <div>
                    <h1 className="text-3xl font-bold text-stone-900">Create New Product</h1>
                    <p className="text-stone-600 mt-1">Add a new product to your collection</p>
                </div>
            </div>

            {/* Form */}
            <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-stone-200 p-6 space-y-6">
                {/* Product Name */}
                <div>
                    <label className="block text-sm font-medium text-stone-700 mb-2">
                        Product Name *
                    </label>
                    <input
                        type="text"
                        value={formData.name}
                        onChange={(e) => handleNameChange(e.target.value)}
                        required
                        placeholder="e.g., Canvas Tote Bag A4"
                        className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    />
                </div>

                {/* Slug */}
                <div>
                    <label className="block text-sm font-medium text-stone-700 mb-2">
                        Slug *
                    </label>
                    <input
                        type="text"
                        value={formData.slug}
                        onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                        required
                        placeholder="canvas-tote-bag-a4"
                        className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    />
                    <p className="text-xs text-stone-500 mt-1">
                        URL-friendly version of the name
                    </p>
                </div>

                {/* SKU */}
                <div>
                    <label className="block text-sm font-medium text-stone-700 mb-2">
                        SKU (Optional)
                    </label>
                    <input
                        type="text"
                        value={formData.sku}
                        onChange={(e) => setFormData({ ...formData, sku: e.target.value })}
                        placeholder="TB-A4-001"
                        className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    />
                </div>

                {/* Product Type */}
                <div>
                    <label className="block text-sm font-medium text-stone-700 mb-2">
                        Product Type *
                    </label>
                    <select
                        value={formData.productType}
                        onChange={(e) => setFormData({ ...formData, productType: e.target.value })}
                        required
                        className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    >
                        <option value="tote-bag">Tote Bag</option>
                        <option value="t-shirt">T-Shirt</option>
                        <option value="hoodie">Hoodie</option>
                        <option value="tumbler">Tumbler</option>
                        <option value="mug">Mug</option>
                        <option value="cap">Cap</option>
                        <option value="other">Other</option>
                    </select>
                </div>

                {/* Description */}
                <div>
                    <label className="block text-sm font-medium text-stone-700 mb-2">
                        Description
                    </label>
                    <textarea
                        value={formData.description}
                        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                        rows={4}
                        placeholder="Describe your product..."
                        className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                    />
                </div>

                {/* Base Image URL */}
                <div>
                    <label className="block text-sm font-medium text-stone-700 mb-2">
                        Base Image
                    </label>

                    <div className="space-y-3">
                        {/* Preview & Upload Area */}
                        <div className="flex gap-4 items-start">
                            <div className="w-32 h-32 bg-stone-100 rounded-lg border border-stone-200 overflow-hidden flex-shrink-0 flex items-center justify-center relative group">
                                {formData.baseImage ? (
                                    <>
                                        <img
                                            src={formData.baseImage}
                                            alt="Preview"
                                            className="w-full h-full object-cover"
                                        />
                                        <button
                                            type="button"
                                            onClick={() => setFormData({ ...formData, baseImage: '' })}
                                            className="absolute inset-0 bg-black/40 text-white opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center"
                                        >
                                            Remove
                                        </button>
                                    </>
                                ) : (
                                    <div className="text-stone-400 text-xs text-center p-2">
                                        No Image
                                    </div>
                                )}
                            </div>

                            <div className="flex-1">
                                <label className="block w-full">
                                    <span className="sr-only">Choose file</span>
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleImageUpload}
                                        disabled={isUploading}
                                        className="block w-full text-sm text-stone-500
                                            file:mr-4 file:py-2 file:px-4
                                            file:rounded-full file:border-0
                                            file:text-sm file:font-semibold
                                            file:bg-amber-50 file:text-amber-700
                                            hover:file:bg-amber-100
                                            cursor-pointer"
                                    />
                                </label>
                                {isUploading && <p className="text-sm text-amber-600 mt-2 flex items-center gap-2"><Loader2 className="w-4 h-4 animate-spin" /> Uploading...</p>}

                                <div className="mt-3">
