                                    />
                                </div>
                                <p className="text-xs text-stone-500 mt-1">
                                    Upload from computer or paste a URL.
                                </p>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Checkboxes */}
                <div className="space-y-3">
                    <div className="flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="isCustomizable"
                            checked={formData.isCustomizable}
                            onChange={(e) => setFormData({ ...formData, isCustomizable: e.target.checked })}
                            className="w-4 h-4 text-amber-600 border-stone-300 rounded focus:ring-amber-500"
                        />
                        <label htmlFor="isCustomizable" className="text-sm font-medium text-stone-700">
                            Allow customization (mockup builder)
                        </label>
                    </div>

                    <div className="flex items-center gap-3">
                        <input
                            type="checkbox"
                            id="isFeatured"
                            checked={formData.isFeatured}
                            onChange={(e) => setFormData({ ...formData, isFeatured: e.target.checked })}
                            className="w-4 h-4 text-amber-600 border-stone-300 rounded focus:ring-amber-500"
                        />
                        <label htmlFor="isFeatured" className="text-sm font-medium text-stone-700">
                            Mark as featured product
                        </label>
                    </div>
                </div>

                {/* Actions */}
                <div className="flex gap-3 pt-4 border-t border-stone-200">
                    <button
                        type="submit"
                        disabled={saving}
                        className="flex-1 flex items-center justify-center gap-2 px-6 py-3 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors font-medium"
                    >
                        {saving ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Creating...
                            </>
                        ) : (
                            <>
                                <Save className="w-5 h-5" />
                                Create Product
                            </>
                        )}
                    </button>
                    <Link
                        href={`/dashboard/${brandSlug}/collections/${collectionId}`}
                        className="px-6 py-3 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors font-medium"
                    >
                        Cancel
                    </Link>
                </div>
            </form>
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { Plus, Package, Eye, Edit, Trash2, Loader2 } from 'lucide-react';
import { useToast } from '@/components/ui/ToastProvider';

export default function CollectionsPage({
    params
}: {
    params: Promise<{ brandSlug: string }>;
}) {
    const { brandSlug } = use(params);
    const router = useRouter();
    const toast = useToast();

    const [collections, setCollections] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchCollections();
    }, [brandSlug]);

    const fetchCollections = async () => {
        try {
            const res = await fetch(`/api/admin/collections?brandSlug=${brandSlug}`);
            if (res.ok) {
                const data = await res.json();
                setCollections(data);
            } else {
                toast.error('Failed to load collections');
            }
        } catch (error) {
            console.error('Error fetching collections:', error);
            toast.error('Failed to load collections');
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this collection?')) return;

        try {
            const res = await fetch(`/api/admin/collections/${id}`, {
                method: 'DELETE'
            });

            if (res.ok) {
                toast.success('Collection deleted successfully');
                fetchCollections();
            } else {
                toast.error('Failed to delete collection');
            }
        } catch (error) {
            console.error('Error deleting collection:', error);
            toast.error('Failed to delete collection');
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-6 max-w-7xl mx-auto">
            {/* Header */}
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h1 className="text-3xl font-bold text-stone-900">Collections</h1>
                    <p className="text-stone-600 mt-1">
                        Manage your product collections and showcase
                    </p>
                </div>
                <Link
                    href={`/dashboard/${brandSlug}/collections/new`}
                    className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                >
                    <Plus className="w-5 h-5" />
                    Create Collection
                </Link>
            </div>

            {/* Collections Grid */}
            {collections.length === 0 ? (
                <div className="text-center py-16 bg-white rounded-xl border-2 border-dashed border-stone-300">
                    <Package className="w-16 h-16 text-stone-400 mx-auto mb-4" />
                    <h3 className="text-xl font-semibold text-stone-900 mb-2">
                        No Collections Yet
                    </h3>
                    <p className="text-stone-600 mb-6">
                        Create your first collection to start organizing products
                    </p>
                    <Link
                        href={`/dashboard/${brandSlug}/collections/new`}
                        className="inline-flex items-center gap-2 px-6 py-3 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                    >
                        <Plus className="w-5 h-5" />
                        Create Collection
                    </Link>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {collections.map((collection) => (
                        <div
                            key={collection.id}
                            className="bg-white rounded-xl border border-stone-200 overflow-hidden hover:shadow-lg transition-shadow"
                        >
                            {/* Cover Image */}
                            {collection.coverImage ? (
                                <div className="h-48 bg-stone-100">
                                    <img
                                        src={collection.coverImage}
                                        alt={collection.name}
                                        className="w-full h-full object-cover"
                                    />
                                </div>
                            ) : (
                                <div className="h-48 bg-gradient-to-br from-amber-100 to-amber-200 flex items-center justify-center">
                                    <Package className="w-16 h-16 text-amber-600" />
                                </div>
                            )}

                            {/* Content */}
                            <div className="p-5">
                                <div className="flex items-start justify-between mb-3">
                                    <div className="flex-1">
                                        <h3 className="text-lg font-bold text-stone-900 mb-1">
                                            {collection.name}
                                        </h3>
                                        <p className="text-sm text-stone-600 line-clamp-2">
                                            {collection.description || 'No description'}
                                        </p>
                                    </div>
                                </div>

                                {/* Stats */}
                                <div className="flex items-center gap-4 mb-4 text-sm text-stone-600">
                                    <div className="flex items-center gap-1">
                                        <Package className="w-4 h-4" />
                                        <span>{collection._count.products} products</span>
                                    </div>
                                    <div className={`px-2 py-1 rounded text-xs font-medium ${collection.visibility === 'published'
                                            ? 'bg-green-100 text-green-700'
                                            : 'bg-stone-100 text-stone-700'
                                        }`}>
                                        {collection.visibility}
                                    </div>
                                </div>

                                {/* Actions */}
                                <div className="flex gap-2">
                                    <Link
                                        href={`/dashboard/${brandSlug}/collections/${collection.id}`}
                                        className="flex-1 flex items-center justify-center gap-2 px-3 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors text-sm font-medium"
                                    >
                                        <Eye className="w-4 h-4" />
                                        View
                                    </Link>
                                    <Link
                                        href={`/dashboard/${brandSlug}/collections/${collection.id}/edit`}
                                        className="flex items-center justify-center gap-2 px-3 py-2 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors"
                                    >
                                        <Edit className="w-4 h-4" />
                                    </Link>
                                    <button
                                        onClick={() => handleDelete(collection.id)}
                                        className="flex items-center justify-center gap-2 px-3 py-2 border border-red-300 text-red-600 rounded-lg hover:bg-red-50 transition-colors"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Plus, Edit2, Trash2, GripVertical, Image as ImageIcon, Video, ToggleLeft, ToggleRight } from 'lucide-react';

interface HeroSlide {
    id: string;
    title: string;
    subtitle: string;
    ctaLabel: string | null;
    ctaLink: string | null;
    mediaType: 'IMAGE' | 'VIDEO';
    imageUrl: string | null;
    videoUrl: string | null;
    sortOrder: number;
    isActive: boolean;
}

export default function HeroSlidesPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const { brandSlug } = use(params);
    const router = useRouter();
    const [slides, setSlides] = useState<HeroSlide[]>([]);
    const [loading, setLoading] = useState(true);
    const [showAddModal, setShowAddModal] = useState(false);

    useEffect(() => {
        fetchSlides();
    }, [brandSlug]);

    const fetchSlides = async () => {
        try {
            const res = await fetch(`/api/admin/${brandSlug}/hero-slides`);
            const data = await res.json();
            // Ensure data is always an array
            setSlides(Array.isArray(data) ? data : []);
        } catch (error) {
            console.error('Failed to fetch slides:', error);
            setSlides([]); // Set empty array on error
        } finally {
            setLoading(false);
        }
    };

    const toggleActive = async (slide: HeroSlide) => {
        try {
            await fetch(`/api/admin/${brandSlug}/hero-slides/${slide.id}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ ...slide, isActive: !slide.isActive }),
            });
            fetchSlides();
        } catch (error) {
            alert('Failed to update slide');
        }
    };

    const deleteSlide = async (id: string) => {
        if (!confirm('Are you sure you want to delete this slide?')) return;

        try {
            await fetch(`/api/admin/${brandSlug}/hero-slides/${id}`, {
                method: 'DELETE',
            });
            fetchSlides();
        } catch (error) {
            alert('Failed to delete slide');
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <div className="text-stone-600">Loading...</div>
            </div>
        );
    }

    return (
        <div className="p-8">
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Hero Slides</h1>
                    <p className="text-stone-600">Manage hero slider content</p>
                </div>
                <button
                    onClick={() => setShowAddModal(true)}
                    className="flex items-center gap-2 px-6 py-2.5 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                >
                    <Plus className="w-4 h-4" />
                    Add Slide
                </button>
            </div>

            {slides.length === 0 ? (
                <div className="bg-white rounded-xl border border-stone-200 p-12 text-center">
                    <ImageIcon className="w-12 h-12 text-stone-300 mx-auto mb-4" />
                    <h3 className="text-lg font-medium text-stone-900 mb-2">No slides yet</h3>
                    <p className="text-stone-600 mb-6">Create your first hero slide to get started</p>
                    <button
                        onClick={() => setShowAddModal(true)}
                        className="inline-flex items-center gap-2 px-6 py-2.5 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                    >
                        <Plus className="w-4 h-4" />
                        Add Slide
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {slides.map((slide) => (
                        <div
                            key={slide.id}
                            className="bg-white rounded-xl border border-stone-200 p-6 hover:shadow-md transition-shadow"
                        >
                            <div className="flex items-start gap-4">
                                <div className="cursor-move text-stone-400 hover:text-stone-600">
                                    <GripVertical className="w-5 h-5" />
                                </div>

                                <div className="flex-1">
                                    <div className="flex items-start justify-between mb-3">
                                        <div>
                                            <h3 className="text-lg font-semibold text-stone-900 mb-1">{slide.title}</h3>
                                            <p className="text-sm text-stone-600">{slide.subtitle}</p>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <span className={`inline-flex items-center gap-1 px-2 py-1 text-xs font-medium rounded-full ${slide.mediaType === 'IMAGE'
                                                ? 'bg-blue-100 text-blue-700'
                                                : 'bg-purple-100 text-purple-700'
                                                }`}>
                                                {slide.mediaType === 'IMAGE' ? <ImageIcon className="w-3 h-3" /> : <Video className="w-3 h-3" />}
                                                {slide.mediaType}
                                            </span>
                                            <button
                                                onClick={() => toggleActive(slide)}
                                                className={`inline-flex items-center gap-1 px-2 py-1 text-xs font-medium rounded-full ${slide.isActive
                                                    ? 'bg-green-100 text-green-700'
                                                    : 'bg-stone-100 text-stone-600'
                                                    }`}
                                            >
                                                {slide.isActive ? <ToggleRight className="w-3 h-3" /> : <ToggleLeft className="w-3 h-3" />}
                                                {slide.isActive ? 'Active' : 'Inactive'}
                                            </button>
                                        </div>
                                    </div>

                                    {slide.ctaLabel && (
                                        <div className="text-sm text-stone-600 mb-3">
                                            CTA: <span className="font-medium">{slide.ctaLabel}</span> → {slide.ctaLink}
                                        </div>
                                    )}

                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={() => {/* TODO: Edit modal */ }}
                                            className="inline-flex items-center gap-2 px-3 py-1.5 text-sm text-amber-700 hover:bg-amber-50 rounded-lg transition-colors"
                                        >
                                            <Edit2 className="w-4 h-4" />
                                            Edit
                                        </button>
                                        <button
                                            onClick={() => deleteSlide(slide.id)}
                                            className="inline-flex items-center gap-2 px-3 py-1.5 text-sm text-red-700 hover:bg-red-50 rounded-lg transition-colors"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                            Delete
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            <div className="mt-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
                <p className="text-sm text-blue-900">
                    <strong>Note:</strong> Hero slider UI is ready! Add/edit modal and drag-and-drop reordering will be added in the next iteration.
                </p>
            </div>
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import FormField from '@/components/admin/FormField';
import { Save, Loader2 } from 'lucide-react';

export default function HeroEditorPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const { brandSlug } = use(params);
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [formData, setFormData] = useState({
        heroTitle: '',
        heroSubtitle: '',
        heroTagline: '',
        heroCtaLabel: '',
        heroCtaLink: '',
        highlightLine: '',
        aboutTitle: '',
        aboutContent: '',
    });

    const isIT = brandSlug === 'it-solutions';
    const isMerch = brandSlug === 'merch';

    useEffect(() => {
        const apiUrl = isMerch
            ? '/api/admin/merch-settings'
            : `/api/admin/${brandSlug}/it-settings`;

        fetch(apiUrl)
            .then((res) => res.json())
            .then((data) => {
                if (data) {
                    setFormData({
                        heroTitle: data.heroTitle || '',
                        heroSubtitle: data.heroSubtitle || '',
                        heroTagline: data.heroTagline || '',
                        heroCtaLabel: data.heroCtaLabel || '',
                        heroCtaLink: data.heroCtaLink || '',
                        highlightLine: data.highlightLine || '',
                        aboutTitle: data.aboutTitle || '',
                        aboutContent: data.aboutContent || '',
                    });
                }
                setLoading(false);
            })
            .catch((err) => {
                console.error('Failed to fetch settings:', err);
                setLoading(false);
            });
    }, [brandSlug, isMerch]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData((prev) => ({ ...prev, [name]: value }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const apiUrl = isMerch
                ? '/api/admin/merch-settings'
                : `/api/admin/${brandSlug}/it-settings`;

            const method = isMerch ? 'PATCH' : 'PUT';

            const res = await fetch(apiUrl, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData),
            });

            if (!res.ok) throw new Error('Failed to update');

            router.refresh();
            alert('Settings saved successfully!');
        } catch (error) {
            alert('Error saving settings');
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-8 max-w-4xl mx-auto">
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Hero & Highlight</h1>
                    <p className="text-stone-600">Manage the main landing page content</p>
                </div>
                <button
                    onClick={handleSubmit}
                    disabled={saving}
                    className="flex items-center gap-2 px-6 py-2.5 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors"
                >
                    {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Save Changes
                </button>
            </div>

            <div className="bg-white rounded-xl border border-stone-200 shadow-sm overflow-hidden">
                <div className="p-6 space-y-6">
                    <div className="border-b border-stone-100 pb-6">
                        <h2 className="text-lg font-semibold text-stone-900 mb-4">Hero Section</h2>
                        <div className="grid gap-4">
                            <FormField
                                label="Headline"
                                name="heroTitle"
                                value={formData.heroTitle}
                                onChange={handleChange}
                                placeholder="e.g. Modern Brands Deserve Thoughtful Merchandise"
                            />
                            <FormField
                                label="Subheadline"
                                name="heroSubtitle"
                                value={formData.heroSubtitle}
                                onChange={handleChange}
                                isTextArea
                                placeholder="Brief description..."
                            />
                            <FormField
                                label="Tagline (Optional)"
                                name="heroTagline"
                                value={formData.heroTagline}
                                onChange={handleChange}
                                placeholder="e.g. Designed for teams. Crafted for brands."
                            />
                        </div>
                    </div>

                    <div className="border-b border-stone-100 pb-6">
                        <h2 className="text-lg font-semibold text-stone-900 mb-4">Call to Action</h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <FormField
                                label="Button Label"
                                name="heroCtaLabel"
                                value={formData.heroCtaLabel}
                                onChange={handleChange}
                                placeholder="e.g. Request Catalogue"
                            />
                            <FormField
                                label="Button Link"
                                name="heroCtaLink"
                                value={formData.heroCtaLink}
                                onChange={handleChange}
                                placeholder="e.g. /contact"
                            />
                        </div>
                    </div>

                    {isMerch && (
                        <div className="border-b border-stone-100 pb-6">
                            <h2 className="text-lg font-semibold text-stone-900 mb-4">Highlight Section</h2>
                            <FormField
                                label="Highlight Line"
                                name="highlightLine"
                                value={formData.highlightLine}
                                onChange={handleChange}
                                placeholder="Text appearing below the hero section"
                            />
                        </div>
                    )}

                    {isIT && (
                        <div>
                            <h2 className="text-lg font-semibold text-stone-900 mb-4">About Section</h2>
                            <div className="grid gap-4">
                                <FormField
                                    label="About Title"
                                    name="aboutTitle"
                                    value={formData.aboutTitle}
                                    onChange={handleChange}
                                    placeholder="e.g. About ACHIERA IT Solutions"
                                />
                                <FormField
                                    label="About Content"
                                    name="aboutContent"
                                    value={formData.aboutContent}
                                    onChange={handleChange}
                                    isTextArea
                                    placeholder="Describe your IT solutions and services..."
                                />
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import FormField from '@/components/admin/FormField';
import { Save, Loader2 } from 'lucide-react';

export default function MockupEditorPage() {
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [formData, setFormData] = useState({
        mockupTitle: '',
        mockupSubtitle: '',
        mockupTagline: '',
        mockupEnabled: true,
    });

    useEffect(() => {
        fetch('/api/admin/merch-settings')
            .then((res) => res.json())
            .then((data) => {
                if (data) {
                    setFormData({
                        mockupTitle: data.mockupTitle || '',
                        mockupSubtitle: data.mockupSubtitle || '',
                        mockupTagline: data.mockupTagline || '',
                        mockupEnabled: data.mockupEnabled ?? true,
                    });
                }
                setLoading(false);
            })
            .catch((err) => {
                console.error('Failed to fetch settings:', err);
                setLoading(false);
            });
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;
        const checked = (e.target as HTMLInputElement).checked;
        setFormData((prev) => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value,
        }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const res = await fetch('/api/admin/merch-settings', {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData),
            });

            if (!res.ok) throw new Error('Failed to update');

            router.refresh();
            alert('Mockup settings saved successfully!');
        } catch (error) {
            alert('Error saving settings');
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-8 max-w-4xl mx-auto">
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Try Live Mockup</h1>
                    <p className="text-stone-600">Configure the mockup builder section</p>
                </div>
                <button
                    onClick={handleSubmit}
                    disabled={saving}
                    className="flex items-center gap-2 px-6 py-2.5 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors"
                >
                    {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Save Changes
                </button>
            </div>

            <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6 space-y-6">
                <div className="flex items-center gap-3 p-4 bg-amber-50 border border-amber-200 rounded-lg">
                    <input
                        type="checkbox"
                        id="mockupEnabled"
                        name="mockupEnabled"
                        checked={formData.mockupEnabled}
                        onChange={handleChange}
                        className="w-5 h-5 text-amber-600 rounded focus:ring-amber-500"
                    />
                    <label htmlFor="mockupEnabled" className="text-sm font-medium text-stone-900">
                        Enable Try Live Mockup Section
                    </label>
                </div>

                <FormField
                    label="Section Title"
                    name="mockupTitle"
                    value={formData.mockupTitle}
                    onChange={handleChange}
                    placeholder="e.g. Try Live Mockup — See Your Brand Come to Life"
                />

                <FormField
                    label="Subtitle"
                    name="mockupSubtitle"
                    value={formData.mockupSubtitle}
                    onChange={handleChange}
                    isTextArea
                    placeholder="Brief description of the mockup feature..."
                />

                <FormField
                    label="Tagline"
                    name="mockupTagline"
                    value={formData.mockupTagline}
                    onChange={handleChange}
                    placeholder="e.g. Fast, accurate, and completely free to try."
                />
            </div>
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { Settings, Save } from 'lucide-react';

interface ItSettingsData {
    heroMode: string;
    heroTitle: string;
    heroSubtitle: string;
    heroTagline?: string;
    heroCtaLabel?: string;
    heroCtaLink?: string;
    aboutTitle?: string;
    aboutContent?: string;
}

export default function ItSettingsPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const { brandSlug } = use(params);
    const [settings, setSettings] = useState<ItSettingsData | null>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        fetchSettings();
    }, [brandSlug]);

    const fetchSettings = async () => {
        try {
            const res = await fetch(`/api/admin/${brandSlug}/it-settings`);
            const data = await res.json();
            if (data) {
                setSettings(data);
            } else {
                // Set defaults
                setSettings({
                    heroMode: 'SINGLE',
                    heroTitle: '',
                    heroSubtitle: '',
                });
            }
        } catch (error) {
            console.error('Failed to fetch settings:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        if (!settings) return;

        setSaving(true);
        try {
            const res = await fetch(`/api/admin/${brandSlug}/it-settings`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(settings),
            });

            if (res.ok) {
                alert('Settings saved successfully!');
            } else {
                alert('Failed to save settings');
            }
        } catch (error) {
            console.error('Failed to save settings:', error);
            alert('Failed to save settings');
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <div className="text-stone-600">Loading settings...</div>
            </div>
        );
    }

    if (!settings) {
        return (
            <div className="flex items-center justify-center h-full">
                <div className="text-stone-600">Failed to load settings</div>
            </div>
        );
    }

    return (
        <div className="p-8">
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900 flex items-center gap-2">
                        <Settings className="w-6 h-6" />
                        IT Solutions Settings
                    </h1>
                    <p className="text-stone-600">Configure your IT Solutions page content</p>
                </div>
                <button
                    onClick={handleSave}
                    disabled={saving}
                    className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors disabled:opacity-50"
                >
                    <Save className="w-4 h-4" />
                    {saving ? 'Saving...' : 'Save Changes'}
                </button>
            </div>

            {/* Settings Form */}
            <div className="space-y-8">
                {/* Hero Section */}
                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <h2 className="text-lg font-bold text-stone-900 mb-4">Hero Section</h2>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Hero Mode
                            </label>
                            <select
                                value={settings.heroMode}
                                onChange={(e) => setSettings({ ...settings, heroMode: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            >
                                <option value="SINGLE">Single Hero</option>
                                <option value="SLIDER">Hero Slider</option>
                                <option value="VIDEO">Video Hero</option>
                            </select>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Hero Title *
                            </label>
                            <input
                                type="text"
                                value={settings.heroTitle}
                                onChange={(e) => setSettings({ ...settings, heroTitle: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="Transform Your Business with Technology"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Hero Subtitle *
                            </label>
                            <textarea
                                value={settings.heroSubtitle}
                                onChange={(e) => setSettings({ ...settings, heroSubtitle: e.target.value })}
                                rows={3}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="Custom software solutions designed to drive innovation and efficiency"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Hero Tagline
                            </label>
                            <input
                                type="text"
                                value={settings.heroTagline || ''}
                                onChange={(e) => setSettings({ ...settings, heroTagline: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="Your Technology Partner"
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-stone-700 mb-2">
                                    CTA Button Label
                                </label>
                                <input
                                    type="text"
                                    value={settings.heroCtaLabel || ''}
                                    onChange={(e) => setSettings({ ...settings, heroCtaLabel: e.target.value })}
                                    className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                    placeholder="Get Started"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-stone-700 mb-2">
                                    CTA Button Link
                                </label>
                                <input
                                    type="text"
                                    value={settings.heroCtaLink || ''}
                                    onChange={(e) => setSettings({ ...settings, heroCtaLink: e.target.value })}
                                    className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                    placeholder="/contact"
                                />
                            </div>
                        </div>
                    </div>
                </div>

                {/* About Section */}
                <div className="bg-white rounded-xl border border-stone-200 p-6">
                    <h2 className="text-lg font-bold text-stone-900 mb-4">About Section</h2>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                About Title
                            </label>
                            <input
                                type="text"
                                value={settings.aboutTitle || ''}
                                onChange={(e) => setSettings({ ...settings, aboutTitle: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="About Our IT Solutions"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                About Content
                            </label>
                            <textarea
                                value={settings.aboutContent || ''}
                                onChange={(e) => setSettings({ ...settings, aboutContent: e.target.value })}
                                rows={6}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                                placeholder="Describe your IT solutions and services..."
                            />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, GripVertical } from 'lucide-react';

interface LifecycleStep {
    id: string;
    title: string;
    description: string;
    icon?: string;
    sortOrder: number;
    isActive: boolean;
}

export default function LifecyclePage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const { brandSlug } = use(params);
    const [steps, setSteps] = useState<LifecycleStep[]>([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [editingStep, setEditingStep] = useState<LifecycleStep | null>(null);

    useEffect(() => {
        fetchSteps();
    }, [brandSlug]);

    const fetchSteps = async () => {
        try {
            const res = await fetch(`/api/admin/${brandSlug}/lifecycle`);
            const data = await res.json();
            setSteps(Array.isArray(data) ? data : []);
        } catch (error) {
            console.error('Failed to fetch lifecycle steps:', error);
            setSteps([]);
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this lifecycle step?')) return;

        try {
            const res = await fetch(`/api/admin/${brandSlug}/lifecycle/${id}`, {
                method: 'DELETE',
            });

            if (res.ok) {
                fetchSteps();
            } else {
                alert('Failed to delete lifecycle step');
            }
        } catch (error) {
            console.error('Failed to delete lifecycle step:', error);
            alert('Failed to delete lifecycle step');
        }
    };

    const openEditModal = (step?: LifecycleStep) => {
        setEditingStep(step || null);
        setShowModal(true);
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <div className="text-stone-600">Loading lifecycle steps...</div>
            </div>
        );
    }

    return (
        <div className="p-8">
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Development Lifecycle</h1>
                    <p className="text-stone-600">Manage your development process steps</p>
                </div>
                <button
                    onClick={() => openEditModal()}
                    className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
                >
                    <Plus className="w-4 h-4" />
                    Add Step
                </button>
            </div>

            {/* Steps List */}
            {steps.length === 0 ? (
                <div className="bg-white rounded-xl border border-stone-200 p-12 text-center">
                    <p className="text-stone-600 mb-4">No lifecycle steps yet</p>
                    <button
                        onClick={() => openEditModal()}
                        className="text-blue-600 hover:text-blue-700 font-medium"
                    >
                        Create your first lifecycle step
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {steps.map((step, index) => (
                        <div
                            key={step.id}
                            className="bg-white rounded-xl border border-stone-200 p-6 flex items-start gap-4"
                        >
                            <div className="cursor-move text-stone-400">
                                <GripVertical className="w-5 h-5" />
                            </div>
                            <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center font-bold flex-shrink-0">
                                {index + 1}
                            </div>
                            <div className="flex-1">
                                <div className="flex items-start justify-between mb-2">
                                    <div>
                                        <h3 className="text-lg font-bold text-stone-900">{step.title}</h3>
                                        {step.icon && (
                                            <span className="text-sm text-stone-500">Icon: {step.icon}</span>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span
                                            className={`px-2 py-1 text-xs rounded-full ${step.isActive
                                                    ? 'bg-green-100 text-green-700'
                                                    : 'bg-stone-100 text-stone-600'
                                                }`}
                                        >
                                            {step.isActive ? 'Active' : 'Inactive'}
                                        </span>
                                        <button
                                            onClick={() => openEditModal(step)}
                                            className="p-2 text-stone-600 hover:text-blue-600 transition-colors"
                                        >
                                            <Edit2 className="w-4 h-4" />
                                        </button>
                                        <button
                                            onClick={() => handleDelete(step.id)}
                                            className="p-2 text-stone-600 hover:text-red-600 transition-colors"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                                <p className="text-stone-600">{step.description}</p>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Modal */}
            {showModal && (
                <LifecycleStepModal
                    brandSlug={brandSlug}
                    step={editingStep}
                    onClose={() => {
                        setShowModal(false);
                        setEditingStep(null);
                    }}
                    onSave={() => {
                        fetchSteps();
                        setShowModal(false);
                        setEditingStep(null);
                    }}
                />
            )}
        </div>
    );
}

function LifecycleStepModal({
    brandSlug,
    step,
    onClose,
    onSave,
}: {
    brandSlug: string;
    step: LifecycleStep | null;
    onClose: () => void;
    onSave: () => void;
}) {
    const [formData, setFormData] = useState({
        title: step?.title || '',
        description: step?.description || '',
        icon: step?.icon || '',
        isActive: step?.isActive !== undefined ? step.isActive : true,
    });
    const [saving, setSaving] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const url = step
                ? `/api/admin/${brandSlug}/lifecycle/${step.id}`
                : `/api/admin/${brandSlug}/lifecycle`;
            const method = step ? 'PUT' : 'POST';

            const res = await fetch(url, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData),
            });

            if (res.ok) {
                onSave();
            } else {
                alert('Failed to save lifecycle step');
            }
        } catch (error) {
            console.error('Failed to save lifecycle step:', error);
            alert('Failed to save lifecycle step');
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                <div className="p-6 border-b border-stone-200">
                    <h2 className="text-xl font-bold text-stone-900">
                        {step ? 'Edit Lifecycle Step' : 'Add New Lifecycle Step'}
                    </h2>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Step Title *
                        </label>
                        <input
                            type="text"
                            value={formData.title}
                            onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                            required
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="Discovery & Planning"
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Description *
                        </label>
                        <textarea
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                            required
                            rows={4}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="We analyze your requirements and create a detailed project roadmap"
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Icon (Lucide icon name)
                        </label>
                        <input
                            type="text"
                            value={formData.icon}
                            onChange={(e) => setFormData({ ...formData, icon: e.target.value })}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="Search, Code, Rocket, etc."
                        />
                        <p className="text-xs text-stone-500 mt-1">
                            Browse icons at{' '}
                            <a
                                href="https://lucide.dev/icons/"
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-blue-600 hover:underline"
                            >
                                lucide.dev
                            </a>
                        </p>
                    </div>

                    <div className="flex items-center gap-2">
                        <input
                            type="checkbox"
                            id="isActive"
                            checked={formData.isActive}
                            onChange={(e) => setFormData({ ...formData, isActive: e.target.checked })}
                            className="w-4 h-4 text-blue-600 border-stone-300 rounded focus:ring-blue-500"
                        />
                        <label htmlFor="isActive" className="text-sm font-medium text-stone-700">
                            Active
                        </label>
                    </div>

                    <div className="flex justify-end gap-3 pt-4">
                        <button
                            type="button"
                            onClick={onClose}
                            className="px-4 py-2 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            disabled={saving}
                            className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors disabled:opacity-50"
                        >
                            {saving ? 'Saving...' : 'Save Step'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

import { prisma } from '@/lib/prisma';
import { Button } from '@/components/ui/button';
import { Calendar } from 'lucide-react';
import Link from 'next/link';

export default async function CampaignsPage({ params }: { params: { brandSlug: string } }) {
    const campaigns = await prisma.campaign.findMany({
        where: { brandId: params.brandSlug },
        include: { bundles: true },
        orderBy: { createdAt: 'desc' }
    });

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Campaigns</h1>
                    <p className="text-muted-foreground">
                        Kelola program kampanye bundling (contoh: "Pahlawan Gizi").
                    </p>
                </div>
                <Link href={`/dashboard/${params.brandSlug}/marketing/campaigns/new`}>
                    <Button>
                        + Buat Campaign Baru
                    </Button>
                </Link>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {campaigns.map(campaign => (
                    <div key={campaign.id} className="border rounded-xl p-6 bg-white shadow-sm hover:shadow-md transition-shadow">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <h3 className="font-bold text-lg">{campaign.title}</h3>
                                <span className={`text-xs px-2 py-1 rounded-full font-bold ${campaign.isActive ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>
                                    {campaign.isActive ? 'AKTIF' : 'DRAFT'}
                                </span>
                            </div>
                            <Link href={`/dashboard/${params.brandSlug}/marketing/campaigns/${campaign.id}`}>
                                <Button variant="outline" size="sm">Edit</Button>
                            </Link>
                        </div>

                        <p className="text-sm text-gray-500 mb-4 line-clamp-2">
                            {campaign.description || "Tidak ada deskripsi"}
                        </p>

                        <div className="flex items-center gap-2 text-sm text-gray-500 mb-4">
                            <Calendar className="w-4 h-4" />
                            {new Date(campaign.startDate).toLocaleDateString()} - {new Date(campaign.endDate).toLocaleDateString()}
                        </div>

                        <div className="border-t pt-4">
                            <p className="text-xs font-bold text-gray-400 uppercase mb-2">Paket Bundling</p>
                            <div className="space-y-2">
                                {campaign.bundles.map(bundle => (
                                    <div key={bundle.id} className="flex justify-between text-sm">
                                        <span>{bundle.name}</span>
                                        <span className="font-bold">Rp {Number(bundle.price).toLocaleString()}</span>
                                    </div>
                                ))}
                                {campaign.bundles.length === 0 && <p className="text-sm text-gray-400 italic">Belum ada paket.</p>}
                            </div>
                        </div>
                    </div>
                ))}

                {campaigns.length === 0 && (
                    <div className="col-span-full py-20 text-center border-2 border-dashed rounded-xl">
                        <p className="text-gray-500">Belum ada campaign yang dibuat.</p>
                        <Button className="mt-4" variant="outline">Mulai Buat Campaign</Button>
                    </div>
                )}
            </div>
        </div>
    );
}

