                        className="px-4 py-2 bg-red-100 text-red-800 rounded-lg font-medium hover:bg-red-200 transition-colors flex items-center gap-2"
                    >
                        <Target className="w-4 h-4" />
                        Campaigns
                    </Link>
                </div>
            </div>

            {/* Analytics Content */}
            <Suspense fallback={<div className="p-12 text-center text-gray-500">Memuat Data Analitik...</div>}>
                <MarketingAnalyticsDashboard brandId={brandSlug} />
            </Suspense>
        </div>
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import { useRouter } from 'next/navigation';
import { ArrowLeft, Save, Loader2, DollarSign, Package } from 'lucide-react';
import Link from 'next/link';

export default function ProductPricingPage({ params }: { params: Promise<{ brandSlug: string; productId: string }> }) {
    const resolvedParams = use(params);
    const { brandSlug, productId } = resolvedParams;
    const router = useRouter();

    const [product, setProduct] = useState<any>(null);
    const [variants, setVariants] = useState<any[]>([]);
    const [pricing, setPricing] = useState<Record<string, { basePrice: string; bulkTiers: Array<{ minQty: string; maxQty: string; price: string }> }>>({});
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    useEffect(() => {
        fetchProductData();
    }, [productId]);

    const fetchProductData = async () => {
        setIsLoading(true);
        try {
            // Fetch product with variants
            const res = await fetch(`/api/admin/mockup-templates/${productId}`);
            if (res.ok) {
                const data = await res.json();
                setProduct(data);
                setVariants(data.variants || []);

                // Initialize pricing state
                const initialPricing: any = {};
                for (const variant of data.variants || []) {
                    initialPricing[variant.id] = {
                        basePrice: variant.price?.toString() || '0',
                        bulkTiers: []
                    };
                }
                setPricing(initialPricing);

                // Fetch existing pricing rules
                await fetchExistingRules(data.variants || []);
            }
        } catch (error) {
            console.error('Failed to fetch product:', error);
            setError('Failed to load product data');
        } finally {
            setIsLoading(false);
        }
    };

    const fetchExistingRules = async (variants: any[]) => {
        try {
            const res = await fetch('/api/admin/pricing/rules');
            if (res.ok) {
                const rules = await res.json();

                const updatedPricing = { ...pricing };
                for (const variant of variants) {
                    // Find rules for this variant
                    const variantRules = rules.filter((r: any) =>
                        r.scope === 'VARIANT' && r.scopeId === variant.id
                    );

                    const bulkRules = variantRules.filter((r: any) =>
                        r.component.code === 'BULK_TIER'
                    ).sort((a: any, b: any) => (a.minQty || 0) - (b.minQty || 0));

                    updatedPricing[variant.id] = {
                        basePrice: variant.price?.toString() || '0',
                        bulkTiers: bulkRules.map((r: any) => ({
                            minQty: r.minQty?.toString() || '',
                            maxQty: r.maxQty?.toString() || '',
                            price: r.amount?.toString() || ''
                        }))
                    };
                }
                setPricing(updatedPricing);
            }
        } catch (error) {
            console.error('Failed to fetch pricing rules:', error);
        }
    };

    const handleAddBulkTier = (variantId: string) => {
        setPricing(prev => ({
            ...prev,
            [variantId]: {
                ...prev[variantId],
                bulkTiers: [
                    ...prev[variantId].bulkTiers,
                    { minQty: '', maxQty: '', price: '' }
                ]
            }
        }));
    };

    const handleRemoveBulkTier = (variantId: string, index: number) => {
        setPricing(prev => ({
            ...prev,
            [variantId]: {
                ...prev[variantId],
                bulkTiers: prev[variantId].bulkTiers.filter((_, i) => i !== index)
            }
        }));
    };

    const handleSave = async () => {
        setIsSaving(true);
        setError('');
        setSuccess('');

        try {
            // Get BASE_UNIT and BULK_TIER components
            const componentsRes = await fetch('/api/admin/pricing/components');
            const components = await componentsRes.json();

            const baseUnitComponent = components.find((c: any) => c.code === 'BASE_UNIT');
            const bulkTierComponent = components.find((c: any) => c.code === 'BULK_TIER');

            if (!baseUnitComponent || !bulkTierComponent) {
                throw new Error('Required pricing components not found. Please run seed-pricing.ts first.');
            }

            // Save pricing for each variant
            for (const variant of variants) {
                const variantPricing = pricing[variant.id];
                if (!variantPricing) continue;

                // 1. Update variant base price in database
                await fetch(`/api/admin/mockup-variants/${variant.id}`, {
                    method: 'PUT',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        price: Number(variantPricing.basePrice)
                    })
                });

                // 2. Delete existing VARIANT-level rules for this variant
                const existingRulesRes = await fetch('/api/admin/pricing/rules');
                const existingRules = await existingRulesRes.json();

                const variantRules = existingRules.filter((r: any) =>
                    r.scope === 'VARIANT' && r.scopeId === variant.id
                );

                for (const rule of variantRules) {
                    await fetch(`/api/admin/pricing/rules/${rule.id}`, {
                        method: 'DELETE'
                    });
                }

                // 3. Create new BASE_UNIT rule for variant
                await fetch('/api/admin/pricing/rules', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        componentId: baseUnitComponent.id,
                        scope: 'VARIANT',
                        scopeId: variant.id,
                        priority: 100,
                        currency: 'IDR',
                        amount: Number(variantPricing.basePrice),
                        isActive: true
                    })
                });

                // 4. Create BULK_TIER rules
                for (const tier of variantPricing.bulkTiers) {
                    if (!tier.minQty || !tier.price) continue;

                    await fetch('/api/admin/pricing/rules', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            componentId: bulkTierComponent.id,
                            scope: 'VARIANT',
                            scopeId: variant.id,
                            priority: 110,
                            currency: 'IDR',
                            amount: Number(tier.price),
                            minQty: Number(tier.minQty),
                            maxQty: tier.maxQty ? Number(tier.maxQty) : null,
                            isActive: true
                        })
                    });
                }
            }

            setSuccess('Pricing saved successfully!');
            setTimeout(() => {
                router.push(`/dashboard/${brandSlug}/mockup`);
            }, 1500);
        } catch (error: any) {
            setError(error.message || 'Failed to save pricing');
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="w-8 h-8 animate-spin text-stone-400" />
            </div>
        );
    }

    return (
        <div className="max-w-5xl mx-auto space-y-6">
            {/* Header */}
            <div className="flex items-center gap-4">
                <Link
                    href={`/dashboard/${brandSlug}/mockup`}
                    className="p-2 hover:bg-stone-100 rounded-lg transition-colors"
                >
                    <ArrowLeft className="w-5 h-5" />
                </Link>
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Configure Pricing</h1>
                    <p className="text-stone-600 text-sm">{product?.displayName}</p>
                </div>
            </div>

            {/* Success/Error Messages */}
            {success && (
                <div className="p-4 bg-green-50 border border-green-200 rounded-lg text-green-800">
                    {success}
                </div>
            )}
            {error && (
                <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-800">
                    {error}
                </div>
            )}

            {/* Variants Pricing */}
            <div className="bg-stone-50 border border-stone-200 rounded-lg p-4 mb-4">
                <h3 className="font-semibold text-stone-900 mb-1">Variant-Specific Pricing</h3>
                <p className="text-sm text-stone-600">
                    Each variant can have different pricing. Configure base price and optional bulk tier discounts for each variant below.
                </p>
            </div>

            <div className="space-y-4">
                {variants.map((variant) => (
                    <div key={variant.id} className="bg-white rounded-xl border border-stone-200 p-6 space-y-4">
                        <div className="flex items-center gap-3">
                            <Package className="w-5 h-5 text-amber-600" />
                            <h3 className="font-bold text-stone-900">{variant.name}</h3>
                        </div>

                        {/* Base Price */}
                        <div>
                            <label className="block text-sm font-bold text-stone-900 mb-2">
                                Base Price (per unit)
                            </label>
                            <div className="relative">
                                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-500">Rp</span>
                                <input
                                    type="number"
                                    value={pricing[variant.id]?.basePrice || ''}
                                    onChange={(e) => setPricing(prev => ({
                                        ...prev,
                                        [variant.id]: {
                                            ...prev[variant.id],
                                            basePrice: e.target.value
                                        }
                                    }))}
                                    className="w-full pl-12 pr-4 py-3 bg-stone-50 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                    placeholder="15000"
                                />
                            </div>
                        </div>

                        {/* Bulk Tiers */}
                        <div>
                            <div className="flex items-center justify-between mb-3">
                                <label className="text-sm font-bold text-stone-900">
                                    Bulk Tier Pricing (Optional)
                                </label>
                                <button
                                    onClick={() => handleAddBulkTier(variant.id)}
                                    className="text-sm text-amber-600 hover:text-amber-700 font-medium"
                                >
                                    + Add Tier
                                </button>
                            </div>

                            {pricing[variant.id]?.bulkTiers.map((tier, index) => (
                                <div key={index} className="grid grid-cols-3 gap-3 mb-3">
                                    <div>
                                        <label className="block text-xs text-stone-600 mb-1">Min Qty</label>
                                        <input
                                            type="number"
                                            value={tier.minQty}
                                            onChange={(e) => {
                                                const newTiers = [...pricing[variant.id].bulkTiers];
                                                newTiers[index].minQty = e.target.value;
                                                setPricing(prev => ({
                                                    ...prev,
                                                    [variant.id]: { ...prev[variant.id], bulkTiers: newTiers }
                                                }));
                                            }}
                                            className="w-full px-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm"
                                            placeholder="10"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs text-stone-600 mb-1">Max Qty</label>
                                        <input
                                            type="number"
                                            value={tier.maxQty}
                                            onChange={(e) => {
                                                const newTiers = [...pricing[variant.id].bulkTiers];
                                                newTiers[index].maxQty = e.target.value;
                                                setPricing(prev => ({
                                                    ...prev,
                                                    [variant.id]: { ...prev[variant.id], bulkTiers: newTiers }
                                                }));
                                            }}
                                            className="w-full px-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm"
                                            placeholder="49"
                                        />
                                    </div>
                                    <div className="flex gap-2">
                                        <div className="flex-1">
                                            <label className="block text-xs text-stone-600 mb-1">Price</label>
                                            <input
                                                type="number"
                                                value={tier.price}
                                                onChange={(e) => {
                                                    const newTiers = [...pricing[variant.id].bulkTiers];
                                                    newTiers[index].price = e.target.value;
                                                    setPricing(prev => ({
                                                        ...prev,
                                                        [variant.id]: { ...prev[variant.id], bulkTiers: newTiers }
                                                    }));
                                                }}
                                                className="w-full px-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm"
                                                placeholder="13500"
                                            />
                                        </div>
                                        <button
                                            onClick={() => handleRemoveBulkTier(variant.id, index)}
                                            className="mt-6 px-3 py-2 text-red-600 hover:bg-red-50 rounded-lg text-sm"
                                        >
                                            ×
                                        </button>
                                    </div>
                                </div>
                            ))}

                            {pricing[variant.id]?.bulkTiers.length === 0 && (
                                <p className="text-sm text-stone-500 italic">
                                    No bulk tiers. Click "+ Add Tier" to add quantity-based discounts.
                                </p>
                            )}
                        </div>
                    </div>
                ))}
            </div>

            {/* Save Button */}
            <div className="flex items-center gap-3 pt-4 border-t border-stone-200">
                <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="flex items-center gap-2 px-6 py-3 bg-stone-900 text-white rounded-lg font-bold hover:bg-stone-800 transition-colors disabled:opacity-50"
                >
                    {isSaving ? (
                        <><Loader2 className="w-4 h-4 animate-spin" /> Saving...</>
                    ) : (
                        <><Save className="w-4 h-4" /> Save Pricing</>
                    )}
                </button>
                <Link
                    href={`/dashboard/${brandSlug}/mockup`}
                    className="px-6 py-3 text-stone-600 hover:text-stone-900 font-medium"
                >
                    Cancel
                </Link>
            </div>

            {/* Info */}
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 text-sm text-blue-800">
                <strong>💡 Tip:</strong> Bulk tiers allow you to offer discounts for larger quantities.
                For example: 1-9 pcs = Rp 15,000, 10-49 pcs = Rp 13,500, 50+ pcs = Rp 12,000.
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import { useRouter } from 'next/navigation';
import MockupTemplateList from '@/components/admin/MockupTemplateList';
import MockupTemplateForm from '@/components/admin/MockupTemplateForm';
import MockupVariantManager from '@/components/admin/MockupVariantManager';
import { ArrowLeft } from 'lucide-react';

export default function MockupDashboardPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    // Unwrap params
    const resolvedParams = use(params);
    const { brandSlug } = resolvedParams;

    const router = useRouter();
    const [view, setView] = useState<'list' | 'create' | 'edit'>('list');
    const [templates, setTemplates] = useState<any[]>([]);
    const [editingTemplate, setEditingTemplate] = useState<any>(null);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        fetchTemplates();
    }, [brandSlug]);

    const fetchTemplates = async () => {
        setIsLoading(true);
        try {
            const res = await fetch(`/api/admin/mockup-templates?brandSlug=${brandSlug}`);
            if (res.ok) {
                const data = await res.json();
                setTemplates(data.templates || []);
            }
        } catch (error) {
            console.error('Failed to fetch templates:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleCreate = async (data: any) => {
        try {
            const res = await fetch('/api/admin/mockup-templates', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ ...data, brandSlug })
            });

            if (!res.ok) {
                const err = await res.json();
                throw new Error(err.error || 'Failed to create');
            }

            const newTemplate = await res.json();
            // Switch to edit mode to add variants
            setEditingTemplate(newTemplate);
            setView('edit');
            fetchTemplates(); // Refresh list in background
        } catch (error) {
            alert('Failed to create template: ' + error);
        }
    };

    const handleUpdate = async (data: any) => {
        if (!editingTemplate?.id) return;
        try {
            const res = await fetch(`/api/admin/mockup-templates/${editingTemplate.id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(data)
            });

            if (!res.ok) throw new Error('Failed to update');

            const updated = await res.json();
            setEditingTemplate(updated);
            alert('Template details saved!');
            fetchTemplates();
        } catch (error) {
            alert('Failed to update template: ' + error);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Delete this template and all its variants? This cannot be undone.')) return;
        try {
            await fetch(`/api/admin/mockup-templates/${id}`, { method: 'DELETE' });
            fetchTemplates();
        } catch (error) {
            alert('Failed to delete');
        }
    };

    if (view === 'list') {
        return (
            <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h1 className="text-2xl font-bold text-stone-900">Mockup Management</h1>
                </div>
                {isLoading ? (
                    <div className="text-center py-12">Loading templates...</div>
                ) : (
                    <MockupTemplateList
                        templates={templates}
                        onCreate={() => setView('create')}
                        onEdit={(t) => { setEditingTemplate(t); setView('edit'); }}
                        onDelete={handleDelete}
                    />
                )}
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <button
                onClick={() => { setView('list'); setEditingTemplate(null); fetchTemplates(); }}
                className="flex items-center gap-2 text-stone-500 hover:text-stone-900 transition-colors"
            >
                <ArrowLeft className="w-4 h-4" />
                Back to List
            </button>

            <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
                {/* Left Column: Template Details */}
                <div className="xl:col-span-1 space-y-6">
                    <MockupTemplateForm
                        initialData={editingTemplate}
                        onSave={view === 'create' ? handleCreate : handleUpdate}
                        onCancel={() => { setView('list'); setEditingTemplate(null); }}
                    />
                </div>

                {/* Right Column: Variants (Only in Edit Mode) */}
                <div className="xl:col-span-2 space-y-6">
                    {view === 'edit' && editingTemplate?.id ? (
                        <div className="bg-white p-6 rounded-xl border border-stone-200 shadow-sm">
                            <MockupVariantManager templateId={editingTemplate.id} />
                        </div>
                    ) : (
                        <div className="bg-stone-50 p-8 rounded-xl border border-stone-100 border-dashed text-center text-stone-400">
                            <p>Save template details first to manage variants</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import { useRouter } from 'next/navigation';
import { ArrowLeft, Save, Loader2, Package } from 'lucide-react';
import Link from 'next/link';

export default function VariantPricingPage({ params }: { params: Promise<{ brandSlug: string; variantId: string }> }) {
    const resolvedParams = use(params);
    const { brandSlug, variantId } = resolvedParams;
    const router = useRouter();

    const [variant, setVariant] = useState<any>(null);
    const [basePrice, setBasePrice] = useState('');
    const [bulkTiers, setBulkTiers] = useState<Array<{ minQty: string; maxQty: string; price: string }>>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    useEffect(() => {
        fetchVariantData();
    }, [variantId]);

    const fetchVariantData = async () => {
        setIsLoading(true);
        try {
            // Fetch variant details
            const variantRes = await fetch(`/api/admin/mockup-variants/${variantId}`);
            if (variantRes.ok) {
                const variantData = await variantRes.json();
                setVariant(variantData);
                setBasePrice(variantData.price?.toString() || '0');

                // Fetch existing pricing rules for this variant
                const rulesRes = await fetch('/api/admin/pricing/rules');
                if (rulesRes.ok) {
                    const rules = await rulesRes.json();

                    const variantRules = rules.filter((r: any) =>
                        r.scope === 'VARIANT' && r.scopeId === variantId
                    );

                    const bulkRules = variantRules
                        .filter((r: any) => r.component.code === 'BULK_TIER')
                        .sort((a: any, b: any) => (a.minQty || 0) - (b.minQty || 0));

                    setBulkTiers(bulkRules.map((r: any) => ({
                        minQty: r.minQty?.toString() || '',
                        maxQty: r.maxQty?.toString() || '',
                        price: r.amount?.toString() || ''
                    })));
                }
            }
        } catch (error) {
            console.error('Failed to fetch variant:', error);
            setError('Failed to load variant data');
        } finally {
            setIsLoading(false);
        }
    };

    const handleAddBulkTier = () => {
        setBulkTiers([...bulkTiers, { minQty: '', maxQty: '', price: '' }]);
    };

    const handleRemoveBulkTier = (index: number) => {
        setBulkTiers(bulkTiers.filter((_, i) => i !== index));
    };

    const handleSave = async () => {
        setIsSaving(true);
        setError('');
        setSuccess('');

        try {
            // Get components
            const componentsRes = await fetch('/api/admin/pricing/components');
            const components = await componentsRes.json();

            const baseUnitComponent = components.find((c: any) => c.code === 'BASE_UNIT');
            const bulkTierComponent = components.find((c: any) => c.code === 'BULK_TIER');

            if (!baseUnitComponent || !bulkTierComponent) {
                throw new Error('Required pricing components not found. Please run seed-pricing.ts first.');
            }

            // 1. Update variant base price
            await fetch(`/api/admin/mockup-variants/${variantId}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ price: Number(basePrice) })
            });

            // 2. Delete existing VARIANT-level rules
            const existingRulesRes = await fetch('/api/admin/pricing/rules');
            const existingRules = await existingRulesRes.json();

            const variantRules = existingRules.filter((r: any) =>
                r.scope === 'VARIANT' && r.scopeId === variantId
            );

            for (const rule of variantRules) {
                await fetch(`/api/admin/pricing/rules/${rule.id}`, { method: 'DELETE' });
            }

            // 3. Create new BASE_UNIT rule
            await fetch('/api/admin/pricing/rules', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    componentId: baseUnitComponent.id,
                    scope: 'VARIANT',
                    scopeId: variantId,
                    priority: 100,
                    currency: 'IDR',
                    amount: Number(basePrice),
                    isActive: true
                })
            });

            // 4. Create BULK_TIER rules
            for (const tier of bulkTiers) {
                if (!tier.minQty || !tier.price) continue;

                await fetch('/api/admin/pricing/rules', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        componentId: bulkTierComponent.id,
                        scope: 'VARIANT',
                        scopeId: variantId,
                        priority: 110,
                        currency: 'IDR',
                        amount: Number(tier.price),
                        minQty: Number(tier.minQty),
                        maxQty: tier.maxQty ? Number(tier.maxQty) : null,
                        isActive: true
                    })
                });
            }

            setSuccess('Pricing saved successfully!');
            setTimeout(() => {
                window.history.back();
            }, 1500);
        } catch (error: any) {
            setError(error.message || 'Failed to save pricing');
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="w-8 h-8 animate-spin text-stone-400" />
            </div>
        );
    }

    return (
        <div className="max-w-3xl mx-auto space-y-6">
            {/* Header */}
            <div className="flex items-center gap-4">
                <button
                    onClick={() => window.history.back()}
                    className="p-2 hover:bg-stone-100 rounded-lg transition-colors"
                >
                    <ArrowLeft className="w-5 h-5" />
                </button>
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Configure Pricing</h1>
                    <p className="text-stone-600 text-sm">{variant?.name}</p>
                </div>
            </div>

            {/* Success/Error Messages */}
            {success && (
                <div className="p-4 bg-green-50 border border-green-200 rounded-lg text-green-800">
                    {success}
                </div>
            )}
            {error && (
                <div className="p-4 bg-red-50 border border-red-200 rounded-lg text-red-800">
                    {error}
                </div>
            )}

            {/* Pricing Form */}
            <div className="bg-white rounded-xl border border-stone-200 p-6 space-y-6">
                <div className="flex items-center gap-3 pb-4 border-b border-stone-100">
                    <Package className="w-5 h-5 text-amber-600" />
                    <h3 className="font-bold text-stone-900">Variant Pricing Configuration</h3>
                </div>

                {/* Base Price */}
                <div>
                    <label className="block text-sm font-bold text-stone-900 mb-2">
                        Base Price (per unit)
                    </label>
                    <div className="relative">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-500">Rp</span>
                        <input
                            type="number"
                            value={basePrice}
                            onChange={(e) => setBasePrice(e.target.value)}
                            className="w-full pl-12 pr-4 py-3 bg-stone-50 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                            placeholder="15000"
                        />
                    </div>
                    <p className="text-xs text-stone-500 mt-1">
                        This is the default price for single unit purchases
                    </p>
                </div>

                {/* Bulk Tiers */}
                <div>
                    <div className="flex items-center justify-between mb-3">
                        <label className="text-sm font-bold text-stone-900">
                            Bulk Tier Pricing (Optional)
                        </label>
                        <button
                            onClick={handleAddBulkTier}
                            className="text-sm text-amber-600 hover:text-amber-700 font-medium"
                        >
                            + Add Tier
                        </button>
                    </div>

                    {bulkTiers.map((tier, index) => (
                        <div key={index} className="grid grid-cols-3 gap-3 mb-3">
                            <div>
                                <label className="block text-xs text-stone-600 mb-1">Min Qty</label>
                                <input
                                    type="number"
                                    value={tier.minQty}
                                    onChange={(e) => {
                                        const newTiers = [...bulkTiers];
                                        newTiers[index].minQty = e.target.value;
                                        setBulkTiers(newTiers);
                                    }}
                                    className="w-full px-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm"
                                    placeholder="10"
                                />
                            </div>
                            <div>
                                <label className="block text-xs text-stone-600 mb-1">Max Qty</label>
                                <input
                                    type="number"
                                    value={tier.maxQty}
                                    onChange={(e) => {
                                        const newTiers = [...bulkTiers];
                                        newTiers[index].maxQty = e.target.value;
                                        setBulkTiers(newTiers);
                                    }}
                                    className="w-full px-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm"
                                    placeholder="49"
                                />
                            </div>
                            <div className="flex gap-2">
                                <div className="flex-1">
                                    <label className="block text-xs text-stone-600 mb-1">Price</label>
                                    <input
                                        type="number"
                                        value={tier.price}
                                        onChange={(e) => {
                                            const newTiers = [...bulkTiers];
                                            newTiers[index].price = e.target.value;
                                            setBulkTiers(newTiers);
                                        }}
                                        className="w-full px-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm"
                                        placeholder="13500"
                                    />
                                </div>
                                <button
                                    onClick={() => handleRemoveBulkTier(index)}
                                    className="mt-6 px-3 py-2 text-red-600 hover:bg-red-50 rounded-lg text-sm"
                                >
                                    ×
                                </button>
                            </div>
                        </div>
                    ))}

                    {bulkTiers.length === 0 && (
                        <p className="text-sm text-stone-500 italic">
                            No bulk tiers. Click "+ Add Tier" to add quantity-based discounts.
                        </p>
                    )}
                </div>
            </div>

            {/* Save Button */}
            <div className="flex items-center gap-3 pt-4 border-t border-stone-200">
                <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="flex items-center gap-2 px-6 py-3 bg-stone-900 text-white rounded-lg font-bold hover:bg-stone-800 transition-colors disabled:opacity-50"
                >
                    {isSaving ? (
                        <><Loader2 className="w-4 h-4 animate-spin" /> Saving...</>
                    ) : (
                        <><Save className="w-4 h-4" /> Save Pricing</>
                    )}
                </button>
                <button
                    onClick={() => window.history.back()}
                    className="px-6 py-3 text-stone-600 hover:text-stone-900 font-medium"
                >
                    Cancel
                </button>
            </div>

            {/* Info */}
            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 text-sm text-blue-800">
                <div className="flex items-start gap-3">
                    <div className="flex-shrink-0 w-5 h-5 bg-blue-200 rounded-full flex items-center justify-center text-blue-700 font-bold text-xs mt-0.5">
                        i
                    </div>
                    <div>
                        <p className="font-semibold mb-1">Pricing Configuration</p>
                        <p className="text-blue-700">
                            Set the base price for this variant and optionally add bulk tier discounts for volume purchases.
                            For example: 1-9 units at Rp 15,000, 10-49 units at Rp 13,500, 50+ units at Rp 12,000.
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { ArrowLeft, Loader2, CheckCircle, XCircle, AlertCircle, Clock, Save, Download } from 'lucide-react';

export default function OrderDetailPage({ params }: { params: Promise<{ brandSlug: string; id: string }> }) {
    const resolvedParams = use(params);
    const { brandSlug, id } = resolvedParams;

    const router = useRouter();
    const [order, setOrder] = useState<any>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    // Status Update State
    const [newStatus, setNewStatus] = useState('');
    const [paymentAmount, setPaymentAmount] = useState('');

    useEffect(() => {
        fetchOrderDetail();
    }, [id]);

    const fetchOrderDetail = async () => {
        setIsLoading(true);
        try {
            const res = await fetch(`/api/admin/orders/${id}`);
            if (res.ok) {
                const data = await res.json();
                setOrder(data);
                setNewStatus(data.status);

                // Fetch brand settings separately or if not in order
                // Actually the API /api/admin/orders/[id] returns order with relations.
                // We need to make sure that API includes product.brand.paymentSettings too.
            }
        } catch (error) {
            console.error('Failed to load order', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleUpdateStatus = async () => {
        if (!newStatus || newStatus === order.status) return;
        if (!confirm(`Change status from ${order.status} to ${newStatus}?`)) return;

        setIsSaving(true);
        try {
            const res = await fetch(`/api/admin/orders/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ status: newStatus })
            });

            if (res.ok) {
                alert('Status Updated');
                fetchOrderDetail();
            } else {
                throw new Error('Failed to update');
            }
        } catch (error) {
            alert('Error updating status');
        } finally {
            setIsSaving(false);
        }
    };

    const handleVerifyPayment = async (type: 'DP' | 'FINAL') => {
        // Calculate Total Paid so far to determine exact remaining balance
        const payments = order.payments || [];
        const verifiedPaid = payments.filter((p: any) => p.isVerified).reduce((sum: number, p: any) => sum + Number(p.amount), 0);

        let amount = 0;
        if (type === 'DP') {
            const dpPercentage = order.product?.brand?.paymentSettings?.downPaymentPercentage || 50;
            const dpDecimal = dpPercentage / 100;
            amount = Number(order.total) * dpDecimal;
        } else {
            amount = Number(order.total) - verifiedPaid;
        }

        const msg = type === 'DP'
            ? `Mark DP (Rp ${amount.toLocaleString()}) as Received?`
            : `Mark Final Payment (Rp ${amount.toLocaleString()}) as Received?`;

        if (!confirm(msg)) return;

        setIsSaving(true);
        try {
            const res = await fetch(`/api/admin/orders/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    paymentVerified: true,
                    paymentAmount: amount,
                    paymentType: type
                })
            });

            if (res.ok) {
                alert(`${type} Payment Verified!`);
                fetchOrderDetail();
            } else {
                throw new Error('Failed to verify');
            }
        } catch (error) {
            alert('Error verifying payment');
        } finally {
            setIsSaving(false);
        }
    }

    if (isLoading) return <div className="p-12 text-center text-stone-500"><Loader2 className="w-8 h-8 animate-spin mx-auto mb-2" />Loading Order Details...</div>;
    if (!order) return <div className="p-12 text-center text-red-500">Order not found</div>;

    const timeline = order.statusLogs || [];

    return (
        <div className="space-y-6 max-w-5xl mx-auto">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <Link href={`/dashboard/${brandSlug}/orders`} className="p-2 hover:bg-stone-100 rounded-lg text-stone-500 transition-colors">
                        <ArrowLeft className="w-5 h-5" />
                    </Link>
                    <div>
                        <h1 className="text-2xl font-bold text-stone-900 flex items-center gap-3">
                            Order
                            <span className="font-mono text-xl bg-stone-100 px-2 py-1 rounded text-stone-600">#{order.invoiceNo}</span>
                        </h1>
                        <p className="text-sm text-stone-500">Placed on {new Date(order.createdAt).toLocaleDateString()} at {new Date(order.createdAt).toLocaleTimeString()}</p>
                    </div>
                </div>
                <div className="flex gap-2">
                    {/* Actions */}
                </div>
            </div>

            {(() => {
                const deliveryMatch = order.customerNote?.match(/^\[(.*?)\]/);
                const deliveryInfo = deliveryMatch ? deliveryMatch[1] : null;
                if (!deliveryInfo) return null;
                const [method, courier] = deliveryInfo.split(' - ');

                return (
                    <div className="bg-white border-2 border-stone-900 rounded-2xl p-6 flex items-center justify-between shadow-md animate-in fade-in slide-in-from-top-4">
                        <div className="flex items-center gap-4">
                            <div className={`p-3 rounded-xl ${method === 'Kurir Instan' ? 'bg-indigo-600 text-white' : 'bg-emerald-600 text-white'}`}>
                                <CheckCircle className="w-6 h-6" />
                            </div>
                            <div>
                                <h3 className="text-[10px] font-black uppercase tracking-widest text-stone-500">Shipping Mode</h3>
                                <div className="text-xl font-black text-stone-900">{method} {courier ? `via ${courier}` : ''}</div>
                            </div>
                        </div>
                        <div className="text-right hidden md:block">
                            <span className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest ${method === 'Kurir Instan' ? 'bg-indigo-100 text-indigo-700' : 'bg-emerald-100 text-emerald-700'}`}>
                                Action Required
                            </span>
                        </div>
                    </div>
                );
            })()}

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Main Content */}
                <div className="lg:col-span-2 space-y-6">

                    {/* Order Items */}
                    <div className="space-y-4">
                        <h3 className="font-bold text-stone-900">Items Ordered</h3>
                        {(order.orderItems && order.orderItems.length > 0) ? order.orderItems.map((item: any) => (
                            <div key={item.id} className="bg-white rounded-xl border border-stone-200 p-6 flex gap-6">
                                <div className="w-32 h-32 bg-stone-100 rounded-lg overflow-hidden flex-shrink-0 border border-stone-200">
                                    {/* Mockup Preview */}
                                    {item.mockupResultPath && !item.mockupResultPath.includes('placeholder') ? (
                                        <img src={item.mockupResultPath} className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-stone-300 text-xs">No Preview</div>
                                    )}
                                </div>
                                <div className="flex-1 space-y-1">
                                    <h3 className="font-bold text-lg text-stone-900">{item.name}</h3>
                                    <div className="text-stone-600 flex items-center gap-2">
                                        <span className="font-medium">{item.variantName}</span>
                                    </div>
                                    <div className="text-stone-500 text-sm mt-2">
                                        Quantity: <span className="font-semibold text-stone-900">{item.quantity} pcs</span>
                                    </div>
                                    <div className="text-stone-600 font-bold text-lg mt-1">
                                        Subtotal: Rp {Number(item.subtotal).toLocaleString()}
                                    </div>
                                    {/* Design File Download Link if exists */}
                                    {item.designUploadPath && (
                                        <a href={item.designUploadPath} target="_blank" className="text-amber-600 text-xs hover:underline block mt-1">
                                            Download Design File
                                        </a>
                                    )}
                                </div>
                            </div>
                        )) : (
                            /* Legacy / Fallback for Single Item without OrderItems */
                            <div className="bg-white rounded-xl border border-stone-200 p-6 flex gap-6">
                                <div className="w-32 h-32 bg-stone-100 rounded-lg overflow-hidden flex-shrink-0 border border-stone-200">
                                    <div className="w-full h-full flex items-center justify-center text-stone-300 text-xs">Legacy Order</div>
                                </div>
                                <div className="flex-1 space-y-1">
                                    <h3 className="font-bold text-lg text-stone-900">{order.product?.displayName}</h3>
                                    <div className="text-stone-600 flex items-center gap-2">
                                        <span className="w-3 h-3 rounded-full border border-stone-300 shadow-sm" style={{ backgroundColor: order.variant?.colorHex || '#fff' }} />
                                        {order.variant?.name}
                                    </div>
                                    <div className="text-stone-500 text-sm mt-2">
                                        Quantity: <span className="font-semibold text-stone-900">{order.quantity} pcs</span>
                                    </div>
                                </div>
                            </div>
                        )}
                        <div className="flex justify-end pt-4 border-t border-stone-200">
                            <div className="text-right">
                                <div className="text-stone-500 text-sm mb-1">Grand Total</div>
                                <div className="text-3xl font-bold text-stone-900">
                                    Rp {Number(order.total).toLocaleString()}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Customer Info */}
                    <div className="bg-white rounded-xl border border-stone-200 p-6">
                        <h3 className="font-bold text-stone-900 mb-4 flex items-center gap-2">
                            <CheckCircle className="w-4 h-4 text-stone-400" />
                            Customer Information
                        </h3>
                        <div className="grid grid-cols-2 gap-y-4 gap-x-8 text-sm">
                            <div>
                                <label className="block text-stone-500 mb-1">Name</label>
                                <div className="font-medium text-stone-900">{order.customerName}</div>
                            </div>
                            <div>
                                <label className="block text-stone-500 mb-1">Phone (WhatsApp)</label>
                                <div className="font-medium text-stone-900 font-mono">{order.customerPhone}</div>
                            </div>
                            <div>
                                <label className="block text-stone-500 mb-1">Email</label>
                                <div className="font-medium text-stone-900">{order.customerEmail}</div>
                            </div>
                            <div className="col-span-2">
                                <label className="block text-stone-500 mb-1">Shipping Address</label>
                                <div className="bg-stone-50 p-3 rounded-lg text-stone-700 leading-relaxed whitespace-pre-wrap">
                                    {order.customerAddress || '-'}
                                </div>
                            </div>
                            <div className="col-span-2">
                                <label className="block text-stone-500 mb-1">Notes</label>
                                <div className="bg-stone-50 p-3 rounded-lg text-stone-700 italic">
                                    {order.customerNote || 'No notes'}
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Payment Proofs (Placeholder) */}
                    <div className="bg-white rounded-xl border border-stone-200 p-6">
                        <h3 className="font-bold text-stone-900 mb-4">Payment & Files</h3>
                        <div className="space-y-3">
                            {order.designUploadPath ? (
                                <div className="flex items-center justify-between p-3 bg-stone-50 rounded-lg border border-stone-200">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-white rounded border border-stone-200">
                                            <Download className="w-4 h-4 text-stone-500" />
                                        </div>
                                        <div className="text-sm font-medium text-stone-700">User Design File</div>
                                    </div>
                                    <button className="text-amber-600 text-sm font-medium hover:underline">Download</button>
                                </div>
                            ) : (
                                <p className="text-sm text-stone-500 italic">No design file uploaded (Uses Builder only)</p>
                            )}

                            {order.payments && order.payments.length > 0 ? (
                                order.payments.map((p: any) => (
                                    <div key={p.id} className="p-3 bg-green-50 border border-green-200 rounded-lg flex justify-between items-center">
                                        <div>
                                            <div className="text-xs text-green-700 font-bold uppercase">{p.type} PAYMENT</div>
                                            <div className="text-sm font-medium text-green-900">Rp {Number(p.amount).toLocaleString()}</div>
                                            {(p.sourceBankName || p.destinationBank) && (
                                                <div className="text-xs text-stone-500 mt-1">
                                                    From <span className="font-bold">{p.sourceBankName || '-'}</span>
                                                    {p.destinationBank && <> to <span className="font-bold">{p.destinationBank.bankName}</span></>}
                                                </div>
                                            )}
                                        </div>
                                        <span className="text-xs bg-green-200 text-green-800 px-2 py-1 rounded-full">{p.isVerified ? 'VERIFIED' : 'PENDING'}</span>
                                    </div>
                                ))
                            ) : (
                                <div className="p-4 bg-yellow-50 border border-yellow-100 rounded-lg text-center">
                                    <AlertCircle className="w-6 h-6 text-yellow-500 mx-auto mb-2" />
                                    <p className="text-sm text-yellow-800 font-medium">No Payment Recorded</p>
                                    <p className="text-xs text-yellow-600 mt-1">Monitor bank account for transfers</p>
                                    {order.status === 'WAITING_PAYMENT' && (
                                        <button
                                            onClick={() => handleVerifyPayment('DP')}
                                            className="mt-3 px-4 py-2 bg-yellow-100 text-yellow-800 rounded-lg text-sm font-bold hover:bg-yellow-200 transition-colors w-full"
                                        >
                                            Mark DP Paid ({order.product?.brand?.paymentSettings?.downPaymentPercentage || 50}%)
                                        </button>
                                    )}
                                    {order.status === 'WAITING_FINAL_PAYMENT' && (
                                        <button
                                            onClick={() => handleVerifyPayment('FINAL')}
                                            className="mt-3 px-4 py-2 bg-orange-100 text-orange-800 rounded-lg text-sm font-bold hover:bg-orange-200 transition-colors w-full"
                                        >
                                            Mark Final Payment Paid
                                        </button>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>

                </div>

                {/* Right Column: Status & Timeline */}
                <div className="lg:col-span-1 space-y-6">
                    {/* Status Card */}
                    <div className="bg-white rounded-xl border border-stone-200 p-6 shadow-sm">
                        <label className="block text-xs font-bold text-stone-500 uppercase tracking-wider mb-2">Current Status</label>
                        <select
                            value={newStatus}
                            onChange={(e) => setNewStatus(e.target.value)}
                            className="w-full p-2 bg-stone-50 border border-stone-200 rounded-lg font-bold text-stone-800 mb-4"
                        >
                            <option value="WAITING_PAYMENT">Waiting Payment</option>
                            <option value="PAYMENT_VERIFIED">Payment Verified (DP)</option>
                            <option value="IN_PRODUCTION">In Production</option>
                            <option value="QUALITY_CHECK">Quality Check</option>
                            <option value="PACKING">Packing</option>
                            <option value="WAITING_FINAL_PAYMENT">Waiting Final Payment</option>
                            <option value="SHIPPED">Shipped</option>
                            <option value="COMPLETED">Completed</option>
                            <option value="CANCELLED">Cancelled</option>
                        </select>
                        <button
                            onClick={handleUpdateStatus}
                            disabled={isSaving || newStatus === order.status}
                            className={`w-full py-3 rounded-lg font-bold flex items-center justify-center gap-2 ${newStatus !== order.status ? 'bg-stone-900 text-white hover:bg-stone-800' : 'bg-stone-100 text-stone-400 cursor-not-allowed'}`}
                        >
                            {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                            Update Status
                        </button>
                    </div>

                    {/* Timeline */}
                    <div className="bg-white rounded-xl border border-stone-200 p-6">
                        <h3 className="font-bold text-stone-900 mb-4">Order History</h3>
                        <div className="relative border-l-2 border-stone-100 ml-3 space-y-6 pl-6 py-2">
                            {timeline.map((log: any, idx: number) => (
                                <div key={log.id} className="relative">
                                    <div className={`absolute -left-[31px] w-4 h-4 rounded-full border-2 ${idx === 0 ? 'bg-amber-500 border-amber-500' : 'bg-white border-stone-300'}`} />
                                    <div className={`text-sm font-bold ${idx === 0 ? 'text-stone-900' : 'text-stone-500'}`}>{log.status.replace('_', ' ')}</div>
                                    <div className="text-xs text-stone-500 mt-1">{new Date(log.createdAt).toLocaleString()}</div>
                                    {log.message && <div className="text-xs text-stone-400 mt-1 italic">{log.message}</div>}
                                </div>
                            ))}
                        </div>
                    </div>

                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import Link from 'next/link';
import { Loader2, Search, Filter, Eye } from 'lucide-react';

// Enum helper or just string mapping
const STATUS_COLORS: Record<string, string> = {
    WAITING_PAYMENT: 'bg-yellow-100 text-yellow-800',
    PAYMENT_VERIFIED: 'bg-blue-100 text-blue-800',
    in_production: 'bg-purple-100 text-purple-800', // Prisma might return uppercase or standard? Schema said UPPERCASE
    IN_PRODUCTION: 'bg-purple-100 text-purple-800',
    WAITING_FINAL_PAYMENT: 'bg-orange-100 text-orange-800',
    COMPLETED: 'bg-green-100 text-green-800',
    CANCELLED: 'bg-red-100 text-red-800',
};

export default function OrderListPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const resolvedParams = use(params);
    const { brandSlug } = resolvedParams;

    const [orders, setOrders] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [filter, setFilter] = useState('');

    useEffect(() => {
        const fetchOrders = async () => {
            try {
                const res = await fetch(`/api/admin/orders?brandSlug=${brandSlug}`);
                if (res.ok) {
                    const data = await res.json();
                    setOrders(data.orders || []);
                }
            } catch (error) {
                console.error('Failed to load orders', error);
            } finally {
                setIsLoading(false);
            }
        };
        fetchOrders();
    }, [brandSlug]);

    const filteredOrders = orders.filter(o =>
        o.invoiceNo.toLowerCase().includes(filter.toLowerCase()) ||
        o.customerName.toLowerCase().includes(filter.toLowerCase())
    );

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <h1 className="text-2xl font-bold text-stone-900">Order Management</h1>
                <div className="relative">
                    <Search className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-stone-400" />
                    <input
                        type="text"
                        placeholder="Search invoice or customer..."
