                        className="px-4 py-2 bg-amber-100 text-amber-800 rounded-lg font-medium hover:bg-amber-200 transition-colors flex items-center gap-2"
                    >
                        <Settings className="w-4 h-4" />
                        Test Sandbox
                    </Link>
                </div>
            </div>

