                    </h1>
                    <p className="text-stone-500 mt-1">Configure automated price adjustments</p>
                </div>
                <Link
                    href={`/dashboard/${brandSlug}/pricing/rules/new`}
                    className="bg-stone-900 text-white px-4 py-2 rounded-lg font-medium hover:bg-black transition-colors flex items-center gap-2"
                >
                    <Plus className="w-4 h-4" />
                    New Rule
                </Link>
            </div>

            {/* List */}
            {loading ? (
                <div className="flex justify-center py-12">
                    <Loader2 className="w-8 h-8 animate-spin text-stone-300" />
                </div>
            ) : (
                <div className="bg-white rounded-xl shadow-sm border border-stone-200 overflow-hidden">
                    <table className="w-full text-left">
                        <thead className="bg-stone-50 border-b border-stone-200 text-xs uppercase text-stone-500 font-semibold tracking-wider">
                            <tr>
                                <th className="px-6 py-4">Component</th>
                                <th className="px-6 py-4">Amount</th>
                                <th className="px-6 py-4">Condition</th>
                                <th className="px-6 py-4">Scope</th>
                                <th className="px-6 py-4 text-right">Status</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-stone-100">
                            {rules.map((rule) => (
                                <tr key={rule.id} className="hover:bg-stone-50/50 transition-colors group">
                                    <td className="px-6 py-4">
                                        <div className="flex flex-col">
                                            <span className="font-medium text-stone-900">{rule.component.name}</span>
                                            <span className="text-xs text-stone-500 font-mono">{rule.component.code}</span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 font-bold text-stone-900">
                                        {rule.component.type === 'PERCENT' ? (
                                            <span className="text-blue-600">{Number(rule.amount)}%</span>
                                        ) : rule.component.type === 'MULTIPLIER' ? (
                                            <span className="text-purple-600">x{Number(rule.amount)}</span>
                                        ) : (
                                            <span className="text-emerald-600">+Rp {Number(rule.amount).toLocaleString()}</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex flex-col gap-1">
                                            {/* Quantity Condition */}
                                            {(rule.minQty || rule.maxQty) && (
                                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs bg-amber-50 text-amber-700 w-fit">
                                                    Qty: {rule.minQty || 0} - {rule.maxQty || '∞'}
                                                </span>
                                            )}
                                            {/* Metadata Conditions */}
                                            {rule.metadata && Object.keys(rule.metadata).length > 0 && (
                                                <div className="flex gap-1 flex-wrap">
                                                    {Object.entries(rule.metadata).map(([k, v]) => (
                                                        <span key={k} className="inline-flex items-center px-2 py-0.5 rounded text-xs bg-stone-100 text-stone-600 border border-stone-200">
                                                            {k}: {String(v)}
                                                        </span>
                                                    ))}
                                                </div>
                                            )}
                                            {(!rule.minQty && !rule.maxQty && (!rule.metadata || Object.keys(rule.metadata).length === 0)) && (
                                                <span className="text-xs text-stone-400">Always Applied</span>
                                            )}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-sm text-stone-600">
                                        {rule.scope}
                                        {rule.scopeId && <span className="text-xs text-stone-400 ml-1">({rule.scopeId.slice(0, 4)}...)</span>}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium ${rule.isActive ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700'
                                            }`}>
                                            {rule.isActive ? 'Active' : 'Inactive'}
                                        </span>
                                    </td>
                                </tr>
                            ))}
                            {rules.length === 0 && (
                                <tr>
                                    <td colSpan={5} className="px-6 py-12 text-center text-stone-400">
                                        No active rules found.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import { Loader2, Calculator, AlertCircle } from 'lucide-react';

export default function PricingTestPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const resolvedParams = use(params);
    const { brandSlug } = resolvedParams;

    const [variants, setVariants] = useState<any[]>([]);
    const [selectedVariant, setSelectedVariant] = useState('');
    const [qty, setQty] = useState(10);
    const [printMethod, setPrintMethod] = useState<'none' | 'plastisol' | 'dtf' | 'heatpress'>('none');
    const [colors, setColors] = useState(1);
    const [size, setSize] = useState<'S' | 'M' | 'L' | 'XL' | 'XXL'>('M');
    const [lengthMeter, setLengthMeter] = useState(1);

    const [result, setResult] = useState<any>(null);
    const [isCalculating, setIsCalculating] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        fetchVariants();
    }, []);

    const fetchVariants = async () => {
        try {
            const res = await fetch('/api/public/mockup-template');
            if (res.ok) {
                const templates = await res.json();
                const allVariants = templates.flatMap((t: any) =>
                    t.variants?.map((v: any) => ({
                        id: v.id,
                        name: `${t.displayName} - ${v.name}`,
                        price: v.price
                    })) || []
                );
                setVariants(allVariants);
                if (allVariants.length > 0) {
                    setSelectedVariant(allVariants[0].id);
                }
            }
        } catch (error) {
            console.error('Failed to fetch variants:', error);
        }
    };

    const handleCalculate = async () => {
        if (!selectedVariant) {
            setError('Please select a variant');
            return;
        }

        setIsCalculating(true);
        setError('');
        setResult(null);

        try {
            const payload: any = {
                variantId: selectedVariant,
                qty,
                currency: 'IDR'
            };

            if (printMethod !== 'none') {
                payload.printing = {
                    method: printMethod,
                    ...(printMethod === 'plastisol' && { colors, size }),
                    ...(printMethod === 'dtf' && { lengthMeter })
                };
            }

            const res = await fetch('/api/pricing/calculate', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (res.ok) {
                const data = await res.json();
                setResult(data);
            } else {
                const err = await res.json();
                setError(err.error || 'Calculation failed');
            }
        } catch (error: any) {
            setError(error.message || 'Network error');
        } finally {
            setIsCalculating(false);
        }
    };

    return (
        <div className="max-w-6xl mx-auto space-y-8">
            <div>
                <h1 className="text-3xl font-bold text-stone-900">Pricing Test Sandbox</h1>
                <p className="text-stone-600 mt-1">Simulate orders and see live pricing calculations</p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Input Form */}
                <div className="bg-white rounded-xl border border-stone-200 p-6 space-y-6">
                    <h2 className="text-xl font-bold text-stone-900">Order Configuration</h2>

                    {/* Variant Selection */}
                    <div>
                        <label className="block text-sm font-bold text-stone-900 mb-2">Product Variant</label>
                        <select
                            value={selectedVariant}
                            onChange={(e) => setSelectedVariant(e.target.value)}
                            className="w-full p-3 bg-stone-50 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                        >
                            {variants.map((v) => (
                                <option key={v.id} value={v.id}>
                                    {v.name} (Rp {Number(v.price).toLocaleString()})
                                </option>
                            ))}
                        </select>
                    </div>

                    {/* Quantity */}
                    <div>
                        <label className="block text-sm font-bold text-stone-900 mb-2">Quantity</label>
                        <input
                            type="number"
                            min="1"
                            value={qty}
                            onChange={(e) => setQty(Number(e.target.value))}
                            className="w-full p-3 bg-stone-50 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                        />
                    </div>

                    {/* Print Method */}
                    <div>
                        <label className="block text-sm font-bold text-stone-900 mb-2">Printing Method</label>
                        <select
                            value={printMethod}
                            onChange={(e) => setPrintMethod(e.target.value as any)}
                            className="w-full p-3 bg-stone-50 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                        >
                            <option value="none">No Printing</option>
                            <option value="plastisol">Plastisol</option>
                            <option value="dtf">DTF (Direct-to-Film)</option>
                            <option value="heatpress">Heat Press</option>
                        </select>
                    </div>

                    {/* Plastisol Options */}
                    {printMethod === 'plastisol' && (
                        <>
                            <div>
                                <label className="block text-sm font-bold text-stone-900 mb-2">Number of Colors</label>
                                <input
                                    type="number"
                                    min="1"
                                    max="10"
                                    value={colors}
                                    onChange={(e) => setColors(Number(e.target.value))}
                                    className="w-full p-3 bg-stone-50 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-bold text-stone-900 mb-2">Print Size</label>
                                <select
                                    value={size}
                                    onChange={(e) => setSize(e.target.value as any)}
                                    className="w-full p-3 bg-stone-50 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                                >
                                    <option value="S">S (1.0x)</option>
                                    <option value="M">M (1.05x)</option>
                                    <option value="L">L (1.1x)</option>
                                    <option value="XL">XL (1.15x)</option>
                                    <option value="XXL">XXL (1.2x)</option>
                                </select>
                            </div>
                        </>
                    )}

                    {/* DTF Options */}
                    {printMethod === 'dtf' && (
                        <div>
                            <label className="block text-sm font-bold text-stone-900 mb-2">Length (Meters)</label>
                            <input
                                type="number"
                                min="0.1"
                                step="0.1"
                                value={lengthMeter}
                                onChange={(e) => setLengthMeter(Number(e.target.value))}
                                className="w-full p-3 bg-stone-50 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                            />
                        </div>
                    )}

                    {/* Calculate Button */}
                    <button
                        onClick={handleCalculate}
                        disabled={isCalculating}
                        className="w-full py-3 bg-stone-900 text-white rounded-lg font-bold hover:bg-stone-800 transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                    >
                        {isCalculating ? (
                            <><Loader2 className="w-5 h-5 animate-spin" /> Calculating...</>
                        ) : (
                            <><Calculator className="w-5 h-5" /> Calculate Price</>
                        )}
                    </button>

                    {error && (
                        <div className="p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3">
                            <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
                            <div className="text-sm text-red-800">{error}</div>
                        </div>
                    )}
                </div>

                {/* Result Display */}
                <div className="bg-white rounded-xl border border-stone-200 p-6 space-y-6">
                    <h2 className="text-xl font-bold text-stone-900">Calculation Result</h2>

                    {!result && (
                        <div className="flex flex-col items-center justify-center h-64 text-stone-400">
                            <Calculator className="w-16 h-16 mb-4 opacity-20" />
                            <p className="text-sm">Configure order and click Calculate</p>
                        </div>
                    )}

                    {result && (
                        <>
                            {/* Total */}
                            <div className="p-6 bg-gradient-to-br from-amber-50 to-amber-100 rounded-xl border-2 border-amber-200">
                                <div className="text-sm text-amber-800 font-medium mb-1">Total Price</div>
                                <div className="text-4xl font-bold text-amber-900">
                                    Rp {result.total.toLocaleString()}
                                </div>
                                {result.usedFallback && (
                                    <div className="mt-2 text-xs text-amber-700 bg-amber-200 px-2 py-1 rounded inline-block">
                                        Using fallback (variant price)
                                    </div>
                                )}
                            </div>

                            {/* Breakdown */}
                            <div>
                                <h3 className="font-bold text-stone-900 mb-3">Price Breakdown</h3>
                                <div className="space-y-2">
                                    {result.breakdown.map((item: any, idx: number) => (
                                        <div key={idx} className="flex items-center justify-between p-3 bg-stone-50 rounded-lg">
                                            <div>
                                                <div className="font-medium text-stone-900">{item.name}</div>
                                                <div className="text-xs text-stone-500">
                                                    {item.unit && `Rp ${Number(item.unit).toLocaleString()} × ${item.qty || 1}`}
                                                    {item.colors && ` × ${item.colors} colors`}
                                                </div>
                                            </div>
                                            <div className="font-bold text-stone-900">
                                                Rp {Number(item.amount).toLocaleString()}
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Applied Rules */}
                            {result.appliedRules && result.appliedRules.length > 0 && (
                                <div>
                                    <h3 className="font-bold text-stone-900 mb-3">Applied Rules</h3>
                                    <div className="space-y-2">
                                        {result.appliedRules.map((rule: any, idx: number) => (
                                            <div key={idx} className="text-xs p-2 bg-blue-50 border border-blue-200 rounded">
                                                <span className="font-mono text-blue-900">{rule.componentCode}</span>
                                                <span className="text-blue-600 mx-2">•</span>
                                                <span className="text-blue-700">{rule.scope}</span>
                                                <span className="text-blue-600 mx-2">•</span>
                                                <span className="text-blue-700">Priority {rule.priority}</span>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, Package, Settings, Eye, Layers, Loader2, Save, Edit } from 'lucide-react';
import { useToast } from '@/components/ui/ToastProvider';
import MockupTemplateEditor from '@/components/admin/MockupTemplateEditor';
import ImageUploadField from '@/components/admin/ImageUploadField';

type Tab = 'details' | 'variants' | 'print-setup' | 'preview';

export default function ProductDetailPage({
    params
}: {
    params: Promise<{ brandSlug: string; id: string }>;
}) {
    const { brandSlug, id } = use(params);
    const router = useRouter();
    const toast = useToast();

    const [product, setProduct] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<Tab>('details');
    const [editing, setEditing] = useState(false);
    const [saving, setSaving] = useState(false);

    const [formData, setFormData] = useState({
        name: '',
        description: '',
        productType: '',
        baseImage: '',
        isCustomizable: true,
        isFeatured: false,
        status: 'active'
    });

    useEffect(() => {
        // Check for 'tab' query param
        const searchParams = new URLSearchParams(window.location.search);
        const tab = searchParams.get('tab');
        if (tab && ['details', 'variants', 'print-setup', 'preview'].includes(tab)) {
            setActiveTab(tab as Tab);
        }

        fetchProduct();
    }, [id]);

    const fetchProduct = async () => {
        try {
            const res = await fetch(`/api/admin/products/${id}`);
            if (res.ok) {
                const data = await res.json();
                setProduct(data);
                setFormData({
                    name: data.name,
                    description: data.description || '',
                    productType: data.productType,
                    baseImage: data.baseImage || '',
                    isCustomizable: data.isCustomizable,
                    isFeatured: data.isFeatured,
                    status: data.status
                });
            } else {
                toast.error('Failed to load product');
            }
        } catch (error) {
            console.error('Error fetching product:', error);
            toast.error('Failed to load product');
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        setSaving(true);
        try {
            const res = await fetch(`/api/admin/products/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData)
            });

            if (res.ok) {
                toast.success('Product updated successfully');
                setEditing(false);
                fetchProduct();
            } else {
                toast.error('Failed to update product');
            }
        } catch (error) {
            console.error('Error updating product:', error);
            toast.error('Failed to update product');
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    if (!product) {
        return (
            <div className="p-6 max-w-7xl mx-auto">
                <div className="text-center py-16">
                    <p className="text-stone-600">Product not found</p>
                </div>
            </div>
        );
    }

    const tabs = [
        { id: 'details' as Tab, label: 'Details', icon: Package },
        { id: 'variants' as Tab, label: 'Variants', icon: Layers },
        { id: 'print-setup' as Tab, label: 'Print Setup', icon: Settings },
        { id: 'preview' as Tab, label: 'Preview', icon: Eye }
    ];

    return (
        <div className="p-6 max-w-7xl mx-auto">
            {/* Header */}
            <div className="flex items-center gap-4 mb-6">
                <Link
                    href={`/dashboard/${brandSlug}/collections/${product.collectionId}`}
                    className="p-2 hover:bg-stone-100 rounded-lg transition-colors"
                >
                    <ArrowLeft className="w-5 h-5" />
                </Link>
                <div className="flex-1">
                    <div className="flex items-center gap-3">
                        <h1 className="text-3xl font-bold text-stone-900">{product.name}</h1>
                        <span className={`px-3 py-1 rounded-full text-sm font-medium ${product.status === 'active'
                            ? 'bg-green-100 text-green-700'
                            : 'bg-stone-100 text-stone-700'
                            }`}>
                            {product.status}
                        </span>
                    </div>
                    <p className="text-stone-600 mt-1">
                        {product.collection?.name} → {product.productType}
                    </p>
                </div>
            </div>

            {/* Tabs */}
            <div className="bg-white rounded-xl border border-stone-200 mb-6">
                <div className="border-b border-stone-200">
                    <div className="flex gap-1 p-2">
                        {tabs.map((tab) => {
                            const Icon = tab.icon;
                            return (
                                <button
                                    key={tab.id}
                                    onClick={() => setActiveTab(tab.id)}
                                    className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-colors ${activeTab === tab.id
                                        ? 'bg-amber-100 text-amber-700 font-medium'
                                        : 'text-stone-600 hover:bg-stone-50'
                                        }`}
                                >
                                    <Icon className="w-4 h-4" />
                                    {tab.label}
                                </button>
                            );
                        })}
                    </div>
                </div>

                {/* Tab Content */}
                <div className="p-6">
                    {activeTab === 'details' && (
                        <div className="space-y-6">
                            <div className="flex items-center justify-between mb-4">
                                <h2 className="text-xl font-bold text-stone-900">Product Details</h2>
                                {!editing ? (
                                    <button
                                        onClick={() => setEditing(true)}
                                        className="flex items-center gap-2 px-4 py-2 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors"
                                    >
                                        <Edit className="w-4 h-4" />
                                        Edit
                                    </button>
                                ) : (
                                    <div className="flex gap-2">
                                        <button
                                            onClick={handleSave}
                                            disabled={saving}
                                            className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors"
                                        >
                                            {saving ? (
                                                <Loader2 className="w-4 h-4 animate-spin" />
                                            ) : (
                                                <Save className="w-4 h-4" />
                                            )}
                                            Save
                                        </button>
                                        <button
                                            onClick={() => {
                                                setEditing(false);
                                                setFormData({
                                                    name: product.name,
                                                    description: product.description || '',
                                                    productType: product.productType,
                                                    baseImage: product.baseImage || '',
                                                    isCustomizable: product.isCustomizable,
                                                    isFeatured: product.isFeatured,
                                                    status: product.status
                                                });
                                            }}
                                            className="px-4 py-2 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors"
                                        >
                                            Cancel
                                        </button>
                                    </div>
                                )}
                            </div>

                            {editing ? (
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-sm font-medium text-stone-700 mb-2">
                                            Product Name
                                        </label>
                                        <input
                                            type="text"
                                            value={formData.name}
                                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-stone-700 mb-2">
                                            Description
                                        </label>
                                        <textarea
                                            value={formData.description}
                                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                            rows={4}
                                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium text-stone-700 mb-2">
                                            Base Image URL
                                        </label>
                                        <ImageUploadField
                                            value={formData.baseImage}
                                            onChange={(url) => setFormData({ ...formData, baseImage: url })}
                                            label="Base Image"
                                            description="Upload product base image (no design)"
                                        />
                                    </div>

                                    <div className="flex items-center gap-3">
                                        <input
                                            type="checkbox"
                                            id="isCustomizable"
                                            checked={formData.isCustomizable}
                                            onChange={(e) => setFormData({ ...formData, isCustomizable: e.target.checked })}
                                            className="w-4 h-4 text-amber-600 border-stone-300 rounded"
                                        />
                                        <label htmlFor="isCustomizable" className="text-sm font-medium text-stone-700">
                                            Allow customization
                                        </label>
                                    </div>

                                    <div className="flex items-center gap-3">
                                        <input
                                            type="checkbox"
                                            id="isFeatured"
                                            checked={formData.isFeatured}
                                            onChange={(e) => setFormData({ ...formData, isFeatured: e.target.checked })}
                                            className="w-4 h-4 text-amber-600 border-stone-300 rounded"
                                        />
                                        <label htmlFor="isFeatured" className="text-sm font-medium text-stone-700">
                                            Featured product
                                        </label>
                                    </div>
                                </div>
                            ) : (
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div>
                                        <h3 className="text-sm font-medium text-stone-600 mb-2">Product Information</h3>
                                        <div className="space-y-3">
                                            <div>
                                                <p className="text-xs text-stone-500">SKU</p>
                                                <p className="text-sm font-medium text-stone-900">{product.sku || 'N/A'}</p>
                                            </div>
                                            <div>
                                                <p className="text-xs text-stone-500">Product Type</p>
                                                <p className="text-sm font-medium text-stone-900">{product.productType}</p>
                                            </div>
                                            <div>
                                                <p className="text-xs text-stone-500">Description</p>
                                                <p className="text-sm text-stone-900">{product.description || 'No description'}</p>
                                            </div>
                                        </div>
                                    </div>

                                    <div>
                                        <h3 className="text-sm font-medium text-stone-600 mb-2">Settings</h3>
                                        <div className="space-y-3">
                                            <div>
                                                <p className="text-xs text-stone-500">Customizable</p>
                                                <p className="text-sm font-medium text-stone-900">
                                                    {product.isCustomizable ? 'Yes' : 'No'}
                                                </p>
                                            </div>
                                            <div>
                                                <p className="text-xs text-stone-500">Featured</p>
                                                <p className="text-sm font-medium text-stone-900">
                                                    {product.isFeatured ? 'Yes' : 'No'}
                                                </p>
                                            </div>
                                            <div>
                                                <p className="text-xs text-stone-500">Variants</p>
                                                <p className="text-sm font-medium text-stone-900">
                                                    {product._count.variants} variants
                                                </p>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {product.baseImage && !editing && (
                                <div>
                                    <h3 className="text-sm font-medium text-stone-600 mb-2">Base Image</h3>
                                    <div className="w-64 h-64 bg-stone-100 rounded-lg overflow-hidden">
                                        <img
                                            src={product.baseImage}
                                            alt={product.name}
                                            className="w-full h-full object-cover"
                                        />
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'variants' && (
                        <div>
                            <div className="flex items-center justify-between mb-4">
                                <h2 className="text-xl font-bold text-stone-900">Product Variants</h2>
                                <Link
                                    href={`/dashboard/${brandSlug}/products/${id}/variants/new`}
                                    className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                                >
                                    <Package className="w-4 h-4" />
                                    Add Variant
                                </Link>
                            </div>

                            {product.variants.length === 0 ? (
                                <div className="text-center py-12 border-2 border-dashed border-stone-300 rounded-lg">
                                    <Layers className="w-12 h-12 text-stone-400 mx-auto mb-3" />
                                    <h3 className="text-lg font-semibold text-stone-900 mb-2">
                                        No Variants Yet
                                    </h3>
                                    <p className="text-stone-600 mb-4">
                                        Create variants for different sizes, materials, or printing methods
                                    </p>
                                    <Link
                                        href={`/dashboard/${brandSlug}/products/${id}/variants/new`}
                                        className="inline-flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                                    >
                                        <Package className="w-4 h-4" />
                                        Add Variant
                                    </Link>
                                </div>
                            ) : (
                                <div className="space-y-3">
                                    {product.variants.map((variant: any) => (
                                        <div
                                            key={variant.id}
                                            className="border border-stone-200 rounded-lg p-4 hover:shadow-md transition-shadow"
                                        >
                                            <div className="flex items-start justify-between">
                                                <div className="flex-1">
                                                    <h3 className="font-bold text-stone-900 mb-1">{variant.name}</h3>
                                                    <p className="text-sm text-stone-600 mb-2">SKU: {variant.sku}</p>
                                                    <div className="flex flex-wrap gap-2">
                                                        {Object.entries(variant.attributes as Record<string, any>).map(([key, value]) => (
                                                            <span
                                                                key={key}
                                                                className="px-2 py-1 bg-stone-100 text-stone-700 rounded text-xs"
                                                            >
                                                                {key}: {value}
                                                            </span>
                                                        ))}
                                                    </div>
                                                </div>
                                                <div className="text-right">
                                                    <p className="text-lg font-bold text-stone-900">
                                                        Rp {Number(variant.basePrice).toLocaleString()}
                                                    </p>
                                                    <p className="text-sm text-stone-600">{variant.stockStatus}</p>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'print-setup' && (
                        <div>
                            <MockupTemplateEditor
                                productId={id}
                                brandSlug={brandSlug}
                            />
                        </div>
                    )}

                    {activeTab === 'preview' && (
                        <div>
                            <h2 className="text-xl font-bold text-stone-900 mb-4">Public Preview</h2>
                            <div className="text-center py-12 border-2 border-dashed border-stone-300 rounded-lg">
                                <Eye className="w-12 h-12 text-stone-400 mx-auto mb-3" />
                                <h3 className="text-lg font-semibold text-stone-900 mb-2">
                                    Preview Coming Soon
                                </h3>
                                <p className="text-stone-600">
                                    See how this product appears to customers
                                </p>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { ArrowLeft, Loader2, Save, Plus, Trash2 } from 'lucide-react';
import { useToast } from '@/components/ui/ToastProvider';

export default function NewVariantPage({
    params
}: {
    params: Promise<{ brandSlug: string; id: string }>;
}) {
    const { brandSlug, id: productId } = use(params);
    const router = useRouter();
    const toast = useToast();

    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [product, setProduct] = useState<any>(null);

    const [formData, setFormData] = useState({
        name: '',
        sku: '',
        basePrice: '',
        stockStatus: 'in-stock',
        stockQuantity: '',
        attributes: [] as { key: string; value: string }[],
        weight: '',
        productionTime: '3-5 days'
    });

    useEffect(() => {
        fetchProduct();
    }, [productId]);

    const fetchProduct = async () => {
        try {
            const res = await fetch(`/api/admin/products/${productId}`);
            if (res.ok) {
                const data = await res.json();
                setProduct(data);

                // Pre-fill name and SKU base
                setFormData(prev => ({
                    ...prev,
                    name: `${data.name} - `,
                    sku: `${data.sku}-`
                }));
            }
        } catch (error) {
            console.error('Error fetching product:', error);
            toast.error('Failed to load product details');
        } finally {
            setLoading(false);
        }
    };

    const handleAttributeChange = (index: number, field: 'key' | 'value', value: string) => {
        const newAttributes = [...formData.attributes];
        newAttributes[index][field] = value;
        setFormData({ ...formData, attributes: newAttributes });
    };

    const addAttribute = () => {
        setFormData({
            ...formData,
            attributes: [...formData.attributes, { key: '', value: '' }]
        });
    };

    const removeAttribute = (index: number) => {
        const newAttributes = formData.attributes.filter((_, i) => i !== index);
        setFormData({ ...formData, attributes: newAttributes });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            // Convert attributes array to object
            const attributesObj = formData.attributes.reduce((acc, curr) => {
                if (curr.key && curr.value) {
                    acc[curr.key] = curr.value;
                }
                return acc;
            }, {} as Record<string, string>);

            const payload = {
                name: formData.name,
                sku: formData.sku,
                basePrice: parseFloat(formData.basePrice),
                stockStatus: formData.stockStatus,
                stockQuantity: formData.stockQuantity ? parseInt(formData.stockQuantity) : null,
                attributes: attributesObj,
                weight: formData.weight ? parseFloat(formData.weight) : null,
                productionTime: formData.productionTime
            };

            const res = await fetch(`/api/admin/products/${productId}/variants`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (res.ok) {
                toast.success('Variant created successfully');
                router.push(`/dashboard/${brandSlug}/products/${productId}?tab=variants`);
            } else {
                const error = await res.json();
                toast.error(error.error || 'Failed to create variant');
            }
        } catch (error) {
            console.error('Error creating variant:', error);
            toast.error('Failed to create variant');
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-6 max-w-4xl mx-auto">
            {/* Header */}
            <div className="flex items-center gap-4 mb-6">
                <Link
                    href={`/dashboard/${brandSlug}/products/${productId}`}
                    className="p-2 hover:bg-stone-100 rounded-lg transition-colors"
                >
                    <ArrowLeft className="w-5 h-5" />
                </Link>
                <div>
                    <h1 className="text-3xl font-bold text-stone-900">Add Variant</h1>
                    <p className="text-stone-600 mt-1">
                        Add a new variant for {product?.name}
                    </p>
                </div>
            </div>

            {/* Form */}
            <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-stone-200 p-6 space-y-8">
                {/* Basic Info */}
                <div className="space-y-4">
                    <h2 className="text-lg font-bold text-stone-900 border-b border-stone-200 pb-2">
                        Basic Information
                    </h2>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Variant Name *
                            </label>
                            <input
                                type="text"
                                value={formData.name}
                                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                required
                                placeholder="e.g., T-Shirt Size S White"
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                SKU *
                            </label>
                            <input
                                type="text"
                                value={formData.sku}
                                onChange={(e) => setFormData({ ...formData, sku: e.target.value })}
                                required
                                placeholder="e.g., TS-WHT-S"
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                            />
                        </div>
                    </div>
                </div>

                {/* Pricing & Inventory */}
                <div className="space-y-4">
                    <h2 className="text-lg font-bold text-stone-900 border-b border-stone-200 pb-2">
                        Pricing & Inventory
                    </h2>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Base Price (Rp) *
                            </label>
                            <input
                                type="number"
                                value={formData.basePrice}
                                onChange={(e) => setFormData({ ...formData, basePrice: e.target.value })}
                                required
                                min="0"
                                placeholder="100000"
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Stock Status *
                            </label>
                            <select
                                value={formData.stockStatus}
                                onChange={(e) => setFormData({ ...formData, stockStatus: e.target.value })}
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                            >
                                <option value="in-stock">In Stock</option>
                                <option value="out-of-stock">Out of Stock</option>
                                <option value="pre-order">Pre-Order</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Stock Quantity
                            </label>
                            <input
                                type="number"
                                value={formData.stockQuantity}
                                onChange={(e) => setFormData({ ...formData, stockQuantity: e.target.value })}
                                min="0"
                                placeholder="Optional"
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Production Time
                            </label>
                            <input
                                type="text"
                                value={formData.productionTime}
                                onChange={(e) => setFormData({ ...formData, productionTime: e.target.value })}
                                placeholder="e.g., 3-5 days"
                                className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                            />
                        </div>
                    </div>
                </div>

                {/* Attributes */}
                <div className="space-y-4">
                    <div className="flex items-center justify-between border-b border-stone-200 pb-2">
                        <h2 className="text-lg font-bold text-stone-900">
                            Attributes
                        </h2>
                        <button
                            type="button"
                            onClick={addAttribute}
                            className="flex items-center gap-1 text-sm font-medium text-amber-600 hover:text-amber-700"
                        >
                            <Plus className="w-4 h-4" />
                            Add Attribute
                        </button>
                    </div>

                    <div className="space-y-3">
                        {formData.attributes.map((attr, index) => (
                            <div key={index} className="flex gap-4 items-start">
                                <div className="flex-1">
                                    <input
                                        type="text"
                                        value={attr.key}
                                        onChange={(e) => handleAttributeChange(index, 'key', e.target.value)}
                                        placeholder="Name (e.g. Size)"
                                        className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                                    />
                                </div>
                                <div className="flex-1">
                                    <input
                                        type="text"
                                        value={attr.value}
                                        onChange={(e) => handleAttributeChange(index, 'value', e.target.value)}
                                        placeholder="Value (e.g. XL)"
                                        className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500"
                                    />
                                </div>
                                <button
                                    type="button"
                                    onClick={() => removeAttribute(index)}
                                    className="p-2 text-stone-400 hover:text-red-500 transition-colors"
                                >
                                    <Trash2 className="w-5 h-5" />
                                </button>
                            </div>
                        ))}
                        {formData.attributes.length === 0 && (
                            <p className="text-sm text-stone-500 italic">
                                Add attributes like Size, Color, or Material to specify this variant.
                            </p>
                        )}
                    </div>
                </div>

                {/* Actions */}
                <div className="flex gap-3 pt-4 border-t border-stone-200">
                    <button
                        type="submit"
                        disabled={saving}
                        className="flex-1 flex items-center justify-center gap-2 px-6 py-3 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors font-medium"
                    >
                        {saving ? (
                            <>
                                <Loader2 className="w-5 h-5 animate-spin" />
                                Creating...
                            </>
                        ) : (
                            <>
                                <Save className="w-5 h-5" />
                                Save Variant
                            </>
                        )}
                    </button>
                    <Link
                        href={`/dashboard/${brandSlug}/products/${productId}`}
                        className="px-6 py-3 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors font-medium"
                    >
                        Cancel
                    </Link>
                </div>
            </form>
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, GripVertical } from 'lucide-react';

interface Service {
    id: string;
    name: string;
    description: string;
    icon?: string;
    features: string[];
    sortOrder: number;
    isActive: boolean;
}

export default function ServicesPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const { brandSlug } = use(params);
    const [services, setServices] = useState<Service[]>([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [editingService, setEditingService] = useState<Service | null>(null);

    useEffect(() => {
        fetchServices();
    }, [brandSlug]);

    const fetchServices = async () => {
        try {
            const res = await fetch(`/api/admin/${brandSlug}/services`);
            const data = await res.json();
            // Ensure data is an array
            setServices(Array.isArray(data) ? data : []);
        } catch (error) {
            console.error('Failed to fetch services:', error);
            setServices([]); // Set empty array on error
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm('Are you sure you want to delete this service?')) return;

        try {
            const res = await fetch(`/api/admin/${brandSlug}/services/${id}`, {
                method: 'DELETE',
            });

            if (res.ok) {
                fetchServices();
            } else {
                alert('Failed to delete service');
            }
        } catch (error) {
            console.error('Failed to delete service:', error);
            alert('Failed to delete service');
        }
    };

    const openEditModal = (service?: Service) => {
        setEditingService(service || null);
        setShowModal(true);
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <div className="text-stone-600">Loading services...</div>
            </div>
        );
    }

    return (
        <div className="p-8">
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">IT Services</h1>
                    <p className="text-stone-600">Manage your IT services and offerings</p>
                </div>
                <button
                    onClick={() => openEditModal()}
                    className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors"
                >
                    <Plus className="w-4 h-4" />
                    Add Service
                </button>
            </div>

            {/* Services List */}
            {services.length === 0 ? (
                <div className="bg-white rounded-xl border border-stone-200 p-12 text-center">
                    <p className="text-stone-600 mb-4">No services yet</p>
                    <button
                        onClick={() => openEditModal()}
                        className="text-blue-600 hover:text-blue-700 font-medium"
                    >
                        Create your first service
                    </button>
                </div>
            ) : (
                <div className="space-y-4">
                    {services.map((service) => (
                        <div
                            key={service.id}
                            className="bg-white rounded-xl border border-stone-200 p-6 flex items-start gap-4"
                        >
                            <div className="cursor-move text-stone-400">
                                <GripVertical className="w-5 h-5" />
                            </div>
                            <div className="flex-1">
                                <div className="flex items-start justify-between mb-2">
                                    <div>
                                        <h3 className="text-lg font-bold text-stone-900">{service.name}</h3>
                                        {service.icon && (
                                            <span className="text-sm text-stone-500">Icon: {service.icon}</span>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <span
                                            className={`px-2 py-1 text-xs rounded-full ${service.isActive
                                                ? 'bg-green-100 text-green-700'
                                                : 'bg-stone-100 text-stone-600'
                                                }`}
                                        >
                                            {service.isActive ? 'Active' : 'Inactive'}
                                        </span>
                                        <button
                                            onClick={() => openEditModal(service)}
                                            className="p-2 text-stone-600 hover:text-blue-600 transition-colors"
                                        >
                                            <Edit2 className="w-4 h-4" />
                                        </button>
                                        <button
                                            onClick={() => handleDelete(service.id)}
                                            className="p-2 text-stone-600 hover:text-red-600 transition-colors"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                                <p className="text-stone-600 mb-3">{service.description}</p>
                                {service.features && service.features.length > 0 && (
                                    <div className="flex flex-wrap gap-2">
                                        {service.features.map((feature, idx) => (
                                            <span
                                                key={idx}
                                                className="px-2 py-1 bg-blue-50 text-blue-700 text-sm rounded"
                                            >
                                                {feature}
                                            </span>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Modal */}
            {showModal && (
                <ServiceModal
                    brandSlug={brandSlug}
                    service={editingService}
                    onClose={() => {
                        setShowModal(false);
                        setEditingService(null);
                    }}
                    onSave={() => {
                        fetchServices();
                        setShowModal(false);
                        setEditingService(null);
                    }}
                />
            )}
        </div>
    );
}

function ServiceModal({
    brandSlug,
    service,
    onClose,
    onSave,
}: {
    brandSlug: string;
    service: Service | null;
    onClose: () => void;
    onSave: () => void;
}) {
    const [formData, setFormData] = useState({
        name: service?.name || '',
        description: service?.description || '',
        icon: service?.icon || '',
        features: service?.features?.join('\n') || '',
        isActive: service?.isActive !== undefined ? service.isActive : true,
    });
    const [saving, setSaving] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const url = service
                ? `/api/admin/${brandSlug}/services/${service.id}`
                : `/api/admin/${brandSlug}/services`;
            const method = service ? 'PUT' : 'POST';

            const res = await fetch(url, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    ...formData,
                    features: formData.features.split('\n').filter((f) => f.trim()),
                }),
            });

            if (res.ok) {
                onSave();
            } else {
                alert('Failed to save service');
            }
        } catch (error) {
            console.error('Failed to save service:', error);
            alert('Failed to save service');
        } finally {
            setSaving(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                <div className="p-6 border-b border-stone-200">
                    <h2 className="text-xl font-bold text-stone-900">
                        {service ? 'Edit Service' : 'Add New Service'}
                    </h2>
                </div>

                <form onSubmit={handleSubmit} className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Service Name *
                        </label>
                        <input
                            type="text"
                            value={formData.name}
                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                            required
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="Web Development"
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Description *
                        </label>
                        <textarea
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                            required
                            rows={3}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="Custom web applications built with modern technologies"
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Icon (Lucide icon name)
                        </label>
                        <input
                            type="text"
                            value={formData.icon}
                            onChange={(e) => setFormData({ ...formData, icon: e.target.value })}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="Code"
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-2">
                            Features (one per line)
                        </label>
                        <textarea
                            value={formData.features}
                            onChange={(e) => setFormData({ ...formData, features: e.target.value })}
                            rows={5}
                            className="w-full px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none"
                            placeholder="Responsive Design&#10;API Integration&#10;Database Management"
                        />
                    </div>

                    <div className="flex items-center gap-2">
                        <input
                            type="checkbox"
                            id="isActive"
                            checked={formData.isActive}
                            onChange={(e) => setFormData({ ...formData, isActive: e.target.checked })}
                            className="w-4 h-4 text-blue-600 border-stone-300 rounded focus:ring-blue-500"
                        />
                        <label htmlFor="isActive" className="text-sm font-medium text-stone-700">
                            Active
                        </label>
                    </div>

                    <div className="flex justify-end gap-3 pt-4">
                        <button
                            type="button"
                            onClick={onClose}
                            className="px-4 py-2 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            disabled={saving}
                            className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors disabled:opacity-50"
                        >
                            {saving ? 'Saving...' : 'Save Service'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect, use } from 'react';
import { Save, Loader2, AlertCircle } from 'lucide-react';

export default function BrandSettingsPage({ params }: { params: Promise<{ brandSlug: string }> }) {
    const resolvedParams = use(params);
    const { brandSlug } = resolvedParams;

    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [settings, setSettings] = useState<any>({ downPaymentPercentage: 50 });

    useEffect(() => {
        const fetchSettings = async () => {
            try {
                const res = await fetch(`/api/admin/brands/${brandSlug}/settings`);
                if (res.ok) {
                    const data = await res.json();
                    setSettings(data.paymentSettings);
                }
            } catch (error) {
                console.error('Failed to load settings', error);
            } finally {
                setIsLoading(false);
            }
        };
        fetchSettings();
    }, [brandSlug]);

    const handleSave = async () => {
        setIsSaving(true);
        try {
            const res = await fetch(`/api/admin/brands/${brandSlug}/settings`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(settings)
            });

            if (res.ok) {
                alert('Settings verified! New orders will use this logic.');
            } else {
                throw new Error('Failed to save');
            }
        } catch (error) {
            alert('Error saving settings');
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) return <div className="p-12 text-center text-stone-500"><Loader2 className="w-8 h-8 animate-spin mx-auto mb-2" />Loading Settings...</div>;

    return (
        <div className="max-w-2xl mx-auto space-y-6">
            <h1 className="text-2xl font-bold text-stone-900">Payment Settings</h1>

            <div className="bg-white rounded-xl border border-stone-200 p-6 shadow-sm">
                <div className="flex items-center gap-2 mb-6 p-4 bg-amber-50 text-amber-800 rounded-lg text-sm">
                    <AlertCircle className="w-5 h-5 flex-shrink-0" />
                    <div>
                        These settings allow you to control the Down Payment percentage for your customers.
                        Changes apply immediately to <strong>new orders</strong>.
                    </div>
                </div>

                <div className="space-y-6">
                    <div>
                        <label className="block text-sm font-bold text-stone-900 mb-2">
                            Down Payment Percentage (%)
                        </label>
                        <div className="flex items-center gap-3">
                            <input
                                type="number"
                                min="0"
                                max="100"
                                value={settings.downPaymentPercentage}
                                onChange={(e) => setSettings({ ...settings, downPaymentPercentage: Number(e.target.value) })}
                                className="w-32 p-3 bg-stone-50 border border-stone-200 rounded-lg font-mono font-bold text-xl text-center focus:ring-2 focus:ring-amber-500 outline-none"
                            />
                            <span className="text-stone-500 font-medium">%</span>
                        </div>
                        <p className="text-sm text-stone-500 mt-2">
                            Example: If 30%, customer pays 30% first, then 70% later.
                        </p>
                    </div>
                </div>

                <div className="pt-6 mt-6 border-t border-stone-100">
                    <button
                        onClick={handleSave}
                        disabled={isSaving}
                        className="flex items-center gap-2 px-6 py-3 bg-stone-900 text-white rounded-lg font-bold hover:bg-stone-800 transition-colors disabled:opacity-50"
                    >
                        {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                        Save Settings
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import FormField from '@/components/admin/FormField';
import { Save, Loader2, ArrowLeft, Plus, X } from 'lucide-react';
import Link from 'next/link';

interface UseCase {
    title: string;
    description: string;
}

interface FAQ {
    question: string;
    answer: string;
}

export default function CollectionEditorPage({ params }: { params: { slug: string } }) {
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [formData, setFormData] = useState({
        name: '',
        heroTitle: '',
        heroSubtitle: '',
        highlights: [] as string[],
        whatsInside: [] as string[],
        designOptions: [] as string[],
        materialPoints: [] as string[],
        useCases: [] as UseCase[],
        packagingOptions: [] as string[],
        faq: [] as FAQ[],
        galleryImages: [] as string[],
    });

    useEffect(() => {
        fetch(`/api/admin/collections/${params.slug}`)
            .then((res) => res.json())
            .then((data) => {
                if (data) {
                    setFormData({
                        name: data.name || '',
                        heroTitle: data.heroTitle || '',
                        heroSubtitle: data.heroSubtitle || '',
                        highlights: Array.isArray(data.highlights) ? data.highlights : JSON.parse(data.highlights || '[]'),
                        whatsInside: Array.isArray(data.whatsInside) ? data.whatsInside : JSON.parse(data.whatsInside || '[]'),
                        designOptions: Array.isArray(data.designOptions) ? data.designOptions : JSON.parse(data.designOptions || '[]'),
                        materialPoints: Array.isArray(data.materialPoints) ? data.materialPoints : JSON.parse(data.materialPoints || '[]'),
                        useCases: Array.isArray(data.useCases) ? data.useCases : JSON.parse(data.useCases || '[]'),
                        packagingOptions: Array.isArray(data.packagingOptions) ? data.packagingOptions : JSON.parse(data.packagingOptions || '[]'),
                        faq: Array.isArray(data.faq) ? data.faq : JSON.parse(data.faq || '[]'),
                        galleryImages: Array.isArray(data.galleryImages) ? data.galleryImages : JSON.parse(data.galleryImages || '[]'),
                    });
                }
                setLoading(false);
            })
            .catch((err) => {
                console.error('Failed to fetch collection:', err);
                setLoading(false);
            });
    }, [params.slug]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormData((prev) => ({ ...prev, [name]: value }));
    };

    const handleArrayChange = (field: keyof typeof formData, value: string) => {
        const items = value.split('\n').filter((item) => item.trim());
        setFormData((prev) => ({ ...prev, [field]: items }));
    };

    const addUseCase = () => {
        setFormData((prev) => ({
            ...prev,
            useCases: [...prev.useCases, { title: '', description: '' }],
        }));
    };

    const updateUseCase = (index: number, field: 'title' | 'description', value: string) => {
        setFormData((prev) => ({
            ...prev,
            useCases: prev.useCases.map((uc, i) => (i === index ? { ...uc, [field]: value } : uc)),
        }));
    };

    const removeUseCase = (index: number) => {
        setFormData((prev) => ({
            ...prev,
            useCases: prev.useCases.filter((_, i) => i !== index),
        }));
    };

    const addFAQ = () => {
        setFormData((prev) => ({
            ...prev,
            faq: [...prev.faq, { question: '', answer: '' }],
        }));
    };

    const updateFAQ = (index: number, field: 'question' | 'answer', value: string) => {
        setFormData((prev) => ({
            ...prev,
            faq: prev.faq.map((f, i) => (i === index ? { ...f, [field]: value } : f)),
        }));
    };

    const removeFAQ = (index: number) => {
        setFormData((prev) => ({
            ...prev,
            faq: prev.faq.filter((_, i) => i !== index),
        }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const res = await fetch(`/api/admin/collections/${params.slug}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData),
            });

            if (!res.ok) throw new Error('Failed to update');

            router.refresh();
            alert('Collection saved successfully!');
        } catch (error) {
            alert('Error saving collection');
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-8 max-w-5xl mx-auto">
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-4">
                    <Link
                        href="/dashboard/collections"
                        className="p-2 hover:bg-stone-100 rounded-lg transition-colors"
                    >
                        <ArrowLeft className="w-5 h-5" />
                    </Link>
                    <div>
                        <h1 className="text-2xl font-bold text-stone-900">Edit Collection</h1>
                        <p className="text-stone-600">{formData.name}</p>
                    </div>
                </div>
                <button
                    onClick={handleSubmit}
                    disabled={saving}
                    className="flex items-center gap-2 px-6 py-2.5 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors"
                >
                    {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Save Changes
                </button>
            </div>

            {/* Form */}
            <div className="space-y-6">
                {/* Basic Info */}
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                    <h2 className="text-lg font-semibold text-stone-900 mb-4">Basic Information</h2>
                    <div className="space-y-4">
                        <FormField
                            label="Collection Name"
                            name="name"
                            value={formData.name}
                            onChange={handleChange}
                        />
                        <FormField
                            label="Hero Title"
                            name="heroTitle"
                            value={formData.heroTitle}
                            onChange={handleChange}
                        />
                        <FormField
                            label="Hero Subtitle"
                            name="heroSubtitle"
                            value={formData.heroSubtitle}
                            onChange={handleChange}
                            isTextArea
                        />
                    </div>
                </div>

                {/* Highlights */}
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                    <h2 className="text-lg font-semibold text-stone-900 mb-4">Highlights</h2>
                    <FormField
                        label="Highlights (one per line)"
                        value={formData.highlights.join('\n')}
                        onChange={(e) => handleArrayChange('highlights', e.target.value)}
                        isTextArea
                        helperText="Enter each highlight on a new line"
                    />
                </div>

                {/* What's Inside */}
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                    <h2 className="text-lg font-semibold text-stone-900 mb-4">What's Inside</h2>
                    <FormField
                        label="Items (one per line)"
                        value={formData.whatsInside.join('\n')}
                        onChange={(e) => handleArrayChange('whatsInside', e.target.value)}
                        isTextArea
                    />
                </div>

                {/* Design Options */}
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                    <h2 className="text-lg font-semibold text-stone-900 mb-4">Design Options</h2>
                    <FormField
                        label="Options (one per line)"
                        value={formData.designOptions.join('\n')}
                        onChange={(e) => handleArrayChange('designOptions', e.target.value)}
                        isTextArea
                    />
                </div>

                {/* Material Points */}
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                    <h2 className="text-lg font-semibold text-stone-900 mb-4">Material Points</h2>
                    <FormField
                        label="Materials (one per line)"
                        value={formData.materialPoints.join('\n')}
                        onChange={(e) => handleArrayChange('materialPoints', e.target.value)}
                        isTextArea
                    />
                </div>

                {/* Use Cases */}
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                    <div className="flex items-center justify-between mb-4">
                        <h2 className="text-lg font-semibold text-stone-900">Use Cases</h2>
                        <button
                            onClick={addUseCase}
                            className="flex items-center gap-2 px-4 py-2 text-sm bg-amber-100 text-amber-700 rounded-lg hover:bg-amber-200 transition-colors"
                        >
                            <Plus className="w-4 h-4" />
                            Add Use Case
                        </button>
                    </div>
                    <div className="space-y-4">
                        {formData.useCases.map((useCase, index) => (
                            <div key={index} className="p-4 border border-stone-200 rounded-lg relative">
                                <button
                                    onClick={() => removeUseCase(index)}
                                    className="absolute top-2 right-2 p-1 text-red-600 hover:bg-red-50 rounded"
                                >
                                    <X className="w-4 h-4" />
                                </button>
                                <div className="space-y-3 pr-8">
                                    <FormField
                                        label="Title"
                                        value={useCase.title}
                                        onChange={(e) => updateUseCase(index, 'title', e.target.value)}
                                    />
                                    <FormField
                                        label="Description"
                                        value={useCase.description}
                                        onChange={(e) => updateUseCase(index, 'description', e.target.value)}
                                        isTextArea
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Packaging Options */}
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                    <h2 className="text-lg font-semibold text-stone-900 mb-4">Packaging Options</h2>
                    <FormField
                        label="Options (one per line)"
                        value={formData.packagingOptions.join('\n')}
                        onChange={(e) => handleArrayChange('packagingOptions', e.target.value)}
                        isTextArea
                    />
                </div>

                {/* FAQ */}
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                    <div className="flex items-center justify-between mb-4">
                        <h2 className="text-lg font-semibold text-stone-900">FAQ</h2>
                        <button
                            onClick={addFAQ}
                            className="flex items-center gap-2 px-4 py-2 text-sm bg-amber-100 text-amber-700 rounded-lg hover:bg-amber-200 transition-colors"
                        >
                            <Plus className="w-4 h-4" />
                            Add FAQ
                        </button>
                    </div>
                    <div className="space-y-4">
                        {formData.faq.map((item, index) => (
                            <div key={index} className="p-4 border border-stone-200 rounded-lg relative">
                                <button
                                    onClick={() => removeFAQ(index)}
                                    className="absolute top-2 right-2 p-1 text-red-600 hover:bg-red-50 rounded"
                                >
                                    <X className="w-4 h-4" />
                                </button>
                                <div className="space-y-3 pr-8">
                                    <FormField
                                        label="Question"
                                        value={item.question}
                                        onChange={(e) => updateFAQ(index, 'question', e.target.value)}
                                    />
                                    <FormField
                                        label="Answer"
                                        value={item.answer}
                                        onChange={(e) => updateFAQ(index, 'answer', e.target.value)}
                                        isTextArea
                                    />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Gallery Images */}
                <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                    <h2 className="text-lg font-semibold text-stone-900 mb-4">Gallery Images</h2>
                    <FormField
                        label="Image URLs (one per line)"
                        value={formData.galleryImages.join('\n')}
                        onChange={(e) => handleArrayChange('galleryImages', e.target.value)}
                        isTextArea
                        helperText="Enter full image URLs, one per line"
                    />
                </div>
            </div>
        </div>
    );
}

