'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import FormField from '@/components/admin/FormField';
import { Save, Loader2 } from 'lucide-react';

export default function MockupEditorPage() {
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [formData, setFormData] = useState({
        mockupTitle: '',
        mockupSubtitle: '',
        mockupTagline: '',
        mockupEnabled: true,
    });

    useEffect(() => {
        fetch('/api/admin/merch-settings')
            .then((res) => res.json())
            .then((data) => {
                if (data) {
                    setFormData({
                        mockupTitle: data.mockupTitle || '',
                        mockupSubtitle: data.mockupSubtitle || '',
                        mockupTagline: data.mockupTagline || '',
                        mockupEnabled: data.mockupEnabled ?? true,
                    });
                }
                setLoading(false);
            })
            .catch((err) => {
                console.error('Failed to fetch settings:', err);
                setLoading(false);
            });
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value, type } = e.target;
        const checked = (e.target as HTMLInputElement).checked;
        setFormData((prev) => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value,
        }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const res = await fetch('/api/admin/merch-settings', {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData),
            });

            if (!res.ok) throw new Error('Failed to update');

            router.refresh();
            alert('Mockup settings saved successfully!');
        } catch (error) {
            alert('Error saving settings');
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-8 max-w-4xl mx-auto">
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Try Live Mockup</h1>
                    <p className="text-stone-600">Configure the mockup builder section</p>
                </div>
                <button
                    onClick={handleSubmit}
                    disabled={saving}
                    className="flex items-center gap-2 px-6 py-2.5 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors"
                >
                    {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Save Changes
                </button>
            </div>

            <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6 space-y-6">
                <div className="flex items-center gap-3 p-4 bg-amber-50 border border-amber-200 rounded-lg">
                    <input
                        type="checkbox"
                        id="mockupEnabled"
                        name="mockupEnabled"
                        checked={formData.mockupEnabled}
                        onChange={handleChange}
                        className="w-5 h-5 text-amber-600 rounded focus:ring-amber-500"
                    />
                    <label htmlFor="mockupEnabled" className="text-sm font-medium text-stone-900">
                        Enable Try Live Mockup Section
                    </label>
                </div>

                <FormField
                    label="Section Title"
                    name="mockupTitle"
                    value={formData.mockupTitle}
                    onChange={handleChange}
                    placeholder="e.g. Try Live Mockup — See Your Brand Come to Life"
                />

                <FormField
                    label="Subtitle"
                    name="mockupSubtitle"
                    value={formData.mockupSubtitle}
                    onChange={handleChange}
                    isTextArea
                    placeholder="Brief description of the mockup feature..."
                />

                <FormField
                    label="Tagline"
                    name="mockupTagline"
                    value={formData.mockupTagline}
                    onChange={handleChange}
                    placeholder="e.g. Fast, accurate, and completely free to try."
                />
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Loader2, Mail, Phone, Building2, Calendar } from 'lucide-react';

interface CatalogueRequest {
    id: string;
    companyName: string;
    contactName: string;
    email: string;
    phone: string | null;
    notes: string | null;
    status: string;
    createdAt: string;
}

interface PaginationData {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
}

export default function CatalogueRequestsPage() {
    const [requests, setRequests] = useState<CatalogueRequest[]>([]);
    const [pagination, setPagination] = useState<PaginationData>({
        page: 1,
        limit: 20,
        total: 0,
        totalPages: 0
    });
    const [loading, setLoading] = useState(true);
    const [statusFilter, setStatusFilter] = useState<string>('');

    useEffect(() => {
        fetchRequests();
    }, [pagination.page, statusFilter]);

    const fetchRequests = async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({
                page: pagination.page.toString(),
                limit: pagination.limit.toString()
            });
            if (statusFilter) {
                params.append('status', statusFilter);
            }

            const res = await fetch(`/api/admin/merch/catalogue-requests?${params}`);
            const data = await res.json();
            setRequests(data.requests || []);
            setPagination(data.pagination);
        } catch (error) {
            console.error('Failed to fetch requests:', error);
        } finally {
            setLoading(false);
        }
    };

    const formatDate = (dateString: string) => {
        return new Date(dateString).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'NEW':
                return 'bg-blue-100 text-blue-800';
            case 'IN_PROGRESS':
                return 'bg-yellow-100 text-yellow-800';
            case 'DONE':
                return 'bg-green-100 text-green-800';
            default:
                return 'bg-stone-100 text-stone-800';
        }
    };

    if (loading && requests.length === 0) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-8 max-w-7xl mx-auto">
            <div className="mb-8">
                <h1 className="text-2xl font-bold text-stone-900 mb-2">Catalogue Requests</h1>
                <p className="text-stone-600">View and manage catalogue requests from customers</p>
            </div>

            {/* Filters */}
            <div className="mb-6 flex gap-4">
                <select
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                    className="px-4 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                >
                    <option value="">All Status</option>
                    <option value="NEW">New</option>
                    <option value="IN_PROGRESS">In Progress</option>
                    <option value="DONE">Done</option>
                </select>
            </div>

            {/* Requests List */}
            {requests.length === 0 ? (
                <div className="text-center py-12 bg-stone-50 rounded-xl border border-stone-200">
                    <p className="text-stone-600">No catalogue requests yet</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {requests.map((request) => (
                        <div
                            key={request.id}
                            className="bg-white rounded-xl border border-stone-200 shadow-sm p-6 hover:shadow-md transition-shadow"
                        >
                            <div className="flex items-start justify-between mb-4">
                                <div className="flex-1">
                                    <div className="flex items-center gap-3 mb-2">
                                        <h3 className="text-lg font-semibold text-stone-900">
                                            {request.contactName}
                                        </h3>
                                        <span className={`px-2 py-1 text-xs font-medium rounded-full ${getStatusColor(request.status)}`}>
                                            {request.status}
                                        </span>
                                    </div>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-sm text-stone-600">
                                        <div className="flex items-center gap-2">
                                            <Building2 className="w-4 h-4" />
                                            {request.companyName}
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <Mail className="w-4 h-4" />
                                            {request.email}
                                        </div>
                                        {request.phone && (
                                            <div className="flex items-center gap-2">
                                                <Phone className="w-4 h-4" />
                                                {request.phone}
                                            </div>
                                        )}
                                        <div className="flex items-center gap-2">
                                            <Calendar className="w-4 h-4" />
                                            {formatDate(request.createdAt)}
                                        </div>
                                    </div>
                                </div>
                            </div>
                            {request.notes && (
                                <div className="mt-4 p-3 bg-stone-50 rounded-lg">
                                    <p className="text-sm text-stone-700">
                                        <span className="font-medium">Notes:</span> {request.notes}
                                    </p>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            )}

            {/* Pagination */}
            {pagination.totalPages > 1 && (
                <div className="mt-6 flex items-center justify-between">
                    <p className="text-sm text-stone-600">
                        Showing {((pagination.page - 1) * pagination.limit) + 1} to{' '}
                        {Math.min(pagination.page * pagination.limit, pagination.total)} of{' '}
                        {pagination.total} requests
                    </p>
                    <div className="flex gap-2">
                        <button
                            onClick={() => setPagination({ ...pagination, page: pagination.page - 1 })}
                            disabled={pagination.page === 1}
                            className="px-4 py-2 border border-stone-300 rounded-lg hover:bg-stone-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                        >
                            Previous
                        </button>
                        <button
                            onClick={() => setPagination({ ...pagination, page: pagination.page + 1 })}
                            disabled={pagination.page === pagination.totalPages}
                            className="px-4 py-2 border border-stone-300 rounded-lg hover:bg-stone-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                        >
                            Next
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { use, useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Save, Loader2, ArrowLeft, Plus, Trash2 } from 'lucide-react';

interface Collection {
    id: string;
    slug: string;
    name: string;
    heroTitle: string;
    heroSubtitle: string;
    highlights: string[];
    whatsInside: string[];
    designOptions: string[];
    materialPoints: string[];
    useCases: Array<{ title: string; description: string }>;
    packagingOptions: string[];
    faq: Array<{ question: string; answer: string }>;
    galleryImages: string[];
}

export default function EditCollectionPage({ params }: { params: Promise<{ id: string }> }) {
    const { id } = use(params);
    const router = useRouter();
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [collection, setCollection] = useState<Collection | null>(null);
    const [activeTab, setActiveTab] = useState('basic');

    useEffect(() => {
        fetchCollection();
    }, [id]);

    const fetchCollection = async () => {
        try {
            const res = await fetch(`/api/admin/merch/collections/${id}`);
            const data = await res.json();
            setCollection(data);
        } catch (error) {
            console.error('Failed to fetch collection:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        if (!collection) return;
        setSaving(true);

        try {
            const res = await fetch(`/api/admin/merch/collections/${id}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(collection)
            });

            if (!res.ok) {
                alert('Failed to save collection');
                return;
            }

            alert('Collection saved successfully!');
        } catch (error) {
            alert('Error saving collection');
        } finally {
            setSaving(false);
        }
    };

    const addArrayItem = (field: keyof Collection, defaultValue: any) => {
        if (!collection) return;
        setCollection({
            ...collection,
            [field]: [...(collection[field] as any[]), defaultValue]
        });
    };

    const removeArrayItem = (field: keyof Collection, index: number) => {
        if (!collection) return;
        const newArray = [...(collection[field] as any[])];
        newArray.splice(index, 1);
        setCollection({
            ...collection,
            [field]: newArray
        });
    };

    const updateArrayItem = (field: keyof Collection, index: number, value: any) => {
        if (!collection) return;
        const newArray = [...(collection[field] as any[])];
        newArray[index] = value;
        setCollection({
            ...collection,
            [field]: newArray
        });
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    if (!collection) {
        return (
            <div className="p-8">
                <p className="text-stone-600">Collection not found</p>
            </div>
        );
    }

    const tabs = [
        { id: 'basic', label: 'Basic Info' },
        { id: 'highlights', label: 'Highlights' },
        { id: 'whatsInside', label: "What's Inside" },
        { id: 'designOptions', label: 'Design Options' },
        { id: 'material', label: 'Material & Quality' },
        { id: 'faq', label: 'FAQ' },
        { id: 'gallery', label: 'Gallery' }
    ];

    return (
        <div className="p-8 max-w-5xl mx-auto">
            <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-4">
                    <button
                        onClick={() => router.push('/dashboard/merch/content/collections')}
                        className="p-2 hover:bg-stone-100 rounded-lg transition-colors"
                    >
                        <ArrowLeft className="w-5 h-5" />
                    </button>
                    <div>
                        <h1 className="text-2xl font-bold text-stone-900">Edit Collection</h1>
                        <p className="text-stone-600">{collection.name}</p>
                    </div>
                </div>
                <button
                    onClick={handleSave}
                    disabled={saving}
                    className="flex items-center gap-2 px-6 py-2.5 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors"
                >
                    {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                    Save Changes
                </button>
            </div>

            {/* Tabs */}
            <div className="flex gap-2 mb-6 overflow-x-auto pb-2">
                {tabs.map((tab) => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id)}
                        className={`px-4 py-2 rounded-lg font-medium whitespace-nowrap transition-colors ${activeTab === tab.id
                                ? 'bg-amber-100 text-amber-900'
                                : 'bg-stone-100 text-stone-600 hover:bg-stone-200'
                            }`}
                    >
                        {tab.label}
                    </button>
                ))}
            </div>

            {/* Tab Content */}
            <div className="bg-white rounded-xl border border-stone-200 shadow-sm p-6">
                {activeTab === 'basic' && (
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-1">
                                Collection Name
                            </label>
                            <input
                                type="text"
                                value={collection.name}
                                onChange={(e) => setCollection({ ...collection, name: e.target.value })}
                                className="w-full px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-1">
                                Slug
                            </label>
                            <input
                                type="text"
                                value={collection.slug}
                                onChange={(e) => setCollection({ ...collection, slug: e.target.value })}
                                className="w-full px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-1">
                                Hero Title
                            </label>
                            <input
                                type="text"
                                value={collection.heroTitle}
                                onChange={(e) => setCollection({ ...collection, heroTitle: e.target.value })}
                                className="w-full px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-1">
                                Hero Subtitle
                            </label>
                            <textarea
                                value={collection.heroSubtitle}
                                onChange={(e) => setCollection({ ...collection, heroSubtitle: e.target.value })}
                                className="w-full px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                rows={3}
                            />
                        </div>
                    </div>
                )}

                {activeTab === 'highlights' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="font-medium text-stone-900">Highlight Badges</h3>
                            <button
                                onClick={() => addArrayItem('highlights', '')}
                                className="flex items-center gap-1 px-3 py-1.5 text-sm text-amber-700 hover:bg-amber-50 rounded-lg transition-colors"
                            >
                                <Plus className="w-4 h-4" />
                                Add Highlight
                            </button>
                        </div>
                        {collection.highlights.map((highlight, index) => (
                            <div key={index} className="flex gap-2">
                                <input
                                    type="text"
                                    value={highlight}
                                    onChange={(e) => updateArrayItem('highlights', index, e.target.value)}
                                    className="flex-1 px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    placeholder="e.g. Premium Quality"
                                />
                                <button
                                    onClick={() => removeArrayItem('highlights', index)}
                                    className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        ))}
                    </div>
                )}

                {activeTab === 'whatsInside' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="font-medium text-stone-900">What's Inside Items</h3>
                            <button
                                onClick={() => addArrayItem('whatsInside', '')}
                                className="flex items-center gap-1 px-3 py-1.5 text-sm text-amber-700 hover:bg-amber-50 rounded-lg transition-colors"
                            >
                                <Plus className="w-4 h-4" />
                                Add Item
                            </button>
                        </div>
                        {collection.whatsInside.map((item, index) => (
                            <div key={index} className="flex gap-2">
                                <input
                                    type="text"
                                    value={item}
                                    onChange={(e) => updateArrayItem('whatsInside', index, e.target.value)}
                                    className="flex-1 px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    placeholder="e.g. T-Shirts"
                                />
                                <button
                                    onClick={() => removeArrayItem('whatsInside', index)}
                                    className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        ))}
                    </div>
                )}

                {activeTab === 'designOptions' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="font-medium text-stone-900">Design Options</h3>
                            <button
                                onClick={() => addArrayItem('designOptions', '')}
                                className="flex items-center gap-1 px-3 py-1.5 text-sm text-amber-700 hover:bg-amber-50 rounded-lg transition-colors"
                            >
                                <Plus className="w-4 h-4" />
                                Add Option
                            </button>
                        </div>
                        {collection.designOptions.map((option, index) => (
                            <div key={index} className="flex gap-2">
                                <input
                                    type="text"
                                    value={option}
                                    onChange={(e) => updateArrayItem('designOptions', index, e.target.value)}
                                    className="flex-1 px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    placeholder="e.g. Screen Printing"
                                />
                                <button
                                    onClick={() => removeArrayItem('designOptions', index)}
                                    className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        ))}
                    </div>
                )}

                {activeTab === 'material' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="font-medium text-stone-900">Material & Quality Points</h3>
                            <button
                                onClick={() => addArrayItem('materialPoints', '')}
                                className="flex items-center gap-1 px-3 py-1.5 text-sm text-amber-700 hover:bg-amber-50 rounded-lg transition-colors"
                            >
                                <Plus className="w-4 h-4" />
                                Add Point
                            </button>
                        </div>
                        {collection.materialPoints.map((point, index) => (
                            <div key={index} className="flex gap-2">
                                <input
                                    type="text"
                                    value={point}
                                    onChange={(e) => updateArrayItem('materialPoints', index, e.target.value)}
                                    className="flex-1 px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    placeholder="e.g. 100% Premium Cotton"
                                />
                                <button
                                    onClick={() => removeArrayItem('materialPoints', index)}
                                    className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        ))}
                    </div>
                )}

                {activeTab === 'faq' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="font-medium text-stone-900">FAQ</h3>
                            <button
                                onClick={() => addArrayItem('faq', { question: '', answer: '' })}
                                className="flex items-center gap-1 px-3 py-1.5 text-sm text-amber-700 hover:bg-amber-50 rounded-lg transition-colors"
                            >
                                <Plus className="w-4 h-4" />
                                Add FAQ
                            </button>
                        </div>
                        {collection.faq.map((item, index) => (
                            <div key={index} className="p-4 border border-stone-200 rounded-lg space-y-2">
                                <div className="flex items-start justify-between gap-2">
                                    <input
                                        type="text"
                                        value={item.question}
                                        onChange={(e) => updateArrayItem('faq', index, { ...item, question: e.target.value })}
                                        className="flex-1 px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                        placeholder="Question"
                                    />
                                    <button
                                        onClick={() => removeArrayItem('faq', index)}
                                        className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                                <textarea
                                    value={item.answer}
                                    onChange={(e) => updateArrayItem('faq', index, { ...item, answer: e.target.value })}
                                    className="w-full px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    rows={2}
                                    placeholder="Answer"
                                />
                            </div>
                        ))}
                    </div>
                )}

                {activeTab === 'gallery' && (
                    <div className="space-y-4">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="font-medium text-stone-900">Gallery Images</h3>
                            <button
                                onClick={() => addArrayItem('galleryImages', '')}
                                className="flex items-center gap-1 px-3 py-1.5 text-sm text-amber-700 hover:bg-amber-50 rounded-lg transition-colors"
                            >
                                <Plus className="w-4 h-4" />
                                Add Image
                            </button>
                        </div>
                        <p className="text-sm text-stone-600">Enter image URLs for the gallery</p>
                        {collection.galleryImages.map((url, index) => (
                            <div key={index} className="flex gap-2">
                                <input
                                    type="text"
                                    value={url}
                                    onChange={(e) => updateArrayItem('galleryImages', index, e.target.value)}
                                    className="flex-1 px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    placeholder="https://..."
                                />
                                <button
                                    onClick={() => removeArrayItem('galleryImages', index)}
                                    className="p-2 text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Plus, Edit, Trash2, Loader2 } from 'lucide-react';

interface Collection {
    id: string;
    slug: string;
    name: string;
    heroTitle: string;
    heroSubtitle: string;
    createdAt: string;
}

export default function CollectionsPage() {
    const router = useRouter();
    const [collections, setCollections] = useState<Collection[]>([]);
    const [loading, setLoading] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [formData, setFormData] = useState({
        name: '',
        heroTitle: '',
        heroSubtitle: '',
        slug: ''
    });
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        fetchCollections();
    }, []);

    const fetchCollections = async () => {
        try {
            const res = await fetch('/api/admin/merch/collections');
            const data = await res.json();
            setCollections(Array.isArray(data) ? data : []);
        } catch (error) {
            console.error('Failed to fetch collections:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreate = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);

        try {
            const res = await fetch('/api/admin/merch/collections', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData)
            });

            if (!res.ok) {
                const error = await res.json();
                alert(error.error || 'Failed to create collection');
                return;
            }

            setShowModal(false);
            setFormData({ name: '', heroTitle: '', heroSubtitle: '', slug: '' });
            fetchCollections();
        } catch (error) {
            alert('Error creating collection');
        } finally {
            setSaving(false);
        }
    };

    const handleDelete = async (id: string, name: string) => {
        if (!confirm(`Delete collection "${name}"? This cannot be undone.`)) return;

        try {
            const res = await fetch(`/api/admin/merch/collections/${id}`, {
                method: 'DELETE'
            });

            if (!res.ok) {
                alert('Failed to delete collection');
                return;
            }

            fetchCollections();
        } catch (error) {
            alert('Error deleting collection');
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-full">
                <Loader2 className="w-8 h-8 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="p-8 max-w-7xl mx-auto">
            <div className="flex items-center justify-between mb-8">
                <div>
                    <h1 className="text-2xl font-bold text-stone-900">Collections</h1>
                    <p className="text-stone-600">Manage your merchandise collections</p>
                </div>
                <button
                    onClick={() => setShowModal(true)}
                    className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                >
                    <Plus className="w-4 h-4" />
                    Add Collection
                </button>
            </div>

            {collections.length === 0 ? (
                <div className="text-center py-12 bg-stone-50 rounded-xl border border-stone-200">
                    <p className="text-stone-600 mb-4">No collections yet</p>
                    <button
                        onClick={() => setShowModal(true)}
                        className="text-amber-600 hover:text-amber-700 font-medium"
                    >
                        Create your first collection
                    </button>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {collections.map((collection) => (
                        <div
                            key={collection.id}
                            className="bg-white rounded-xl border border-stone-200 shadow-sm overflow-hidden hover:shadow-md transition-shadow"
                        >
                            <div className="p-6">
                                <h3 className="text-lg font-semibold text-stone-900 mb-2">
                                    {collection.name}
                                </h3>
                                <p className="text-sm text-stone-600 mb-1">
                                    <span className="font-medium">Slug:</span> {collection.slug}
                                </p>
                                <p className="text-sm text-stone-500 line-clamp-2">
                                    {collection.heroTitle}
                                </p>
                            </div>
                            <div className="px-6 py-3 bg-stone-50 border-t border-stone-200 flex gap-2">
                                <button
                                    onClick={() => router.push(`/dashboard/merch/content/collections/${collection.id}/edit`)}
                                    className="flex items-center gap-1 px-3 py-1.5 text-sm text-amber-700 hover:bg-amber-50 rounded-lg transition-colors"
                                >
                                    <Edit className="w-3.5 h-3.5" />
                                    Edit
                                </button>
                                <button
                                    onClick={() => handleDelete(collection.id, collection.name)}
                                    className="flex items-center gap-1 px-3 py-1.5 text-sm text-red-700 hover:bg-red-50 rounded-lg transition-colors"
                                >
                                    <Trash2 className="w-3.5 h-3.5" />
                                    Delete
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Create Collection Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-xl max-w-lg w-full p-6">
                        <h2 className="text-xl font-bold text-stone-900 mb-4">Create Collection</h2>
                        <form onSubmit={handleCreate} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-stone-700 mb-1">
                                    Collection Name
                                </label>
                                <input
                                    type="text"
                                    value={formData.name}
                                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                    className="w-full px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    placeholder="e.g. Premium Apparel"
                                    required
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-stone-700 mb-1">
                                    Hero Title
                                </label>
                                <input
                                    type="text"
                                    value={formData.heroTitle}
                                    onChange={(e) => setFormData({ ...formData, heroTitle: e.target.value })}
                                    className="w-full px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    placeholder="e.g. Elevate Your Brand with Premium Apparel"
                                    required
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-stone-700 mb-1">
                                    Hero Subtitle
                                </label>
                                <textarea
                                    value={formData.heroSubtitle}
                                    onChange={(e) => setFormData({ ...formData, heroSubtitle: e.target.value })}
                                    className="w-full px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    rows={3}
                                    placeholder="Brief description..."
                                    required
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-stone-700 mb-1">
                                    Slug (optional)
                                </label>
                                <input
                                    type="text"
                                    value={formData.slug}
                                    onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                                    className="w-full px-3 py-2 border border-stone-300 rounded-lg focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    placeholder="e.g. premium-apparel (auto-generated if empty)"
                                />
                            </div>
                            <div className="flex gap-3 pt-4">
                                <button
                                    type="button"
                                    onClick={() => setShowModal(false)}
                                    className="flex-1 px-4 py-2 border border-stone-300 text-stone-700 rounded-lg hover:bg-stone-50 transition-colors"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    disabled={saving}
                                    className="flex-1 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors flex items-center justify-center gap-2"
                                >
                                    {saving && <Loader2 className="w-4 h-4 animate-spin" />}
                                    Create
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

