'use client';

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, GripVertical } from 'lucide-react';

export interface ColorOption {
    key: string;
    label: string;
    hex: string;
}

interface ColorOptionsFieldProps {
    value: string; // JSON string of { colors: ColorOption[] }
    onChange: (jsonValue: string) => void;
}

export default function ColorOptionsField({ value, onChange }: ColorOptionsFieldProps) {
    const [colors, setColors] = useState<ColorOption[]>([]);

    useEffect(() => {
        try {
            if (value) {
                const parsed = JSON.parse(value);
                if (parsed.colors && Array.isArray(parsed.colors)) {
                    setColors(parsed.colors);
                } else if (Array.isArray(parsed)) {
                    // Handle legacy or direct array format if any
                    setColors(parsed);
                }
            }
        } catch (e) {
            console.error('Failed to parse color options:', e);
            setColors([]);
        }
    }, [value]);

    const updateColors = (newColors: ColorOption[]) => {
        setColors(newColors);
        onChange(JSON.stringify({ colors: newColors }));
    };

    const addColor = () => {
        const newColor: ColorOption = {
            key: `color-${Date.now()}`,
            label: 'New Color',
            hex: '#000000'
        };
        updateColors([...colors, newColor]);
    };

    const removeColor = (index: number) => {
        const newColors = [...colors];
        newColors.splice(index, 1);
        updateColors(newColors);
    };

    const updateColorField = (index: number, field: keyof ColorOption, newValue: string) => {
        const newColors = [...colors];
        newColors[index] = { ...newColors[index], [field]: newValue };
        updateColors(newColors);
    };

    return (
        <div className="space-y-3">
            <div className="flex items-center justify-between">
                <label className="block text-sm font-medium text-stone-700">
                    Color Options
                </label>
                <button
                    type="button"
                    onClick={addColor}
                    className="text-xs flex items-center gap-1 text-amber-600 hover:text-amber-700 font-medium"
                >
                    <Plus className="w-3 h-3" />
                    Add Color
                </button>
            </div>

            <div className="border border-stone-200 rounded-lg overflow-hidden">
                <table className="w-full text-sm">
                    <thead className="bg-stone-50 border-b border-stone-200">
                        <tr>
                            <th className="px-3 py-2 text-left font-medium text-stone-500 w-1/4">Key</th>
                            <th className="px-3 py-2 text-left font-medium text-stone-500 w-1/4">Label</th>
                            <th className="px-3 py-2 text-left font-medium text-stone-500 w-1/4">Hex</th>
                            <th className="px-3 py-2 text-center font-medium text-stone-500 w-16">Preview</th>
                            <th className="px-3 py-2 w-10"></th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-stone-200 bg-white">
                        {colors.length === 0 ? (
                            <tr>
                                <td colSpan={5} className="px-3 py-4 text-center text-stone-400 italic">
                                    No colors added. Click "Add Color" to start.
                                </td>
                            </tr>
                        ) : (
                            colors.map((color, index) => (
                                <tr key={index} className="group hover:bg-stone-50">
                                    <td className="px-3 py-2">
                                        <input
                                            type="text"
                                            value={color.key}
                                            onChange={(e) => updateColorField(index, 'key', e.target.value)}
                                            className="w-full px-2 py-1 border border-stone-300 rounded text-xs focus:ring-1 focus:ring-amber-500 focus:border-amber-500"
                                            placeholder="e.g. white"
                                        />
                                    </td>
                                    <td className="px-3 py-2">
                                        <input
                                            type="text"
                                            value={color.label}
                                            onChange={(e) => updateColorField(index, 'label', e.target.value)}
                                            className="w-full px-2 py-1 border border-stone-300 rounded text-xs focus:ring-1 focus:ring-amber-500 focus:border-amber-500"
                                            placeholder="e.g. White"
                                        />
                                    </td>
                                    <td className="px-3 py-2">
                                        <div className="flex items-center gap-2">
                                            <input
                                                type="text"
                                                value={color.hex}
                                                onChange={(e) => updateColorField(index, 'hex', e.target.value)}
                                                className="w-full px-2 py-1 border border-stone-300 rounded text-xs focus:ring-1 focus:ring-amber-500 focus:border-amber-500 font-mono"
                                                placeholder="#FFFFFF"
                                            />
                                            <input
                                                type="color"
                                                value={color.hex}
                                                onChange={(e) => updateColorField(index, 'hex', e.target.value)}
                                                className="w-6 h-6 p-0 border-0 rounded cursor-pointer"
                                            />
                                        </div>
                                    </td>
                                    <td className="px-3 py-2 text-center">
                                        <div
                                            className="w-6 h-6 rounded-full border border-stone-200 shadow-sm mx-auto"
                                            style={{ backgroundColor: color.hex }}
                                        />
                                    </td>
                                    <td className="px-3 py-2 text-center">
                                        <button
                                            type="button"
                                            onClick={() => removeColor(index)}
                                            className="text-stone-400 hover:text-red-500 transition-colors"
                                            title="Remove color"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>
            <p className="text-xs text-stone-500">
                Define the available color options for this product. The "Key" is used internally, "Label" is shown to users.
            </p>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { Plus, Trash2, Upload, GripVertical } from 'lucide-react';
import Image from 'next/image';

interface ColorVariant {
    id?: string;
    key: string;
    label: string;
    swatchHex: string;
    imageUrl: string;
    backImageUrl?: string;
    sortOrder: number;
    isActive: boolean;
}

interface ColorVariantsFieldProps {
    templateId?: string;
    value: ColorVariant[];
    onChange: (variants: ColorVariant[]) => void;
}

export default function ColorVariantsField({ templateId, value, onChange }: ColorVariantsFieldProps) {
    const [uploading, setUploading] = useState<{ index: number, field: 'imageUrl' | 'backImageUrl' } | null>(null);

    const handleAddVariant = () => {
        const newVariant: ColorVariant = {
            key: '',
            label: '',
            swatchHex: '#000000',
            imageUrl: '',
            backImageUrl: '',
            sortOrder: value.length,
            isActive: true
        };
        onChange([...value, newVariant]);
    };

    const handleRemoveVariant = (index: number) => {
        const updated = value.filter((_, i) => i !== index);
        onChange(updated);
    };

    const handleUpdateVariant = (index: number, field: keyof ColorVariant, newValue: any) => {
        const updated = [...value];
        updated[index] = { ...updated[index], [field]: newValue };
        onChange(updated);
    };

    const handleImageUpload = async (index: number, field: 'imageUrl' | 'backImageUrl', file: File) => {
        setUploading({ index, field });
        const formData = new FormData();
        formData.append('file', file);

        try {
            const res = await fetch('/api/admin/upload', {
                method: 'POST',
                body: formData
            });

            if (!res.ok) throw new Error('Upload failed');

            const data = await res.json();
            handleUpdateVariant(index, field, data.url);
        } catch (error) {
            console.error('Error uploading image:', error);
            alert('Failed to upload image');
        } finally {
            setUploading(null);
        }
    };

    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between">
                <label className="block text-sm font-medium text-stone-700">
                    Color Variants
                </label>
                <button
                    type="button"
                    onClick={handleAddVariant}
                    className="flex items-center gap-2 px-3 py-1.5 text-sm bg-amber-600 text-white rounded-lg hover:bg-amber-700 transition-colors"
                >
                    <Plus className="w-4 h-4" />
                    Add Color
                </button>
            </div>

            {value.length === 0 ? (
                <div className="text-center py-8 text-stone-400 border-2 border-dashed border-stone-200 rounded-lg">
                    No color variants yet. Click "Add Color" to start.
                </div>
            ) : (
                <div className="space-y-3">
                    {value.map((variant, index) => (
                        <div
                            key={index}
                            className="flex items-start gap-3 p-4 bg-stone-50 rounded-lg border border-stone-200"
                        >
                            {/* Drag Handle */}
                            <div className="flex items-center pt-2">
                                <GripVertical className="w-5 h-5 text-stone-400 cursor-move" />
                            </div>

                            {/* Swatch Preview */}
                            <div className="flex-shrink-0 pt-2">
                                <div
                                    className="w-10 h-10 rounded-lg border-2 border-stone-300 shadow-sm"
                                    style={{ backgroundColor: variant.swatchHex }}
                                />
                            </div>

                            {/* Form Fields */}
                            <div className="flex-1 grid grid-cols-2 gap-3">
                                <div>
                                    <label className="block text-xs font-medium text-stone-600 mb-1">
                                        Key
                                    </label>
                                    <input
                                        type="text"
                                        value={variant.key}
                                        onChange={(e) => handleUpdateVariant(index, 'key', e.target.value)}
                                        placeholder="black"
                                        className="w-full px-2 py-1.5 text-sm border border-stone-300 rounded focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-medium text-stone-600 mb-1">
                                        Label
                                    </label>
                                    <input
                                        type="text"
                                        value={variant.label}
                                        onChange={(e) => handleUpdateVariant(index, 'label', e.target.value)}
                                        placeholder="Black"
                                        className="w-full px-2 py-1.5 text-sm border border-stone-300 rounded focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-medium text-stone-600 mb-1">
                                        Swatch Hex
                                    </label>
                                    <div className="flex gap-2">
                                        <input
                                            type="color"
                                            value={variant.swatchHex}
                                            onChange={(e) => handleUpdateVariant(index, 'swatchHex', e.target.value)}
                                            className="w-10 h-8 border border-stone-300 rounded cursor-pointer"
                                        />
                                        <input
                                            type="text"
                                            value={variant.swatchHex}
                                            onChange={(e) => handleUpdateVariant(index, 'swatchHex', e.target.value)}
                                            placeholder="#000000"
                                            className="flex-1 px-2 py-1.5 text-sm border border-stone-300 rounded focus:ring-2 focus:ring-amber-500 focus:border-transparent"
                                        />
                                    </div>
                                </div>

                                {/* Front Image */}
                                <div>
                                    <label className="block text-xs font-medium text-stone-600 mb-1">
                                        Front Image
                                    </label>
                                    <div className="flex gap-2">
                                        {variant.imageUrl && (
                                            <div className="relative w-10 h-10 bg-stone-100 rounded border border-stone-200 overflow-hidden flex-shrink-0">
                                                <Image
                                                    src={variant.imageUrl}
                                                    alt={variant.label}
                                                    fill
                                                    sizes="40px"
                                                    className="object-contain"
                                                />
                                            </div>
                                        )}
                                        <label className="flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-sm border border-stone-300 rounded cursor-pointer hover:bg-stone-50 transition-colors">
                                            <Upload className="w-4 h-4" />
                                            {uploading?.index === index && uploading?.field === 'imageUrl' ? '...' : 'Front'}
                                            <input
                                                type="file"
                                                accept="image/png,image/jpeg,image/webp"
                                                onChange={(e) => {
                                                    const file = e.target.files?.[0];
                                                    if (file) handleImageUpload(index, 'imageUrl', file);
                                                }}
                                                className="hidden"
                                                disabled={uploading !== null}
                                            />
                                        </label>
                                    </div>
                                </div>

                                {/* Back Image */}
                                <div>
                                    <label className="block text-xs font-medium text-stone-600 mb-1">
                                        Back Image (Optional)
                                    </label>
                                    <div className="flex gap-2">
                                        {variant.backImageUrl && (
                                            <div className="relative w-10 h-10 bg-stone-100 rounded border border-stone-200 overflow-hidden flex-shrink-0">
                                                <Image
                                                    src={variant.backImageUrl}
                                                    alt={`${variant.label} Back`}
                                                    fill
                                                    sizes="40px"
                                                    className="object-contain"
                                                />
                                            </div>
                                        )}
                                        <label className="flex-1 flex items-center justify-center gap-2 px-2 py-1.5 text-sm border border-stone-300 rounded cursor-pointer hover:bg-stone-50 transition-colors">
                                            <Upload className="w-4 h-4" />
                                            {uploading?.index === index && uploading?.field === 'backImageUrl' ? '...' : 'Back'}
                                            <input
                                                type="file"
                                                accept="image/png,image/jpeg,image/webp"
                                                onChange={(e) => {
                                                    const file = e.target.files?.[0];
                                                    if (file) handleImageUpload(index, 'backImageUrl', file);
                                                }}
                                                className="hidden"
                                                disabled={uploading !== null}
                                            />
                                        </label>
                                    </div>
                                </div>
                            </div>

                            {/* Delete Button */}
                            <button
                                type="button"
                                onClick={() => handleRemoveVariant(index)}
                                className="flex-shrink-0 p-2 text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                                title="Delete variant"
                            >
                                <Trash2 className="w-4 h-4" />
                            </button>
                        </div>
                    ))}
                </div>
            )}

            <p className="text-xs text-stone-500">
                Each color variant should have a unique key, display label, swatch color for buttons, and a final PNG image of the product in that color.
            </p>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useToast } from '@/components/ui/ToastProvider';
import { Loader2, Save, Upload, Image as ImageIcon } from 'lucide-react';

interface MockupTemplateEditorProps {
    productId: string;
    variantId?: string;
    brandSlug: string;
}

export default function MockupTemplateEditor({
    productId,
    variantId,
    brandSlug
}: MockupTemplateEditorProps) {
    const toast = useToast();
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [template, setTemplate] = useState<any>(null);

    // Form state
    const [formData, setFormData] = useState({
        canvasWidth: 2000,
        canvasHeight: 2000,
        printAreaWidth: 1000,
        printAreaHeight: 1200,
        printAreaX: 500,
        printAreaY: 400,
        frontMockupImage: '',
        backMockupImage: '',
        hasBackView: false,
        isActive: true
    });

    useEffect(() => {
        fetchTemplate();
    }, [productId, variantId]);

    const fetchTemplate = async () => {
        try {
            const url = `/api/admin/products/${productId}/mockup${variantId ? `?variantId=${variantId}` : ''
                }`;
            const res = await fetch(url);

            if (res.ok) {
                const data = await res.json();
                setTemplate(data);
                setFormData({
                    canvasWidth: data.canvasWidth,
                    canvasHeight: data.canvasHeight,
                    printAreaWidth: data.printAreaWidth,
                    printAreaHeight: data.printAreaHeight,
                    printAreaX: data.printAreaX,
                    printAreaY: data.printAreaY,
                    frontMockupImage: data.frontMockupImage || '',
                    backMockupImage: data.backMockupImage || '',
                    hasBackView: data.hasBackView,
                    isActive: data.isActive
                });
            } else if (res.status !== 404) {
                toast.error('Failed to load mockup template');
            }
        } catch (error) {
            console.error('Error fetching template:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleSave = async () => {
        setSaving(true);
        try {
            const res = await fetch(`/api/admin/products/${productId}/mockup`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    variantId,
                    ...formData
                })
            });

            if (res.ok) {
                const data = await res.json();
                setTemplate(data);
                toast.success('Print setup saved successfully');
            } else {
                toast.error('Failed to save print setup');
            }
        } catch (error) {
            console.error('Error saving template:', error);
            toast.error('Failed to save print setup');
        } finally {
            setSaving(false);
        }
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, field: 'frontMockupImage' | 'backMockupImage') => {
        const file = e.target.files?.[0];
        if (!file) return;

        const formData = new FormData();
        formData.append('file', file);

        try {
            const res = await fetch('/api/upload', {
                method: 'POST',
                body: formData
            });

            if (res.ok) {
                const data = await res.json();
                setFormData(prev => ({ ...prev, [field]: data.url }));
                toast.success('Image uploaded');
            } else {
                toast.error('Upload failed');
            }
        } catch (error) {
            console.error('Error uploading:', error);
            toast.error('Upload failed');
        }
    };

    if (loading) {
        return (
            <div className="flex justify-center p-8">
                <Loader2 className="w-6 h-6 animate-spin text-amber-600" />
            </div>
        );
    }

    return (
        <div className="space-y-8">
            <div className="flex items-center justify-between">
                <h3 className="text-lg font-bold text-stone-900">
                    Print Area Configuration
                </h3>
                <button
                    onClick={handleSave}
                    disabled={saving}
                    className="flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 disabled:opacity-50 transition-colors"
                >
                    {saving ? (
                        <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                        <Save className="w-4 h-4" />
                    )}
                    Save Configuration
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Visual Editor (Placeholder) */}
                <div className="bg-stone-100 rounded-xl border border-stone-200 aspect-square flex items-center justify-center relative overflow-hidden">
                    {formData.frontMockupImage ? (
                        <div className="relative w-full h-full">
                            <img
                                src={formData.frontMockupImage}
                                alt="Mockup Base"
                                className="w-full h-full object-contain"
                            />
                            {/* Print Area Overlay */}
                            <div
                                className="absolute border-2 border-dashed border-blue-500 bg-blue-500/10 pointer-events-none"
                                style={{
                                    left: `${(formData.printAreaX / formData.canvasWidth) * 100}%`,
                                    top: `${(formData.printAreaY / formData.canvasHeight) * 100}%`,
                                    width: `${(formData.printAreaWidth / formData.canvasWidth) * 100}%`,
                                    height: `${(formData.printAreaHeight / formData.canvasHeight) * 100}%`,
                                }}
                            >
                                <div className="absolute top-0 left-0 bg-blue-500 text-white text-[10px] px-1">
                                    Print Area
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="text-center text-stone-400">
                            <ImageIcon className="w-12 h-12 mx-auto mb-2" />
                            <p>Upload a mockup base image to visualize</p>
                        </div>
                    )}
                </div>

                {/* Controls */}
                <div className="space-y-6">
                    {/* Images */}
                    <div className="space-y-4">
                        <h4 className="font-medium text-stone-900">Mockup Images</h4>

                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-2">
                                Front Mockup Base
                            </label>
                            <div className="flex gap-4 items-center">
                                <input
                                    type="text"
                                    value={formData.frontMockupImage}
                                    onChange={(e) => setFormData({ ...formData, frontMockupImage: e.target.value })}
                                    className="flex-1 px-3 py-2 border border-stone-300 rounded-lg text-sm"
                                    placeholder="Image URL"
                                />
                                <label className="cursor-pointer px-4 py-2 border border-stone-300 rounded-lg hover:bg-stone-50 transition-colors">
                                    <Upload className="w-4 h-4" />
                                    <input
                                        type="file"
                                        accept="image/*"
                                        className="hidden"
                                        onChange={(e) => handleFileUpload(e, 'frontMockupImage')}
                                    />
                                </label>
                            </div>
                        </div>

                        <div>
                            <label className="flex items-center gap-2 mb-2">
                                <input
                                    type="checkbox"
                                    checked={formData.hasBackView}
                                    onChange={(e) => setFormData({ ...formData, hasBackView: e.target.checked })}
                                    className="w-4 h-4 text-amber-600 border-stone-300 rounded"
                                />
                                <span className="text-sm font-medium text-stone-700">Enable Back View</span>
                            </label>

                            {formData.hasBackView && (
                                <div className="pl-6">
                                    <label className="block text-sm font-medium text-stone-700 mb-2">
                                        Back Mockup Base
                                    </label>
                                    <div className="flex gap-4 items-center">
                                        <input
                                            type="text"
                                            value={formData.backMockupImage}
                                            onChange={(e) => setFormData({ ...formData, backMockupImage: e.target.value })}
                                            className="flex-1 px-3 py-2 border border-stone-300 rounded-lg text-sm"
                                            placeholder="Image URL"
                                        />
