                            <button
                                onClick={handleSave}
                                disabled={isLoading}
                                className="px-6 py-2 rounded-lg bg-stone-900 text-white hover:bg-stone-800 disabled:opacity-50 flex items-center gap-2"
                            >
                                {isLoading && <RotateCcw className="w-4 h-4 animate-spin" />}
                                Save Changes
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { signOut, useSession } from 'next-auth/react';
import {
    LayoutDashboard,
    FileText,
    Sparkles,
    Package,
    Palette,
    Mail,
    LogOut,
    Building2,
    Briefcase,
    FileCode,
    BarChart3,
    Image as ImageIcon,
    DollarSign,
    Megaphone,
    Zap,
} from 'lucide-react';

interface SidebarProps {
    brandSlug: string;
}

export default function Sidebar({ brandSlug }: SidebarProps) {
    const pathname = usePathname();
    const { data: session } = useSession();

    const brandRoles = (session?.user as any)?.brandRoles || [];
    const currentBrand = brandRoles.find((br: any) => br.brandSlug === brandSlug);

    const isMerch = brandSlug === 'merch';
    const isIT = brandSlug === 'it-solutions';

    const merchMenuItems = [
        {
            title: 'Dashboard',
            href: `/dashboard/${brandSlug}`,
            icon: LayoutDashboard,
        },
        {
            title: 'Content',
            items: [
                { title: 'Hero & Highlight', href: `/dashboard/${brandSlug}/hero`, icon: FileText },
                { title: 'Hero Slides', href: `/dashboard/${brandSlug}/hero-slides`, icon: ImageIcon },
            ],
        },
        {
            title: 'Collections',
            href: `/dashboard/${brandSlug}/collections`,
            icon: Package,
        },
        {
            title: 'Catalogue Requests',
            href: `/dashboard/${brandSlug}/catalogue-requests`,
            icon: Mail,
        },
        {
            title: 'Orders',
            href: `/dashboard/${brandSlug}/orders`,
            icon: Package,
        },
        {
            title: 'Pricing Engine',
            items: [
                { title: 'Price Rules', href: `/dashboard/${brandSlug}/pricing/rules`, icon: DollarSign },
                { title: 'Components', href: `/dashboard/${brandSlug}/pricing/components`, icon: Package },
            ],
        },
        {
            title: 'Marketing',
            items: [
                { title: 'Overview', href: `/dashboard/${brandSlug}/marketing`, icon: Sparkles },
                { title: 'Campaigns', href: `/dashboard/${brandSlug}/marketing/campaigns`, icon: Megaphone },
                { title: 'Flash Sale', href: `/dashboard/${brandSlug}/marketing/flash-sale`, icon: Zap },
            ],
        },
        {
            title: 'Analytics',
            href: `/dashboard/${brandSlug}/analytics`,
            icon: BarChart3,
        },
        {
            title: 'Settings',
            href: `/dashboard/${brandSlug}/settings`,
            icon: Palette,
        },
    ];

    const itMenuItems = [
        {
            title: 'Dashboard',
            href: `/dashboard/${brandSlug}`,
            icon: LayoutDashboard,
        },
        {
            title: 'Content',
            items: [
                { title: 'Hero Section', href: `/dashboard/${brandSlug}/content/hero`, icon: FileText },
                { title: 'Hero Slides', href: `/dashboard/${brandSlug}/content/hero-slides`, icon: ImageIcon },
            ],
        },
        {
            title: 'Services',
            href: `/dashboard/${brandSlug}/services`,
            icon: Briefcase,
        },
        {
            title: 'Case Studies',
            href: `/dashboard/${brandSlug}/case-studies`,
            icon: FileCode,
        },
        {
            title: 'Analytics',
            href: `/dashboard/${brandSlug}/analytics`,
            icon: BarChart3,
        },
        {
            title: 'Settings',
            href: `/dashboard/${brandSlug}/settings`,
            icon: Palette,
        },
    ];

    const menuItems = isMerch ? merchMenuItems : itMenuItems;

    const handleSignOut = () => {
        signOut({ callbackUrl: '/login' });
    };

    return (
        <div className="w-64 bg-white border-r border-stone-200 min-h-screen flex flex-col" suppressHydrationWarning>
            {/* Logo & Brand */}
            <div className="p-6 border-b border-stone-200" suppressHydrationWarning>
                <div className="flex items-center gap-3 mb-2" suppressHydrationWarning>
                    <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-amber-500 to-amber-600 flex items-center justify-center" suppressHydrationWarning>
                        <Building2 className="w-5 h-5 text-white" />
                    </div>
                    <div suppressHydrationWarning>
                        <h1 className="text-lg font-bold text-stone-900" suppressHydrationWarning>
                            {currentBrand?.brandName || 'ACHIERA'}
                        </h1>
                    </div>
                </div>
                <p className="text-xs text-stone-500" suppressHydrationWarning>Admin Dashboard</p>
            </div>

            {/* Navigation */}
            <nav className="flex-1 p-4 space-y-1" suppressHydrationWarning>
                {menuItems.map((item, idx) => {
                    if ('items' in item) {
                        // Section with submenu
                        return (
                            <div key={idx} className="mb-4" suppressHydrationWarning>
                                <div className="px-3 py-2 text-xs font-semibold text-stone-500 uppercase tracking-wider" suppressHydrationWarning>
                                    {item.title}
                                </div>
                                <div className="space-y-1" suppressHydrationWarning>
                                    {item.items.map((subItem) => {
                                        const Icon = subItem.icon;
                                        const isActive = pathname === subItem.href;
                                        return (
                                            <Link
                                                key={subItem.href}
                                                href={subItem.href}
                                                className={`flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors ${isActive
                                                    ? 'bg-amber-100 text-amber-900'
                                                    : 'text-stone-700 hover:bg-stone-100'
                                                    }`}
                                                suppressHydrationWarning
                                            >
                                                <Icon className="w-4 h-4" />
                                                {subItem.title}
                                            </Link>
                                        );
                                    })}
                                </div>
                            </div>
                        );
                    } else {
                        // Single menu item
                        const Icon = item.icon;
                        const isActive = pathname === item.href;
                        return (
                            <Link
                                key={item.href}
                                href={item.href}
                                className={`flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors ${isActive
                                    ? 'bg-amber-100 text-amber-900'
                                    : 'text-stone-700 hover:bg-stone-100'
                                    }`}
                                suppressHydrationWarning
                            >
                                <Icon className="w-4 h-4" />
                                {item.title}
                            </Link>
                        );
                    }
                })}
            </nav>

            {/* Brand Switcher (if user has multiple brands) */}
            {brandRoles.length > 1 && (
                <div className="p-4 border-t border-stone-200" suppressHydrationWarning>
                    <Link
                        href="/dashboard"
                        className="flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium text-stone-700 hover:bg-stone-100 transition-colors"
                        suppressHydrationWarning
                    >
                        <Building2 className="w-4 h-4" />
                        Switch Brand
                    </Link>
                </div>
            )}

            {/* Sign Out */}
            <div className="p-4 border-t border-stone-200" suppressHydrationWarning>
                <button
                    onClick={handleSignOut}
                    className="flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium text-red-700 hover:bg-red-50 w-full transition-colors"
                    suppressHydrationWarning
                >
                    <LogOut className="w-4 h-4" />
                    Sign Out
                </button>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Loader2, Save, ArrowLeft } from 'lucide-react';
import { PriceComponentType } from '@prisma/client';

interface ComponentFormProps {
    initialData?: any;
    brandSlug: string;
}

export default function ComponentForm({ initialData, brandSlug }: ComponentFormProps) {
    const router = useRouter();
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const [formData, setFormData] = useState({
        code: initialData?.code || '',
        name: initialData?.name || '',
        type: initialData?.type || 'BASE',
        description: initialData?.description || ''
    });

    const isEditing = !!initialData;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            const url = isEditing
                ? `/api/admin/pricing/components/${initialData.id}`
                : '/api/admin/pricing/components';

            const method = isEditing ? 'PUT' : 'POST';

            const res = await fetch(url, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(formData)
            });

            if (res.ok) {
                router.push(`/dashboard/${brandSlug}/pricing/components`);
                router.refresh();
            } else {
                const data = await res.json();
                setError(data.error || 'Something went wrong');
            }
        } catch (err) {
            setError('Failed to save');
        } finally {
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="max-w-2xl mx-auto p-6 bg-white rounded-xl shadow-sm border border-stone-200">
            {/* Header */}
            <div className="flex items-center justify-between mb-6 border-b border-stone-100 pb-4">
                <h2 className="text-lg font-bold text-stone-900">
                    {isEditing ? 'Edit Component' : 'New Component'}
                </h2>
                <button
                    type="button"
                    onClick={() => router.back()}
                    className="text-stone-500 hover:text-stone-700 text-sm flex items-center gap-1"
                >
                    <ArrowLeft className="w-4 h-4" /> Cancel
                </button>
            </div>

            {error && (
                <div className="mb-6 p-4 bg-red-50 text-red-600 rounded-lg text-sm border border-red-100">
                    {error}
                </div>
            )}

            <div className="space-y-6">
                <div className="grid grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-1">Code</label>
                        <input
                            type="text"
                            required
                            disabled={isEditing}
                            value={formData.code}
                            onChange={(e) => setFormData({ ...formData, code: e.target.value.toUpperCase().replace(/\s+/g, '_') })}
                            placeholder="e.g. DTF_PRINT"
                            className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none uppercase font-mono text-sm disabled:bg-stone-50 disabled:text-stone-500"
                        />
                        <p className="text-xs text-stone-400 mt-1">Unique identifier (UPPERCASE)</p>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-1">Type</label>
                        <select
                            value={formData.type}
                            onChange={(e) => setFormData({ ...formData, type: e.target.value })}
                            className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none"
                        >
                            {Object.keys(PriceComponentType).map(type => (
                                <option key={type} value={type}>{type}</option>
                            ))}
                        </select>
                    </div>
                </div>

                <div>
                    <label className="block text-sm font-medium text-stone-700 mb-1">Display Name</label>
                    <input
                        type="text"
                        required
                        value={formData.name}
                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                        placeholder="e.g. DTF Printing Service"
                        className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-stone-700 mb-1">Description (Optional)</label>
                    <textarea
                        rows={3}
                        value={formData.description}
                        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                        className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none resize-none"
                    />
                </div>

                <div className="pt-4 flex justify-end">
                    <button
                        type="submit"
                        disabled={loading}
                        className="bg-stone-900 text-white px-6 py-2.5 rounded-lg font-medium hover:bg-black transition-colors flex items-center gap-2 disabled:opacity-50"
                    >
                        {loading && <Loader2 className="w-4 h-4 animate-spin" />}
                        {isEditing ? 'Update Component' : 'Create Component'}
                    </button>
                </div>
            </div>
        </form>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Loader2, Plus, Trash2, ArrowLeft } from 'lucide-react';
import { PriceScope } from '@prisma/client';

interface RuleFormProps {
    initialData?: any;
    brandSlug: string;
}

export default function RuleForm({ initialData, brandSlug }: RuleFormProps) {
    const router = useRouter();
    const [loading, setLoading] = useState(false);
    const [components, setComponents] = useState<any[]>([]);

    const [formData, setFormData] = useState({
        componentId: initialData?.componentId || '',
        scope: initialData?.scope || 'GLOBAL',
        scopeId: initialData?.scopeId || '',
        amount: initialData?.amount || 0,
        currency: 'IDR',
        priority: initialData?.priority || 0,
        minQty: initialData?.minQty || '',
        maxQty: initialData?.maxQty || '',
        metadata: initialData?.metadata ? Object.entries(initialData.metadata).map(([k, v]) => ({ key: k, value: v })) : []
    });

    const [scopeOptions, setScopeOptions] = useState<any[]>([]);
    const [loadingOptions, setLoadingOptions] = useState(false);

    useEffect(() => {
        // Fetch components for dropdown
        fetch('/api/admin/pricing/components')
            .then(res => res.json())
            .then(data => setComponents(data));
    }, []);

    // Fetch scope options when scope changes
    useEffect(() => {
        if (formData.scope === 'PRODUCT' || formData.scope === 'VARIANT') {
            setLoadingOptions(true);
            const query = new URLSearchParams({ scope: formData.scope });
            if (brandSlug) query.append('brandSlug', brandSlug);

            fetch(`/api/admin/pricing/scope-options?${query.toString()}`)
                .then(res => res.json())
                .then(data => {
                    setScopeOptions(Array.isArray(data) ? data : []);
                })
                .catch(err => console.error("Failed to fetch options", err))
                .finally(() => setLoadingOptions(false));
        } else {
            setScopeOptions([]);
        }
    }, [formData.scope, brandSlug]);

    const handleAddMetadata = () => {
        setFormData(prev => ({
            ...prev,
            metadata: [...prev.metadata, { key: '', value: '' }]
        }));
    };

    const handleRemoveMetadata = (index: number) => {
        setFormData(prev => ({
            ...prev,
            metadata: prev.metadata.filter((_, i) => i !== index)
        }));
    };

    const handleMetadataChange = (index: number, field: 'key' | 'value', val: string) => {
        const newMeta = [...formData.metadata];
        // @ts-ignore
        newMeta[index][field] = val;
        setFormData({ ...formData, metadata: newMeta });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);

        try {
            // Convert metadata array back to object
            const metadataObj: any = {};
            formData.metadata.forEach((item: any) => {
                if (item.key) metadataObj[item.key] = item.value; // Simple string values for now
            });

            const payload = {
                ...formData,
                amount: Number(formData.amount),
                priority: Number(formData.priority),
                minQty: formData.minQty ? Number(formData.minQty) : null,
                maxQty: formData.maxQty ? Number(formData.maxQty) : null,
                metadata: metadataObj
            };

            const url = initialData
                ? `/api/admin/pricing/rules/${initialData.id}`
                : '/api/admin/pricing/rules';

            const method = initialData ? 'PUT' : 'POST';

            const res = await fetch(url, {
                method,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (res.ok) {
                router.push(`/dashboard/${brandSlug}/pricing/rules`);
                router.refresh();
            }
        } catch (error) {
            console.error('Save error', error);
        } finally {
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="max-w-4xl mx-auto p-6 bg-white rounded-xl shadow-sm border border-stone-200">
            <div className="flex items-center justify-between mb-6 border-b border-stone-100 pb-4">
                <h2 className="text-lg font-bold text-stone-900">
                    {initialData ? 'Edit Rule' : 'New Pricing Rule'}
                </h2>
                <button
                    type="button"
                    onClick={() => router.back()}
                    className="text-stone-500 hover:text-stone-700 text-sm flex items-center gap-1"
                >
                    <ArrowLeft className="w-4 h-4" /> Cancel
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Left Column: Basic Info */}
                <div className="space-y-6">
                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-1">Pricing Component</label>
                        <select
                            required
                            value={formData.componentId}
                            onChange={e => setFormData({ ...formData, componentId: e.target.value })}
                            className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none"
                        >
                            <option value="">Select a component...</option>
                            {components.map(c => (
                                <option key={c.id} value={c.id}>{c.name} ({c.type})</option>
                            ))}
                        </select>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-1">Amount</label>
                            <input
                                type="number"
                                required
                                value={formData.amount}
                                onChange={e => setFormData({ ...formData, amount: e.target.value as any })}
                                className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-1">Priority</label>
                            <input
                                type="number"
                                value={formData.priority}
                                onChange={e => setFormData({ ...formData, priority: e.target.value as any })}
                                className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none"
                            />
                            <p className="text-xs text-stone-400 mt-1">Higher runs last</p>
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-stone-700 mb-1">Scope</label>
                        <select
                            value={formData.scope}
                            onChange={e => setFormData({ ...formData, scope: e.target.value as any, scopeId: '' })}
                            className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none"
                        >
                            <option value="GLOBAL">Global (All Products)</option>
                            <option value="BRAND">Brand</option>
                            <option value="PRODUCT">Product</option>
                            <option value="VARIANT">Variant</option>
                        </select>
                    </div>

                    {formData.scope !== 'GLOBAL' && (
                        <div>
                            <label className="block text-sm font-medium text-stone-700 mb-1">Scope ID</label>
                            {(formData.scope === 'PRODUCT' || formData.scope === 'VARIANT') ? (
                                <select
                                    value={formData.scopeId}
                                    onChange={e => setFormData({ ...formData, scopeId: e.target.value })}
                                    className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none"
                                    disabled={loadingOptions}
                                >
                                    <option value="">
                                        {loadingOptions ? 'Loading...' : `Select ${formData.scope.toLowerCase()}...`}
                                    </option>
                                    {scopeOptions.map(opt => (
                                        <option key={opt.id} value={opt.id}>{opt.name}</option>
                                    ))}
                                </select>
                            ) : (
                                <input
                                    type="text"
                                    placeholder={`Enter ${formData.scope} ID`}
                                    value={formData.scopeId}
                                    onChange={e => setFormData({ ...formData, scopeId: e.target.value })}
                                    className="w-full p-2.5 rounded-lg border border-stone-200 focus:ring-2 focus:ring-amber-500 outline-none font-mono text-sm"
                                />
                            )}
                        </div>
                    )}
                </div>

                {/* Right Column: Conditions */}
                <div className="space-y-6 bg-stone-50 p-6 rounded-xl">
                    <h3 className="text-sm font-bold text-stone-900 uppercase tracking-wide">Conditions</h3>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-xs font-medium text-stone-500 mb-1">Min Qty</label>
                            <input
                                type="number"
                                value={formData.minQty}
                                onChange={e => setFormData({ ...formData, minQty: e.target.value })}
                                placeholder="None"
                                className="w-full p-2 rounded border border-stone-200"
                            />
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-stone-500 mb-1">Max Qty</label>
                            <input
                                type="number"
                                value={formData.maxQty}
                                onChange={e => setFormData({ ...formData, maxQty: e.target.value })}
                                placeholder="None"
                                className="w-full p-2 rounded border border-stone-200"
                            />
                        </div>
                    </div>

                    <div>
                        <div className="flex justify-between items-center mb-2">
                            <label className="block text-xs font-medium text-stone-500">Metadata Matchers</label>
                            <button type="button" onClick={handleAddMetadata} className="text-amber-600 hover:text-amber-700 text-xs font-medium flex items-center gap-1">
                                <Plus className="w-3 h-3" /> Add
                            </button>
                        </div>

                        <div className="space-y-2">
                            {formData.metadata.map((meta: any, idx) => (
                                <div key={idx} className="flex gap-2">
                                    <input
                                        type="text"
                                        placeholder="Key (e.g. printMethod)"
                                        value={meta.key}
                                        onChange={e => handleMetadataChange(idx, 'key', e.target.value)}
                                        className="flex-1 p-2 rounded border border-stone-200 text-sm"
                                    />
                                    <input
                                        type="text"
                                        placeholder="Value (e.g. dtf)"
                                        value={meta.value}
                                        onChange={e => handleMetadataChange(idx, 'value', e.target.value)}
                                        className="flex-1 p-2 rounded border border-stone-200 text-sm"
                                    />
                                    <button type="button" onClick={() => handleRemoveMetadata(idx)} className="text-red-400 hover:text-red-600">
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                            {formData.metadata.length === 0 && (
                                <p className="text-xs text-stone-400 italic text-center py-2">No metadata conditions</p>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <div className="mt-8 pt-6 border-t border-stone-100 flex justify-end">
                <button
                    type="submit"
                    disabled={loading}
                    className="bg-stone-900 text-white px-6 py-2.5 rounded-lg font-medium hover:bg-black transition-colors flex items-center gap-2 disabled:opacity-50"
                >
                    {loading && <Loader2 className="w-4 h-4 animate-spin" />}
                    {initialData ? 'Update Rule' : 'Create Rule'}
                </button>
            </div>
        </form>
    );
}

'use client';

import {
    LineChart, Line, BarChart, Bar, AreaChart, Area,
    XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';

interface ChartData {
    date: string;
    [key: string]: string | number;
}

interface AnalyticsChartProps {
    data: ChartData[];
    type?: 'line' | 'bar' | 'area';
    dataKeys: { key: string; name: string; color: string }[];
    height?: number;
}

export default function AnalyticsChart({
    data,
    type = 'line',
    dataKeys,
    height = 300
}: AnalyticsChartProps) {
    if (!data || data.length === 0) {
        return (
            <div className="flex items-center justify-center h-64 bg-stone-50 rounded-[2rem] border border-dashed border-stone-200">
                <p className="text-stone-400 font-bold uppercase text-[10px] tracking-widest">No intelligence data yet</p>
            </div>
        );
    }

    const getChartComponent = () => {
        switch (type) {
            case 'bar': return BarChart;
            case 'area': return AreaChart;
            default: return LineChart;
        }
    };

    const getDataComponent = () => {
        switch (type) {
            case 'bar': return Bar;
            case 'area': return Area;
            default: return Line;
        }
    };

    const ChartComponent = getChartComponent();
    const DataComponent = getDataComponent();

    return (
        <ResponsiveContainer width="100%" height={height}>
            <ChartComponent data={data} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                <defs>
                    {dataKeys.map(({ key, color }) => (
                        <linearGradient key={`grad-${key}`} id={`grad-${key}`} x1="0" y1="0" x2="0" y2="1">
                            <stop offset="5%" stopColor={color} stopOpacity={0.3} />
                            <stop offset="95%" stopColor={color} stopOpacity={0} />
                        </linearGradient>
                    ))}
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis
                    dataKey="date"
                    stroke="#94a3b8"
                    fontSize={10}
                    fontWeight={700}
                    axisLine={false}
                    tickLine={false}
                    tickMargin={10}
                />
                <YAxis
                    stroke="#94a3b8"
                    fontSize={10}
                    fontWeight={700}
                    axisLine={false}
                    tickLine={false}
                    tickFormatter={(val) => val >= 1000000 ? `${(val / 1000000).toFixed(1)}jt` : val.toLocaleString()}
                />
                <Tooltip
                    contentStyle={{
                        backgroundColor: 'rgba(255, 255, 255, 0.9)',
                        backdropFilter: 'blur(8px)',
                        border: '1px solid #e2e8f0',
                        borderRadius: '16px',
                        boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)',
                        padding: '12px',
                        fontSize: '11px',
                        fontWeight: '800'
                    }}
                    cursor={{ stroke: '#e2e8f0', strokeWidth: 1 }}
                />
                <Legend
                    wrapperStyle={{ fontSize: '10px', fontWeight: '900', textTransform: 'uppercase', letterSpacing: '0.1em', paddingTop: '20px' }}
                    iconType="circle"
                />
                {dataKeys.map(({ key, name, color }) => (
                    <DataComponent
                        key={key}
                        type="monotone"
                        dataKey={key}
                        name={name}
                        stroke={color}
                        fill={type === 'area' ? `url(#grad-${key})` : color}
                        strokeWidth={3}
                        dot={type === 'line' ? { r: 4, strokeWidth: 2, fill: '#fff' } : false}
                        activeDot={{ r: 6, strokeWidth: 0 }}
                        animationDuration={1500}
                    />
                ))}
            </ChartComponent>
        </ResponsiveContainer>
    );
}

import React, { useState } from 'react';

export interface StagedAction {
    id: string;
    suggestionId: string;
    status: 'STAGED' | 'PENDING_APPROVAL' | 'APPROVED' | 'EXECUTING' | 'COMPLETED' | 'FAILED' | 'REVERTING' | 'REVERTED';
    payload: any;
    riskTier: string;
    reversalPlan: any;
    suggestion?: {
        title: string;
    };
    approvals: any[];
}

export function ActionStagingArea({ brandId, actions, onRefresh }: { brandId: string; actions: StagedAction[]; onRefresh: () => void }) {
    const [isSubmitting, setIsSubmitting] = useState<string | null>(null);
    const [acceptedTerms, setAcceptedTerms] = useState<Record<string, boolean>>({});

    const handleAction = async (actionId: string, type: 'FINALIZE' | 'APPROVE' | 'EXECUTE' | 'REVERT') => {
        setIsSubmitting(actionId);
        try {
            const payload: any = { action: type, actionId };

            if (type === 'APPROVE') {
                payload.operatorId = 'OPERATOR_01'; // Mock
                payload.role = 'CFO'; // Mock
                payload.acknowledgment = "I have verified the risk of this action.";
            } else if (type === 'FINALIZE') {
                // Just finalizing the current payload for simplicity in this component
                payload.payload = actions.find(a => a.id === actionId)?.payload;
            }

            const response = await fetch('/api/autonomous-analytics/assisted-actions', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            if (response.ok) {
                onRefresh();
            }
        } catch (err) {
            console.error(`Action ${type} failed:`, err);
        } finally {
            setIsSubmitting(null);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex items-center gap-4 mb-8">
                <h2 className="text-sm font-black tracking-[0.3em] uppercase text-gray-400">Action Staging Area</h2>
                <div className="h-px flex-grow bg-gray-100"></div>
                <div className="px-3 py-1 bg-gray-900 text-white text-[9px] font-black uppercase tracking-widest rounded shadow-sm">
                    HUMAN-LOCKED CONDUIT
                </div>
            </div>

            {actions.length === 0 ? (
                <div className="bg-white border-2 border-dashed border-gray-100 rounded-3xl p-16 text-center">
                    <p className="text-sm font-bold text-gray-300 uppercase tracking-widest">No actions currently staged</p>
                    <p className="text-[10px] text-gray-400 mt-2 lowercase">promote a suggestion to start the execution workflow</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 gap-6">
                    {actions.map((item) => (
                        <div key={item.id} className="bg-white border border-gray-100 rounded-3xl overflow-hidden shadow-sm hover:shadow-md transition-shadow">
                            <div className="p-8">
                                <div className="flex justify-between items-start mb-6">
                                    <div>
                                        <div className="flex items-center gap-3 mb-2">
                                            <span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase ${item.status === 'STAGED' ? 'bg-gray-100 text-gray-500' :
                                                    item.status === 'APPROVED' ? 'bg-green-100 text-green-600' :
                                                        'bg-blue-100 text-blue-600'
                                                }`}>
                                                {item.status.replace(/_/g, ' ')}
                                            </span>
                                            <span className="text-[10px] text-gray-400 font-mono">ID: {item.id}</span>
                                        </div>
                                        <h3 className="text-lg font-black text-gray-800 tracking-tight">{item.suggestion?.title || 'Unknown Action'}</h3>
                                    </div>
                                    <div className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase ${item.riskTier === 'HIGH' ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-blue-50 text-blue-600 border border-blue-100'
                                        }`}>
                                        {item.riskTier} RISK
                                    </div>
                                </div>

                                {/* State-specific Controls */}
                                <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                                    {/* Step 1: Definition */}
                                    <div className={`p-6 rounded-2xl border ${item.status === 'STAGED' ? 'bg-gray-50 border-gray-200' : 'bg-white opacity-50 border-gray-100'}`}>
                                        <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-4">1. Staging</span>
                                        <p className="text-[10px] text-gray-500 leading-relaxed mb-4 font-bold uppercase italic">"Verify action parameters and payload integrity."</p>
                                        <button
                                            disabled={item.status !== 'STAGED' || isSubmitting === item.id}
                                            onClick={() => handleAction(item.id, 'FINALIZE')}
                                            className="w-full py-3 bg-white border border-gray-200 rounded-xl text-[10px] font-black uppercase tracking-widest hover:border-blue-500 hover:text-blue-600 transition-all disabled:opacity-30"
                                        >
                                            Finalize Definition
                                        </button>
                                    </div>

                                    {/* Step 2: Approval */}
                                    <div className={`p-6 rounded-2xl border ${item.status === 'PENDING_APPROVAL' ? 'bg-blue-50 border-blue-200' : (item.status === 'APPROVED' || item.status === 'EXECUTING' || item.status === 'COMPLETED') ? 'bg-green-50/30 border-green-100' : 'bg-white opacity-50 border-gray-100'}`}>
                                        <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest block mb-4">2. Governance</span>
                                        <div className="space-y-2 mb-4">
                                            {item.approvals.length > 0 ? item.approvals.map((a: any, i: number) => (
                                                <div key={i} className="flex items-center gap-2 text-[10px] font-bold text-gray-500">
                                                    <div className="h-1.5 w-1.5 rounded-full bg-green-500"></div>
                                                    {a.role} SIGNED
                                                </div>
                                            )) : <div className="text-[10px] text-gray-400 italic">Awaiting Signatures...</div>}
                                        </div>
                                        <button
                                            disabled={item.status !== 'PENDING_APPROVAL' || isSubmitting === item.id}
                                            onClick={() => handleAction(item.id, 'APPROVE')}
                                            className="w-full py-3 bg-blue-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-700 transition-all disabled:opacity-30 shadow-lg shadow-blue-200"
                                        >
                                            Sign as CFO
                                        </button>
                                    </div>

                                    {/* Step 3: Execution */}
                                    <div className={`lg:col-span-2 p-6 rounded-2xl border ${item.status === 'APPROVED' ? 'bg-orange-50 border-orange-200 shadow-inner' : 'bg-white opacity-50 border-gray-100'}`}>
                                        <div className="flex justify-between items-center mb-6">
                                            <span className="text-[9px] font-black text-orange-600 uppercase tracking-widest">3. Manual Trigger</span>
                                            {item.status === 'APPROVED' && (
                                                <div className="flex items-center gap-3">
                                                    <input
                                                        type="checkbox"
                                                        id={`terms-${item.id}`}
                                                        checked={!!acceptedTerms[item.id]}
                                                        onChange={(e) => setAcceptedTerms(prev => ({ ...prev, [item.id]: e.target.checked }))}
                                                        className="h-4 w-4 border-2 border-orange-300 rounded focus:ring-orange-500"
                                                    />
                                                    <label htmlFor={`terms-${item.id}`} className="text-[9px] font-black text-orange-800 uppercase tracking-tighter cursor-pointer">
                                                        I accept full responsibility
                                                    </label>
                                                </div>
                                            )}
                                        </div>

                                        <button
                                            disabled={item.status !== 'APPROVED' || !acceptedTerms[item.id] || isSubmitting === item.id}
                                            onClick={() => handleAction(item.id, 'EXECUTE')}
                                            className={`w-full py-6 rounded-2xl text-[11px] font-black uppercase tracking-[0.2em] transition-all shadow-xl ${item.status === 'APPROVED' && acceptedTerms[item.id]
                                                    ? 'bg-gray-900 text-white border-2 border-gray-900 hover:bg-black scale-[1.02]'
                                                    : 'bg-gray-50 text-gray-300 border-2 border-gray-100'
                                                } disabled:opacity-30 disabled:scale-100`}
                                        >
                                            {item.status === 'EXECUTING' ? 'Propagating Signals...' :
                                                item.status === 'COMPLETED' ? '✓ Execution Verified' :
                                                    'Execute Manual Shift'}
                                        </button>

                                        {item.status === 'COMPLETED' && (
                                            <button
                                                onClick={() => handleAction(item.id, 'REVERT')}
                                                className="mt-4 w-full py-2 bg-red-50 text-red-600 text-[9px] font-black uppercase tracking-widest rounded-xl hover:bg-red-100 transition-all"
                                            >
                                                Trigger Emergency Rollback
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Immutable Audit Line */}
                            <div className="px-8 py-3 bg-gray-50 border-t border-gray-100 flex justify-between items-center">
                                <span className="text-[8px] font-black text-gray-400 uppercase tracking-widest">Responsibility Locked</span>
                                <span className="text-[8px] font-mono text-gray-400 uppercase tracking-tighter">PHASE 4.0 PROTOCOL</span>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

// Risk Heatmap - Matrix showing rules by risk tier and autonomy level
// Interactive heatmap with drill-down capability

'use client';

import React, { useState } from 'react';
import { StatusBadge } from '@/components/autonomous/ui/CoreComponents';

interface RiskHeatmapData {
    cells: Array<{
        autonomy_level: 0 | 1 | 2 | 3;
        risk_tier: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
        rule_count: number;
        total_executions: number;
        rollback_rate: number;
        approval_rate: number;
        rules: Array<{
            ruleId: string;
            ruleName: string;
            status: 'OK' | 'REVIEW' | 'PAUSE';
        }>;
    }>;
}

export function RiskHeatmap({ data }: { data: RiskHeatmapData }) {
    const [selectedCell, setSelectedCell] = useState<any>(null);

    if (!data || !data.cells) {
        return <div className="text-center text-gray-500">No data available</div>;
    }

    const levels = [0, 1, 2, 3];
    const risks: Array<'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL'> = ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];

    // Create matrix
    const matrix: Record<number, Record<string, any>> = {};
    levels.forEach(level => {
        matrix[level] = {};
        risks.forEach(risk => {
            const cell = data.cells.find(c => c.autonomy_level === level && c.risk_tier === risk);
            matrix[level][risk] = cell || { rule_count: 0, total_executions: 0, rules: [] };
        });
    });

    const getCellColor = (count: number) => {
        if (count === 0) return 'bg-gray-100 text-gray-400';
        if (count <= 2) return 'bg-green-100 text-green-800';
        if (count <= 5) return 'bg-yellow-100 text-yellow-800';
        return 'bg-red-100 text-red-800';
    };

    return (
        <div>
            {/* Heatmap Table */}
            <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                Level / Risk
                            </th>
                            {risks.map(risk => (
                                <th key={risk} className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    {risk}
                                </th>
                            ))}
                        </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {levels.map(level => (
                            <tr key={level}>
                                <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                    Level {level}
                                </td>
                                {risks.map(risk => {
                                    const cell = matrix[level][risk];
                                    return (
                                        <td
                                            key={risk}
                                            className={`px-6 py-4 whitespace-nowrap text-center cursor-pointer hover:opacity-80 transition-opacity ${getCellColor(cell.rule_count)}`}
                                            onClick={() => cell.rule_count > 0 && setSelectedCell(cell)}
                                        >
                                            <div className="text-2xl font-bold">{cell.rule_count}</div>
                                            {cell.total_executions > 0 && (
                                                <div className="text-xs mt-1">
                                                    {cell.total_executions} exec
                                                </div>
                                            )}
                                        </td>
                                    );
                                })}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Selected Cell Details */}
            {selectedCell && selectedCell.rules.length > 0 && (
                <div className="mt-6 p-4 bg-blue-50 rounded-lg">
                    <div className="flex justify-between items-start mb-4">
                        <h3 className="text-lg font-semibold text-gray-900">
                            Level {selectedCell.autonomy_level} - {selectedCell.risk_tier} Risk
                        </h3>
                        <button
                            onClick={() => setSelectedCell(null)}
                            className="text-gray-400 hover:text-gray-600"
                        >
                            ✕
                        </button>
                    </div>

                    <div className="grid grid-cols-3 gap-4 mb-4">
                        <div>
                            <div className="text-sm text-gray-600">Rules</div>
                            <div className="text-xl font-bold">{selectedCell.rule_count}</div>
                        </div>
                        <div>
                            <div className="text-sm text-gray-600">Approval Rate</div>
                            <div className="text-xl font-bold">{(selectedCell.approval_rate * 100).toFixed(0)}%</div>
                        </div>
                        <div>
                            <div className="text-sm text-gray-600">Rollback Rate</div>
                            <div className="text-xl font-bold">{(selectedCell.rollback_rate * 100).toFixed(0)}%</div>
                        </div>
                    </div>

                    <div>
                        <h4 className="text-sm font-medium text-gray-700 mb-2">Rules:</h4>
                        <div className="space-y-2">
                            {selectedCell.rules.map((rule: any) => (
                                <div key={rule.ruleId} className="flex justify-between items-center bg-white p-2 rounded">
                                    <span className="text-sm">{rule.ruleName}</span>
                                    <StatusBadge status={rule.status} size="sm" />
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

import React from 'react';

interface ReadinessResponse {
    data: {
        simulationSummary: {
            totalSimulations: number;
            byFailureType: Record<string, number>;
            criticalFailures: number;
        };
        rollbackMetrics: {
            totalRollbacks: number;
            successfulRollbacks: number;
            avgLatencySeconds: number;
            RCS: number;
        };
    };
    decision: {
        decision: 'READY' | 'BLOCKED';
        blockReasons: string[];
        riskFlags: string[];
        cfoEscalationRequired: boolean;
        governanceStatement: string;
    };
}

export function GovernanceReadinessGate({ response, loading }: { response: ReadinessResponse | null, loading?: boolean }) {
    if (loading || !response) {
        return <div className="h-64 bg-gray-50 animate-pulse rounded-3xl border border-gray-100"></div>;
    }

    const { decision, data } = response;
    const isReady = decision.decision === 'READY';

    return (
        <div className={`rounded-3xl border-2 p-10 transition-all ${isReady ? 'bg-green-50/50 border-green-200' : 'bg-red-50/50 border-red-200'}`}>
            <div className="flex justify-between items-start mb-10">
                <div>
                    <h3 className="text-2xl font-black text-gray-800 tracking-tight mb-1">Phase 4.5: Governance Readiness Gate</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest leading-loose">
                        Exit Evaluation for Assisted Mode Execution
                    </p>
                </div>
                <div className={`px-6 py-2 rounded-xl text-lg font-black uppercase tracking-widest ${isReady ? 'bg-green-600 text-white' : 'bg-red-600 text-white'}`}>
                    {decision.decision}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-10">
                {/* Evidence Column 1: Simulation Volume */}
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-4">Evidence: Volume</span>
                    <div className="text-4xl font-black text-gray-800 mb-1">{data.simulationSummary.totalSimulations}</div>
                    <p className="text-[10px] text-gray-500 font-bold uppercase tracking-tighter">Total Simulations Run</p>
                    <div className="mt-4 flex items-center gap-2">
                        <div className={`h-2 w-2 rounded-full ${data.simulationSummary.totalSimulations >= 50 ? 'bg-green-500' : 'bg-red-500'}`}></div>
                        <span className="text-[9px] font-bold text-gray-400 uppercase">Target: 50+</span>
                    </div>
                </div>

                {/* Evidence Column 2: Rollback Score */}
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-4">Evidence: Reliability</span>
                    <div className="text-4xl font-black text-gray-800 mb-1">{data.rollbackMetrics.RCS.toFixed(1)}%</div>
                    <p className="text-[10px] text-gray-500 font-bold uppercase tracking-tighter">Rollback Confidence Score</p>
                    <div className="mt-4 flex items-center gap-2">
                        <div className={`h-2 w-2 rounded-full ${data.rollbackMetrics.RCS >= 98.5 ? 'bg-green-500' : 'bg-orange-500'}`}></div>
                        <span className="text-[9px] font-bold text-gray-400 uppercase">Red-Line: 98.5%</span>
                    </div>
                </div>

                {/* Evidence Column 3: Critical Failures */}
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-4">Evidence: Safety</span>
                    <div className={`text-4xl font-black mb-1 ${data.simulationSummary.criticalFailures > 0 ? 'text-red-600' : 'text-green-600'}`}>
                        {data.simulationSummary.criticalFailures}
                    </div>
                    <p className="text-[10px] text-gray-500 font-bold uppercase tracking-tighter">Active Critical Failures</p>
                    <div className="mt-4 flex items-center gap-2">
                        <div className={`h-2 w-2 rounded-full ${data.simulationSummary.criticalFailures === 0 ? 'bg-green-500' : 'bg-red-500'}`}></div>
                        <span className="text-[9px] font-bold text-gray-400 uppercase">Target: 0</span>
                    </div>
                </div>
            </div>

            {/* Decision Details */}
            <div className="bg-white rounded-2xl p-8 border border-gray-100">
                <div className="mb-6 pb-6 border-b border-gray-50">
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-4">Official Governance Statement</span>
                    <p className={`text-lg font-bold leading-relaxed italic ${isReady ? 'text-green-800' : 'text-red-800'}`}>
                        "{decision.governanceStatement}"
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {/* Block Reasons */}
                    <div>
                        <span className="text-[9px] font-black text-red-600 uppercase tracking-widest block mb-4">Critical Block Reasons</span>
                        {decision.blockReasons.length > 0 ? (
                            <ul className="space-y-3">
                                {decision.blockReasons.map((reason, i) => (
                                    <li key={i} className="flex items-start gap-2 bg-red-50 p-3 rounded-xl border border-red-100">
                                        <span className="text-[10px] font-black text-red-700">⚠️</span>
                                        <span className="text-[10px] font-bold text-red-900">{reason}</span>
                                    </li>
                                ))}
                            </ul>
                        ) : (
                            <div className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">No active blocks</div>
                        )}
                    </div>

                    {/* Risk Flags & Escalation */}
                    <div>
                        <span className="text-[9px] font-black text-orange-600 uppercase tracking-widest block mb-4">Risk Flags & Escalation</span>
                        {decision.riskFlags.length > 0 || decision.cfoEscalationRequired ? (
                            <div className="space-y-4">
                                {decision.cfoEscalationRequired && (
                                    <div className="p-4 bg-orange-100 rounded-xl border border-orange-200">
                                        <span className="text-[10px] font-black text-orange-900 uppercase block mb-1">CFO Escalation Required</span>
                                        <p className="text-[10px] text-orange-800 leading-relaxed">
                                            Rollback Confidence is above floor (90%) but below Red-Line (98.5%). Mandatory CFO sign-off required.
                                        </p>
                                    </div>
                                )}
                                <ul className="space-y-2">
                                    {decision.riskFlags.map((flag, i) => (
                                        <li key={i} className="flex items-center gap-2 text-[10px] font-bold text-orange-700">
                                            <div className="h-1.5 w-1.5 rounded-full bg-orange-400"></div>
                                            {flag}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        ) : (
                            <div className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Cleared: No risk flags</div>
                        )}
                    </div>
                </div>
            </div>

            <div className="mt-10 text-center">
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest italic">
                    "Readiness is proven by evidence, not intent. AI does not trust. AI verifies."
                </p>
            </div>
        </div>
    );
}

// Approval History List - List of past approvals/rejections
// Shows status and who approved/rejected

'use client';

import React from 'react';

interface ApprovalHistory {
    id: string;
    ruleName: string;
    actionName: string;
    status: 'APPROVED' | 'REJECTED' | 'EXPIRED';
    approvedBy?: string;
    rejectedBy?: string;
    reason?: string;
    processedAt: Date;
    timeAgo: string;
}

interface ApprovalHistoryListProps {
    approvals: ApprovalHistory[];
    onSelectApproval: (id: string) => void;
}

export function ApprovalHistoryList({ approvals, onSelectApproval }: ApprovalHistoryListProps) {
    const getStatusIcon = (status: string) => {
        switch (status) {
            case 'APPROVED': return '✅';
            case 'REJECTED': return '❌';
            case 'EXPIRED': return '⏱️';
            default: return '•';
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'APPROVED': return 'text-green-600';
            case 'REJECTED': return 'text-red-600';
            case 'EXPIRED': return 'text-gray-600';
            default: return 'text-gray-600';
        }
    };

    return (
        <div className="space-y-3 max-h-[600px] overflow-y-auto">
            {approvals.map((approval) => (
                <div
                    key={approval.id}
                    onClick={() => onSelectApproval(approval.id)}
                    className="border border-gray-200 rounded-lg p-3 hover:bg-gray-50 cursor-pointer transition-colors"
                >
                    <div className="flex items-start space-x-2 mb-2">
                        <span className="text-lg">{getStatusIcon(approval.status)}</span>
                        <div className="flex-1">
                            <h3 className="text-sm font-medium text-gray-900">
                                {approval.ruleName}
                            </h3>
                            <p className="text-xs text-gray-500 mt-0.5">
                                {approval.actionName}
                            </p>
                        </div>
                        <span className={`text-xs font-medium ${getStatusColor(approval.status)}`}>
                            {approval.status}
                        </span>
                    </div>

                    <div className="text-xs text-gray-600">
                        {approval.status === 'APPROVED' && approval.approvedBy && (
                            <p>Approved by: <span className="font-medium">{approval.approvedBy}</span></p>
                        )}
                        {approval.status === 'REJECTED' && approval.rejectedBy && (
                            <div>
                                <p>Rejected by: <span className="font-medium">{approval.rejectedBy}</span></p>
                                {approval.reason && (
                                    <p className="text-gray-500 italic mt-1">"{approval.reason}"</p>
                                )}
                            </div>
                        )}
                        <p className="mt-1">{approval.timeAgo}</p>
                    </div>
                </div>
            ))}
        </div>
    );
}

import React, { useState } from 'react';
import { RiskBadge } from '../ui/CoreComponents';
import { AgreementSamplingCard } from '../trust/AgreementSamplingCard';

interface SimulationResult {
    decisionId?: string; // Standardized field for calibration
    ruleId: string;
    ruleName: string;
    triggered: boolean;
    confidenceScore: number;
    riskLevel: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
    blockReason?: string;
    estimatedImpact: {
        type: string;
        amount: number;
    };
    safetyGateResults: Array<{
        gate: string;
        passed: boolean;
        message?: string;
    }>;
    aiExplanationPreview: string;
}

interface SimulationResultListProps {
    brandId: string;
    results: SimulationResult[];
}

export function SimulationResultList({ brandId, results }: SimulationResultListProps) {
    return (
        <div className="space-y-4">
            {results.map((result) => (
                <ResultItem key={result.ruleId} brandId={brandId} result={result} />
            ))}
        </div>
    );
}

function ResultItem({ brandId, result }: { brandId: string; result: SimulationResult }) {
    const [showExplanation, setShowExplanation] = useState(false);
    const [showCalibration, setShowCalibration] = useState(false);

    return (
        <div className={`bg-white border rounded-xl shadow-sm transition-all ${result.blockReason ? 'border-red-200' : 'border-gray-100 hover:shadow-md'}`}>
            <div className="p-5">
                <div className="flex justify-between items-start mb-4">
                    <div className="flex-grow">
                        <div className="flex items-center gap-2 mb-1">
                            <h4 className="font-bold text-gray-800">{result.ruleName}</h4>
                            <RiskBadge tier={result.riskLevel} size="sm" />
                        </div>
                        <div className="text-xs font-mono text-gray-400">{result.ruleId}</div>
                    </div>
                    <div className="text-right">
                        <div className="text-sm font-bold text-gray-900 border-b border-gray-100 pb-1 mb-1">
                            Est. {result.estimatedImpact.type}
                        </div>
                        <div className="text-lg font-black text-green-600">
                            +IDR {result.estimatedImpact.amount.toLocaleString()}
                        </div>
                    </div>
                </div>

                {/* Simulation Alert */}
                {result.blockReason && (
                    <div className="mb-4 p-3 bg-red-50 border border-red-100 rounded-lg flex items-center gap-3">
                        <div className="bg-red-500 text-white rounded-full p-1">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" viewBox="0 0 20 20" fill="currentColor">
                                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                            </svg>
                        </div>
                        <span className="text-xs font-bold text-red-700 uppercase">Execution Blocked: {result.blockReason}</span>
                    </div>
                )}

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Safety Gate Checklist */}
                    <div className="bg-gray-50 rounded-lg p-3">
                        <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 block">Safety Gate Checklist</span>
                        <div className="space-y-1.5">
                            {result.safetyGateResults.map((gate, idx) => (
                                <div key={idx} className="flex items-center justify-between text-xs">
                                    <span className="text-gray-600">{gate.gate}</span>
                                    <div className="flex items-center gap-1.5">
                                        {gate.message && <span className="text-[10px] text-gray-400 italic">{gate.message}</span>}
                                        {gate.passed ? (
                                            <span className="text-green-500 font-bold">PASS</span>
                                        ) : (
                                            <span className="text-red-500 font-bold">FAIL</span>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Confidence Meter */}
                    <div className="bg-gray-50 rounded-lg p-3 flex flex-col justify-center">
                        <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Decision Confidence</span>
                        <div className="flex items-end gap-2">
                            <span className="text-2xl font-black text-gray-800">{(result.confidenceScore * 100).toFixed(0)}%</span>
                            <div className="flex-grow bg-gray-200 rounded-full h-2 mb-2">
                                <div
                                    className={`h-2 rounded-full ${result.confidenceScore >= 0.85 ? 'bg-green-500' : 'bg-yellow-500'}`}
                                    style={{ width: `${result.confidenceScore * 100}%` }}
                                ></div>
                            </div>
                        </div>
                        <span className="text-[9px] text-gray-400 italic">Target Threshold: 85%</span>
                    </div>
                </div>

                {/* Trust Calibration Section (UPGRADED) */}
                <div className="mt-4">
                    <button
                        onClick={() => setShowCalibration(!showCalibration)}
                        className={`w-full py-2 px-4 rounded-lg flex justify-between items-center transition-all ${showCalibration ? 'bg-blue-600 text-white' : 'bg-gray-50 text-gray-600 border border-gray-100 hover:bg-gray-100'}`}
                    >
                        <span className="text-[10px] font-black uppercase tracking-widest">
                            {showCalibration ? 'Hide Calibration Input' : '🚀 Calibrate Human Trust Alignment'}
                        </span>
                        {result.confidenceScore < 0.85 && !showCalibration && (
                            <span className="text-[8px] font-black bg-orange-500 text-white px-2 py-0.5 rounded animate-pulse">ACTION REQUIRED</span>
                        )}
                    </button>

                    {showCalibration && (
                        <div className="mt-3 animate-in fade-in slide-in-from-top-2 duration-300">
                            <AgreementSamplingCard
                                decisionId={result.decisionId || result.ruleId}
                                brandId={brandId}
                            />
                        </div>
                    )}
                </div>

                {/* AI Explanation Advisory */}
                <div className="mt-4 pt-4 border-t border-gray-100 flex justify-between items-center">
                    <button
                        onClick={() => setShowExplanation(!showExplanation)}
                        className="flex items-center gap-2 text-xs font-bold text-gray-400 hover:text-blue-600 transition-colors"
                    >
                        {showExplanation ? '⯆' : '⯈'} AI ADVISORY EXPLANATION
                    </button>

                    <div className="flex items-center gap-2">
                        <span className="text-[9px] font-black text-gray-300 uppercase">Observe Protocol Active</span>
                    </div>
                </div>

                {showExplanation && (
                    <div className="mt-2 p-3 bg-blue-50 bg-opacity-30 border-l-4 border-blue-400 text-sm text-gray-600 italic">
                        "{result.aiExplanationPreview}"
                        <div className="mt-2 text-[10px] text-blue-500 font-bold uppercase tracking-wider">
                            Advisory only. Final decision belongs to deterministic logic.
                        </div>
                    </div>
                )}
            </div>

            {/* Simulated Action Tag */}
            <div className="px-5 py-2 bg-yellow-50 rounded-b-xl border-t border-yellow-100 text-[10px] font-black text-yellow-700 flex justify-between items-center text-opacity-80">
                <span>INTENT: {result.blockReason ? 'BLOCK ' : 'SUGGEST '} [{result.ruleId}]</span>
                <span className="flex items-center gap-1">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" viewBox="0 0 20 20" fill="currentColor">
                        <path d="M7 3a1 1 0 000 2h6a1 1 0 100-2H7zM4 7a1 1 0 011-1h10a1 1 0 110 2H5a1 1 0 01-1-1zM2 11a2 2 0 012-2h12a2 2 0 012 2v4a2 2 0 01-2 2H4a2 2 0 01-2-2v-4z" />
                    </svg>
                    SIMULATED - NO ACTION
                </span>
            </div>
        </div>
    );
}

// Execution Details Modal - Full execution trace and snapshot viewer
// Shows complete audit trail and rollback capability

'use client';

import React, { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { RiskBadge } from '@/components/autonomous/ui/CoreComponents';

interface ExecutionDetailsModalProps {
    execution: {
        id: string;
        ruleName: string;
        ruleId: string;
        actionName: string;
        actionId: string;
        status: 'success' | 'rolled_back' | 'failed' | 'pending';
        riskTier: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
        estimatedImpact: number;
        actualImpact?: number;
        executedAt: Date;
        rolledBackAt?: Date;
        snapshotId?: string;
        rollbackAvailable: boolean;
        auditTrail: Array<{
            timestamp: Date;
            event: string;
            details?: string;
        }>;
        snapshot?: {
            preState: any;
            postState?: any;
        };
    };
    onClose: () => void;
}

export function ExecutionDetailsModal({ execution, onClose }: ExecutionDetailsModalProps) {
    const [showSnapshot, setShowSnapshot] = useState(false);
    const queryClient = useQueryClient();

    // Rollback mutation
    const rollbackMutation = useMutation({
        mutationFn: async (reason: string) => {
            const response = await fetch(`/api/autonomous-analytics/executions/${execution.id}/rollback`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    reason,
                    performedBy: 'current_user'
                })
            });

            if (!response.ok) throw new Error('Failed to rollback');
            return response.json();
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['executions'] });
            queryClient.invalidateQueries({ queryKey: ['execution-details', execution.id] });
            alert('Rollback executed successfully');
            onClose();
        }
    });

    const handleRollback = () => {
        const reason = prompt('Reason for rollback (required):');
        if (!reason || reason.length < 10) {
            alert('Please provide a reason (minimum 10 characters)');
            return;
        }

        if (confirm(`Rollback execution: ${execution.ruleName}?`)) {
            rollbackMutation.mutate(reason);
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'success': return 'text-green-600';
            case 'rolled_back': return 'text-yellow-600';
            case 'failed': return 'text-red-600';
            case 'pending': return 'text-blue-600';
            default: return 'text-gray-600';
        }
    };

    return (
        <div className="fixed inset-0 bg-gray-500 bg-opacity-75 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-lg max-w-4xl w-full max-h-[90vh] overflow-y-auto">
                {/* Header */}
                <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex justify-between items-start">
                    <div>
                        <h2 className="text-xl font-bold text-gray-900">{execution.ruleName}</h2>
                        <p className="text-sm text-gray-500 mt-1">{execution.actionName}</p>
                    </div>
                    <button
                        onClick={onClose}
                        className="text-gray-400 hover:text-gray-600"
                    >
                        ✕
                    </button>
                </div>

                {/* Content */}
                <div className="p-6 space-y-6">
                    {/* Status & Metrics */}
                    <div className="grid grid-cols-4 gap-4">
                        <div>
                            <div className="text-sm text-gray-600">Status</div>
                            <div className={`text-lg font-bold ${getStatusColor(execution.status)}`}>
                                {execution.status.replace('_', ' ').toUpperCase()}
                            </div>
                        </div>
                        <div>
                            <div className="text-sm text-gray-600">Risk Tier</div>
                            <div className="mt-1">
                                <RiskBadge tier={execution.riskTier} />
                            </div>
                        </div>
                        <div>
                            <div className="text-sm text-gray-600">Estimated Impact</div>
                            <div className="text-lg font-bold text-gray-900">
                                Rp {(execution.estimatedImpact / 1000).toFixed(0)}k
                            </div>
                        </div>
                        {execution.actualImpact !== undefined && (
                            <div>
                                <div className="text-sm text-gray-600">Actual Impact</div>
                                <div className="text-lg font-bold text-gray-900">
                                    Rp {(execution.actualImpact / 1000).toFixed(0)}k
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Execution Info */}
                    <div>
                        <h3 className="text-lg font-semibold text-gray-900 mb-2">Execution Info</h3>
                        <div className="bg-gray-50 rounded-lg p-4 space-y-2 text-sm">
                            <div className="flex justify-between">
                                <span className="text-gray-600">Execution ID:</span>
                                <span className="font-mono text-gray-900">{execution.id}</span>
                            </div>
                            <div className="flex justify-between">
                                <span className="text-gray-600">Executed At:</span>
                                <span className="text-gray-900">{new Date(execution.executedAt).toLocaleString('id-ID')}</span>
                            </div>
                            {execution.rolledBackAt && (
                                <div className="flex justify-between">
                                    <span className="text-gray-600">Rolled Back At:</span>
                                    <span className="text-gray-900">{new Date(execution.rolledBackAt).toLocaleString('id-ID')}</span>
                                </div>
                            )}
                            {execution.snapshotId && (
                                <div className="flex justify-between">
                                    <span className="text-gray-600">Snapshot ID:</span>
                                    <span className="font-mono text-gray-900">{execution.snapshotId}</span>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Audit Trail */}
                    <div>
                        <h3 className="text-lg font-semibold text-gray-900 mb-2">Audit Trail</h3>
                        <div className="bg-gray-50 rounded-lg p-4">
                            <div className="space-y-2">
                                {execution.auditTrail.map((entry, i) => (
                                    <div key={i} className="flex items-start space-x-3 text-sm">
                                        <span className="text-gray-500 font-mono text-xs whitespace-nowrap">
                                            {new Date(entry.timestamp).toLocaleTimeString('id-ID')}
                                        </span>
                                        <div className="flex-1">
                                            <div className="text-gray-900 font-medium">{entry.event}</div>
                                            {entry.details && (
                                                <div className="text-gray-600 text-xs mt-0.5">{entry.details}</div>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* Snapshot Viewer */}
                    {execution.snapshot && (
                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <h3 className="text-lg font-semibold text-gray-900">State Snapshot</h3>
                                <button
                                    onClick={() => setShowSnapshot(!showSnapshot)}
                                    className="text-sm text-blue-600 hover:text-blue-800"
                                >
                                    {showSnapshot ? 'Hide' : 'Show'} Snapshot
                                </button>
                            </div>

                            {showSnapshot && (
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <h4 className="text-sm font-medium text-gray-700 mb-2">Pre-Execution State</h4>
                                        <pre className="bg-gray-900 text-green-400 p-4 rounded text-xs overflow-x-auto">
                                            {JSON.stringify(execution.snapshot.preState, null, 2)}
                                        </pre>
                                    </div>
                                    {execution.snapshot.postState && (
                                        <div>
                                            <h4 className="text-sm font-medium text-gray-700 mb-2">Post-Execution State</h4>
                                            <pre className="bg-gray-900 text-green-400 p-4 rounded text-xs overflow-x-auto">
                                                {JSON.stringify(execution.snapshot.postState, null, 2)}
                                            </pre>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Actions */}
                {execution.rollbackAvailable && execution.status === 'success' && (
                    <div className="sticky bottom-0 bg-gray-50 px-6 py-4 border-t border-gray-200">
                        <div className="flex gap-3">
                            <button
                                onClick={handleRollback}
                                disabled={rollbackMutation.isPending}
                                className="px-4 py-2 bg-yellow-600 text-white rounded-md hover:bg-yellow-700 font-medium disabled:opacity-50"
                            >
                                {rollbackMutation.isPending ? 'Rolling back...' : 'Rollback Execution'}
                            </button>
                            <button
                                onClick={onClose}
                                className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300 font-medium"
                            >
                                Close
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

import React, { useState } from 'react';
import { LoadingSpinner, RiskBadge } from '../ui/CoreComponents';
import { SimulationResultList } from '../lists/SimulationResultList';

interface SimulationPanelProps {
    brandId: string;
}

export function SimulationPanel({ brandId }: SimulationPanelProps) {
    const [simulateMode, setSimulateMode] = useState<boolean>(false);
    const [loading, setLoading] = useState<boolean>(false);
    const [results, setResults] = useState<any[]>([]);
    const [domain, setDomain] = useState<string>('ALL');

    const runSimulation = async () => {
        setLoading(true);
        setResults([]);

        try {
            const response = await fetch('/api/autonomous-analytics/simulation', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    brandId,
                    domain: domain === 'ALL' ? undefined : domain
                })
            });

            if (!response.ok) throw new Error('Simulation failed');

            const data = await response.json();

            // Map DecisionResult to our UI display format
            const mappedResults = data.results.map((r: any) => ({
                ruleId: r.ruleId,
                ruleName: r.ruleName,
                triggered: r.triggered,
                confidenceScore: r.confidenceScore,
                riskLevel: r.riskLevel,
                blockReason: r.blockReason,
                estimatedImpact: r.estimatedImpact,
                safetyGateResults: r.safetyGateResults,
                aiExplanationPreview: r.explanation || "AI Evaluation completed based on deterministic rule sets."
            }));

            setResults(mappedResults);
            setSimulateMode(true);
        } catch (error) {
            console.error('Simulation failed:', error);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="bg-gray-50 border border-gray-200 rounded-xl relative overflow-hidden">
            {/* Watermark */}
            <div className="absolute top-4 right-4 rotate-12 opacity-10 pointer-events-none select-none">
                <span className="text-4xl font-black text-blue-600 border-4 border-blue-600 p-2">SIMULATION MODE</span>
            </div>

            <div className="p-6">
                <div className="flex justify-between items-center mb-6">
                    <div>
                        <h2 className="text-lg font-bold text-gray-800">Simulation Center (The Safe Lab)</h2>
                        <p className="text-sm text-gray-500">Run safe, read-only scenarios to validate rule logic without affecting production.</p>
                    </div>

                    <div className="flex gap-2">
                        <select
                            value={domain}
                            onChange={(e) => setDomain(e.target.value)}
                            className="bg-white border border-gray-300 text-gray-700 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block p-2.5"
                        >
                            <option value="ALL">All Domains</option>
                            <option value="SALES">Sales Optimization</option>
                            <option value="INVENTORY">Inventory Management</option>
                            <option value="ADS">Ad Spend Control</option>
                        </select>

                        <button
                            onClick={runSimulation}
                            disabled={loading}
                            className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors disabled:opacity-50"
                        >
                            {loading ? <LoadingSpinner size="sm" /> : 'Run Simulation'}
                        </button>
                    </div>
                </div>

                {loading && (
                    <div className="py-12 flex flex-col items-center justify-center text-gray-400">
                        <LoadingSpinner size="lg" />
                        <p className="mt-4 animate-pulse">AI Simulation in progress... evaluating safety gates...</p>
                    </div>
                )}

                {simulateMode && !loading && (
                    <div className="space-y-6">
                        <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 flex items-center justify-between">
                            <span className="text-sm font-medium text-blue-800">Found {results.filter(r => r.triggered).length} potential outcomes for brand: <strong>{brandId}</strong></span>
                            <span className="text-xs font-bold text-blue-600 uppercase">Snapshot: Read-Only Simulation</span>
                        </div>

                        <SimulationResultList brandId={brandId} results={results} />
                    </div>
                )}

                {!simulateMode && !loading && (
                    <div className="py-12 text-center">
                        <div className="bg-white inline-flex p-4 rounded-full shadow-sm mb-4">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.642.386a6 6 0 01-3.86.517l-2.387-.477a2 2 0 00-1.022.547l-1.168 1.168a2 2 0 01-2.828 0l-.168-.168a2 2 0 010-2.828l1.168-1.168a2 2 0 00.547-1.022l.477-2.387a6 6 0 01.517-3.86l.386-.642a6 6 0 00.517-3.86l-.477-2.387a2 2 0 00-.547-1.022l-1.168-1.168a2 2 0 010-2.828l.168-.168a2 2 0 012.828 0l1.168 1.168a2 2 0 001.022.547l2.387.477a6 6 0 003.86-.517l.642-.386a6 6 0 013.86-.517l2.387.477a2 2 0 001.022-.547l1.168-1.168a2 2 0 012.828 0l.168.168a2 2 0 010 2.828l-1.168 1.168a2 2 0 00-.547 1.022l-.477 2.387a6 6 0 00-.517 3.86l-.386.642a6 6 0 01-.517 3.86l.477 2.387a2 2 0 00.547 1.022l1.168 1.168a2 2 0 010 2.828l-.168.168a2 2 0 01-2.828 0l-1.168-1.168z" />
                            </svg>
                        </div>
                        <h3 className="text-gray-600 font-medium">Ready for Stress Test</h3>
                        <p className="text-gray-400 text-sm max-w-xs mx-auto">Click "Run Simulation" to see how current rules would respond to latest market conditions.</p>
                    </div>
                )}
            </div>

            {/* CFO Safety Interlock Footer */}
            <div className="px-6 py-3 bg-gray-100 border-t border-gray-200 flex items-center justify-between text-[10px] text-gray-500 uppercase tracking-widest font-bold">
                <span>Safe Lab Context: Read-Only (Determinism: 1.0)</span>
