        </div>
    );
}

import React from 'react';

export interface Suggestion {
    id: string;
    brandId: string;
    domain: string;
    title: string;
    proposedAction: string;
    rationale: string[];
    expectedImpact: {
        metric: string;
        direction: 'UP' | 'DOWN';
        confidence: number;
    };
    confidenceScore: number;
    riskLevel: 'LOW' | 'MEDIUM' | 'HIGH';
    phaseGate: string;
    createdAt: string;
}

interface SuggestionCardProps {
    suggestion: Suggestion;
    onClick: (suggestion: Suggestion) => void;
}

export function SuggestionCard({ suggestion, onClick }: SuggestionCardProps) {
    const isHighRisk = suggestion.riskLevel === 'HIGH';
    const isLowConfidence = suggestion.confidenceScore < 0.8;

    return (
        <div
            onClick={() => onClick(suggestion)}
            className={`group bg-white border-2 rounded-2xl p-6 cursor-pointer transition-all hover:shadow-xl hover:-translate-y-1 ${isHighRisk ? 'border-orange-100 hover:border-orange-300' : 'border-gray-50 hover:border-blue-200'
                }`}
        >
            {/* Safety Label */}
            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-2">
                    <span className="text-[10px] font-black bg-blue-50 text-blue-600 px-2 py-0.5 rounded tracking-widest uppercase">
                        {suggestion.domain}
                    </span>
                    <span className="h-1 w-1 rounded-full bg-gray-200"></span>
                    <span className={`text-[10px] font-bold uppercase tracking-widest ${isHighRisk ? 'text-orange-600' : 'text-gray-400'}`}>
                        {suggestion.riskLevel} Risk
                    </span>
                </div>
                {isLowConfidence && (
                    <span className="px-2 py-0.5 bg-yellow-400 text-black text-[9px] font-black uppercase italic rounded tracking-tighter">
                        Low Confidence
                    </span>
                )}
            </div>

            <h3 className="text-lg font-black text-gray-800 leading-tight mb-3 group-hover:text-blue-600 transition-colors">
                {suggestion.title}
            </h3>

            <p className="text-xs text-gray-500 mb-6 bg-gray-50 p-3 rounded-xl italic font-medium leading-relaxed">
                "{suggestion.proposedAction}"
            </p>

            <div className="grid grid-cols-2 gap-4 mb-6 border-t border-gray-50 pt-6">
                <div>
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-1">Expected Impact</span>
                    <div className="flex items-center gap-1.5">
                        <span className={`text-sm font-black ${suggestion.expectedImpact.direction === 'UP' ? 'text-green-600' : 'text-red-500'}`}>
                            {suggestion.expectedImpact.direction === 'UP' ? '▲' : '▼'} {suggestion.expectedImpact.metric}
                        </span>
                    </div>
                </div>
                <div>
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-1">AI Confidence</span>
                    <div className="text-sm font-black text-gray-700">
                        {(suggestion.confidenceScore * 100).toFixed(0)}%
                    </div>
                </div>
            </div>

            {/* Formal Adhesive Info */}
            <div className="flex justify-between items-center py-3 px-4 bg-gray-900 rounded-xl">
                <span className="text-[9px] font-black text-white uppercase tracking-widest">
                    AI SUGGESTION — NOT EXECUTED
                </span>
                <div className="flex gap-1">
                    <div className="h-1 w-1 rounded-full bg-blue-100"></div>
                    <div className="h-1 w-1 rounded-full bg-blue-300"></div>
                    <div className="h-1 w-1 rounded-full bg-blue-500"></div>
                </div>
            </div>
        </div>
    );
}

import React, { useState } from 'react';
import { Suggestion } from './SuggestionCard';

interface SuggestionDetailDrawerProps {
    suggestion: Suggestion | null;
    onClose: () => void;
    onFeedback: () => void;
}

export function SuggestionDetailDrawer({ suggestion, onClose, onFeedback }: SuggestionDetailDrawerProps) {
    const [reason, setReason] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    if (!suggestion) return null;

    const handleFeedback = async (decision: 'ACCEPTED' | 'REJECTED' | 'DEFERRED') => {
        setIsSubmitting(true);
        try {
            const response = await fetch('/api/autonomous-analytics/suggestions/feedback', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    suggestionId: suggestion.id,
                    operatorId: 'BOARD_MEMBER_01',
                    decision,
                    reason: reason || undefined
                })
            });

            if (response.ok) {
                onFeedback();
                onClose();
            }
        } catch (error) {
            console.error('Record Feedback Error:', error);
        } finally {
            setIsSubmitting(false);
        }
    };

    const handlePromote = async () => {
        setIsSubmitting(true);
        try {
            const response = await fetch('/api/autonomous-analytics/assisted-actions', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    action: 'PROMOTE',
                    suggestionId: suggestion.id
                })
            });

            if (response.ok) {
                onFeedback();
                onClose();
            }
        } catch (error) {
            console.error('Promotion Error:', error);
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 overflow-hidden">
            <div className="absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity" onClick={onClose}></div>

            <div className="absolute inset-y-0 right-0 max-w-xl w-full bg-white shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
                {/* Header */}
                <div className="px-8 py-6 border-b border-gray-100 flex justify-between items-center bg-[#fafbfc]">
                    <div>
                        <div className="flex items-center gap-2 mb-1">
                            <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 px-2 py-0.5 rounded">Advisory Mode</span>
                            <span className="text-[10px] text-gray-400 font-mono">ID: {suggestion.id}</span>
                        </div>
                        <h2 className="text-xl font-black text-gray-800 tracking-tight">Suggestion Analysis</h2>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-400">✕</button>
                </div>

                {/* Content */}
                <div className="flex-grow overflow-y-auto px-8 py-8 space-y-8">
                    {/* Summary & Impact */}
                    <div className="bg-gray-900 rounded-2xl p-6 text-white">
                        <h3 className="text-lg font-bold mb-4">{suggestion.title}</h3>
                        <p className="text-sm text-gray-300 italic mb-6">"{suggestion.proposedAction}"</p>

                        <div className="grid grid-cols-2 gap-4">
                            <div className="p-4 bg-white/5 rounded-xl border border-white/10">
                                <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-1">Projected Shift</span>
                                <div className={`text-sm font-black ${suggestion.expectedImpact.direction === 'UP' ? 'text-green-400' : 'text-red-400'}`}>
                                    {suggestion.expectedImpact.direction} {suggestion.expectedImpact.metric}
                                </div>
                            </div>
                            <div className="p-4 bg-white/5 rounded-xl border border-white/10">
                                <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-1">System Confidence</span>
                                <div className="text-sm font-black text-blue-400">
                                    {(suggestion.confidenceScore * 100).toFixed(0)}%
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Rationale Section */}
                    <div>
                        <div className="flex items-center gap-2 mb-4">
                            <h4 className="text-[11px] font-black text-gray-400 uppercase tracking-widest">Evidence & Rationale</h4>
                            <div className="h-px flex-grow bg-gray-100"></div>
                        </div>
                        <ul className="space-y-4">
                            {suggestion.rationale.map((item, idx) => (
                                <li key={idx} className="flex gap-4 items-start p-4 bg-gray-50 rounded-xl border border-gray-100">
                                    <span className="text-blue-600 font-bold text-xs mt-0.5">•</span>
                                    <p className="text-sm text-gray-600 leading-relaxed font-medium">
                                        {item}
                                    </p>
                                </li>
                            ))}
                        </ul>
                    </div>

                    {/* Risk Disclosure */}
                    <div className={`p-6 rounded-2xl border ${suggestion.riskLevel === 'HIGH' ? 'bg-orange-50 border-orange-100' : 'bg-blue-50 border-blue-100'}`}>
                        <div className="flex items-center gap-2 mb-3">
                            <span className={`p-1 rounded ${suggestion.riskLevel === 'HIGH' ? 'bg-orange-200' : 'bg-blue-200'}`}>
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                                </svg>
                            </span>
                            <h4 className={`text-[11px] font-black uppercase tracking-widest ${suggestion.riskLevel === 'HIGH' ? 'text-orange-800' : 'text-blue-800'}`}>
                                Risk Disclosure: {suggestion.riskLevel} Tier
                            </h4>
                        </div>
                        {suggestion.riskLevel === 'HIGH' && (
                            <p className="text-xs text-orange-700 font-bold mb-4 animate-pulse">
                                ⚠️ ATTENTION: High-risk scenario detected. Detailed manual validation in external system is MANDATORY.
                            </p>
                        )}
                        <p className="text-xs text-gray-600 italic leading-relaxed">
                            This analysis is strictly advisory. The system does not possess execution authority. Any implementation of this suggestion must be performed manually by an authorized operator through external management consoles.
                        </p>
                    </div>

                    {/* Manual Steps Checklist */}
                    <div className="p-6 bg-[#fafbfc] rounded-2xl border border-gray-100">
                        <h4 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4">Manual Action Protocol (Outside System)</h4>
                        <div className="space-y-4">
                            <div className="flex items-start gap-3">
                                <div className="mt-1 h-3 w-3 border-2 border-blue-600 rounded"></div>
                                <p className="text-xs text-gray-500">Log in to primary management console (Ads Manager/ERP/Price Controller).</p>
                            </div>
                            <div className="flex items-start gap-3">
                                <div className="mt-1 h-3 w-3 border-2 border-blue-600 rounded"></div>
                                <p className="text-xs text-gray-500">Search for SKU/Campaign: <span className="font-bold text-gray-700">{suggestion.title.split(' ').slice(-2).join(' ')}</span>.</p>
                            </div>
                            <div className="flex items-start gap-3">
                                <div className="mt-1 h-3 w-3 border-2 border-blue-600 rounded"></div>
                                <p className="text-xs text-gray-500">Apply the shift detailed in: <span className="italic">"{suggestion.proposedAction}"</span>.</p>
                            </div>
                        </div>
                    </div>

                    {/* Feedback Form */}
                    <div className="pt-8 border-t border-gray-100">
                        <h4 className="text-[11px] font-black text-gray-400 uppercase tracking-widest mb-4">Governor Review Feedback</h4>
                        <textarea
                            value={reason}
                            onChange={(e) => setReason(e.target.value)}
                            placeholder="Optional: Justification for decision..."
                            className="w-full h-24 p-4 bg-gray-50 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 focus:bg-white transition-all outline-none"
                        ></textarea>
                    </div>
                </div>

                {/* Footer Controls */}
                <div className="px-8 py-6 bg-white border-t border-gray-100 space-y-4">
                    <button
                        onClick={() => handleFeedback('ACCEPTED')}
                        disabled={isSubmitting}
                        className="w-full py-4 bg-blue-600 text-white rounded-xl text-sm font-black uppercase tracking-widest shadow-lg shadow-blue-200 hover:bg-blue-700 hover:shadow-xl transition-all disabled:opacity-50"
                    >
                        {isSubmitting ? 'Registering...' : 'Mark as Considered'}
                    </button>

                    <div className="flex gap-4">
                        <button
                            onClick={() => handleFeedback('REJECTED')}
                            disabled={isSubmitting}
                            className="flex-1 py-3 bg-white border border-gray-200 text-gray-600 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-50 hover:text-red-600 hover:border-red-100 transition-all disabled:opacity-50"
                        >
                            Reject Suggestion
                        </button>
                        <button
                            onClick={() => handleFeedback('DEFERRED')}
                            disabled={isSubmitting}
                            className="flex-1 py-4 border border-gray-200 rounded-2xl text-[10px] font-black uppercase tracking-widest text-gray-500 hover:bg-gray-50 transition-all"
                        >
                            Defer
                        </button>
                        <button
                            onClick={handlePromote}
                            disabled={isSubmitting}
                            className="flex-1 py-4 bg-gray-900 border border-gray-900 rounded-2xl text-[10px] font-black uppercase tracking-widest text-white hover:bg-black transition-all shadow-lg shadow-gray-200"
                        >
                            Promote to Action
                        </button>
                    </div>

                    {/* Professional Disclaimer */}
                    <div className="text-center">
                        <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tight leading-relaxed">
                            Sistem ini memberikan saran berbasis data historis. Keputusan akhir sepenuhnya berada di tangan Anda.
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
}

import React, { useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Suggestion, SuggestionCard } from './SuggestionCard';
import { SuggestionDetailDrawer } from './SuggestionDetailDrawer';

interface SuggestionInboxProps {
    brandId: string;
    onActionPromoted?: () => void;
}

export function SuggestionInbox({ brandId, onActionPromoted }: SuggestionInboxProps) {
    const [selectedSuggestion, setSelectedSuggestion] = useState<Suggestion | null>(null);
    const queryClient = useQueryClient();

    const { data: suggestionData, isLoading: loadingSuggestions, refetch } = useQuery({
        queryKey: ['suggestions', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/suggestions?brandId=${brandId}`).then(r => r.json())
    });

    const { data: verdictData, isLoading: loadingVerdict } = useQuery({
        queryKey: ['trust-verdict', brandId],
        queryFn: () => fetch(`/api/autonomous-analytics/trust/verdict?brandId=${brandId}`).then(r => r.json())
    });

    const suggestions = suggestionData?.suggestions || [];
    const isLocked = verdictData?.verdict !== 'CONDITIONALLY_READY' || verdictData?.observation_days < 30;

    const handleFeedback = () => {
        queryClient.invalidateQueries({ queryKey: ['suggestions', brandId] });
        refetch();
        if (onActionPromoted) onActionPromoted();
    };

    if (loadingSuggestions || loadingVerdict) {
        return (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-pulse">
                {[1, 2, 3].map(i => (
                    <div key={i} className="h-64 bg-gray-50 rounded-2xl border-2 border-dashed border-gray-100"></div>
                ))}
            </div>
        );
    }

    if (isLocked) {
        return (
            <div className="bg-gray-50 border-2 border-dashed border-gray-200 rounded-3xl p-12 text-center">
                <div className="inline-flex items-center justify-center p-4 bg-white rounded-full shadow-sm mb-6">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-gray-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                    </svg>
                </div>
                <h3 className="text-xl font-black text-gray-800 uppercase tracking-tighter mb-2">Suggestion Mode Locked</h3>
                <p className="text-sm text-gray-400 max-w-md mx-auto leading-relaxed">
                    Suggest Mode requires a minimum of 30 observation days and a "CONDITIONALLY_READY" governance verdict.
                    Current progress: <span className="font-bold text-blue-600">{verdictData?.observation_days} / 30 days</span>.
                </p>

                <div className="mt-8 pt-8 border-t border-gray-100 flex justify-center gap-8">
                    <div className="text-center">
                        <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest block mb-1">Status</span>
                        <span className="text-xs font-bold text-gray-500 uppercase">{verdictData?.verdict.replace('_', ' ') || 'LOCKED'}</span>
                    </div>
                    <div className="text-center">
                        <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest block mb-1">Safety Gate</span>
                        <span className="text-xs font-bold text-gray-500 uppercase">Interlocked</span>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8">
            {/* Global Advisory Banner */}
            <div className="bg-green-50 border border-green-100 rounded-2xl px-6 py-4 flex flex-col md:flex-row justify-between items-center gap-4">
                <div className="flex items-center gap-3">
                    <span className="flex h-3 w-3 relative">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                    </span>
                    <span className="text-xs font-black text-green-800 uppercase tracking-widest">
                        Suggest Mode — Human Action Required Outside System
                    </span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="flex -space-x-1">
                        {[1, 2, 3].map(i => <div key={i} className="h-5 w-5 rounded-full border-2 border-green-50 bg-green-100 flex items-center justify-center text-[8px] font-bold text-green-600">G{i}</div>)}
                    </div>
                    <span className="text-[10px] font-bold text-green-600 uppercase">Governance v3.0 Active</span>
                </div>
            </div>

            {suggestions.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 bg-white rounded-3xl border border-gray-50 shadow-sm">
                    <div className="h-12 w-12 bg-blue-50 text-blue-500 rounded-full flex items-center justify-center mb-4">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
                        </svg>
                    </div>
                    <h4 className="text-sm font-black text-gray-800 uppercase tracking-widest mb-1">Heuristic Engine Analyzing...</h4>
                    <p className="text-xs text-gray-400 font-medium">No actionable advisory drafts present for this segment.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {suggestions.map((s: any) => (
                        <SuggestionCard
                            key={s.id}
                            suggestion={{
                                id: s.id,
                                brandId: s.brandId,
                                domain: s.domain,
                                title: s.title,
                                proposedAction: s.proposedAction,
                                rationale: s.rationale,
                                expectedImpact: s.expectedImpact,
                                confidenceScore: s.confidenceScore,
                                riskLevel: s.riskLevel,
                                phaseGate: s.phaseGate,
                                createdAt: s.createdAt
                            }}
                            onClick={(item) => setSelectedSuggestion(item)}
                        />
                    ))}
                </div>
            )}

            <SuggestionDetailDrawer
                suggestion={selectedSuggestion}
                onClose={() => setSelectedSuggestion(null)}
                onFeedback={handleFeedback}
            />
        </div>
    );
}

import React from 'react';

interface QualityReport {
    acceptanceRatio: number;
    deferredAgingIndex: number;
    rejectionReasonClusters: { reason: string; count: number }[];
    status: 'HEALTHY' | 'NOISY' | 'LOW_SIGNAL' | 'INCONSISTENT';
    lastUpdated: string;
}

interface SuggestionQualityDashboardProps {
    report: QualityReport | null;
    loading?: boolean;
}

export function SuggestionQualityDashboard({ report, loading }: SuggestionQualityDashboardProps) {
    if (loading || !report) {
        return <div className="h-64 bg-gray-50 animate-pulse rounded-2xl border-2 border-dashed border-gray-100"></div>;
    }

    const statusColors = {
        HEALTHY: 'text-green-600 bg-green-50 border-green-100',
        NOISY: 'text-orange-600 bg-orange-50 border-orange-100',
        LOW_SIGNAL: 'text-blue-600 bg-blue-50 border-blue-100',
        INCONSISTENT: 'text-red-600 bg-red-50 border-red-100'
    };

    const acceptancePercent = (report.acceptanceRatio * 100).toFixed(0);

    return (
        <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-8">
            <div className="flex justify-between items-start mb-10">
                <div>
                    <h3 className="text-xl font-black text-gray-800 tracking-tight mb-1">Suggestion Quality Audit</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest leading-loose">
                        Phase 3.5: Evaluating AI Sanity & Relevance
                    </p>
                </div>
                <div className={`px-4 py-2 rounded-xl border font-black text-[10px] uppercase tracking-widest ${statusColors[report.status]}`}>
                    {report.status.replace('_', ' ')}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Metric A: Acceptance Ratio */}
                <div className="p-6 bg-gray-50 rounded-2xl border border-gray-100">
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-4">Quality Signal</span>
                    <div className="flex items-end gap-2 mb-2">
                        <div className="text-4xl font-black text-gray-800">{acceptancePercent}%</div>
                        <span className="text-xs font-bold text-gray-400 pb-1">Acceptance</span>
                    </div>
                    <div className="w-full bg-gray-200 h-1.5 rounded-full overflow-hidden">
                        <div
                            className={`h-full transition-all duration-1000 ${report.acceptanceRatio < 0.4 ? 'bg-red-500' : 'bg-green-500'}`}
                            style={{ width: `${acceptancePercent}%` }}
                        ></div>
                    </div>
                    <p className="text-[9px] text-gray-400 mt-4 italic">
                        {report.acceptanceRatio < 0.4 ? '⚠️ Divergence Threshold: High human friction detected.' : 'AI output matches human business judgment.'}
                    </p>
                </div>

                {/* Metric B: Aging Index */}
                <div className="p-6 bg-gray-50 rounded-2xl border border-gray-100">
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-4">Context Mismatch Index</span>
                    <div className="flex items-end gap-2 mb-2">
                        <div className="text-4xl font-black text-gray-800">{report.deferredAgingIndex.toFixed(1)}</div>
                        <span className="text-xs font-bold text-gray-400 pb-1">Days Deferred</span>
                    </div>
                    <p className="text-[10px] text-gray-500 leading-relaxed font-medium mt-auto">
                        High aging indicates suggestions that are conceptually valid but lack timing or actionability context.
                    </p>
                </div>

                {/* Metric C: Cluster Insight */}
                <div className="p-6 bg-gray-900 rounded-2xl text-white">
                    <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-4">Top Human Rejection Reasons</span>
                    <div className="space-y-4">
                        {report.rejectionReasonClusters.length > 0 ? report.rejectionReasonClusters.map((cluster, i) => (
                            <div key={i} className="flex justify-between items-center bg-white/5 p-3 rounded-xl border border-white/10">
                                <span className="text-[10px] font-bold text-gray-300">{cluster.reason}</span>
                                <span className="text-[10px] font-black text-blue-400">{cluster.count}</span>
                            </div>
                        )) : (
                            <div className="text-[10px] text-gray-500 italic py-4">No rejection data available.</div>
                        )}
                    </div>
                </div>
            </div>

            <div className="mt-8 pt-8 border-t border-gray-100 text-center">
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tight italic">
                    "Executive confidence does not equal system permission. Audit evaluates AI output quality only."
                </p>
            </div>
        </div>
    );
}

import React, { useState } from 'react';
import { RiskBadge, StatusBadge } from '../ui/CoreComponents';
import { format } from 'date-fns';
import { AgreementSamplingCard } from '../trust/AgreementSamplingCard';

interface DecisionLogItem {
    id: string;
    decisionId?: string; // Standardized field
    ruleId: string;
    ruleName: string;
    domain?: string;
    riskLevel: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
    suggestedAction: string;
    impactAmount?: number;
    currency?: string;
    status: 'SUCCESS' | 'FAILED' | 'BLOCKED' | 'PENDING' | 'SIMULATED';
    executedAt: Date;
    metadata?: any;
    blockReason?: string;
}

interface DecisionAuditTableProps {
    brandId: string;
    data: DecisionLogItem[];
    loading?: boolean;
}

export function DecisionAuditTable({ brandId, data, loading }: DecisionAuditTableProps) {
    const [selectedItem, setSelectedItem] = useState<DecisionLogItem | null>(null);

    if (loading) {
        return (
            <div className="bg-white shadow rounded-lg overflow-hidden animate-pulse">
                <div className="h-10 bg-gray-50 border-b border-gray-200"></div>
                {[1, 2, 3, 4, 5].map((i) => (
                    <div key={i} className="h-16 border-b border-gray-100 px-6 flex items-center gap-4">
                        <div className="h-4 bg-gray-200 rounded w-24"></div>
                        <div className="h-4 bg-gray-200 rounded w-48"></div>
                        <div className="h-4 bg-gray-200 rounded w-16"></div>
                        <div className="flex-grow"></div>
                        <div className="h-4 bg-gray-200 rounded w-20"></div>
                    </div>
                ))}
            </div>
        );
    }

    if (data.length === 0) {
        return (
            <div className="bg-white shadow rounded-lg p-12 text-center text-gray-500">
                <p>No decision history found for this brand.</p>
            </div>
        );
    }

    return (
        <div className="bg-white shadow rounded-lg overflow-hidden">
            <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Executed At</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Rule</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Risk Tier</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Suggested Action</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Est. Impact</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Audit Status</th>
                            <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Trace</th>
                        </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {data.map((item) => (
                            <tr key={item.id} className="hover:bg-gray-50 transition-colors">
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                    {format(new Date(item.executedAt), 'MMM d, HH:mm:ss')}
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap">
                                    <div className="text-sm font-medium text-blue-600 truncate max-w-[200px]" title={item.ruleName}>
                                        {item.ruleName}
                                    </div>
                                    <div className="text-xs text-gray-400 font-mono">{item.ruleId}</div>
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap">
                                    <RiskBadge tier={item.riskLevel} size="sm" />
                                </td>
                                <td className="px-6 py-4 text-sm text-gray-600 max-w-xs truncate">
                                    {item.suggestedAction}
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                                    {item.impactAmount ? `${item.currency || 'IDR'} ${item.impactAmount.toLocaleString()}` : '-'}
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap">
                                    <div className="flex flex-col gap-1">
                                        <StatusBadge
                                            status={item.status === 'SUCCESS' ? 'OK' : item.status === 'PENDING' ? 'REVIEW' : 'PAUSE'}
                                            size="sm"
                                        />
                                        {item.status === 'BLOCKED' && item.blockReason && (
                                            <span className="text-[10px] text-red-500 font-medium max-w-[120px] truncate" title={item.blockReason}>
                                                Reason: {item.blockReason}
                                            </span>
                                        )}
                                    </div>
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                    <button
                                        onClick={() => setSelectedItem(item)}
                                        className="text-gray-400 hover:text-blue-600 transition-colors"
                                        title="View Evaluation Metadata"
                                    >
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                                            <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                                        </svg>
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Traceability Modal (Read-Only JSON View) */}
            {selectedItem && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
                    <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full max-h-[90vh] flex flex-col overflow-hidden">
                        <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
