import React from 'react';

interface ExecutiveConfidenceDashboardProps {
    score: number;
    dimensions: {
        operational: number;
        risk: number;
        explainability: number;
        psychological: number;
    };
    status: 'CRITICAL' | 'CAUTION' | 'ALIGNED' | 'PENDING';
    loading?: boolean;
}

export function ExecutiveConfidenceDashboard({ score, dimensions, status, loading }: ExecutiveConfidenceDashboardProps) {
    if (loading) {
        return <div className="h-64 bg-gray-50 animate-pulse rounded-2xl border-2 border-dashed border-gray-100"></div>;
    }

    const size = 220;
    const center = size / 2;
    const radius = size * 0.4;

    const getPoint = (val: number, angleDeg: number) => {
        const angleRad = (angleDeg - 90) * (Math.PI / 180);
        const normalizedVal = val / 100;
        return {
            x: center + (radius * normalizedVal) * Math.cos(angleRad),
            y: center + (radius * normalizedVal) * Math.sin(angleRad)
        };
    };

    const pOp = getPoint(dimensions.operational, 0);
    const pRisk = getPoint(dimensions.risk, 90);
    const pExp = getPoint(dimensions.explainability, 180);
    const pPsy = getPoint(dimensions.psychological, 270);

    const radarPath = `M ${pOp.x} ${pOp.y} L ${pRisk.x} ${pRisk.y} L ${pExp.x} ${pExp.y} L ${pPsy.x} ${pPsy.y} Z`;

    const statusColors = {
        CRITICAL: 'text-red-600 bg-red-50 border-red-100',
        CAUTION: 'text-orange-600 bg-orange-50 border-orange-100',
        ALIGNED: 'text-green-600 bg-green-50 border-green-100',
        PENDING: 'text-gray-400 bg-gray-50 border-gray-100'
    };

    return (
        <div className="bg-white rounded-3xl shadow-sm border border-gray-100 p-8">
            <div className="flex justify-between items-start mb-10">
                <div>
                    <h3 className="text-xl font-black text-gray-800 tracking-tight mb-1">Executive Confidence Review</h3>
                    <p className="text-xs text-gray-400 font-medium italic">"Executive confidence does not equal system permission."</p>
                </div>
                <div className={`px-4 py-2 rounded-xl border font-black text-xs uppercase tracking-widest ${statusColors[status]}`}>
                    {status}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
                {/* Radar Visualization */}
                <div className="relative flex justify-center">
                    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
                        {/* Grids */}
                        {[20, 40, 60, 80, 100].map((lvl) => (
                            <circle key={lvl} cx={center} cy={center} r={radius * (lvl / 100)} fill="none" stroke="#f1f5f9" strokeWidth="1" />
                        ))}

                        {/* Axes */}
                        {[0, 90, 180, 270].map((ang) => {
                            const p = getPoint(100, ang);
                            return <line key={ang} x1={center} y1={center} x2={p.x} y2={p.y} stroke="#f1f5f9" strokeWidth="1" />;
                        })}

                        {/* Radar Shape */}
                        <path d={radarPath} fill="rgba(37, 99, 235, 0.1)" stroke="#2563eb" strokeWidth="3" className="transition-all duration-1000" />

                        {/* Markers */}
                        <circle cx={pOp.x} cy={pOp.y} r="5" fill="#2563eb" />
                        <circle cx={pRisk.x} cy={pRisk.y} r="5" fill="#f59e0b" />
                        <circle cx={pExp.x} cy={pExp.y} r="5" fill="#10b981" />
                        <circle cx={pPsy.x} cy={pPsy.y} r="5" fill="#6366f1" />
                    </svg>

                    {/* Labels */}
                    <div className="absolute top-[-25px] left-1/2 translate-x-[-50%] text-[9px] font-black text-blue-600 uppercase tracking-widest">Operational</div>
                    <div className="absolute top-1/2 right-[-35px] translate-y-[-50%] text-[9px] font-black text-orange-600 uppercase tracking-widest">Risk</div>
                    <div className="absolute bottom-[-25px] left-1/2 translate-x-[-50%] text-[9px] font-black text-green-600 uppercase tracking-widest">Explainability</div>
                    <div className="absolute top-1/2 left-[-35px] translate-y-[-50%] text-[9px] font-black text-indigo-600 uppercase tracking-widest">Psychological</div>
                </div>

                {/* Score Breakdown */}
                <div className="space-y-6">
                    <div className="text-center lg:text-left">
                        <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] block mb-2">Aggregated Score</span>
                        <div className="text-6xl font-black text-gray-800 tracking-tighter">
                            {score}<span className="text-2xl text-gray-300">/100</span>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
                            <span className="text-[9px] font-black text-blue-600 uppercase block mb-1">Operational</span>
                            <div className="text-lg font-black text-gray-700">{dimensions.operational}%</div>
                        </div>
                        <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
                            <span className="text-[9px] font-black text-orange-600 uppercase block mb-1">Risk Buffer</span>
                            <div className="text-lg font-black text-gray-700">{dimensions.risk}%</div>
                        </div>
                        <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
                            <span className="text-[9px] font-black text-green-600 uppercase block mb-1">Explainability</span>
                            <div className="text-lg font-black text-gray-700">{dimensions.explainability}%</div>
                        </div>
                        <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
                            <span className="text-[9px] font-black text-indigo-600 uppercase block mb-1">Psych Safety</span>
                            <div className="text-lg font-black text-gray-700">{dimensions.psychological}%</div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Governance Legend */}
            <div className="mt-12 pt-8 border-t border-gray-100">
                <div className="flex flex-wrap justify-between gap-6">
                    <div className="flex items-center gap-3">
                        <div className="h-3 w-3 rounded-full bg-blue-600"></div>
                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">Board Significance</span>
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="h-3 w-3 rounded-full bg-orange-500"></div>
                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">CFO Sensitivity</span>
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="h-3 w-3 rounded-full bg-green-500"></div>
                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">System Clarity</span>
                    </div>
                </div>
            </div>
        </div>
    );
}

import React, { useState } from 'react';

interface GovernanceSignOffPanelProps {
    brandId: string;
    onSignOff: () => void;
}

export function GovernanceSignOffPanel({ brandId, onSignOff }: GovernanceSignOffPanelProps) {
    const [role, setRole] = useState<'CFO' | 'BOARD' | 'OPERATOR'>('CFO');
    const [dimensions, setDimensions] = useState({
        operational: 80,
        risk: 80,
        explainability: 80,
        psychological: 80
    });
    const [comments, setComments] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    const handleSliderChange = (dim: keyof typeof dimensions, val: string) => {
        setDimensions(prev => ({ ...prev, [dim]: parseInt(val) }));
    };

    const handleSubmit = async () => {
        setIsSubmitting(true);
        try {
            const response = await fetch('/api/autonomous-analytics/trust/confidence/sign-off', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    brandId,
                    reviewerRole: role,
                    dimensions,
                    comments
                })
            });

            if (response.ok) {
                onSignOff();
                setComments('');
            }
        } catch (error) {
            console.error('Sign-off error:', error);
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="bg-gray-900 rounded-3xl p-8 text-white shadow-2xl">
            <div className="flex justify-between items-center mb-10">
                <div>
                    <h3 className="text-xl font-black tracking-tight mb-1">Governance Sign-off</h3>
                    <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">Formal Executive Confidence Review</p>
                </div>
                <div className="flex bg-white/5 p-1 rounded-xl border border-white/10">
                    {(['CFO', 'BOARD', 'OPERATOR'] as const).map(r => (
                        <button
                            key={r}
                            onClick={() => setRole(r)}
                            className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${role === r ? 'bg-blue-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'
                                }`}
                        >
                            {r}
                        </button>
                    ))}
                </div>
            </div>

            <div className="space-y-8 mb-10">
                {Object.entries(dimensions).map(([dim, val]) => (
                    <div key={dim}>
                        <div className="flex justify-between items-center mb-4">
                            <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">{dim}</span>
                            <span className="text-sm font-black text-blue-400">{val}%</span>
                        </div>
                        <input
                            type="range"
                            min="0"
                            max="100"
                            value={val}
                            onChange={(e) => handleSliderChange(dim as any, e.target.value)}
                            className="w-full h-1.5 bg-white/10 rounded-full appearance-none cursor-pointer accent-blue-500 hover:accent-blue-400 transition-all"
                        />
                    </div>
                ))}
            </div>

            <div className="mb-8">
                <span className="text-[10px] font-black uppercase tracking-widest text-gray-400 block mb-4">Qualitative Assessment</span>
                <textarea
                    value={comments}
                    onChange={(e) => setComments(e.target.value)}
                    placeholder="Provide reasoning for your confidence scores..."
                    className="w-full h-32 bg-white/5 border border-white/10 rounded-2xl p-4 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white/10 transition-all"
                ></textarea>
            </div>

            <button
                onClick={handleSubmit}
                disabled={isSubmitting}
                className="w-full py-5 bg-blue-600 hover:bg-blue-700 text-white rounded-2xl font-black uppercase tracking-[0.2em] text-xs shadow-lg shadow-blue-900/40 transition-all disabled:opacity-50"
            >
                {isSubmitting ? 'Recording Protocol...' : 'Submit Confidence Sign-off'}
            </button>

            <div className="mt-8 pt-8 border-t border-white/5">
                <p className="text-[10px] text-gray-500 font-bold uppercase tracking-tight text-center leading-relaxed">
                    "Executive confidence does not equal system permission."<br />
                    This signature is purely diagnostic and does not enable autonomous execution.
                </p>
            </div>
        </div>
    );
}

import React from 'react';

interface TrendMetric {
    label: string;
    key: string;
    description: string;
}

interface TrustTrendGridProps {
    data7d: any;
    data14d: any;
    data30d: any;
    loading?: boolean;
}

const METRICS: TrendMetric[] = [
    { label: 'Rule Acceptance', key: 'rule_acceptance', description: 'Human approval rate of AI decisions.' },
    { label: 'AI Agreement', key: 'ai_agreement', description: 'Internal deterministic vs AI model alignment.' },
    { label: 'Rollback Freq', key: 'rollback_rate', description: 'Percentage of actions reversed.' },
    { label: 'Avg Confidence', key: 'avg_confidence', description: 'Mean uncertainty score of evaluations.' },
    { label: 'Gate Failures', key: 'safety_gate_failures', description: 'Internal safety violation rate.' }
];

export function TrustTrendGrid({ data7d, data14d, data30d, loading }: TrustTrendGridProps) {
    if (loading) {
        return (
            <div className="bg-white rounded-xl shadow p-6 animate-pulse border border-gray-100">
                <div className="h-4 bg-gray-200 rounded w-1/4 mb-6"></div>
                <div className="space-y-4">
                    {[1, 2, 3, 4, 5].map(i => <div key={i} className="h-10 bg-gray-100 rounded"></div>)}
                </div>
            </div>
        );
    }

    const formatValue = (val: number, key: string) => {
        if (key === 'avg_confidence') return val.toFixed(2);
        return `${(val * 100).toFixed(1)}%`;
    };

    return (
        <div className="bg-white rounded-xl shadow-lg border border-gray-100 overflow-hidden">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center">
                <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest">Temporal Trust Trends</h3>
                <span className="text-[10px] text-blue-600 bg-blue-50 px-2 py-0.5 rounded font-black uppercase">Audited Dataset</span>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead>
                        <tr className="bg-gray-50 border-b border-gray-100">
                            <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest">System Metric</th>
                            <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">7 Day</th>
                            <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">14 Day</th>
                            <th className="px-6 py-4 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">30 Day</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {METRICS.map((metric) => (
                            <tr key={metric.key} className="hover:bg-gray-50 transition-colors group">
                                <td className="px-6 py-4">
                                    <div className="flex flex-col">
                                        <span className="text-xs font-bold text-gray-700">{metric.label}</span>
                                        <span className="text-[9px] text-gray-400 uppercase tracking-tighter">{metric.description}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <span className="text-xs font-mono font-black text-gray-600">
                                        {data7d ? formatValue(data7d[metric.key], metric.key) : '—'}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <span className="text-xs font-mono font-black text-gray-600">
                                        {data14d ? formatValue(data14d[metric.key], metric.key) : '—'}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <span className={`text-xs font-mono font-black px-2 py-1 rounded ${metric.key === 'rollback_rate' && data30d?.[metric.key] > 0.02 ? 'bg-red-50 text-red-600' : 'text-gray-900'}`}>
                                        {data30d ? formatValue(data30d[metric.key], metric.key) : '—'}
                                    </span>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="p-4 bg-gray-50 border-t border-gray-100">
                <div className="flex items-start gap-2">
                    <span className="text-blue-500 font-bold text-xs mt-0.5">ℹ</span>
                    <p className="text-[9px] text-gray-500 leading-normal font-medium">
                        All trends are computed daily at 00:00 UTC. Previous period variances exceeding 5% are flagged for manual review by the Risk Committee.
                    </p>
                </div>
            </div>
        </div>
    );
}

import React from 'react';
import { AutonomyVerdict } from '@/lib/autonomous-analytics/trust/verdict';

interface TrustVerdictPanelProps {
    verdict?: AutonomyVerdict;
    loading?: boolean;
}

export function TrustVerdictPanel({ verdict, loading }: TrustVerdictPanelProps) {
    if (loading) {
        return (
            <div className="bg-white border-2 border-dashed border-gray-200 rounded-2xl p-8 flex flex-col items-center justify-center animate-pulse">
                <div className="h-8 w-48 bg-gray-100 rounded-lg mb-4"></div>
                <div className="h-4 w-32 bg-gray-50 rounded"></div>
            </div>
        );
    }

    if (!verdict) return null;

    const isReady = verdict.verdict === 'CONDITIONALLY_READY';
    const hasRedFlags = verdict.blocking_factors.length > 0;

    return (
        <div className={`relative overflow-hidden rounded-2xl border-2 transition-all duration-500 ${isReady ? 'border-green-500 bg-green-50/30' : 'border-orange-200 bg-orange-50/30'}`}>
            {/* Background Watermark */}
            <div className="absolute top-0 right-0 p-8 rotate-12 opacity-5 pointer-events-none select-none">
                <span className={`text-6xl font-black uppercase tracking-tighter ${isReady ? 'text-green-600' : 'text-orange-600'}`}>
                    Governance Gate
                </span>
            </div>

            <div className="p-8 relative z-10">
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8">
                    <div>
                        <div className="flex items-center gap-3 mb-2">
                            <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Autonomy Eligibility Verdict</span>
                            <span className="h-1 w-1 rounded-full bg-gray-300"></span>
                            <span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Phase 2.9 Final Gate</span>
                        </div>
                        <h2 className={`text-4xl font-black tracking-tight ${isReady ? 'text-green-800' : 'text-orange-800'}`}>
                            {verdict.verdict === 'CONDITIONALLY_READY' ? 'ELIGIBILITY GRANTED' : 'ELIGIBILITY WITHHELD'}
                        </h2>
                        <p className="text-gray-500 mt-1 max-w-xl">
                            Deterministic analysis of sub-system stability, AI reliability, and human trust alignment.
                        </p>
                    </div>

                    <div className={`px-8 py-4 rounded-xl shadow-sm border-2 flex flex-col items-center ${isReady ? 'bg-green-600 border-green-700' : 'bg-orange-500 border-orange-600'}`}>
                        <span className="text-[10px] font-black text-white/70 uppercase tracking-widest mb-1">Status</span>
                        <span className="text-xl font-black text-white uppercase tracking-wider">{verdict.verdict.replace('_', ' ')}</span>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
                    <VerdictMetric label="Observation Days" value={`${verdict.observation_days}d`} sub="Min: 7d" status={verdict.observation_days >= 7 ? 'good' : 'warning'} />
                    <VerdictMetric label="System Stability" value={verdict.system_stability} sub="Success Rate" status={verdict.system_stability === 'STABLE' ? 'good' : 'danger'} />
                    <VerdictMetric label="AI Reliability" value={verdict.ai_reliability} sub="Drift Check" status={verdict.ai_reliability === 'CONSISTENT' ? 'good' : 'warning'} />
                    <VerdictMetric label="Human Alignment" value={verdict.human_alignment} sub="Subjective Delta" status={verdict.human_alignment === 'HIGH' ? 'good' : verdict.human_alignment === 'MEDIUM' ? 'warning' : 'danger'} />
                </div>

                {hasRedFlags && (
                    <div className="bg-white/80 border border-orange-200 rounded-xl p-6 mb-8 animate-in fade-in slide-in-from-bottom-2">
                        <div className="flex items-center gap-2 mb-4">
                            <span className="p-1.5 bg-orange-100 text-orange-600 rounded-full">
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                                </svg>
                            </span>
                            <h3 className="text-sm font-black text-orange-800 uppercase tracking-widest">Blocking Factors Detected</h3>
                        </div>
                        <ul className="space-y-3">
                            {verdict.blocking_factors.map((factor, idx) => (
                                <li key={idx} className="flex items-start gap-3">
                                    <span className="h-2 w-2 rounded-full bg-orange-400 mt-1.5 shrink-0"></span>
                                    <span className="text-sm text-gray-700 italic">{factor}</span>
                                </li>
                            ))}
                        </ul>
                    </div>
                )}

                <div className="flex flex-col md:flex-row justify-between items-end gap-6 pt-6 border-t border-gray-100/50">
                    <div className="flex-grow">
                        <div className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Board Recommendation</div>
                        <div className={`text-lg font-black uppercase tracking-widest ${isReady ? 'text-green-700' : 'text-blue-600'}`}>
                            {verdict.recommendation.replace('_', ' ')}
                        </div>
                    </div>

                    <div className="text-right">
                        <div className="text-[9px] text-gray-400 uppercase tracking-widest mb-1 italic">Issued By Governance Controller</div>
                        <div className="text-xs font-mono text-gray-500">{new Date(verdict.issued_at).toLocaleString()}</div>
                    </div>
                </div>
            </div>

            {/* Read-Only Interlock Footer */}
            <div className={`px-8 py-3 flex justify-between items-center text-[10px] font-black uppercase tracking-widest ${isReady ? 'bg-green-600 text-white' : 'bg-orange-600 text-white'}`}>
                <span>Governance Lock: Read-Only Protocol Active</span>
                <span>Interlock State: Deterministic Evaluation Only</span>
            </div>
        </div>
    );
}

function VerdictMetric({ label, value, sub, status }: { label: string, value: string, sub: string, status: 'good' | 'warning' | 'danger' }) {
    const colorClass = status === 'good' ? 'text-green-600' : status === 'warning' ? 'text-orange-500' : 'text-red-500';
    const bgClass = status === 'good' ? 'bg-green-50' : status === 'warning' ? 'bg-orange-50' : 'bg-red-50';

    return (
        <div className="bg-white/60 p-4 rounded-xl border border-gray-100/50 transition-all hover:shadow-md">
            <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-1">{label}</span>
            <div className={`text-lg font-black tracking-tight ${colorClass}`}>{value}</div>
            <div className="flex items-center gap-1.5 mt-1">
                <span className={`h-1 w-1 rounded-full ${colorClass.replace('text', 'bg')}`}></span>
                <span className="text-[9px] text-gray-400 font-bold uppercase">{sub}</span>
            </div>
        </div>
    );
}

// Pending Approvals Widget - Quick view of pending approval requests
// Shows count and list of pending items

'use client';

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { RiskBadge, LoadingSpinner, EmptyState } from '@/components/autonomous/ui/CoreComponents';
import Link from 'next/link';

interface PendingApprovalsWidgetProps {
    brandId: string;
}

export function PendingApprovalsWidget({ brandId }: PendingApprovalsWidgetProps) {
    const { data, isLoading } = useQuery({
