    className?: string;
}

const PromoBadge: React.FC<PromoBadgeProps> = ({ type, text, className = '' }) => {
    let bgColor = 'bg-amber-500';
    let textColor = 'text-white';
    let defaultText = '';

    switch (type) {
        case 'FLASH_SALE':
