            break;
        case 'PROMO':
            bgColor = 'bg-amber-500';
            defaultText = 'SAYANG IBU';
            break;
        case 'NEW':
            bgColor = 'bg-emerald-600';
            defaultText = 'TERBARU';
            break;
        case 'BEST_SELLER':
            bgColor = 'bg-[#8B7E66]';
            defaultText = 'FAVORIT';
            break;
    }

    return (
        <div className={`
