                        >
                            {isOpen ? <X className="w-6 h-6 animate-in spin-in-90 duration-300" /> : <Menu className="w-6 h-6 animate-in zoom-in duration-300" />}
                        </button>
                    </div>
                </div>
            </nav>

            {/* Mobile Menu Overlay - Move outside nav to avoid sticky/transparency issues */}
            <div
