'use client';

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { getVarianceAnalysisAction, getAIForecastAction } from '@/lib/actions/budget';
import { TrendingUp, TrendingDown, AlertTriangle, CheckCircle2, DollarSign, BrainCircuit } from 'lucide-react';

interface BudgetTrackerProps {
    brandId: string;
    fiscalYear?: number;
}

export function BudgetTracker({ brandId, fiscalYear = new Date().getFullYear() }: BudgetTrackerProps) {
    const { data: varianceData, isLoading: loadingVariance } = useQuery({
        queryKey: ['budget-variance', brandId, fiscalYear],
        queryFn: () => getVarianceAnalysisAction(brandId, fiscalYear)
    });

    const { data: forecastData, isLoading: loadingForecast } = useQuery({
        queryKey: ['budget-forecast', brandId, fiscalYear],
        queryFn: () => getAIForecastAction(brandId, fiscalYear)
    });

    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    if (loadingVariance || loadingForecast) {
        return (
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6 animate-pulse">
                <div className="h-4 bg-slate-200 rounded w-1/4 mb-4"></div>
                <div className="h-20 bg-slate-100 rounded mb-4"></div>
                <div className="h-10 bg-slate-100 rounded"></div>
            </div>
        );
    }

    const variance = (varianceData as any)?.data;
    const forecast = (forecastData as any)?.data;

    if (!variance) {
        return (
            <div className="bg-white rounded-xl border border-dashed border-slate-300 p-8 text-center">
                <p className="text-slate-400 font-medium">No Active Budget for {fiscalYear}</p>
                <p className="text-xs text-slate-400 mt-1">Contact Owner to set annual targets.</p>
            </div>
        );
    }

    const getStatusColor = (status: string) => {
        switch (status) {
            case 'good': return 'text-emerald-600 bg-emerald-50 border-emerald-200';
            case 'warning': return 'text-amber-600 bg-amber-50 border-amber-200';
            case 'bad': return 'text-rose-600 bg-rose-50 border-rose-200';
            default: return 'text-slate-600 bg-slate-50 border-slate-200';
        }
    };

    return (
        <div className="space-y-6">
            {/* Variance Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Revenue */}
                <div className={`p-4 rounded-xl border ${getStatusColor(variance.revenue.status)}`}>
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-xs font-bold uppercase tracking-wider">Revenue Target</span>
                        <TrendingUp className="w-4 h-4" />
                    </div>
                    <div className="text-2xl font-black mb-1">{currency.format(variance.revenue.actual)}</div>
                    <div className="flex justify-between items-end">
                        <span className="text-xs opacity-70">Target: {currency.format(variance.revenue.budget)}</span>
                        <span className="text-xs font-bold">{variance.revenue.variancePercent > 0 ? '+' : ''}{variance.revenue.variancePercent.toFixed(1)}%</span>
                    </div>
                </div>

                {/* Expense */}
                <div className={`p-4 rounded-xl border ${getStatusColor(variance.expense.status)}`}>
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-xs font-bold uppercase tracking-wider">Expense Limit</span>
                        <DollarSign className="w-4 h-4" />
                    </div>
                    <div className="text-2xl font-black mb-1">{currency.format(variance.expense.actual)}</div>
                    <div className="flex justify-between items-end">
                        <span className="text-xs opacity-70">Limit: {currency.format(variance.expense.budget)}</span>
                        <span className="text-xs font-bold">{variance.expense.variancePercent > 0 ? '+' : ''}{variance.expense.variancePercent.toFixed(1)}%</span>
                    </div>
                </div>

                {/* AI Forecast Insight */}
                <div className="p-4 rounded-xl border border-indigo-200 bg-indigo-50 text-indigo-900">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-xs font-bold uppercase tracking-wider flex items-center gap-1">
                            <BrainCircuit className="w-3 h-3" /> AI Forecast
                        </span>
                    </div>
                    {forecast?.recommendation?.shouldAdjust ? (
                        <div>
                            <div className="flex items-center gap-2 mb-2 font-bold text-sm">
                                <AlertTriangle className="w-4 h-4 text-amber-600" />
                                Adjustment Recommended
                            </div>
                            <p className="text-xs leading-relaxed opacity-90 line-clamp-2">
                                {forecast.recommendation.reason}
                            </p>
                        </div>
                    ) : (
                        <div>
                            <div className="flex items-center gap-2 mb-2 font-bold text-sm">
                                <CheckCircle2 className="w-4 h-4 text-emerald-600" />
                                On Track
                            </div>
                            <p className="text-xs leading-relaxed opacity-90">
                                Performance aligns with annual targets. No aggressive changes needed.
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { getICTransactionHistoryAction } from '@/lib/actions/interCompany';
import { ArrowRight, TrendingUp, TrendingDown } from 'lucide-react';

interface ICTrackerProps {
    brandId: string;
    brandName: string;
}

export function ICTracker({ brandId, brandName }: ICTrackerProps) {
    const { data: historyData, isLoading } = useQuery({
        queryKey: ['ic-history', brandId],
        queryFn: () => getICTransactionHistoryAction(brandId)
    });

    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    const transactions = (historyData as any)?.data || [];

    // Calculate net position
    let totalReceivable = 0;
    let totalPayable = 0;

    transactions.forEach((tx: any) => {
        if (tx.status === 'APPROVED') {
            if (tx.fromBrandId === brandId) {
                totalReceivable += Number(tx.amount);
            } else if (tx.toBrandId === brandId) {
                totalPayable += Number(tx.amount);
            }
        }
    });

    const netPosition = totalReceivable - totalPayable;

    if (isLoading) {
        return (
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                <div className="text-center text-slate-400">Loading IC data...</div>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-gradient-to-r from-purple-50 to-indigo-50">
                <h3 className="font-black text-lg text-purple-900">Inter-Company Position</h3>
                <p className="text-sm text-purple-700 mt-1">Transactions with other brands</p>
            </div>

            <div className="p-6">
                {/* Net Position Summary */}
                <div className="grid grid-cols-3 gap-4 mb-6">
                    <div className="text-center p-4 bg-green-50 rounded-xl border border-green-200">
                        <div className="text-xs font-bold text-green-700 uppercase tracking-wider mb-1">Receivable</div>
                        <div className="text-xl font-black text-green-900">{currency.format(totalReceivable)}</div>
                    </div>
                    <div className="text-center p-4 bg-red-50 rounded-xl border border-red-200">
                        <div className="text-xs font-bold text-red-700 uppercase tracking-wider mb-1">Payable</div>
                        <div className="text-xl font-black text-red-900">{currency.format(totalPayable)}</div>
                    </div>
                    <div className={`text-center p-4 rounded-xl border-2 ${netPosition >= 0 ? 'bg-emerald-50 border-emerald-300' : 'bg-orange-50 border-orange-300'}`}>
                        <div className={`text-xs font-bold uppercase tracking-wider mb-1 ${netPosition >= 0 ? 'text-emerald-700' : 'text-orange-700'}`}>
                            Net Position
                        </div>
                        <div className={`text-xl font-black flex items-center justify-center gap-1 ${netPosition >= 0 ? 'text-emerald-900' : 'text-orange-900'}`}>
                            {netPosition >= 0 ? <TrendingUp size={20} /> : <TrendingDown size={20} />}
                            {currency.format(Math.abs(netPosition))}
                        </div>
                    </div>
                </div>

                {/* Recent Transactions */}
                <div>
                    <h4 className="font-bold text-sm text-slate-700 mb-3 uppercase tracking-wider">Recent Transactions</h4>
                    {transactions.length === 0 ? (
                        <div className="text-center py-8 text-slate-400">No IC transactions yet</div>
                    ) : (
                        <div className="space-y-2">
                            {transactions.slice(0, 5).map((tx: any) => {
                                const isReceivable = tx.fromBrandId === brandId;
                                const counterparty = isReceivable ? tx.toBrand.name : tx.fromBrand.name;

                                return (
                                    <div key={tx.id} className="flex justify-between items-center p-3 bg-slate-50 rounded-lg hover:bg-slate-100 transition-colors">
                                        <div className="flex-1">
                                            <div className="flex items-center gap-2 mb-1">
                                                {isReceivable ? (
                                                    <>
                                                        <span className="font-medium text-slate-900">{brandName}</span>
                                                        <ArrowRight size={14} className="text-slate-400" />
                                                        <span className="text-slate-600">{counterparty}</span>
                                                    </>
                                                ) : (
                                                    <>
                                                        <span className="text-slate-600">{counterparty}</span>
                                                        <ArrowRight size={14} className="text-slate-400" />
                                                        <span className="font-medium text-slate-900">{brandName}</span>
                                                    </>
                                                )}
                                            </div>
                                            <div className="text-xs text-slate-500">{tx.type.replace('_', ' ')} • {new Date(tx.createdAt).toLocaleDateString()}</div>
                                        </div>
                                        <div className="text-right">
                                            <div className={`font-bold ${isReceivable ? 'text-green-600' : 'text-red-600'}`}>
                                                {isReceivable ? '+' : '-'}{currency.format(Number(tx.amount))}
                                            </div>
                                            <div className={`text-[10px] font-medium ${tx.status === 'APPROVED' ? 'text-green-600' :
                                                    tx.status === 'PENDING' ? 'text-amber-600' :
                                                        'text-red-600'
                                                }`}>
                                                {tx.status}
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
