                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import {
    BrainCircuit,
    TrendingUp,
    Users,
    Zap,
    TrendingDown,
    AlertCircle,
    ShoppingCart,
    ArrowUpRight,
    PieChart as PieChartIcon,
    LineChart as LineChartIcon,
    Package
} from 'lucide-react';
import { getHoldingIntelligenceAction } from '@/lib/actions/intelligence';

export default function HoldingIntelligenceHub() {
    const [data, setData] = React.useState<any>(null);
    const [isLoading, setIsLoading] = React.useState(true);

    React.useEffect(() => {
        const loadIntelligence = async () => {
            setIsLoading(true);
            const res = await getHoldingIntelligenceAction();
            if (res.success) {
                setData(res);
            }
            setIsLoading(false);
        };
        loadIntelligence();
    }, []);

    if (isLoading) {
        return (
            <div className="flex flex-col items-center justify-center p-20 space-y-4">
                <BrainCircuit className="w-12 h-12 text-indigo-500 animate-pulse" />
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Generating AI Insights...</p>
            </div>
        );
    }

    const segments = data?.rfm || [];
    const forecast = data?.forecast || [];
    const restock = data?.smartRestock || [];

    const segmentStats = segments.reduce((acc: any, curr: any) => {
        acc[curr.segment] = (acc[curr.segment] || 0) + 1;
        return acc;
    }, {});

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-5 duration-700">
            {/* AI Insight Header */}
            <div className="flex items-center justify-between bg-gradient-to-r from-indigo-600 to-purple-700 p-8 rounded-[2.5rem] text-white shadow-xl shadow-indigo-900/20">
                <div className="space-y-2">
                    <h2 className="text-3xl font-black tracking-tight flex items-center gap-3">
                        <BrainCircuit className="w-8 h-8" />
                        Intelligence Hub
                    </h2>
                    <p className="text-indigo-100 text-sm font-medium max-w-md">
                        Heuristic AI models are analyzing your ecosystem data to predict trends, classify customers, and optimize inventory.
                    </p>
                </div>
                <div className="hidden lg:flex gap-4">
                    <div className="bg-white/10 backdrop-blur-md p-4 rounded-2xl border border-white/10">
                        <p className="text-[9px] font-black uppercase tracking-widest text-indigo-200">Total Analyzed</p>
                        <p className="text-xl font-black">{segments.length} Customers</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Sales Forecasting */}
                <div className="lg:col-span-2 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
                    <div className="flex items-center justify-between">
                        <h3 className="text-lg font-black text-slate-900 flex items-center gap-2 uppercase tracking-tight">
                            <LineChartIcon className="w-5 h-5 text-indigo-600" />
                            Revenue Forecast (Next 7 Days)
                        </h3>
                        <span className="text-[10px] font-black text-emerald-600 bg-emerald-50 px-2 py-1 rounded-lg uppercase">Linear Trend</span>
                    </div>

                    <div className="h-64 flex items-end gap-2 px-2">
                        {forecast.map((f: any, i: number) => {
                            const isFuture = i >= 7;
                            const maxVal = Math.max(...forecast.map((x: any) => x.actual || x.forecast));
                            const height = ((f.actual || f.forecast) / maxVal) * 100;

                            return (
                                <div key={f.date} className="flex-1 flex flex-col items-center group relative">
                                    <div
                                        style={{ height: `${height}%` }}
                                        className={`w-full rounded-t-lg transition-all ${isFuture ? 'bg-indigo-200 opacity-50 group-hover:opacity-100' : 'bg-indigo-600'}`}
                                    />
                                    <div className="absolute -top-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[9px] font-bold px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity z-10 whitespace-nowrap">
                                        Rp {(f.actual || f.forecast).toLocaleString()}
                                    </div>
                                    <p className="text-[8px] font-bold text-slate-400 mt-2 rotate-45 lg:rotate-0">
                                        {f.date.split('-').slice(1).join('/')}
                                    </p>
                                </div>
                            );
                        })}
                    </div>
                    <p className="text-[10px] text-slate-400 italic text-center">** Dark bars represent actuals, light bars represent AI predictions based on 30-day velocity.</p>
                </div>

                {/* Customer Segmentation */}
                <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
                    <h3 className="text-lg font-black text-slate-900 flex items-center gap-2 uppercase tracking-tight">
                        <PieChartIcon className="w-5 h-5 text-purple-600" />
                        RFM Segments
                    </h3>

                    <div className="space-y-4">
                        {Object.entries(segmentStats).map(([segment, count]: any) => {
                            const colors: any = {
                                CHAMPION: 'bg-emerald-500',
                                LOYAL: 'bg-blue-500',
                                AT_RISK: 'bg-rose-500',
                                NEW: 'bg-amber-500'
                            };
                            return (
                                <div key={segment} className="flex items-center justify-between group">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-3 h-3 rounded-full ${colors[segment] || 'bg-slate-300'}`} />
                                        <span className="text-[10px] font-black text-slate-600 uppercase tracking-widest">{segment}</span>
                                    </div>
                                    <span className="text-xs font-black text-slate-900">{count}</span>
                                </div>
                            );
                        })}
                    </div>

                    <div className="pt-6 border-t border-slate-100">
                        <div className="p-4 bg-slate-50 rounded-2xl space-y-2">
                            <div className="flex items-center gap-2 text-[10px] font-black text-slate-900 uppercase">
                                <Zap className="w-3 h-3 text-amber-500" />
                                Growth Insight
                            </div>
                            <p className="text-[10px] text-slate-500 leading-relaxed font-medium">
                                Your **Champions** contribute to {((segmentStats['CHAMPION'] || 0) / segments.length * 100).toFixed(1)}% of the total customer base. Target them for exclusivity.
                            </p>
                        </div>
                    </div>
                </div>

                {/* Smart Restock System */}
                <div className="lg:col-span-3 bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
                    <div className="flex items-center justify-between">
                        <h3 className="text-lg font-black text-slate-900 flex items-center gap-2 uppercase tracking-tight">
                            <Package className="w-5 h-5 text-amber-600" />
                            Smart Procurement Recommendations
                        </h3>
                        <div className="flex items-center gap-2">
                            <span className="w-2 h-2 bg-rose-500 rounded-full animate-ping" />
                            <span className="text-[10px] font-black text-rose-600 uppercase">Action Required</span>
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead>
                                <tr className="border-b border-slate-50">
                                    <th className="py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Item / Variant</th>
                                    <th className="py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Velocity</th>
                                    <th className="py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-center">Stock Remaining</th>
                                    <th className="py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Pred. Depletion</th>
                                    <th className="py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Rec. Buy</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50">
                                {restock.map((item: any) => (
                                    <tr key={item.variantId} className="group hover:bg-slate-50/50 transition-colors">
                                        <td className="py-4">
                                            <p className="text-xs font-black text-slate-900">{item.name}</p>
                                            <p className="text-[9px] text-slate-400 font-medium">{item.sku}</p>
                                        </td>
                                        <td className="py-4">
                                            <div className="flex items-center gap-1.5">
                                                <TrendingUp className="w-3 h-3 text-emerald-500" />
                                                <span className="text-xs font-bold text-slate-600">{item.velocity} <span className="text-[8px] uppercase">units/day</span></span>
                                            </div>
                                        </td>
                                        <td className="py-4 text-center">
                                            <span className={`px-3 py-1 rounded-full text-[10px] font-black ${item.stock < 20 ? 'bg-rose-50 text-rose-600' : 'bg-slate-50 text-slate-600'}`}>
                                                {item.stock} Units
                                            </span>
                                        </td>
                                        <td className="py-4 text-right">
                                            <p className={`text-xs font-black ${item.daysRemaining < 7 ? 'text-rose-600' : 'text-amber-600'}`}>
                                                {item.daysRemaining <= 0 ? 'Out of Stock' : `${item.daysRemaining} Days`}
                                            </p>
                                        </td>
                                        <td className="py-4 text-right">
                                            <button className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition-all">
                                                Order {item.recommendation}
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                                {restock.length === 0 && (
                                    <tr>
                                        <td colSpan={5} className="py-12 text-center text-slate-400 text-xs font-bold">No critical stock depletion predicted based on current velocity.</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import {
    X,
    ArrowRight,
    DollarSign,
    Package,
    ShieldCheck,
    Loader2,
    RefreshCw,
    AlertCircle
} from 'lucide-react';
import { createInterBrandTransferAction } from '@/lib/actions/holding';

interface ResourceTransferModalProps {
    brands: Array<{ name: string; slug: string; id?: string }>;
    onClose: () => void;
    onSuccess: () => void;
}

export default function ResourceTransferModal({ brands, onClose, onSuccess }: ResourceTransferModalProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [formData, setFormData] = useState({
        sendingBrandId: '',
        receivingBrandId: '',
        type: 'CASH' as 'CASH' | 'STOCK' | 'SERVICE',
        value: '',
        description: ''
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!formData.sendingBrandId || !formData.receivingBrandId || !formData.value) {
            setError('Semua field wajib diisi');
            return;
        }

        if (formData.sendingBrandId === formData.receivingBrandId) {
            setError('Brand pengirim dan penerima tidak boleh sama');
            return;
        }

        setIsLoading(true);
        setError(null);

        try {
            const res = await createInterBrandTransferAction({
                ...formData,
                value: parseFloat(formData.value)
            });

            if (res.success) {
                onSuccess();
                onClose();
            } else {
                setError(res.error || 'Gagal mencatat transfer');
            }
        } catch (err: any) {
            setError(err.message);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-[#1A241A]/60 backdrop-blur-md" onClick={onClose}></div>

            <div className="relative w-full max-w-xl bg-white rounded-[2.5rem] shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-300">
                {/* Header */}
                <div className="p-8 border-b border-[#F9F7F2] flex justify-between items-center">
                    <div>
                        <h3 className="text-2xl font-black text-[#1A241A] tracking-tighter">
                            Record <span className="text-amber-600">Resource Transfer</span>
                        </h3>
                        <p className="text-[10px] font-bold text-[#8B7E66] uppercase tracking-widest mt-1">Inter-Brand Asset Movement</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-[#F9F7F2] rounded-xl transition-all">
                        <X className="w-6 h-6 text-[#8B7E66]" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-8 space-y-6">
                    {error && (
                        <div className="p-4 bg-rose-50 border border-rose-100 rounded-2xl flex items-center gap-3 text-rose-600 text-xs font-bold animate-in slide-in-from-top-2">
                            <AlertCircle className="w-4 h-4" />
                            {error}
                        </div>
                    )}

                    <div className="grid grid-cols-2 gap-4">
                        {/* Sending Brand */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase text-[#8B7E66] tracking-widest block ml-1">Dari Brand</label>
                            <select
                                value={formData.sendingBrandId}
                                onChange={(e) => setFormData({ ...formData, sendingBrandId: e.target.value })}
                                className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-2xl p-4 text-sm font-bold text-[#1A241A] focus:outline-none focus:ring-2 focus:ring-amber-500/20 transition-all appearance-none"
                            >
                                <option value="">Pilih Brand...</option>
                                {brands.map(b => (
                                    <option key={b.slug} value={b.slug}>{b.name}</option>
                                ))}
                            </select>
                        </div>

                        {/* Receiving Brand */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase text-[#8B7E66] tracking-widest block ml-1">Ke Brand</label>
                            <select
                                value={formData.receivingBrandId}
                                onChange={(e) => setFormData({ ...formData, receivingBrandId: e.target.value })}
                                className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-2xl p-4 text-sm font-bold text-[#1A241A] focus:outline-none focus:ring-2 focus:ring-amber-500/20 transition-all appearance-none"
                            >
                                <option value="">Pilih Brand...</option>
                                {brands.map(b => (
                                    <option key={b.slug} value={b.slug}>{b.name}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        {/* Type */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase text-[#8B7E66] tracking-widest block ml-1">Jenis Sumber Daya</label>
                            <div className="flex bg-[#FDFBF7] p-1 rounded-2xl border border-[#E5E1D8]">
                                {(['CASH', 'STOCK', 'SERVICE'] as const).map((t) => (
                                    <button
                                        key={t}
                                        type="button"
                                        onClick={() => setFormData({ ...formData, type: t })}
                                        className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${formData.type === t
                                                ? 'bg-[#2D3A2D] text-white shadow-lg'
                                                : 'text-[#8B7E66] hover:bg-white'
                                            }`}
                                    >
                                        {t === 'CASH' && <DollarSign className="w-3 h-3 mx-auto mb-1" />}
                                        {t === 'STOCK' && <Package className="w-3 h-3 mx-auto mb-1" />}
                                        {t === 'SERVICE' && <RefreshCw className="w-3 h-3 mx-auto mb-1" />}
                                        {t}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Value */}
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase text-[#8B7E66] tracking-widest block ml-1">Nilai (Rp)</label>
                            <input
                                type="number"
                                placeholder="0"
                                value={formData.value}
                                onChange={(e) => setFormData({ ...formData, value: e.target.value })}
                                className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-2xl p-4 text-sm font-bold text-[#1A241A] placeholder:text-[#E5E1D8] focus:outline-none focus:ring-2 focus:ring-amber-500/20 transition-all"
                            />
                        </div>
                    </div>

                    {/* Description */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-[#8B7E66] tracking-widest block ml-1">Keterangan / Alasan</label>
                        <textarea
                            rows={3}
                            placeholder="Misal: Suntikan modal awal, Pinjam stok 50pcs Rendang, Jasa IT..."
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                            className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-2xl p-4 text-sm font-bold text-[#1A241A] placeholder:text-[#E5E1D8] focus:outline-none focus:ring-2 focus:ring-amber-500/20 transition-all resize-none"
                        />
                    </div>

                    <button
                        type="submit"
                        disabled={isLoading}
                        className="w-full py-5 bg-[#2D3A2D] text-white rounded-2xl font-black uppercase tracking-[0.2em] text-xs shadow-xl shadow-green-900/10 hover:shadow-2xl hover:-translate-y-0.5 transition-all disabled:opacity-50 disabled:translate-y-0 flex items-center justify-center gap-3"
                    >
                        {isLoading ? (
                            <Loader2 className="w-5 h-5 animate-spin" />
                        ) : (
                            <>
                                <ShieldCheck className="w-5 h-5" />
                                Record Transfer
                            </>
                        )}
                    </button>
                </form>
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import {
    ShieldAlert,
    AlertTriangle,
    Info,
    CheckCircle2,
    XCircle,
    RefreshCw,
    ShieldCheck
} from 'lucide-react';
import { getAnomaliesAction, updateAnomalyStatusAction, triggerRiskScanAction } from '@/lib/actions/holding';

export default function RiskControlCenter() {
    const [anomalies, setAnomalies] = React.useState<any[]>([]);
    const [isLoading, setIsLoading] = React.useState(true);
    const [isScanning, setIsScanning] = React.useState(false);

    const loadAnomalies = React.useCallback(async () => {
        setIsLoading(true);
        const res = await getAnomaliesAction();
        if (res.success) {
            setAnomalies(res.anomalies);
        }
        setIsLoading(false);
    }, []);

    React.useEffect(() => {
        loadAnomalies();
    }, [loadAnomalies]);

    const handleRunScan = async () => {
        setIsScanning(true);
        const res = await triggerRiskScanAction();
        if (res.success) {
            await loadAnomalies();
        }
        setIsScanning(false);
    };

    const handleUpdateStatus = async (id: string, status: 'RESOLVED' | 'DISMISSED') => {
        const res = await updateAnomalyStatusAction(id, status);
        if (res.success) {
            setAnomalies(prev => prev.filter(a => a.id !== id));
        }
    };

    const getSeverityStyles = (severity: string) => {
        switch (severity) {
            case 'CRITICAL': return 'bg-rose-50 text-rose-700 border-rose-100';
            case 'WARNING': return 'bg-amber-50 text-amber-700 border-amber-100';
            default: return 'bg-blue-50 text-blue-700 border-blue-100';
        }
    };

    const getSeverityIcon = (severity: string) => {
        switch (severity) {
            case 'CRITICAL': return <ShieldAlert className="w-5 h-5 text-rose-600" />;
            case 'WARNING': return <AlertTriangle className="w-5 h-5 text-amber-600" />;
            default: return <Info className="w-5 h-5 text-blue-600" />;
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-black text-stone-900 tracking-tight flex items-center gap-2">
                        <ShieldCheck className="w-7 h-7 text-emerald-600" />
                        Risk Control Center
                    </h2>
                    <p className="text-stone-500 text-sm font-medium">Anomaly detection & operational integrity logs</p>
                </div>
                <button
                    onClick={handleRunScan}
                    disabled={isScanning}
                    className="flex items-center gap-2 px-6 py-3 bg-stone-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-stone-800 transition-all disabled:opacity-50 shadow-xl shadow-stone-900/10"
                >
                    <RefreshCw className={`w-4 h-4 ${isScanning ? 'animate-spin' : ''}`} />
                    {isScanning ? 'Scanning...' : 'Run Security Scan'}
                </button>
            </div>

            {isLoading ? (
                <div className="flex flex-col items-center justify-center p-20 bg-white rounded-[2.5rem] border border-stone-100 shadow-sm">
                    <RefreshCw className="w-10 h-10 text-stone-200 animate-spin" />
                    <p className="mt-4 text-stone-400 font-bold uppercase tracking-widest text-[10px]">Verifying ecosystem health...</p>
                </div>
            ) : anomalies.length === 0 ? (
                <div className="flex flex-col items-center justify-center p-20 bg-white rounded-[2.5rem] border border-emerald-100 shadow-sm shadow-emerald-900/5">
                    <div className="w-16 h-16 bg-emerald-50 rounded-full flex items-center justify-center mb-4">
                        <ShieldCheck className="w-8 h-8 text-emerald-600" />
                    </div>
                    <h3 className="text-xl font-black text-stone-900">Ecosystem Secured</h3>
                    <p className="text-stone-500 text-sm max-w-xs text-center mt-2">No operational anomalies or suspicious activities detected in the last 48 hours.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 gap-4">
                    {anomalies.map((anomaly) => (
                        <div
                            key={anomaly.id}
                            className={`p-6 bg-white rounded-[2rem] border border-stone-200 shadow-sm hover:shadow-md transition-all group overflow-hidden relative`}
                        >
                            <div className={`absolute top-0 right-0 p-4 opacity-[0.03] group-hover:scale-110 transition-transform`}>
                                <ShieldAlert className="w-24 h-24" />
                            </div>

                            <div className="flex flex-col md:flex-row md:items-start justify-between gap-6 relative z-10">
                                <div className="flex gap-4">
                                    <div className={`p-4 rounded-2xl ${getSeverityStyles(anomaly.severity)} border shrink-0 h-fit`}>
                                        {getSeverityIcon(anomaly.severity)}
                                    </div>
                                    <div className="space-y-1">
                                        <div className="flex items-center gap-2">
                                            <span className="text-[10px] font-black text-stone-400 uppercase tracking-widest">{anomaly.type.replace(/_/g, ' ')}</span>
                                            <span className="w-1 h-1 bg-stone-300 rounded-full" />
                                            <span className="text-[10px] font-bold text-stone-500">{new Date(anomaly.createdAt).toLocaleString()}</span>
                                        </div>
                                        <h4 className="text-lg font-black text-stone-900 leading-tight">{anomaly.description}</h4>
                                        <p className="text-stone-500 text-xs font-medium italic">Brand Source: {anomaly.brand?.name || 'Holding/Platform'}</p>

                                        {anomaly.metadata && (
                                            <div className="mt-4 p-4 bg-stone-50 rounded-2xl border border-stone-100">
                                                <p className="text-[9px] font-black text-stone-400 uppercase tracking-widest mb-2">Technical Metadata</p>
                                                <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                                                    {Object.entries(anomaly.metadata as any).map(([k, v]: [string, any]) => (
                                                        <div key={k}>
                                                            <p className="text-[8px] font-bold text-stone-400 uppercase">{k}</p>
                                                            <p className="text-[10px] font-black text-stone-700 truncate min-w-0" title={String(v)}>
                                                                {String(v)}
                                                            </p>
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </div>
                                <div className="flex items-center gap-2 self-end md:self-start">
                                    <button
                                        onClick={() => handleUpdateStatus(anomaly.id, 'RESOLVED')}
                                        className="p-3 text-emerald-600 hover:bg-emerald-50 rounded-xl transition-all"
                                        title="Resolve Anomaly"
                                    >
                                        <CheckCircle2 className="w-5 h-5" />
                                    </button>
                                    <button
                                        onClick={() => handleUpdateStatus(anomaly.id, 'DISMISSED')}
                                        className="p-3 text-stone-400 hover:bg-stone-100 rounded-xl transition-all"
                                        title="Dismiss Anomaly"
                                    >
                                        <XCircle className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import {
    Users,
    UserPlus,
    Shield,
    Building,
    Trash2,
    Mail,
    Key,
    ChevronRight,
    Search,
    UserCheck,
    Settings2,
    X,
    Plus,
    CheckCircle2,
    Lock
} from 'lucide-react';
import {
    createUserAction,
    deleteUserAction,
    updateUserAction,
    assignBrandRoleAction,
    removeBrandRoleAction,
    getUsersAction
} from '@/lib/actions/users';
import { GlobalRole, BrandRole } from '@prisma/client';

interface UserManagementProps {
    initialUsers: any[];
    availableBrands: any[];
}

export default function UserManagement({ initialUsers, availableBrands }: UserManagementProps) {
    const [users, setUsers] = useState(initialUsers);
    const [searchTerm, setSearchTerm] = useState('');
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [selectedUserId, setSelectedUserId] = useState<string | null>(null);
    const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    // Derive active user from master list
    const activeUser = users.find(u => u.id === selectedUserId);

    // Form States
    const [newUser, setNewUser] = useState({
        name: '',
        email: '',
        password: '',
        globalRole: 'USER' as GlobalRole
    });

    const refreshUsers = async () => {
        const res = await getUsersAction();
        if (res.success) setUsers(res.data);
    };

    const handleCreateUser = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        const res = await createUserAction(newUser);
        if (res.success) {
            setIsCreateModalOpen(false);
            setNewUser({ name: '', email: '', password: '', globalRole: 'USER' });
            await refreshUsers();
        } else {
            alert(res.error);
        }
        setIsLoading(false);
    };

    const handleDeleteUser = async (userId: string) => {
        if (!confirm('Are you sure you want to delete this user?')) return;
        setIsLoading(true);
        const res = await deleteUserAction(userId);
        if (res.success) await refreshUsers();
        else alert(res.error);
        setIsLoading(false);
    };

    const handleUpdateGlobalRole = async (userId: string, role: GlobalRole) => {
        setIsLoading(true);
        const res = await updateUserAction(userId, { globalRole: role });
        if (res.success) await refreshUsers();
        else alert(res.error);
        setIsLoading(false);
    };

    const handleAssignBrandRole = async (userId: string, brandId: string, role: BrandRole) => {
        setIsLoading(true);
        const res = await assignBrandRoleAction(userId, brandId, role);
        if (res.success) await refreshUsers();
        else alert(res.error);
        setIsLoading(false);
    };

    const handleRemoveBrandRole = async (userId: string, brandId: string) => {
        setIsLoading(true);
        const res = await removeBrandRoleAction(userId, brandId);
        if (res.success) await refreshUsers();
        else alert(res.error);
        setIsLoading(false);
    };

    const filteredUsers = users.filter(u =>
        u.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        u.email.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div className="min-h-screen bg-[#FDFBF7] p-8">
            {/* Header */}
            <div className="max-w-7xl mx-auto mb-12 flex justify-between items-end">
                <div className="space-y-2">
                    <div className="flex items-center gap-3 text-stone-500 mb-2">
                        <Users className="w-5 h-5" />
                        <span className="text-sm font-bold uppercase tracking-[0.2em]">Platform Governance</span>
                    </div>
                    <h1 className="text-4xl font-black text-stone-900">User Management</h1>
                    <p className="text-stone-500">Manage system access, global roles, and brand-specific permissions.</p>
                </div>
                <button
                    onClick={() => setIsCreateModalOpen(true)}
                    className="flex items-center gap-2 px-6 py-3 bg-stone-900 text-white rounded-2xl font-bold hover:bg-stone-800 transition-all shadow-xl shadow-stone-900/10"
                >
                    <UserPlus className="w-5 h-5" />
                    Create New User
                </button>
            </div>

            {/* Main Content */}
            <div className="max-w-7xl mx-auto space-y-6">
                {/* Search & Stats */}
                <div className="flex gap-4 items-center bg-white p-4 rounded-3xl border border-stone-200 shadow-sm">
                    <div className="flex-1 relative">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-stone-400" />
                        <input
                            type="text"
                            placeholder="Search by name or email..."
                            className="w-full pl-12 pr-4 py-3 bg-stone-50 rounded-2xl border-none focus:ring-2 focus:ring-stone-900 outline-none transition-all"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    </div>
                    <div className="px-6 py-3 bg-amber-50 rounded-2xl border border-amber-100 flex items-center gap-3">
                        <UserCheck className="w-5 h-5 text-amber-600" />
                        <div className="text-sm font-bold text-amber-900">
                            {users.length} Total Users
                        </div>
                    </div>
                </div>

                {/* User Table Card */}
                <div className="bg-white rounded-[2.5rem] border border-stone-200 shadow-sm overflow-hidden">
                    <table className="w-full text-left">
                        <thead>
                            <tr className="bg-stone-50 border-b border-stone-100">
                                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-stone-400">Identity</th>
                                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-stone-400">Global Role</th>
                                <th className="px-8 py-5 text-[10px] font-black uppercase tracking-[0.2em] text-stone-400">Brand Access</th>
                                <th className="px-8 py-5 text-right text-[10px] font-black uppercase tracking-[0.2em] text-stone-400">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-stone-50">
                            {filteredUsers.map((user) => (
                                <tr key={user.id} className="hover:bg-stone-50/50 transition-colors group">
                                    <td className="px-8 py-6">
                                        <div className="flex items-center gap-4">
                                            <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-stone-100 to-stone-200 flex items-center justify-center font-black text-stone-500">
                                                {user.name.charAt(0)}
                                            </div>
                                            <div>
                                                <p className="font-black text-stone-900">{user.name}</p>
                                                <p className="text-xs text-stone-400">{user.email}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-8 py-6">
                                        <div className="flex items-center gap-2">
                                            <Shield className={`w-4 h-4 ${user.globalRole === 'OWNER' ? 'text-amber-500' : 'text-stone-400'}`} />
                                            <span className={`text-[10px] font-black uppercase tracking-widest ${user.globalRole === 'OWNER' ? 'text-amber-600' : 'text-stone-500'}`}>
                                                {user.globalRole}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="px-8 py-6">
                                        <div className="flex flex-wrap gap-2">
                                            {user.globalRole === 'OWNER' ? (
                                                <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-amber-100 text-amber-700 rounded-full text-[10px] font-black uppercase tracking-tight border border-amber-200">
                                                    <Shield className="w-3 h-3" />
                                                    All Brands (Master)
                                                </span>
                                            ) : user.brandRoles?.length > 0 ? (
                                                user.brandRoles.map((br: any) => (
                                                    <span key={br.id} className="inline-flex items-center gap-1.5 px-3 py-1 bg-stone-100 text-stone-600 rounded-full text-[10px] font-black uppercase tracking-tight">
                                                        <Building className="w-3 h-3" />
                                                        {br.brand.name} ({br.role})
                                                    </span>
                                                ))
                                            ) : (
                                                <span className="text-[10px] font-bold text-stone-300 italic italic">No brand access</span>
                                            )}
                                        </div>
                                    </td>
                                    <td className="px-8 py-6 text-right">
                                        <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button
                                                onClick={() => { setSelectedUserId(user.id); setIsRoleModalOpen(true); }}
                                                className="p-2 hover:bg-white rounded-xl border border-transparent hover:border-stone-200 text-stone-400 hover:text-stone-900 transition-all"
                                                title="Permissions"
                                            >
                                                <Settings2 className="w-5 h-5" />
                                            </button>
                                            <button
                                                onClick={() => handleDeleteUser(user.id)}
                                                className="p-2 hover:bg-rose-50 rounded-xl border border-transparent hover:border-rose-200 text-stone-400 hover:text-rose-600 transition-all"
                                                title="Delete User"
                                            >
                                                <Trash2 className="w-5 h-5" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Create User Modal */}
            {isCreateModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-stone-900/40 backdrop-blur-md">
                    <div className="bg-white w-full max-w-lg rounded-[3rem] shadow-2xl border border-stone-200 overflow-hidden animate-in fade-in zoom-in duration-300">
                        <div className="px-10 py-8 border-b border-stone-100 flex justify-between items-center bg-stone-50/50">
                            <div className="space-y-1">
                                <span className="text-[10px] font-black uppercase tracking-[0.4em] text-stone-400">Platform Registry</span>
                                <h2 className="text-2xl font-black text-stone-900">Create New Identity</h2>
                            </div>
                            <button onClick={() => setIsCreateModalOpen(false)} className="p-2 hover:bg-stone-100 rounded-xl transition-all">
                                <X className="w-6 h-6 text-stone-400" />
                            </button>
                        </div>
                        <form onSubmit={handleCreateUser} className="p-10 space-y-6">
                            <div className="space-y-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-stone-400">Full Name</label>
                                    <div className="relative">
                                        <Users className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-stone-300" />
                                        <input
                                            required
                                            className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-12 py-3 text-sm focus:ring-2 focus:ring-stone-900 outline-none transition-all"
                                            placeholder="Achiera Staff"
                                            value={newUser.name}
                                            onChange={(e) => setNewUser({ ...newUser, name: e.target.value })}
                                        />
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-stone-400">Email Address</label>
                                    <div className="relative">
                                        <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-stone-300" />
                                        <input
                                            type="email"
                                            required
                                            className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-12 py-3 text-sm focus:ring-2 focus:ring-stone-900 outline-none transition-all"
                                            placeholder="staff@achiera.com"
                                            value={newUser.email}
                                            onChange={(e) => setNewUser({ ...newUser, email: e.target.value })}
                                        />
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-stone-400">Initialize Password</label>
                                    <div className="relative">
                                        <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-stone-300" />
                                        <input
                                            type="password"
                                            required
                                            className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-12 py-3 text-sm focus:ring-2 focus:ring-stone-900 outline-none transition-all"
                                            placeholder="Min. 8 characters"
                                            value={newUser.password}
                                            onChange={(e) => setNewUser({ ...newUser, password: e.target.value })}
                                        />
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-stone-400">Global System Role</label>
                                    <select
                                        className="w-full bg-stone-50 border border-stone-100 rounded-2xl px-4 py-3 text-sm focus:ring-2 focus:ring-stone-900 outline-none transition-all"
                                        value={newUser.globalRole}
                                        onChange={(e) => setNewUser({ ...newUser, globalRole: e.target.value as GlobalRole })}
                                    >
                                        <option value="USER">USER (Standard)</option>
                                        <option value="PLATFORM_ADMIN">PLATFORM_ADMIN</option>
                                        <option value="PLATFORM_FINANCE">PLATFORM_FINANCE</option>
                                        <option value="OWNER">OWNER (Full Master)</option>
                                    </select>
                                </div>
                            </div>
                            <button type="submit" className="w-full py-4 bg-stone-900 text-white font-black uppercase tracking-widest rounded-2xl hover:bg-stone-800 transition-all shadow-xl shadow-stone-900/20">
                                Deploy Identity
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Permissions & Roles Modal */}
            {isRoleModalOpen && activeUser && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-stone-900/40 backdrop-blur-md">
                    <div className="bg-white w-full max-w-2xl rounded-[3rem] shadow-2xl border border-stone-200 overflow-hidden animate-in fade-in zoom-in duration-300">
                        {isLoading && (
                            <div className="absolute inset-0 bg-white/50 backdrop-blur-[1px] z-10 flex items-center justify-center">
                                <div className="w-8 h-8 border-4 border-stone-900 border-t-transparent rounded-full animate-spin"></div>
                            </div>
                        )}
                        <div className="px-10 py-8 border-b border-stone-100 flex justify-between items-center bg-stone-50/50">
                            <div className="flex items-center gap-4">
                                <div className="w-12 h-12 rounded-2xl bg-stone-900 flex items-center justify-center font-black text-white text-xl">
                                    {activeUser.name.charAt(0)}
                                </div>
                                <div>
                                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-stone-400">Permissions Matrix</span>
                                    <h2 className="text-xl font-black text-stone-900">{activeUser.name}</h2>
                                </div>
                            </div>
                            <button onClick={() => { setIsRoleModalOpen(false); setSelectedUserId(null); }} className="p-2 hover:bg-stone-100 rounded-xl transition-all">
                                <X className="w-6 h-6 text-stone-400" />
                            </button>
                        </div>

                        <div className="p-10 space-y-10 max-h-[60vh] overflow-y-auto">
                            {/* Global Role Section */}
                            <div className="bg-stone-50 p-8 rounded-[2rem] border border-stone-100 space-y-6">
                                <div className="flex items-center justify-between">
                                    <h3 className="text-[10px] font-black text-stone-900 uppercase tracking-[0.3em] flex items-center gap-2">
                                        <Shield className="w-4 h-4 text-stone-400" />
                                        Global System Responsibility
                                    </h3>
                                    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-tight border ${activeUser.globalRole === 'OWNER' ? 'bg-amber-100 text-amber-700 border-amber-200' : 'bg-stone-100 text-stone-600 border-stone-200'
                                        }`}>
                                        Current: {activeUser.globalRole}
                                    </span>
                                </div>

                                <div className="grid grid-cols-2 gap-3">
                                    {['USER', 'PLATFORM_ADMIN', 'PLATFORM_FINANCE', 'OWNER'].map((role) => (
                                        <button
                                            key={role}
                                            disabled={isLoading}
                                            onClick={() => handleUpdateGlobalRole(activeUser.id, role as GlobalRole)}
                                            className={`px-4 py-4 rounded-2xl border-2 text-[10px] font-black uppercase tracking-widest transition-all ${activeUser.globalRole === role
                                                    ? 'bg-stone-900 border-stone-900 text-white shadow-lg shadow-stone-900/20'
                                                    : 'bg-white border-stone-100 text-stone-400 hover:border-stone-300'
                                                } disabled:opacity-50`}
                                        >
                                            {role}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Brand Access Section */}
                            <div className="space-y-6">
                                <h3 className="text-[10px] font-black text-stone-900 uppercase tracking-[0.3em] flex items-center gap-2 px-2">
                                    <Building className="w-4 h-4 text-stone-400" />
                                    Brand Specific Permissions
                                </h3>

                                {activeUser.globalRole === 'OWNER' ? (
                                    <div className="p-8 bg-amber-50 rounded-[2rem] border-2 border-amber-200 border-dashed text-center space-y-3">
                                        <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center mx-auto text-amber-600">
                                            <Shield className="w-6 h-6" />
                                        </div>
                                        <div className="space-y-1">
                                            <h4 className="text-sm font-black text-amber-900 uppercase tracking-widest">Master Authority</h4>
                                            <p className="text-xs text-amber-700 font-medium max-w-[280px] mx-auto">
                                                As an OWNER, this user automatically inherits full administrative permissions across all brands in the Achiera ecosystem.
                                            </p>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="grid grid-cols-1 gap-3">
                                        {availableBrands.map((brand) => {
                                            const currentRole = activeUser.brandRoles?.find((br: any) => br.brandId === brand.id);
                                            return (
                                                <div key={brand.id} className="p-5 bg-white rounded-3xl flex items-center justify-between border border-stone-200 hover:border-stone-300 transition-all group/brand">
                                                    <div className="font-bold text-stone-900 flex items-center gap-4">
                                                        <div className="w-10 h-10 rounded-xl bg-stone-50 border border-stone-100 flex items-center justify-center text-lg grayscale group-hover/brand:grayscale-0 transition-all">
                                                            {brand.slug.includes('rasa-ibu') ? '🥗' : brand.slug.includes('it-solution') ? '💻' : brand.slug.includes('merch') ? '👕' : '🏛️'}
                                                        </div>
                                                        <div>
                                                            <p className="text-sm font-black text-stone-900">{brand.name}</p>
                                                            <p className="text-[10px] text-stone-400 uppercase tracking-widest font-bold">
                                                                {currentRole ? currentRole.role : 'No Access'}
                                                            </p>
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center gap-3">
                                                        <select
                                                            disabled={isLoading}
                                                            className="bg-stone-50 border border-stone-100 rounded-xl px-4 py-2 text-[10px] font-black uppercase tracking-widest outline-none focus:ring-2 focus:ring-stone-900 disabled:opacity-50 transition-all cursor-pointer"
                                                            value={currentRole?.role || ''}
                                                            onChange={(e) => {
                                                                if (e.target.value) {
                                                                    handleAssignBrandRole(activeUser.id, brand.id, e.target.value as BrandRole);
                                                                } else {
                                                                    handleRemoveBrandRole(activeUser.id, brand.id);
                                                                }
                                                            }}
                                                        >
                                                            <option value="">No Access</option>
                                                            <option value="BRAND_ADMIN">BRAND_ADMIN</option>
                                                            <option value="BRAND_FINANCE">BRAND_FINANCE</option>
                                                            <option value="BRAND_WAREHOUSE_ADMIN">WAREHOUSE_ADMIN</option>
                                                            <option value="WAREHOUSE_STAFF">STAFF</option>
                                                            <option value="BRAND_MARKETING">MARKETING</option>
                                                            <option value="CUSTOMER_SUPPORT">SUPPORT</option>
                                                        </select>
                                                        {currentRole && (
                                                            <button
                                                                disabled={isLoading}
                                                                onClick={() => handleRemoveBrandRole(activeUser.id, brand.id)}
                                                                className="p-2 hover:bg-rose-50 rounded-xl text-rose-500 transition-all disabled:opacity-50 border border-transparent hover:border-rose-100"
                                                            >
                                                                <Trash2 className="w-4 h-4" />
                                                            </button>
                                                        )}
                                                    </div>
                                                </div>
                                            );
                                        })}
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="px-10 py-8 bg-stone-50 border-t border-stone-100 flex justify-end">
                            <button
                                onClick={() => { setIsRoleModalOpen(false); setSelectedUserId(null); }}
                                className="px-8 py-3 bg-stone-900 text-white rounded-2xl font-bold hover:shadow-lg transition-all"
                            >
                                Done
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
    Loader2,
    Search,
    Mail,
    Phone,
    CheckCircle2,
    Calendar,
    MessageSquare
} from 'lucide-react';
import { toast } from 'sonner';

interface CatalogueRequest {
    id: string;
    companyName: string;
    contactName: string;
    email: string;
    phone: string | null;
    notes: string | null;
    status: string;
    createdAt: string;
}

interface CatalogueRequestListProps {
    brandSlug: string;
}

export default function CatalogueRequestList({ brandSlug }: CatalogueRequestListProps) {
    const [requests, setRequests] = useState<CatalogueRequest[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');

    useEffect(() => {
        fetchRequests();
    }, [brandSlug]);

    const fetchRequests = async () => {
        try {
            const res = await fetch(`/api/admin/${brandSlug}/catalogue-requests`);
            if (!res.ok) throw new Error('Failed to fetch requests');
            const data = await res.json();

            if (Array.isArray(data)) {
                setRequests(data);
            } else {
                console.error('Expected array but got:', data);
                setRequests([]);
            }
        } catch (error) {
            console.error(error);
            toast.error('Failed to load requests');
            setRequests([]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleUpdateStatus = async (id: string, newStatus: string) => {
        // Optimistic update
        const previous = [...requests];
        setRequests(requests.map(r => r.id === id ? { ...r, status: newStatus } : r));

        try {
            const res = await fetch(`/api/admin/${brandSlug}/catalogue-requests`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ id, status: newStatus })
            });

            if (!res.ok) throw new Error('Failed to update status');
            toast.success('Status updated');
        } catch (error) {
            toast.error('Failed to update status');
            setRequests(previous);
        }
    };

    const filteredRequests = requests.filter(r =>
        r.companyName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        r.contactName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        r.email.toLowerCase().includes(searchQuery.toLowerCase())
    );

    if (isLoading) {
        return (
            <div className="flex justify-center items-center h-64">
                <Loader2 className="w-8 h-8 animate-spin text-stone-400" />
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Toolbar */}
            <div className="flex justify-between items-center bg-white p-4 rounded-xl border border-stone-200 shadow-sm">
                <div className="relative w-full sm:w-96">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-stone-400" />
                    <input
                        type="text"
                        placeholder="Search leads..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 border border-stone-200 rounded-lg focus:ring-2 focus:ring-amber-500 outline-none"
                    />
                </div>
                <div className="text-sm text-stone-500">
                    {filteredRequests.length} Requests Found
                </div>
            </div>

            {/* List */}
            {filteredRequests.length === 0 ? (
                <div className="text-center py-20 bg-stone-50 rounded-xl border-2 border-dashed border-stone-200">
                    <div className="bg-white w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm border border-stone-100">
                        <Mail className="w-8 h-8 text-stone-400" />
                    </div>
                    <h3 className="text-lg font-bold text-stone-900 mb-2">No Requests Yet</h3>
                    <p className="text-stone-500 max-w-sm mx-auto">
                        New catalogue download requests will appear here.
                    </p>
                </div>
            ) : (
                <div className="grid gap-4">
                    {filteredRequests.map((req) => (
                        <div key={req.id} className="bg-white p-6 rounded-xl border border-stone-200 shadow-sm hover:shadow-md transition-shadow">
                            <div className="flex flex-col md:flex-row justify-between gap-6">
                                {/* Lead Info */}
                                <div className="space-y-4 flex-1">
                                    <div>
                                        <div className="flex items-center gap-3 mb-1">
                                            <h3 className="text-lg font-bold text-stone-900">{req.companyName}</h3>
                                            <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold ${req.status === 'NEW'
