'use client';

import React, { useState, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getAuditLogsAction } from '@/lib/actions/audit';
import { AuditSeverity } from '@prisma/client';
import {
    Activity, Pause, Play, Filter,
    CheckCircle, AlertTriangle, AlertCircle, Shield
} from 'lucide-react';

interface ActivityMonitorProps {
    brandId?: string;
    autoRefresh?: boolean;
    refreshInterval?: number; // in seconds
}

export function ActivityMonitor({
    brandId,
    autoRefresh = true,
    refreshInterval = 10
}: ActivityMonitorProps) {
    const [isPaused, setIsPaused] = useState(false);
    const [severityFilter, setSeverityFilter] = useState<AuditSeverity | 'ALL'>('ALL');

    const { data: logsData, refetch } = useQuery({
        queryKey: ['activity-monitor', brandId, severityFilter],
        queryFn: async () => {
            const result = await getAuditLogsAction({
                brandId,
                severity: severityFilter !== 'ALL' ? severityFilter : undefined,
                limit: 20
            });
            return result.data || [];
        },
        refetchInterval: !isPaused && autoRefresh ? refreshInterval * 1000 : false
    });

    const getSeverityIcon = (severity: AuditSeverity) => {
        switch (severity) {
            case 'INFO': return <CheckCircle className="text-blue-500" size={16} />;
            case 'WARNING': return <AlertTriangle className="text-yellow-500" size={16} />;
            case 'CRITICAL': return <AlertCircle className="text-red-500" size={16} />;
            case 'SECURITY': return <Shield className="text-purple-500" size={16} />;
        }
    };

    const getSeverityColor = (severity: AuditSeverity) => {
        switch (severity) {
            case 'INFO': return 'border-l-blue-500 bg-blue-50';
            case 'WARNING': return 'border-l-yellow-500 bg-yellow-50';
            case 'CRITICAL': return 'border-l-red-500 bg-red-50';
            case 'SECURITY': return 'border-l-purple-500 bg-purple-50';
        }
    };

    const formatActionName = (action: string) => {
        return action.replace(/_/g, ' ').toLowerCase()
            .split(' ')
            .map(word => word.charAt(0).toUpperCase() + word.slice(1))
            .join(' ');
    };

    const getTimeAgo = (timestamp: Date) => {
        const now = new Date();
        const diff = now.getTime() - new Date(timestamp).getTime();
        const seconds = Math.floor(diff / 1000);
        const minutes = Math.floor(seconds / 60);
        const hours = Math.floor(minutes / 60);

        if (seconds < 60) return `${seconds}s ago`;
        if (minutes < 60) return `${minutes}m ago`;
        if (hours < 24) return `${hours}h ago`;
        return new Date(timestamp).toLocaleDateString();
    };

    return (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            {/* Header */}
            <div className="p-4 border-b border-slate-200 bg-gradient-to-r from-slate-50 to-slate-100">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <Activity className="text-indigo-600" size={20} />
                        <h3 className="font-bold text-slate-900">Live Activity Monitor</h3>
                        {!isPaused && (
                            <span className="flex items-center gap-1 text-xs text-green-600 font-medium">
                                <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                                Live
                            </span>
                        )}
                    </div>

                    <div className="flex items-center gap-2">
                        {/* Severity Filter */}
                        <select
                            value={severityFilter}
                            onChange={(e) => setSeverityFilter(e.target.value as AuditSeverity | 'ALL')}
                            className="text-xs px-2 py-1 border border-slate-300 rounded focus:ring-2 focus:ring-indigo-500"
                        >
                            <option value="ALL">All</option>
                            <option value="INFO">Info</option>
                            <option value="WARNING">Warning</option>
                            <option value="CRITICAL">Critical</option>
                            <option value="SECURITY">Security</option>
                        </select>

                        {/* Pause/Play Button */}
                        <button
                            onClick={() => setIsPaused(!isPaused)}
                            className={`flex items-center gap-1 px-3 py-1 rounded text-xs font-medium transition-colors ${isPaused
                                    ? 'bg-green-600 text-white hover:bg-green-700'
                                    : 'bg-slate-600 text-white hover:bg-slate-700'
                                }`}
                        >
                            {isPaused ? (
                                <>
                                    <Play size={12} />
                                    Resume
                                </>
                            ) : (
                                <>
                                    <Pause size={12} />
                                    Pause
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </div>

            {/* Activity Feed */}
            <div className="max-h-[600px] overflow-y-auto">
                {logsData && logsData.length > 0 ? (
                    <div className="divide-y divide-slate-100">
                        {logsData.map((log: any, index: number) => (
                            <div
                                key={log.id}
                                className={`p-3 border-l-4 ${getSeverityColor(log.severity)} hover:bg-slate-50 transition-all duration-200`}
                                style={{
                                    animation: index === 0 && !isPaused ? 'slideIn 0.3s ease-out' : 'none'
                                }}
                            >
                                <div className="flex items-start gap-3">
                                    {/* Icon */}
                                    <div className="flex-shrink-0 mt-0.5">
                                        {getSeverityIcon(log.severity)}
                                    </div>

                                    {/* Content */}
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className="font-semibold text-slate-900 text-sm">
                                                {log.userName}
                                            </span>
                                            <span className="text-xs text-slate-400">•</span>
                                            <span className="text-xs text-slate-600">
                                                {formatActionName(log.action)}
                                            </span>
                                        </div>

                                        <div className="text-xs text-slate-600 mb-1">
                                            <span className="font-medium">{log.entityType}</span>
                                            {log.brand && (
                                                <>
                                                    <span className="text-slate-400 mx-1">in</span>
                                                    <span className="font-medium">{log.brand.name}</span>
                                                </>
                                            )}
                                        </div>

                                        {log.metadata && log.metadata.description && (
                                            <div className="text-xs text-slate-500 mt-1">
                                                {log.metadata.description}
                                            </div>
                                        )}
                                    </div>

                                    {/* Timestamp */}
                                    <div className="flex-shrink-0 text-xs text-slate-400">
                                        {getTimeAgo(log.timestamp)}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="p-12 text-center text-slate-400">
                        <Activity size={48} className="mx-auto mb-4 opacity-50" />
                        <p className="font-medium">No recent activity</p>
                        <p className="text-sm mt-1">Activity will appear here in real-time</p>
                    </div>
                )}
            </div>

            {/* Footer */}
            <div className="p-3 border-t border-slate-200 bg-slate-50 text-center">
                <p className="text-xs text-slate-500">
                    {isPaused ? (
                        'Updates paused'
                    ) : (
                        `Auto-refreshing every ${refreshInterval} seconds`
                    )}
                </p>
            </div>

            <style jsx>{`
                @keyframes slideIn {
                    from {
                        opacity: 0;
                        transform: translateY(-10px);
                    }
                    to {
                        opacity: 1;
                        transform: translateY(0);
                    }
                }
            `}</style>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import {
    getAuditLogsAction,
    exportAuditLogsAction,
    getAuditStatisticsAction
} from '@/lib/actions/audit';
import { AuditAction, AuditSeverity } from '@prisma/client';
import {
    Search, Download, Filter, Clock, User,
    AlertCircle, CheckCircle, AlertTriangle, Shield
} from 'lucide-react';

interface AuditTrailViewerProps {
    brandId?: string;
}

export function AuditTrailViewer({ brandId }: AuditTrailViewerProps) {
    const [filters, setFilters] = useState({
        brandId,
        action: undefined as AuditAction | undefined,
        severity: undefined as AuditSeverity | undefined,
        searchQuery: '',
        startDate: undefined as Date | undefined,
        endDate: undefined as Date | undefined
    });

    const { data: logsData, isLoading } = useQuery({
        queryKey: ['audit-logs', filters],
        queryFn: async () => {
            const result = await getAuditLogsAction({
                brandId: filters.brandId,
                action: filters.action,
                severity: filters.severity,
                startDate: filters.startDate,
                endDate: filters.endDate,
                limit: 100
            });
            return result.data || [];
        }
    });

    const { data: statsData } = useQuery({
        queryKey: ['audit-stats', brandId],
        queryFn: async () => {
            const result = await getAuditStatisticsAction(brandId, 30);
            return result.data;
        }
    });

    const handleExport = async () => {
        const result = await exportAuditLogsAction(filters);
        if (result.success && result.data) {
            const blob = new Blob([result.data], { type: 'text/csv' });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `audit-trail-${new Date().toISOString()}.csv`;
            a.click();
        }
    };

    const getSeverityIcon = (severity: AuditSeverity) => {
        switch (severity) {
            case 'INFO': return <CheckCircle className="text-blue-500" size={16} />;
            case 'WARNING': return <AlertTriangle className="text-yellow-500" size={16} />;
            case 'CRITICAL': return <AlertCircle className="text-red-500" size={16} />;
            case 'SECURITY': return <Shield className="text-purple-500" size={16} />;
        }
    };

    const getSeverityColor = (severity: AuditSeverity) => {
        switch (severity) {
            case 'INFO': return 'bg-blue-50 text-blue-700 border-blue-200';
            case 'WARNING': return 'bg-yellow-50 text-yellow-700 border-yellow-200';
            case 'CRITICAL': return 'bg-red-50 text-red-700 border-red-200';
            case 'SECURITY': return 'bg-purple-50 text-purple-700 border-purple-200';
        }
    };

    const formatActionName = (action: string) => {
        return action.replace(/_/g, ' ').toLowerCase()
            .split(' ')
            .map(word => word.charAt(0).toUpperCase() + word.slice(1))
            .join(' ');
    };

    const filteredLogs = logsData?.filter(log => {
        if (filters.searchQuery) {
            const query = filters.searchQuery.toLowerCase();
            return (
                log.userName.toLowerCase().includes(query) ||
                log.entityType.toLowerCase().includes(query) ||
                log.action.toLowerCase().includes(query)
            );
        }
        return true;
    });

    return (
        <div className="space-y-6">
            {/* Header with Statistics */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                <div className="flex items-center justify-between mb-6">
                    <div>
                        <h2 className="text-2xl font-black text-slate-900">Audit Trail</h2>
                        <p className="text-sm text-slate-600 mt-1">Complete activity log for accountability</p>
                    </div>
                    <button
                        onClick={handleExport}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-medium"
                    >
                        <Download size={16} />
                        Export CSV
                    </button>
                </div>

                {/* Statistics Cards */}
                {statsData && (
                    <div className="grid grid-cols-4 gap-4">
                        <div className="bg-gradient-to-br from-blue-50 to-blue-100 rounded-lg p-4 border border-blue-200">
                            <div className="text-xs font-bold text-blue-700 uppercase tracking-wider mb-1">Total Actions</div>
                            <div className="text-2xl font-black text-blue-900">{statsData.total.toLocaleString()}</div>
                        </div>
                        <div className="bg-gradient-to-br from-green-50 to-green-100 rounded-lg p-4 border border-green-200">
                            <div className="text-xs font-bold text-green-700 uppercase tracking-wider mb-1">Info</div>
                            <div className="text-2xl font-black text-green-900">{statsData.bySeverity.INFO || 0}</div>
                        </div>
                        <div className="bg-gradient-to-br from-yellow-50 to-yellow-100 rounded-lg p-4 border border-yellow-200">
                            <div className="text-xs font-bold text-yellow-700 uppercase tracking-wider mb-1">Warnings</div>
                            <div className="text-2xl font-black text-yellow-900">{statsData.bySeverity.WARNING || 0}</div>
                        </div>
                        <div className="bg-gradient-to-br from-red-50 to-red-100 rounded-lg p-4 border border-red-200">
                            <div className="text-xs font-bold text-red-700 uppercase tracking-wider mb-1">Critical</div>
                            <div className="text-2xl font-black text-red-900">
                                {(statsData.bySeverity.CRITICAL || 0) + (statsData.bySeverity.SECURITY || 0)}
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Filters */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-4">
                <div className="flex items-center gap-4">
                    <div className="flex-1 relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                        <input
                            type="text"
                            placeholder="Search by user, entity, or action..."
                            value={filters.searchQuery}
                            onChange={(e) => setFilters({ ...filters, searchQuery: e.target.value })}
                            className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                        />
                    </div>

                    <select
                        value={filters.severity || ''}
                        onChange={(e) => setFilters({ ...filters, severity: e.target.value as AuditSeverity || undefined })}
                        className="px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                    >
                        <option value="">All Severities</option>
                        <option value="INFO">Info</option>
                        <option value="WARNING">Warning</option>
                        <option value="CRITICAL">Critical</option>
                        <option value="SECURITY">Security</option>
                    </select>

                    <button className="flex items-center gap-2 px-4 py-2 border border-slate-300 rounded-lg hover:bg-slate-50 transition-colors">
                        <Filter size={16} />
                        More Filters
                    </button>
                </div>
            </div>

            {/* Audit Log Timeline */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 border-b border-slate-200 bg-slate-50">
                    <h3 className="font-bold text-slate-900">Activity Timeline</h3>
                </div>

                {isLoading ? (
                    <div className="p-12 text-center text-slate-400">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
                        Loading audit logs...
                    </div>
                ) : filteredLogs && filteredLogs.length > 0 ? (
                    <div className="divide-y divide-slate-100">
                        {filteredLogs.map((log: any) => (
                            <div key={log.id} className="p-4 hover:bg-slate-50 transition-colors">
                                <div className="flex items-start gap-4">
                                    {/* Severity Icon */}
                                    <div className="mt-1">
                                        {getSeverityIcon(log.severity)}
                                    </div>

                                    {/* Content */}
                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 mb-1">
                                            <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-bold border ${getSeverityColor(log.severity)}`}>
                                                {log.severity}
                                            </span>
                                            <span className="text-xs font-medium text-slate-500">
                                                {formatActionName(log.action)}
                                            </span>
                                        </div>

                                        <div className="flex items-center gap-2 text-sm mb-2">
                                            <User size={14} className="text-slate-400" />
                                            <span className="font-semibold text-slate-900">{log.userName}</span>
                                            <span className="text-slate-400">•</span>
                                            <span className="text-slate-600">{log.userRole}</span>
                                        </div>

                                        <div className="text-sm text-slate-700 mb-2">
                                            <span className="font-medium">{log.entityType}</span>
                                            <span className="text-slate-400 mx-2">→</span>
                                            <code className="text-xs bg-slate-100 px-2 py-0.5 rounded">{log.entityId}</code>
                                        </div>

                                        {log.brand && (
                                            <div className="text-xs text-slate-500">
                                                Brand: <span className="font-medium">{log.brand.name}</span>
                                            </div>
                                        )}

                                        {log.changes && (
                                            <details className="mt-2">
                                                <summary className="text-xs text-indigo-600 cursor-pointer hover:text-indigo-700 font-medium">
                                                    View Changes
                                                </summary>
                                                <pre className="mt-2 p-3 bg-slate-50 rounded text-xs overflow-x-auto border border-slate-200">
                                                    {JSON.stringify(log.changes, null, 2)}
                                                </pre>
                                            </details>
                                        )}
                                    </div>

                                    {/* Timestamp */}
                                    <div className="text-right">
                                        <div className="flex items-center gap-1 text-xs text-slate-500 mb-1">
                                            <Clock size={12} />
                                            {new Date(log.timestamp).toLocaleTimeString()}
                                        </div>
                                        <div className="text-xs text-slate-400">
                                            {new Date(log.timestamp).toLocaleDateString()}
                                        </div>
                                        {log.ipAddress && (
                                            <div className="text-xs text-slate-400 mt-1">
                                                IP: {log.ipAddress}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="p-12 text-center text-slate-400">
                        <AlertCircle size={48} className="mx-auto mb-4 opacity-50" />
                        <p className="font-medium">No audit logs found</p>
                        <p className="text-sm mt-1">Try adjusting your filters</p>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getAllBudgetsAction, getVarianceAnalysisAction, getAIForecastAction } from '@/lib/actions/budget';
import { TrendingUp, TrendingDown, AlertCircle, Target, Lightbulb } from 'lucide-react';

export function BudgetManagementHub() {
    const currentYear = new Date().getFullYear();
    const [selectedYear, setSelectedYear] = useState(currentYear);

    const { data: budgetsData, isLoading: loadingBudgets } = useQuery({
        queryKey: ['budgets'],
        queryFn: () => getAllBudgetsAction()
    });

    const budgets = (budgetsData as any)?.data || [];
    const currentYearBudgets = budgets.filter((b: any) => b.fiscalYear === selectedYear);

    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    // Calculate totals
    const totalBudgetRevenue = currentYearBudgets.reduce((sum: number, b: any) => sum + Number(b.revenueTarget), 0);
    const totalBudgetExpense = currentYearBudgets.reduce((sum: number, b: any) => sum + Number(b.expenseTarget), 0);
    const totalBudgetProfit = currentYearBudgets.reduce((sum: number, b: any) => sum + Number(b.profitTarget), 0);

    return (
        <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-700 delay-200">
            <div className="p-8 border-b border-slate-100 bg-gradient-to-r from-slate-900 to-slate-800 text-white">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-blue-500/20 rounded-2xl backdrop-blur-md border border-blue-500/30 text-blue-400">
                            <Target size={24} />
                        </div>
                        <div>
                            <h3 className="font-black text-2xl tracking-tight">Budget Management Center</h3>
                            <p className="text-slate-400 font-medium">Track budget targets vs actual performance metrics</p>
                        </div>
                    </div>

                    <div className="flex items-center gap-3 bg-white/5 p-1 rounded-xl border border-white/10">
                        <div className="pl-3 text-xs font-bold text-slate-500 uppercase tracking-widest">Fiscal Year</div>
                        <select
                            value={selectedYear}
                            onChange={(e) => setSelectedYear(Number(e.target.value))}
                            className="px-4 py-2 bg-slate-800 border-none rounded-lg text-white font-bold text-sm outline-none focus:ring-2 focus:ring-blue-500"
                        >
                            <option value={currentYear - 1}>{currentYear - 1}</option>
                            <option value={currentYear}>{currentYear}</option>
                            <option value={currentYear + 1}>{currentYear + 1}</option>
                        </select>
                    </div>
                </div>
            </div>

            <div className="p-6">
                {loadingBudgets ? (
                    <div className="text-center py-8 text-slate-400">Loading budgets...</div>
                ) : currentYearBudgets.length === 0 ? (
                    <div className="text-center py-12">
                        <div className="bg-amber-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                            <AlertCircle size={32} className="text-amber-600" />
                        </div>
                        <h4 className="font-medium text-slate-900">No Budgets Set</h4>
                        <p className="text-sm text-slate-500 mt-1">Create budgets for {selectedYear} to start tracking performance</p>
                    </div>
                ) : (
                    <div className="space-y-6">
                        {/* Budget Summary */}
                        <div className="grid grid-cols-3 gap-4">
                            <div className="text-center p-4 bg-green-50 rounded-xl border border-green-200">
                                <div className="text-xs font-bold text-green-700 uppercase tracking-wider mb-1">Total Revenue Target</div>
                                <div className="text-2xl font-black text-green-900">{currency.format(totalBudgetRevenue)}</div>
                            </div>
                            <div className="text-center p-4 bg-red-50 rounded-xl border border-red-200">
                                <div className="text-xs font-bold text-red-700 uppercase tracking-wider mb-1">Total Expense Budget</div>
                                <div className="text-2xl font-black text-red-900">{currency.format(totalBudgetExpense)}</div>
                            </div>
                            <div className="text-center p-4 bg-blue-50 rounded-xl border-2 border-blue-300">
                                <div className="text-xs font-bold text-blue-700 uppercase tracking-wider mb-1">Target Profit</div>
                                <div className="text-2xl font-black text-blue-900">{currency.format(totalBudgetProfit)}</div>
                            </div>
                        </div>

                        {/* Brand Budgets */}
                        <div>
                            <h4 className="font-bold text-sm text-slate-700 mb-3 uppercase tracking-wider">Brand Budgets</h4>
                            <div className="space-y-3">
                                {currentYearBudgets.map((budget: any) => (
                                    <BudgetCard key={budget.id} budget={budget} fiscalYear={selectedYear} />
                                ))}
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
}

function BudgetCard({ budget, fiscalYear }: { budget: any; fiscalYear: number }) {
    const [showDetails, setShowDetails] = useState(false);

    const { data: varianceData } = useQuery({
        queryKey: ['variance', budget.brandId, fiscalYear],
        queryFn: () => getVarianceAnalysisAction(budget.brandId, fiscalYear),
        enabled: showDetails
    });

    const { data: forecastData } = useQuery({
        queryKey: ['forecast', budget.brandId, fiscalYear],
        queryFn: () => getAIForecastAction(budget.brandId, fiscalYear),
        enabled: showDetails
    });

    const variance = (varianceData as any)?.data;
    const forecast = (forecastData as any)?.data;
    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    return (
        <div className="border border-slate-200 rounded-lg overflow-hidden">
            <div
                className="p-4 bg-slate-50 cursor-pointer hover:bg-slate-100 transition-colors"
                onClick={() => setShowDetails(!showDetails)}
            >
                <div className="flex justify-between items-center">
                    <div>
                        <h5 className="font-bold text-slate-900">{budget.brand.name}</h5>
                        <p className="text-xs text-slate-500 mt-1">FY {budget.fiscalYear} • {budget.period}</p>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="text-right">
                            <div className="text-xs text-slate-500">Revenue Target</div>
                            <div className="font-bold text-slate-900">{currency.format(Number(budget.revenueTarget))}</div>
                        </div>
                        <div className="text-right">
                            <div className="text-xs text-slate-500">Profit Target</div>
                            <div className="font-bold text-blue-600">{currency.format(Number(budget.profitTarget))}</div>
                        </div>
                        <Target size={20} className={`text-slate-400 transition-transform ${showDetails ? 'rotate-90' : ''}`} />
                    </div>
                </div>
            </div>

            {showDetails && variance && (
                <div className="p-4 border-t border-slate-200 bg-white">
                    <div className="grid grid-cols-3 gap-4 mb-4">
                        <VarianceMetric
                            label="Revenue"
                            budget={variance.revenue.budget}
                            actual={variance.revenue.actual}
                            variance={variance.revenue.variancePercent}
                            status={variance.revenue.status}
                            isRevenue={true}
                        />
                        <VarianceMetric
                            label="Expense"
                            budget={variance.expense.budget}
                            actual={variance.expense.actual}
                            variance={variance.expense.variancePercent}
                            status={variance.expense.status}
                            isRevenue={false}
                        />
                        <VarianceMetric
                            label="Profit"
                            budget={variance.profit.budget}
                            actual={variance.profit.actual}
                            variance={variance.profit.variancePercent}
                            status={variance.profit.status}
                            isRevenue={true}
                        />
                    </div>

                    {forecast && forecast.recommendation.shouldAdjust && (
                        <div className="mt-4 p-3 bg-amber-50 border border-amber-200 rounded-lg">
                            <div className="flex items-start gap-2">
                                <Lightbulb size={18} className="text-amber-600 mt-0.5" />
                                <div className="flex-1">
                                    <div className="font-bold text-amber-900 text-sm mb-1">AI Forecast Recommendation</div>
                                    <p className="text-xs text-amber-700">{forecast.recommendation.reason}</p>
                                    {forecast.recommendation.suggestedRevenue && (
                                        <div className="mt-2 text-xs text-amber-800">
                                            Suggested adjustment: Revenue {currency.format(forecast.recommendation.suggestedRevenue)} •
                                            Profit {currency.format(forecast.recommendation.suggestedProfit || 0)}
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

function VarianceMetric({ label, budget, actual, variance, status, isRevenue }: any) {
    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    const statusColor = status === 'good' ? 'text-green-600' : status === 'warning' ? 'text-amber-600' : 'text-red-600';
    const bgColor = status === 'good' ? 'bg-green-50' : status === 'warning' ? 'bg-amber-50' : 'bg-red-50';

    return (
        <div className={`p-3 rounded-lg ${bgColor}`}>
            <div className="text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">{label}</div>
            <div className="space-y-1">
                <div className="flex justify-between text-xs">
                    <span className="text-slate-500">Budget:</span>
                    <span className="font-medium">{currency.format(budget)}</span>
                </div>
                <div className="flex justify-between text-xs">
                    <span className="text-slate-500">Actual:</span>
                    <span className="font-bold">{currency.format(actual)}</span>
                </div>
                <div className={`flex items-center justify-between text-xs font-bold ${statusColor}`}>
                    <span>Variance:</span>
                    <span className="flex items-center gap-1">
                        {variance >= 0 ? <TrendingUp size={14} /> : <TrendingDown size={14} />}
                        {variance >= 0 ? '+' : ''}{variance.toFixed(1)}%
                    </span>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
    generateAllocationRecommendationsAction,
    getCashPositionsAction,
    getAllAllocationsAction,
    approveAllocationAction
} from '@/lib/actions/capitalAllocation';
import {
    DollarSign, TrendingUp, TrendingDown, AlertTriangle,
    RefreshCw, CheckCircle, XCircle, Loader, ArrowRight,
    Target, Shield, Zap
} from 'lucide-react';

export function CapitalAllocationDashboard() {
    const [selectedAllocation, setSelectedAllocation] = useState<string | null>(null);
    const queryClient = useQueryClient();

    // Get cash positions
    const { data: cashData, isLoading: cashLoading } = useQuery({
        queryKey: ['cash-positions'],
        queryFn: async () => {
            const result = await getCashPositionsAction();
            return result.data || null;
        }
    });

    // Get latest allocation recommendations
    const { data: allocationsData, isLoading: allocationsLoading } = useQuery({
        queryKey: ['allocations'],
        queryFn: async () => {
            const result = await getAllAllocationsAction(5);
            return result.data || [];
        }
    });

    // Generate new recommendations
    const generateMutation = useMutation({
        mutationFn: async () => {
            return await generateAllocationRecommendationsAction('current-user-id');
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['allocations'] });
            queryClient.invalidateQueries({ queryKey: ['cash-positions'] });
        }
    });

    // Approve allocation
    const approveMutation = useMutation({
        mutationFn: async (allocationId: string) => {
            return await approveAllocationAction(allocationId, 'current-user-id');
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['allocations'] });
        }
    });

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            maximumFractionDigits: 0
        }).format(amount);
    };

    const getRiskColor = (risk: string) => {
        switch (risk) {
            case 'LOW': return 'text-green-600 bg-green-50 border-green-200';
            case 'MEDIUM': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
            case 'HIGH': return 'text-orange-600 bg-orange-50 border-orange-200';
            case 'CRITICAL': return 'text-red-600 bg-red-50 border-red-200';
            default: return 'text-gray-600 bg-gray-50 border-gray-200';
        }
    };

    const latestAllocation = allocationsData?.[0];

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 delay-[500ms]">
            {/* Header */}
            <div className="relative overflow-hidden bg-gradient-to-br from-slate-950 via-slate-900 to-indigo-950 rounded-3xl shadow-2xl p-8 text-white border border-white/5">
                {/* Decorative background elements */}
                <div className="absolute top-0 right-0 w-64 h-64 bg-purple-500/10 blur-[80px] -mr-32 -mt-32 rounded-full" />
                <div className="absolute bottom-0 left-0 w-48 h-48 bg-indigo-500/10 blur-[60px] -ml-24 -mb-24 rounded-full" />

                <div className="relative flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-indigo-500/20 rounded-2xl backdrop-blur-md border border-indigo-500/30 text-indigo-400">
                            <Target size={24} />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black tracking-tight">Capital Allocation Optimizer</h2>
                            <p className="text-slate-400 font-medium flex items-center gap-2">
                                <Shield size={14} className="text-indigo-500" />
                                AI-powered capital deployment strategies and ROI projections
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={() => generateMutation.mutate()}
                        disabled={generateMutation.isPending}
                        className="group flex items-center gap-2 px-8 py-3.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl transition-all font-bold text-sm uppercase tracking-wider shadow-[0_0_20px_rgba(79,70,229,0.3)] hover:shadow-[0_0_30px_rgba(79,70,229,0.5)] disabled:opacity-50"
                    >
                        {generateMutation.isPending ? (
                            <>
                                <Loader className="animate-spin" size={18} />
                                Processing...
                            </>
                        ) : (
                            <>
                                <Zap size={18} className="group-hover:scale-125 transition-transform" />
                                Optimize Allocation
                            </>
                        )}
                    </button>
                </div>
            </div>
            {/* Summary Stats */}
            {cashData && (
                <div className="grid grid-cols-4 gap-4">
                    <div className="bg-white/10 backdrop-blur-md rounded-lg p-4 border border-white/20">
                        <div className="text-xs font-bold text-indigo-100 uppercase tracking-wider mb-1">Total Cash</div>
                        <div className="text-2xl font-black">{formatCurrency(cashData.totalCash)}</div>
                    </div>
                    <div className="bg-white/10 backdrop-blur-md rounded-lg p-4 border border-white/20">
                        <div className="text-xs font-bold text-indigo-100 uppercase tracking-wider mb-1">Avg Runway</div>
                        <div className="text-2xl font-black">{cashData.averageRunway.toFixed(1)} months</div>
                    </div>
                    <div className="bg-white/10 backdrop-blur-md rounded-lg p-4 border border-white/20">
                        <div className="text-xs font-bold text-indigo-100 uppercase tracking-wider mb-1">Critical Brands</div>
                        <div className="text-2xl font-black text-red-300">{cashData.criticalBrands.length}</div>
                    </div>
                    <div className="bg-white/10 backdrop-blur-md rounded-lg p-4 border border-white/20">
                        <div className="text-xs font-bold text-indigo-100 uppercase tracking-wider mb-1">Excess Cash</div>
                        <div className="text-2xl font-black text-green-300">{cashData.excessCashBrands.length}</div>
                    </div>
                </div>
            )}

            {/* Cash Positions */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                    <DollarSign size={20} className="text-indigo-600" />
                    Cash Positions by Brand
                </h3>

                {cashLoading ? (
                    <div className="text-center py-8">
                        <Loader className="animate-spin mx-auto mb-2 text-indigo-600" size={32} />
                        <p className="text-slate-600">Loading cash positions...</p>
                    </div>
                ) : cashData ? (
                    <div className="grid grid-cols-3 gap-4">
                        {cashData.positions.map((position: any) => (
                            <div
                                key={position.brandId}
                                className={`p-4 rounded-lg border-2 ${position.runway < 3
                                    ? 'bg-red-50 border-red-200'
                                    : position.runway > 12
                                        ? 'bg-green-50 border-green-200'
                                        : 'bg-slate-50 border-slate-200'
                                    }`}
                            >
                                <div className="flex items-center justify-between mb-2">
                                    <h4 className="font-bold text-slate-900">{position.brandName}</h4>
                                    {position.trend === 'INCREASING' ? (
                                        <TrendingUp size={18} className="text-green-600" />
                                    ) : position.trend === 'DECREASING' ? (
                                        <TrendingDown size={18} className="text-red-600" />
                                    ) : null}
                                </div>
                                <div className="space-y-1">
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-600">Cash:</span>
                                        <span className="font-bold text-slate-900">{formatCurrency(position.cash)}</span>
                                    </div>
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-600">Runway:</span>
                                        <span className={`font-bold ${position.runway < 3 ? 'text-red-600' :
                                            position.runway > 12 ? 'text-green-600' : 'text-slate-900'
                                            }`}>
                                            {position.runway.toFixed(1)} months
                                        </span>
                                    </div>
                                    <div className="flex justify-between text-sm">
                                        <span className="text-slate-600">Burn Rate:</span>
                                        <span className="font-semibold text-slate-700">{formatCurrency(position.burnRate)}/mo</span>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : null}
            </div>

            {/* AI Recommendations */}
            {
                latestAllocation && (
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                                <Target size={20} className="text-indigo-600" />
                                AI Recommendations
                            </h3>
                            <div className="flex items-center gap-4">
                                <div className="text-right">
                                    <div className="text-xs text-slate-600">Overall Score</div>
                                    <div className="text-2xl font-black text-indigo-600">{latestAllocation.overallScore.toFixed(0)}/100</div>
                                </div>
                                <div className={`px-3 py-1 rounded-full border font-bold text-sm ${getRiskColor(latestAllocation.riskLevel)}`}>
                                    <Shield size={14} className="inline mr-1" />
                                    {latestAllocation.riskLevel} RISK
                                </div>
                            </div>
                        </div>

                        <div className="space-y-3">
                            {Array.isArray(latestAllocation.recommendations) && latestAllocation.recommendations.map((rec: any, idx: number) => (
                                <div
                                    key={idx}
                                    className="p-4 bg-slate-50 rounded-lg border border-slate-200 hover:border-indigo-300 transition-colors"
                                >
                                    <div className="flex items-start justify-between">
                                        <div className="flex-1">
                                            <div className="flex items-center gap-2 mb-2">
                                                <span className="px-2 py-1 bg-indigo-100 text-indigo-700 rounded text-xs font-bold">
                                                    {rec.type.replace('_', ' ')}
                                                </span>
                                                <span className={`px-2 py-1 rounded text-xs font-bold ${getRiskColor(rec.risk)}`}>
                                                    {rec.risk} RISK
                                                </span>
                                                <span className="text-xs text-slate-500">Priority: {rec.priority}/10</span>
                                            </div>

                                            <div className="flex items-center gap-2 mb-2">
                                                {rec.fromBrand && (
                                                    <>
                                                        <span className="font-semibold text-slate-700">{rec.fromBrand}</span>
                                                        <ArrowRight size={16} className="text-slate-400" />
                                                    </>
                                                )}
                                                <span className="font-semibold text-slate-900">{rec.toBrand || 'Reserve'}</span>
                                                <span className="font-black text-indigo-600">{formatCurrency(rec.amount)}</span>
                                            </div>

                                            <p className="text-sm text-slate-600 mb-2">{rec.reason}</p>

                                            <div className="flex items-center gap-4 text-xs">
                                                <div className="flex items-center gap-1">
                                                    <TrendingUp size={14} className="text-green-600" />
                                                    <span className="text-slate-600">Predicted ROI:</span>
                                                    <span className="font-bold text-green-600">{rec.predictedROI}%</span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>

                        {/* Action Buttons */}
                        <div className="mt-6 flex items-center gap-3">
                            <button
                                onClick={() => approveMutation.mutate(latestAllocation.id)}
                                disabled={approveMutation.isPending || latestAllocation.status !== 'PENDING'}
                                className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-bold disabled:opacity-50"
                            >
                                <CheckCircle size={18} />
                                {latestAllocation.status === 'APPROVED' ? 'Approved' : 'Approve & Execute'}
                            </button>
                            <button
                                disabled={latestAllocation.status !== 'PENDING'}
                                className="flex items-center gap-2 px-6 py-3 border-2 border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors font-bold disabled:opacity-50"
                            >
                                <XCircle size={18} />
                                Reject
                            </button>
                            <div className="ml-auto text-sm text-slate-600">
                                <div>Generated: {new Date(latestAllocation.generatedAt).toLocaleString()}</div>
                                <div>Confidence: {latestAllocation.confidence.toFixed(0)}%</div>
                            </div>
                        </div>
                    </div>
                )
            }

            {/* Empty State */}
            {
                !latestAllocation && !allocationsLoading && (
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-12 text-center">
                        <AlertTriangle size={48} className="mx-auto mb-4 text-slate-400" />
                        <h3 className="text-lg font-bold text-slate-900 mb-2">No Recommendations Yet</h3>
                        <p className="text-slate-600 mb-4">
                            Generate AI-powered capital allocation recommendations based on current cash positions
                        </p>
                        <button
                            onClick={() => generateMutation.mutate()}
                            className="px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-bold"
                        >
                            Generate Now
                        </button>
                    </div>
                )
            }
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
    generateCashFlowForecastAction,
    getForecastsAction,
    getActiveLiquidityRisksAction
} from '@/lib/actions/cashFlowForecast';
import { getAllBrandsAction } from '@/lib/actions/brands';
import {
    LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend,
    ResponsiveContainer, Area, AreaChart
} from 'recharts';
import {
    TrendingUp, TrendingDown, AlertTriangle, Zap, Calendar,
    DollarSign, Shield, Target, Loader
} from 'lucide-react';

export function CashFlowForecastDashboard() {
    const [selectedBrand, setSelectedBrand] = useState<string>('');
    const [timeframe, setTimeframe] = useState<3 | 6 | 12>(6);
    const queryClient = useQueryClient();

    // Get all brands
    const { data: brandsData } = useQuery({
        queryKey: ['brands'],
        queryFn: async () => {
            const result = await getAllBrandsAction();
            const brands = result.data || [];
            // Set first brand as default if none selected
            if (brands.length > 0 && !selectedBrand) {
                setSelectedBrand(brands[0].id);
            }
            return brands;
        }
    });

    // Get forecasts
    const { data: forecastsData, isLoading: forecastsLoading, error: forecastsError } = useQuery({
        queryKey: ['cash-flow-forecasts', selectedBrand, timeframe],
        queryFn: async () => {
            if (!selectedBrand) return [];
            const result = await getForecastsAction(selectedBrand, timeframe);
            if (!result.success) {
                console.error('Forecast fetch error:', result.error);
                return [];
            }
            return result.data || [];
        },
        enabled: !!selectedBrand
    });

    // Get liquidity risks
    const { data: risksData } = useQuery({
        queryKey: ['liquidity-risks', selectedBrand],
        queryFn: async () => {
            const result = await getActiveLiquidityRisksAction(selectedBrand);
            return result.data || [];
        }
    });

    // Generate forecast mutation
    const generateMutation = useMutation({
        mutationFn: async () => {
            console.log('Generating forecast for:', selectedBrand, timeframe);
            const result = await generateCashFlowForecastAction(selectedBrand, timeframe);
            if (!result.success) {
                throw new Error(result.error || 'Failed to generate forecast');
            }
            return result;
        },
        onSuccess: (data) => {
            console.log('Forecast generated successfully:', data);
            alert('Cash flow forecast generated successfully!');
            queryClient.invalidateQueries({ queryKey: ['cash-flow-forecasts'] });
            queryClient.invalidateQueries({ queryKey: ['liquidity-risks'] });
        },
        onError: (error: any) => {
            console.error('Forecast generation error:', error);
            alert(`Error: ${error.message}`);
        }
    });

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            maximumFractionDigits: 0,
            notation: 'compact'
        }).format(amount);
    };

    const formatDate = (date: string | Date) => {
        return new Date(date).toLocaleDateString('id-ID', {
            month: 'short',
            year: 'numeric'
        });
    };

    const getRiskColor = (severity: string) => {
        switch (severity) {
            case 'LOW': return 'text-green-600 bg-green-50 border-green-200';
            case 'MEDIUM': return 'text-yellow-600 bg-yellow-50 border-yellow-200';
            case 'HIGH': return 'text-orange-600 bg-orange-50 border-orange-200';
            case 'CRITICAL': return 'text-red-600 bg-red-50 border-red-200';
            default: return 'text-gray-600 bg-gray-50 border-gray-200';
        }
    };

    // Prepare chart data
    const chartData = forecastsData?.map((f: any) => ({
        date: formatDate(f.forecastDate),
        balance: f.predictedBalance,
        bestCase: f.bestCase,
        worstCase: f.worstCase,
        mostLikely: f.mostLikely,
        confidence: f.confidence
    })) || [];

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 delay-[400ms]">
            {/* Header */}
            <div className="relative overflow-hidden bg-gradient-to-br from-slate-950 via-slate-900 to-indigo-950 rounded-3xl shadow-2xl p-8 text-white border border-white/5">
                {/* Decorative background elements */}
                <div className="absolute top-0 right-0 w-64 h-64 bg-cyan-500/10 blur-[80px] -mr-32 -mt-32 rounded-full" />
                <div className="absolute bottom-0 left-0 w-48 h-48 bg-blue-500/10 blur-[60px] -ml-24 -mb-24 rounded-full" />

                <div className="relative flex flex-col lg:flex-row lg:items-center justify-between gap-6 mb-8">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-cyan-500/20 rounded-2xl backdrop-blur-md border border-cyan-500/30 text-cyan-400">
                            <Zap size={24} />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black tracking-tight">AI Cash Flow Forecast</h2>
                            <p className="text-slate-400 font-medium flex items-center gap-2">
                                <Shield size={14} className="text-cyan-500" />
                                ML-powered liquidity projections for strategic planning
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={() => generateMutation.mutate()}
                        disabled={generateMutation.isPending || !selectedBrand}
                        className="group flex items-center gap-2 px-8 py-3.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl transition-all font-bold text-sm uppercase tracking-wider shadow-[0_0_20px_rgba(79,70,229,0.3)] hover:shadow-[0_0_30px_rgba(79,70,229,0.5)] disabled:opacity-50"
                    >
                        {generateMutation.isPending ? (
                            <>
                                <Loader className="animate-spin" size={18} />
                                Analyzing...
                            </>
                        ) : (
                            <>
                                <Zap size={18} className="group-hover:scale-125 transition-transform" />
                                Generate Forecast
                            </>
                        )}
                    </button>
                </div>

                {/* Controls */}
                <div className="relative flex flex-wrap items-center gap-6 p-4 bg-white/5 backdrop-blur-md rounded-2xl border border-white/10">
                    <div className="flex items-center gap-3">
                        <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Portfolio Brand</label>
                        <select
                            value={selectedBrand}
                            onChange={(e) => setSelectedBrand(e.target.value)}
                            className="px-4 py-2.5 bg-slate-800 border-none rounded-xl text-white font-bold text-sm outline-none focus:ring-2 focus:ring-indigo-500 min-w-[180px]"
                        >
                            {brandsData && brandsData.length > 0 ? (
                                brandsData.map((brand) => (
                                    <option key={brand.id} value={brand.id} className="text-slate-900">
                                        {brand.name}
                                    </option>
                                ))
                            ) : (
                                <option value="" className="text-slate-900">Loading brands...</option>
                            )}
                        </select>
                    </div>

                    <div className="w-px h-8 bg-white/10 hidden sm:block" />

                    <div className="flex items-center gap-3">
                        <label className="text-xs font-black text-slate-500 uppercase tracking-widest pl-2">Forecast Horizon</label>
                        <div className="flex gap-1 bg-slate-900 p-1 rounded-xl">
                            {[3, 6, 12].map((months) => (
                                <button
                                    key={months}
                                    onClick={() => setTimeframe(months as 3 | 6 | 12)}
                                    className={`px-4 py-1.5 rounded-lg font-bold text-xs transition-all ${timeframe === months
                                        ? 'bg-indigo-600 text-white shadow-lg'
                                        : 'text-slate-400 hover:text-white hover:bg-white/5'
                                        }`}
                                >
                                    {months}M
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            </div>

            {/* Forecast Chart */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                    <TrendingUp size={20} className="text-blue-600" />
                    Cash Balance Forecast
                </h3>

                {forecastsLoading ? (
                    <div className="text-center py-12">
                        <Loader className="animate-spin mx-auto mb-2 text-blue-600" size={32} />
                        <p className="text-slate-600">Loading forecast data...</p>
                    </div>
                ) : chartData.length > 0 ? (
                    <div className="h-96">
                        <ResponsiveContainer width="100%" height="100%">
                            <AreaChart data={chartData}>
                                <defs>
                                    <linearGradient id="colorBest" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#10b981" stopOpacity={0.3} />
                                        <stop offset="95%" stopColor="#10b981" stopOpacity={0} />
                                    </linearGradient>
                                    <linearGradient id="colorWorst" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#ef4444" stopOpacity={0.3} />
                                        <stop offset="95%" stopColor="#ef4444" stopOpacity={0} />
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                                <XAxis
                                    dataKey="date"
                                    stroke="#64748b"
                                    style={{ fontSize: '12px', fontWeight: 600 }}
                                />
                                <YAxis
                                    stroke="#64748b"
                                    style={{ fontSize: '12px', fontWeight: 600 }}
                                    tickFormatter={(value) => formatCurrency(value)}
                                />
                                <Tooltip
                                    contentStyle={{
                                        backgroundColor: '#1e293b',
                                        border: 'none',
                                        borderRadius: '8px',
                                        color: '#fff',
                                        fontWeight: 600
                                    }}
                                    formatter={(value: any) => formatCurrency(value)}
                                />
                                <Legend
                                    wrapperStyle={{ fontWeight: 600, fontSize: '14px' }}
                                />
                                <Area
                                    type="monotone"
                                    dataKey="bestCase"
                                    stroke="#10b981"
                                    strokeWidth={2}
                                    fill="url(#colorBest)"
                                    name="Best Case"
                                />
                                <Line
                                    type="monotone"
                                    dataKey="mostLikely"
                                    stroke="#3b82f6"
                                    strokeWidth={3}
                                    dot={{ fill: '#3b82f6', r: 4 }}
                                    name="Most Likely"
                                />
                                <Area
                                    type="monotone"
                                    dataKey="worstCase"
                                    stroke="#ef4444"
                                    strokeWidth={2}
                                    fill="url(#colorWorst)"
                                    name="Worst Case"
                                />
                            </AreaChart>
                        </ResponsiveContainer>
                    </div>
                ) : (
                    <div className="text-center py-12">
                        <Calendar size={48} className="mx-auto mb-4 text-slate-400" />
                        <h3 className="text-lg font-bold text-slate-900 mb-2">No Forecast Data</h3>
                        <p className="text-slate-600 mb-4">
                            Generate a forecast to see predictions
                        </p>
                        <button
                            onClick={() => generateMutation.mutate()}
                            className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-bold"
                        >
                            Generate Now
                        </button>
                    </div>
                )}
            </div>

            {/* Liquidity Risks Panel */}
            {risksData && risksData.length > 0 && (
                <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                    <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                        <AlertTriangle size={20} className="text-orange-600" />
                        Liquidity Risk Alerts
                    </h3>

                    <div className="space-y-3">
                        {risksData.map((risk: any) => (
                            <div
                                key={risk.id}
                                className={`p-4 rounded-lg border-2 ${getRiskColor(risk.severity)}`}
                            >
                                <div className="flex items-start justify-between mb-2">
                                    <div className="flex items-center gap-2">
                                        <span className={`px-3 py-1 rounded-full text-xs font-bold ${getRiskColor(risk.severity)}`}>
                                            {risk.severity}
                                        </span>
                                        <span className="text-sm font-semibold text-slate-700">
                                            {risk.type.replace(/_/g, ' ')}
                                        </span>
                                    </div>
                                    <span className="text-sm text-slate-600">
                                        {formatDate(risk.riskDate)}
                                    </span>
                                </div>

                                <div className="grid grid-cols-3 gap-4 mb-3">
                                    <div>
                                        <div className="text-xs text-slate-600 mb-1">Projected Cash</div>
                                        <div className="text-sm font-bold text-slate-900">
                                            {formatCurrency(risk.projectedCash)}
                                        </div>
                                    </div>
                                    <div>
                                        <div className="text-xs text-slate-600 mb-1">Required</div>
                                        <div className="text-sm font-bold text-slate-900">
                                            {formatCurrency(risk.requiredCash)}
                                        </div>
                                    </div>
                                    <div>
                                        <div className="text-xs text-slate-600 mb-1">Shortfall</div>
                                        <div className="text-sm font-bold text-red-600">
                                            {formatCurrency(risk.shortfall)}
                                        </div>
                                    </div>
                                </div>

                                {risk.recommendations && Array.isArray(risk.recommendations) && (
                                    <div className="mt-3 pt-3 border-t border-slate-200">
                                        <div className="text-xs font-bold text-slate-700 mb-2">Recommendations:</div>
                                        <div className="space-y-1">
                                            {risk.recommendations.slice(0, 2).map((rec: any, idx: number) => (
                                                <div key={idx} className="text-xs text-slate-600 flex items-start gap-2">
                                                    <Target size={12} className="mt-0.5 text-blue-600 flex-shrink-0" />
                                                    <span>{rec.description}</span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Forecast Summary */}
            {chartData.length > 0 && (
                <div className="grid grid-cols-3 gap-4">
                    <div className="bg-green-50 border-2 border-green-200 rounded-lg p-4">
                        <div className="flex items-center gap-2 mb-2">
                            <TrendingUp size={18} className="text-green-600" />
                            <span className="text-xs font-bold text-green-700 uppercase">Best Case</span>
                        </div>
                        <div className="text-2xl font-black text-green-900">
                            {formatCurrency(chartData[chartData.length - 1]?.bestCase || 0)}
                        </div>
                        <div className="text-xs text-green-600 mt-1">
                            End of {timeframe} months
                        </div>
                    </div>

                    <div className="bg-blue-50 border-2 border-blue-200 rounded-lg p-4">
                        <div className="flex items-center gap-2 mb-2">
                            <DollarSign size={18} className="text-blue-600" />
                            <span className="text-xs font-bold text-blue-700 uppercase">Most Likely</span>
                        </div>
                        <div className="text-2xl font-black text-blue-900">
                            {formatCurrency(chartData[chartData.length - 1]?.mostLikely || 0)}
                        </div>
                        <div className="text-xs text-blue-600 mt-1">
                            Confidence: {chartData[chartData.length - 1]?.confidence?.toFixed(0) || 0}%
                        </div>
                    </div>

                    <div className="bg-red-50 border-2 border-red-200 rounded-lg p-4">
                        <div className="flex items-center gap-2 mb-2">
                            <TrendingDown size={18} className="text-red-600" />
                            <span className="text-xs font-bold text-red-700 uppercase">Worst Case</span>
                        </div>
                        <div className="text-2xl font-black text-red-900">
                            {formatCurrency(chartData[chartData.length - 1]?.worstCase || 0)}
                        </div>
                        <div className="text-xs text-red-600 mt-1">
                            Risk scenario
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getCashFlowForecastAction } from '@/lib/actions/cashFlow';
import { TrendingUp, TrendingDown, AlertTriangle, DollarSign, Calendar } from 'lucide-react';

interface CashFlowForecastPanelProps {
    brandId: string;
}

export function CashFlowForecastPanel({ brandId }: CashFlowForecastPanelProps) {
    const [forecastPeriod, setForecastPeriod] = useState<30 | 60 | 90>(30);

    const { data: forecastData, isLoading } = useQuery({
        queryKey: ['cashflow-forecast', brandId, forecastPeriod],
        queryFn: () => getCashFlowForecastAction(brandId, forecastPeriod)
    });

    const forecast = (forecastData as any)?.data;
    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    if (isLoading) {
        return (
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                <div className="text-center text-slate-400">Loading cash flow forecast...</div>
            </div>
        );
    }

    if (!forecast) {
        return (
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                <div className="text-center text-slate-400">No forecast data available</div>
            </div>
        );
    }

    const criticalAlerts = forecast.alerts.filter((a: any) => a.severity === 'CRITICAL');
    const mediumAlerts = forecast.alerts.filter((a: any) => a.severity === 'MEDIUM');

    return (
        <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-6 border-b border-slate-100 bg-gradient-to-r from-cyan-50 to-blue-50">
                <div className="flex justify-between items-center">
                    <div>
                        <h3 className="font-black text-lg text-cyan-900">Cash Flow Forecast</h3>
                        <p className="text-sm text-cyan-700 mt-1">Projected liquidity for next {forecastPeriod} days</p>
                    </div>
                    <div className="flex gap-2">
                        <button
                            onClick={() => setForecastPeriod(30)}
                            className={`px-4 py-2 rounded-lg font-medium text-sm transition-colors ${forecastPeriod === 30
                                    ? 'bg-cyan-600 text-white'
                                    : 'bg-white text-cyan-700 border border-cyan-200 hover:bg-cyan-50'
                                }`}
                        >
                            30 Days
                        </button>
                        <button
                            onClick={() => setForecastPeriod(60)}
                            className={`px-4 py-2 rounded-lg font-medium text-sm transition-colors ${forecastPeriod === 60
                                    ? 'bg-cyan-600 text-white'
                                    : 'bg-white text-cyan-700 border border-cyan-200 hover:bg-cyan-50'
                                }`}
                        >
                            60 Days
                        </button>
                        <button
                            onClick={() => setForecastPeriod(90)}
                            className={`px-4 py-2 rounded-lg font-medium text-sm transition-colors ${forecastPeriod === 90
                                    ? 'bg-cyan-600 text-white'
                                    : 'bg-white text-cyan-700 border border-cyan-200 hover:bg-cyan-50'
                                }`}
                        >
                            90 Days
                        </button>
                    </div>
                </div>
            </div>

            <div className="p-6">
                {/* Summary Cards */}
                <div className="grid grid-cols-4 gap-4 mb-6">
                    <div className="text-center p-4 bg-blue-50 rounded-xl border border-blue-200">
                        <div className="text-xs font-bold text-blue-700 uppercase tracking-wider mb-1">Current Cash</div>
                        <div className="text-2xl font-black text-blue-900">{currency.format(forecast.currentCashBalance)}</div>
                    </div>
                    <div className="text-center p-4 bg-green-50 rounded-xl border border-green-200">
                        <div className="text-xs font-bold text-green-700 uppercase tracking-wider mb-1">Projected Inflows</div>
                        <div className="text-2xl font-black text-green-900 flex items-center justify-center gap-1">
                            <TrendingUp size={20} />
                            {currency.format(forecast.summary.totalProjectedInflows)}
                        </div>
                    </div>
                    <div className="text-center p-4 bg-red-50 rounded-xl border border-red-200">
                        <div className="text-xs font-bold text-red-700 uppercase tracking-wider mb-1">Projected Outflows</div>
                        <div className="text-2xl font-black text-red-900 flex items-center justify-center gap-1">
                            <TrendingDown size={20} />
                            {currency.format(forecast.summary.totalProjectedOutflows)}
                        </div>
                    </div>
                    <div className={`text-center p-4 rounded-xl border-2 ${forecast.summary.endingBalance > forecast.safetyThreshold
                            ? 'bg-emerald-50 border-emerald-300'
                            : forecast.summary.endingBalance > forecast.criticalThreshold
                                ? 'bg-amber-50 border-amber-300'
                                : 'bg-rose-50 border-rose-300'
                        }`}>
                        <div className={`text-xs font-bold uppercase tracking-wider mb-1 ${forecast.summary.endingBalance > forecast.safetyThreshold
                                ? 'text-emerald-700'
                                : forecast.summary.endingBalance > forecast.criticalThreshold
                                    ? 'text-amber-700'
                                    : 'text-rose-700'
                            }`}>
                            Ending Balance
                        </div>
                        <div className={`text-2xl font-black ${forecast.summary.endingBalance > forecast.safetyThreshold
                                ? 'text-emerald-900'
                                : forecast.summary.endingBalance > forecast.criticalThreshold
                                    ? 'text-amber-900'
                                    : 'text-rose-900'
                            }`}>
                            {currency.format(forecast.summary.endingBalance)}
                        </div>
                    </div>
                </div>

                {/* Liquidity Alerts */}
                {(criticalAlerts.length > 0 || mediumAlerts.length > 0) && (
                    <div className="mb-6">
                        <h4 className="font-bold text-sm text-slate-700 mb-3 uppercase tracking-wider flex items-center gap-2">
                            <AlertTriangle size={16} className="text-amber-600" />
                            Liquidity Alerts
                        </h4>
                        <div className="space-y-2">
                            {criticalAlerts.map((alert: any, idx: number) => (
                                <div key={idx} className="p-3 bg-red-50 border border-red-200 rounded-lg">
                                    <div className="flex items-start gap-2">
                                        <AlertTriangle size={18} className="text-red-600 mt-0.5" />
                                        <div className="flex-1">
                                            <div className="font-bold text-red-900 text-sm">{alert.message}</div>
                                            <div className="text-xs text-red-700 mt-1">{alert.recommendation}</div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                            {mediumAlerts.map((alert: any, idx: number) => (
                                <div key={idx} className="p-3 bg-amber-50 border border-amber-200 rounded-lg">
                                    <div className="flex items-start gap-2">
                                        <AlertTriangle size={18} className="text-amber-600 mt-0.5" />
                                        <div className="flex-1">
                                            <div className="font-bold text-amber-900 text-sm">{alert.message}</div>
                                            <div className="text-xs text-amber-700 mt-1">{alert.recommendation}</div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* Simple Chart Visualization */}
                <div>
                    <h4 className="font-bold text-sm text-slate-700 mb-3 uppercase tracking-wider">Cash Balance Trend</h4>
                    <div className="bg-slate-50 rounded-lg p-4 border border-slate-200">
                        <div className="space-y-2">
                            {forecast.projections.filter((_: any, idx: number) => idx % Math.ceil(forecast.projections.length / 10) === 0).map((projection: any, idx: number) => {
                                const maxBalance = Math.max(...forecast.projections.map((p: any) => p.cumulativeBalance));
                                const widthPercent = (projection.cumulativeBalance / maxBalance) * 100;

                                return (
                                    <div key={idx} className="flex items-center gap-3">
                                        <div className="text-xs text-slate-500 w-20">
                                            Day {Math.ceil((new Date(projection.date).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24))}
                                        </div>
                                        <div className="flex-1 bg-slate-200 rounded-full h-6 relative overflow-hidden">
                                            <div
                                                className={`h-full rounded-full transition-all ${projection.alertLevel === 'GREEN'
                                                        ? 'bg-gradient-to-r from-green-400 to-emerald-500'
                                                        : projection.alertLevel === 'AMBER'
                                                            ? 'bg-gradient-to-r from-amber-400 to-orange-500'
                                                            : 'bg-gradient-to-r from-red-400 to-rose-500'
                                                    }`}
                                                style={{ width: `${widthPercent}%` }}
                                            />
                                            <div className="absolute inset-0 flex items-center px-3">
                                                <span className="text-xs font-bold text-white drop-shadow">
                                                    {currency.format(projection.cumulativeBalance)}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>

                        {/* Legend */}
                        <div className="mt-4 pt-4 border-t border-slate-300 flex items-center justify-center gap-6 text-xs">
                            <div className="flex items-center gap-2">
                                <div className="w-4 h-4 rounded bg-gradient-to-r from-green-400 to-emerald-500" />
                                <span className="text-slate-600">Healthy ({currency.format(forecast.safetyThreshold)}+)</span>
                            </div>
                            <div className="flex items-center gap-2">
                                <div className="w-4 h-4 rounded bg-gradient-to-r from-amber-400 to-orange-500" />
                                <span className="text-slate-600">Caution</span>
                            </div>
                            <div className="flex items-center gap-2">
                                <div className="w-4 h-4 rounded bg-gradient-to-r from-red-400 to-rose-500" />
                                <span className="text-slate-600">Critical ({currency.format(forecast.criticalThreshold)}-)</span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import { Newspaper, Zap, AlertTriangle, CheckCircle2 } from 'lucide-react';
import { ExecutiveBriefing } from '@/lib/services/GlobalStrategyService';

interface Props {
    briefing: ExecutiveBriefing;
}

export const ChiefStrategyOfficer = ({ briefing }: Props) => {

