                                <div className="flex items-center gap-2 mb-4">
                                    <Zap size={20} className="text-amber-300 fill-amber-300 animate-pulse" />
                                    <h3 className="font-black uppercase tracking-widest text-sm text-indigo-100">Action of the Day</h3>
                                </div>
                                <p className="text-2xl font-bold leading-tight">
                                    {briefing.strategicAction}
                                </p>
                            </div>

                            <button className="mt-8 w-full py-3 bg-white text-indigo-900 font-bold rounded-lg hover:bg-indigo-50 transition-colors flex items-center justify-center gap-2">
                                Execute Strategy
                                <Zap size={16} />
                            </button>
                        </div>

                        {/* Background Effect */}
                        <div className="absolute top-0 right-0 -mt-10 -mr-10 w-40 h-40 bg-white/10 rounded-full blur-3xl group-hover:bg-white/20 transition-all duration-700" />
                    </div>
                </div>

            </div>
        </div>
    );
};

'use client';

import React from 'react';
import { useQuery } from '@tanstack/react-query';
import {
    getComplianceDashboardAction,
    getComplianceViolationsAction,
    resolveViolationAction,
    waiveViolationAction
} from '@/lib/actions/audit';
import {
    Shield, TrendingUp, TrendingDown, Minus,
    AlertCircle, CheckCircle, Clock, XCircle
} from 'lucide-react';

interface ComplianceDashboardProps {
    brandId?: string;
}

export function ComplianceDashboard({ brandId }: ComplianceDashboardProps) {
    const { data: dashboardData, isLoading, refetch } = useQuery({
        queryKey: ['compliance-dashboard', brandId],
        queryFn: async () => {
            const result = await getComplianceDashboardAction(brandId);
            return result.data;
        }
    });

    const { data: violationsData } = useQuery({
        queryKey: ['compliance-violations', brandId],
        queryFn: async () => {
            const result = await getComplianceViolationsAction({
                brandId,
                status: 'OPEN'
            });
            return result.data || [];
        }
    });

    const handleResolve = async (violationId: string) => {
        const resolution = prompt('Enter resolution notes:');
        if (resolution) {
            await resolveViolationAction(violationId, 'current-user-id', resolution);
            refetch();
        }
    };

    const handleWaive = async (violationId: string) => {
        const reason = prompt('Enter waiver reason:');
        if (reason) {
            await waiveViolationAction(violationId, 'current-user-id', reason);
            refetch();
        }
    };

    const getScoreColor = (score: number) => {
        if (score >= 90) return 'text-green-600';
        if (score >= 70) return 'text-yellow-600';
        return 'text-red-600';
    };

    const getScoreGradient = (score: number) => {
        if (score >= 90) return 'from-green-500 to-emerald-600';
        if (score >= 70) return 'from-yellow-500 to-orange-600';
        return 'from-red-500 to-rose-600';
    };

    const getTrendIcon = (trend: string) => {
        switch (trend) {
            case 'IMPROVING': return <TrendingUp className="text-green-500" size={20} />;
            case 'DECLINING': return <TrendingDown className="text-red-500" size={20} />;
            default: return <Minus className="text-slate-400" size={20} />;
        }
    };

    const getSeverityBadge = (severity: string) => {
        const colors = {
            CRITICAL: 'bg-red-100 text-red-700 border-red-300',
            HIGH: 'bg-orange-100 text-orange-700 border-orange-300',
            MEDIUM: 'bg-yellow-100 text-yellow-700 border-yellow-300',
            LOW: 'bg-blue-100 text-blue-700 border-blue-300'
        };
        return colors[severity as keyof typeof colors] || colors.LOW;
    };

    if (isLoading) {
        return (
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-12">
                <div className="text-center text-slate-400">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
                    Loading compliance data...
                </div>
            </div>
        );
    }

    if (!dashboardData) return null;

    return (
        <div className="space-y-6">
            {/* Header with Score */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-6 text-white">
                    <div className="flex items-center justify-between">
                        <div>
                            <h2 className="text-2xl font-black mb-1">Compliance Overview</h2>
                            <p className="text-indigo-100">Governance & Risk Management</p>
                        </div>
                        <Shield size={48} className="opacity-50" />
                    </div>
                </div>

                <div className="p-6">
                    <div className="grid grid-cols-2 gap-6">
                        {/* Compliance Score */}
                        <div className="text-center">
                            <div className="inline-flex items-center justify-center w-32 h-32 rounded-full bg-gradient-to-br from-slate-100 to-slate-200 mb-4 relative">
                                <div className={`absolute inset-2 rounded-full bg-gradient-to-br ${getScoreGradient(dashboardData.overallScore)} opacity-20`}></div>
                                <div className={`text-4xl font-black ${getScoreColor(dashboardData.overallScore)} relative z-10`}>
                                    {dashboardData.overallScore}
                                </div>
                            </div>
                            <div className="text-sm font-bold text-slate-700 uppercase tracking-wider">Compliance Score</div>
                            <div className="flex items-center justify-center gap-2 mt-2">
                                {getTrendIcon(dashboardData.trend)}
                                <span className="text-xs font-medium text-slate-600">
                                    {dashboardData.trend === 'IMPROVING' ? 'Improving' :
                                        dashboardData.trend === 'DECLINING' ? 'Declining' : 'Stable'}
                                </span>
                            </div>
                        </div>

                        {/* Statistics Grid */}
                        <div className="grid grid-cols-2 gap-4">
                            <div className="bg-blue-50 rounded-lg p-4 border border-blue-200">
                                <div className="text-xs font-bold text-blue-700 uppercase tracking-wider mb-1">Active Rules</div>
                                <div className="text-2xl font-black text-blue-900">{dashboardData.activeRules}</div>
                                <div className="text-xs text-blue-600 mt-1">of {dashboardData.totalRules} total</div>
                            </div>
                            <div className="bg-green-50 rounded-lg p-4 border border-green-200">
                                <div className="text-xs font-bold text-green-700 uppercase tracking-wider mb-1">Resolved</div>
                                <div className="text-2xl font-black text-green-900">
                                    {dashboardData.totalViolations - dashboardData.openViolations}
                                </div>
                                <div className="text-xs text-green-600 mt-1">violations</div>
                            </div>
                            <div className="bg-yellow-50 rounded-lg p-4 border border-yellow-200">
                                <div className="text-xs font-bold text-yellow-700 uppercase tracking-wider mb-1">Open Issues</div>
                                <div className="text-2xl font-black text-yellow-900">{dashboardData.openViolations}</div>
                                <div className="text-xs text-yellow-600 mt-1">pending</div>
                            </div>
                            <div className="bg-red-50 rounded-lg p-4 border border-red-200">
                                <div className="text-xs font-bold text-red-700 uppercase tracking-wider mb-1">Critical</div>
                                <div className="text-2xl font-black text-red-900">{dashboardData.criticalViolations}</div>
                                <div className="text-xs text-red-600 mt-1">urgent</div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Active Violations */}
            <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="p-4 border-b border-slate-200 bg-slate-50">
                    <h3 className="font-bold text-slate-900">Active Violations ({dashboardData.openViolations})</h3>
                </div>

                {violationsData && violationsData.length > 0 ? (
                    <div className="divide-y divide-slate-100">
                        {violationsData.map((violation: any) => (
                            <div key={violation.id} className="p-4 hover:bg-slate-50 transition-colors">
                                <div className="flex items-start gap-4">
                                    <div className="flex-shrink-0 mt-1">
                                        {violation.severity === 'CRITICAL' ? (
                                            <AlertCircle className="text-red-500" size={20} />
                                        ) : (
                                            <AlertCircle className="text-yellow-500" size={20} />
                                        )}
                                    </div>

                                    <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2 mb-2">
                                            <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-bold border ${getSeverityBadge(violation.severity)}`}>
                                                {violation.severity}
                                            </span>
                                            <span className="text-xs text-slate-500">
                                                {violation.rule.category.replace(/_/g, ' ')}
                                            </span>
                                        </div>

                                        <h4 className="font-bold text-slate-900 mb-1">{violation.rule.name}</h4>
                                        <p className="text-sm text-slate-600 mb-2">{violation.description}</p>

                                        <div className="flex items-center gap-4 text-xs text-slate-500">
                                            <div className="flex items-center gap-1">
                                                <Clock size={12} />
                                                {new Date(violation.createdAt).toLocaleDateString()}
                                            </div>
                                            {violation.brand && (
                                                <div>Brand: {violation.brand.name}</div>
                                            )}
                                            {violation.user && (
                                                <div>User: {violation.user.name}</div>
                                            )}
                                        </div>
                                    </div>

                                    <div className="flex gap-2">
                                        <button
                                            onClick={() => handleResolve(violation.id)}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors text-sm font-medium"
                                        >
                                            <CheckCircle size={14} />
                                            Resolve
                                        </button>
                                        <button
                                            onClick={() => handleWaive(violation.id)}
                                            className="flex items-center gap-1 px-3 py-1.5 bg-slate-600 text-white rounded-lg hover:bg-slate-700 transition-colors text-sm font-medium"
                                        >
                                            <XCircle size={14} />
                                            Waive
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="p-12 text-center text-slate-400">
                        <CheckCircle size={48} className="mx-auto mb-4 opacity-50 text-green-500" />
                        <p className="font-medium text-slate-600">No active violations</p>
                        <p className="text-sm mt-1">All compliance rules are being followed</p>
                    </div>
                )}
            </div>

            {/* Violations by Category */}
            {Object.keys(dashboardData.violationsByCategory).length > 0 && (
                <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                    <h3 className="font-bold text-slate-900 mb-4">Violations by Category</h3>
                    <div className="space-y-3">
                        {Object.entries(dashboardData.violationsByCategory).map(([category, count]) => (
                            <div key={category} className="flex items-center gap-3">
                                <div className="flex-1">
                                    <div className="flex items-center justify-between mb-1">
                                        <span className="text-sm font-medium text-slate-700">
                                            {category.replace(/_/g, ' ')}
                                        </span>
                                        <span className="text-sm font-bold text-slate-900">{count as number}</span>
                                    </div>
                                    <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                                        <div
                                            className="h-full bg-gradient-to-r from-indigo-500 to-purple-500"
                                            style={{ width: `${Math.min(100, ((count as number) / dashboardData.totalViolations) * 100)}%` }}
                                        ></div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
    generateConsolidatedStatementAction,
    getConsolidatedStatementAction,
    getAllStatementsAction
} from '@/lib/actions/financialStatements';
import { ConsolidationPeriod } from '@prisma/client';
import {
    FileText, Download, TrendingUp, DollarSign,
    Calendar, RefreshCw, CheckCircle, AlertCircle, Loader
} from 'lucide-react';

export function ConsolidatedStatementsHub() {
    const [fiscalYear, setFiscalYear] = useState(new Date().getFullYear());
    const [period, setPeriod] = useState<ConsolidationPeriod>('ANNUAL');
    const [activeTab, setActiveTab] = useState<'pl' | 'bs' | 'cf' | 'ic'>('pl');

    const queryClient = useQueryClient();

    // Get current statement
    const { data: statementData, isLoading } = useQuery({
        queryKey: ['consolidated-statement', fiscalYear, period],
        queryFn: async () => {
            const result = await getConsolidatedStatementAction(fiscalYear, period);
            return result.data;
        }
    });

    // Get all statements
    const { data: allStatements } = useQuery({
        queryKey: ['all-statements'],
        queryFn: async () => {
            const result = await getAllStatementsAction(10);
            return result.data || [];
        }
    });

    // Generate statement mutation
    const generateMutation = useMutation({
        mutationFn: async () => {
            return await generateConsolidatedStatementAction(
                fiscalYear,
                period,
                'current-user-id' // TODO: Get from auth
            );
        },
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['consolidated-statement'] });
            queryClient.invalidateQueries({ queryKey: ['all-statements'] });
        }
    });

    const handleGenerate = () => {
        if (confirm(`Generate consolidated statement for ${period} ${fiscalYear}?\n\nThis will replace any existing statement.`)) {
            generateMutation.mutate();
        }
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            maximumFractionDigits: 0
        }).format(amount);
    };

    const tabs = [
        { id: 'pl' as const, label: 'Profit & Loss', icon: DollarSign },
        { id: 'bs' as const, label: 'Balance Sheet', icon: TrendingUp },
        { id: 'cf' as const, label: 'Cash Flow', icon: RefreshCw },
        { id: 'ic' as const, label: 'IC Eliminations', icon: FileText }
    ];

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 delay-75">
            {/* Header & Controls */}
            <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden">
                <div className="p-8 border-b border-slate-100 bg-gradient-to-r from-slate-900 to-slate-800 text-white">
                    <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                        <div className="flex items-center gap-4">
                            <div className="p-3 bg-blue-500/20 rounded-2xl backdrop-blur-md border border-blue-500/30 text-blue-400">
                                <FileText size={24} />
                            </div>
                            <div>
                                <h2 className="text-2xl font-black tracking-tight">Consolidated Financial Statements</h2>
                                <p className="text-slate-400 font-medium">Group-wide performance analysis with automated IC elimination</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-3">
                            {statementData && (
                                <button className="flex items-center gap-2 px-5 py-2.5 bg-white/10 hover:bg-white/20 backdrop-blur-md border border-white/10 rounded-xl transition-all font-bold text-sm">
                                    <Download size={18} />
                                    Export PDF
                                </button>
                            )}
                            <button
                                onClick={handleGenerate}
                                disabled={generateMutation.isPending}
                                className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-xl transition-all font-bold text-sm shadow-lg shadow-blue-600/20 disabled:opacity-50"
                            >
                                {generateMutation.isPending ? (
                                    <>
                                        <Loader className="animate-spin" size={18} />
                                        Processing...
                                    </>
                                ) : (
                                    <>
                                        <RefreshCw size={18} />
                                        Generate Statement
                                    </>
                                )}
                            </button>
                        </div>
                    </div>
                </div>

                {/* Period Selector */}
                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2">
                        <Calendar size={18} className="text-slate-400" />
                        <select
                            value={fiscalYear}
                            onChange={(e) => setFiscalYear(Number(e.target.value))}
                            className="px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 font-medium"
                        >
                            {[2024, 2023, 2022, 2021].map(year => (
                                <option key={year} value={year}>{year}</option>
                            ))}
                        </select>
                    </div>

                    <select
                        value={period}
                        onChange={(e) => setPeriod(e.target.value as ConsolidationPeriod)}
                        className="px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 font-medium"
                    >
                        <option value="ANNUAL">Annual</option>
                        <option value="QUARTERLY">Quarterly</option>
                        <option value="MONTHLY">Monthly</option>
                        <option value="YTD">Year-to-Date</option>
                    </select>

                    {statementData && (
                        <div className="ml-auto flex items-center gap-2 text-sm text-slate-600">
                            <CheckCircle size={16} className="text-green-500" />
                            Generated {new Date(statementData.generatedAt).toLocaleString()}
                        </div>
                    )}
                </div>
            </div>

            {/* Statement Content */}
            {isLoading ? (
                <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-12 text-center">
                    <Loader className="animate-spin mx-auto mb-4 text-indigo-600" size={48} />
                    <p className="text-slate-600">Loading statement...</p>
                </div>
            ) : !statementData ? (
                <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-12 text-center">
                    <AlertCircle size={48} className="mx-auto mb-4 text-slate-400" />
                    <h3 className="text-lg font-bold text-slate-900 mb-2">No Statement Available</h3>
                    <p className="text-slate-600 mb-4">
                        Generate a consolidated statement for {period} {fiscalYear}
                    </p>
                    <button
                        onClick={handleGenerate}
                        className="px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-medium"
                    >
                        Generate Now
                    </button>
                </div>
            ) : (
                <>
                    {/* Tabs */}
                    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                        <div className="flex border-b border-slate-200">
                            {tabs.map((tab) => {
                                const Icon = tab.icon;
                                return (
                                    <button
                                        key={tab.id}
                                        onClick={() => setActiveTab(tab.id)}
                                        className={`flex-1 flex items-center justify-center gap-2 px-6 py-4 font-bold transition-all ${activeTab === tab.id
                                            ? 'bg-indigo-50 text-indigo-700 border-b-2 border-indigo-600'
                                            : 'text-slate-600 hover:bg-slate-50'
                                            }`}
                                    >
                                        <Icon size={20} />
                                        {tab.label}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="p-6">
                            {/* P&L Tab */}
                            {activeTab === 'pl' && (
                                <div className="space-y-6">
                                    <div className="text-center mb-6">
                                        <h3 className="text-xl font-black text-slate-900">ACHIERA HOLDING</h3>
                                        <h4 className="text-lg font-bold text-slate-700">Consolidated Statement of Profit & Loss</h4>
                                        <p className="text-sm text-slate-600">
                                            For the {period} ended {new Date(statementData.endDate).toLocaleDateString()}
                                        </p>
                                    </div>

                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center py-3 border-b border-slate-200">
                                            <span className="font-semibold text-slate-700">Revenue</span>
                                            <span className="font-bold text-slate-900">{formatCurrency(statementData.totalRevenue)}</span>
                                        </div>
                                        <div className="flex justify-between items-center py-3 border-b border-slate-200">
                                            <span className="font-semibold text-slate-700">Cost of Goods Sold</span>
                                            <span className="font-bold text-red-600">({formatCurrency(statementData.totalCOGS)})</span>
                                        </div>
                                        <div className="flex justify-between items-center py-3 border-b-2 border-slate-300 bg-slate-50 px-3 rounded">
                                            <span className="font-bold text-slate-900">Gross Profit</span>
                                            <span className="font-black text-slate-900">
                                                {formatCurrency(statementData.totalRevenue - statementData.totalCOGS)}
                                            </span>
                                        </div>
                                        <div className="flex justify-between items-center py-3 border-b border-slate-200">
                                            <span className="font-semibold text-slate-700">Operating Expenses</span>
                                            <span className="font-bold text-red-600">({formatCurrency(statementData.totalExpenses)})</span>
                                        </div>
                                        <div className="flex justify-between items-center py-4 border-b-2 border-indigo-300 bg-indigo-50 px-3 rounded">
                                            <span className="font-black text-indigo-900 text-lg">Net Profit</span>
                                            <span className="font-black text-indigo-900 text-lg">
                                                {formatCurrency(statementData.netProfit)}
                                            </span>
                                        </div>
                                    </div>

                                    <div className="mt-6 p-4 bg-amber-50 border border-amber-200 rounded-lg">
                                        <p className="text-sm text-amber-800">
                                            <strong>Note:</strong> IC Eliminations: {formatCurrency(statementData.icEliminationAmount)}
                                            ({statementData.icTransactionCount} transactions)
                                        </p>
                                    </div>
                                </div>
                            )}

                            {/* Balance Sheet Tab */}
                            {activeTab === 'bs' && (
                                <div className="space-y-6">
                                    <div className="text-center mb-6">
                                        <h3 className="text-xl font-black text-slate-900">ACHIERA HOLDING</h3>
                                        <h4 className="text-lg font-bold text-slate-700">Consolidated Balance Sheet</h4>
                                        <p className="text-sm text-slate-600">
                                            As of {new Date(statementData.endDate).toLocaleDateString()}
                                        </p>
                                    </div>

                                    <div className="grid grid-cols-2 gap-8">
                                        {/* Assets */}
                                        <div>
                                            <h5 className="font-bold text-slate-900 mb-4 text-lg border-b-2 border-slate-300 pb-2">ASSETS</h5>
                                            <div className="space-y-3">
                                                <div className="flex justify-between items-center py-3 border-b-2 border-slate-300 bg-slate-50 px-3 rounded">
                                                    <span className="font-black text-slate-900">Total Assets</span>
                                                    <span className="font-black text-slate-900">
                                                        {formatCurrency(statementData.totalAssets)}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Liabilities & Equity */}
                                        <div>
                                            <h5 className="font-bold text-slate-900 mb-4 text-lg border-b-2 border-slate-300 pb-2">LIABILITIES & EQUITY</h5>
                                            <div className="space-y-3">
                                                <div className="flex justify-between items-center py-3 border-b border-slate-200">
                                                    <span className="font-semibold text-slate-700">Total Liabilities</span>
                                                    <span className="font-bold text-slate-900">
                                                        {formatCurrency(statementData.totalLiabilities)}
                                                    </span>
                                                </div>
                                                <div className="flex justify-between items-center py-3 border-b border-slate-200">
                                                    <span className="font-semibold text-slate-700">Total Equity</span>
                                                    <span className="font-bold text-slate-900">
                                                        {formatCurrency(statementData.totalEquity)}
                                                    </span>
                                                </div>
                                                <div className="flex justify-between items-center py-3 border-b-2 border-indigo-300 bg-indigo-50 px-3 rounded">
                                                    <span className="font-black text-indigo-900">Total Liabilities & Equity</span>
                                                    <span className="font-black text-indigo-900">
                                                        {formatCurrency(statementData.totalLiabilities + statementData.totalEquity)}
                                                    </span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {/* Cash Flow Tab */}
                            {activeTab === 'cf' && (
                                <div className="space-y-6">
                                    <div className="text-center mb-6">
                                        <h3 className="text-xl font-black text-slate-900">ACHIERA HOLDING</h3>
                                        <h4 className="text-lg font-bold text-slate-700">Consolidated Cash Flow Statement</h4>
                                        <p className="text-sm text-slate-600">
                                            For the {period} ended {new Date(statementData.endDate).toLocaleDateString()}
                                        </p>
                                    </div>

                                    <div className="space-y-3">
                                        <div className="flex justify-between items-center py-3 border-b border-slate-200">
                                            <span className="font-semibold text-slate-700">Operating Cash Flow</span>
                                            <span className="font-bold text-slate-900">{formatCurrency(statementData.operatingCashFlow)}</span>
                                        </div>
                                        <div className="flex justify-between items-center py-3 border-b border-slate-200">
                                            <span className="font-semibold text-slate-700">Investing Cash Flow</span>
                                            <span className="font-bold text-slate-900">{formatCurrency(statementData.investingCashFlow)}</span>
                                        </div>
                                        <div className="flex justify-between items-center py-3 border-b border-slate-200">
                                            <span className="font-semibold text-slate-700">Financing Cash Flow</span>
                                            <span className="font-bold text-slate-900">{formatCurrency(statementData.financingCashFlow)}</span>
                                        </div>
                                        <div className="flex justify-between items-center py-4 border-b-2 border-indigo-300 bg-indigo-50 px-3 rounded">
                                            <span className="font-black text-indigo-900 text-lg">Net Cash Flow</span>
                                            <span className="font-black text-indigo-900 text-lg">
                                                {formatCurrency(
                                                    statementData.operatingCashFlow +
                                                    statementData.investingCashFlow +
                                                    statementData.financingCashFlow
                                                )}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {/* IC Eliminations Tab */}
                            {activeTab === 'ic' && (
                                <div className="space-y-6">
                                    <div className="text-center mb-6">
                                        <h3 className="text-xl font-black text-slate-900">Inter-Company Eliminations</h3>
                                        <p className="text-sm text-slate-600">Transactions eliminated from consolidation</p>
                                    </div>

                                    <div className="grid grid-cols-3 gap-4 mb-6">
                                        <div className="bg-blue-50 rounded-lg p-4 border border-blue-200">
                                            <div className="text-xs font-bold text-blue-700 uppercase tracking-wider mb-1">Total Eliminated</div>
                                            <div className="text-2xl font-black text-blue-900">
                                                {formatCurrency(statementData.icEliminationAmount)}
                                            </div>
                                        </div>
                                        <div className="bg-green-50 rounded-lg p-4 border border-green-200">
                                            <div className="text-xs font-bold text-green-700 uppercase tracking-wider mb-1">Transactions</div>
                                            <div className="text-2xl font-black text-green-900">
                                                {statementData.icTransactionCount}
                                            </div>
                                        </div>
                                        <div className="bg-purple-50 rounded-lg p-4 border border-purple-200">
                                            <div className="text-xs font-bold text-purple-700 uppercase tracking-wider mb-1">Impact on Revenue</div>
                                            <div className="text-2xl font-black text-purple-900">
                                                {((statementData.icEliminationAmount / statementData.totalRevenue) * 100).toFixed(1)}%
                                            </div>
                                        </div>
                                    </div>

                                    {statementData.icEliminations && Array.isArray(statementData.icEliminations) && (
                                        <div className="space-y-2">
                                            <h5 className="font-bold text-slate-900 mb-3">Elimination Details</h5>
                                            {statementData.icEliminations.map((elim: any, idx: number) => (
                                                <div key={idx} className="p-4 bg-slate-50 rounded-lg border border-slate-200">
                                                    <div className="flex items-center justify-between">
                                                        <div>
                                                            <span className="font-semibold text-slate-900">{elim.type}</span>
                                                            <p className="text-sm text-slate-600 mt-1">{elim.description}</p>
                                                        </div>
                                                        <span className="font-bold text-slate-900">{formatCurrency(elim.amount)}</span>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>
                </>
            )}

            {/* Recent Statements */}
            {allStatements && allStatements.length > 0 && (
                <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                    <h3 className="font-bold text-slate-900 mb-4">Recent Statements</h3>
                    <div className="space-y-2">
                        {allStatements.slice(0, 5).map((stmt: any) => (
                            <button
                                key={stmt.id}
                                onClick={() => {
                                    setFiscalYear(stmt.fiscalYear);
                                    setPeriod(stmt.period);
                                }}
                                className="w-full flex items-center justify-between p-3 hover:bg-slate-50 rounded-lg transition-colors text-left"
                            >
                                <div>
                                    <span className="font-semibold text-slate-900">
                                        {stmt.period} {stmt.fiscalYear}
                                    </span>
                                    <p className="text-xs text-slate-500 mt-1">
                                        Generated {new Date(stmt.generatedAt).toLocaleDateString()}
                                    </p>
                                </div>
                                <div className="text-right">
                                    <div className="font-bold text-slate-900">{formatCurrency(Number(stmt.netProfit))}</div>
                                    <div className="text-xs text-slate-500">Net Profit</div>
                                </div>
                            </button>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
    getPendingICTransactionsAction,
    getICBalancesAction,
    approveICTransactionAction,
    rejectICTransactionAction,
    getICTransactionHistoryAction
} from '@/lib/actions/interCompany';
import { Check, X, ArrowRight, TrendingUp, TrendingDown } from 'lucide-react';

export function InterCompanyHub() {
    const queryClient = useQueryClient();
    const [selectedTab, setSelectedTab] = useState<'pending' | 'balances' | 'history'>('pending');

    // Fetch pending transactions
    const { data: pendingData, isLoading: loadingPending } = useQuery({
        queryKey: ['ic-pending'],
        queryFn: () => getPendingICTransactionsAction()
    });

    // Fetch IC balances
    const { data: balancesData, isLoading: loadingBalances } = useQuery({
        queryKey: ['ic-balances'],
        queryFn: () => getICBalancesAction()
    });

    // Fetch transaction history
    const { data: historyData, isLoading: loadingHistory } = useQuery({
        queryKey: ['ic-history'],
        queryFn: () => getICTransactionHistoryAction()
    });

    // Approve mutation
    const approveMutation = useMutation({
        mutationFn: ({ id, approvedBy }: { id: string; approvedBy: string }) =>
            approveICTransactionAction(id, approvedBy),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['ic-pending'] });
            queryClient.invalidateQueries({ queryKey: ['ic-balances'] });
            queryClient.invalidateQueries({ queryKey: ['ic-history'] });
        }
    });

    // Reject mutation
    const rejectMutation = useMutation({
        mutationFn: (id: string) => rejectICTransactionAction(id),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['ic-pending'] });
            queryClient.invalidateQueries({ queryKey: ['ic-history'] });
        }
    });

    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    const pendingTransactions = (pendingData as any)?.data || [];
    const balances = (balancesData as any)?.data || [];
    const history = (historyData as any)?.data || [];

    return (
        <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-700 delay-150">
            <div className="p-8 border-b border-slate-100 bg-gradient-to-r from-slate-900 to-slate-800 text-white">
                <div className="flex items-center gap-4">
                    <div className="p-3 bg-indigo-500/20 rounded-2xl backdrop-blur-md border border-indigo-500/30 text-indigo-400">
                        <ArrowRight size={24} />
                    </div>
                    <div>
                        <h3 className="font-black text-2xl tracking-tight">Inter-Company Transaction Center</h3>
                        <p className="text-slate-400 font-medium">Coordinate financial flows and balances across brands</p>
                    </div>
                </div>
            </div>

            {/* Tabs */}
            <div className="bg-slate-50/50 p-2 border-b border-slate-200">
                <div className="flex bg-white/50 p-1.5 rounded-2xl border border-slate-200 w-fit mx-auto sm:mx-0">
                    <button
                        onClick={() => setSelectedTab('pending')}
                        className={`px-6 py-2.5 font-bold text-sm rounded-xl transition-all ${selectedTab === 'pending'
                            ? 'bg-slate-900 text-white shadow-lg shadow-slate-900/20'
                            : 'text-slate-500 hover:text-slate-900 hover:bg-slate-100'
                            }`}
                    >
                        Pending Approvals ({pendingTransactions.length})
                    </button>
                    <button
                        onClick={() => setSelectedTab('balances')}
                        className={`px-6 py-2.5 font-bold text-sm rounded-xl transition-all ${selectedTab === 'balances'
                            ? 'bg-slate-900 text-white shadow-lg shadow-slate-900/20'
                            : 'text-slate-500 hover:text-slate-900 hover:bg-slate-100'
                            }`}
                    >
                        IC Balances
                    </button>
                    <button
                        onClick={() => setSelectedTab('history')}
                        className={`px-6 py-2.5 font-bold text-sm rounded-xl transition-all ${selectedTab === 'history'
                            ? 'bg-slate-900 text-white shadow-lg shadow-slate-900/20'
                            : 'text-slate-500 hover:text-slate-900 hover:bg-slate-100'
                            }`}
                    >
                        History
                    </button>
                </div>
            </div>

            <div className="p-6">
                {/* Pending Approvals Tab */}
                {selectedTab === 'pending' && (
                    <div className="space-y-4">
                        {loadingPending ? (
                            <div className="text-center py-8 text-slate-400">Loading...</div>
                        ) : pendingTransactions.length === 0 ? (
                            <div className="text-center py-12">
                                <div className="bg-green-100 rounded-full w-16 h-16 flex items-center justify-center mx-auto mb-4">
                                    <Check size={32} className="text-green-600" />
                                </div>
                                <h4 className="font-medium text-slate-900">All Clear</h4>
                                <p className="text-sm text-slate-500 mt-1">No pending IC transactions</p>
                            </div>
                        ) : (
                            pendingTransactions.map((tx: any) => (
                                <div key={tx.id} className="border border-slate-200 rounded-lg p-4 hover:border-purple-300 transition-colors">
                                    <div className="flex justify-between items-start mb-3">
                                        <div>
                                            <div className="flex items-center gap-2 mb-1">
                                                <span className="font-bold text-slate-900">{tx.fromBrand.name}</span>
                                                <ArrowRight size={16} className="text-slate-400" />
                                                <span className="font-bold text-slate-900">{tx.toBrand.name}</span>
                                            </div>
                                            <span className="inline-block px-2 py-0.5 bg-purple-100 text-purple-700 text-xs font-medium rounded">
                                                {tx.type.replace('_', ' ')}
                                            </span>
                                        </div>
                                        <div className="text-right">
                                            <div className="text-xl font-black text-slate-900">{currency.format(Number(tx.amount))}</div>
                                            <div className="text-xs text-slate-400">{new Date(tx.createdAt).toLocaleDateString()}</div>
                                        </div>
                                    </div>
                                    <p className="text-sm text-slate-600 mb-3">{tx.description}</p>
                                    {tx.referenceNo && (
                                        <p className="text-xs text-slate-400 mb-3">Ref: {tx.referenceNo}</p>
                                    )}
                                    <div className="flex gap-2">
                                        <button
                                            onClick={() => approveMutation.mutate({ id: tx.id, approvedBy: 'OWNER' })}
                                            disabled={approveMutation.isPending}
                                            className="flex-1 px-4 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg font-medium text-sm transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                                        >
                                            <Check size={16} />
                                            Approve
                                        </button>
                                        <button
                                            onClick={() => rejectMutation.mutate(tx.id)}
                                            disabled={rejectMutation.isPending}
                                            className="flex-1 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg font-medium text-sm transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                                        >
                                            <X size={16} />
                                            Reject
                                        </button>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                )}

                {/* IC Balances Tab */}
                {selectedTab === 'balances' && (
                    <div className="space-y-6">
                        {loadingBalances ? (
                            <div className="text-center py-8 text-slate-400">Loading...</div>
                        ) : balances.length === 0 ? (
                            <div className="text-center py-12 text-slate-400">No IC balances found</div>
                        ) : (
                            balances.map((balance: any) => (
                                <div key={balance.brandId} className="border border-slate-200 rounded-lg p-4">
                                    <div className="flex justify-between items-center mb-4">
                                        <h4 className="font-bold text-slate-900">{balance.brandName}</h4>
                                        <div className="text-right">
                                            <div className="text-xs text-slate-500 uppercase tracking-wider mb-1">Net Position</div>
                                            <div className={`text-xl font-black ${balance.netPosition >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                                                {balance.netPosition >= 0 ? (
                                                    <span className="flex items-center gap-1">
                                                        <TrendingUp size={20} />
                                                        {currency.format(balance.netPosition)}
                                                    </span>
                                                ) : (
                                                    <span className="flex items-center gap-1">
                                                        <TrendingDown size={20} />
                                                        {currency.format(Math.abs(balance.netPosition))}
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        {balance.details.map((detail: any) => (
                                            <div key={detail.counterpartyBrandId} className="flex justify-between items-center p-2 bg-slate-50 rounded text-sm">
                                                <span className="text-slate-700">{detail.counterpartyName}</span>
                                                <div className="flex gap-4 text-xs">
                                                    <span className="text-green-600">Receivable: {currency.format(detail.receivable)}</span>
                                                    <span className="text-red-600">Payable: {currency.format(detail.payable)}</span>
                                                    <span className={`font-bold ${detail.net >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                                                        Net: {currency.format(Math.abs(detail.net))}
                                                    </span>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                )}

                {/* Transaction History Tab */}
                {selectedTab === 'history' && (
                    <div className="space-y-2">
                        {loadingHistory ? (
                            <div className="text-center py-8 text-slate-400">Loading...</div>
                        ) : history.length === 0 ? (
                            <div className="text-center py-12 text-slate-400">No transaction history</div>
                        ) : (
                            <table className="w-full text-sm">
                                <thead className="bg-slate-50 text-slate-500 font-medium">
                                    <tr>
                                        <th className="px-4 py-3 text-left">Date</th>
                                        <th className="px-4 py-3 text-left">From</th>
                                        <th className="px-4 py-3 text-left">To</th>
                                        <th className="px-4 py-3 text-left">Type</th>
                                        <th className="px-4 py-3 text-right">Amount</th>
                                        <th className="px-4 py-3 text-center">Status</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {history.map((tx: any) => (
                                        <tr key={tx.id} className="hover:bg-slate-50">
                                            <td className="px-4 py-3 text-slate-600">{new Date(tx.createdAt).toLocaleDateString()}</td>
                                            <td className="px-4 py-3 font-medium">{tx.fromBrand.name}</td>
                                            <td className="px-4 py-3 font-medium">{tx.toBrand.name}</td>
                                            <td className="px-4 py-3 text-slate-600">{tx.type.replace('_', ' ')}</td>
                                            <td className="px-4 py-3 text-right font-bold">{currency.format(Number(tx.amount))}</td>
                                            <td className="px-4 py-3 text-center">
                                                <span className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${tx.status === 'APPROVED' ? 'bg-green-100 text-green-700' :
                                                    tx.status === 'REJECTED' ? 'bg-red-100 text-red-700' :
                                                        'bg-amber-100 text-amber-700'
                                                    }`}>
                                                    {tx.status}
                                                </span>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { ShoppingBag, TrendingUp, ArrowRight, Loader2 } from 'lucide-react';
import { ProcurementSynergyService, SynergyOpportunity } from '@/lib/services/ProcurementSynergyService';
// Note: We need a server action or API route to call service from client. 
// For simplicity in this demo, we assume data is passed as prop or fetched via server action.
