'use client';

import React, { useEffect, useState } from 'react';
import { QRCodeSVG } from 'qrcode.react';

interface ReceiptItem {
    name: string;
    quantity: number;
    price: number;
}

interface DigitalReceiptProps {
    order: any;
    onClose: () => void;
}

export default function DigitalReceipt({ order, onClose }: DigitalReceiptProps) {
    if (!order) return null;

    const items = order.orderItems || [];
    const subtotal = Number(order.totalAmount || order.total || 0);
    const dateStr = new Date(order.createdAt).toLocaleString('id-ID', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 print:p-0 print:static print:bg-white">
            {/* Control Panel (Hidden on Print) */}
            <div className="absolute top-8 right-8 flex gap-4 print:hidden">
                <button
                    onClick={() => window.print()}
                    className="px-6 py-3 bg-emerald-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl hover:bg-emerald-700 transition-all active:scale-95"
                >
                    Print Nota
                </button>
                <button
                    onClick={onClose}
                    className="px-6 py-3 bg-white text-slate-400 rounded-2xl font-black uppercase tracking-widest text-xs border border-slate-200 shadow-xl hover:bg-slate-50 transition-all active:scale-95"
                >
                    Tutup
                </button>
            </div>

            {/* Receipt Paper */}
            <div className="bg-white w-full max-w-[400px] p-8 shadow-2xl print:shadow-none print:max-w-none print:w-[80mm] print:mx-auto font-mono text-slate-800 animate-in fade-in zoom-in duration-300">

                {/* Brand Header */}
                <div className="text-center space-y-2 mb-8">
                    <h1 className="text-2xl font-black text-emerald-900 tracking-tighter">RASA IBU</h1>
                    <p className="text-[10px] uppercase font-bold tracking-widest text-slate-400">Masakan Rumah & Frozen Food</p>
                    <div className="h-0.5 w-12 bg-emerald-100 mx-auto rounded-full"></div>
                </div>

                {/* Metadata */}
                <div className="space-y-1 text-[10px] mb-6 border-b border-dashed border-slate-200 pb-4">
                    <div className="flex justify-between">
                        <span>NO. NOTA</span>
                        <span className="font-bold">{order.invoiceNo || order.id.slice(-8).toUpperCase()}</span>
                    </div>
                    <div className="flex justify-between">
                        <span>TANGGAL</span>
                        <span className="font-bold">{dateStr}</span>
                    </div>
                    <div className="flex justify-between">
                        <span>PELANGGAN</span>
                        <span className="font-bold">{order.customerName}</span>
                    </div>
                    <div className="flex justify-between">
                        <span>SUMBER</span>
                        <span className="font-bold uppercase tracking-wider">{order.channel || 'OFFLINE'}</span>
                    </div>
                    {(() => {
                        const deliveryMatch = order.customerNote?.match(/^\[(.*?)\]/);
                        const deliveryInfo = deliveryMatch ? deliveryMatch[1] : null;
                        if (deliveryInfo) {
                            const [method, courier] = deliveryInfo.split(' - ');
                            return (
                                <>
                                    <div className="flex justify-between">
                                        <span>PENGIRIMAN</span>
                                        <span className="font-bold uppercase">{method}</span>
                                    </div>
                                    {courier && (
                                        <div className="flex justify-between">
                                            <span>KURIR</span>
                                            <span className="font-bold uppercase">{courier}</span>
                                        </div>
                                    )}
                                </>
                            );
                        }
                        return null;
                    })()}
                    {order.customerAddress && (
                        <div className="pt-2 border-t border-dashed border-slate-100">
                            <span className="text-[9px] text-slate-400">ALAMAT PENGIRIMAN:</span>
                            <p className="text-[10px] font-bold mt-1 leading-relaxed">{order.customerAddress}</p>
                        </div>
                    )}
                </div>

                {/* Items */}
                <div className="space-y-4 mb-6">
                    <div className="flex justify-between text-[10px] font-black border-b border-slate-100 pb-2">
                        <span>PESANAN</span>
                        <span>SUBTOT</span>
                    </div>
                    {items.map((item: any, idx: number) => (
                        <div key={idx} className="space-y-1">
                            <div className="flex justify-between text-[11px] font-bold">
                                <span className="uppercase">{item.frozenVariant?.product?.name || 'Produk'}</span>
                                <span>Rp {(item.quantity * Number(item.price || item.frozenVariant?.price || 0)).toLocaleString('id-ID')}</span>
                            </div>
                            <div className="text-[9px] text-slate-400">
                                {item.quantity} x @Rp {Number(item.price || item.frozenVariant?.price || 0).toLocaleString('id-ID')}
                            </div>
                        </div>
                    ))}
                    {items.length === 0 && (
                        <div className="text-[11px] font-bold flex justify-between">
                            <span className="uppercase">Pesanan Manual</span>
                            <span>Rp {subtotal.toLocaleString('id-ID')}</span>
                        </div>
                    )}
                </div>

                {/* Totals */}
                <div className="border-t-2 border-slate-900 pt-4 space-y-2 mb-8">
                    <div className="flex justify-between text-base font-black">
                        <span>TOTAL</span>
                        <span>Rp {subtotal.toLocaleString('id-ID')}</span>
                    </div>
                    <div className="text-[9px] text-center text-slate-400 italic">
                        Harga sudah termasuk pajak & biaya layanan.
                    </div>
                </div>

                {/* Footer QR */}
                <div className="flex flex-col items-center gap-4">
                    <div className="p-2 border border-slate-100 rounded-xl">
                        <QRCodeSVG
                            value={order.id}
                            size={80}
                            className="grayscale"
                        />
                    </div>
                    <div className="text-center space-y-1">
                        <p className="text-[10px] font-black uppercase tracking-widest text-emerald-900">Terima Kasih!</p>
                        <p className="text-[8px] text-slate-400 font-medium">Barang yang sudah dibeli tidak dapat ditukar.</p>
                        <p className="text-[8px] text-slate-400 font-medium italic">achiera.com • digital-receipt-v1</p>
                    </div>
                </div>

            </div>

            {/* Print Injected Styles */}
            <style jsx global>{`
                @media print {
                    body * {
                        visibility: hidden;
                    }
                    #receipt-content, #receipt-content * {
                        visibility: visible;
                    }
                    #receipt-content {
                        position: absolute;
                        left: 0;
                        top: 0;
                        width: 80mm;
                    }
                }
            `}</style>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { X, Receipt, Loader2, Camera, UploadCloud, ChevronRight, CheckCircle2 } from 'lucide-react';
import { recordExpenseAction, getLedgerAccountsAction } from '@/lib/actions/rasa-ibu/finance';
import { scanReceiptAction } from '@/lib/actions/rasa-ibu/finance/receipt-scanning';
import { toast } from 'sonner';

interface ExpenseEntryModalProps {
    brandId: string;
    onClose: () => void;
}

const EXPENSE_TYPES = [
    { value: 'SALARY', label: 'Gaji & Upah', icon: '👥' },
    { value: 'RENT', label: 'Sewa Tempat', icon: '🏠' },
    { value: 'UTILITIES', label: 'Listrik & Air', icon: '⚡' },
    { value: 'MARKETING', label: 'Iklan & Promo', icon: '📣' },
    { value: 'ADMIN', label: 'Admin & Kantor', icon: '📁' },
    { value: 'OTHER', label: 'Lain-lain', icon: '📦' },
];

export default function ExpenseEntryModal({ brandId, onClose }: ExpenseEntryModalProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [amount, setAmount] = useState('');
    const [expenseAccountCode, setExpenseAccountCode] = useState('');
    const [description, setDescription] = useState('');
    const [sourceAccountId, setSourceAccountId] = useState('');
    const [assetAccounts, setAssetAccounts] = useState<any[]>([]);
    const [expenseAccounts, setExpenseAccounts] = useState<any[]>([]);
    const [error, setError] = useState<string | null>(null);

    // Scanning State
    const [mode, setMode] = useState<'MANUAL' | 'SCAN'>('MANUAL');
    const [scanFile, setScanFile] = useState<File | null>(null);
    const [isScanning, setIsScanning] = useState(false);
    const [scanPreview, setScanPreview] = useState<string | null>(null);
    const [scanResult, setScanResult] = useState<any>(null);

    useEffect(() => {
        async function load() {
            const res = await getLedgerAccountsAction(brandId);
            if (res.success) {
                const assets = res.data.filter((a: any) => a.type === 'ASSET');
                // Allow EXPENSE (Cost) and LIABILITY (Debt Repayment)
                const expenses = res.data.filter((a: any) => a.type === 'EXPENSE' || a.type === 'LIABILITY');

                setAssetAccounts(assets);
                setExpenseAccounts(expenses);

                if (assets.length > 0) setSourceAccountId(assets[0].code);
                if (expenses.length > 0) setExpenseAccountCode(expenses[0].code);
            }
        }
        load();
    }, [brandId]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        if (!amount || Number(amount) <= 0) {
            setError('Jumlah nominal harus valid');
            return;
        }

        if (!expenseAccountCode) {
            setError('Silakan pilih kategori biaya');
            return;
        }

        setIsLoading(true);
        try {
            const res = await recordExpenseAction({
                brandId,
                amount: Number(amount),
                expenseAccountCode,
                description: description || `Biaya ${expenseAccountCode}`,
                date: new Date(),
                sourceAccountId
            });

            if (res.success) {
                onClose();
            } else {
                setError(res.error || 'Gagal menyimpan biaya');
            }
        } catch (err: any) {
            setError(err.message);
        } finally {
            setIsLoading(false);
        }
    };

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            setScanFile(file);
            const reader = new FileReader();
            reader.onload = (ev) => setScanPreview(ev.target?.result as string);
            reader.readAsDataURL(file);
        }
    };

    const handleScanUpload = async () => {
        if (!scanFile) return;
        setIsScanning(true);
        setError(null);

        try {
            const formData = new FormData();
            formData.append('file', scanFile);

            const res = await scanReceiptAction(formData);
            if (res.success) {
                setScanResult(res.data);
                toast.success('Struk berhasil dipindai!');
            } else {
                setError(res.error || 'Gagal memindai struk');
            }
        } catch (err) {
            setError('Terjadi kesalahan sistem');
        } finally {
            setIsScanning(false);
        }
    };

    const applyScanResult = () => {
        if (!scanResult) return;

        if (scanResult.totalAmount) setAmount(scanResult.totalAmount.toString());

        const itemsSummary = scanResult.items?.map((i: any) => `${i.name} (${i.qty})`).join(', ');
        setDescription(`[SCAN] ${scanResult.merchant || 'Merchant'} - ${itemsSummary || 'Items'}`);

        setMode('MANUAL');
    };

    const updateScanResult = (field: string, value: any) => {
        setScanResult((prev: any) => ({
            ...prev,
            [field]: value
        }));
    };

    const updateScanItem = (idx: number, field: string, value: any) => {
        setScanResult((prev: any) => {
            const newItems = [...(prev.items || [])];
            newItems[idx] = { ...newItems[idx], [field]: value };
            return { ...prev, items: newItems };
        });
    };

    return (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-[#1A241A]/60 backdrop-blur-md p-6">
            <div className="bg-[#FDFBF7] w-full max-w-xl max-h-[85vh] md:max-h-[90vh] flex flex-col rounded-[2rem] md:rounded-[3rem] shadow-2xl border border-[#E5E1D8] overflow-hidden animate-in fade-in zoom-in duration-500">
                {/* Header */}
                <div className="px-10 py-8 border-b border-[#E5E1D8] flex justify-between items-center bg-white sticky top-0 z-10">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-rose-50 rounded-2xl">
                            <Receipt className="w-6 h-6 text-rose-600" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-[#2D3A2D]">Catat Beban</h2>
                            <p className="text-[10px] font-bold text-[#8B7E66] uppercase tracking-widest">Input Pengeluaran Operasional</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        type="button"
                        className="p-3 hover:bg-rose-50 rounded-full transition-colors group border border-transparent hover:border-rose-100"
                    >
                        <X className="w-6 h-6 text-slate-400 group-hover:text-rose-500 transition-colors" />
                    </button>
                </div>

                {/* Mode Toggler */}
                <div className="px-10 py-4 bg-gray-50 border-b border-[#E5E1D8] flex gap-2">
                    <button
                        onClick={() => setMode('MANUAL')}
                        className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${mode === 'MANUAL' ? 'bg-[#2D3A2D] text-white shadow-lg' : 'text-[#8B7E66] hover:bg-white'}`}
                    >
                        Input Manual
                    </button>
                    <button
                        onClick={() => setMode('SCAN')}
                        className={`px-4 py-2 rounded-xl text-xs font-bold transition-all flex items-center gap-2 ${mode === 'SCAN' ? 'bg-[#2D3A2D] text-white shadow-lg' : 'text-[#8B7E66] hover:bg-white'}`}
                    >
                        <Camera className="w-3.5 h-3.5" />
                        Scan Struk (AI)
                    </button>
                </div>

                {mode === 'SCAN' ? (
                    <div className="p-10 space-y-8 overflow-y-auto custom-scrollbar h-full">
                        {!scanResult ? (
                            <div className="flex flex-col items-center justify-center space-y-6 h-full">
                                <div className="w-full max-w-sm border-3 border-dashed border-[#E5E1D8] rounded-[2rem] p-8 text-center bg-white hover:bg-[#faf9f6] transition-colors relative group">
                                    <input
                                        type="file"
                                        accept="image/*"
                                        onChange={handleFileSelect}
                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                    />
                                    {scanPreview ? (
                                        <div className="relative rounded-xl overflow-hidden shadow-lg">
                                            <img src={scanPreview} alt="Preview" className="w-full h-auto object-cover max-h-64" />
                                            <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                                <p className="text-white font-bold text-sm">Ganti Foto</p>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="py-12 flex flex-col items-center gap-4">
                                            <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center text-rose-300">
                                                <Camera className="w-8 h-8" />
                                            </div>
                                            <div>
                                                <p className="text-sm font-black text-[#2D3A2D]">Ambil / Upload Foto Struk</p>
                                                <p className="text-xs text-[#8B7E66] mt-1">Kami akan membaca detailnya otomatis</p>
                                            </div>
                                        </div>
                                    )}
                                </div>

                                {scanFile && (
                                    <button
                                        onClick={handleScanUpload}
                                        disabled={isScanning}
                                        className="px-8 py-4 bg-rose-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-rose-700 hover:-translate-y-1 transition-all shadow-xl shadow-rose-200 disabled:opacity-50 disabled:translate-y-0"
                                    >
                                        {isScanning ? (
                                            <div className="flex items-center gap-2">
                                                <Loader2 className="w-4 h-4 animate-spin" />
                                                Menganalisis Struk...
                                            </div>
                                        ) : (
                                            <div className="flex items-center gap-2">
                                                <UploadCloud className="w-4 h-4" />
                                                Proses dengan AI
                                            </div>
                                        )}
                                    </button>
                                )}

                                {error && <p className="text-rose-600 text-xs font-bold bg-rose-50 px-4 py-2 rounded-lg">{error}</p>}
                            </div>
                        ) : (
                            <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
                                <div className="bg-emerald-50 border border-emerald-100 p-6 rounded-[2rem] flex items-start gap-4">
                                    <div className="p-3 bg-emerald-100 text-emerald-600 rounded-xl">
                                        <CheckCircle2 className="w-6 h-6" />
                                    </div>
                                    <div className="space-y-1">
                                        <h3 className="text-sm font-black text-emerald-800">Analisis Berhasil!</h3>
                                        <p className="text-xs text-emerald-600 leading-relaxed">AI menemukan data transaksi. Silakan review sebelum dimasukkan ke form.</p>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="bg-white p-6 rounded-[1.5rem] border border-[#E5E1D8] shadow-sm space-y-2">
                                        <p className="text-[10px] font-black text-[#8B7E66] uppercase tracking-wider">Merchant / Toko</p>
                                        <input
                                            type="text"
                                            value={scanResult.merchant || ''}
                                            onChange={(e) => updateScanResult('merchant', e.target.value)}
                                            className="w-full bg-transparent border-0 p-0 text-lg font-black text-[#2D3A2D] focus:ring-0 outline-none"
                                        />
                                    </div>
                                    <div className="bg-white p-6 rounded-[1.5rem] border border-[#E5E1D8] shadow-sm space-y-2">
                                        <p className="text-[10px] font-black text-[#8B7E66] uppercase tracking-wider">Total Nominal</p>
                                        <div className="flex items-center gap-2">
                                            <span className="text-lg font-black text-rose-500">Rp</span>
                                            <input
                                                type="number"
                                                value={scanResult.totalAmount || ''}
                                                onChange={(e) => updateScanResult('totalAmount', e.target.value)}
                                                className="w-full bg-transparent border-0 p-0 text-lg font-black text-[#2D3A2D] focus:ring-0 outline-none"
                                            />
                                        </div>
                                    </div>
                                    <div className="bg-white p-6 rounded-[1.5rem] border border-[#E5E1D8] shadow-sm col-span-1 md:col-span-2 space-y-4">
                                        <div className="flex justify-between items-center pb-2 border-b border-gray-50">
                                            <p className="text-[10px] font-black text-[#8B7E66] uppercase tracking-wider">Rincian Barang (Klik untuk edit)</p>
                                            <span className="bg-emerald-100 text-emerald-700 text-[8px] font-black px-2 py-0.5 rounded-full">AUTO-CAPTURED</span>
                                        </div>
                                        <div className="space-y-4">
                                            {scanResult.items?.map((item: any, idx: number) => (
                                                <div key={idx} className="flex flex-col md:flex-row md:items-center gap-3 group">
                                                    <input
                                                        type="text"
                                                        value={item.name || ''}
                                                        onChange={(e) => updateScanItem(idx, 'name', e.target.value)}
                                                        className="flex-1 bg-gray-50/50 px-3 py-2 rounded-lg text-xs font-bold text-gray-700 border-0 focus:bg-white focus:ring-1 focus:ring-rose-200 transition-all outline-none"
                                                    />
                                                    <div className="flex items-center gap-3">
                                                        <div className="flex items-center gap-1 group/qty">
                                                            <span className="text-[10px] font-bold text-gray-400">x</span>
                                                            <input
                                                                type="number"
                                                                value={item.qty || 1}
                                                                onChange={(e) => updateScanItem(idx, 'qty', e.target.value)}
                                                                className="w-12 bg-gray-50/50 px-2 py-2 rounded-lg text-xs font-black text-center text-gray-700 border-0 focus:bg-white focus:ring-1 focus:ring-rose-200 transition-all outline-none"
                                                            />
                                                        </div>
                                                        <div className="flex items-center gap-1 group/price">
                                                            <span className="text-[10px] font-bold text-gray-400">Rp</span>
                                                            <input
                                                                type="number"
                                                                value={item.total || 0}
                                                                onChange={(e) => updateScanItem(idx, 'total', e.target.value)}
                                                                className="w-24 bg-gray-50/50 px-3 py-2 rounded-lg text-xs font-mono font-bold text-right text-emerald-600 border-0 focus:bg-white focus:ring-1 focus:ring-rose-200 transition-all outline-none"
                                                            />
                                                        </div>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </div>

                                <div className="flex gap-4">
                                    <button
                                        onClick={() => { setScanResult(null); setScanFile(null); setScanPreview(null); }}
                                        className="flex-1 py-4 bg-gray-100 text-gray-500 rounded-2xl font-bold text-xs uppercase hover:bg-gray-200 transition-colors"
                                    >
                                        Scan Ulang
                                    </button>
                                    <button
                                        onClick={applyScanResult}
                                        className="flex-[2] py-4 bg-[#2D3A2D] text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-[#1a241a] transition-all shadow-xl flex items-center justify-center gap-2"
                                    >
                                        Gunakan Data Ini <ChevronRight className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>
                ) : (
                    <form onSubmit={handleSubmit} className="p-6 md:p-10 space-y-6 md:space-y-8 overflow-y-auto custom-scrollbar">
                        {error && (
                            <div className="p-4 bg-rose-50 border border-rose-100 rounded-2xl text-rose-600 text-xs font-bold">
                                ⚠️ {error}
                            </div>
                        )}

                        {/* Amount Input */}
                        <div className="space-y-3">
                            <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest ml-1">Nominal (IDR)</label>
                            <div className="relative group">
                                <div className="absolute inset-y-0 left-0 pl-5 flex items-center pointer-events-none">
                                    <span className="text-lg font-black text-rose-600">Rp</span>
                                </div>
                                <input
                                    type="number"
                                    required
                                    value={amount}
                                    onChange={(e) => setAmount(e.target.value)}
                                    className="block w-full pl-16 pr-5 py-5 bg-white border-2 border-[#E5E1D8] rounded-[2rem] text-2xl font-black text-[#2D3A2D] focus:border-rose-500 focus:ring-4 focus:ring-rose-500/10 transition-all outline-none"
                                    placeholder="0"
                                />
                            </div>
                        </div>

                        {/* Type Choice */}
                        <div className="space-y-3">
                            <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest ml-1">Kategori Biaya (Dari Chart of Accounts)</label>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                {expenseAccounts.map((acc: any) => (
                                    <button
                                        key={acc.id}
                                        type="button"
                                        onClick={() => setExpenseAccountCode(acc.code)}
                                        className={`px-6 py-4 rounded-2xl border-2 transition-all flex justify-between items-center group ${expenseAccountCode === acc.code
                                            ? 'bg-rose-50 border-rose-500 text-rose-700 shadow-md'
                                            : 'bg-white border-[#E5E1D8] text-[#8B7E66] hover:border-[#8B7E66]'
                                            }`}
                                    >
                                        <div className="text-left">
                                            <p className="text-[10px] font-black uppercase tracking-tight">{acc.name}</p>
                                            <p className="text-[8px] opacity-60 font-bold">{acc.code}</p>
                                        </div>
                                        <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${expenseAccountCode === acc.code ? 'border-rose-500 bg-rose-500' : 'border-[#E5E1D8]'}`}>
                                            {expenseAccountCode === acc.code && <div className="w-1.5 h-1.5 bg-white rounded-full" />}
                                        </div>
                                    </button>
                                ))}
                                {expenseAccounts.length === 0 && <p className="text-[10px] font-bold text-[#8B7E66] italic col-span-2">Belum ada akun biaya di CoA.</p>}
                            </div>
                        </div>

                        {/* Source & Desc */}
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
                            <div className="space-y-3">
                                <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest ml-1">Sumber Dana (Bank/Kas)</label>
                                <select
                                    value={sourceAccountId}
                                    onChange={(e) => setSourceAccountId(e.target.value)}
                                    className="w-full p-4 bg-white border-2 border-[#E5E1D8] rounded-2xl text-xs font-bold text-[#2D3A2D] focus:border-rose-500 outline-none"
                                >
                                    {assetAccounts.map((acc: any) => (
                                        <option key={acc.code} value={acc.code}>{acc.name} ({acc.code})</option>
                                    ))}
                                    {assetAccounts.length === 0 && <option value="">Belum ada akun bank/kas</option>}
                                </select>
                            </div>
                            <div className="space-y-3">
                                <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest ml-1">Keterangan</label>
                                <input
                                    type="text"
                                    value={description}
                                    onChange={(e) => setDescription(e.target.value)}
                                    placeholder="Detail biaya..."
                                    className="w-full p-4 bg-white border-2 border-[#E5E1D8] rounded-2xl text-xs font-bold text-[#2D3A2D] focus:border-rose-500 outline-none"
                                />
                            </div>
                        </div>

                        <button
                            type="submit"
                            disabled={isLoading}
                            className="w-full py-5 bg-rose-600 text-white rounded-[2rem] font-black text-sm uppercase tracking-[0.2em] shadow-xl shadow-rose-900/20 hover:bg-rose-700 hover:-translate-y-1 active:translate-y-0 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
                        >
                            {isLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Simpan Biaya'}
                        </button>
                    </form>
                )}
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import {
    LineChart, Line, AreaChart, Area, XAxis, YAxis, CartesianGrid,
    Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend
} from 'recharts';
import {
    TrendingUp, TrendingDown, DollarSign, PieChart as PieIcon,
    ShieldCheck, Zap, ArrowLeft, Info, Calendar, ExternalLink, Receipt, Settings, BrainCircuit, Landmark, BookOpen, AlertTriangle, ArrowUpRight, ArrowDownRight, Target, Box
} from 'lucide-react';

import type { FinancialPulse } from '@/lib/intelligence/financeEngine';
import TaxReportModal from './TaxReportModal';
import SettlementParserModal from './finance/SettlementParserModal';
import { ICTracker } from '../ICTracker';
import { BudgetTracker } from '../BudgetTracker';
import { getPriceAnalysisAction, getStockAction, getBrandPriceAnalysisAction } from '@/lib/actions/rasa-ibu/stock';
import { History, Search, ArrowRight, FileText } from 'lucide-react';
import LedgerModal from './LedgerModal';

interface FinanceHubProps {
    brandId: string;
    pulse: FinancialPulse;
    onBack: () => void;
    onOpenExpenseEntry: () => void;
    onOpenIncomeEntry: () => void;
    onOpenIntel: () => void;
    onOpenAccountManager: () => void;
    onOpenAssetHub: () => void;
    onOpenSettings: () => void;
    onOpenPricing: () => void;
}


export default function FinanceHub({ brandId, pulse, onBack, onOpenExpenseEntry, onOpenIncomeEntry, onOpenIntel, onOpenAccountManager, onOpenAssetHub, onOpenSettings, onOpenPricing }: FinanceHubProps) {
    const [showTaxReport, setShowTaxReport] = React.useState(false);
    const [showSettlementParser, setShowSettlementParser] = React.useState(false);
    const [showLedger, setShowLedger] = React.useState(false);

    // Price Intelligence State
    const [materials, setMaterials] = React.useState<any[]>([]);
    const [selectedMaterialId, setSelectedMaterialId] = React.useState<string | 'OVERVIEW'>('OVERVIEW');
    const [priceAnalysis, setPriceAnalysis] = React.useState<any[]>([]);
    const [overviewData, setOverviewData] = React.useState<any>(null);
    const [isLoadingAnalysis, setIsLoadingAnalysis] = React.useState(false);
    const [trendGranularity, setTrendGranularity] = React.useState<'Daily' | 'Weekly' | 'Monthly'>('Daily');


    const currency = new Intl.NumberFormat('id-ID', {
        style: 'currency',
        currency: 'IDR',
        maximumFractionDigits: 0
    });

    React.useEffect(() => {
        const loadMaterials = async () => {
            const res = await getStockAction(brandId);
            if (res.success) setMaterials(res.data);
        };
        loadMaterials();
    }, [brandId]);

    React.useEffect(() => {
        const loadAnalysis = async () => {
            setIsLoadingAnalysis(true);
            if (selectedMaterialId === 'OVERVIEW') {
                const res = await getBrandPriceAnalysisAction(brandId);
                if (res.success && res.data) {
                    setOverviewData(res.data);
                    setPriceAnalysis(res.data.aggregateTrend);
                }
            } else if (selectedMaterialId) {
                const res = await getPriceAnalysisAction(selectedMaterialId);
                if (res.success) setPriceAnalysis(res.data || []);
            }
            setIsLoadingAnalysis(false);
        };
        loadAnalysis();
    }, [selectedMaterialId, brandId]);

    // Color Palette
    const COLORS = ['#10b981', '#f59e0b', '#3b82f6', '#ef4444', '#8b5cf6'];
    const GLASS_CARD = "bg-white/5 backdrop-blur-2xl border border-white/10 rounded-[2.5rem] p-8 shadow-2xl relative overflow-hidden group";

    return (
        <div className="space-y-10 animate-in fade-in zoom-in-95 duration-700 pb-20">
            {/* Header & Control */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                <div>
                    <button
                        onClick={onBack}
                        className="flex items-center gap-2 text-[#8B7E66] hover:text-[#2D3A2D] transition-colors mb-4 group"
                    >
                        <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Kembali ke OPS</span>
                    </button>
                    <h2 className="text-2xl md:text-4xl font-black text-[#1A241A] tracking-tighter flex items-center gap-3">
                        <span className="text-emerald-600 bg-emerald-100 p-2 rounded-2xl shadow-inner inline-flex items-center justify-center">📈</span>
                        Intelligence <span className="text-emerald-600">Finance Hub</span>
                    </h2>
                    <p className="text-[#8B7E66] text-xs md:text-sm mt-2 font-medium">Laporan Laba/Rugi & Analisis Margin Strategis</p>
                </div>

                <div className="flex flex-wrap items-center gap-3 md:gap-4 bg-[#F9F7F2] p-2 md:p-3 rounded-2xl border border-[#E5E1D8]">
                    <button
                        onClick={() => setShowTaxReport(true)}
                        className="px-4 md:px-6 py-2 md:py-2.5 bg-white text-[#2D3A2D] border border-rose-200 rounded-xl text-[9px] md:text-[10px] font-black uppercase tracking-widest hover:bg-rose-50 transition-all shadow-sm flex items-center gap-2"
                    >
                        <Landmark className="w-3.5 h-3.5 text-rose-500" />
                        Laporan Pajak
                    </button>
                    <button
                        onClick={() => setShowSettlementParser(true)}
                        className="px-4 md:px-6 py-2 md:py-2.5 bg-indigo-600 text-white border border-indigo-400 rounded-xl text-[9px] md:text-[10px] font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-900/20 flex items-center gap-2"
                    >
                        <BrainCircuit className="w-3.5 h-3.5" />
                        Settlement AI
                    </button>
                    <button
                        onClick={onOpenIncomeEntry}
                        className="px-4 md:px-6 py-2 md:py-2.5 bg-emerald-600 text-white rounded-xl text-[9px] md:text-[10px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-900/20 flex items-center gap-2"
                    >
                        <TrendingUp className="w-3.5 h-3.5" />
                        Pemasukan
                    </button>
                    <button
                        onClick={onOpenPricing}
                        className="px-4 md:px-6 py-2 md:py-2.5 bg-white text-[#2D3A2D] border border-emerald-200 rounded-xl text-[9px] md:text-[10px] font-black uppercase tracking-widest hover:bg-emerald-50 transition-all shadow-sm flex items-center gap-2"
                    >
                        <TrendingUp className="w-3.5 h-3.5 text-emerald-600" />
                        Strategi Harga
                    </button>
                    <button
                        onClick={onOpenExpenseEntry}
                        className="px-4 md:px-6 py-2 md:py-2.5 bg-rose-600 text-white rounded-xl text-[9px] md:text-[10px] font-black uppercase tracking-widest hover:bg-rose-700 transition-all shadow-lg shadow-rose-900/20 flex items-center gap-2"
                    >
                        <Receipt className="w-3.5 h-3.5" />
                        Biaya
                    </button>
                    <div className="px-3 md:px-4 py-2 bg-white rounded-xl shadow-sm text-[9px] md:text-[10px] font-bold text-[#8B7E66] flex items-center gap-2 border border-[#E5E1D8]">
                        <Calendar className="w-3 h-3 text-emerald-600" />
                        Bulan Ini
                    </div>
                    <div className="flex items-center gap-2">
                        <button
                            onClick={onOpenIntel}
                            className="p-2 md:p-2.5 bg-indigo-600 text-white border border-indigo-500 rounded-xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-900/10"
                            title="AI Business Intelligence"
                        >
                            <BrainCircuit className="w-3.5 h-3.5 md:w-4 h-4" />
                        </button>
                        <button
                            onClick={onOpenAccountManager}
                            className="p-2 md:p-2.5 bg-white text-indigo-600 border border-indigo-100 rounded-xl hover:bg-indigo-50 transition-all shadow-sm"
                            title="Chart of Accounts"
                        >
                            <BookOpen className="w-3.5 h-3.5 md:w-4 h-4" />
                        </button>
                        <button
                            onClick={() => setShowLedger(true)}
                            className="p-2 md:p-2.5 bg-white text-indigo-600 border border-indigo-100 rounded-xl hover:bg-indigo-50 transition-all shadow-sm"
                            title="Buku Besar (Jurnal)"
                        >
                            <FileText className="w-3.5 h-3.5 md:w-4 h-4" />
                        </button>
                        <button
                            onClick={onOpenAssetHub}
                            className="p-2 md:p-2.5 bg-amber-50 text-amber-600 border border-amber-100 rounded-xl hover:bg-amber-100 transition-all shadow-sm"
                            title="Manajemen Aset"
                        >
                            <Box className="w-3.5 h-3.5 md:w-4 h-4" />
                        </button>
                        <button
                            onClick={onOpenSettings}
                            className="p-2 md:p-2.5 bg-white text-[#2D3A2D] border border-[#E5E1D8] rounded-xl hover:bg-[#F9F7F2] transition-all shadow-sm"
                        >
                            <Settings className="w-3.5 h-3.5 md:w-4 h-4" />
                        </button>
                    </div>
                </div>
            </div>

            {/* Top Stat Cards (Glassmorphism Dark) */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
                {/* Net Profit Card */}
                <div className={`${GLASS_CARD} bg-gradient-to-br from-[#1A241A] to-[#0A0F0A] col-span-1 md:col-span-2 ring-1 ring-emerald-500/30`}>
                    <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
                    <div className="flex justify-between items-start mb-10">
                        <div className="p-4 bg-emerald-500/20 rounded-2xl border border-emerald-500/20">
                            <TrendingUp className="w-6 h-6 text-emerald-400" />
                        </div>
                        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-emerald-400 bg-emerald-500/10 px-4 py-2 rounded-full border border-emerald-500/20">Net Margin: {pulse.monthlyRevenue > 0 ? Math.round((pulse.monthlyNetProfit / pulse.monthlyRevenue) * 100) : 0}%</span>
                    </div>
                    <p className="text-[11px] font-bold uppercase tracking-[0.4em] text-[#B2BCA2] mb-3 opacity-60">Estimasi Laba Bersih</p>
                    <h3 className="text-6xl font-black tracking-tighter text-white mb-6">
                        {currency.format(pulse.monthlyNetProfit)}
                    </h3>
                    <div className="flex items-center gap-2 text-[10px] font-bold text-emerald-400/80">
                        <Zap className="w-3 h-3" />
                        Data dihitung setelah potongan HPP & Komisi Marketplace
                    </div>
                </div>

                {/* Gross Revenue with Periodic Info */}
                <div className={`${GLASS_CARD} bg-white/40 border-[#E5E1D8] text-[#1A241A] flex flex-col justify-between`}>
                    <div>
                        <div className="flex justify-between items-center mb-4">
                            <p className="text-[10px] font-black uppercase tracking-[0.3em] text-[#8B7E66]">Penjualan Berkala</p>
                            {pulse.growth.revenue > 0 ? (
                                <div className="flex items-center gap-1 text-[9px] font-black text-emerald-600 bg-emerald-50 px-2 py-1 rounded-full">
                                    <ArrowUpRight className="w-3 h-3" />
                                    {Math.round(pulse.growth.revenue)}% Growth
                                </div>
                            ) : (
                                <div className="flex items-center gap-1 text-[9px] font-black text-rose-600 bg-rose-50 px-2 py-1 rounded-full">
                                    <ArrowDownRight className="w-3 h-3" />
                                    {Math.round(Math.abs(pulse.growth.revenue))}% Drop
                                </div>
                            )}
                        </div>
                        <div className="space-y-4 mt-2">
                            <div className="flex justify-between items-end border-b border-dashed border-[#E5E1D8] pb-2">
                                <span className="text-[10px] font-bold text-[#8B7E66]">Harian:</span>
                                <span className="text-sm font-black">{currency.format(pulse.periodicSales.daily)}</span>
                            </div>
                            <div className="flex justify-between items-end border-b border-dashed border-[#E5E1D8] pb-2">
                                <span className="text-[10px] font-bold text-[#8B7E66]">Mingguan:</span>
                                <span className="text-sm font-black">{currency.format(pulse.periodicSales.weekly)}</span>
                            </div>
                            <div className="flex justify-between items-end">
                                <span className="text-[10px] font-bold text-[#8B7E66]">Tahunan:</span>
                                <span className="text-sm font-black text-emerald-600 font-black">{currency.format(pulse.periodicSales.yearly)}</span>
                            </div>
                        </div>
                    </div>
                    <div className="mt-6">
                        <div className="flex justify-between items-center mb-2">
                            <div className="text-[8px] font-black text-[#8B7E66] uppercase tracking-widest">Revenue Target: {currency.format(pulse.targets.revenue)}</div>
                            <div className="text-[8px] font-black text-emerald-600 uppercase tracking-widest">{Math.min(Math.round(pulse.targets.revenueProgress), 100)}% Achieved</div>
                        </div>
                        <div className="h-1.5 w-full bg-[#E5E1D8] rounded-full overflow-hidden">
                            <div className="h-full bg-emerald-600 rounded-full transition-all duration-1000" style={{ width: `${Math.min(pulse.targets.revenueProgress, 100)}%` }}></div>
                        </div>
                    </div>
                </div>

                {/* HPP & Expired Burden with Targeting */}
                <div className={`${GLASS_CARD} bg-white/20 border-[#E5E1D8] text-[#1A241A] flex flex-col justify-between`}>
                    <div className="flex justify-between items-center mb-6">
                        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-rose-600">Biaya & Efisiensi</p>
                        <div className={`px-2 py-1 rounded-full text-[8px] font-black uppercase ${pulse.targets.expenseProgress > 100 ? 'bg-rose-100 text-rose-600' : 'bg-emerald-100 text-emerald-600'}`}>
                            {pulse.targets.expenseProgress > 100 ? 'Over Budget' : 'Safe Budget'}
                        </div>
                    </div>

                    <div className="space-y-4">
                        <div className="flex justify-between items-center text-[9px] font-bold">
                            <span className="text-[#8B7E66]">HPP: {currency.format(pulse.monthlyCOGS)}</span>
                            <span className="text-rose-600">Ops: {currency.format(pulse.monthlyLedgerExpenses)}</span>
                        </div>
                        <div className="p-4 bg-rose-50/50 rounded-2xl border border-rose-100 flex items-center justify-between">
                            <div>
                                <p className="text-[9px] font-black uppercase tracking-widest text-rose-600 mb-1 flex items-center gap-1">
                                    <AlertTriangle className="w-3 h-3" /> Beban Expired
                                </p>
                                <h4 className="text-xl font-black text-rose-700">{currency.format(pulse.expiredBurden)}</h4>
                            </div>
                        </div>
                    </div>

                    <div className="mt-6">
                        <div className="flex justify-between items-end mb-1">
                            <span className="text-[8px] font-black uppercase tracking-widest text-[#8B7E66]">Limit: {currency.format(pulse.targets.expenseLimit)}</span>
                        </div>
                        <div className="h-1.5 w-full bg-[#E5E1D8]/50 rounded-full overflow-hidden">
                            <div className={`h-full rounded-full transition-all duration-1000 ${pulse.targets.expenseProgress > 90 ? 'bg-rose-500' : 'bg-[#1A241A]'}`} style={{ width: `${Math.min(pulse.targets.expenseProgress, 100)}%` }}></div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Charts Section */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 bg-white border border-[#E5E1D8] p-10 rounded-[3rem] shadow-xl">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
                        <div>
                            <h4 className="text-xs font-black uppercase tracking-[0.4em] text-[#8B7E66] mb-1">Revenue Trend & AI Prediction</h4>
                            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Visualisasi Performa Berjangka</p>
                        </div>
                        <div className="flex items-center gap-4 bg-[#F9F7F2] p-1.5 rounded-2xl border border-[#E5E1D8]">
                            {['Daily', 'Weekly', 'Monthly'].map((type) => (
                                <button
                                    key={type}
                                    onClick={() => setTrendGranularity(type as any)}
                                    className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${trendGranularity === type
                                        ? 'bg-[#2D3A2D] text-white shadow-lg'
                                        : 'text-[#8B7E66] hover:bg-white hover:text-[#2D3A2D]'
                                        }`}
                                >
                                    {type}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div className="h-[400px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <AreaChart data={[...pulse.revenueTrend, ...pulse.forecastTrend]}>
                                <defs>
                                    <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#10b981" stopOpacity={0.3} />
                                        <stop offset="95%" stopColor="#10b981" stopOpacity={0} />
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f1f1" />
                                <XAxis
                                    dataKey="date"
                                    axisLine={false}
                                    tickLine={false}
                                    tick={{ fontSize: 9, fontWeight: 700, fill: '#8B7E66' }}
                                    tickFormatter={(val: string) => {
                                        if (trendGranularity === 'Monthly') return val.split('-').slice(0, 2).join('/');
                                        return val.split('-').slice(2).join('/');
                                    }}
                                />
                                <YAxis
                                    axisLine={false}
                                    tickLine={false}
                                    tick={{ fontSize: 9, fontWeight: 700, fill: '#8B7E66' }}
                                    tickFormatter={(val) => `Rp${val / 1000000}M`}
                                />
                                <Tooltip
                                    contentStyle={{
                                        borderRadius: '1.5rem',
                                        border: 'none',
                                        boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)',
                                        fontSize: '11px',
                                        fontWeight: 'bold',
                                        padding: '1.5rem'
                                    }}
                                    formatter={(val) => currency.format(Number(val))}
                                />
                                <Area
                                    type="monotone"
                                    dataKey="amount"
                                    stroke="#10b981"
                                    strokeWidth={4}
                                    fillOpacity={1}
                                    fill="url(#colorRevenue)"
                                    activeDot={{ r: 8, stroke: '#fff', strokeWidth: 4 }}
                                />
                            </AreaChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Marketplace Distribution */}
                <div className="bg-white border border-[#E5E1D8] p-10 rounded-[3rem] shadow-xl flex flex-col justify-between">
                    <div>
                        <h4 className="text-xs font-black uppercase tracking-[0.4em] text-[#8B7E66] mb-10">Marketplace Effective Margin</h4>
                        <div className="h-[250px] w-full">
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie
                                        data={pulse.channelBreakdown}
                                        innerRadius={60}
                                        outerRadius={90}
                                        paddingAngle={5}
                                        dataKey="grossAmount"
                                    >
                                        {pulse.channelBreakdown.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                        ))}
                                    </Pie>
                                    <Tooltip
                                        contentStyle={{ borderRadius: '1rem', border: 'none', fontSize: '11px', fontWeight: 'bold' }}
                                        formatter={(val) => currency.format(Number(val))}
                                    />
                                </PieChart>
                            </ResponsiveContainer>
                        </div>

                        <div className="mt-8 space-y-5">
                            {pulse.channelBreakdown.map((item, idx) => (
                                <div key={item.channel} className="flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className="w-3 h-3 rounded-full" style={{ backgroundColor: COLORS[idx % COLORS.length] }}></div>
                                        <span className="text-[10px] font-black uppercase text-[#1A241A] tracking-wider">{item.channel}</span>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-[10px] font-black">{currency.format(item.netAmount)}</p>
                                        <p className="text-[8px] font-bold text-emerald-600">Margin: {item.grossAmount > 0 ? Math.round((item.netAmount / item.grossAmount) * 100) : 0}%</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="mt-10 p-6 bg-emerald-50 rounded-2xl border border-emerald-100 italic text-[10px] text-emerald-800 font-medium">
                        "Marketplace WA memiliki margin tertinggi karena minim biaya platform."
                    </div>
                </div>
            </div>

            {/* Efficiency & Profit Leakage Audit (Radar) */}
            <div className="bg-white border border-[#E5E1D8] p-12 rounded-[3.5rem] shadow-xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-emerald-500 via-amber-500 to-rose-500"></div>

                <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-12 gap-6">
                    <div>
                        <h4 className="text-xs font-black uppercase tracking-[0.4em] text-[#8B7E66] mb-2">Efficiency & Leakage Radar</h4>
                        <p className="text-sm text-[#2D3A2D] font-medium italic">Audit otomatis untuk mendeteksi biaya tersembunyi & kebocoran profit.</p>
                    </div>
                    <div className="flex items-center gap-4 bg-[#F9F7F2] px-6 py-3 rounded-2xl border border-[#E5E1D8]">
                        <span className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Financial Health Score</span>
                        <div className="flex items-center gap-2">
                            <div className="w-12 h-2 bg-gray-200 rounded-full overflow-hidden">
                                <div
                                    className="h-full bg-emerald-500 rounded-full"
                                    style={{ width: `${pulse.efficiency?.efficiencyScore || 0}%` }}
                                ></div>
                            </div>
                            <span className="text-sm font-black text-emerald-600">{Math.round(pulse.efficiency?.efficiencyScore || 0)}%</span>
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                    {/* Marketplace Commission */}
                    <div className="space-y-4">
                        <div className="p-4 bg-[#FDFBF7] rounded-2xl border border-[#E5E1D8] flex items-center gap-3">
                            <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg">
                                <PieIcon className="w-4 h-4" />
                            </div>
                            <span className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Tagihan Jasa Aplikasi</span>
                        </div>
                        <div className="px-2">
                            <h5 className="text-2xl font-black text-[#2D3A2D]">{currency.format(pulse.efficiency?.totalCommission || 0)}</h5>
                            <p className="text-[10px] text-slate-400 font-medium mt-1">Estimasi potongan komisi dari semua platform.</p>
                        </div>
                    </div>

                    {/* MDR / Admin Fees */}
                    <div className="space-y-4">
                        <div className="p-4 bg-[#FDFBF7] rounded-2xl border border-[#E5E1D8] flex items-center gap-3">
                            <div className="p-2 bg-amber-100 text-amber-600 rounded-lg">
                                <DollarSign className="w-4 h-4" />
                            </div>
                            <span className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">MDR & Biaya Transaksi</span>
                        </div>
