                                                <stop offset="95%" stopColor={selectedMaterialId === 'OVERVIEW' ? '#10b981' : '#f59e0b'} stopOpacity={0} />
                                            </linearGradient>
                                        </defs>
                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                                        <XAxis
                                            dataKey="date"
                                            axisLine={false}
                                            tickLine={false}
                                            tick={{ fontSize: 10, fontWeight: 700, fill: '#94a3b8' }}
                                            dy={10}
                                        />
                                        <YAxis
                                            axisLine={false}
                                            tickLine={false}
                                            tick={{ fontSize: 10, fontWeight: 700, fill: '#94a3b8' }}
                                            tickFormatter={(val) => `Rp${val.toLocaleString()}`}
                                        />
                                        <Tooltip
                                            contentStyle={{
                                                borderRadius: '1rem',
                                                border: 'none',
                                                boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)',
                                                padding: '1rem',
                                                fontSize: '11px',
                                                fontWeight: 'bold'
                                            }}
                                            formatter={(val: any) => [
                                                `Rp ${val.toLocaleString()}`,
                                                selectedMaterialId === 'OVERVIEW' ? 'Harga Rata-rata Index' : 'Harga Beli'
                                            ]}
                                        />
                                        <Area
                                            type="monotone"
                                            dataKey={selectedMaterialId === 'OVERVIEW' ? 'avgPrice' : 'price'}
                                            stroke={selectedMaterialId === 'OVERVIEW' ? '#10b981' : '#f59e0b'}
                                            strokeWidth={3}
                                            fillOpacity={1}
                                            fill="url(#colorPrice)"
                                            animationDuration={1500}
                                        />
