'use client';

import React, { useState, useEffect } from 'react';
import { toast } from 'sonner';
import { GripVertical, Plus, Edit2, Trash2, Eye, EyeOff, X } from 'lucide-react';
import {
    getHeroSlides,
    createHeroSlide,
    updateHeroSlide,
    deleteHeroSlide,
    reorderHeroSlides,
    toggleHeroSlideStatus
} from '@/lib/actions/rasa-ibu/hero-slides';
import { useConfirm } from '@/components/ui/BrandConfirm';

interface HeroSlide {
    id: string;
    title: string;
    subtitle: string;
    ctaLabel: string | null;
    ctaLink: string | null;
    mediaType: 'IMAGE' | 'VIDEO';
    imageUrl: string | null;
    videoUrl: string | null;
    isActive: boolean;
    sortOrder: number;
}

interface HeroSliderManagerProps {
    brandId: string;
}

export default function HeroSliderManager({ brandId }: HeroSliderManagerProps) {
    const [slides, setSlides] = useState<HeroSlide[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [showForm, setShowForm] = useState(false);
    const [editingSlide, setEditingSlide] = useState<HeroSlide | null>(null);
    const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
    const confirm = useConfirm();

    // Form state
    const [formData, setFormData] = useState({
        title: '',
        subtitle: '',
        ctaLabel: '',
        ctaLink: '',
        mediaType: 'IMAGE' as 'IMAGE' | 'VIDEO',
        imageUrl: '',
        videoUrl: '',
        tagline: '',
        isActive: true
    });

    const [imagePreview, setImagePreview] = useState('');

    useEffect(() => {
        loadSlides();
    }, []);

    const loadSlides = async () => {
        setIsLoading(true);
        const result = await getHeroSlides(brandId);
        if (result.success && result.slides) {
            setSlides(result.slides as HeroSlide[]);
        }
        setIsLoading(false);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (editingSlide) {
            // Update existing slide
            const result = await updateHeroSlide(editingSlide.id, formData);
            if (result.success) {
                toast.success('Hero slide berhasil diupdate!');
                loadSlides();
                resetForm();
            } else {
                toast.error(result.error || 'Gagal update slide');
            }
        } else {
            // Create new slide
            const result = await createHeroSlide({
                brandId,
                ...formData
            });
            if (result.success) {
                toast.success('Hero slide berhasil ditambahkan!');
                loadSlides();
                resetForm();
            } else {
                toast.error(result.error || 'Gagal menambahkan slide');
            }
        }
    };

    const handleEdit = (slide: HeroSlide) => {
        setEditingSlide(slide);
        setFormData({
            title: slide.title,
            subtitle: slide.subtitle,
            ctaLabel: slide.ctaLabel || '',
            ctaLink: slide.ctaLink || '',
            mediaType: slide.mediaType,
            imageUrl: slide.imageUrl || '',
            videoUrl: slide.videoUrl || '',
            tagline: (slide as any).tagline || '',
            isActive: slide.isActive
        });
        setImagePreview(slide.imageUrl || '');
        setShowForm(true);
    };

    const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        if (file.size > 2 * 1024 * 1024) {
            toast.error('Ukuran gambar maksimal 2MB');
            return;
        }

        const reader = new FileReader();
        reader.onloadend = () => {
            const base64 = reader.result as string;
            setFormData({ ...formData, imageUrl: base64 });
            setImagePreview(base64);
        };
        reader.readAsDataURL(file);
    };

    const handleDelete = async (id: string) => {
        const confirmed = await confirm({
            title: 'Hapus Slide?',
            message: 'Slide banner ini akan dihapus secara permanen dari beranda. Lanjutkan?',
            confirmText: 'Ya, Hapus',
            cancelText: 'Batal',
            variant: 'danger'
        });

        if (!confirmed) return;

        const result = await deleteHeroSlide(id);
        if (result.success) {
            toast.success('Slide berhasil dihapus!');
            loadSlides();
        } else {
            toast.error(result.error || 'Gagal menghapus slide');
        }
    };

    const handleToggleStatus = async (id: string, currentStatus: boolean) => {
        const result = await toggleHeroSlideStatus(id, !currentStatus);
        if (result.success) {
            toast.success(`Slide ${!currentStatus ? 'diaktifkan' : 'dinonaktifkan'}!`);
            loadSlides();
        } else {
            toast.error(result.error || 'Gagal mengubah status');
        }
    };

    const handleDragStart = (index: number) => {
        setDraggedIndex(index);
    };

    const handleDragOver = (e: React.DragEvent, index: number) => {
        e.preventDefault();
        if (draggedIndex === null || draggedIndex === index) return;

        const newSlides = [...slides];
        const draggedSlide = newSlides[draggedIndex];
        newSlides.splice(draggedIndex, 1);
        newSlides.splice(index, 0, draggedSlide);

        setSlides(newSlides);
        setDraggedIndex(index);
    };

    const handleDragEnd = async () => {
        if (draggedIndex === null) return;

        const slideIds = slides.map(s => s.id);
        const result = await reorderHeroSlides(slideIds);

        if (result.success) {
            toast.success('Urutan slide berhasil diupdate!');
            loadSlides();
        } else {
            toast.error(result.error || 'Gagal mengubah urutan');
            loadSlides(); // Reload to reset order
        }

        setDraggedIndex(null);
    };

    const resetForm = () => {
        setFormData({
            title: '',
            subtitle: '',
            ctaLabel: '',
            ctaLink: '',
            mediaType: 'IMAGE',
            imageUrl: '',
            videoUrl: '',
            tagline: '',
            isActive: true
        });
        setImagePreview('');
        setEditingSlide(null);
        setShowForm(false);
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex justify-between items-center">
                <div>
                    <h3 className="text-lg font-black text-[#2D3A2D]">Hero Slider Management</h3>
                    <p className="text-sm text-slate-500">Kelola banner promosi di homepage (max 5 slides aktif)</p>
                </div>
                <button
                    onClick={() => setShowForm(true)}
                    className="px-6 py-3 bg-[#2D3A2D] text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-amber-600 transition-all flex items-center gap-2"
                >
                    <Plus className="w-4 h-4" />
                    Tambah Slide
                </button>
            </div>

            {/* Slides List */}
            {isLoading ? (
                <div className="text-center py-12 text-slate-400">Loading...</div>
            ) : slides.length === 0 ? (
                <div className="text-center py-12 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200">
                    <p className="text-slate-400 font-medium">Belum ada hero slide. Tambahkan slide pertama!</p>
                </div>
            ) : (
                <div className="space-y-4">
                    {slides.map((slide, index) => (
                        <div
                            key={slide.id}
                            draggable
                            onDragStart={() => handleDragStart(index)}
                            onDragOver={(e) => handleDragOver(e, index)}
                            onDragEnd={handleDragEnd}
                            className={`bg-white border-2 rounded-2xl p-6 transition-all ${slide.isActive ? 'border-emerald-200' : 'border-slate-200 opacity-60'
                                } ${draggedIndex === index ? 'opacity-50' : ''} hover:shadow-md cursor-move`}
                        >
                            <div className="flex items-start gap-4">
                                {/* Drag Handle */}
                                <div className="pt-2">
                                    <GripVertical className="w-5 h-5 text-slate-400" />
                                </div>

                                {/* Preview */}
                                <div className="w-32 h-20 bg-slate-100 rounded-lg overflow-hidden flex-shrink-0">
                                    {slide.mediaType === 'IMAGE' && slide.imageUrl ? (
                                        <img src={slide.imageUrl} alt={slide.title} className="w-full h-full object-cover" />
                                    ) : slide.mediaType === 'VIDEO' && slide.videoUrl ? (
                                        <video src={slide.videoUrl} className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-slate-400 text-xs">
                                            No Media
                                        </div>
                                    )}
                                </div>

                                {/* Content */}
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-start justify-between gap-4">
                                        <div className="flex-1 min-w-0">
                                            <h4 className="font-black text-[#2D3A2D] truncate">{slide.title}</h4>
                                            <p className="text-sm text-slate-600 line-clamp-2">{slide.subtitle}</p>
                                            {slide.ctaLabel && (
                                                <p className="text-xs text-amber-600 mt-1">
                                                    CTA: {slide.ctaLabel} → {slide.ctaLink}
                                                </p>
                                            )}
                                        </div>

                                        {/* Actions */}
                                        <div className="flex items-center gap-2">
                                            <span className="text-xs font-bold text-slate-400">#{index + 1}</span>
                                            <button
                                                onClick={() => handleToggleStatus(slide.id, slide.isActive)}
                                                className={`p-2 rounded-lg transition-colors ${slide.isActive
                                                    ? 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100'
                                                    : 'bg-slate-100 text-slate-400 hover:bg-slate-200'
                                                    }`}
                                                title={slide.isActive ? 'Nonaktifkan' : 'Aktifkan'}
                                            >
                                                {slide.isActive ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                                            </button>
                                            <button
                                                onClick={() => handleEdit(slide)}
                                                className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors"
                                                title="Edit"
                                            >
                                                <Edit2 className="w-4 h-4" />
                                            </button>
                                            <button
                                                onClick={() => handleDelete(slide.id)}
                                                className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-colors"
                                                title="Hapus"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Form Modal */}
            {showForm && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-6">
                    <div className="bg-white rounded-3xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="p-8 space-y-6">
                            {/* Header */}
                            <div className="flex justify-between items-center">
                                <h3 className="text-2xl font-black text-[#2D3A2D]">
                                    {editingSlide ? 'Edit Hero Slide' : 'Tambah Hero Slide'}
                                </h3>
                                <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-lg transition-colors">
                                    <X className="w-5 h-5" />
                                </button>
                            </div>

                            {/* Form */}
                            <form onSubmit={handleSubmit} className="space-y-6">
                                <div>
                                    <label className="block text-sm font-bold text-slate-700 mb-2">Tagline (Kecil - Atas)</label>
                                    <input
                                        type="text"
                                        value={formData.tagline}
                                        onChange={(e) => setFormData({ ...formData, tagline: e.target.value })}
                                        className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl focus:border-amber-500 focus:outline-none"
                                        placeholder="Misal: HANGATNYA MEJA MAKAN"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-bold text-slate-700 mb-2">Judul *</label>
                                    <input
                                        type="text"
                                        value={formData.title}
                                        onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                                        className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl focus:border-amber-500 focus:outline-none"
                                        required
                                        placeholder="Promo Ramadan - Diskon 20%"
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-bold text-slate-700 mb-2">Subtitle *</label>
                                    <textarea
                                        value={formData.subtitle}
                                        onChange={(e) => setFormData({ ...formData, subtitle: e.target.value })}
                                        className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl focus:border-amber-500 focus:outline-none"
                                        rows={3}
                                        required
                                        placeholder="Nikmati diskon spesial untuk semua menu favorit"
                                    />
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-bold text-slate-700 mb-2">CTA Label</label>
                                        <input
                                            type="text"
                                            value={formData.ctaLabel}
                                            onChange={(e) => setFormData({ ...formData, ctaLabel: e.target.value })}
                                            className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl focus:border-amber-500 focus:outline-none"
                                            placeholder="Lihat Menu"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-slate-700 mb-2">CTA Link</label>
                                        <input
                                            type="text"
                                            value={formData.ctaLink}
                                            onChange={(e) => setFormData({ ...formData, ctaLink: e.target.value })}
                                            className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl focus:border-amber-500 focus:outline-none"
                                            placeholder="/rasa-ibu/products"
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-sm font-bold text-slate-700 mb-2">Media Type *</label>
                                    <div className="flex gap-4">
                                        <label className="flex items-center gap-2 cursor-pointer">
                                            <input
                                                type="radio"
                                                value="IMAGE"
                                                checked={formData.mediaType === 'IMAGE'}
                                                onChange={(e) => setFormData({ ...formData, mediaType: e.target.value as 'IMAGE' | 'VIDEO' })}
                                                className="w-4 h-4"
                                            />
                                            <span className="text-sm font-medium">Image</span>
                                        </label>
                                        <label className="flex items-center gap-2 cursor-pointer">
                                            <input
                                                type="radio"
                                                value="VIDEO"
                                                checked={formData.mediaType === 'VIDEO'}
                                                onChange={(e) => setFormData({ ...formData, mediaType: e.target.value as 'IMAGE' | 'VIDEO' })}
                                                className="w-4 h-4"
                                            />
                                            <span className="text-sm font-medium">Video</span>
                                        </label>
                                    </div>
                                </div>

                                {formData.mediaType === 'IMAGE' ? (
                                    <div>
                                        <label className="block text-sm font-bold text-slate-700 mb-2">Upload Gambar *</label>
                                        {imagePreview && (
                                            <div className="mb-3 relative">
                                                <img src={imagePreview} alt="Preview" className="w-full h-48 object-cover rounded-xl" />
                                                <button
                                                    type="button"
                                                    onClick={() => {
                                                        setImagePreview('');
                                                        setFormData({ ...formData, imageUrl: '' });
                                                    }}
                                                    className="absolute top-2 right-2 p-2 bg-red-500 text-white rounded-lg hover:bg-red-600"
                                                >
                                                    <X className="w-4 h-4" />
                                                </button>
                                            </div>
                                        )}
                                        <input
                                            type="file"
                                            accept="image/*"
                                            onChange={handleImageUpload}
                                            className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl focus:border-amber-500 focus:outline-none"
                                        />
                                        <p className="text-xs text-slate-500 mt-1">Max 2MB. Format: JPG, PNG, WebP</p>
                                    </div>
                                ) : (
                                    <div>
                                        <label className="block text-sm font-bold text-slate-700 mb-2">Video URL</label>
                                        <input
                                            type="url"
                                            value={formData.videoUrl}
                                            onChange={(e) => setFormData({ ...formData, videoUrl: e.target.value })}
                                            className="w-full px-4 py-3 border-2 border-slate-200 rounded-xl focus:border-amber-500 focus:outline-none"
                                            placeholder="https://example.com/video.mp4"
                                        />
                                    </div>
                                )}

                                <div className="flex items-center gap-3">
                                    <input
                                        type="checkbox"
                                        id="isActive"
                                        checked={formData.isActive}
                                        onChange={(e) => setFormData({ ...formData, isActive: e.target.checked })}
                                        className="w-5 h-5 rounded"
                                    />
                                    <label htmlFor="isActive" className="text-sm font-bold text-slate-700 cursor-pointer">
                                        Aktifkan slide ini
                                    </label>
                                </div>

                                {/* Actions */}
                                <div className="flex gap-4 pt-4">
                                    <button
                                        type="button"
                                        onClick={resetForm}
                                        className="flex-1 px-6 py-3 border-2 border-slate-200 text-slate-700 rounded-xl font-bold hover:bg-slate-50 transition-colors"
                                    >
                                        Batal
                                    </button>
                                    <button
                                        type="submit"
                                        className="flex-1 px-6 py-3 bg-[#2D3A2D] text-white rounded-xl font-bold hover:bg-amber-600 transition-colors"
                                    >
                                        {editingSlide ? 'Update Slide' : 'Tambah Slide'}
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { X, TrendingUp, Loader2, Check } from 'lucide-react';
import { recordIncomeAction, getLedgerAccountsAction } from '@/lib/actions/rasa-ibu/finance';

interface IncomeEntryModalProps {
    brandId: string;
    onClose: () => void;
}

export default function IncomeEntryModal({ brandId, onClose }: IncomeEntryModalProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [amount, setAmount] = useState('');
    const [revenueAccountCode, setRevenueAccountCode] = useState('');
    const [description, setDescription] = useState('');
    const [assetAccountCode, setAssetAccountCode] = useState('');
    const [assetAccounts, setAssetAccounts] = useState<any[]>([]);
    const [revenueAccounts, setRevenueAccounts] = useState<any[]>([]);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        async function load() {
            const res = await getLedgerAccountsAction(brandId);
            if (res.success) {
                const assets = res.data.filter((a: any) => a.type === 'ASSET');
                const revenue = res.data.filter((a: any) => a.type === 'REVENUE');

                setAssetAccounts(assets);
                setRevenueAccounts(revenue);

                if (assets.length > 0) setAssetAccountCode(assets[0].code);
                if (revenue.length > 0) setRevenueAccountCode(revenue[0].code);
            }
        }
        load();
    }, [brandId]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);

        if (!amount || Number(amount) <= 0) {
            setError('Jumlah nominal harus valid');
            return;
        }

        if (!revenueAccountCode) {
            setError('Silakan pilih kategori pendapatan');
            return;
        }

        setIsLoading(true);
        try {
            const res = await recordIncomeAction({
                brandId,
                amount: Number(amount),
                revenueAccountCode,
                description: description || `Pendapatan ${revenueAccountCode}`,
                assetAccountCode,
                date: new Date()
            });

            if (res.success) {
                onClose();
            } else {
                setError(res.error || 'Gagal menyimpan pendapatan');
            }
        } catch (err: any) {
            setError(err.message);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center bg-[#1A241A]/60 backdrop-blur-md p-6">
            <div className="bg-[#FDFBF7] w-full max-w-xl max-h-[85vh] md:max-h-[90vh] flex flex-col rounded-[2.5rem] shadow-2xl border border-[#E5E1D8] overflow-hidden animate-in fade-in zoom-in duration-500">
                {/* Header */}
                <div className="px-10 py-8 border-b border-[#E5E1D8] flex justify-between items-center bg-white sticky top-0 z-10">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-emerald-50 rounded-2xl">
                            <TrendingUp className="w-6 h-6 text-emerald-600" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-[#2D3A2D]">Catat Pemasukan</h2>
                            <p className="text-[10px] font-bold text-[#8B7E66] uppercase tracking-widest">Input Pendapatan Non-Pesanan</p>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        type="button"
                        className="p-3 hover:bg-emerald-50 rounded-full transition-colors group"
                    >
                        <X className="w-6 h-6 text-slate-400 group-hover:text-emerald-500 transition-colors" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-10 space-y-8 overflow-y-auto custom-scrollbar">
                    {error && (
                        <div className="p-4 bg-rose-50 border border-rose-100 rounded-2xl text-rose-600 text-xs font-bold">
                            ⚠️ {error}
                        </div>
                    )}

                    {/* Amount Input */}
                    <div className="space-y-3">
                        <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest ml-1">Nominal (IDR)</label>
                        <div className="relative group">
                            <div className="absolute inset-y-0 left-0 pl-5 flex items-center pointer-events-none">
                                <span className="text-lg font-black text-emerald-600">Rp</span>
                            </div>
                            <input
                                type="number"
                                required
                                value={amount}
                                onChange={(e) => setAmount(e.target.value)}
                                className="block w-full pl-16 pr-5 py-5 bg-white border-2 border-[#E5E1D8] rounded-[2rem] text-2xl font-black text-[#2D3A2D] focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/10 transition-all outline-none"
                                placeholder="0"
                            />
                        </div>
                    </div>

                    {/* Revenue Category */}
                    <div className="space-y-3">
                        <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest ml-1">Kategori Pendapatan</label>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                            {revenueAccounts.map((acc: any) => (
                                <button
                                    key={acc.id}
                                    type="button"
                                    onClick={() => setRevenueAccountCode(acc.code)}
                                    className={`px-6 py-4 rounded-2xl border-2 transition-all flex justify-between items-center group ${revenueAccountCode === acc.code
                                        ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-md'
                                        : 'bg-white border-[#E5E1D8] text-[#8B7E66] hover:border-[#8B7E66]'
                                        }`}
                                >
                                    <div className="text-left">
                                        <p className="text-[10px] font-black uppercase tracking-tight">{acc.name}</p>
                                        <p className="text-[8px] opacity-60 font-bold">{acc.code}</p>
                                    </div>
                                    <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${revenueAccountCode === acc.code ? 'border-emerald-500 bg-emerald-500' : 'border-[#E5E1D8]'}`}>
                                        {revenueAccountCode === acc.code && <div className="w-1.5 h-1.5 bg-white rounded-full" />}
                                    </div>
                                </button>
                            ))}
                            {revenueAccounts.length === 0 && <p className="text-[10px] font-bold text-[#8B7E66] italic col-span-2">Belum ada akun pendapatan di CoA.</p>}
                        </div>
                    </div>

                    {/* Deposit To & Desc */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="space-y-3">
                            <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest ml-1">Setor Ke (Bank/Kas)</label>
                            <select
                                value={assetAccountCode}
                                onChange={(e) => setAssetAccountCode(e.target.value)}
                                className="w-full p-4 bg-white border-2 border-[#E5E1D8] rounded-2xl text-xs font-bold text-[#2D3A2D] focus:border-emerald-500 outline-none"
                            >
                                {assetAccounts.map((acc: any) => (
                                    <option key={acc.code} value={acc.code}>{acc.name} ({acc.code})</option>
                                ))}
                                {assetAccounts.length === 0 && <option value="">Belum ada akun bank/kas</option>}
                            </select>
                        </div>
                        <div className="space-y-3">
                            <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest ml-1">Keterangan</label>
                            <input
                                type="text"
                                value={description}
                                onChange={(e) => setDescription(e.target.value)}
                                placeholder="Detail pemasukan..."
                                className="w-full p-4 bg-white border-2 border-[#E5E1D8] rounded-2xl text-xs font-bold text-[#2D3A2D] focus:border-emerald-500 outline-none"
                            />
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={isLoading}
                        className="w-full py-5 bg-emerald-600 text-white rounded-[2rem] font-black text-sm uppercase tracking-[0.2em] shadow-xl shadow-emerald-900/20 hover:bg-emerald-700 hover:-translate-y-1 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
                    >
                        {isLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : <><Check className="w-5 h-5" /> Simpan Pemasukan</>}
                    </button>
                </form>
            </div>
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { getBusinessAnalysis } from '@/lib/actions/rasa-ibu/intelligence';
import AnalyticsChart from '@/components/analytics/AnalyticsChart';
import { BrainCircuit, LineChart, Target, Zap, ArrowLeft, AlertTriangle } from 'lucide-react';
import BundleAdvisor from './intelligence/BundleAdvisor';
import CustomerSegmentation from './intelligence/CustomerSegmentation';
import PromoPerformance from './intelligence/PromoPerformance';
import WasteAnalysis from './intelligence/WasteAnalysis';
import ProcurementForecast from './intelligence/ProcurementForecast';
import IntelligenceConfig from './intelligence/IntelligenceConfig';
import LTVForecast from './intelligence/LTVForecast';
import ProductionPlan from './intelligence/ProductionPlan';
import WhatsAppBroadcast from './intelligence/WhatsAppBroadcast';
import WhatsAppConnector from './intelligence/WhatsAppConnector';
import LoyaltyProgramDashboard from './intelligence/LoyaltyProgramDashboard';
import MarketplaceTracker from './intelligence/MarketplaceTracker';

interface IntelligenceHubProps {
    brandId: string;
    onClose: () => void;
}

export default function IntelligenceHub({ brandId, onClose }: IntelligenceHubProps) {
    const [analysis, setAnalysis] = useState<any>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    const loadData = async () => {
        setIsLoading(true);
        setError(null);
        try {
            const res = await getBusinessAnalysis(brandId);
            if (res.success) {
                setAnalysis(res.data);
            } else {
                setError(res.error || 'Terjadi kesalahan saat memuat data.');
            }
        } catch (e: any) {
            setError(e.message || 'Gagal terhubung ke server.');
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        loadData();
    }, [brandId]);

    const trendChartData = (analysis?.dailyTrend || []).map((d: any, idx: number) => {
        const date = new Date(d.date).toLocaleDateString('id-ID', { day: '2-digit', month: 'short' });
        const prev = analysis.comparisonTrend?.[idx]?.amount || 0;
        return {
            date,
            'Bulan Ini': d.amount,
            'Bulan Lalu': prev
        };
    });

    const paretoChartData = (analysis?.pareto || []).map((p: any) => ({
        name: p.name,
        Revenue: p.revenue,
        Margin: p.margin,
        Profit: p.profit,
        Quantity: p.quantity
    }));

    return (
        <div className="space-y-10 animate-in fade-in zoom-in-95 duration-700 pb-20">
            {/* Header & Control */}
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
                <div>
                    <button
                        onClick={onClose}
                        className="flex items-center gap-2 text-[#8B7E66] hover:text-[#2D3A2D] transition-colors mb-4 group"
                    >
                        <ArrowLeft className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Kembali ke OPS</span>
                    </button>
                    <h2 className="text-2xl md:text-4xl font-black text-[#1A241A] tracking-tighter flex items-center gap-3">
                        <span className="text-indigo-600 bg-indigo-100 p-2 rounded-2xl shadow-inner inline-flex items-center justify-center">🧠</span>
                        Intelligence <span className="text-indigo-600">Decision Hub</span>
                    </h2>
                    <p className="text-[#8B7E66] text-xs md:text-sm mt-2 font-medium">Analisis AI & Strategi Pertumbuhan Rasa Ibu</p>
                </div>

                <div className="px-6 py-3 md:py-2.5 bg-white border border-[#E5E1D8] rounded-2xl shadow-sm text-center md:text-left">
                    <p className="text-[8px] font-black text-[#8B7E66] uppercase tracking-[0.2em]">Deep Intelligence Engaged</p>
                    <p className="text-xs md:text-sm font-black text-[#2D3A2D]">v3.0_AI_ADVANCED</p>
                </div>
            </div>

            {/* Content Area */}
            <div className="space-y-12">
                {isLoading ? (
                    <div className="flex flex-col items-center justify-center py-32 space-y-6">
                        <div className="relative">
                            <div className="w-20 h-20 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
                            <Zap className="w-8 h-8 text-indigo-600 absolute inset-0 m-auto animate-pulse" />
                        </div>
                        <p className="text-xs font-black uppercase tracking-[0.3em] text-indigo-400">Mensintesa Data Operasional...</p>
                    </div>
                ) : error ? (
                    <div className="flex flex-col items-center justify-center py-32 space-y-6">
                        <div className="p-6 bg-rose-50 rounded-full">
                            <AlertTriangle className="w-10 h-10 text-rose-500" />
                        </div>
                        <div className="text-center space-y-2">
                            <p className="text-slate-600 font-medium italic">{error}</p>
                            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Pastikan koneksi stabil & data tersedia di sistem.</p>
                        </div>
                        <button
                            onClick={loadData}
                            className="px-8 py-3 bg-indigo-600 text-white rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200"
                        >
                            Coba Lagi
                        </button>
                    </div>
                ) : !analysis ? (
                    <div className="flex flex-col items-center justify-center py-32 space-y-4">
                        <p className="text-slate-400 font-medium italic">Gagal memuat data analisis. Pastikan transaksi tersedia.</p>
                    </div>
                ) : (
                    <div className="space-y-16">
                        {/* 1. Dashboard Row: Promo & Waste (The Strategic Focus) */}
                        <div className="grid grid-cols-1 xl:grid-cols-2 gap-12">
                            <PromoPerformance data={analysis.promo} />
                            <WasteAnalysis data={analysis.waste} />
                        </div>

                        {/* 2. Predictive Row: Procurement */}
                        <ProcurementForecast data={analysis.procurement} />

                        {/* Phase 12: Production Intelligence (Dapur Hari Ini) */}
                        <ProductionPlan brandId={brandId} />

                        {/* NEW: Smart Bundle Advisor */}
                        <BundleAdvisor brandId={brandId} />

                        {/* Phase 1: Customer Loyalty (Retention) */}
                        <div className="bg-white p-10 rounded-[3rem] border border-[#E5E1D8] shadow-sm">
                            <LoyaltyProgramDashboard brandId={brandId} />
                        </div>

                        {/* NEW: WhatsApp Connector & Automation Bridge */}
                        <WhatsAppConnector />

                        {/* Phase 1: WhatsApp Broadcast (Communication) */}
                        <WhatsAppBroadcast brandId={brandId} />

                        {/* Phase 11: RFM Customer Segmentation */}
                        <CustomerSegmentation brandId={brandId} />

                        {/* Phase 11 & Marketplace: Program Performance */}
                        <MarketplaceTracker brandId={brandId} />

                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                            {/* 1. Insights & Predictions */}
                            <div className="lg:col-span-4 space-y-8">
                                <div className="bg-white p-10 rounded-[2.5rem] border border-[#E5E1D8] shadow-sm">
                                    <div className="flex items-center gap-4 mb-8">
                                        <div className="p-3 bg-emerald-50 rounded-xl">
                                            <Target className="w-5 h-5 text-emerald-600" />
                                        </div>
                                        <h3 className="text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Temuan Utama</h3>
                                    </div>
                                    <div className="space-y-6">
                                        <div className="p-6 bg-slate-50 rounded-2xl border-l-4 border-indigo-500">
                                            <p className="text-[10px] font-black text-indigo-600 uppercase mb-2">Produk Primadona</p>
                                            <p className="text-lg font-black text-[#2D3A2D]">{analysis.pareto?.[0]?.name || '-'}</p>
                                            <p className="text-[10px] text-slate-400 mt-2">Menyumbang revenue tertinggi bulan ini.</p>
                                        </div>
                                        <div className="p-6 bg-slate-50 rounded-2xl border-l-4 border-emerald-500">
                                            <p className="text-[10px] font-black text-emerald-600 uppercase mb-2">Volume Pesanan</p>
                                            <p className="text-lg font-black text-[#2D3A2D]">{analysis.totalOrders || 0} Pesanan</p>
                                            <p className="text-[10px] text-slate-400 mt-2">Iterasi dapur berjalan stabil.</p>
                                        </div>
                                    </div>
                                </div>

                                {/* Heatmap Peak Hours */}
                                {analysis.heatmap && (
                                    <div className="bg-white p-8 rounded-[2.5rem] border border-[#E5E1D8] shadow-sm overflow-hidden">
                                        <h3 className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66] mb-6 flex items-center gap-2">
                                            <Zap size={14} className="text-amber-500" />
                                            Peak Interaction Heatmap
                                        </h3>
                                        <div className="grid grid-cols-[repeat(24,minmax(0,1fr))] gap-1">
                                            {analysis.heatmap.map((dayRow: number[], dIdx: number) => (
                                                dayRow.map((count: number, hIdx: number) => {
                                                    const intensity = Math.min(count * 25, 100);
                                                    return (
                                                        <div
                                                            key={`${dIdx}-${hIdx}`}
                                                            className="aspect-square rounded-[1px] transition-all hover:scale-150 hover:z-10 cursor-pointer"
                                                            style={{ backgroundColor: count > 0 ? `rgba(79, 70, 229, ${intensity / 100})` : '#F9F7F2' }}
                                                            title={`Hari ${['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'][dIdx]}, Jam ${hIdx}:00: ${count} order`}
                                                        ></div>
                                                    );
                                                })
                                            ))}
                                        </div>
                                        <div className="mt-4 flex justify-between text-[7px] font-black text-[#8B7E66] uppercase tracking-tighter opacity-50">
                                            <span>00:00</span>
                                            <span>Malam</span>
                                            <span>Pagi</span>
                                            <span>Siang</span>
                                            <span>18:00</span>
                                            <span>23:59</span>
                                        </div>
                                        <p className="text-[9px] text-indigo-600 font-bold mt-4 italic">
                                            "Bunda paling sibuk di hari {['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'][analysis.heatmap.map((d: any[]) => d.reduce((a: any, b: any) => a + b, 0)).indexOf(Math.max(...analysis.heatmap.map((d: any[]) => d.reduce((a: any, b: any) => a + b, 0))))]}."
                                        </p>
                                    </div>
                                )}

                                <div className="bg-[#2D3A2D] p-10 rounded-[2.5rem] text-[#FDFBF7] shadow-xl">
                                    <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-[#B2BCA2] mb-6">Rekomendasi Strategis</h3>
                                    <p className="text-sm font-medium leading-relaxed opacity-80 italic">
                                        "{analysis.pareto?.[0] ? `Pertahankan stok bumbu untuk ${analysis.pareto[0].name}. Tren menunjukkan peningkatan minat pada akhir pekan.` : 'Gunakan data transaksi untuk melihat pola penjualan produk Anda.'}"
                                    </p>
                                </div>
                            </div>

                            {/* Charts */}
                            <div className="lg:col-span-8 space-y-12">
                                <div className="bg-white p-10 rounded-[3rem] border border-[#E5E1D8] shadow-sm space-y-8">
                                    <div className="flex justify-between items-center">
                                        <div className="flex items-center gap-4">
                                            <LineChart className="w-5 h-5 text-[#8B7E66]" />
                                            <h3 className="text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Strategi Omzet vs Periode Sebelumnya</h3>
                                        </div>
                                    </div>
                                    <div className="h-[300px]">
                                        <AnalyticsChart
                                            data={trendChartData}
                                            type="area"
                                            dataKeys={[
                                                { key: 'Bulan Ini', name: 'Bulan Ini', color: '#2D3A2D' },
                                                { key: 'Bulan Lalu', name: 'Periode Sebelumnya', color: '#B2BCA2' }
                                            ]}
                                        />
                                    </div>
                                </div>

                                <div className="bg-white p-10 rounded-[3rem] border border-[#E5E1D8] shadow-sm space-y-8">
                                    <div className="flex justify-between items-center">
                                        <div className="flex items-center gap-4">
                                            <div className="p-2 bg-amber-50 rounded-lg">
                                                <Target className="w-4 h-4 text-[#8B7E66]" />
                                            </div>
                                            <h3 className="text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Matriks Pareto (Profitabilitas Produk)</h3>
                                        </div>
                                    </div>
                                    <div className="h-[300px]">
                                        <AnalyticsChart
                                            data={paretoChartData}
                                            type="bar"
                                            dataKeys={[
                                                { key: 'Revenue', name: 'Revenue', color: '#B2BCA2' },
                                                { key: 'Profit', name: 'Estimasi Profit', color: '#2D3A2D' }
                                            ]}
                                        />
                                    </div>
                                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                                        {analysis.pareto?.slice(0, 4).map((p: any, i: number) => (
                                            <div key={i} className="p-4 bg-[#F9F7F2] rounded-2xl border border-[#E5E1D8]">
                                                <p className="text-[8px] font-black uppercase text-[#8B7E66] truncate">{p.name}</p>
                                                <p className="text-sm font-black text-[#2D3A2D]">{Math.round(p.margin)}% Margin</p>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Brand Configuration Section */}
                        <IntelligenceConfig brandId={brandId} />
                    </div>
                )}
                <div className="pt-10 border-t border-[#E5E1D8] text-center">
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-[0.2em]">
                        Intelligence Engine v3.0 • Data tersinkronisasi otomatis dengan Buku Besar
                    </p>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { getLedgerEntriesAction } from '@/lib/actions/rasa-ibu/finance';
import { FileText, X } from 'lucide-react';

interface LedgerModalProps {
    brandId: string;
    onClose: () => void;
}

export default function LedgerModal({ brandId, onClose }: LedgerModalProps) {
    const [entries, setEntries] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    useEffect(() => {
        const load = async () => {
            const res = await getLedgerEntriesAction(brandId);
            if (res.success) {
                setEntries(res.data);
            }
            setIsLoading(false);
        };
        load();
    }, [brandId]);

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#1A241A]/60 backdrop-blur-md p-6">
            <div className="bg-[#FDFBF7] w-full max-w-5xl max-h-[85vh] rounded-[3rem] shadow-2xl border border-[#E5E1D8] overflow-hidden flex flex-col animate-in fade-in zoom-in duration-500">
                {/* Header */}
                <div className="px-12 py-10 border-b border-[#E5E1D8] bg-white flex justify-between items-center">
                    <div className="flex items-center gap-6">
                        <div className="p-4 bg-amber-50 rounded-2xl">
                            <FileText className="w-8 h-8 text-[#8B7E66]" />
                        </div>
                        <div className="space-y-1">
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66]">Executive Transparency</span>
                            <h2 className="text-3xl font-black text-[#2D3A2D]">Buku Besar RASA IBU</h2>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-3 hover:bg-slate-100 rounded-full transition-colors"
                    >
                        <X className="w-6 h-6 text-slate-400" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-12">
                    {isLoading ? (
                        <div className="flex flex-col items-center justify-center py-20 space-y-4">
                            <div className="w-12 h-12 border-4 border-amber-200 border-t-[#8B7E66] rounded-full animate-spin"></div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Menyusun Catatan...</p>
                        </div>
                    ) : (
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="bg-[#F9F7F2] text-[10px] font-black uppercase tracking-[0.2em] text-[#8B7E66] border-b border-[#E5E1D8]">
                                    <th className="px-8 py-5">Tanggal</th>
                                    <th className="px-8 py-5">Keterangan / Transaksi</th>
                                    <th className="px-8 py-5">Akun Ledger</th>
                                    <th className="px-8 py-5 text-right">Debit (+)</th>
                                    <th className="px-8 py-5 text-right">Kredit (-)</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-[#F9F7F2]">
                                {entries.map((entry) => (
                                    <tr key={entry.id} className="hover:bg-white transition-colors group">
                                        <td className="px-8 py-6 text-[11px] font-medium text-slate-400">
                                            {new Date(entry.transaction.date).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })}
                                        </td>
                                        <td className="px-8 py-6">
                                            <div className="space-y-1">
                                                <p className="text-xs font-black text-[#1A241A]">{entry.transaction.description}</p>
                                                <p className="text-[9px] text-slate-400 uppercase tracking-tighter">REF: {entry.transaction.reference || 'SYSTEM'}</p>
                                            </div>
                                        </td>
                                        <td className="px-8 py-6">
                                            <span className="text-[10px] font-bold text-[#8B7E66] px-3 py-1 bg-amber-50 rounded-lg">
                                                {entry.account.name}
                                            </span>
                                        </td>
                                        <td className="px-8 py-6 text-right font-black text-emerald-600 text-xs">
                                            {entry.debit > 0 ? currency.format(entry.debit) : '-'}
                                        </td>
                                        <td className="px-8 py-6 text-right font-black text-red-400 text-xs">
                                            {entry.credit > 0 ? currency.format(entry.credit) : '-'}
                                        </td>
                                    </tr>
                                ))}
                                {entries.length === 0 && (
                                    <tr>
                                        <td colSpan={5} className="px-8 py-20 text-center text-slate-400 italic text-xs">
                                            Belum ada catatan transaksi yang terdaftar di buku besar.
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    )}
                </div>

                {/* Footer Info */}
                <div className="px-12 py-8 bg-white border-t border-[#E5E1D8] flex justify-between items-center text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                    <span>Otoritas: Owner Persona</span>
                    <span>Neraca Terakhir: {new Date().toLocaleDateString('id-ID')}</span>
                </div>
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import { Star, TrendingUp, Calendar, ChevronRight, Info, Award } from 'lucide-react';

interface LoyaltySettingsPanelProps {
    settings: any;
    onSettingsUpdate: (newSettings: any) => void;
}

export default function LoyaltySettingsPanel({ settings, onSettingsUpdate }: LoyaltySettingsPanelProps) {
    const loyalty = settings.loyalty || {
        pointsPerRupiah: 0.0001,
        tierThresholds: {
            SILVER: 1000000,
            GOLD: 5000000,
            PLATINUM: 10000000
        },
        pointExpiryDays: 365
    };

    const updateLoyalty = (field: string, value: any) => {
        onSettingsUpdate({
            ...settings,
            loyalty: {
                ...loyalty,
                [field]: value
            }
        });
    };

    const updateTier = (tier: string, value: number) => {
        onSettingsUpdate({
            ...settings,
            loyalty: {
                ...loyalty,
                tierThresholds: {
                    ...loyalty.tierThresholds,
                    [tier]: value
                }
            }
        });
    };

    // Helper to convert multiplier/ratio to "Points per Rp 10.000"
    const pointsPer10k = (loyalty.pointsPerRupiah * 10000).toFixed(2);

    return (
        <section className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center gap-2 border-b border-[#F9F7F2] pb-4">
                <Star className="w-4 h-4 text-purple-600" />
                <h3 className="text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Loyalty Member Configuration</h3>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Point System Configuration */}
                <div className="bg-white border border-[#E5E1D8] p-8 rounded-[2rem] shadow-sm hover:shadow-md transition-all space-y-6">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-purple-50 text-purple-600 rounded-2xl">
                            <Award className="w-5 h-5" />
                        </div>
                        <div>
                            <h4 className="text-sm font-black text-[#2D3A2D] uppercase tracking-wider">Perolehan Poin</h4>
                            <p className="text-[10px] text-[#8B7E66] font-medium">Atur berapa poin yang didapat pelanggan</p>
                        </div>
                    </div>

                    <div className="space-y-4">
                        <div className="space-y-2">
                            <label className="text-[10px] font-bold text-[#8B7E66] uppercase tracking-widest flex items-center gap-1">
                                Poin per Rp 10.000 <Info className="w-3 h-3 text-slate-300" />
                            </label>
                            <div className="relative">
                                <input
                                    type="number"
                                    step="0.1"
                                    value={pointsPer10k}
                                    onChange={(e) => {
                                        const val = parseFloat(e.target.value) || 0;
                                        updateLoyalty('pointsPerRupiah', val / 10000);
                                    }}
                                    className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm font-black focus:outline-none focus:border-purple-600 pr-12"
                                />
                                <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-[#8B7E66]">PTS</span>
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] font-bold text-[#8B7E66] uppercase tracking-widest flex items-center gap-1">
                                Nilai Tukar Poin <Info className="w-3 h-3 text-slate-300" />
                            </label>
                            <div className="relative">
                                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-[#8B7E66]">Rp</span>
                                <input
                                    type="number"
                                    value={loyalty.pointValueInRupiah || 100}
                                    onChange={(e) => updateLoyalty('pointValueInRupiah', parseInt(e.target.value) || 0)}
                                    className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-xl px-10 py-3 text-sm font-black focus:outline-none focus:border-purple-600"
                                />
                            </div>
                            <p className="text-[9px] text-slate-400 font-medium italic">Nilai Rupiah yang didapat pelanggan per 1 poin saat ditukar.</p>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] font-bold text-[#8B7E66] uppercase tracking-widest">Masa Berlaku Poin</label>
                            <div className="relative">
                                <input
                                    type="number"
                                    value={loyalty.pointExpiryDays}
                                    onChange={(e) => updateLoyalty('pointExpiryDays', parseInt(e.target.value) || 0)}
                                    className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm font-black focus:outline-none focus:border-purple-600 pr-16"
                                />
                                <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-[#8B7E66]">HARI</span>
                            </div>
                            <p className="text-[9px] text-slate-400 font-medium italic">Poin akan otomatis hangus setelah masa berlaku habis.</p>
                        </div>
                    </div>
                </div>

                {/* Tier Thresholds */}
                <div className="bg-white border border-[#E5E1D8] p-8 rounded-[2rem] shadow-sm hover:shadow-md transition-all space-y-6">
                    <div className="flex items-center gap-3">
                        <div className="p-3 bg-emerald-50 text-emerald-600 rounded-2xl">
                            <TrendingUp className="w-5 h-5" />
                        </div>
                        <div>
                            <h4 className="text-sm font-black text-[#2D3A2D] uppercase tracking-wider">Ambang Batas Tier</h4>
                            <p className="text-[10px] text-[#8B7E66] font-medium">Total belanja untuk naik level</p>
                        </div>
                    </div>

                    <div className="space-y-5">
                        {['SILVER', 'GOLD', 'PLATINUM'].map((tier) => (
                            <div key={tier} className="space-y-2">
                                <div className="flex justify-between items-center">
                                    <label className="text-[10px] font-bold text-[#8B7E66] uppercase tracking-widest flex items-center gap-2">
                                        <div className={`w-2 h-2 rounded-full ${tier === 'SILVER' ? 'bg-slate-300' :
                                            tier === 'GOLD' ? 'bg-amber-400' : 'bg-purple-500'
                                            }`} />
                                        {tier} Threshold
                                    </label>
                                    <span className="text-[9px] font-black text-emerald-600">IDR</span>
                                </div>
                                <div className="relative">
                                    <input
                                        type="number"
                                        value={loyalty.tierThresholds[tier]}
                                        onChange={(e) => updateTier(tier, parseInt(e.target.value) || 0)}
                                        className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm font-black focus:outline-none focus:border-emerald-600"
                                    />
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-1 opacity-20 group-hover:opacity-100">
                                        <ChevronRight size={14} />
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            <div className="p-6 bg-amber-50/50 border border-amber-100 rounded-2xl flex gap-4 items-start">
                <div className="p-2 bg-amber-100 text-amber-700 rounded-lg shrink-0">
                    <Info size={16} />
                </div>
                <div className="space-y-1">
                    <h5 className="text-[11px] font-black text-amber-900 uppercase">Penting!</h5>
                    <p className="text-[10px] text-amber-800 leading-relaxed font-medium">
                        Perubahan aturan loyalitas hanya akan berlaku untuk transaksi <b>mendatang</b>. Poin yang sudah dimiliki pelanggan dan status tier saat ini tidak akan berubah secara otomatis.
                    </p>
                </div>
            </div>
        </section>
    );
}

import React from 'react';
import { updateOrderStatus } from '@/lib/actions/rasa-ibu/orders';

const STATUS_LABELS: Record<string, string> = {
    'DIPESAN': 'Pesan Tercatat',
    'MENUNGGU_VERIFIKASI_QRIS': '🔍 Verifikasi QRIS',
    'DIBAYAR': 'Sudah Dibayar',
    'DISIAPKAN': 'Sedang Disiapkan',
    'DIKIRIM': 'Sedang Diantar',
    'SELESAI': 'Selesai',
};

const STATUS_COLORS: Record<string, string> = {
    'DIPESAN': 'bg-stone-50 text-stone-600 border-stone-200',
    'MENUNGGU_VERIFIKASI_QRIS': 'bg-amber-50 text-amber-700 border-amber-200 animate-pulse',
    'DIBAYAR': 'bg-blue-50 text-blue-700 border-blue-200',
    'DISIAPKAN': 'bg-emerald-50 text-emerald-700 border-emerald-200',
    'DIKIRIM': 'bg-indigo-50 text-indigo-700 border-indigo-200',
    'SELESAI': 'bg-slate-100 text-slate-500 border-slate-200',
};

const SOURCE_ICONS: Record<string, string> = {
    'WHATSAPP': '📱',
    'WEBSITE': '🌐',
    'SHOPEE': '🛍️',
    'GRABFOOD': '🟢',
    'GOFOOD': '🔴'
};

interface ManualOrderLedgerProps {
    orders: any[];
    onOpenIngestion: () => void;
    onOpenOrderEntry: () => void;
    onOpenReceipt: (order: any) => void;
    onOpenQRISPayment: (order: any) => void;
    onOpenPaymentVerification: () => void;
    onToggleFullscreen?: () => void;
    isFullscreen?: boolean;
}

export default function ManualOrderLedger({
    orders,
    onOpenIngestion,
    onOpenOrderEntry,
    onOpenReceipt,
    onOpenQRISPayment,
    onOpenPaymentVerification,
    onToggleFullscreen,
    isFullscreen = false
}: ManualOrderLedgerProps) {
    const [searchQuery, setSearchQuery] = React.useState('');
    const sortedOrders = [...orders]
        .filter(order => {
            const searchLower = searchQuery.toLowerCase();
            return (
                order.customerName?.toLowerCase().includes(searchLower) ||
                order.manualRef?.toLowerCase().includes(searchLower) ||
                order.customerAddress?.toLowerCase().includes(searchLower) ||
                order.channel?.toLowerCase().includes(searchLower)
            );
        })
        .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    return (
        <div suppressHydrationWarning className={`bg-white border border-[#E5E1D8] ${isFullscreen ? 'rounded-none border-none min-h-screen' : 'rounded-[3rem] shadow-sm shadow-stone-200/50'} overflow-hidden transition-all duration-500`}>
            <div className={`px-6 py-6 border-b border-[#F9F7F2] flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white ${isFullscreen ? 'sticky top-0 z-20 shadow-sm' : ''}`}>
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-[#2D3A2D] rounded-lg flex items-center justify-center">
                        <span className="text-sm">📋</span>
                    </div>
                    <div>
                        <h3 className="text-sm font-black text-[#2D3A2D] uppercase tracking-widest">Buku Pesanan RASA IBU</h3>
                        {isFullscreen && <p className="text-[10px] text-[#8B7E66] font-bold uppercase tracking-widest opacity-60">Operational Fullscreen View</p>}
                    </div>
                </div>

                {/* Integrated Search Bar */}
                <div className="flex-1 max-w-md w-full relative group">
                    <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
                        <span className="text-stone-400 group-focus-within:text-[#2D3A2D] transition-colors">🔍</span>
                    </div>
                    <input
                        type="text"
                        placeholder="Cari Bunda, Ref, atau Alamat..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full bg-[#F9F7F2] border border-[#E5E1D8] rounded-2xl py-2.5 pl-11 pr-4 text-xs font-bold text-[#2D3A2D] placeholder:text-stone-400 focus:outline-none focus:ring-2 focus:ring-[#2D3A2D]/10 focus:border-[#2D3A2D] transition-all"
                    />
                </div>

                <div className="flex items-center gap-3 w-full md:w-auto">
                    <button
                        onClick={onOpenIngestion}
                        className="text-[10px] font-black uppercase tracking-[0.2em] text-[#8B7E66] border border-[#E5E1D8] px-5 py-2.5 rounded-xl hover:bg-stone-50 transition-all shadow-sm"
                    >
                        📥 Impor
                    </button>
                    <button
                        onClick={onOpenOrderEntry}
                        className="text-[10px] font-black uppercase tracking-[0.2em] text-[#FDFBF7] bg-[#2D3A2D] px-5 py-2.5 rounded-xl hover:shadow-xl hover:bg-[#1A241A] transition-all shadow-lg shadow-green-900/10 flex-1 md:flex-none text-center"
                    >
                        + Catat Baru
                    </button>
                    {onToggleFullscreen && (
                        <button
                            onClick={onToggleFullscreen}
                            className={`p-2.5 rounded-xl border border-[#E5E1D8] transition-all ${isFullscreen ? 'bg-[#2D3A2D] text-white border-[#2D3A2D]' : 'bg-white text-[#8B7E66] hover:bg-stone-50'}`}
                            title={isFullscreen ? 'Minimize' : 'Maximize'}
                        >
                            {isFullscreen ? (
                                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M8 3v3a2 2 0 0 1-2 2H3m18 0h-3a2 2 0 0 1-2-2V3m0 18v-3a2 2 0 0 1 2-2h3M3 16h3a2 2 0 0 1 2 2v3" /></svg>
                            ) : (
                                <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" /></svg>
                            )}
                        </button>
                    )}
                </div>
            </div>

            <div className={`overflow-x-auto ${isFullscreen ? 'pb-10' : ''}`}>
                <table className="w-full text-left">
                    <thead className={`bg-[#F9F7F2] text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] border-b border-slate-100 ${isFullscreen ? 'sticky top-[81px] z-10' : ''}`}>
                        <tr>
                            <th className="px-6 py-5">Sumber</th>
                            <th className="px-6 py-5">Pelanggan / Ref</th>
                            <th className="px-6 py-5">Pengiriman</th>
                            <th className="px-6 py-5">Outlet</th>
                            <th className="px-6 py-5">Status</th>
                            <th className="px-6 py-5 text-right">Total</th>
                            <th className="px-6 py-5 text-right">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                        {sortedOrders.map((order) => {
                            const isAttentionNeeded = order.status === 'DIPESAN';

                            // Detect if order is "Frozen-Only"
                            const orderItems = order.orderItems || [];
                            const isFrozenOnly = orderItems.length > 0 && orderItems.every((item: any) =>
                                item.frozenVariant?.product?.category?.slug === 'frozen' ||
                                item.frozenVariant?.product?.category?.name?.toLowerCase().includes('frozen')
                            );

                            return (
                                <tr key={order.id} className={`hover:bg-[#FDFBF7]/50 transition-colors ${isAttentionNeeded ? 'bg-amber-50/20' : ''}`}>
                                    <td className="px-6 py-6">
                                        <div className="flex items-center gap-2">
                                            <span className="text-xl grayscale hover:grayscale-0 transition-all cursor-help" title={order.channel || 'Manual'}>
                                                {SOURCE_ICONS[order.channel as keyof typeof SOURCE_ICONS] || '❓'}
                                            </span>
                                            <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest whitespace-nowrap">
                                                {order.channel || 'Manual'}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-6">
                                        <div className="space-y-1">
                                            <div className="flex items-center gap-2">
                                                <p className="text-xs font-black text-[#1A241A] whitespace-nowrap">{order.customerName}</p>
                                                {order.subscriptionId && (
                                                    <span className="px-2 py-0.5 bg-purple-100 text-purple-700 border border-purple-200 rounded-md text-[8px] font-black uppercase tracking-wider">
                                                        🔄 Langganan
                                                    </span>
                                                )}
                                            </div>
                                            {order.manualRef && (
                                                <p className="text-[9px] font-medium text-slate-400 tracking-tighter">REF: {order.manualRef}</p>
                                            )}
                                            {order.customerAddress && (
                                                <p className="text-[9px] text-indigo-700 bg-indigo-50/50 px-2 py-1 rounded inline-block max-w-[250px] truncate font-bold">
                                                    📍 {order.customerAddress}
                                                </p>
                                            )}
                                            {order.customerNote && (
                                                <div className="mt-2 p-2 bg-amber-50 rounded border border-amber-100 max-w-[250px]">
                                                    <p className="text-[9px] font-black text-amber-800 uppercase tracking-widest mb-1">📝 Catatan Customer:</p>
                                                    <p className="text-[9px] text-amber-700 leading-relaxed font-medium">"{order.customerNote}"</p>
                                                </div>
                                            )}
                                        </div>
                                    </td>
                                    <td className="px-6 py-6">
                                        {(() => {
                                            const deliveryMatch = order.customerNote?.match(/^\[(.*?)\]/);
                                            const deliveryInfo = deliveryMatch ? deliveryMatch[1] : null;

                                            if (!deliveryInfo) return <span className="text-slate-300 italic text-[10px]">Cek Manual</span>;

                                            const [method, courier] = deliveryInfo.split(' - ');
                                            return (
                                                <div className="flex flex-col gap-1 min-w-[100px]">
                                                    <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-tight text-center border ${method === 'Kurir Instan'
                                                        ? 'bg-indigo-50 text-indigo-700 border-indigo-100'
                                                        : 'bg-emerald-50 text-emerald-700 border-emerald-100'
                                                        }`}>
                                                        {method}
                                                    </span>
                                                    {courier && (
                                                        <span className="text-[9px] font-black text-[#8B7E66] uppercase text-center">{courier}</span>
                                                    )}
                                                </div>
                                            );
                                        })()}
                                    </td>
                                    <td className="px-6 py-6">
                                        <div className="flex items-center gap-2">
                                            <div className="w-2 h-2 bg-amber-400 rounded-full animate-pulse" />
                                            <span className="text-[10px] font-black text-[#2D3A2D] uppercase tracking-widest whitespace-nowrap">
                                                {order.warehouse?.name || 'Dapur Ibu'}
                                            </span>
                                        </div>
                                    </td>
                                    <td className="px-6 py-6">
                                        <span className={`px-4 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-wider whitespace-nowrap ${STATUS_COLORS[order.status] || 'bg-slate-50'}`}>
                                            {STATUS_LABELS[order.status] || order.status}
                                        </span>
                                    </td>
                                    <td className="px-6 py-6 text-right font-black text-[#1A241A] text-sm whitespace-nowrap">
                                        Rp {(Number(order.totalAmount || order.total || 0)).toLocaleString('id-ID')}
                                    </td>
                                    <td className="px-6 py-6 text-right">
                                        <div className="flex justify-end gap-2 flex-nowrap">
                                            <button
                                                onClick={() => onOpenReceipt(order)}
                                                className="text-[9px] font-black uppercase text-amber-600 border border-amber-200 px-3 py-2 rounded-xl bg-amber-50 hover:bg-amber-100 transition-all shadow-sm"
                                            >
                                                Nota
                                            </button>
                                            {order.status === 'DIPESAN' && (
                                                <div className="flex gap-2">
                                                    <button
                                                        onClick={() => onOpenQRISPayment(order)}
                                                        className="text-[9px] font-black uppercase text-purple-600 border border-purple-200 px-3 py-2 rounded-xl bg-purple-50 hover:bg-purple-100 transition-all shadow-sm"
                                                    >
                                                        QRIS
                                                    </button>
                                                    <button
                                                        onClick={() => updateOrderStatus(order.id, 'DIBAYAR')}
                                                        className="text-[9px] font-black uppercase text-blue-600 border border-blue-200 px-3 py-2 rounded-xl bg-blue-50 hover:bg-blue-100 transition-all shadow-sm"
                                                    >
                                                        Cash
                                                    </button>
                                                </div>
                                            )}
                                            {order.status === 'MENUNGGU_VERIFIKASI_QRIS' && (
                                                <button
                                                    onClick={onOpenPaymentVerification}
                                                    className="text-[9px] font-black uppercase text-amber-600 border border-amber-200 px-3 py-2 rounded-xl bg-amber-50 hover:bg-amber-100 transition-all shadow-sm flex items-center gap-2"
                                                >
                                                    Cek Bukti
                                                </button>
                                            )}
                                            {order.status === 'DIBAYAR' && (
                                                <button
                                                    onClick={() => updateOrderStatus(order.id, 'DISIAPKAN')}
                                                    className="text-[9px] font-black uppercase text-emerald-600 border border-emerald-200 px-3 py-2 rounded-xl bg-emerald-50 hover:bg-emerald-100 transition-all shadow-sm"
                                                >
                                                    {isFrozenOnly ? '🧤 Siapkan' : '🍳 Masak'}
                                                </button>
                                            )}
                                            {order.status === 'DISIAPKAN' && (
                                                <button
                                                    onClick={() => updateOrderStatus(order.id, 'DIKIRIM')}
                                                    className="text-[9px] font-black uppercase text-indigo-600 border border-indigo-200 px-3 py-2 rounded-xl bg-indigo-50 hover:bg-indigo-100 transition-all shadow-sm"
                                                >
                                                    {isFrozenOnly ? '📦 Pack' : '🚚 Antar'}
                                                </button>
                                            )}
                                            {order.status === 'DIKIRIM' && (
                                                <button
                                                    onClick={() => updateOrderStatus(order.id, 'SELESAI')}
                                                    className="text-[9px] font-black uppercase text-slate-600 border border-slate-200 px-3 py-2 rounded-xl bg-slate-50 hover:bg-slate-100 transition-all shadow-sm"
                                                >
                                                    Selesai
                                                </button>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            );
                        })}
                        {sortedOrders.length === 0 && (
                            <tr>
                                <td colSpan={7} className="px-6 py-24 text-center">
                                    <div className="flex flex-col items-center gap-4 opacity-40">
                                        <span className="text-4xl">🔎</span>
                                        <p className="text-slate-400 italic text-sm font-bold uppercase tracking-widest">
                                            {searchQuery ? `Tidak ada hasil untuk "${searchQuery}"` : 'Belum ada pesanan terdaftar hari ini.'}
                                        </p>
                                    </div>
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { createManualOrder, getUnlinkedAutoOrdersAction } from '@/lib/actions/rasa-ibu/orders';
import { getWarehousesAction } from '@/lib/actions/rasa-ibu/warehouse';
import { getCustomerProfileByPhoneAction } from '@/lib/actions/commerce/customers';
import { getPlatformSettingsAction } from '@/lib/actions/rasa-ibu/finance';
import { X, Loader2, UserCheck, Sparkles } from 'lucide-react';
import { toast } from 'sonner';

export default function OrderEntryModal({ brandId, products, onClose }: { brandId: string; products: any[]; onClose: () => void }) {
    const [customerName, setCustomerName] = useState('');
    const [customerPhone, setCustomerPhone] = useState('');
    const [customerAddress, setCustomerAddress] = useState('');
    const [customerEmail, setCustomerEmail] = useState('');
    const [source, setSource] = useState('WHATSAPP');
    const [manualRef, setManualRef] = useState('');
    const [internalNotes, setInternalNotes] = useState('');
    const [selectedWarehouseId, setSelectedWarehouseId] = useState('');
    const [warehouses, setWarehouses] = useState<any[]>([]);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isAutofilling, setIsAutofilling] = useState(false);
    const [loyaltyInfo, setLoyaltyInfo] = useState<any>(null);
    const [pointValue, setPointValue] = useState<number>(100);

    // Cart state
    const [cart, setCart] = useState<any[]>([]);
    const [selectedProductId, setSelectedProductId] = useState('');
    const [quantity, setQuantity] = useState<string>('1');
    const [usePoints, setUsePoints] = useState(false);

    // Linking state
    const [unlinkedOrders, setUnlinkedOrders] = useState<any[]>([]);
    const [selectedSkeletonId, setSelectedSkeletonId] = useState('');

    useEffect(() => {
        async function fetchWarehouses() {
            const res = await getWarehousesAction(brandId);
            if (res.success && res.data) {
                setWarehouses(res.data);
                const defaultWh = res.data.find((w: any) => w.isDefault);
                if (defaultWh) setSelectedWarehouseId(defaultWh.id);
            }
        }
        fetchWarehouses();

        async function fetchConfig() {
            const res = await getPlatformSettingsAction(brandId);
            if (res.success && res.settings?.loyalty) {
                setPointValue(res.settings.loyalty.pointValueInRupiah || 100);
            }
        }
        fetchConfig();
    }, [brandId]);

    // AUTOFILL Logic
    const handlePhoneBlur = async () => {
        if (customerPhone.length >= 10 && !customerName) {
            setIsAutofilling(true);
            const res = await getCustomerProfileByPhoneAction(brandId, customerPhone);
            setIsAutofilling(false);

            if (res.success && res.data?.isRepeatCustomer) {
                if (!customerName) setCustomerName(res.data.name);
                if (!customerAddress) setCustomerAddress(res.data.address);
                if (!customerEmail) setCustomerEmail(res.data.email);
                if (res.data.loyalty) {
                    setLoyaltyInfo(res.data.loyalty);
                    if (res.data.loyalty.availablePoints > 0) {
                        setUsePoints(true);
                    }
                }
                toast.success('Data pelanggan ditemukan otomatis!');
            }
        }
    };

    // Fetch unlinked skeleton orders when channel changes
    useEffect(() => {
        async function fetchUnlinked() {
            if (['SHOPEE', 'GRABFOOD', 'GOFOOD'].includes(source)) {
                const res = await getUnlinkedAutoOrdersAction(brandId, source);
                if (res.success && res.data) {
                    setUnlinkedOrders(res.data);
                } else {
                    setUnlinkedOrders([]);
                }
            } else {
                setUnlinkedOrders([]);
            }
            setSelectedSkeletonId(''); // Reset selection
        }
        fetchUnlinked();
    }, [source, brandId]);

    const selectedProduct = products.find(p => p.id === selectedProductId);
    const stockOnHand = selectedProduct?.variants?.[0]?.stockOnHand || 0;
    const isLowStock = stockOnHand < Number(quantity);

    const handleAddToCart = () => {
        if (!selectedProduct || isLowStock) return;

        const variant = selectedProduct.variants?.[0];
        if (!variant) return;

        const newItem = {
            productId: selectedProduct.id,
            variantId: variant.id,
            name: selectedProduct.name,
            quantity: Number(quantity),
            price: Number(variant.price),
            subtotal: Number(variant.price) * Number(quantity)
        };

        setCart([...cart, newItem]);
        // Reset selection
        setSelectedProductId('');
        setQuantity('1');
    };

    const handleRemoveFromCart = (index: number) => {
        const newCart = [...cart];
        newCart.splice(index, 1);
        setCart(newCart);
    };

    const cartTotal = cart.reduce((sum, item) => sum + item.subtotal, 0);
    const availableToUse = loyaltyInfo?.availablePoints || 0;
    const discountValue = usePoints ? availableToUse * pointValue : 0;
    const finalTotal = Math.max(0, cartTotal - discountValue);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (cart.length === 0) {
            toast.error('Mohon tambah minimal 1 produk ke pesanan.');
            return;
        }

        setIsSubmitting(true);
        const res = await createManualOrder({
            brandId,
            customerName,
            customerPhone: customerPhone || undefined,
            items: cart,
            channel: source,
            customerEmail: customerEmail || undefined,
            internalNotes: internalNotes || undefined,
            manualRef: manualRef || undefined,
            warehouseId: selectedWarehouseId || undefined,
            totalAmount: finalTotal,
            existingOrderId: selectedSkeletonId || undefined,
            // @ts-ignore
            redeemedPoints: usePoints ? availableToUse : 0
        });

        if (res.success) {
            toast.success('✅ Pesanan berhasil disimpan!');
            setTimeout(() => window.location.reload(), 1000);
        } else {
            toast.error(`❌ Error: ${res.error}`);
            console.error('Order creation failed:', res.error);
        }
        setIsSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#2D3A2D]/40 backdrop-blur-sm p-6">
            <div className="bg-[#FDFBF7] w-full max-w-2xl max-h-[90vh] rounded-[2.5rem] shadow-2xl border border-[#E5E1D8] overflow-hidden flex flex-col animate-in fade-in zoom-in duration-300">
                <div className="px-10 py-8 border-b border-[#E5E1D8] flex justify-between items-center bg-white shrink-0">
                    <div className="space-y-1">
                        <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66]">Pencatatan Manual</span>
                        <h2 className="text-2xl font-black text-[#2D3A2D]">Tambah Pesanan Baru</h2>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-2 hover:bg-slate-100 rounded-full transition-colors"
                    >
                        <X className="w-6 h-6 text-slate-400" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto custom-scrollbar flex flex-col">
                    <div className="flex-1 overflow-y-auto px-10 py-6 space-y-8 custom-scrollbar">
                        {/* Customer Info */}
                        <div className="space-y-6">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Nomor WhatsApp</label>
                                    <input
                                        value={customerPhone}
                                        onBlur={handlePhoneBlur}
                                        onChange={(e) => setCustomerPhone(e.target.value)}
                                        className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#B2BCA2]"
                                        placeholder="081234..."
                                    />
                                    {loyaltyInfo && (
                                        <div className="flex items-center gap-1 text-[9px] font-bold text-indigo-600">
                                            <Sparkles className="w-3 h-3" /> Pelanggan Setia: {loyaltyInfo.availablePoints} Poin
                                        </div>
                                    )}
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Nama Pelanggan</label>
                                    <div className="relative">
                                        <input
                                            required
                                            value={customerName}
                                            onChange={(e) => setCustomerName(e.target.value)}
                                            className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#B2BCA2]"
                                            placeholder="Contoh: Bunda Sarah"
                                        />
                                        {isAutofilling && (
                                            <div className="absolute right-3 top-1/2 -translate-y-1/2">
                                                <Loader2 className="w-4 h-4 animate-spin text-slate-300" />
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Alamat Lengkap</label>
                                <textarea
                                    value={customerAddress}
                                    onChange={(e) => setCustomerAddress(e.target.value)}
                                    className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-[#B2BCA2] h-20"
                                    placeholder="Alamat pengiriman Bunda..."
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Alamat Email (PENTING)</label>
                                    <input
                                        required
                                        type="email"
                                        value={customerEmail}
                                        onChange={(e) => setCustomerEmail(e.target.value)}
                                        className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-200"
                                        placeholder="bunda@email.com"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Sumber Pesanan</label>
                                    <select
                                        value={source}
                                        onChange={(e) => setSource(e.target.value)}
                                        className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm focus:outline-none"
                                    >
                                        <option value="WHATSAPP">WhatsApp (Legacy)</option>
                                        <option value="QRIS">QRIS Direct</option>
                                        <option value="WEBSITE">Website</option>
                                        <option value="SHOPEE">Shopee</option>
                                        <option value="GRABFOOD">GrabFood</option>
                                        <option value="GOFOOD">GoFood</option>
                                    </select>
                                </div>
                            </div>
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">No. Ref (Opsional)</label>
                            <input
                                value={manualRef}
                                onChange={(e) => setManualRef(e.target.value)}
                                className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm focus:outline-none"
                                placeholder="Ref marketplace..."
                            />
                        </div>

                        {unlinkedOrders.length > 0 && (
                            <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 space-y-2 animate-in slide-in-from-top-2">
                                <div className="flex items-start gap-3">
                                    <div className="p-2 bg-amber-100 rounded-full text-amber-600">
                                        <Loader2 className="w-4 h-4" />
                                    </div>
                                    <div className="flex-1 space-y-2">
                                        <div>
                                            <h4 className="text-xs font-black text-amber-800 uppercase tracking-wide">Hubungkan dengan Pending Order?</h4>
                                            <p className="text-[10px] text-amber-700 leading-relaxed">
                                                Ditemukan {unlinkedOrders.length} order dari Settlement {source} yang belum memiliki detail item.
                                                Pilih salah satu jika Anda sedang menginput detail untuk order tersebut.
                                            </p>
                                        </div>

                                        <select
                                            value={selectedSkeletonId}
                                            onChange={(e) => {
                                                setSelectedSkeletonId(e.target.value);
                                                const sel = unlinkedOrders.find(o => o.id === e.target.value);
                                                if (sel) {
                                                    setManualRef(sel.externalOrderId || '');
                                                }
                                            }}
                                            className="w-full bg-white border border-amber-300 text-amber-900 text-xs rounded-xl px-3 py-2 focus:outline-none focus:ring-2 focus:ring-amber-400"
                                        >
                                            <option value="">-- Buat Order Baru (Jangan Hubungkan) --</option>
                                            {unlinkedOrders.map(Order => (
                                                <option key={Order.id} value={Order.id}>
                                                    {Order.externalOrderId} — Rp {Order.total.toLocaleString()} — {new Date(Order.date).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                </option>
                                            ))}
                                        </select>
                                    </div>
                                </div>
                            </div>
                        )}

                        {warehouses.length > 0 && (
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Outlet Fulfillment (Dapur)</label>
                                <select
                                    required
                                    value={selectedWarehouseId}
                                    onChange={(e) => setSelectedWarehouseId(e.target.value)}
                                    className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm focus:outline-none"
                                >
                                    <option value="">Pilih Dapur...</option>
                                    {warehouses.map(w => (
                                        <option key={w.id} value={w.id}>{w.name}</option>
                                    ))}
                                </select>
                            </div>
                        )}

                        <hr className="border-dashed border-gray-200" />

                        <div className="space-y-4">
                            <h4 className="font-bold text-[#2D3A2D] text-sm flex items-center gap-2">
                                Items
                                <span className="text-[10px] font-normal text-gray-400 bg-gray-100 px-2 py-0.5 rounded-full">{cart.length} item</span>
                            </h4>

                            <div className="flex gap-2 items-end bg-gray-50 p-4 rounded-2xl border border-gray-100">
                                <div className="flex-1 space-y-1">
                                    <label className="text-[10px] font-bold text-gray-500 uppercase">Produk</label>
                                    <select
                                        value={selectedProductId}
                                        onChange={(e) => {
                                            setSelectedProductId(e.target.value);
                                            setQuantity('1');
                                        }}
                                        className="w-full bg-white border border-gray-200 rounded-xl px-3 py-2 text-sm focus:outline-none"
                                    >
                                        <option value="">Pilih Produk...</option>
                                        {products.map((p) => (
                                            <option key={p.id} value={p.id}>
                                                {p.name} (Stok: {p.variants?.[0]?.stockOnHand || 0})
                                            </option>
                                        ))}
                                    </select>
                                </div>
                                <div className="w-20 space-y-1">
                                    <label className="text-[10px] font-bold text-gray-500 uppercase">Qty</label>
                                    <input
                                        type="number"
                                        min="1"
                                        value={quantity}
                                        onChange={(e) => setQuantity(e.target.value)}
                                        className="w-full bg-white border border-gray-200 rounded-xl px-3 py-2 text-sm text-center focus:outline-none"
                                    />
                                </div>
                                <button
                                    type="button"
                                    onClick={handleAddToCart}
                                    disabled={!selectedProductId || isLowStock}
                                    className="px-4 py-2 bg-[#2D3A2D] text-white text-xs font-bold rounded-xl hover:bg-[#1A241A] disabled:opacity-50 disabled:cursor-not-allowed h-[38px]"
                                >
                                    + Tambah
                                </button>
                            </div>

                            {cart.length > 0 ? (
                                <div className="space-y-2">
                                    {cart.map((item, idx) => (
                                        <div key={idx} className="flex justify-between items-center p-3 bg-white border border-gray-100 rounded-xl shadow-sm">
                                            <div>
                                                <p className="text-sm font-bold text-gray-800">{item.name}</p>
                                                <p className="text-[10px] text-gray-500">{item.quantity} x Rp {item.price.toLocaleString('id-ID')}</p>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <span className="text-sm font-bold text-[#2D3A2D]">Rp {item.subtotal.toLocaleString('id-ID')}</span>
                                                <button
                                                    type="button"
                                                    onClick={() => handleRemoveFromCart(idx)}
                                                    className="text-rose-500 hover:text-rose-700 p-1 bg-rose-50 rounded-lg"
                                                >
                                                    <X className="w-3 h-3" />
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                    <div className="flex justify-between items-center pt-2 border-t border-gray-100">
                                        <span className="text-sm font-bold text-gray-500">Subtotal</span>
                                        <span className="text-sm font-bold text-gray-800">Rp {cartTotal.toLocaleString('id-ID')}</span>
                                    </div>
                                    {usePoints && (
                                        <div className="flex justify-between items-center text-indigo-600">
                                            <span className="text-xs font-medium italic">Diskon Poin ({availableToUse} Poin)</span>
                                            <span className="text-sm font-bold">- Rp {discountValue.toLocaleString('id-ID')}</span>
                                        </div>
                                    )}
                                    <div className="flex justify-between items-center pt-2 border-t border-[#2D3A2D]/10">
                                        <span className="text-sm font-bold text-gray-500">Total Akhir</span>
                                        <span className="text-xl font-black text-[#2D3A2D]">Rp {finalTotal.toLocaleString('id-ID')}</span>
                                    </div>

                                    {loyaltyInfo && loyaltyInfo.availablePoints > 0 && (
                                        <label className="flex items-center gap-3 p-4 bg-indigo-50 border border-indigo-100 rounded-2xl cursor-pointer hover:bg-indigo-100 transition-all select-none group mt-4">
                                            <input
                                                type="checkbox"
                                                checked={usePoints}
                                                onChange={(e) => setUsePoints(e.target.checked)}
                                                className="w-5 h-5 rounded-lg border-2 border-indigo-300 text-indigo-600 focus:ring-indigo-500 transition-all cursor-pointer"
                                            />
                                            <div className="flex-1">
                                                <p className="text-sm font-black text-indigo-900 flex items-center gap-2">
                                                    <Sparkles className="w-4 h-4 text-indigo-500" /> Gunakan Poin Loyalitas
                                                </p>
                                                <p className="text-[10px] text-indigo-700 font-medium">
                                                    Potong saldo *Rp {discountValue.toLocaleString('id-ID')}* dari *{availableToUse}* poin Bunda.
                                                </p>
                                            </div>
                                        </label>
                                    )}
                                </div>
                            ) : (
                                <div className="text-center py-4 text-gray-400 text-xs italic bg-gray-50/50 rounded-xl border border-dashed border-gray-200">
                                    Belum ada item ditambahkan.
                                </div>
                            )}
                        </div>

                        {isLowStock && selectedProductId && (
                            <div className="p-4 bg-amber-50 border border-amber-100 rounded-2xl animate-pulse">
                                <p className="text-[10px] font-black text-amber-700 uppercase">⚠️ Stok Tidak Cukup</p>
                                <p className="text-xs text-amber-600 italic">Maaf Bunda, stok di dapur hanya sisa {stockOnHand}.</p>
                            </div>
                        )}

                        <div className="space-y-2 px-10 pb-6">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Catatan Internal</label>
                            <textarea
                                value={internalNotes}
                                onChange={(e) => setInternalNotes(e.target.value)}
                                className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm focus:outline-none h-20"
                                placeholder="Catatan tambahan..."
                            />
                        </div>
                    </div>

                    <div className="px-10 py-6 border-t border-[#E5E1D8] flex justify-between items-center bg-white shrink-0">
                        <button type="button" onClick={onClose} className="text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-600">
                            Batal
                        </button>
                        <button
                            disabled={isSubmitting || cart.length === 0}
                            type="submit"
                            className={`px-10 py-4 bg-[#2D3A2D] text-[#FDFBF7] text-[10px] font-black uppercase tracking-widest rounded-2xl shadow-xl transition-all ${isSubmitting || cart.length === 0 ? 'opacity-30' : 'hover:scale-105 active:scale-95'}`}
                        >
                            {isSubmitting ? 'Menyimpan...' : 'Simpan Pesanan'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import { Download } from 'lucide-react';

interface PantryStockGridProps {
    products: any[];
    canAudit?: boolean;
    onOpenAudit: () => void;
    onOpenProduction?: () => void;
}

export default function PantryStockGrid({ products, canAudit, onOpenAudit, onOpenProduction }: PantryStockGridProps) {
    return (
        <div suppressHydrationWarning className="bg-white border border-[#E5E1D8] rounded-[3rem] overflow-hidden shadow-sm shadow-stone-200/50">
            <div className="px-10 py-8 border-b border-[#F9F7F2] bg-white flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-amber-50 rounded-lg flex items-center justify-center text-amber-600">
                        <span className="text-sm">🥘</span>
                    </div>
                    <h3 className="text-sm font-black text-[#2D3A2D] uppercase tracking-widest">Ketersediaan Stok (The Pantry)</h3>
                </div>
                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2 bg-amber-50 px-3 py-1.5 rounded-full border border-amber-100">
                        <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse"></span>
                        <span className="text-[10px] font-black text-amber-700 uppercase tracking-widest">Buffer Alert</span>
                    </div>
                    {canAudit && (
                        <button
                            onClick={onOpenAudit}
                            className="px-6 py-2.5 bg-amber-50 text-amber-700 border border-amber-100 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-amber-100 transition-all shadow-sm"
                        >
                            Audit Hub
                        </button>
                    )}
                    <button
                        className="p-2.5 bg-[#FDFBF7] border border-[#E5E1D8] rounded-xl hover:bg-white transition-all text-[#8B7E66]"
                        title="Download CSV"
                    >
                        <Download className="w-4 h-4" />
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-px bg-[#E5E1D8]/50">
                {products
                    .filter(p => !p.inventoryType || p.inventoryType === 'FINISHED_GOOD' || p.inventoryType === 'SUPPLY')
                    .map((product) => {
                        // Calculate total stock across all variants for this product
                        const variants = product.variants || [];
                        const totalStock = variants.reduce((sum: number, v: any) => sum + (v.stockOnHand || 0), 0);
                        const isLow = totalStock <= 10;

                        return (
                            <div key={product.id} className="bg-white p-8 space-y-6 hover:bg-[#FDFBF7] transition-all group">
                                <div className="flex justify-between items-start">
                                    <div className="space-y-1">
                                        <div className="flex items-center gap-2">
                                            <h4 className="text-xs font-black text-[#1A241A] truncate max-w-[120px]">{product.name}</h4>
                                            {product.inventoryType === 'SUPPLY' && (
                                                <span className="px-1.5 py-0.5 bg-blue-50 text-[8px] font-black text-blue-600 rounded-md border border-blue-100 uppercase tracking-tighter">Supply</span>
                                            )}
                                        </div>
                                        <span className="text-[10px] text-slate-400 font-bold uppercase">{product.category?.name || 'Frozen'}</span>
                                    </div>
                                    {isLow && (
                                        <span className="flex h-2 w-2 rounded-full bg-amber-400 shadow-[0_0_8px_rgba(251,191,36,0.5)]"></span>
                                    )}
                                </div>

                                <div className="space-y-4">
                                    {variants.map((variant: any) => {
                                        const variantLow = (variant.stockOnHand || 0) <= 5;
                                        return (
                                            <div key={variant.id} className="space-y-1">
                                                <div className="flex justify-between items-baseline">
                                                    <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">{variant.name || 'Default'}</span>
                                                    <div className="flex items-center gap-2">
                                                        <span className={`text-[9px] font-black uppercase ${variantLow ? 'text-amber-600' : 'text-emerald-600'}`}>
                                                            {variant.stockOnHand === 0 ? 'Habis' : variantLow ? 'Menipis' : 'Cukup'}
                                                        </span>
                                                        <div className="flex items-baseline gap-1">
                                                            <span className="text-md font-black text-[#1A241A] tracking-tighter">{variant.stockOnHand}</span>
                                                            <span className="text-[10px] font-bold text-slate-400">{variant.unit || 'pcs'}</span>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        );
                                    })}
                                    {isLow && (
                                        <p className="text-[9px] font-bold text-amber-500 italic bg-amber-50 p-2 rounded-md">
                                            Beberapa stok menipis. Cek gudang atau segera order!
                                        </p>
                                    )}
                                </div>

                                <div className="grid grid-cols-2 gap-3 pt-4">
                                    <button
                                        onClick={onOpenProduction}
                                        className="text-[9px] font-black uppercase tracking-widest text-white bg-[#B2BCA2] py-3 rounded-2xl hover:bg-[#2D3A2D] transition-all shadow-md shadow-[#B2BCA2]/20 disabled:opacity-50 disabled:cursor-not-allowed"
                                        disabled={!onOpenProduction}
                                    >
                                        📩 Update Dapur
                                    </button>
                                </div>
                            </div>
                        );
                    })}
            </div>
        </div>
    );
}

