'use client';

import React, { useEffect, useState } from 'react';
import { getPendingReconciliationsAction, verifyPaymentAction, rejectPaymentAction } from '@/lib/actions/rasa-ibu/finance';
import { BadgeCheck, X, AlertCircle, Check, Eye } from 'lucide-react';
import { toast } from 'sonner';
import { useConfirm } from '@/components/ui/BrandConfirm';
import Image from 'next/image';

interface PaymentReconciliationModalProps {
    brandId: string;
    onClose: () => void;
}

export default function PaymentReconciliationModal({ brandId, onClose }: PaymentReconciliationModalProps) {
    const [reconciliations, setReconciliations] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedProof, setSelectedProof] = useState<string | null>(null);
    const confirm = useConfirm();

    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    const loadData = async () => {
        setIsLoading(true);
        const res = await getPendingReconciliationsAction(brandId);
        if (res.success) {
            setReconciliations(res.data);
        }
        setIsLoading(false);
    };

    useEffect(() => {
        loadData();
    }, [brandId]);

    const handleVerify = async (id: string, orderId: string) => {
        const confirmed = await confirm({
            title: 'Konfirmasi Pembayaran',
            message: `Bunda yakin pembayaran untuk Pesanan #${orderId.slice(-4)} sudah sesuai?`,
            confirmText: 'Ya, Sesuai',
            cancelText: 'Batal',
            variant: 'info'
        });

        if (!confirmed) return;

        // Optimistic update
        setReconciliations(prev => prev.filter(r => r.id !== id));

        const res = await verifyPaymentAction(id, 'CURRENT_USER'); // TODO: Get actual user ID
        if (!res.success) {
            toast.error('Gagal memverifikasi pembayaran: ' + res.error);
            loadData(); // Revert
        }
    };

    const handleReject = async (id: string, orderId: string) => {
        const reason = await confirm({
            title: 'Tolak Rekonsiliasi?',
            message: `Berikan alasan penolakan untuk Pesanan #${orderId.slice(-4)} agar pelanggan tahu apa yang salah.`,
            confirmText: 'Tolak Pembayaran',
            cancelText: 'Batal',
            variant: 'danger',
            showInput: true,
            inputPlaceholder: 'Alasan penolakan...'
        });

        if (!reason || typeof reason !== 'string') return;

        setReconciliations(prev => prev.filter(r => r.id !== id));

        const res = await rejectPaymentAction(id, reason, 'CURRENT_USER');
        if (!res.success) {
            toast.error('Gagal menolak pembayaran: ' + res.error);
            loadData();
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#1A241A]/60 backdrop-blur-md p-6">
            <div className="bg-[#FDFBF7] w-full max-w-4xl max-h-[90vh] rounded-[3rem] shadow-2xl border border-[#E5E1D8] overflow-hidden flex flex-col animate-in fade-in zoom-in duration-500">
                {/* Header */}
                <div className="px-12 py-8 border-b border-[#E5E1D8] bg-white flex justify-between items-center">
                    <div className="flex items-center gap-6">
                        <div className="p-4 bg-amber-50 rounded-2xl">
                            <BadgeCheck className="w-8 h-8 text-[#8B7E66]" />
                        </div>
                        <div className="space-y-1">
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66]">Verifikasi Pembayaran</span>
                            <h2 className="text-3xl font-black text-[#2D3A2D]">Reconciliation Desk</h2>
                        </div>
                    </div>
                    <button
                        onClick={onClose}
                        className="p-3 hover:bg-slate-100 rounded-full transition-colors"
                    >
                        <X className="w-6 h-6 text-slate-400" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-12 bg-white relative">
                    {isLoading ? (
                        <div className="flex flex-col items-center justify-center py-20 space-y-4">
                            <div className="w-12 h-12 border-4 border-amber-200 border-t-[#8B7E66] rounded-full animate-spin"></div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Memeriksa Antrian...</p>
                        </div>
                    ) : reconciliations.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-20 space-y-6 text-center">
                            <div className="p-6 bg-[#F9F7F2] rounded-full">
                                <Check className="w-12 h-12 text-[#B2BCA2]" />
                            </div>
                            <div>
                                <h3 className="text-xl font-black text-[#2D3A2D]">Semua Beres!</h3>
                                <p className="text-slate-400 mt-2">Tidak ada pembayaran yang perlu diverifikasi saat ini.</p>
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-6">
                            {reconciliations.map((item) => (
                                <div key={item.id} className="bg-white border border-[#E5E1D8] rounded-[2rem] p-8 shadow-sm hover:shadow-md transition-shadow flex flex-col md:flex-row gap-8 items-start">
                                    {/* Proof Preview */}
                                    <div className="w-full md:w-48 h-48 bg-slate-100 rounded-2xl relative overflow-hidden group flex-shrink-0 cursor-pointer" onClick={() => setSelectedProof(item.paymentProof)}>
                                        {item.paymentProof ? (
                                            <img src={item.paymentProof} alt="Proof" className="w-full h-full object-cover" />
                                        ) : (
                                            <div className="flex items-center justify-center h-full text-slate-300 italic text-xs">No Image</div>
                                        )}
                                        <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                                            <Eye className="text-white w-6 h-6" />
                                        </div>
                                    </div>

                                    {/* Info */}
                                    <div className="flex-1 space-y-4">
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <p className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66] mb-1">Pesanan #{item.order.invoiceNo}</p>
                                                <h3 className="text-2xl font-black text-[#2D3A2D]">{item.order.customerName}</h3>
                                            </div>
                                            <div className="text-right">
                                                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">Nominal</p>
                                                <p className="text-2xl font-black text-[#2D3A2D]">{currency.format(Number(item.amount))}</p>
                                            </div>
                                        </div>

                                        <div className="bg-[#F9F7F2] p-4 rounded-xl flex gap-8 text-xs">
                                            <div>
                                                <span className="block font-bold text-slate-400 uppercase tracking-wider text-[10px]">Bank Tujuan</span>
                                                <span className="font-bold text-[#2D3A2D]">{item.bankAccount || '-'}</span>
                                            </div>
                                            <div>
                                                <span className="block font-bold text-slate-400 uppercase tracking-wider text-[10px]">Metode</span>
                                                <span className="font-bold text-[#2D3A2D]">{item.paymentMethod}</span>
                                            </div>
                                            <div>
                                                <span className="block font-bold text-slate-400 uppercase tracking-wider text-[10px]">Waktu Upload</span>
                                                <span className="font-bold text-[#2D3A2D]">{new Date(item.createdAt).toLocaleString('id-ID')}</span>
                                            </div>
                                        </div>

                                        <div className="flex gap-4 pt-4">
                                            <button
                                                onClick={() => handleVerify(item.id, item.order.id)}
                                                className="flex-1 bg-[#2D3A2D] text-[#FDFBF7] py-3 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-emerald-600 transition-colors"
                                            >
                                                Verifikasi Valid
                                            </button>
                                            <button
                                                onClick={() => handleReject(item.id, item.order.id)}
                                                className="px-8 bg-white border border-red-100 text-red-400 py-3 rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-red-50 transition-colors"
                                            >
                                                Tolak
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                {/* Proof Lightbox */}
                {selectedProof && (
                    <div className="absolute inset-0 z-50 bg-black/90 flex items-center justify-center p-10" onClick={() => setSelectedProof(null)}>
                        <img src={selectedProof} alt="Full Proof" className="max-w-full max-h-full object-contain rounded-lg" />
                        <button className="absolute top-8 right-8 text-white hover:text-red-400">
                            <X className="w-10 h-10" />
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { CheckCircle2, XCircle, Clock, Eye, Loader2, DollarSign, ShieldCheck, User, Image as ImageIcon, AlertCircle } from 'lucide-react';
import { toast } from 'sonner';
import { getPendingPaymentsAction, verifyPaymentAction, rejectPaymentAction } from '@/lib/actions/rasa-ibu/qris';
import { useConfirm } from '@/components/ui/BrandConfirm';

interface PaymentVerificationPanelProps {
    brandId: string;
    onVerificationSuccess?: () => void;
}

export default function PaymentVerificationPanel({ brandId, onVerificationSuccess }: PaymentVerificationPanelProps) {
    const [payments, setPayments] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedPayment, setSelectedPayment] = useState<any | null>(null);
    const [isActionLoading, setIsActionLoading] = useState(false);
    const confirm = useConfirm();

    const loadPayments = async () => {
        setIsLoading(true);
        const res = await getPendingPaymentsAction(brandId);
        if (res.success) {
            setPayments(res.data);
        }
        setIsLoading(false);
    };

    useEffect(() => {
        loadPayments();
    }, [brandId]);

    const handleVerify = async (paymentId: string) => {
        const confirmed = await confirm({
            title: 'Verifikasi Pembayaran?',
            message: 'Pastikan dana benar-benar sudah masuk ke rekening atau E-wallet Bunda sebelum memverifikasi.',
            confirmText: 'Ya, Verifikasi',
            cancelText: 'Cek Lagi',
            variant: 'info'
        });

        if (!confirmed) return;

        setIsActionLoading(true);
        try {
            const res = await verifyPaymentAction(paymentId, 'Staff Dapur'); // Replace with actual user name if available
            if (res.success) {
                toast.success('Pembayaran Terverifikasi!');
                setSelectedPayment(null);
                loadPayments();
                if (onVerificationSuccess) onVerificationSuccess();
            } else {
                toast.error('Gagal verifikasi: ' + res.error);
            }
        } catch (error) {
            toast.error('Terjadi kesalahan');
        } finally {
            setIsActionLoading(false);
        }
    };

    const handleReject = async (paymentId: string) => {
        const reason = await confirm({
            title: 'Tolak Pembayaran?',
            message: 'Mohon masukkan alasan penolakan untuk diinfokan ke pelanggan.',
            confirmText: 'Tolak Pembayaran',
            cancelText: 'Batal',
            variant: 'danger',
            showInput: true,
            inputPlaceholder: 'Contoh: Nominal tidak sesuai, Bukti tidak jelas...'
        });

        if (!reason || typeof reason !== 'string') return;

        setIsActionLoading(true);
        try {
            const res = await rejectPaymentAction(paymentId, reason);
            if (res.success) {
                toast.success('Pembayaran Ditolak');
                setSelectedPayment(null);
                loadPayments();
                if (onVerificationSuccess) onVerificationSuccess();
            } else {
                toast.error('Gagal menolak: ' + res.error);
            }
        } catch (error) {
            toast.error('Terjadi kesalahan');
        } finally {
            setIsActionLoading(false);
        }
    };

    return (
        <div suppressHydrationWarning className="bg-white border border-[#E5E1D8] rounded-[3rem] overflow-hidden shadow-sm shadow-stone-200/50 h-full flex flex-col min-h-[500px]">
            <div className="px-10 py-8 border-b border-[#F9F7F2] bg-white flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-blue-50 rounded-lg flex items-center justify-center text-blue-600">
                        <ShieldCheck className="w-5 h-5" />
                    </div>
                    <div className="text-left">
                        <h3 className="text-sm font-black text-[#2D3A2D] uppercase tracking-widest leading-none">Verifikasi Pembayaran</h3>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Antrean QRIS Menunggu</p>
                    </div>
                </div>
                {payments.length > 0 && (
                    <div className="bg-amber-50 px-3 py-1.5 rounded-full border border-amber-100 flex items-center gap-2">
                        <span className="text-[9px] font-black text-amber-700 uppercase tracking-widest">{payments.length} Pending</span>
                        <span className="flex h-2 w-2 rounded-full bg-amber-500 animate-pulse"></span>
                    </div>
                )}
            </div>

            <div className="flex-1 divide-y divide-slate-50 overflow-y-auto custom-scrollbar">
                {isLoading ? (
                    <div className="h-64 flex flex-col items-center justify-center space-y-3 opacity-30">
                        <Loader2 className="w-8 h-8 animate-spin" />
                        <p className="text-xs font-black uppercase tracking-widest">Memuat Antrean...</p>
                    </div>
                ) : payments.length === 0 ? (
                    <div className="h-64 flex flex-col items-center justify-center space-y-3 opacity-20">
                        <CheckCircle2 size={48} strokeWidth={1} />
                        <p className="text-xs font-black uppercase tracking-widest">Semua Terverifikasi</p>
                    </div>
                ) : (
                    payments.map((payment) => (
                        <div
                            key={payment.id}
                            onClick={() => setSelectedPayment(payment)}
                            className={`px-10 py-6 flex items-start gap-4 hover:bg-[#FDFBF7] transition-all cursor-pointer group/item ${selectedPayment?.id === payment.id ? 'bg-[#F9F7F2]' : ''}`}
                        >
                            <div className="w-12 h-12 bg-white border border-[#E5E1D8] rounded-2xl overflow-hidden shadow-sm group-hover/item:scale-110 transition-transform flex items-center justify-center">
                                {payment.proofPath ? (
                                    <img src={payment.proofPath} alt="Proof Small" className="w-full h-full object-cover" />
                                ) : (
                                    <ImageIcon className="text-slate-200" size={20} />
                                )}
                            </div>
                            <div className="flex-1 min-w-0 text-left">
                                <div className="flex justify-between items-baseline mb-1">
                                    <p className="text-sm font-black text-[#1A241A] truncate">{payment.order?.customerName || 'Anonymous'}</p>
                                    <span className="text-[9px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded-md border border-slate-100">
                                        #{payment.order?.invoiceNo || payment.order?.id.slice(-6).toUpperCase()}
                                    </span>
                                </div>
                                <div className="flex items-center gap-3 mt-1">
                                    <p className="text-xs font-black text-emerald-700">Rp {Number(payment.amount).toLocaleString('id-ID')}</p>
                                    <div className="h-1 w-1 bg-slate-300 rounded-full" />
                                    <div className="flex items-center gap-1 text-[9px] font-bold text-slate-400 uppercase tracking-tight">
                                        <Clock size={10} />
                                        {new Date(payment.createdAt).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                    </div>
                                </div>
                            </div>
                            <div className="opacity-0 group-hover/item:opacity-100 transition-opacity">
                                <button className="p-2 bg-white text-slate-400 border border-slate-200 rounded-xl hover:text-emerald-600 hover:border-emerald-200 transition-all">
                                    <Eye size={16} />
                                </button>
                            </div>
                        </div>
                    ))
                )}
            </div>

            {/* Expanded View / Detail Overlay */}
            {selectedPayment && (
                <div className="fixed inset-0 z-[120] bg-black/60 backdrop-blur-md flex items-center justify-center p-6 animate-in fade-in duration-300">
                    <div className="bg-[#FDFBF7] w-full max-w-2xl rounded-[3rem] shadow-2xl overflow-hidden border border-white/20 animate-in zoom-in-95 duration-200">
                        <div className="p-8 border-b border-[#E5E1D8] bg-white flex justify-between items-center">
                            <div className="flex items-center gap-4 text-left">
                                <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center">
                                    <User size={24} />
                                </div>
                                <div className="text-left">
                                    <h4 className="text-lg font-black text-[#2D3A2D] tracking-tighter">{selectedPayment.order?.customerName}</h4>
                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Verifikasi Pembayaran QRIS</p>
                                </div>
                            </div>
                            <button onClick={() => setSelectedPayment(null)} className="p-3 hover:bg-slate-100 rounded-full transition-colors">
                                <XCircle className="w-6 h-6 text-slate-400" />
                            </button>
                        </div>

                        <div className="p-10 space-y-8">
                            <div className="grid grid-cols-2 gap-10">
                                <div className="space-y-4">
                                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Bukti Transfer</label>
                                    <div className="aspect-[3/4] bg-white border-2 border-[#E5E1D8] rounded-[2rem] overflow-hidden shadow-2xl group relative">
                                        <img src={selectedPayment.proofPath} alt="Full Proof" className="w-full h-full object-contain" />
                                        <a
                                            href={selectedPayment.proofPath}
                                            target="_blank"
                                            rel="noreferrer"
                                            className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity"
                                        >
                                            <span className="px-4 py-2 bg-white text-[10px] font-black uppercase rounded-xl shadow-lg">Lihat Ukuran Penuh</span>
                                        </a>
                                    </div>
                                </div>
                                <div className="space-y-8">
                                    <div className="space-y-6">
                                        <div className="space-y-1">
                                            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Nominal Seharusnya</label>
                                            <p className="text-3xl font-black text-[#2D3A2D] tracking-tighter">
                                                Rp {Number(selectedPayment.amount).toLocaleString('id-ID')}
                                            </p>
                                        </div>
                                        <div className="p-6 bg-amber-50 border border-amber-100 rounded-[2rem] space-y-3">
                                            <div className="flex items-center gap-2 text-amber-700">
                                                <AlertCircle size={14} />
                                                <span className="text-[10px] font-black uppercase tracking-widest">Audit Checklist</span>
                                            </div>
                                            <ul className="space-y-2">
                                                {['Cek Nama Pengirim', 'Cek Tanggal & Jam', 'Cek Nominal Persis'].map((check, i) => (
                                                    <li key={i} className="flex items-center gap-2 text-[10px] font-bold text-amber-800/60">
                                                        <div className="w-1 h-1 bg-amber-400 rounded-full" />
                                                        {check}
                                                    </li>
                                                ))}
                                            </ul>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 gap-4 pt-10">
                                        <button
                                            onClick={() => handleVerify(selectedPayment.id)}
                                            disabled={isActionLoading}
                                            className="w-full py-5 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all flex items-center justify-center gap-2 shadow-xl shadow-emerald-900/10"
                                        >
                                            {isActionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckCircle2 size={16} />}
                                            Verifikasi & Update Status
                                        </button>
                                        <button
                                            onClick={() => handleReject(selectedPayment.id)}
                                            disabled={isActionLoading}
                                            className="w-full py-5 text-rose-600 hover:bg-rose-50 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all border border-rose-100 flex items-center justify-center gap-2"
                                        >
                                            {isActionLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <XCircle size={16} />}
                                            Tolak Pembayaran
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            <div className="p-6 bg-[#FDFBF7] border-t border-[#E5E1D8] mt-auto flex justify-between items-center shrink-0">
                <button
                    onClick={loadPayments}
                    className="text-[9px] font-black text-[#8B7E66] uppercase tracking-widest flex items-center gap-2 hover:text-[#2D3A2D] transition-colors"
                >
                    <Clock size={12} /> Segarkan Data
                </button>
                <div className="flex items-center gap-2 opacity-50">
                    <ShieldCheck size={12} className="text-blue-600" />
                    <span className="text-[9px] font-black text-[#8B7E66] uppercase tracking-widest">Encrypted</span>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Settings, Save, X, Info, Percent, DollarSign, Loader2, Plus, Trash2, Tag, CreditCard, Zap } from 'lucide-react';
import { toast } from 'sonner';
import { getPlatformSettingsAction, updatePlatformSettingsAction } from '@/lib/actions/rasa-ibu/finance';
import QRISSettingsPanel from './QRISSettingsPanel';
import BankSettingsPanel from './BankSettingsPanel';
import LoyaltySettingsPanel from './LoyaltySettingsPanel';

interface PlatformSettingsModalProps {
    brandId: string;
    onClose: () => void;
}

export default function PlatformSettingsModal({ brandId, onClose }: PlatformSettingsModalProps) {
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [settings, setSettings] = useState<any>({
        marketplaceFees: {
            WHATSAPP: 0,
            SHOPEE: 15,
            GRAB_FOOD: 25,
            GO_FOOD: 25,
            TIKTOK_SHOP: 12
        },
        mdrFees: {
            WHATSAPP: 0,
            SHOPEE: 1.5,
            GRAB_FOOD: 0,
            GO_FOOD: 0,
            TIKTOK_SHOP: 0
        },
        campaignFees: {},
        taxRates: {
            PPN: 11,
            PPH: 0.5
        },
        operationalOverhead: 5000,
        dailyKitchenOverhead: 0,
        qrisEnabled: false,
        qrisImageUrl: ''
    });

    useEffect(() => {
        async function load() {
            const res = await getPlatformSettingsAction(brandId);
            if (res.success && res.settings) {
                // Ensure mdrFees exists if loading from old data
                const loaded = res.settings;
                if (!loaded.mdrFees) {
                    loaded.mdrFees = {
                        WHATSAPP: 0,
                        SHOPEE: 1.5,
                        GRAB_FOOD: 0,
                        GO_FOOD: 0,
                        TIKTOK_SHOP: 0
                    };
                }
                setSettings(loaded);
            }
            setIsLoading(false);
        }
        load();
    }, [brandId]);

    const handleSave = async () => {
        setIsSaving(true);
        const res = await updatePlatformSettingsAction(brandId, settings);
        if (res.success) {
            toast.success('Pengaturan berhasil disimpan. Kalkulasi profit akan otomatis diperbarui.');
            onClose();
        } else {
            toast.error('Gagal menyimpan: ' + res.error);
        }
        setIsSaving(false);
    };

    const updateFee = (channel: string, val: string) => {
        setSettings({
            ...settings,
            marketplaceFees: {
                ...settings.marketplaceFees,
                [channel]: parseFloat(val) || 0
            }
        });
    };

    const updateMdr = (channel: string, val: string) => {
        setSettings({
            ...settings,
            mdrFees: {
                ...settings.mdrFees,
                [channel]: parseFloat(val) || 0
            }
        });
    };

    const updateCampaignFee = (tag: string, val: string) => {
        setSettings({
            ...settings,
            campaignFees: {
                ...settings.campaignFees,
                [tag.toUpperCase()]: parseFloat(val) || 0
            }
        });
    };

    const addCampaignFee = () => {
        const tag = prompt('Masukkan Nama Kampanye (contoh: #PROMO)');
        if (tag) {
            const cleanTag = tag.toUpperCase().startsWith('#') ? tag.toUpperCase() : '#' + tag.toUpperCase();
            setSettings({
                ...settings,
                campaignFees: {
                    ...settings.campaignFees,
                    [cleanTag]: 0
                }
            });
        }
    };

    const removeCampaignFee = (tag: string) => {
        const newCampaignFees = { ...settings.campaignFees };
        delete newCampaignFees[tag];
        setSettings({ ...settings, campaignFees: newCampaignFees });
    };

    if (isLoading) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#2D3A2D]/40 backdrop-blur-md p-6">
            <div className="bg-[#FDFBF7] w-full max-w-4xl rounded-[2.5rem] shadow-2xl border border-[#E5E1D8] overflow-hidden flex flex-col animate-in fade-in zoom-in duration-300 max-h-[90vh]">
                <div className="px-10 py-8 border-b border-[#E5E1D8] bg-white flex justify-between items-center">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-emerald-600 text-white rounded-2xl">
                            <Settings className="w-5 h-5" />
                        </div>
                        <div>
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66]">Konfigurasi Sistem</span>
                            <h2 className="text-2xl font-black text-[#2D3A2D]">Pengaturan Finansial</h2>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-3 hover:bg-slate-100 rounded-full transition-colors">
                        <X className="w-6 h-6 text-slate-400" />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-10 space-y-12 custom-scrollbar">
                    {/* Bank Transfer Settings - NEW */}
                    <BankSettingsPanel brandId={brandId} />

                    {/* QRIS Settings Configuration */}
                    <section className="space-y-6">
                        <QRISSettingsPanel
                            brandId={brandId}
                            settings={settings}
                            onSettingsUpdate={(newSettings) => {
                                setSettings(newSettings);
                                // The component itself handles server update, but we update local state
                                // Actually, verify if onSettingsUpdate in component purely updates parent state or assumes server is updated.
                                // Component calls upload/toggle actions, then calls onSettingsUpdate.
                                // So we just need to update local state.
                            }}
                        />
                    </section>

                    {/* Marketplace Fees & MDR Configuration */}
                    <section className="space-y-6">
                        <div className="flex items-center gap-2 border-b border-[#F9F7F2] pb-4">
                            <Percent className="w-4 h-4 text-emerald-600" />
                            <h3 className="text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Struktur Biaya Marketplace</h3>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {Object.entries(settings.marketplaceFees).map(([channel, fee]: [string, any]) => (
                                <div key={channel} className="bg-white border border-[#E5E1D8] p-5 rounded-2xl space-y-4 shadow-sm hover:shadow-md transition-shadow">
                                    <h4 className="text-[11px] font-black text-[#2D3A2D] uppercase tracking-wider flex items-center gap-2">
                                        {channel.replace('_', ' ')}
                                    </h4>

                                    <div className="grid grid-cols-2 gap-4">
                                        {/* Commission Cost */}
                                        <div className="space-y-1">
                                            <label className="text-[9px] font-bold text-[#8B7E66] uppercase">Komisi (%)</label>
                                            <div className="relative">
                                                <input
                                                    type="number"
                                                    value={fee}
                                                    onChange={(e) => updateFee(channel, e.target.value)}
                                                    className="w-full bg-[#F9F7F2] border border-[#E5E1D8] rounded-xl px-3 py-2 text-xs font-black focus:outline-none focus:border-emerald-600 pr-8"
                                                />
                                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[9px] font-black text-[#8B7E66]">%</span>
                                            </div>
                                        </div>

                                        {/* MDR Cost */}
                                        <div className="space-y-1">
                                            <label className="text-[9px] font-bold text-[#8B7E66] uppercase flex items-center gap-1">
                                                MDR <CreditCard className="w-2 h-2 text-slate-400" />
                                            </label>
                                            <div className="relative">
                                                <input
                                                    type="number"
                                                    value={settings.mdrFees?.[channel] || 0}
                                                    onChange={(e) => updateMdr(channel, e.target.value)}
                                                    className="w-full bg-[#F9F7F2] border border-[#E5E1D8] rounded-xl px-3 py-2 text-xs font-black focus:outline-none focus:border-emerald-600 pr-8"
                                                />
                                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[9px] font-black text-[#8B7E66]">%</span>
                                            </div>
                                        </div>
                                    </div>
                                    <p className="text-[9px] text-slate-400 font-medium">
                                        Total Fee: <span className="text-emerald-600 font-bold">{Number(fee) + Number(settings.mdrFees?.[channel] || 0)}%</span>
                                    </p>
                                </div>
                            ))}
                        </div>
                    </section>

                    {/* Campaign Fees */}
                    <section className="space-y-6">
                        <div className="flex items-center justify-between border-b border-[#F9F7F2] pb-4">
                            <div className="flex items-center gap-2">
                                <Tag className="w-4 h-4 text-purple-600" />
                                <h3 className="text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Biaya Kampanye Khusus</h3>
                            </div>
                            <button
                                onClick={addCampaignFee}
                                className="flex items-center gap-1 text-[10px] font-black text-emerald-600 hover:text-emerald-700 transition-colors"
                            >
                                <Plus className="w-3 h-3" /> TAMBAH TAG
                            </button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {Object.entries(settings.campaignFees || {}).map(([tag, fee]: [string, any]) => (
                                <div key={tag} className="bg-white border border-[#E5E1D8] rounded-2xl p-4 flex items-center gap-4 group">
                                    <div className="flex-1">
                                        <label className="text-[10px] font-bold text-[#8B7E66] uppercase tracking-wider">{tag}</label>
                                        <div className="relative mt-1">
                                            <input
                                                type="number"
                                                value={fee}
                                                onChange={(e) => updateCampaignFee(tag, e.target.value)}
                                                className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-xl px-4 py-2 text-xs font-black focus:outline-none focus:border-purple-600 pr-10"
                                            />
                                            <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black text-[#8B7E66]">%</span>
                                        </div>
                                    </div>
                                    <button
                                        onClick={() => removeCampaignFee(tag)}
                                        className="p-2 text-rose-200 hover:text-rose-600 transition-colors"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                            {Object.keys(settings.campaignFees || {}).length === 0 && (
                                <div className="col-span-2 py-4 text-center bg-[#F9F7F2]/50 rounded-2xl border border-dashed border-[#E5E1D8]">
                                    <p className="text-[10px] text-[#8B7E66] italic">Belum ada kampanye terdaftar. Gunakan hashtag di catatan pesanan untuk memicu biaya kampanye.</p>
                                </div>
                            )}
                        </div>
                    </section>

                    <LoyaltySettingsPanel
                        settings={settings}
                        onSettingsUpdate={(newSettings) => setSettings(newSettings)}
                    />


                    {/* Operational Overhead Moved Notice */}
                    <section className="space-y-8">
                        <div className="flex items-center gap-2 border-b border-[#F9F7F2] pb-4">
                            <DollarSign className="w-4 h-4 text-rose-600" />
                            <h3 className="text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Biaya Operasional & Overhead</h3>
                        </div>

                        <div className="p-8 bg-white border border-[#E5E1D8] rounded-[2.5rem] space-y-6 text-center">
                            <div className="w-16 h-16 bg-emerald-50 text-emerald-600 rounded-3xl flex items-center justify-center mx-auto shadow-sm">
                                <Zap size={32} />
                            </div>
                            <div className="max-w-md mx-auto space-y-2">
                                <h4 className="text-sm font-black text-[#2D3A2D] uppercase tracking-wider">Pengaturan Telah Berpindah</h4>
                                <p className="text-xs text-[#8B7E66] leading-relaxed">
                                    Konfigurasi biaya operasional harian (Listrik, Gaji, dll) sekarang terintegrasi langsung di <b>Pricing Advantage Hub</b> untuk memberikan analisis <i>True HPP</i> yang lebih akurat.
                                </p>
                            </div>
                            <button
                                onClick={() => {
                                    onClose();
                                    if ((window as any).showPricingAdvantage) {
                                        (window as any).showPricingAdvantage();
                                    }
                                }}
                                className="px-8 py-3 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:scale-105 transition-all shadow-lg shadow-emerald-900/10"
                            >
                                Buka Pricing Advantage Hub
                            </button>
                        </div>
                    </section>
                </div>

                <div className="px-10 py-8 bg-[#F9F7F2] border-t border-[#E5E1D8] flex justify-between items-center">
                    <button onClick={onClose} className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66] hover:text-rose-600 transition-colors">
                        Batal
                    </button>
                    <button
                        onClick={handleSave}
                        disabled={isSaving}
                        className="px-10 py-4 bg-[#2D3A2D] text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:scale-105 transition-all flex items-center gap-2 shadow-xl shadow-green-900/20 disabled:opacity-50"
                    >
                        {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                        Simpan Konfigurasi
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { ShoppingCart, X, AlertTriangle, TrendingUp, Copy, Check, MessageSquare, Package } from 'lucide-react';
import { getProcurementAdviceAction } from '@/lib/actions/rasa-ibu/procurement';

interface ProcurementAdvisorProps {
    brandId: string;
    onClose: () => void;
}

export default function ProcurementAdvisor({ brandId, onClose }: ProcurementAdvisorProps) {
    const [suggestions, setSuggestions] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [copied, setCopied] = useState(false);

    useEffect(() => {
        const loadAdvice = async () => {
            setIsLoading(true);
            const res = await getProcurementAdviceAction(brandId);
            if (res.success) setSuggestions(res.data);
            setIsLoading(false);
        };
        loadAdvice();
    }, [brandId]);

    const handleCopyWA = () => {
        const criticalItems = suggestions.filter(s => s.suggestedPurchase > 0);
        if (criticalItems.length === 0) return;

        let text = `*Daftar Belanja Rasa Ibu*\n`;
        text += `_Prediksi kebutuhan untuk 7 hari ke depan_\n\n`;

        criticalItems.forEach(item => {
            text += `• *${item.ingredientName}*: ${item.suggestedPurchase} ${item.unit}\n`;
        });

        text += `\n_Mohon dibantu order ya, terima kasih!_ 🙏✨`;

        navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#1A241A]/60 backdrop-blur-md p-6">
            <div className="bg-[#FDFBF7] w-full max-w-3xl max-h-[85vh] rounded-[3rem] shadow-2xl border border-[#E5E1D8] overflow-hidden flex flex-col animate-in fade-in zoom-in duration-500">

                {/* Header */}
                <div className="px-10 py-8 bg-white border-b border-[#E5E1D8] flex justify-between items-center">
                    <div className="flex items-center gap-6">
                        <div className="p-4 bg-amber-50 rounded-2xl">
                            <ShoppingCart className="w-8 h-8 text-amber-600" />
                        </div>
                        <div className="space-y-1">
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-amber-600">Proactive Procurement</span>
                            <h2 className="text-2xl font-black text-[#2D3A2D]">Penasihat Belanja Pintar</h2>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-3 hover:bg-slate-100 rounded-full transition-colors">
                        <X className="w-6 h-6 text-slate-400" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto p-10 space-y-8">
                    {isLoading ? (
                        <div className="py-20 flex flex-col items-center justify-center space-y-4">
                            <div className="w-10 h-10 border-4 border-amber-100 border-t-amber-600 rounded-full animate-spin"></div>
                            <p className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Menganalisa Riwayat Jualan Bunda...</p>
                        </div>
                    ) : suggestions.length === 0 ? (
                        <div className="py-20 text-center space-y-4 bg-slate-50/50 rounded-[2.5rem] border border-dashed border-slate-200">
                            <Package className="w-12 h-12 text-slate-300 mx-auto" />
                            <p className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Belum ada data cukup untuk memprediksi.</p>
                        </div>
                    ) : (
                        <div className="space-y-6">
                            <div className="p-6 bg-emerald-50 rounded-2xl border border-emerald-100 flex items-start gap-4">
                                <TrendingUp className="w-5 h-5 text-emerald-600 mt-1" />
                                <div className="space-y-1">
                                    <p className="text-sm font-bold text-emerald-900">Hasil Analisis 30 Hari Terakhir</p>
                                    <p className="text-[11px] text-emerald-700 leading-relaxed font-medium">
                                        Berdasarkan jualan Bunda sebulan terakhir, sistem menghitung kebutuhan bahan untuk 7 hari ke depan.
                                        Baris dengan label <span className="font-black">CRITICAL</span> berarti stok Bunda akan habis dalam kurang dari 2 hari.
                                    </p>
                                </div>
                            </div>

                            <div className="space-y-3">
                                {suggestions.map((item) => (
                                    <div
                                        key={item.ingredientId}
                                        className={`p-5 rounded-2xl border transition-all hover:shadow-md flex items-center justify-between ${item.isCritical ? 'bg-rose-50 border-rose-100' : 'bg-white border-[#E5E1D8]'
                                            }`}
                                    >
                                        <div className="flex items-center gap-4">
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${item.isCritical ? 'bg-rose-100 text-rose-600' : 'bg-slate-50 text-slate-400'}`}>
                                                <ShoppingCart className="w-5 h-5" />
                                            </div>
                                            <div>
                                                <div className="flex items-center gap-2">
                                                    <h4 className="font-black text-[#2D3A2D] uppercase tracking-tight">{item.ingredientName}</h4>
                                                    {item.isCritical && (
                                                        <span className="px-2 py-0.5 bg-rose-600 text-white text-[8px] font-black rounded-full uppercase tracking-widest">Critical</span>
                                                    )}
                                                </div>
                                                <p className="text-[10px] font-bold text-slate-400">Rata-rata: {item.avgDailyUsage} {item.unit} / hari</p>
                                            </div>
                                        </div>

                                        <div className="text-right">
                                            <p className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest">Saran Beli:</p>
                                            <div className="flex items-center gap-2 justify-end">
                                                <span className={`text-xl font-black ${item.suggestedPurchase > 0 ? (item.isCritical ? 'text-rose-600' : 'text-emerald-600') : 'text-slate-300'}`}>
                                                    {item.suggestedPurchase > 0 ? `+${item.suggestedPurchase}` : 'Aman'}
                                                </span>
                                                <span className="text-[10px] font-bold text-slate-400 uppercase">{item.unit}</span>
                                            </div>
                                            <p className="text-[10px] font-bold text-slate-400">Tersisa: {item.daysRemaining} hari</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="px-10 py-6 bg-[#FDFBF7] border-t border-[#E5E1D8] flex justify-between items-center gap-4">
                    <p className="flex-1 text-[10px] text-[#8B7E66] italic leading-relaxed font-medium">
                        *Saran ini hanyalah perkiraan berdasarkan data jualan. Pastikan cek fisik gudang sebelum belanja ya Bun!
                    </p>
                    <button
                        onClick={handleCopyWA}
                        disabled={suggestions.filter(s => s.suggestedPurchase > 0).length === 0}
                        className={`px-8 py-3 rounded-2xl font-black uppercase tracking-widest text-[10px] flex items-center gap-2 transition-all shadow-lg active:scale-95 disabled:opacity-50 ${copied ? 'bg-emerald-600 text-white shadow-emerald-600/20' : 'bg-emerald-500 text-white shadow-emerald-500/20 hover:bg-emerald-600'
                            }`}
                    >
                        {copied ? (
                            <><Check className="w-4 h-4" /> Berhasil Di-copy</>
                        ) : (
                            <><MessageSquare className="w-4 h-4" /> Copy untuk WhatsApp</>
                        )}
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { X, Upload, CheckCircle2, Loader2, QrCode, DollarSign, Image as ImageIcon, AlertCircle } from 'lucide-react';
import { toast } from 'sonner';
import { getQRISInfoAction, uploadPaymentProofAction } from '@/lib/actions/rasa-ibu/qris';

interface QRISPaymentModalProps {
    order: any;
    onClose: () => void;
    onSuccess: () => void;
}

export default function QRISPaymentModal({ order, onClose, onSuccess }: QRISPaymentModalProps) {
    const [isUploading, setIsUploading] = useState(false);
    const [qrisImageUrl, setQrisImageUrl] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [previewUrl, setPreviewUrl] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        async function loadQRIS() {
            const res = await getQRISInfoAction(order.brandId);
            if (res.success) {
                setQrisImageUrl(res.qrisImageUrl);
            }
            setIsLoading(false);
        }
        loadQRIS();
    }, [order.brandId]);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        // Preview
        const reader = new FileReader();
        reader.onloadend = () => {
            setPreviewUrl(reader.result as string);
        };
        reader.readAsDataURL(file);
    };

    const handleUpload = async () => {
        if (!fileInputRef.current?.files?.[0]) {
            toast.error('Pilih bukti pembayaran terlebih dahulu');
            return;
        }

        setIsUploading(true);
        const formData = new FormData();
        formData.append('image', fileInputRef.current.files[0]);

        try {
            const res = await uploadPaymentProofAction(order.id, formData);
            if (res.success) {
                toast.success('Bukti pembayaran berhasil diunggah! Staff kami akan segera memverifikasi.');
                onSuccess();
            } else {
                toast.error('Gagal mengunggah: ' + res.error);
            }
        } catch (error) {
            toast.error('Terjadi kesalahan saat mengunggah');
        } finally {
            setIsUploading(false);
        }
    };

    if (isLoading) return null;

    return (
        <div className="fixed inset-0 z-[110] flex items-center justify-center bg-[#2D3A2D]/40 backdrop-blur-md p-6">
            <div className="bg-[#FDFBF7] w-full max-w-4xl rounded-[3rem] shadow-2xl border border-[#E5E1D8] overflow-hidden flex flex-col animate-in fade-in zoom-in duration-300 max-h-[90vh]">
                <div className="px-10 py-8 border-b border-[#E5E1D8] bg-white flex justify-between items-center text-left">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-emerald-600 text-white rounded-2xl text-left">
                            <QrCode className="w-5 h-5 text-left" />
                        </div>
                        <div className="text-left">
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66] text-left">Pembayaran Pesanan</span>
                            <h2 className="text-2xl font-black text-[#2D3A2D] uppercase tracking-tighter text-left">QRIS Dynamic</h2>
                        </div>
                    </div>
                    <button onClick={onClose} className="p-3 hover:bg-slate-100 rounded-full transition-colors">
                        <X className="w-6 h-6 text-slate-400" />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-10">
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                        {/* Left Side: QR Code and Order Info */}
                        <div className="space-y-8">
                            <div className="bg-white border border-[#E5E1D8] rounded-[2.5rem] p-10 space-y-6 shadow-sm flex flex-col items-center text-center">
                                <div className="space-y-1">
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Pembayaran</p>
                                    <h3 className="text-4xl font-black text-emerald-900 tracking-tighter">
                                        Rp {(Number(order.totalAmount || order.total || 0)).toLocaleString('id-ID')}
                                    </h3>
                                </div>

                                <div className="p-6 bg-[#F9F7F2] rounded-[2rem] border-2 border-[#E5E1D8] relative group">
                                    {qrisImageUrl ? (
                                        <img src={qrisImageUrl} alt="QRIS" className="w-[200px] h-[200px] object-contain mix-blend-multiply" />
                                    ) : (
                                        <div className="w-[200px] h-[200px] flex items-center justify-center text-slate-300">
                                            <QrCode size={100} strokeWidth={1} />
                                        </div>
                                    )}
                                    <div className="absolute inset-0 border-[10px] border-white/50 pointer-events-none rounded-[1.5rem]" />
                                </div>

                                <div className="space-y-2">
                                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">No. Invoice</p>
