                                <div className="space-y-1 text-left">
                                    <p className="text-[10px] font-black text-blue-900 uppercase text-left">Petunjuk Pembayaran</p>
                                    <p className="text-[11px] text-blue-800/70 leading-relaxed font-medium text-left">
