                                    <>
                                        <CheckCircle2 className="w-4 h-4" />
                                        Kirim untuk Verifikasi
                                    </>
                                )}
                            </button>

                            <div className="p-8 bg-[#F9F7F2] rounded-[2.5rem] border border-[#E5E1D8] space-y-4">
                                <h4 className="text-[10px] font-black text-[#8B7E66] uppercase tracking-[0.2em] flex items-center gap-2">
                                    <div className="w-1 h-1 bg-emerald-600 rounded-full" />
                                    Security Promise
                                </h4>
                                <ul className="space-y-3">
                                    {[
                                        'Data anda dienkripsi secara aman',
                                        'Diverifikasi langsung oleh Finance Staff',
                                        'Notifikasi otomatis via WhatsApp'
                                    ].map((item, i) => (
                                        <li key={i} className="text-[10px] font-bold text-[#8B7E66] flex items-center gap-2">
                                            <CheckCircle2 size={12} className="text-emerald-600" />
                                            {item}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="px-10 py-6 bg-white border-t border-[#E5E1D8] text-center">
                    <p className="text-[9px] text-slate-400 font-medium">
                        Butuh bantuan? Hubungi Admin via WhatsApp atau Email Support.
                    </p>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useRef } from 'react';
import { QrCode, Upload, Trash2, CheckCircle2, AlertCircle, Loader2, Image as ImageIcon } from 'lucide-react';
import { toast } from 'sonner';
import { uploadQRISImageAction, toggleQRISAction } from '@/lib/actions/rasa-ibu/qris';

interface QRISSettingsPanelProps {
    brandId: string;
    settings: any;
    onSettingsUpdate: (newSettings: any) => void;
}

export default function QRISSettingsPanel({ brandId, settings, onSettingsUpdate }: QRISSettingsPanelProps) {
    const [isUploading, setIsUploading] = useState(false);
    const [previewUrl, setPreviewUrl] = useState<string | null>(settings.qrisImageUrl || null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        // Preview
        const reader = new FileReader();
        reader.onloadend = () => {
            setPreviewUrl(reader.result as string);
        };
        reader.readAsDataURL(file);

        // Upload
        setIsUploading(true);
        const formData = new FormData();
        formData.append('image', file);

        try {
            const res = await uploadQRISImageAction(brandId, formData);
            if (res.success) {
                toast.success('QRIS Image berhasil diunggah dan disimpan!');
                onSettingsUpdate({
                    ...settings,
                    qrisImageUrl: res.url,
                    qrisEnabled: true
                });
            } else {
                toast.error('Gagal mengunggah QRIS: ' + res.error);
                setPreviewUrl(settings.qrisImageUrl || null);
            }
        } catch (error) {
            toast.error('Terjadi kesalahan saat mengunggah');
            setPreviewUrl(settings.qrisImageUrl || null);
        } finally {
            setIsUploading(false);
        }
    };

    const handleToggle = async (enabled: boolean) => {
        try {
            const res = await toggleQRISAction(brandId, enabled);
            if (res.success) {
                toast.success(enabled ? 'QRIS Pembayaran Diaktifkan' : 'QRIS Pembayaran Dinonaktifkan');
                onSettingsUpdate({
                    ...settings,
                    qrisEnabled: enabled
                });
            } else {
                toast.error('Gagal memperbarui status QRIS');
            }
        } catch (error) {
            toast.error('Terjadi kesalahan');
        }
    };

    return (
        <section className="space-y-6">
            <div className="flex items-center justify-between border-b border-[#F9F7F2] pb-4">
                <div className="flex items-center gap-2">
                    <QrCode className="w-4 h-4 text-emerald-600" />
                    <h3 className="text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Metode Pembayaran QRIS</h3>
                </div>
                <div className="flex items-center gap-2">
                    <span className="text-[10px] font-bold text-[#8B7E66] uppercase">Status:</span>
                    <button
                        onClick={() => handleToggle(!settings.qrisEnabled)}
                        className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-wider transition-all ${settings.qrisEnabled
                                ? 'bg-emerald-100 text-emerald-700 border border-emerald-200'
                                : 'bg-slate-100 text-slate-500 border border-slate-200'
                            }`}
                    >
                        {settings.qrisEnabled ? 'Aktif' : 'Non-Aktif'}
                    </button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">
                {/* Image Preview & Upload */}
                <div className="space-y-4">
                    <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-widest">Preview QRIS</label>
                    <div className="relative aspect-square max-w-[280px] bg-white border-2 border-dashed border-[#E5E1D8] rounded-[2rem] overflow-hidden flex flex-col items-center justify-center group">
                        {previewUrl ? (
                            <>
                                <img src={previewUrl} alt="QRIS Preview" className="w-full h-full object-contain p-4" />
                                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-3">
                                    <button
                                        onClick={() => fileInputRef.current?.click()}
                                        className="p-3 bg-white text-emerald-600 rounded-2xl hover:scale-110 transition-transform shadow-xl"
                                    >
                                        <Upload className="w-5 h-5" />
                                    </button>
                                </div>
                            </>
                        ) : (
                            <div className="text-center p-6 space-y-3">
                                <div className="w-12 h-12 bg-[#F9F7F2] text-slate-300 rounded-2xl flex items-center justify-center mx-auto">
                                    <ImageIcon className="w-6 h-6" />
                                </div>
                                <p className="text-[10px] font-medium text-slate-400">Belum ada image QRIS ditalakan</p>
                                <button
                                    onClick={() => fileInputRef.current?.click()}
                                    className="px-6 py-2 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:scale-105 transition-all"
                                >
                                    Upload QRIS
                                </button>
                            </div>
                        )}

                        {isUploading && (
                            <div className="absolute inset-0 bg-white/80 backdrop-blur-sm flex items-center justify-center">
                                <div className="text-center space-y-2">
                                    <Loader2 className="w-8 h-8 text-emerald-600 animate-spin mx-auto" />
                                    <p className="text-[10px] font-black text-[#2D3A2D] uppercase">Mengunggah...</p>
                                </div>
                            </div>
                        )}
                    </div>
                    <input
                        type="file"
                        ref={fileInputRef}
                        onChange={handleFileChange}
                        className="hidden"
                        accept="image/*"
                    />
                </div>

                {/* Instructions & Features */}
                <div className="space-y-6 bg-emerald-50/50 border border-emerald-100 p-8 rounded-[2.5rem]">
                    <div className="space-y-2">
                        <h4 className="text-sm font-black text-emerald-900 uppercase tracking-tight flex items-center gap-2">
                            <CheckCircle2 className="w-4 h-4" /> Smart Payment Logic
                        </h4>
                        <p className="text-[11px] text-emerald-800/70 leading-relaxed font-medium">
                            Aktifkan fitur ini untuk memberikan opsi pembayaran QRIS yang dikelola secara dinamis.
                        </p>
                    </div>

                    <ul className="space-y-3">
                        {[
                            'Otomatis muncul di halaman pesanan pelanggan',
                            'Customer mengunggah bukti transfer',
                            'Notifikasi WhatsApp otomatis setelah verifikasi',
                            'Laporan finansial terupdate secara real-time'
                        ].map((item, i) => (
                            <li key={i} className="flex items-start gap-3 text-[10px] font-bold text-emerald-900/60">
                                <div className="mt-1 w-1 h-1 rounded-full bg-emerald-400 shrink-0" />
                                {item}
                            </li>
                        ))}
                    </ul>

                    <div className="pt-4 border-t border-emerald-100 mt-6 flex items-start gap-3 bg-white/50 p-4 rounded-2xl">
                        <AlertCircle className="w-4 h-4 text-emerald-600 shrink-0" />
                        <div>
                            <p className="text-[10px] font-black text-emerald-900 uppercase">Verifikasi Manual</p>
                            <p className="text-[9px] text-emerald-800/60 leading-tight">
                                Pastikan staff memeriksa bukti transfer di dashboard sebelum memvalidasi status pesanan.
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
}

'use client';

import React, { useState } from 'react';
import { processIngestion, executeIngestion } from '@/lib/actions/rasa-ibu/ingestion';
import { toast } from 'sonner';

export default function SmartIngestionPanel({ brandId, onClose }: { brandId: string; onClose: () => void }) {
    const [file, setFile] = useState<File | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);
    const [result, setResult] = useState<any>(null);
    const [assignedMappings, setAssignedMappings] = useState<Record<number, string>>({});
    const [isExecuting, setIsExecuting] = useState(false);

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (!selectedFile) return;

        setFile(selectedFile);
        setIsProcessing(true);

        const reader = new FileReader();
        reader.onload = async (event) => {
            const content = event.target?.result as string;
            const res = await processIngestion(selectedFile.name, content);

            if (res.success && res.data) {
                setResult(res.data);

                // Auto-assign high confidence mappings
                if (res.data.inference?.mappings) {
                    const initial: Record<number, string> = {};
                    res.data.inference.mappings.forEach((m: any) => {
                        if (m.canonicalField && m.confidence > 0.7) {
                            initial[m.sourceColumnIndex] = m.canonicalField;
                        }
                    });
                    setAssignedMappings(initial);
                }
            } else {
                toast.error(res.error || 'Gagal menganalisis file CSV');
                setResult(null);
            }
            setIsProcessing(false);
        };
        reader.readAsText(selectedFile);
    };

    const handleExecute = async () => {
        if (!result) return;
        setIsExecuting(true);
        const csvRows = result.sampleRows; // In a real app, you'd send the full content or stream it
        const res = await executeIngestion(brandId, result.headers, csvRows, assignedMappings as any);
        if (res.success) {
            toast.success(`Berhasil mengimpor ${res.count} pesanan.`);
            onClose();
        } else {
            toast.error(`Gagal: ${res.error}`);
        }
        setIsExecuting(false);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#2D3A2D]/40 backdrop-blur-sm p-6">
            <div className="bg-[#FDFBF7] w-full max-w-4xl rounded-[2.5rem] shadow-2xl border border-[#E5E1D8] overflow-hidden animate-in fade-in zoom-in duration-300">
                {/* Header */}
                <div className="px-10 py-8 border-b border-[#E5E1D8] flex justify-between items-center bg-white">
                    <div className="space-y-1">
                        <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66]">Kecerdasan Achiera</span>
                        <h2 className="text-2xl font-black text-[#2D3A2D]">Impor Buku Pesanan Cerdas</h2>
                    </div>
                    <button onClick={onClose} className="text-slate-400 hover:text-slate-800 transition-colors">
                        ✕
                    </button>
                </div>

                <div className="p-10 space-y-8 max-h-[70vh] overflow-y-auto">
                    {!result ? (
                        <div className="border-2 border-dashed border-[#E5E1D8] rounded-3xl p-16 text-center space-y-6 bg-white/50">
                            <div className="w-16 h-16 bg-[#F9F7F2] rounded-full flex items-center justify-center mx-auto shadow-inner">
                                <span className="text-2xl">📄</span>
                            </div>
                            <div className="space-y-2">
                                <p className="text-sm font-black text-[#2D3A2D]">Tarik file CSV (Shopee/Tokopedia) ke sini</p>
                                <p className="text-xs text-slate-400 font-medium italic">Achiera akan menebak kolom secara otomatis.</p>
                            </div>
                            <input
                                type="file"
                                accept=".csv"
                                onChange={handleFileChange}
                                className="hidden"
                                id="csv-upload"
                            />
                            <label
                                htmlFor="csv-upload"
                                className="inline-block px-8 py-3 bg-[#2D3A2D] text-[#FDFBF7] text-[10px] font-black uppercase tracking-widest rounded-xl hover:scale-105 transition-transform cursor-pointer shadow-lg"
                            >
                                {isProcessing ? 'Menganalisis...' : 'Pilih File CSV'}
                            </label>
                        </div>
                    ) : (
                        <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
                            {/* Inference Results */}
                            <div className="space-y-4">
                                <h3 className="text-xs font-black uppercase tracking-widest text-[#8B7E66]">Hasil Analisis Achiera</h3>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {result.headers?.map((header: string, idx: number) => {
                                        const mapping = result.inference?.mappings?.find((m: any) => m.sourceColumnIndex === idx);
                                        const isMapped = !!assignedMappings[idx];
                                        return (
                                            <div key={idx} className={`p-4 rounded-2xl border transition-all ${isMapped ? 'bg-emerald-50 border-emerald-100' : 'bg-white border-slate-100'}`}>
                                                <div className="flex justify-between items-center mb-2">
                                                    <span className="text-[10px] font-mono text-slate-400">Kolom {idx + 1}</span>
                                                    {mapping?.confidence > 0.8 && (
                                                        <span className="text-[9px] font-black uppercase text-emerald-600 bg-emerald-100/50 px-2 py-0.5 rounded-md">Yakin ✨</span>
                                                    )}
                                                </div>
                                                <p className="text-xs font-black text-[#2D3A2D] mb-3">{header}</p>
                                                <select
                                                    value={assignedMappings[idx] || ''}
                                                    onChange={(e) => setAssignedMappings({ ...assignedMappings, [idx]: e.target.value })}
                                                    className="w-full text-[10px] font-bold p-2 bg-transparent border-b border-slate-200 focus:outline-none"
                                                >
                                                    <option value="">Abaikan</option>
                                                    <option value="order_id">ID Pesanan (No. Invoice)</option>
                                                    <option value="customer_name">Nama Pelanggan</option>
                                                    <option value="transaction_date">Tanggal</option>
                                                    <option value="total_amount">Total Harga</option>
                                                    <option value="product_name">Nama Produk</option>
                                                    <option value="quantity">Jumlah</option>
                                                </select>
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>

                            {/* Blocking Issues / Warnings */}
                            {result.inference?.blockingIssues?.length > 0 && (
                                <div className="p-4 bg-amber-50 border border-amber-100 rounded-2xl space-y-2">
                                    <p className="text-[10px] font-black text-amber-700 uppercase tracking-widest">⚠️ Hal yang Perlu Diperhatikan</p>
                                    <ul className="text-xs text-amber-600 italic space-y-1">
                                        {result.inference.blockingIssues.map((issue: string, i: number) => (
                                            <li key={i}>— {issue}</li>
                                        ))}
                                    </ul>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {/* Footer Actions */}
                <div className="p-10 bg-[#F9F7F2] border-t border-[#E5E1D8] flex justify-between items-center">
                    <button onClick={() => setResult(null)} className="text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-colors">
                        Batal
                    </button>
                    <button
                        disabled={!result || isExecuting}
                        onClick={handleExecute}
                        className={`px-10 py-4 bg-[#2D3A2D] text-[#FDFBF7] text-[10px] font-black uppercase tracking-widest rounded-2xl shadow-xl transition-all ${(!result || isExecuting) ? 'opacity-30' : 'hover:scale-105 active:scale-95'}`}
                    >
                        {isExecuting ? 'Memproses...' : 'Eksekusi Impor'}
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { adjustStock } from '@/lib/actions/rasa-ibu/stock';
import { X } from 'lucide-react';
import { toast } from 'sonner';

export default function StockAuditHub({ products, onClose }: { products: any[]; onClose: () => void }) {
    const [selectedVariantId, setSelectedVariantId] = useState('');
    const [adjustment, setAdjustment] = useState(0);
    const [reason, setReason] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);

    const variants = products.flatMap(p => (p.variants || []).map((v: any) => ({
        ...v,
        productName: p.name
    })));

    const selectedVariant = variants.find(v => v.id === selectedVariantId);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedVariantId || adjustment === 0) return;

        setIsSubmitting(true);
        const res = await adjustStock({
            variantId: selectedVariantId,
            adjustment,
            reason: reason || 'Audit Rutin Dapur',
            type: adjustment > 0 ? 'IN' : 'ADJUSTMENT',
            operatorId: 'SYSTEM_AUDIT'
        });

        if (res.success) {
            onClose();
        } else {
            toast.error(`Error: ${res.error}`);
        }
        setIsSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#2D3A2D]/40 backdrop-blur-sm p-6">
            <div className="bg-[#FDFBF7] w-full max-w-lg rounded-[2.5rem] shadow-2xl border border-[#E5E1D8] overflow-hidden animate-in fade-in zoom-in duration-300">
                <div className="px-10 py-8 border-b border-[#E5E1D8] flex justify-between items-center bg-white">
                    <div className="space-y-1">
                        <span className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8B7E66]">Pantry Audit</span>
                        <h2 className="text-2xl font-black text-[#2D3A2D]">Audit Stok Dapur</h2>
                    </div>
                    <button onClick={onClose} className="p-3 hover:bg-slate-100 rounded-full transition-colors">
                        <X className="w-6 h-6 text-slate-400" />
                    </button>
                </div>

                <form onSubmit={handleSubmit} className="p-10 space-y-6">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Pilih Varian Produk</label>
                        <select
                            required
                            value={selectedVariantId}
                            onChange={(e) => setSelectedVariantId(e.target.value)}
                            className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm focus:outline-none"
                        >
                            <option value="">Pilih...</option>
                            {variants.map(v => (
                                <option key={v.id} value={v.id}>{v.productName} - {v.name} (Sisa: {v.stockOnHand})</option>
                            ))}
                        </select>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Penyesuaian (+/-)</label>
                            <input
                                type="number"
                                required
                                value={adjustment}
                                onChange={(e) => setAdjustment(parseInt(e.target.value))}
                                className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm"
                                placeholder="E.g. -5 atau 10"
                            />
                        </div>
                        <div className="flex items-end pb-3">
                            {selectedVariant && (
                                <div className="text-right w-full">
                                    <p className="text-[10px] font-black text-slate-400 uppercase">Stok Baru</p>
                                    <p className="text-lg font-black text-[#2D3A2D]">{selectedVariant.stockOnHand + adjustment}</p>
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Alasan Perubahan</label>
                        <textarea
                            value={reason}
                            onChange={(e) => setReason(e.target.value)}
                            className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm h-24 focus:outline-none"
                            placeholder="Contoh: Diterima dari supplier atau Rusak saat pengiriman"
                        />
                    </div>

                    <div className="pt-6 flex justify-between items-center">
                        <button type="button" onClick={onClose} className="text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-600">
                            Batal
                        </button>
                        <button
                            disabled={isSubmitting || adjustment === 0 || !selectedVariantId}
                            type="submit"
                            className={`px-10 py-4 bg-[#2D3A2D] text-[#FDFBF7] text-[10px] font-black uppercase tracking-widest rounded-2xl shadow-xl transition-all ${isSubmitting || adjustment === 0 || !selectedVariantId ? 'opacity-30' : 'hover:scale-105 active:scale-95'}`}
                        >
                            {isSubmitting ? 'Menyimpan...' : 'Update Stok'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

