                            </select>
                            <select
                                value={year}
                                onChange={(e) => setYear(parseInt(e.target.value))}
                                className="bg-white border border-[#E5E1D8] rounded-xl px-4 py-2 text-xs font-black outline-none focus:border-emerald-500"
                            >
                                <option value={2025}>2025</option>
                            </select>
