import React from 'react';

export default function KitchenRhythm({ rhythm }: { rhythm: { averagePrepTimeMinutes: number; tempoLabel: string } }) {
    const isBusy = rhythm.tempoLabel === 'SIBUK';
    const isNormal = rhythm.tempoLabel === 'NORMAL';

    return (
        <div className="bg-[#FDFBF7] border border-[#E5E1D8] p-6 rounded-2xl space-y-4">
            <div className="flex justify-between items-center">
                <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-[#8B7E66]">Tempo Pemenuhan Dapur</h3>
                <div className="flex items-center gap-2">
                    <span className={`text-[10px] font-black uppercase ${isBusy ? 'text-amber-600' : 'text-emerald-600'}`}>
                        {rhythm.tempoLabel === 'TENANG' ? 'Hening & Teratur' : rhythm.tempoLabel === 'NORMAL' ? 'Ritme Mengalir' : 'Dapur Bersemangat'}
                    </span>
                    <div className="relative flex h-2 w-2">
                        <span className={`animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 ${isBusy ? 'bg-amber-400' : 'bg-emerald-400'}`}></span>
                        <span className={`relative inline-flex rounded-full h-2 w-2 ${isBusy ? 'bg-amber-500' : 'bg-emerald-500'}`}></span>
                    </div>
                </div>
            </div>

            <div className="flex items-end gap-1 h-12">
                {[...Array(12)].map((_, i) => (
                    <div
                        key={i}
                        className={`flex-1 rounded-t-sm transition-all duration-1000 ${isBusy ? 'bg-amber-200' : 'bg-emerald-100'
                            }`}
                        style={{
                            height: `${20 + Math.random() * (isBusy ? 80 : 40)}%`,
                            opacity: 0.3 + (i / 12) * 0.7
                        }}
                    ></div>
                ))}
            </div>

            <div className="pt-2">
                <p className="text-[9px] font-medium text-slate-400 italic">
                    "Ritme saat ini rata-rata {rhythm.averagePrepTimeMinutes} menit per hidangan. Semuanya terkendali."
                </p>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Zap, TrendingUp, AlertTriangle, UserCheck, DollarSign, Loader2, Sparkles, ArrowRight, MessageCircle, Download } from 'lucide-react';
import { toast } from 'sonner';
import { getCustomerLTVAction } from '@/lib/actions/rasa-ibu/intelligence';
import { exportToCSV } from '@/lib/utils/exportUtils';

interface LTVForecastProps {
    brandId: string;
}

export default function LTVForecast({ brandId }: LTVForecastProps) {
    const [isLoading, setIsLoading] = useState(true);
    const [stats, setStats] = useState<any>(null);

    useEffect(() => {
        async function load() {
            const res = await getCustomerLTVAction(brandId);
            if (res.success) {
                setStats(res.data);
            }
            setIsLoading(false);
        }
        load();
    }, [brandId]);

    const currency = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 });

    const handleChat = (cust: any) => {
        const phone = cust.id.replace(/\D/g, '');
        if (!phone || phone.length < 5) {
            toast.error('Nomor WhatsApp tidak valid untuk pelanggan ini.');
            return;
        }

        const template = cust.template || 'Halo Bunda {{name}}, apa kabar?';
        const message = template.replace('{{name}}', cust.name);

        const waUrl = `https://wa.me/${phone.startsWith('0') ? '62' + phone.substring(1) : phone}?text=${encodeURIComponent(message)}`;
        window.open(waUrl, '_blank');
    };

    if (isLoading) {
        return (
            <div className="bg-white p-8 rounded-[2.5rem] border border-[#E5E1D8] shadow-sm flex flex-col items-center justify-center min-h-[300px] space-y-4">
                <Loader2 className="w-8 h-8 text-amber-600 animate-spin" />
                <p className="text-xs font-black text-[#8B7E66] uppercase tracking-widest">Memproses Ramalan Masa Depan...</p>
            </div>
        );
    }

    if (!stats || stats.customers?.length === 0) return null;

    return (
        <div className="space-y-10">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex items-center gap-4">
                    <div className="p-4 bg-amber-50 text-amber-600 rounded-[1.5rem] shadow-inner">
                        <Sparkles className="w-6 h-6" />
                    </div>
                    <div>
                        <h3 className="text-[10px] font-black text-amber-400 uppercase tracking-[0.3em]">Predictive Analytics</h3>
                        <h2 className="text-2xl font-black text-[#2D3A2D]">Customer Lifetime Value (LTV)</h2>
                    </div>
                </div>
                <button
                    onClick={() => {
                        const exportData = stats.customers.map((cust: any) => ({
                            'Nama': cust.name,
                            'Predicted LTV': cust.predictedLTV,
                            'Risk Level': cust.risk,
                            'Recency (hari)': cust.recencyDays,
                            'Total Orders': cust.orders || 0,
                            'Total Spent': cust.spent || 0,
                            'WhatsApp': cust.id
                        }));
                        exportToCSV(exportData, 'Customer_LTV_Prediction');
                    }}
                    className="px-4 py-2 bg-amber-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-amber-700 transition-all shadow-lg shadow-amber-200 flex items-center gap-2"
                >
                    <Download className="w-3.5 h-3.5" />
                    Export CSV
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
                {/* Prediction Summary */}
                <div className="lg:col-span-4 bg-gradient-to-br from-amber-500 to-orange-600 rounded-[3rem] p-10 text-white shadow-2xl relative overflow-hidden">
                    <div className="absolute -right-10 -bottom-10 w-48 h-48 bg-white/10 rounded-full blur-3xl"></div>
                    <div className="relative z-10 space-y-10">
                        <div className="space-y-2">
                            <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80">Potensi Revenue (12 Bln)</p>
                            <h3 className="text-4xl font-black tracking-tighter">{currency.format(stats.totalPotential)}</h3>
                        </div>
                        <div className="p-6 bg-white/10 backdrop-blur-md rounded-2xl border border-white/20">
                            <p className="text-[10px] font-black uppercase mb-1">Nilai Rata-rata per Orang</p>
                            <p className="text-xl font-black">{currency.format(stats.avgLTV)}</p>
                        </div>
                        <p className="text-[10px] font-medium leading-relaxed opacity-90 italic">
                            *Prediksi berdasarkan data belanja historis dan frekuensi transaksi Bunda di sistem.
                        </p>
                    </div>
                </div>

                {/* VIPs at Risk */}
                <div className="lg:col-span-8 bg-white rounded-[3rem] border border-[#E5E1D8] p-10 shadow-sm space-y-8">
                    <div className="flex items-center justify-between">
                        <h4 className="text-xs font-black uppercase tracking-widest text-[#2D3A2D]">Target Retention: VIP at Risk</h4>
                        <div className="px-3 py-1 bg-rose-50 text-rose-600 text-[8px] font-black rounded-full uppercase">Perlu Perhatian Segera</div>
                    </div>

                    <div className="space-y-4">
                        {stats.customers.filter((c: any) => c.risk !== 'LOW').slice(0, 4).map((cust: any, idx: number) => (
                            <div key={idx} className="flex items-center justify-between p-4 hover:bg-slate-50 rounded-2xl transition-all group border border-transparent hover:border-slate-100">
                                <div className="flex items-center gap-4">
                                    <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-black ${cust.risk === 'HIGH' ? 'bg-rose-100 text-rose-600' : 'bg-amber-100 text-amber-600'}`}>
                                        {cust.name.substring(0, 1)}
                                    </div>
                                    <div>
                                        <div className="flex items-center gap-2">
                                            <p className="text-sm font-black text-[#2D3A2D]">{cust.name}</p>
                                            <span className={`text-[7px] font-black uppercase px-2 py-0.5 rounded-full ${cust.risk === 'HIGH' ? 'bg-rose-500 text-white' : 'bg-amber-500 text-white'}`}>
                                                {cust.risk} RISK
                                            </span>
                                        </div>
                                        <div className="flex items-center gap-2 mt-1">
                                            <span className="text-[9px] text-slate-400 font-bold">{cust.recencyDays} hari absen</span>
                                            <span className="text-[9px] text-slate-300">•</span>
                                            <span className="text-[9px] text-emerald-600 font-black">LTV: {currency.format(cust.predictedLTV)}</span>
                                        </div>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3">
                                    <button
                                        onClick={() => handleChat(cust)}
                                        className="flex items-center gap-2 px-5 py-2.5 bg-emerald-500 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 transition-all shadow-lg shadow-emerald-200"
                                    >
                                        <MessageCircle className="w-3.5 h-3.5" />
                                        Chat Bunda
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="p-6 bg-slate-50 rounded-[2rem] border border-dashed border-slate-200">
                        <p className="text-[10px] font-medium text-slate-500 italic text-center">
                            "Mencegah pelanggan VIP pergi jauh lebih murah 5x lipat daripada mencari pelanggan baru. Klik tombol chat di atas untuk mengirimkan pesan kangen pribadi."
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { getLoyaltyStatsAction, redeemLoyaltyPointsAction } from '@/lib/actions/rasa-ibu/intelligence';
import { Gift, Search, Coins, Award, History, ArrowRight, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

interface LoyaltyPanelProps {
    brandId: string;
}

export default function LoyaltyPanel({ brandId }: LoyaltyPanelProps) {
    const [phone, setPhone] = useState('');
    const [account, setAccount] = useState<any>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [redeemAmount, setRedeemAmount] = useState<number>(0);
    const [pointValue, setPointValue] = useState<number>(100);

    const handleCheck = async () => {
        if (!phone) return toast.error('Masukkan nomor HP');
        setIsLoading(true);
        const res = await getLoyaltyStatsAction({ customerPhone: phone, brandId });

        if (res.success && res.data) {
            setAccount(res.data);
            if (res.config?.pointValueInRupiah) {
                setPointValue(res.config.pointValueInRupiah);
            }
        } else if (res.success) {
            setAccount(null);
            toast.info('Pelanggan belum memiliki point loyalty.');
        } else {
            toast.error(res.error);
        }
        setIsLoading(false);
    };

    const handleRedeem = async () => {
        if (!redeemAmount || redeemAmount <= 0) return;
        if (redeemAmount > (account?.balance || 0)) return toast.error('Poin tidak mencukupi');

        setIsLoading(true);
        const res = await redeemLoyaltyPointsAction({
            brandId,
            customerPhone: phone,
            points: redeemAmount,
            description: `Redemption via Dashboard`
        });

        if (res.success) {
            toast.success(`Berhasil redeem ${redeemAmount} poin!`);
            handleCheck(); // Refresh
            setRedeemAmount(0);
        } else {
            toast.error(res.error);
        }
        setIsLoading(false);
    };

    const getTierColor = (tier: string) => {
        switch (tier) {
            case 'PLATINUM': return 'bg-slate-800 text-white border-slate-600';
            case 'GOLD': return 'bg-yellow-100 text-yellow-700 border-yellow-300';
            case 'SILVER': return 'bg-slate-100 text-slate-700 border-slate-300';
            default: return 'bg-orange-50 text-orange-700 border-orange-200';
        }
    };

    return (
        <div className="space-y-8">
            <div className="flex items-center gap-4">
                <div className="p-4 bg-purple-50 text-purple-600 rounded-[1.5rem] shadow-inner">
                    <Gift className="w-6 h-6" />
                </div>
                <div>
                    <h3 className="text-[10px] font-black text-purple-600 uppercase tracking-[0.3em]">Retention</h3>
                    <h2 className="text-2xl font-black text-[#2D3A2D]">Loyalty & Gamification</h2>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Search & Action */}
                <div className="bg-white p-8 rounded-[2.5rem] border border-[#E5E1D8] shadow-sm space-y-6">
                    <h4 className="font-black text-[#2D3A2D] flex items-center gap-2">
                        <Search className="w-4 h-4 text-purple-500" />
                        Cek Poin Pelanggan
                    </h4>

                    <div className="flex gap-2">
                        <input
                            type="tel"
                            value={phone}
                            onChange={e => setPhone(e.target.value)}
                            placeholder="Nomor HP (0812...)"
                            className="flex-1 px-4 py-3 rounded-xl border border-[#E5E1D8] text-sm font-medium focus:outline-none focus:ring-2 focus:ring-purple-500/20"
                        />
                        <button
                            onClick={handleCheck}
                            disabled={isLoading}
                            className="px-6 bg-purple-600 text-white rounded-xl font-bold hover:bg-purple-700 transition-all disabled:opacity-50"
                        >
                            {isLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Cek'}
                        </button>
                    </div>

                    {account && (
                        <div className="space-y-6 animate-in fade-in slide-in-from-top-4">
                            <div className="bg-gradient-to-br from-purple-500 to-pink-500 p-6 rounded-[2rem] text-white shadow-lg shadow-purple-200 relative overflow-hidden">
                                <div className="absolute top-0 right-0 p-4 opacity-10">
                                    <Award className="w-32 h-32 transform rotate-12" />
                                </div>
                                <div className="relative z-10">
                                    <div className="flex justify-between items-start">
                                        <div>
                                            <p className="text-purple-100 text-xs font-bold uppercase tracking-widest">Total Poin</p>
                                            <h3 className="text-4xl font-black mt-1">{account.balance}</h3>
                                        </div>
                                        <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase border ${getTierColor(account.tier)}`}>
                                            {account.tier} TIER
                                        </span>
                                    </div>
                                    <div className="mt-8 flex gap-4 text-sm font-medium text-purple-100">
                                        <div>
                                            <p className="text-[10px] opacity-70 uppercase">Lifetime Earned</p>
                                            <p>{account.lifetimeEarned}</p>
                                        </div>
                                        <div>
                                            <p className="text-[10px] opacity-70 uppercase">Redeemed</p>
                                            <p>{account.lifetimeRedeemed}</p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="space-y-4">
                                <label className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66] block">Tukar Poin</label>
                                <div className="flex gap-2">
                                    {[50, 100, 200].map(amt => (
                                        <button
                                            key={amt}
                                            onClick={() => setRedeemAmount(amt)}
                                            className={`flex-1 py-2 rounded-lg text-xs font-bold border transition-all ${redeemAmount === amt
                                                ? 'bg-purple-600 text-white border-purple-600'
                                                : 'bg-white text-slate-600 border-slate-200 hover:border-purple-300'
                                                }`}
                                        >
                                            {amt} Poin
                                        </button>
                                    ))}
                                </div>

                                {redeemAmount > 0 && (
                                    <div className="bg-slate-50 p-4 rounded-xl text-center space-y-2">
                                        <p className="text-xs text-slate-500">Nilai Penukaran:</p>
                                        <p className="text-xl font-black text-purple-600">Rp {(redeemAmount * pointValue).toLocaleString('id-ID')}</p>
                                        <button
                                            onClick={handleRedeem}
                                            disabled={isLoading}
                                            className="w-full py-3 bg-slate-900 text-white rounded-xl font-bold text-xs uppercase tracking-widest hover:bg-black transition-all"
                                        >
                                            Konfirmasi Redeem
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>

                {/* History */}
                <div className="space-y-4">
