'use client';

import React, { useEffect, useState } from 'react';
import {
    Users,
    Star,
    Gift,
    TrendingUp,
    Award,
    RefreshCw,
    Search,
    Crown
} from 'lucide-react';
import { toast } from 'sonner';
import {
    getLoyaltyMembers,
    getLoyaltyStats,
    getLoyaltyRewards,
    createLoyaltyReward
} from '@/lib/actions/rasa-ibu/businessIntelligence';

interface LoyaltyProgramDashboardProps {
    brandId: string;
    onClose?: () => void;
}

export default function LoyaltyProgramDashboard({ brandId, onClose }: LoyaltyProgramDashboardProps) {
    const [isLoading, setIsLoading] = useState(true);
    const [stats, setStats] = useState<any>(null);
    const [members, setMembers] = useState<any[]>([]);
    const [rewards, setRewards] = useState<any[]>([]);
    const [activeTab, setActiveTab] = useState<'overview' | 'members' | 'rewards'>('overview');
    const [searchQuery, setSearchQuery] = useState('');
    const [tierFilter, setTierFilter] = useState<string>('ALL');

    const loadData = async () => {
        setIsLoading(true);
        const [statsRes, membersRes, rewardsRes] = await Promise.all([
            getLoyaltyStats(brandId),
            getLoyaltyMembers(brandId),
            getLoyaltyRewards(brandId)
        ]);

        if (statsRes.success) setStats(statsRes.data);
        if (membersRes.success) setMembers(membersRes.data || []);
        if (rewardsRes.success) setRewards(rewardsRes.data || []);

        setIsLoading(false);
    };

    useEffect(() => {
        loadData();
    }, [brandId]);

    const getTierColor = (tier: string) => {
        switch (tier) {
            case 'PLATINUM': return 'bg-purple-100 text-purple-700 border-purple-300';
            case 'GOLD': return 'bg-yellow-100 text-yellow-700 border-yellow-300';
            case 'SILVER': return 'bg-gray-100 text-gray-700 border-gray-300';
            default: return 'bg-orange-100 text-orange-700 border-orange-300';
        }
    };

    const getTierIcon = (tier: string) => {
        switch (tier) {
            case 'PLATINUM': return '💎';
            case 'GOLD': return '🏆';
            case 'SILVER': return '🥈';
            default: return '🥉';
        }
    };

    const filteredMembers = members.filter(m => {
        const matchesSearch = m.customerName.toLowerCase().includes(searchQuery.toLowerCase()) ||
            m.customerPhone.includes(searchQuery);
        const matchesTier = tierFilter === 'ALL' || m.tier === tierFilter;
        return matchesSearch && matchesTier;
    });

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            minimumFractionDigits: 0
        }).format(amount);
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-purple-100 rounded-lg">
                        <Award className="w-6 h-6 text-purple-600" />
                    </div>
                    <div>
                        <h2 className="text-xl font-bold text-gray-800">Loyalty Program Hub</h2>
                        <p className="text-sm text-gray-500">Manage members, tiers & rewards</p>
                    </div>
                </div>
                <button
                    onClick={loadData}
                    className="px-4 py-2 bg-purple-600 text-white rounded-lg font-semibold hover:bg-purple-700 transition-colors flex items-center gap-2"
                >
                    <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
                    Refresh
                </button>
            </div>

            {/* Stats Cards */}
            {stats && (
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                    <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-4 rounded-xl border border-purple-200">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-purple-500 rounded-lg">
                                <Users className="w-5 h-5 text-white" />
                            </div>
                            <div>
                                <div className="text-2xl font-bold text-purple-900">{stats.totalMembers}</div>
                                <div className="text-xs text-purple-700 font-semibold">Total Members</div>
                            </div>
                        </div>
                    </div>
                    <div className="bg-gradient-to-br from-green-50 to-green-100 p-4 rounded-xl border border-green-200">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-green-500 rounded-lg">
                                <TrendingUp className="w-5 h-5 text-white" />
                            </div>
                            <div>
                                <div className="text-2xl font-bold text-green-900">{stats.activeMembers}</div>
                                <div className="text-xs text-green-700 font-semibold">Active Members</div>
                            </div>
                        </div>
                    </div>
                    <div className="bg-gradient-to-br from-amber-50 to-amber-100 p-4 rounded-xl border border-amber-200">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-amber-500 rounded-lg">
                                <Star className="w-5 h-5 text-white" />
                            </div>
                            <div>
                                <div className="text-2xl font-bold text-amber-900">{(stats.totalPointsIssued || 0).toLocaleString()}</div>
                                <div className="text-xs text-amber-700 font-semibold">Points Issued</div>
                            </div>
                        </div>
                    </div>
                    <div className="bg-gradient-to-br from-blue-50 to-blue-100 p-4 rounded-xl border border-blue-200">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-blue-500 rounded-lg">
                                <Gift className="w-5 h-5 text-white" />
                            </div>
                            <div>
                                <div className="text-2xl font-bold text-blue-900">{(stats.totalPointsAvailable || 0).toLocaleString()}</div>
                                <div className="text-xs text-blue-700 font-semibold">Points Available</div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Tier Distribution */}
            {stats && (
                <div className="bg-white rounded-xl border border-gray-100 shadow-sm p-6">
                    <h3 className="text-lg font-bold text-gray-800 mb-4">Tier Distribution</h3>
                    <div className="grid grid-cols-4 gap-4">
                        {['BRONZE', 'SILVER', 'GOLD', 'PLATINUM'].map(tier => (
                            <div key={tier} className={`p-4 rounded-lg border-2 ${getTierColor(tier)}`}>
                                <div className="text-center">
                                    <div className="text-3xl mb-2">{getTierIcon(tier)}</div>
                                    <div className="text-2xl font-bold">{stats.tierCounts[tier] || 0}</div>
                                    <div className="text-xs font-semibold uppercase">{tier}</div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Tabs */}
            <div className="flex gap-2 p-1 bg-gray-100 rounded-lg w-fit">
                {[
                    { id: 'overview', label: 'Overview', icon: Star },
                    { id: 'members', label: 'Members', icon: Users },
                    { id: 'rewards', label: 'Rewards', icon: Gift }
                ].map(tab => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id as any)}
                        className={`px-4 py-2 rounded-md text-sm font-medium transition-all flex items-center gap-2 ${activeTab === tab.id ? 'bg-white text-purple-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'
                            }`}
                    >
                        <tab.icon className="w-4 h-4" />
                        {tab.label}
                    </button>
                ))}
            </div>

            {/* Tab Content */}
            <div className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden">
                {activeTab === 'overview' && (
                    <div className="p-6 space-y-4">
                        <h3 className="text-lg font-bold text-gray-800">Program Overview</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="p-4 bg-purple-50 rounded-lg">
                                <h4 className="font-bold text-purple-900 mb-2">Point System</h4>
                                <ul className="text-sm text-purple-700 space-y-1">
                                    <li>✓ 1 point per Rp 10,000 spent</li>
                                    <li>✓ Tier multipliers (up to 2x)</li>
                                    <li>✓ Birthday date (exact): 2x points</li>
                                    <li>✓ Points valid for 1 year</li>
                                </ul>
                            </div>
                            <div className="p-4 bg-amber-50 rounded-lg">
                                <h4 className="font-bold text-amber-900 mb-2">Tier Benefits</h4>
                                <ul className="text-sm text-amber-700 space-y-1">
                                    <li>🥉 Bronze: 1x points</li>
                                    <li>🥈 Silver: 1.25x points (Rp 1M)</li>
                                    <li>🏆 Gold: 1.5x points (Rp 5M)</li>
                                    <li>💎 Platinum: 2x points (Rp 10M)</li>
                                </ul>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'members' && (
                    <div className="p-6">
                        <div className="flex items-center gap-4 mb-4">
                            <div className="flex-1 relative">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                                <input
                                    type="text"
                                    placeholder="Search by name or phone..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500"
                                />
                            </div>
                            <select
                                value={tierFilter}
                                onChange={(e) => setTierFilter(e.target.value)}
                                className="px-4 py-2 border border-gray-200 rounded-lg font-medium"
                            >
                                <option value="ALL">All Tiers</option>
                                <option value="PLATINUM">Platinum</option>
                                <option value="GOLD">Gold</option>
                                <option value="SILVER">Silver</option>
                                <option value="BRONZE">Bronze</option>
                            </select>
                        </div>

                        {filteredMembers.length === 0 ? (
                            <div className="text-center py-12 text-gray-500">
                                <Users className="w-12 h-12 mx-auto mb-3 opacity-30" />
                                <p>No members found</p>
                            </div>
                        ) : (
                            <div className="space-y-2">
                                {filteredMembers.slice(0, 20).map((member) => (
                                    <div key={member.id} className="p-4 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-4">
                                                <div className="text-2xl">{getTierIcon(member.tier)}</div>
                                                <div>
                                                    <div className="font-bold text-gray-800">{member.customerName}</div>
                                                    <div className="text-sm text-gray-500">{member.customerPhone}</div>
                                                </div>
                                            </div>
                                            <div className="text-right">
                                                <div className="text-lg font-bold text-purple-600">{(member.availablePoints || 0).toLocaleString()} pts</div>
                                                <div className="text-xs text-gray-500">{member.totalOrders} orders • {formatCurrency(Number(member.totalSpent))}</div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {activeTab === 'rewards' && (
                    <div className="p-6">
                        <h3 className="text-lg font-bold text-gray-800 mb-4">Reward Catalog</h3>
                        {rewards.length === 0 ? (
                            <div className="text-center py-12 text-gray-500">
                                <Gift className="w-12 h-12 mx-auto mb-3 opacity-30" />
                                <p>No rewards configured yet</p>
                                <p className="text-sm mt-2">Create rewards to encourage redemptions!</p>
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                {rewards.map((reward) => (
                                    <div key={reward.id} className="p-4 bg-gradient-to-br from-purple-50 to-purple-100 rounded-lg border border-purple-200">
                                        <div className="flex items-start justify-between mb-2">
                                            <div className="flex-1">
                                                <h4 className="font-bold text-purple-900">{reward.name}</h4>
                                                <p className="text-sm text-purple-700 mt-1">{reward.description}</p>
                                            </div>
                                            <div className="ml-4 text-right">
                                                <div className="text-2xl font-bold text-purple-600">{reward.pointsCost}</div>
                                                <div className="text-xs text-purple-700">points</div>
                                            </div>
                                        </div>
                                        <div className="mt-3 flex items-center justify-between text-xs text-purple-600">
                                            <span>Redeemed: {reward.timesRedeemed}x</span>
                                            <span className="px-2 py-1 bg-purple-200 rounded font-bold">{reward.rewardType}</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { getMarketplacePerformanceAction } from '@/lib/actions/rasa-ibu/intelligence';
import { ShoppingBag, TrendingUp, BarChart3, AlertCircle, Loader2, Sparkles, Tag, Download } from 'lucide-react';
import { exportToCSV } from '@/lib/utils/exportUtils';

interface MarketplaceTrackerProps {
    brandId: string;
}

export default function MarketplaceTracker({ brandId }: MarketplaceTrackerProps) {
    const [data, setData] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const currency = new Intl.NumberFormat('id-ID', {
        style: 'currency',
        currency: 'IDR',
        maximumFractionDigits: 0
    });

    useEffect(() => {
        async function load() {
            const res = await getMarketplacePerformanceAction(brandId);
            if (res.success && res.data) {
                setData(res.data);
            }
            setIsLoading(false);
        }
        load();
    }, [brandId]);

    if (isLoading) {
        return (
            <div className="bg-white p-12 rounded-[3.5rem] border border-[#E5E1D8] flex flex-col items-center justify-center space-y-4">
                <Loader2 className="w-8 h-8 text-orange-500 animate-spin" />
                <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Menganalisis Efektivitas Program Marketplace...</p>
            </div>
        );
    }

    if (data.length === 0) {
        return (
            <div className="bg-white rounded-[3.5rem] border border-[#E5E1D8] p-12 shadow-sm flex flex-col items-center justify-center text-center space-y-6">
                <div className="p-5 bg-orange-50 rounded-[1.5rem] text-orange-200">
                    <ShoppingBag className="w-10 h-10" />
                </div>
                <div className="space-y-2">
                    <h3 className="text-xl font-black text-[#2D3A2D] tracking-tight">Marketplace & Program Ads</h3>
                    <p className="text-xs text-[#8B7E66] font-medium italic max-w-lg">Belum ada transaksi dari GoFood/GrabFood/Shopee yang terdeteksi. Hubungkan channel marketplace Bunda untuk melihat efektivitas iklan dan promo platform otomatis di sini. 🛍️</p>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-[3.5rem] border border-[#E5E1D8] overflow-hidden shadow-sm">
            <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-gradient-to-r from-orange-50/30 to-transparent">
                <div className="flex items-center gap-5">
                    <div className="p-4 bg-orange-100 rounded-[1.5rem] text-orange-600">
                        <ShoppingBag className="w-6 h-6" />
                    </div>
                    <div>
                        <h3 className="text-xl font-black text-[#2D3A2D] tracking-tight">Marketplace & Program Ads</h3>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Efektivitas Campaign Platform (30 Hari Terakhir)</p>
                    </div>
                </div>
                <button
                    onClick={() => {
                        const exportData = data.flatMap((platform: any) =>
                            platform.programs.map((prog: any) => ({
                                'Platform': platform.platform,
                                'Program': prog.tag,
                                'Revenue': prog.revenue,
                                'Orders': prog.orders,
                                'Contribution %': prog.contribution,
                                'Platform Total Revenue': platform.totalRevenue,
                                'Platform Total Orders': platform.totalOrders,
                                'AOV': platform.avgOrderValue
                            }))
                        );
                        exportToCSV(exportData, 'Marketplace_Performance');
                    }}
                    className="px-4 py-2 bg-orange-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-orange-700 transition-all shadow-lg shadow-orange-200 flex items-center gap-2"
                >
                    <Download className="w-3.5 h-3.5" />
                    Export CSV
                </button>
            </div>

            <div className="p-10">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {data.map((platform) => (
                        <div key={platform.platform} className="bg-slate-50/50 rounded-[2.5rem] p-8 border border-slate-100 flex flex-col justify-between group hover:bg-white hover:shadow-xl transition-all duration-500">
                            <div>
                                <div className="flex justify-between items-start mb-6">
                                    <span className="px-4 py-2 bg-white rounded-full text-[10px] font-black uppercase tracking-widest border border-slate-100 shadow-sm">{platform.platform}</span>
                                    <div className="text-right">
                                        <p className="text-[9px] font-bold text-slate-400 uppercase">Total Revenue</p>
                                        <p className="text-lg font-black text-[#2D3A2D]">{currency.format(platform.totalRevenue)}</p>
                                    </div>
                                </div>

                                {platform.programs.length > 0 ? (
                                    <div className="space-y-4 mt-8">
                                        <p className="text-[10px] font-black text-orange-600 uppercase tracking-widest flex items-center gap-2">
                                            <Sparkles className="w-3 h-3" />
                                            Program Terdeteksi
                                        </p>
                                        {platform.programs.map((prog: any) => (
                                            <div key={prog.tag} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm group-hover:border-orange-100 transition-colors">
                                                <div className="flex justify-between items-start mb-2">
                                                    <div className="flex items-center gap-2">
                                                        <Tag className="w-3 h-3 text-orange-500" />
                                                        <span className="text-[11px] font-black text-[#2D3A2D]">{prog.tag}</span>
                                                    </div>
                                                    <span className="text-[9px] font-black text-emerald-600">+{prog.contribution.toFixed(1)}%</span>
                                                </div>
                                                <div className="flex justify-between items-center text-[10px] font-bold text-slate-400">
                                                    <span>{prog.orders} Pesanan</span>
                                                    <span>{currency.format(prog.revenue)}</span>
                                                </div>
                                                <div className="mt-3 h-1 w-full bg-slate-50 rounded-full overflow-hidden">
                                                    <div className="h-full bg-orange-400 rounded-full" style={{ width: `${prog.contribution}%` }}></div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="mt-12 p-6 bg-white/50 rounded-3xl border border-dashed border-slate-200 text-center">
                                        <p className="text-[10px] font-bold text-slate-400 italic">Belum ada program Ads/Voucher terdeteksi untuk platform ini.</p>
                                    </div>
                                )}
                            </div>

                            <div className="mt-8 pt-6 border-t border-slate-100 flex justify-between items-center">
                                <div className="flex items-center gap-2">
                                    <BarChart3 className="w-3.5 h-3.5 text-slate-400" />
                                    <span className="text-[10px] font-bold text-slate-500">{platform.totalOrders} Global Orders</span>
                                </div>
                                <div className="text-right">
                                    <p className="text-[9px] font-bold text-slate-400">AOV</p>
                                    <p className="text-[11px] font-black text-[#2D3A2D]">{currency.format(platform.avgOrderValue)}</p>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                <div className="mt-10 p-6 bg-blue-50 rounded-3xl border border-blue-100 flex items-start gap-4">
                    <AlertCircle className="w-5 h-5 text-blue-600 mt-1" />
                    <div className="space-y-1">
                        <p className="text-[11px] font-black text-blue-900 uppercase tracking-widest leading-relaxed">Executive Insight</p>
                        <p className="text-xs text-blue-800 font-medium leading-relaxed italic">
                            "Analisis ini mendeteksi program promosi otomatis melalui hashtag di catatan internal pesanan. Gunakan #SHOPEE_ADS, #GRAB_PROMO, atau tag lainnya agar AI dapat memisahkan omzet organik vs program berbayar."
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
}

