'use client';

import React, { useState, useEffect } from 'react';
import {
    X, TrendingUp, DollarSign, Zap, AlertCircle,
    ArrowUpRight, ArrowDownRight, Info, PieChart,
    CheckCircle2, Target, BarChart3, Save, Loader2
} from 'lucide-react';
import { toast } from 'sonner';
import {
    calculateDynamicPricing,
    applyPriceAdjustment,
    getRecipeCostingAction
} from '@/lib/actions/rasa-ibu/intelligence';
import { getBrandConfigAction, updateBrandConfigAction } from '@/lib/actions/content/updateBrandConfig';

interface PricingAdvantageHubProps {
    brandId: string;
    onClose: () => void;
}

export default function PricingAdvantageHub({ brandId, onClose }: PricingAdvantageHubProps) {
    const [loading, setLoading] = useState(true);
    const [data, setData] = useState<any>(null);
    const [recipeCosting, setRecipeCosting] = useState<any[]>([]);
    const [config, setConfig] = useState({
        defaultOverheadPerUnit: 0,
        targetMonthlyVolume: 1,
        marketplaceFeeRate: 0.15,
        targetNetMarginRate: 0.30,
        operationalOverhead: 0,
        overheadBreakdown: {
            electricity: 0,
            water: 0,
            gas: 0,
            labor: 0
        }
    });
    const [applying, setApplying] = useState<string | null>(null);
    const [savingConfig, setSavingConfig] = useState(false);

    const loadData = async () => {
        setLoading(true);
        const [pricingRes, configRes, costingRes] = await Promise.all([
            calculateDynamicPricing(brandId),
            getBrandConfigAction(brandId),
            getRecipeCostingAction(brandId)
        ]);

        if (pricingRes.success) {
            setData(pricingRes.data);
        }
        if (configRes.success && configRes.data) {
            setConfig({
                defaultOverheadPerUnit: (configRes.data as any).defaultOverheadPerUnit || 0,
                targetMonthlyVolume: (configRes.data as any).targetMonthlyVolume || 1,
                marketplaceFeeRate: (configRes.data as any).marketplaceFeeRate || 0.15,
                targetNetMarginRate: (configRes.data as any).targetNetMarginRate || 0.30,
                operationalOverhead: (configRes.data as any).operationalOverhead || 0,
                overheadBreakdown: (configRes.data as any).overheadBreakdown || {
                    electricity: 0,
                    water: 0,
                    gas: 0,
                    labor: 0
                }
            });
        }
        if (costingRes?.success) {
            setRecipeCosting(costingRes.data);
        }
        setLoading(false);
    };

    useEffect(() => {
        loadData();
    }, [brandId]);

    const handleApply = async (adj: any) => {
        setApplying(adj.variantId);
        const res = await applyPriceAdjustment(adj.variantId, adj.recommendedPrice);
        if (res.success) {
            await loadData();
        } else {
            toast.error('Gagal memperbarui harga.');
        }
        setApplying(null);
    };

    const handleSaveConfig = async () => {
        setSavingConfig(true);
        const res = await updateBrandConfigAction(brandId, config);
        if (res.success) {
            // Reload pricing data as it depends on these config values
            await loadData();
        } else {
            toast.error('Gagal menyimpan konfigurasi.');
        }
        setSavingConfig(false);
    };

    return (
        <div className="flex flex-col h-full animate-in fade-in slide-in-from-right-8 duration-500">
            {/* Header Area */}
            <div className="flex items-center justify-between mb-10">
                <div className="flex items-center gap-6">
                    <div className="w-16 h-16 bg-gradient-to-br from-emerald-600 to-teal-700 rounded-3xl flex items-center justify-center shadow-2xl shadow-emerald-200">
                        <TrendingUp className="w-8 h-8 text-white" />
                    </div>
                    <div className="space-y-1">
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-emerald-600">Dynamic Pricing Intelligence</span>
                            <div className="bg-emerald-50 text-emerald-700 px-2 py-0.5 rounded-full text-[8px] font-black uppercase">Phase 11 Active</div>
                        </div>
                        <h2 className="text-4xl font-black text-[#1A241A] tracking-tighter">Pricing <span className="text-emerald-600">Advantage Hub</span></h2>
                    </div>
                </div>
                <button
                    onClick={onClose}
                    className="p-3 bg-white border border-[#E5E1D8] rounded-2xl hover:bg-stone-50 transition-all shadow-sm"
                >
                    <X className="w-6 h-6 text-stone-400" />
                </button>
            </div>

            {loading ? (
                <div className="flex-1 flex flex-col items-center justify-center space-y-4">
                    <div className="w-12 h-12 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin"></div>
                    <p className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Menganalisis Efisiensi Harga & OPEX...</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 pb-10">
                    {/* Insights & Recommendations */}
                    <div className="lg:col-span-2 space-y-12">
                        {/* Summary Cards */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div className="bg-white p-6 rounded-[2rem] border border-[#E5E1D8] shadow-sm flex items-center gap-4 relative overflow-hidden group">
                                {data?.overhead?.opexTotal > 0 && (
                                    <div className="absolute top-0 right-0 bg-emerald-600 text-white px-3 py-1 rounded-bl-xl text-[8px] font-black uppercase tracking-widest animate-pulse">
                                        Live Opex
                                    </div>
                                )}
                                <div className="p-4 bg-emerald-50 rounded-2xl text-emerald-600">
                                    <DollarSign size={24} />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-[#8B7E66] uppercase">Overhead / Unit</p>
                                    <p className="text-2xl font-black text-[#2D3A2D]">Rp {data?.overhead?.perUnitDynamic?.toLocaleString()}</p>
                                </div>
                            </div>
                            <div className="bg-white p-6 rounded-[2rem] border border-[#E5E1D8] shadow-sm flex items-center gap-4">
                                <div className="p-4 bg-blue-50 rounded-2xl text-blue-600">
                                    <BarChart3 size={24} />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-[#8B7E66] uppercase">Velocity Index</p>
                                    <p className="text-2xl font-black text-[#2D3A2D]">{(data?.velocityIndex * 100).toFixed(0)}%</p>
                                </div>
                            </div>
                            <div className="bg-white p-6 rounded-[2rem] border border-[#E5E1D8] shadow-sm flex items-center gap-4">
                                <div className={`p-4 rounded-2xl ${recipeCosting.some(r => r.isSuboptimal) ? 'bg-rose-50 text-rose-600 animate-pulse' : 'bg-green-50 text-green-600'}`}>
                                    <AlertCircle size={24} />
                                </div>
                                <div>
                                    <p className="text-[10px] font-black text-[#8B7E66] uppercase">Recipe Health</p>
                                    <p className="text-2xl font-black text-[#2D3A2D]">{recipeCosting.filter(r => !r.isSuboptimal).length}/{recipeCosting.length}</p>
                                </div>
                            </div>
                        </div>

                        {/* NEW: Smart Recipe Costing Breakdown */}
                        <div className="space-y-6">
                            <h4 className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66] px-2 flex items-center gap-2">
                                <Zap size={12} className="text-amber-500" />
                                Analisis Modal Resep (True HPP)
                            </h4>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                {recipeCosting.slice(0, 4).map((recipe, idx) => (
                                    <div key={idx} className={`p-6 bg-white border rounded-[2rem] transition-all relative overflow-hidden ${recipe.isSuboptimal ? 'border-rose-200 bg-rose-50/20' : 'border-[#E5E1D8]'}`}>
                                        <div className="flex justify-between items-start mb-4">
                                            <div>
                                                <h5 className="font-black text-[#1A241A] text-sm group-hover:text-emerald-600 transition-colors uppercase">{recipe.name}</h5>
                                                <p className="text-[9px] font-bold text-[#8B7E66] uppercase">HPP: Rp {Math.round(recipe.trueHpp).toLocaleString()}</p>
                                            </div>
                                            <div className={`px-2 py-1 rounded-lg text-[8px] font-black uppercase ${recipe.isSuboptimal ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'}`}>
                                                {Math.round(recipe.currentMargin)}% Margin
                                            </div>
                                        </div>
                                        <div className="space-y-4">
                                            <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                                                <div
                                                    className={`h-full rounded-full ${recipe.isSuboptimal ? 'bg-rose-500' : 'bg-emerald-500'}`}
                                                    style={{ width: `${Math.min(100, (recipe.currentMargin / recipe.targetMargin) * 100)}%` }}
                                                ></div>
                                            </div>
                                            <div className="flex justify-between text-[8px] font-black uppercase">
                                                <span className="text-slate-400">Target: {recipe.targetMargin}%</span>
                                                <span className={recipe.isSuboptimal ? 'text-rose-600' : 'text-emerald-600'}>
                                                    {recipe.isSuboptimal ? `Kurang ${(recipe.targetMargin - recipe.currentMargin).toFixed(1)}%` : 'Target Tercapai'}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Adjustments List */}
                        <div className="space-y-4">
                            <h4 className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66] px-2 flex items-center gap-2">
                                <DollarSign size={12} className="text-emerald-600" />
                                Rekomendasi Penyesuaian Harga (Markup & Surge)
                            </h4>
                            {data?.adjustments?.length === 0 ? (
                                <div className="p-12 text-center bg-stone-50/50 border-2 border-dashed border-[#E5E1D8] rounded-[2rem]">
                                    <p className="text-stone-400 text-sm font-medium italic">Semua harga sudah optimal sesuai margin target & overhead.</p>
                                </div>
                            ) : (
                                data?.adjustments?.map((adj: any, idx: number) => (
                                    <div key={idx} className="bg-white border border-[#E5E1D8] rounded-[2rem] p-8 hover:shadow-xl hover:border-emerald-200 transition-all group">
                                        <div className="flex flex-col md:flex-row items-center justify-between gap-8">
                                            <div className="flex-1 space-y-4 w-full">
                                                <div className="flex items-center gap-4">
                                                    <div className={`p-2 rounded-xl ${adj.type === 'SURGE' ? 'bg-rose-50 text-rose-600' :
                                                        adj.type === 'DISCOUNT' ? 'bg-amber-50 text-amber-600' :
                                                            'bg-emerald-50 text-emerald-600'
                                                        }`}>
                                                        {adj.type === 'SURGE' ? <ArrowUpRight size={18} /> :
                                                            adj.type === 'DISCOUNT' ? <ArrowDownRight size={18} /> :
                                                                <Target size={18} />}
                                                    </div>
                                                    <h5 className="font-black text-[#1A241A] text-lg uppercase tracking-tight">{adj.variantName}</h5>
                                                </div>

                                                <div className="grid grid-cols-2 gap-4">
                                                    <div className="p-4 bg-stone-50 rounded-2xl border border-stone-100">
                                                        <p className="text-[8px] font-black text-[#8B7E66] uppercase mb-1">Harga Sekarang</p>
                                                        <p className="text-sm font-black text-stone-400 line-through">Rp {adj.currentPrice.toLocaleString()}</p>
                                                    </div>
                                                    <div className="p-4 bg-emerald-50/50 rounded-2xl border border-emerald-100">
                                                        <p className="text-[8px] font-black text-[#8B7E66] uppercase mb-1">Rekomendasi AI</p>
                                                        <p className="text-sm font-black text-emerald-700">Rp {adj.recommendedPrice.toLocaleString()}</p>
                                                    </div>
                                                </div>

                                                <div className="flex items-center gap-2 text-xs font-medium text-[#8B7E66] bg-stone-50 p-3 rounded-xl border border-stone-100">
                                                    <Info size={14} className="text-emerald-400" />
                                                    {adj.reason}
                                                </div>
                                            </div>

                                            <button
                                                onClick={() => handleApply(adj)}
                                                disabled={applying === adj.variantId}
                                                className="w-full md:w-auto px-8 py-5 bg-[#2D3A2D] text-white rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all shadow-lg active:scale-95 disabled:opacity-50 flex items-center justify-center gap-3"
                                            >
                                                {applying === adj.variantId ? (
                                                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                                ) : <CheckCircle2 size={14} className="text-emerald-400" />}
                                                Terapkan Harga Baru
                                            </button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>

                    {/* Sidebar: OPEX Breakdown */}
                    <div className="space-y-8">
                        <div className="bg-[#1A241A] rounded-[3rem] p-8 text-white relative overflow-hidden shadow-2xl">
                            <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                            <h4 className="text-xs font-black uppercase tracking-widest text-[#B2BCA2] mb-6 flex items-center gap-2">
                                <PieChart size={14} />
                                Allocated OPEX Impact
                            </h4>

                            <div className="space-y-6">
                                {data?.overheadBreakdown?.length === 0 ? (
                                    <p className="text-xs text-stone-500 font-medium italic">Belum ada data pengeluaran operasional di Ledger.</p>
                                ) : (
                                    data?.overheadBreakdown?.map((item: any, idx: number) => (
                                        <div key={idx} className="space-y-2">
                                            <div className="flex justify-between items-end">
                                                <p className="text-[10px] font-black uppercase text-white">{item.name}</p>
                                                <p className="text-[10px] font-bold text-[#B2BCA2]">Rp {item.amount.toLocaleString()}</p>
                                            </div>
                                            <div className="h-1 bg-white/10 rounded-full overflow-hidden">
                                                <div
                                                    className="h-full bg-emerald-500 rounded-full"
                                                    style={{ width: `${(item.amount / data.overhead.opexTotal) * 100}%` }}
                                                ></div>
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>

                            <div className="mt-10 pt-6 border-t border-white/10">
                                <div className="flex justify-between items-center bg-white/5 p-4 rounded-2xl">
                                    <div className="space-y-1">
                                        <p className="text-[8px] font-black text-stone-400 uppercase">
                                            {data?.overhead?.opexTotal > 0 ? 'Live Monthly OPEX' : 'Fallback Overhead Mode'}
                                        </p>
                                        <p className="text-lg font-black text-emerald-400">
                                            {data?.overhead?.opexTotal > 0
                                                ? `Rp ${data?.overhead?.opexTotal?.toLocaleString()}`
                                                : `Rp ${data?.overhead?.perUnitDynamic?.toLocaleString()} / unit`
                                            }
                                        </p>
                                    </div>
                                    <div className={`p-2 rounded-lg ${data?.overhead?.opexTotal > 0 ? 'bg-emerald-500/20 text-emerald-400' : 'bg-amber-500/20 text-amber-400'}`}>
                                        <Zap size={16} className={data?.overhead?.opexTotal > 0 ? 'animate-pulse' : ''} />
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Strategy Config */}
                        <div className="bg-[#F9F7F2] rounded-[2.5rem] border border-[#E5E1D8] p-8 space-y-6">
                            <div className="flex items-center justify-between">
                                <h4 className="text-xs font-black uppercase tracking-widest text-[#8B7E66] flex items-center gap-2">
                                    <Target size={14} />
                                    Strategy Parameters
                                </h4>
                                {savingConfig ? (
                                    <Loader2 className="w-4 h-4 text-emerald-600 animate-spin" />
                                ) : (
                                    <button
                                        onClick={handleSaveConfig}
                                        className="text-[10px] font-black uppercase text-emerald-600 hover:text-emerald-700 transition-colors flex items-center gap-1"
                                    >
                                        <Save size={12} />
                                        Save
                                    </button>
                                )}
                            </div>

                            <div className="space-y-4">
                                <div className="space-y-1.5">
                                    <label className="text-[9px] font-black text-[#8B7E66] uppercase tracking-wider px-1">Default Overhead (Fallback)</label>
                                    <div className="relative">
                                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-xs font-black text-stone-400">Rp</span>
                                        <input
                                            type="number"
                                            value={config.defaultOverheadPerUnit}
                                            onChange={e => setConfig({ ...config, defaultOverheadPerUnit: parseFloat(e.target.value) || 0 })}
                                            className="w-full bg-white border border-[#E5E1D8] rounded-xl py-3 pl-10 pr-4 text-sm font-black text-[#2D3A2D] outline-none focus:ring-2 focus:ring-emerald-500/20 transition-all"
                                        />
                                    </div>
                                </div>

                                <div className="space-y-1.5">
                                    <label className="text-[9px] font-black text-[#8B7E66] uppercase tracking-wider px-1">Target Monthly Volume</label>
                                    <div className="relative">
                                        <input
                                            type="number"
                                            value={config.targetMonthlyVolume}
                                            onChange={e => setConfig({ ...config, targetMonthlyVolume: parseInt(e.target.value) || 1 })}
                                            className="w-full bg-white border border-[#E5E1D8] rounded-xl py-3 px-4 text-sm font-black text-[#2D3A2D] outline-none focus:ring-2 focus:ring-emerald-500/20 transition-all"
                                        />
                                        <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-bold text-stone-400 uppercase">Unit</span>
                                    </div>
                                </div>

                                <div className="space-y-1.5">
                                    <label className="text-[9px] font-black text-[#8B7E66] uppercase tracking-wider px-1">Operational Overhead (Per Order)</label>
                                    <div className="relative">
                                        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-xs font-black text-stone-400">Rp</span>
                                        <input
                                            type="number"
                                            value={config.operationalOverhead}
                                            onChange={e => setConfig({ ...config, operationalOverhead: parseFloat(e.target.value) || 0 })}
                                            className="w-full bg-white border border-[#E5E1D8] rounded-xl py-3 pl-10 pr-4 text-sm font-black text-[#2D3A2D] outline-none focus:ring-2 focus:ring-emerald-500/20 transition-all"
                                        />
                                    </div>
                                    <p className="text-[8px] text-[#8B7E66] font-medium leading-tight px-1 italic mt-1 opacity-70">
                                        Packing, stiker, plastik, dll per pesanan.
                                    </p>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-1.5">
                                        <label className="text-[9px] font-black text-[#8B7E66] uppercase tracking-wider px-1">Marketplace Fee</label>
                                        <div className="relative">
                                            <input
                                                type="number"
                                                step="0.1"
                                                value={config.marketplaceFeeRate * 100}
                                                onChange={e => setConfig({ ...config, marketplaceFeeRate: (parseFloat(e.target.value) || 0) / 100 })}
                                                className="w-full bg-white border border-[#E5E1D8] rounded-xl py-3 px-4 text-sm font-black text-[#2D3A2D] outline-none focus:ring-2 focus:ring-emerald-500/20 transition-all"
                                            />
                                            <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-bold text-stone-400 uppercase">%</span>
                                        </div>
                                    </div>
                                    <div className="space-y-1.5">
                                        <label className="text-[9px] font-black text-[#8B7E66] uppercase tracking-wider px-1">Target Net Margin</label>
                                        <div className="relative">
                                            <input
                                                type="number"
                                                step="0.1"
                                                value={config.targetNetMarginRate * 100}
                                                onChange={e => setConfig({ ...config, targetNetMarginRate: (parseFloat(e.target.value) || 0) / 100 })}
                                                className="w-full bg-white border border-[#E5E1D8] rounded-xl py-3 px-4 text-sm font-black text-[#2D3A2D] outline-none focus:ring-2 focus:ring-emerald-500/20 transition-all"
                                            />
                                            <span className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-bold text-stone-400 uppercase">%</span>
                                        </div>
                                    </div>
                                </div>

                                <div className="p-4 bg-emerald-50/50 rounded-2xl border border-emerald-100 flex gap-3">
                                    <Info className="w-4 h-4 text-emerald-500 shrink-0 mt-0.5" />
                                    <p className="text-[10px] text-emerald-700/80 leading-relaxed italic">
                                        "Jika <strong>Live OPEX</strong> tersedia, sistem akan mengabaikan fallback dan menggunakan data real untuk proteksi margin maksimal."
                                    </p>
                                </div>

                                {/* Overhead Breakdown Sub-sections */}
                                <div className="pt-4 border-t border-stone-200">
                                    <label className="text-[10px] font-black text-[#8B7E66] uppercase tracking-wider px-1 block mb-3">Live OPEX Breakdown (Monthly)</label>
                                    <div className="grid grid-cols-2 gap-4">
                                        {[
                                            { id: 'electricity', label: 'Listrik', icon: Zap },
                                            { id: 'water', label: 'Air (PDAM)', icon: Info },
                                            { id: 'gas', label: 'Gas (LPG)', icon: TrendingUp },
                                            { id: 'labor', label: 'Gaji Staff', icon: DollarSign }
                                        ].map((item) => (
                                            <div key={item.id} className="space-y-1.5">
                                                <label className="text-[8px] font-bold text-[#8B7E66] uppercase">{item.label}</label>
                                                <div className="relative">
                                                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-stone-400">Rp</span>
                                                    <input
                                                        type="number"
                                                        value={config.overheadBreakdown[item.id as keyof typeof config.overheadBreakdown] || 0}
                                                        onChange={e => setConfig({
                                                            ...config,
                                                            overheadBreakdown: {
                                                                ...config.overheadBreakdown,
                                                                [item.id]: parseFloat(e.target.value) || 0
                                                            }
                                                        })}
                                                        className="w-full bg-white border border-[#E5E1D8] rounded-xl py-2 pl-8 pr-3 text-xs font-black text-[#2D3A2D] outline-none focus:ring-2 focus:ring-emerald-500/20"
                                                    />
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import React from 'react';
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip,
    ResponsiveContainer, Cell
} from 'recharts';
import { ShoppingCart, Calendar, ArrowRight, Zap } from 'lucide-react';

interface ProcurementForecastProps {
    data: any[];
}

export default function ProcurementForecast({ data }: ProcurementForecastProps) {
    if (!data || data.length === 0) {
        return (
            <div className="bg-[#1A241A] p-12 rounded-[3rem] text-white shadow-2xl space-y-6 flex flex-col items-center justify-center text-center relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/5 blur-[100px] -mr-32 -mt-32"></div>
                <div className="p-4 bg-white/5 rounded-full border border-white/10 relative z-10">
                    <ShoppingCart className="w-10 h-10 text-indigo-400 opacity-40" />
                </div>
                <div className="space-y-2 relative z-10">
                    <h3 className="text-sm font-black uppercase tracking-widest text-indigo-300">Prediksi Stok 7 Hari Ke Depan</h3>
                    <p className="text-xs text-white/40 font-medium italic max-w-md mx-auto">AI sedang mengumpulkan data penggunaan bahan baku Bunda. Prediksi akan muncul setelah sistem mendeteksi pola penggunaan stok dalam beberapa hari terakhir. 🛒</p>
                </div>
            </div>
        );
    }

    const chartData = data.slice(0, 6).map(p => ({
        name: p.material,
        Need: Math.ceil(p.predicted7DayNeed),
        unit: p.unit,
        confidence: p.confidence
    }));

    return (
        <div className="bg-[#1A241A] p-10 rounded-[3rem] text-white shadow-2xl space-y-10 relative overflow-hidden">
            {/* Background Accent */}
            <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 blur-[100px] -mr-32 -mt-32"></div>

            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 relative z-10">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-white/10 rounded-lg">
                            <ShoppingCart className="w-5 h-5 text-indigo-400" />
                        </div>
                        <h3 className="text-sm font-black uppercase tracking-widest text-indigo-300">Prediksi Stok 7 Hari Ke Depan</h3>
                    </div>
                    <p className="text-xs text-white/60 font-medium">Berdasarkan rata-rata penggunaan 14 hari terakhir + buffer 10%.</p>
                </div>
                <div className="flex items-center gap-3 bg-white/5 px-6 py-3 rounded-2xl border border-white/10">
                    <Calendar className="w-4 h-4 text-indigo-400" />
                    <p className="text-xs font-black uppercase tracking-widest">Periode: {new Date().toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })} - {new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toLocaleDateString('id-ID', { day: '2-digit', month: 'short' })}</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                <div className="lg:col-span-7 h-[300px]">
                    <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={chartData}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="rgba(255,255,255,0.05)" />
                            <XAxis
                                dataKey="name"
                                axisLine={false}
                                tickLine={false}
                                tick={{ fontSize: 9, fontWeight: 700, fill: 'rgba(255,255,255,0.4)' }}
                            />
                            <YAxis hide />
                            <Tooltip
                                contentStyle={{ backgroundColor: '#1A241A', borderRadius: '15px', border: '1px solid rgba(255,255,255,0.1)', color: '#fff' }}
                                itemStyle={{ color: '#818CF8' }}
                            />
                            <Bar dataKey="Need" name="Prediksi Butuh" fill="#6366F1" radius={[12, 12, 0, 0]} barSize={40}>
                                {chartData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fillOpacity={entry.confidence === 'HIGH' ? 1 : 0.6} />
                                ))}
                            </Bar>
                        </BarChart>
                    </ResponsiveContainer>
                </div>

                <div className="lg:col-span-5 space-y-6">
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-white/40">Daftar Belanja Rekomendasi AI</h4>
                    <div className="space-y-3">
                        {data.slice(0, 4).map((p, i) => (
                            <div key={i} className="group p-5 bg-white/5 rounded-[2rem] border border-white/5 hover:border-indigo-500/50 hover:bg-white/10 transition-all cursor-pointer">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-4">
                                        <div className="w-10 h-10 bg-indigo-500/20 rounded-xl flex items-center justify-center">
                                            <Zap className={`w-4 h-4 ${p.confidence === 'HIGH' ? 'text-indigo-400' : 'text-slate-400'}`} />
                                        </div>
                                        <div>
                                            <p className="text-xs font-black text-white">{p.material}</p>
                                            <p className="text-[9px] font-bold text-white/40 uppercase">Rerata {p.avgDailyUsage.toFixed(1)} {p.unit} / hari</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-sm font-black text-indigo-400">{Math.ceil(p.predicted7DayNeed)} {p.unit}</p>
                                        <ArrowRight className="w-3 h-3 text-white/20 ml-auto mt-1 group-hover:translate-x-1 transition-transform" />
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                    <button className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest transition-all shadow-xl shadow-indigo-900/40">
                        Buat Draft Purchase Order
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { getProductionPlanAction } from '@/lib/actions/rasa-ibu/intelligence';
import { ChefHat, ClipboardList, Clock, AlertCircle, Loader2, MessageSquare, CheckCircle2, Download } from 'lucide-react';
import { exportToCSV } from '@/lib/utils/exportUtils';

interface ProductionPlanProps {
    brandId: string;
}

export default function ProductionPlan({ brandId }: ProductionPlanProps) {
    const [plan, setPlan] = useState<any>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'COOK' | 'GROCERY'>('COOK');

    useEffect(() => {
        async function load() {
            const res = await getProductionPlanAction(brandId);
            if (res.success) {
                setPlan(res.data);
            }
            setIsLoading(false);
        }
        load();
    }, [brandId]);

    if (isLoading) {
        return (
            <div className="bg-white p-12 rounded-[3.5rem] border border-[#E5E1D8] flex flex-col items-center justify-center space-y-4">
                <Loader2 className="w-8 h-8 text-indigo-500 animate-spin" />
                <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Menyusun Rencana Produksi Dapur...</p>
            </div>
        );
    }

    if (!plan || (plan.cookList.length === 0 && plan.groceryList.length === 0)) {
        return (
            <div className="bg-white p-12 rounded-[3.5rem] border border-[#E5E1D8] text-center space-y-4">
                <CheckCircle2 className="w-12 h-12 text-emerald-500 mx-auto" />
                <h3 className="text-xl font-black text-[#2D3A2D]">Semua Pesanan Selesai!</h3>
                <p className="text-xs text-slate-400 font-medium italic">Tidak ada antrean masak aktif saat ini.</p>
            </div>
        );
    }

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
            {/* Left: Aggregated Lists */}
            <div className="lg:col-span-2 space-y-8">
                <div className="bg-white rounded-[3.5rem] border border-[#E5E1D8] overflow-hidden shadow-xl">
                    <div className="p-10 border-b border-slate-50 bg-indigo-600 text-white flex flex-col gap-8">
                        <div className="flex justify-between items-center">
                            <div className="flex items-center gap-5">
                                <div className="p-4 bg-white/20 rounded-[1.5rem] backdrop-blur-md">
                                    <ChefHat className="w-6 h-6" />
                                </div>
                                <div>
                                    <h3 className="text-xl font-black tracking-tight">Intelligence Hub Dapur</h3>
                                    <p className="text-[10px] font-bold opacity-70 uppercase tracking-widest mt-1">Sistem Produksi & Inventaris Otomatis</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-4">
                                <button
                                    onClick={() => {
                                        if (activeTab === 'COOK') {
                                            const exportData = plan.cookList.map((item: any) => ({
                                                'Menu': item.name,
                                                'Quantity': item.quantity,
                                                'Tiket Pesanan': item.orders,
                                                'Catatan Khusus': item.notes.join('; ') || '-'
                                            }));
                                            exportToCSV(exportData, 'Daftar_Masak_Hari_Ini');
                                        } else {
                                            const exportData = plan.groceryList.map((ing: any) => ({
                                                'Bahan': ing.name,
                                                'Total': ing.total,
                                                'Satuan': ing.unit
                                            }));
                                            exportToCSV(exportData, 'Daftar_Belanja_Hari_Ini');
                                        }
                                    }}
                                    className="px-4 py-2 bg-white text-indigo-600 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-white/90 transition-all shadow-lg flex items-center gap-2"
                                >
                                    <Download className="w-3.5 h-3.5" />
                                    Export CSV
                                </button>
                                <div className="text-right">
                                    <p className="text-[10px] font-black uppercase tracking-widest opacity-60">Total Pesanan</p>
                                    <p className="text-3xl font-black">{plan.totalActiveOrders}</p>
                                </div>
                            </div>
                        </div>

                        <div className="flex bg-black/10 p-1.5 rounded-2xl w-fit">
                            <button
                                onClick={() => setActiveTab('COOK')}
                                className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'COOK' ? 'bg-white text-indigo-600 shadow-lg' : 'text-white/60 hover:text-white'}`}
                            >
                                <div className="flex items-center gap-2">
                                    <ChefHat className="w-3.5 h-3.5" />
                                    Daftar Masak
                                </div>
                            </button>
                            <button
                                onClick={() => setActiveTab('GROCERY')}
                                className={`px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'GROCERY' ? 'bg-white text-indigo-600 shadow-lg' : 'text-white/60 hover:text-white'}`}
                            >
                                <div className="flex items-center gap-2">
                                    <ClipboardList className="w-3.5 h-3.5" />
                                    Daftar Belanja
                                </div>
                            </button>
                        </div>
                    </div>

                    <div className="p-10 space-y-6">
                        {activeTab === 'COOK' ? (
                            plan.cookList.map((item: any, idx: number) => (
                                <div key={idx} className="flex items-center justify-between p-6 bg-slate-50 rounded-3xl border border-slate-100 hover:border-indigo-200 transition-all group">
                                    <div className="flex items-center gap-6">
                                        <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-2xl font-black text-indigo-600 shadow-sm border border-slate-100 group-hover:scale-110 transition-transform">
                                            {item.quantity}
                                        </div>
                                        <div>
                                            <h4 className="text-lg font-black text-[#2D3A2D]">{item.name}</h4>
                                            <div className="flex items-center gap-2 mt-1 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                                                <ClipboardList className="w-3 h-3" />
                                                {item.orders} Tiket Pesanan
                                            </div>
                                        </div>
                                    </div>

                                    {item.notes.length > 0 && (
                                        <div className="flex items-center gap-2 px-4 py-2 bg-amber-50 rounded-xl border border-amber-100 animate-pulse">
                                            <AlertCircle className="w-3.5 h-3.5 text-amber-600" />
                                            <span className="text-[9px] font-black text-amber-700 uppercase">Ada Pesan Khusus</span>
                                        </div>
                                    )}
                                </div>
                            ))
                        ) : (
                            <div className="space-y-4">
                                {plan.groceryList.length > 0 ? (
                                    plan.groceryList.map((ing: any, idx: number) => (
                                        <div key={idx} className="flex items-center justify-between p-6 border border-slate-100 rounded-3xl bg-white hover:bg-slate-50 transition-colors">
                                            <div className="flex items-center gap-4">
                                                <div className="p-3 bg-emerald-50 rounded-xl text-emerald-600">
                                                    <CheckCircle2 className="w-5 h-5" />
                                                </div>
                                                <h4 className="text-sm font-black text-[#2D3A2D] uppercase tracking-tight">{ing.name}</h4>
                                            </div>
                                            <div className="text-right">
                                                <p className="text-xl font-black text-indigo-600">{ing.total % 1 === 0 ? ing.total : ing.total.toFixed(2)}</p>
                                                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{ing.unit}</p>
                                            </div>
                                        </div>
                                    ))
                                ) : (
                                    <div className="text-center py-20 px-10 bg-slate-50 rounded-[2.5rem] border border-dashed border-slate-200">
                                        <AlertCircle className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                                        <h4 className="text-sm font-black text-slate-500 uppercase tracking-widest">Resep Belum Lengkap</h4>
                                        <p className="text-xs text-slate-400 mt-2 italic">Pastikan "Ingredients" pada produk Bunda sudah diisi dengan format:<br />Nama (Jumlah Satuan), contoh: Ayam (0.25 ekor)</p>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Right: Notes & Instructions */}
            <div className="space-y-8">
                <div className="bg-[#2D3A2D] p-10 rounded-[3rem] text-white shadow-xl">
                    <div className="flex items-center gap-3 mb-8">
                        <MessageSquare className="w-5 h-5 text-indigo-400" />
                        <h3 className="text-xs font-black uppercase tracking-widest">Pesan Khusus Pelanggan</h3>
                    </div>

                    <div className="space-y-6 max-h-[500px] overflow-y-auto pr-4 custom-scrollbar">
                        {plan.cookList.flatMap((item: any) => item.notes).length > 0 ? (
                            plan.cookList.flatMap((item: any) => item.notes).map((note: string, idx: number) => (
                                <div key={idx} className="p-5 bg-white/5 rounded-2xl border border-white/10 italic text-xs leading-relaxed text-slate-300">
                                    "{note}"
                                </div>
                            ))
                        ) : (
                            <p className="text-xs text-slate-500 font-medium text-center py-10">Belum ada catatan khusus dari pelanggan.</p>
                        )}
                    </div>
                </div>

                <div className="bg-indigo-50 p-8 rounded-[2.5rem] border border-indigo-100">
                    <div className="flex items-center gap-3 mb-4 text-indigo-600">
                        <Clock className="w-4 h-4" />
                        <span className="text-[10px] font-black uppercase tracking-widest">Auto-Refresh Active</span>
                    </div>
                    <p className="text-[11px] text-indigo-900 font-medium leading-relaxed">
                        Data ini disinkronkan secara real-time dengan status pesanan. Setiap pesanan baru akan langsung menambah kuantitas masak di layar ini.
                    </p>
                </div>
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend,
    ResponsiveContainer, Cell, ComposedChart, Line
} from 'recharts';
import { TrendingUp, Package, Percent, Target } from 'lucide-react';

interface PromoPerformanceProps {
    data: any;
}

export default function PromoPerformance({ data }: PromoPerformanceProps) {
    if (!data || !data.campaigns || data.campaigns.length === 0) {
        return (
            <div className="bg-white p-10 rounded-[3rem] border border-[#E5E1D8] shadow-sm space-y-6 flex flex-col items-center justify-center min-h-[400px] text-center">
                <div className="p-4 bg-slate-50 rounded-full border border-slate-100">
                    <Target className="w-10 h-10 text-slate-300" />
                </div>
                <div className="space-y-2">
                    <h3 className="text-sm font-black uppercase tracking-widest text-[#2D3A2D]">Analisis Performa Promo</h3>
                    <p className="text-xs text-[#8B7E66] font-medium italic max-w-xs">Belum ada data promo (dual-metric) yang terdeteksi bulan ini. Promo akan muncul otomatis jika Bunda menggunakan tag promo pada pesanan. 🏷️</p>
                </div>
            </div>
        );
    }

    const chartData = data.campaigns.map((c: any) => ({
        tag: c.tag,
        'Revenue (K)': Math.round(c.revenue / 1000),
        'Qty (Pcs)': c.quantity,
        'Uplift Revenue %': Math.round(c.upliftRevenue),
        'Uplift Qty %': Math.round(c.upliftQty)
    }));

    const currency = (val: number) => `Rp${(val / 1000).toFixed(0)}rb`;

    return (
        <div className="bg-white p-10 rounded-[3rem] border border-[#E5E1D8] shadow-sm space-y-10">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 bg-indigo-50 rounded-lg">
                            <Target className="w-5 h-5 text-indigo-600" />
                        </div>
                        <h3 className="text-sm font-black uppercase tracking-widest text-[#2D3A2D]">Analisis Performa Promosi</h3>
                    </div>
                    <p className="text-xs text-[#8B7E66] font-medium">Perbandingan Omzet & Volume (Pcs) saat ada Promo vs Normal</p>
                </div>
                <div className="flex gap-4">
                    <div className="px-4 py-2 bg-slate-50 rounded-xl border border-slate-100">
                        <p className="text-[8px] font-black text-slate-400 uppercase">Baseline Avg AOV</p>
                        <p className="text-sm font-black text-[#2D3A2D]">{new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(data.baseline.avgAOV)}</p>
                    </div>
                    <div className="px-4 py-2 bg-slate-50 rounded-xl border border-slate-100">
                        <p className="text-[8px] font-black text-slate-400 uppercase">Baseline Avg Qty</p>
                        <p className="text-sm font-black text-[#2D3A2D]">{data.baseline.avgQty.toFixed(1)} Pcs/Order</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Chart 1: Revenue vs Qty Uplift */}
                <div className="space-y-6">
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Uplift Performa (%)</h4>
                    <div className="h-[300px]">
                        <ResponsiveContainer width="100%" height="100%">
                            <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F0EFEA" />
                                <XAxis
                                    dataKey="tag"
                                    axisLine={false}
                                    tickLine={false}
                                    tick={{ fontSize: 10, fontWeight: 700, fill: '#8B7E66' }}
                                />
                                <YAxis
                                    axisLine={false}
                                    tickLine={false}
                                    tick={{ fontSize: 10, fontWeight: 700, fill: '#8B7E66' }}
                                    unit="%"
                                />
                                <Tooltip
                                    contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 10px 30px rgba(0,0,0,0.1)' }}
                                />
                                <Legend wrapperStyle={{ paddingTop: '20px', fontSize: '10px', fontWeight: 900, textTransform: 'uppercase' }} />
                                <Bar dataKey="Uplift Revenue %" name="Kenaikan Omzet" fill="#4F46E5" radius={[10, 10, 0, 0]} />
                                <Bar dataKey="Uplift Qty %" name="Kenaikan Volume (Pcs)" fill="#10B981" radius={[10, 10, 0, 0]} />
                            </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* List Summary */}
                <div className="space-y-4">
                    <h4 className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Top Campaigns</h4>
                    <div className="space-y-3">
                        {data.campaigns.map((c: any, i: number) => (
                            <div key={i} className="p-5 bg-[#F9F7F2] rounded-3xl border border-[#E5E1D8] flex items-center justify-between group hover:bg-white hover:shadow-xl hover:shadow-indigo-50 transition-all duration-300">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 bg-white rounded-2xl border border-[#E5E1D8] flex items-center justify-center text-lg font-black text-indigo-600 shadow-sm">
                                        #{i + 1}
                                    </div>
                                    <div>
                                        <p className="text-sm font-black text-[#2D3A2D]">{c.tag}</p>
                                        <p className="text-[10px] font-bold text-[#8B7E66] uppercase">{c.orders} Berhasil Digunakan</p>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <div className="flex items-center justify-end gap-1 text-emerald-600">
                                        <TrendingUp className="w-3 h-3" />
                                        <p className="text-xs font-black">+{Math.round(c.upliftQty)}% Vol</p>
                                    </div>
                                    <p className="text-[10px] font-bold text-[#8B7E66] uppercase">Revenue: {new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(c.revenue)}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import { Sparkles, AlertCircle, RefreshCw, Zap } from 'lucide-react';

interface SmartAdvisoryProps {
    intelligence: any;
}

export default function SmartAdvisory({ intelligence }: SmartAdvisoryProps) {
    const { rhythm, anticipations } = intelligence || {};
    const [mounted, setMounted] = React.useState(false);

    React.useEffect(() => {
        setMounted(true);
    }, []);

    // Derived insights
    const criticalStock = anticipations?.underBufferCount || 0;
    const peakTime = rhythm?.peakHour || 'N/A';

    // Dynamic Time Greeting
    const hour = mounted ? new Date().getHours() : 12; // Default to neutral 12 during SSR
    let timeGreeting = "pagi ini";
    if (hour >= 11 && hour < 15) timeGreeting = "siang ini";
    else if (hour >= 15 && hour < 19) timeGreeting = "sore ini";
    else if (hour >= 19 || hour < 4) timeGreeting = "malam ini";

    return (
        <div suppressHydrationWarning className="bg-gradient-to-br from-[#2D3A2D] to-[#1A241A] rounded-[3rem] p-8 shadow-2xl relative overflow-hidden group">
            {/* Background Decor */}
            <div className="absolute -right-20 -top-20 w-64 h-64 bg-emerald-500/10 rounded-full blur-3xl group-hover:bg-emerald-500/20 transition-all duration-1000"></div>
            <div className="absolute -left-20 -bottom-20 w-64 h-64 bg-amber-500/10 rounded-full blur-3xl group-hover:bg-amber-500/20 transition-all duration-1000"></div>

            <div className="relative z-10 flex flex-col md:flex-row gap-8 items-center">
                {/* Advisor Persona */}
                <div className="flex-shrink-0">
                    <div className="w-20 h-20 bg-gradient-to-tr from-emerald-400 to-amber-400 rounded-3xl flex items-center justify-center rotate-3 group-hover:rotate-6 transition-transform shadow-xl">
                        <Sparkles className="w-10 h-10 text-white animate-pulse" />
                    </div>
                </div>

                {/* Insight Content */}
                <div className="flex-1 space-y-4 text-center md:text-left">
                    <div>
                        <span className="text-[10px] font-black uppercase tracking-[0.5em] text-emerald-400/80">Proactive Operational Pulse</span>
                        <h2 className="text-2xl font-black text-white italic tracking-tight">
                            "Dapur sedang dalam ritme <span className="text-emerald-400">Optimal</span> {timeGreeting}."
                        </h2>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                        <div className="bg-white/5 backdrop-blur-md border border-white/10 p-4 rounded-2xl flex items-center gap-3">
                            <div className="p-2 bg-amber-500/20 rounded-lg text-amber-400">
                                <AlertCircle className="w-4 h-4" />
                            </div>
                            <div>
