'use client';

import React, { useState, useEffect } from 'react';
import { QRCodeSVG } from 'qrcode.react'; // Using SVG for better rendering
import { MessageCircle, Zap, Loader2, CheckCircle2, RefreshCw, LogOut, AlertTriangle } from 'lucide-react';
import { toast } from 'sonner';
import { getWhatsAppStatusAction, logoutWhatsAppAction } from '@/lib/actions/rasa-ibu/whatsapp';
import { useConfirm } from '@/components/ui/BrandConfirm';

export default function WhatsAppConnector() {
    const [status, setStatus] = useState<any>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [isRefreshing, setIsRefreshing] = useState(false);
    const confirm = useConfirm();

    const loadStatus = async () => {
        setIsRefreshing(true);
        const res = await getWhatsAppStatusAction();
        if (res.success) {
            setStatus(res);
        } else {
            toast.error('Gagal mengambil status WhatsApp: ' + res.error);
        }
        setIsLoading(false);
        setIsRefreshing(false);
    };

    useEffect(() => {
        loadStatus();
        // Poll status every 5 seconds if not connected
        const interval = setInterval(() => {
            if (status?.state !== 'CONNECTED') {
                loadStatus();
            }
        }, 5000);
        return () => clearInterval(interval);
    }, [status?.state]);

    const handleLogout = async () => {
        const confirmed = await confirm({
            title: 'Putuskan Koneksi WhatsApp?',
            message: 'Robot Achiera tidak akan bisa mengirim pesan otomatis sampai Bunda menghubungkannya kembali. Lanjutkan?',
            confirmText: 'Ya, Putuskan',
            cancelText: 'Batal',
            variant: 'danger'
        });

        if (!confirmed) return;

        setIsLoading(true);
        const res = await logoutWhatsAppAction();
        if (res.success) {
            toast.success('Berhasil logout dari WhatsApp');
            loadStatus();
        } else {
            toast.error('Gagal logout: ' + res.error);
        }
        setIsLoading(false);
    };

    if (isLoading && !status) {
        return (
            <div className="flex flex-col items-center justify-center py-20 bg-white rounded-[3rem] border border-[#E5E1D8]">
                <Loader2 className="w-10 h-10 text-[#2D3A2D] animate-spin mb-4" />
                <p className="text-sm font-bold text-[#8B7E66]">Menghubungkan ke Engine...</p>
            </div>
        );
    }

    return (
        <div className="bg-white p-8 rounded-[3rem] border border-[#E5E1D8] shadow-sm space-y-8">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <div className={`p-4 rounded-[1.5rem] shadow-inner ${status?.state === 'CONNECTED' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600'
                        }`}>
                        <MessageCircle className="w-6 h-6" />
                    </div>
                    <div>
                        <h3 className="text-[10px] font-black text-[#8B7E66] uppercase tracking-[0.3em]">Hardware Sync</h3>
                        <h2 className="text-2xl font-black text-[#2D3A2D]">WhatsApp Connector</h2>
                    </div>
                </div>
                {status?.state === 'CONNECTED' && (
                    <button
                        onClick={handleLogout}
                        className="flex items-center gap-2 px-4 py-2 bg-rose-50 text-rose-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-rose-100 transition-all"
                    >
                        <LogOut className="w-3.5 h-3.5" />
                        Disconnect
                    </button>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
                {/* Status Card */}
                <div className={`p-8 rounded-[2.5rem] border ${status?.state === 'CONNECTED' ? 'bg-emerald-50/30 border-emerald-100' : 'bg-slate-50 border-slate-100'
                    } space-y-6`}>
                    <div className="space-y-2">
                        <p className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Connection Status</p>
                        <div className="flex items-center gap-3">
                            <div className={`w-3 h-3 rounded-full animate-pulse ${status?.state === 'CONNECTED' ? 'bg-emerald-500' : 'bg-amber-500'
                                }`} />
                            <span className="text-xl font-black text-[#2D3A2D]">
                                {status?.state === 'CONNECTED' ? 'TERHUBUNG' : 'SIAP SCAN'}
                            </span>
                        </div>
                    </div>

                    <div className="space-y-4">
                        <div className="flex items-start gap-3">
                            {status?.state === 'CONNECTED' ? (
                                <CheckCircle2 className="w-5 h-5 text-emerald-500 mt-0.5" />
                            ) : (
                                <Zap className="w-5 h-5 text-amber-500 mt-0.5" />
                            )}
                            <p className="text-sm font-medium text-[#2D3A2D] leading-relaxed">
                                {status?.state === 'CONNECTED'
                                    ? 'Achiera sekarang bisa mengirim nota dan campaign promosi secara otomatis melalui nomor WhatsApp Bunda.'
                                    : 'Scan QR Code di samping menggunakan fitur "Perangkat Tertaut" di aplikasi WhatsApp Bunda untuk mengaktifkan robot pengirim.'}
                            </p>
                        </div>

                        <div className="pt-4 flex items-center gap-4">
                            <button
                                onClick={loadStatus}
                                disabled={isRefreshing}
                                className="p-3 bg-white border border-[#E5E1D8] rounded-2xl hover:bg-slate-50 transition-all"
                            >
                                <RefreshCw className={`w-5 h-5 text-[#8B7E66] ${isRefreshing ? 'animate-spin' : ''}`} />
                            </button>
                            <p className="text-[10px] font-bold text-[#8B7E66]">Terakhir cek: {new Date().toLocaleTimeString()}</p>
                        </div>
                    </div>
                </div>

                {/* QR / Success Display */}
                <div className="flex flex-col items-center justify-center p-8 bg-[#F9F7F2] rounded-[2.5rem] border border-[#E5E1D8] min-h-[300px]">
                    {status?.state === 'CONNECTED' ? (
                        <div className="text-center space-y-4">
                            <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto shadow-lg">
                                <CheckCircle2 className="w-10 h-10" />
                            </div>
                            <div>
                                <p className="text-sm font-black text-[#2D3A2D]">Robot Siap Bekerja!</p>
                                <p className="text-[10px] font-bold text-[#8B7E66]">Sesi aktif terdeteksi.</p>
                            </div>
                        </div>
                    ) : status?.qr ? (
                        <div className="space-y-6 text-center">
                            <div className="bg-white p-6 rounded-3xl shadow-xl border border-white">
                                <QRCodeSVG value={status.qr} size={200} />
                            </div>
                            <div className="flex items-center gap-2 text-amber-600 justify-center">
                                <AlertTriangle className="w-4 h-4" />
                                <span className="text-[10px] font-black uppercase tracking-widest">QR Code Aktif</span>
                            </div>
                        </div>
                    ) : (
                        <div className="flex flex-col items-center gap-4 text-[#8B7E66]">
                            <Loader2 className="w-8 h-8 animate-spin" />
                            <p className="text-xs font-bold text-center">Menunggu QR Code dari Engine...</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState } from 'react';
import { Plus, Edit2, Trash2, X, Tag } from 'lucide-react';
import { toast } from 'sonner';
import { upsertIbuCategory, deleteIbuCategory } from '@/lib/actions/rasa-ibu/catalog';
import { useConfirm } from '@/components/ui/BrandConfirm';

interface CategoryManagerProps {
    brandId: string;
    categories: any[];
    onClose: () => void;
    onRefresh: () => void;
}

export default function CategoryManager({ brandId, categories, onClose, onRefresh }: CategoryManagerProps) {
    const [isAdding, setIsAdding] = useState(false);
    const [editingCategory, setEditingCategory] = useState<any>(null);
    const [folderName, setFolderName] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const confirm = useConfirm();

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!folderName.trim()) return;

        setIsSubmitting(true);
        const res = await upsertIbuCategory({
            id: editingCategory?.id,
            brandId,
            name: folderName
        });

        if (res.success) {
            setFolderName('');
            setEditingCategory(null);
            setIsAdding(false);
            onRefresh();
        } else {
            toast.error('Gagal menyimpan kategori: ' + res.error);
        }
        setIsSubmitting(false);
    };

    const handleDelete = async (id: string) => {
        const confirmed = await confirm({
            title: 'Hapus Kategori?',
            message: 'Bunda yakin ingin menghapus kategori ini? Produk di dalamnya mungkin perlu diatur ulang.',
            confirmText: 'Ya, Hapus',
            cancelText: 'Batal',
            variant: 'danger'
        });

        if (!confirmed) return;

        setIsSubmitting(true);
        const res = await deleteIbuCategory(id);
        if (res.success) {
            onRefresh();
        } else {
            toast.error(res.error);
        }
        setIsSubmitting(false);
    };

    return (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-[#2D3A2D]/40 backdrop-blur-sm p-6 whitespace-normal">
            <div className="bg-[#FDFBF7] w-full max-w-lg rounded-[2.5rem] shadow-2xl border border-[#E5E1D8] overflow-hidden flex flex-col animate-in zoom-in slide-in-from-bottom-4 duration-300">
                {/* Header */}
                <div className="px-8 py-6 border-b border-[#E5E1D8] bg-white flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-amber-100 text-amber-700 rounded-xl">
                            <Tag className="w-4 h-4" />
                        </div>
                        <h3 className="text-lg font-black text-[#2D3A2D]">Kelola Kategori Menu</h3>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full transition-colors">
                        <X className="w-5 h-5 text-slate-400" />
                    </button>
                </div>

                {/* Content */}
                <div className="p-8 space-y-6">
                    {/* Add/Edit Form */}
                    {(isAdding || editingCategory) ? (
                        <form onSubmit={handleSave} className="bg-white p-6 rounded-2xl border-2 border-amber-200 border-dashed space-y-4">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black uppercase tracking-widest text-amber-700">
                                    {editingCategory ? 'Edit Nama Kategori' : 'Nama Kategori Baru'}
                                </label>
                                <input
                                    autoFocus
                                    type="text"
                                    value={folderName}
                                    onChange={(e) => setFolderName(e.target.value)}
                                    className="w-full bg-[#FDFBF7] border border-[#E5E1D8] rounded-xl px-4 py-3 text-sm font-bold focus:outline-none focus:border-amber-500"
                                    placeholder="Misal: Frozen, Camilan, Bumbu..."
                                />
                            </div>

                            <div className="flex gap-2">
                                <button
                                    type="button"
                                    onClick={() => {
                                        setIsAdding(false);
                                        setEditingCategory(null);
                                        setFolderName('');
                                    }}
                                    className="flex-1 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400"
                                >
                                    Batal
                                </button>
                                <button
                                    disabled={isSubmitting}
                                    type="submit"
                                    className="flex-2 px-8 py-3 bg-amber-600 text-white text-[10px] font-black uppercase tracking-widest rounded-xl hover:bg-amber-700 transition-colors shadow-lg shadow-amber-600/20"
                                >
                                    {isSubmitting ? 'Menyimpan...' : 'Simpan Kategori'}
                                </button>
                            </div>
                        </form>
                    ) : (
                        <button
                            onClick={() => setIsAdding(true)}
                            className="w-full py-4 border-2 border-dashed border-[#E5E1D8] rounded-2xl flex items-center justify-center gap-2 text-slate-400 hover:border-amber-400 hover:text-amber-600 transition-all font-bold group"
                        >
                            <Plus className="w-4 h-4 group-hover:scale-125 transition-transform" />
                            Tambah Kategori Menu Baru
                        </button>
                    )}

                    {/* Category List */}
                    <div className="space-y-3 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
                        {categories.map((cat) => (
                            <div key={cat.id} className="group flex items-center justify-between p-4 bg-white border border-[#E5E1D8] rounded-2xl hover:border-amber-200 hover:shadow-md transition-all">
                                <div className="flex items-center gap-3">
                                    <span className="text-lg">🍱</span>
                                    <div>
                                        <span className="font-bold text-[#2D3A2D]">{cat.name}</span>
                                        {cat.description && (
                                            <p className="text-[9px] text-slate-500 font-medium line-clamp-1">{cat.description}</p>
                                        )}
                                        {!cat.isActive && (
                                            <span className="text-[8px] bg-slate-100 px-2 py-0.5 rounded-full text-slate-500">Hidden</span>
                                        )}
                                    </div>
                                </div>
                                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button
                                        onClick={() => {
                                            setEditingCategory(cat);
                                            setFolderName(cat.name);
                                        }}
                                        className="p-2 text-slate-400 hover:text-amber-600 transition-colors"
                                    >
                                        <Edit2 className="w-4 h-4" />
                                    </button>
                                    <button
                                        onClick={() => handleDelete(cat.id)}
                                        className="p-2 text-slate-400 hover:text-rose-500 transition-colors"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="p-6 bg-[#F9F7F2] border-t border-[#E5E1D8] text-center">
                    <p className="text-[10px] text-slate-400 font-medium">Kategori ini hanya untuk mengatur tampilan Menu di Website.</p>
                </div>
            </div>
        </div>
    );
}

