'use client';

import React, { useState, useEffect } from 'react';
import { ChefHat, FileText, DollarSign, Save, ArrowLeft, Info, RefreshCw } from 'lucide-react';
import { getRecipesAction } from '@/lib/actions/rasa-ibu/production';
import { getStockAction } from '@/lib/actions/rasa-ibu/stock';
import { createMenuFromRecipeAction, createMenuManualAction } from '@/lib/actions/rasa-ibu/menu';
import { getPricingDataAction } from '@/lib/actions/rasa-ibu/overhead';
import PricingCalculator from './PricingCalculator';
import { toast } from 'sonner';

interface MenuCreationHubProps {
    brandId: string;
    onClose: () => void;
    onSuccess: () => void;
}

export default function MenuCreationHub({ brandId, onClose, onSuccess }: MenuCreationHubProps) {
    const [path, setPath] = useState<'recipe' | 'manual' | null>(null);
    const [recipes, setRecipes] = useState<any[]>([]);
    const [finishedGoods, setFinishedGoods] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [isLoadingPricing, setIsLoadingPricing] = useState(false);

    // Pricing data from Financial Hub
    const [pricingData, setPricingData] = useState<any>(null);

    // Form data
    const [selectedRecipeId, setSelectedRecipeId] = useState('');
    const [selectedVariantId, setSelectedVariantId] = useState('');
    const [manualHPP, setManualHPP] = useState(0);
    const [operationalCost, setOperationalCost] = useState(2000);
    const [marketplaceFee, setMarketplaceFee] = useState(0.15); // 15%
    const [targetMargin, setTargetMargin] = useState(0.30); // 30%

    // Calculated HPP from recipe
    const [calculatedHPP, setCalculatedHPP] = useState(0);

    useEffect(() => {
        loadData();
        loadPricingData();
    }, [brandId]);

    const loadPricingData = async () => {
        setIsLoadingPricing(true);
        const res = await getPricingDataAction(brandId);
        if (res.success && res.data) {
            setPricingData(res.data);
            // Auto-fill from Financial Hub data
            setOperationalCost(Math.round(res.data.operationalCost?.operationalCostPerUnit || 2000));
            setMarketplaceFee(res.data.marketplaceFee?.feeRate || 0.15);
            setTargetMargin(res.data.targetMargin || 0.30);
        }
        setIsLoadingPricing(false);
    };

    useEffect(() => {
        if (path === 'recipe' && selectedRecipeId) {
            calculateHPPFromRecipe(selectedRecipeId);
        }
    }, [selectedRecipeId]);

    const loadData = async () => {
        setIsLoading(true);
        const [recipesRes, stockRes] = await Promise.all([
            getRecipesAction(brandId),
            getStockAction(brandId)
        ]);

        if (recipesRes.success) setRecipes(recipesRes.data);
        if (stockRes.success) {
            const finished = stockRes.data.filter((v: any) => v.product.inventoryType === 'FINISHED_GOOD');
            setFinishedGoods(finished);
        }
        setIsLoading(false);
    };

    const calculateHPPFromRecipe = (recipeId: string) => {
        const recipe = recipes.find(r => r.id === recipeId);
        if (!recipe) return;

        let totalCost = 0;
        recipe.items.forEach((item: any) => {
            const costPrice = Number(item.ingredient.costPrice) || 0;
            const quantity = Number(item.quantity) || 0;
            totalCost += costPrice * quantity;
        });

        const hppPerUnit = recipe.outputQuantity > 0 ? totalCost / recipe.outputQuantity : totalCost;
        setCalculatedHPP(hppPerUnit);
    };

    const handleSave = async () => {
        if (path === 'recipe') {
            if (!selectedRecipeId) {
                toast.error('Pilih resep terlebih dahulu');
                return;
            }

            setIsSaving(true);
            const res = await createMenuFromRecipeAction({
                brandId,
                recipeId: selectedRecipeId,
                operationalCostPerUnit: operationalCost,
                marketplaceFeeRate: marketplaceFee,
                targetMargin
            });

            if (res.success) {
                toast.success('Menu berhasil dibuat dari resep!');
                onSuccess();
                onClose();
            } else {
                toast.error('Gagal membuat menu: ' + res.error);
            }
            setIsSaving(false);
        } else if (path === 'manual') {
            if (!selectedVariantId) {
                toast.error('Pilih produk terlebih dahulu');
                return;
            }

            setIsSaving(true);
            const res = await createMenuManualAction({
                brandId,
                variantId: selectedVariantId,
                hpp: manualHPP,
                operationalCostPerUnit: operationalCost,
                marketplaceFeeRate: marketplaceFee,
                targetMargin
            });

            if (res.success) {
                toast.success('Menu berhasil dibuat dengan pricing manual!');
                onSuccess();
                onClose();
            } else {
                toast.error('Gagal membuat menu: ' + res.error);
            }
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="w-8 h-8 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
        );
    }

    if (!path) {
        return (
            <div className="space-y-8 animate-in fade-in zoom-in duration-500">
                <div className="text-center space-y-2">
                    <h3 className="text-3xl font-black text-[#2D3A2D]">Buat Menu Baru</h3>
                    <p className="text-xs text-slate-400 uppercase tracking-widest font-bold">Pilih metode pembuatan menu</p>
                </div>

                <div className="grid grid-cols-2 gap-6">
                    {/* Path 1: From Recipe */}
                    <button
                        onClick={() => setPath('recipe')}
                        className="group p-8 bg-gradient-to-br from-emerald-50 to-teal-50 hover:from-emerald-100 hover:to-teal-100 border-2 border-emerald-200 hover:border-emerald-400 rounded-[2rem] transition-all active:scale-95"
                    >
                        <div className="flex flex-col items-center space-y-4">
                            <div className="p-5 bg-emerald-600 text-white rounded-2xl shadow-lg shadow-emerald-500/20 group-hover:scale-110 transition-transform">
                                <ChefHat className="w-10 h-10" />
                            </div>
                            <div className="space-y-1 text-center">
                                <h4 className="text-lg font-black text-emerald-900 uppercase tracking-tight">Dari Resep</h4>
                                <p className="text-xs text-emerald-700 font-medium">HPP dihitung otomatis dari bahan baku</p>
                            </div>
                            <div className="pt-4 space-y-1">
                                <div className="flex items-center gap-2 text-[10px] text-emerald-600 font-bold">
                                    <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div>
                                    Akurat & Konsisten
                                </div>
                                <div className="flex items-center gap-2 text-[10px] text-emerald-600 font-bold">
                                    <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div>
                                    Tracking Bahan Baku
                                </div>
                            </div>
                        </div>
                    </button>

                    {/* Path 2: Manual */}
                    <button
                        onClick={() => setPath('manual')}
                        className="group p-8 bg-gradient-to-br from-blue-50 to-indigo-50 hover:from-blue-100 hover:to-indigo-100 border-2 border-blue-200 hover:border-blue-400 rounded-[2rem] transition-all active:scale-95"
                    >
                        <div className="flex flex-col items-center space-y-4">
                            <div className="p-5 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-500/20 group-hover:scale-110 transition-transform">
                                <FileText className="w-10 h-10" />
                            </div>
                            <div className="space-y-1 text-center">
                                <h4 className="text-lg font-black text-blue-900 uppercase tracking-tight">Manual</h4>
                                <p className="text-xs text-blue-700 font-medium">Input HPP manual tanpa resep</p>
                            </div>
                            <div className="pt-4 space-y-1">
                                <div className="flex items-center gap-2 text-[10px] text-blue-600 font-bold">
                                    <div className="w-1.5 h-1.5 bg-blue-500 rounded-full"></div>
                                    Cepat & Fleksibel
                                </div>
                                <div className="flex items-center gap-2 text-[10px] text-blue-600 font-bold">
                                    <div className="w-1.5 h-1.5 bg-blue-500 rounded-full"></div>
                                    Untuk Menu Sederhana
                                </div>
                            </div>
                        </div>
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <button
                        onClick={() => setPath(null)}
                        className="p-3 bg-slate-100 hover:bg-slate-200 rounded-xl transition-colors"
                    >
                        <ArrowLeft className="w-5 h-5 text-slate-600" />
                    </button>
                    <div>
                        <h3 className="text-2xl font-black text-[#2D3A2D]">
                            {path === 'recipe' ? 'Buat Menu dari Resep' : 'Buat Menu Manual'}
                        </h3>
                        <p className="text-xs text-slate-400 uppercase tracking-widest font-bold">
                            {path === 'recipe' ? 'HPP otomatis dari bahan baku' : 'Input HPP manual'}
                        </p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-2 gap-8">
                {/* Left: Form */}
                <div className="space-y-6">
                    {path === 'recipe' ? (
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-emerald-900 uppercase">Pilih Resep</label>
                            <select
                                value={selectedRecipeId}
                                onChange={e => setSelectedRecipeId(e.target.value)}
                                className="w-full p-4 bg-white border border-emerald-100 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-emerald-500 outline-none"
                            >
                                <option value="">-- Pilih Resep --</option>
                                {recipes.map(r => (
                                    <option key={r.id} value={r.id}>{r.name} ({r.outputQuantity} porsi)</option>
                                ))}
                            </select>
                            {selectedRecipeId && (
                                <div className="p-4 bg-emerald-50 border border-emerald-100 rounded-2xl space-y-2">
                                    <div className="flex justify-between items-center text-[10px] font-bold text-emerald-800 uppercase tracking-tighter">
                                        <span>Modal Bahan (Resep)</span>
                                        <span>Rp {calculatedHPP.toLocaleString('id-ID')}</span>
                                    </div>
                                    <div className="flex justify-between items-center text-[10px] font-bold text-emerald-800 uppercase tracking-tighter">
                                        <span>Alokasi Operasional</span>
                                        <span>+ Rp {operationalCost.toLocaleString('id-ID')}</span>
                                    </div>
                                    <div className="h-px bg-emerald-200/50" />
                                    <div className="flex justify-between items-center font-black">
                                        <span className="text-[11px] text-emerald-900">TOTAL MODAL DASAR</span>
                                        <span className="text-sm text-emerald-900">Rp {(calculatedHPP + operationalCost).toLocaleString('id-ID')}</span>
                                    </div>
                                </div>
                            )}
                        </div>
                    ) : (
                        <>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-blue-900 uppercase">Pilih Produk</label>
                                <select
                                    value={selectedVariantId}
                                    onChange={e => setSelectedVariantId(e.target.value)}
                                    className="w-full p-4 bg-white border border-blue-100 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                                >
                                    <option value="">-- Pilih Produk --</option>
                                    {finishedGoods.map(v => (
                                        <option key={v.id} value={v.id}>{v.product.name} - {v.name}</option>
                                    ))}
                                </select>
                            </div>
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-blue-900 uppercase">HPP Manual (Rp)</label>
                                <input
                                    type="number"
                                    value={manualHPP}
                                    onChange={e => setManualHPP(parseFloat(e.target.value) || 0)}
                                    className="w-full p-4 bg-white border border-blue-100 rounded-2xl text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                                    placeholder="10000"
                                />
                                {manualHPP > 0 && (
                                    <div className="p-4 bg-blue-50 border border-blue-100 rounded-2xl space-y-2">
                                        <div className="flex justify-between items-center text-[10px] font-bold text-blue-800 uppercase tracking-tighter">
                                            <span>Modal Bahan</span>
                                            <span>Rp {manualHPP.toLocaleString('id-ID')}</span>
                                        </div>
                                        <div className="flex justify-between items-center text-[10px] font-bold text-blue-800 uppercase tracking-tighter">
                                            <span>Alokasi Operasional</span>
                                            <span>+ Rp {operationalCost.toLocaleString('id-ID')}</span>
                                        </div>
                                        <div className="h-px bg-blue-200/50" />
                                        <div className="flex justify-between items-center font-black">
                                            <span className="text-[11px] text-blue-900">TOTAL MODAL DASAR</span>
                                            <span className="text-sm text-blue-900">Rp {(manualHPP + operationalCost).toLocaleString('id-ID')}</span>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </>
                    )}

                    <div className="space-y-2">
                        <div className="flex items-center justify-between">
                            <label className="text-[10px] font-black text-[#8B7E66] uppercase">Biaya Operasional per Unit (Rp)</label>
                            <button
                                onClick={loadPricingData}
                                disabled={isLoadingPricing}
                                className="flex items-center gap-1 text-[9px] font-bold text-blue-600 hover:text-blue-700 disabled:opacity-50"
                            >
                                <RefreshCw className={`w-3 h-3 ${isLoadingPricing ? 'animate-spin' : ''}`} />
                                Reload dari Financial Hub
                            </button>
                        </div>
                        <input
                            type="number"
                            value={operationalCost}
                            onChange={e => setOperationalCost(parseFloat(e.target.value) || 0)}
                            className="w-full p-4 bg-white border border-[#E5E1D8] rounded-2xl text-sm font-bold focus:ring-2 focus:ring-emerald-500 outline-none"
                        />
                        {pricingData?.operationalCost && (
                            <div className="p-3 bg-blue-50 rounded-xl border border-blue-100">
                                <div className="flex items-start gap-2">
                                    <Info className="w-4 h-4 text-blue-600 mt-0.5 flex-shrink-0" />
                                    <div className="space-y-1">
                                        <p className="text-[10px] font-bold text-blue-900">Dihitung dari Financial Hub:</p>
                                        <div className="flex justify-between gap-4">
                                            <span className="text-[9px] text-blue-700">Total Overhead:</span>
                                            <span className="text-[9px] font-bold text-blue-700">Rp {Math.round(pricingData.operationalCost.totalOverhead).toLocaleString('id-ID')}</span>
                                        </div>
                                        <div className="flex justify-between gap-4">
                                            <span className="text-[9px] text-blue-700">Target Volume:</span>
                                            <span className="text-[9px] font-bold text-blue-700">{pricingData.operationalCost.targetVolume} porsi/bulan</span>
                                        </div>
                                        <div className="h-px bg-blue-200 my-1" />
                                        <div className="flex justify-between gap-4">
                                            <span className="text-[9px] font-black text-blue-800">Biaya per Porsi:</span>
                                            <span className="text-[9px] font-black text-blue-800">Rp {Math.round(pricingData.operationalCost.operationalCostPerUnit).toLocaleString('id-ID')}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-[#8B7E66] uppercase">Marketplace Fee (%)</label>
                            <input
                                type="number"
                                value={marketplaceFee * 100}
                                onChange={e => setMarketplaceFee((parseFloat(e.target.value) || 0) / 100)}
                                className="w-full p-4 bg-white border border-[#E5E1D8] rounded-2xl text-sm font-bold focus:ring-2 focus:ring-emerald-500 outline-none"
                                step="0.1"
                            />
                            {pricingData?.marketplaceFee && (
                                <p className="text-[9px] text-blue-600 font-bold flex items-center gap-1">
                                    <Info className="w-3 h-3" />
                                    {pricingData.marketplaceFee.platform === 'AVERAGE' ? 'Rata-rata' : pricingData.marketplaceFee.platform}: {pricingData.marketplaceFee.feePercentage.toFixed(1)}%
                                </p>
                            )}
                        </div>
                        <div className="space-y-2">
                            <label className="text-[10px] font-black text-[#8B7E66] uppercase">Target Margin (%)</label>
                            <input
                                type="number"
                                value={targetMargin * 100}
                                onChange={e => setTargetMargin((parseFloat(e.target.value) || 0) / 100)}
                                className="w-full p-4 bg-white border border-[#E5E1D8] rounded-2xl text-sm font-bold focus:ring-2 focus:ring-emerald-500 outline-none"
                                step="0.1"
                            />
                        </div>
                    </div>

                    <button
                        onClick={handleSave}
                        disabled={isSaving || (path === 'recipe' ? !selectedRecipeId : !selectedVariantId)}
                        className="w-full py-5 bg-emerald-600 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-xl shadow-emerald-500/20 hover:bg-emerald-700 transition-all active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                    >
                        <Save className="w-4 h-4" />
                        {isSaving ? 'Menyimpan...' : 'Simpan Menu & Pricing'}
                    </button>
                </div>

                {/* Right: Pricing Calculator */}
                <div>
                    <PricingCalculator
                        hpp={path === 'recipe' ? calculatedHPP : manualHPP}
                        operationalCost={operationalCost}
                        marketplaceFeeRate={marketplaceFee}
                        targetMargin={targetMargin}
                    />
                </div>
            </div>
        </div>
    );
}

'use client';

import React from 'react';
import { Calculator, TrendingUp, DollarSign } from 'lucide-react';

interface PricingCalculatorProps {
    hpp: number;
    operationalCost: number;
    marketplaceFeeRate: number; // 0.15 = 15%
    targetMargin: number; // 0.30 = 30%
    onChange?: (sellingPrice: number) => void;
}

export default function PricingCalculator({
    hpp,
    operationalCost,
    marketplaceFeeRate,
    targetMargin,
    onChange
}: PricingCalculatorProps) {
    // Simulation State
    const [simulatedVolume, setSimulatedVolume] = React.useState<number>(100);
    const [isSimulating, setIsSimulating] = React.useState(false);

    // Reverse engineer Total Overhead from Unit OpCost (assuming standard volume of 100 if unknown)
    const estimatedTotalOverhead = operationalCost * 100;

    // Calculate Dynamic Op Cost based on Simulation
    const dynamicOpCost = isSimulating ? (estimatedTotalOverhead / simulatedVolume) : operationalCost;

    // Formula: Selling Price = (HPP + OpCost) / (1 - MarketplaceFee - Margin)
    const subtotal = hpp + dynamicOpCost;
    const divisor = 1 - marketplaceFeeRate - targetMargin;
    const sellingPrice = divisor > 0 ? subtotal / divisor : 0;

    const marketplaceFee = sellingPrice * marketplaceFeeRate;
    const targetProfit = sellingPrice * targetMargin;
    const netProfit = sellingPrice - hpp - dynamicOpCost - marketplaceFee;

    React.useEffect(() => {
        if (onChange) {
            onChange(Math.round(sellingPrice));
        }
    }, [sellingPrice, onChange]);

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center gap-3">
                <div className="p-3 bg-emerald-50 rounded-2xl">
                    <Calculator className="w-6 h-6 text-emerald-600" />
                </div>
                <div>
                    <h4 className="text-xs font-black uppercase tracking-widest text-emerald-900">Kalkulasi Harga Jual</h4>
                    <p className="text-[10px] text-emerald-600 font-medium">Otomatis berdasarkan HPP + Biaya Operasional</p>
                </div>
            </div>

            {/* Volume Simulator */}
            <div className="p-5 bg-[#F9F7F2] rounded-2xl border border-[#E5E1D8] space-y-3">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <TrendingUp className="w-4 h-4 text-emerald-600" />
                        <span className="text-[10px] font-black uppercase tracking-widest text-[#2D3A2D]">
                            Simulasi Volume Penjualan
                        </span>
                    </div>
                    <label className="relative inline-flex items-center cursor-pointer">
                        <input
                            type="checkbox"
                            checked={isSimulating}
                            onChange={(e) => setIsSimulating(e.target.checked)}
                            className="sr-only peer"
                        />
                        <div className="w-9 h-5 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-emerald-600"></div>
                    </label>
                </div>

                {isSimulating ? (
                    <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
                        <input
                            type="range"
                            min="50"
                            max="1000"
                            step="50"
                            value={simulatedVolume}
                            onChange={(e) => setSimulatedVolume(parseInt(e.target.value))}
                            className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-emerald-600"
                        />
                        <div className="flex justify-between items-center text-xs font-bold">
                            <span>50 Porsi</span>
                            <span className="text-emerald-600 bg-emerald-100 px-3 py-1 rounded-lg">{simulatedVolume} Porsi / Bulan</span>
                            <span>1000 Porsi</span>
                        </div>
                        <p className="text-[10px] italic text-[#8B7E66]">
                            "Semakin tinggi volume penjualan, semakin kecil beban per porsi."
                        </p>
                    </div>
                ) : (
                    <p className="text-[10px] text-[#8B7E66] opacity-60">Aktifkan untuk melihat dampak target penjualan terhadap harga.</p>
                )}
            </div>

            {/* Breakdown */}
            <div className="space-y-3">
                <div className="flex justify-between items-center p-4 bg-slate-50 rounded-xl">
                    <span className="text-xs font-bold text-slate-600">HPP (Harga Pokok Produksi)</span>
                    <span className="text-sm font-black text-slate-900">Rp {hpp.toLocaleString('id-ID')}</span>
                </div>
                <div className={`flex justify-between items-center p-4 rounded-xl transition-colors ${isSimulating ? 'bg-amber-50 border border-amber-200' : 'bg-slate-50'}`}>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold text-slate-600">
                            Alokasi Biaya Tetap (Fixed Cost)
                            {isSimulating && <span className="ml-2 text-[9px] text-amber-600 font-bold bg-amber-100 px-2 py-0.5 rounded-full">SIMULATED</span>}
                        </span>
                        <span className="text-[9px] text-slate-400 font-medium mt-0.5">Listrik, Gaji, Sewa (dibagi volume)</span>
                    </div>
                    <span className={`text-sm font-black ${isSimulating ? 'text-amber-700' : 'text-slate-900'}`}>
                        Rp {Math.round(dynamicOpCost).toLocaleString('id-ID')}
                    </span>
                </div>
                <div className="flex justify-between items-center p-4 bg-blue-50 rounded-xl border border-blue-100">
                    <span className="text-xs font-bold text-blue-700">Total Modal Dasar (HPP + Overhead)</span>
                    <span className="text-sm font-black text-blue-900">Rp {Math.round(subtotal).toLocaleString('id-ID')}</span>
                </div>
            </div>

            {/* Formula Explanation */}
            <div className="p-5 bg-gradient-to-br from-amber-50 to-orange-50 rounded-2xl border border-amber-200">
                <p className="text-[10px] font-black uppercase tracking-widest text-amber-900 mb-2">Formula Pricing</p>
                <div className="space-y-2">
                    <p className="text-xs font-mono text-amber-800">
                        Harga Jual = Modal Dasar / (1 - Fee - Margin)
                    </p>
                    <p className="text-xs font-mono text-amber-800">
                        = Rp {Math.round(subtotal).toLocaleString('id-ID')} / (1 - {(marketplaceFeeRate * 100).toFixed(0)}% - {(targetMargin * 100).toFixed(0)}%)
                    </p>
                    <p className="text-xs font-mono text-amber-800">
                        Dimana Modal Dasar = HPP + Overhead (OpCost)
                    </p>
                </div>
            </div>

            {/* Result */}
            <div className="p-8 bg-gradient-to-br from-emerald-600 to-teal-600 rounded-[2rem] text-white shadow-xl shadow-emerald-500/20">
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-2">
                        <DollarSign className="w-5 h-5" />
                        <span className="text-xs font-black uppercase tracking-widest">Harga Jual Rekomendasi</span>
                    </div>
                    <TrendingUp className="w-5 h-5 opacity-50" />
                </div>
                <p className="text-5xl font-black mb-2">Rp {Math.round(sellingPrice).toLocaleString('id-ID')}</p>
                <p className="text-xs opacity-80 font-medium">per porsi / unit</p>
            </div>

            {/* Profit Breakdown */}
            <div className="grid grid-cols-3 gap-3">
                <div className="p-4 bg-red-50 rounded-xl border border-red-100">
                    <p className="text-[9px] font-black uppercase tracking-wider text-red-600 mb-1">Marketplace Fee</p>
                    <p className="text-lg font-black text-red-700">Rp {Math.round(marketplaceFee).toLocaleString('id-ID')}</p>
                    <p className="text-[8px] text-red-500 font-medium">{(marketplaceFeeRate * 100).toFixed(0)}% dari harga jual</p>
                </div>
                <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
                    <p className="text-[9px] font-black uppercase tracking-wider text-blue-600 mb-1">Target Margin</p>
                    <p className="text-lg font-black text-blue-700">Rp {Math.round(targetProfit).toLocaleString('id-ID')}</p>
                    <p className="text-[8px] text-blue-500 font-medium">{(targetMargin * 100).toFixed(0)}% dari harga jual</p>
                </div>
                <div className="p-4 bg-emerald-50 rounded-xl border border-emerald-100">
                    <p className="text-[9px] font-black uppercase tracking-wider text-emerald-600 mb-1">Net Profit</p>
                    <p className="text-lg font-black text-emerald-700">Rp {Math.round(netProfit).toLocaleString('id-ID')}</p>
                    <p className="text-[8px] text-emerald-500 font-medium">Keuntungan bersih</p>
                </div>
            </div>
        </div>
    );
}

'use client';

import React, { useState, useEffect } from 'react';
import { X, ChefHat, BookOpen, BarChart3, Plus, Search, ChevronRight, Play, CheckCircle2, AlertCircle, UtensilsCrossed } from 'lucide-react';
import { getRecipesAction, getProductionPlansAction } from '@/lib/actions/rasa-ibu/production';
import RecipeManager from './RecipeManager';
import CookingList from './CookingList';
import IngredientForecaster from './IngredientForecaster';
import MenuCreationHub from './MenuCreationHub';

interface ProductionHubProps {
    brandId: string;
    onClose: () => void;
}

export default function ProductionHub({ brandId, onClose }: ProductionHubProps) {
    const [activeTab, setActiveTab] = useState<'COOKING' | 'RECIPES' | 'FORECAST' | 'MENU'>('COOKING');
    const [recipes, setRecipes] = useState<any[]>([]);
    const [plans, setPlans] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const loadData = async () => {
        setIsLoading(true);
        const [recipeRes, planRes] = await Promise.all([
            getRecipesAction(brandId),
            getProductionPlansAction(brandId)
        ]);

        if (recipeRes.success) setRecipes(recipeRes.data);
        if (planRes.success) setPlans(planRes.data);
        setIsLoading(false);
    };

    useEffect(() => {
        loadData();
    }, [brandId]);

    return (
        <div className="flex flex-col h-full bg-[#FDFBF7] rounded-[3rem] shadow-2xl border border-[#E5E1D8] overflow-hidden animate-in fade-in zoom-in duration-500">

            {/* Header */}
            <div className="px-12 py-8 border-b border-[#E5E1D8] bg-white flex justify-between items-center">
                <div className="flex items-center gap-6">
                    <div className="p-4 bg-emerald-50 rounded-2xl">
                        <ChefHat className="w-8 h-8 text-emerald-600" />
                    </div>
                    <div className="space-y-1">
                        <span className="text-[10px] font-black uppercase tracking-[0.4em] text-emerald-600">Kitchen Intelligence</span>
                        <h2 className="text-3xl font-black text-[#2D3A2D]">Pusat Produksi Dapur</h2>
                    </div>
                </div>
                <button
                    onClick={onClose}
                    className="p-3 hover:bg-slate-100 rounded-full transition-colors"
                >
                    <X className="w-6 h-6 text-slate-400" />
                </button>
            </div>

            {/* Tab Navigation */}
            <div className="flex border-b border-[#E5E1D8] bg-[#F9F7F2]">
                <button
                    onClick={() => setActiveTab('COOKING')}
                    className={`flex-1 py-6 flex flex-col items-center justify-center gap-2 border-b-4 transition-colors ${activeTab === 'COOKING' ? 'border-emerald-600 bg-white' : 'border-transparent hover:bg-white/50'
                        }`}
                >
                    <div className="flex items-center gap-2">
                        <Play className={`w-4 h-4 ${activeTab === 'COOKING' ? 'text-emerald-600' : 'text-slate-400'}`} />
                        <span className={`text-xs font-black uppercase tracking-widest ${activeTab === 'COOKING' ? 'text-[#2D3A2D]' : 'text-slate-400'}`}>Produksi Aktif</span>
                    </div>
                </button>
                <button
                    onClick={() => setActiveTab('RECIPES')}
                    className={`flex-1 py-6 flex flex-col items-center justify-center gap-2 border-b-4 transition-colors ${activeTab === 'RECIPES' ? 'border-emerald-600 bg-white' : 'border-transparent hover:bg-white/50'
                        }`}
                >
                    <div className="flex items-center gap-2">
                        <BookOpen className={`w-4 h-4 ${activeTab === 'RECIPES' ? 'text-emerald-600' : 'text-slate-400'}`} />
                        <span className={`text-xs font-black uppercase tracking-widest ${activeTab === 'RECIPES' ? 'text-[#2D3A2D]' : 'text-slate-400'}`}>Katalog Resep</span>
                    </div>
                </button>
                <button
                    onClick={() => setActiveTab('FORECAST')}
                    className={`flex-1 py-6 flex flex-col items-center justify-center gap-2 border-b-4 transition-colors ${activeTab === 'FORECAST' ? 'border-emerald-600 bg-white' : 'border-transparent hover:bg-white/50'
                        }`}
                >
                    <div className="flex items-center gap-2">
                        <BarChart3 className={`w-4 h-4 ${activeTab === 'FORECAST' ? 'text-emerald-600' : 'text-slate-400'}`} />
                        <span className={`text-xs font-black uppercase tracking-widest ${activeTab === 'FORECAST' ? 'text-[#2D3A2D]' : 'text-slate-400'}`}>Ramalan Bahan</span>
                    </div>
                </button>
                <button
                    onClick={() => setActiveTab('MENU')}
                    className={`flex-1 py-6 flex flex-col items-center justify-center gap-2 border-b-4 transition-colors ${activeTab === 'MENU' ? 'border-emerald-600 bg-white' : 'border-transparent hover:bg-white/50'
                        }`}
                >
                    <div className="flex items-center gap-2">
                        <UtensilsCrossed className={`w-4 h-4 ${activeTab === 'MENU' ? 'text-emerald-600' : 'text-slate-400'}`} />
                        <span className={`text-xs font-black uppercase tracking-widest ${activeTab === 'MENU' ? 'text-[#2D3A2D]' : 'text-slate-400'}`}>Buat Menu</span>
                    </div>
                </button>
            </div>

            {/* Content Area */}
            <div className="flex-1 overflow-y-auto bg-white p-12">
                {isLoading ? (
                    <div className="flex flex-col items-center justify-center py-20 space-y-4">
                        <div className="w-12 h-12 border-4 border-emerald-200 border-t-emerald-600 rounded-full animate-spin"></div>
                        <p className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Menyiapkan Dapur...</p>
                    </div>
                ) : (
                    <div className="max-w-5xl mx-auto">
                        {activeTab === 'COOKING' && (
                            <CookingList
                                brandId={brandId}
                                plans={plans}
                                recipes={recipes}
                                onRefresh={loadData}
                            />
                        )}
                        {activeTab === 'RECIPES' && (
                            <RecipeManager
                                brandId={brandId}
                                recipes={recipes}
                                onRefresh={loadData}
                            />
                        )}
                        {activeTab === 'FORECAST' && (
                            <IngredientForecaster
                                brandId={brandId}
                                plans={plans}
                            />
                        )}
                        {activeTab === 'MENU' && (
                            <MenuCreationHub
                                brandId={brandId}
                                onClose={() => setActiveTab('RECIPES')}
                                onSuccess={loadData}
                            />
                        )}
                    </div>
                )}
            </div>

            {/* Status Footer */}
            <div className="px-12 py-4 bg-[#FDFBF7] border-t border-[#E5E1D8] flex justify-between items-center opacity-70">
                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2">
                        <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
                        <span className="text-[9px] font-black text-[#8B7E66] uppercase">Kitchen Link Online</span>
                    </div>
                </div>
                <p className="text-[9px] font-medium text-[#8B7E66] italic">
                    "Produksi yang terencana adalah kunci efisiensi."
                </p>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Save, Search, Book, Info, ChevronRight, Calculator, Pencil, X } from 'lucide-react';
import { upsertRecipeAction } from '@/lib/actions/rasa-ibu/production';
import { getStockAction, updateIngredientAction } from '@/lib/actions/rasa-ibu/stock';
import { toast } from 'sonner';

interface RecipeManagerProps {
    brandId: string;
    recipes: any[];
    onRefresh: () => void;
}

export default function RecipeManager({ brandId, recipes, onRefresh }: RecipeManagerProps) {
    const [isAdding, setIsAdding] = useState(false);
    const [editingRecipe, setEditingRecipe] = useState<any>(null);
    const [inventory, setInventory] = useState<any[]>([]);
    const [searchTerm, setSearchTerm] = useState('');

    const [formData, setFormData] = useState({
        name: '',
        description: '',
        frozenVariantId: '',
        outputQuantity: 1,
        items: [] as { ingredientId: string; quantity: number; unit: string; note: string }[]
    });

    // Helper: Unit Conversion
    const convertToMatchStockUnit = (qty: number, fromUnit: string, toUnit: string): number => {
        const normalize = (u: string) => u?.toLowerCase() || '';
        const f = normalize(fromUnit);
        const t = normalize(toUnit);

        if (f === t) return qty;

        // Weight
        if (f === 'gram' && t === 'kg') return qty / 1000;
        if (f === 'kg' && t === 'gram') return qty * 1000;

        // Volume
        if (f === 'ml' && t === 'liter') return qty / 1000;
        if (f === 'liter' && t === 'ml') return qty * 1000;

        // Fallback: No conversion logic found, assume 1:1 but warn logically (future improvement)
        return qty;
    };

    // Cost Editor State
    const [editingCostItem, setEditingCostItem] = useState<any>(null);
    const [calcData, setCalcData] = useState({ packPrice: '', packSize: '' });
    const [isUpdatingCost, setIsUpdatingCost] = useState(false);

    // Real-time HPP Calculation with Conversion
    const estimatedHPP = React.useMemo(() => {
        let total = 0;
        formData.items.forEach(item => {
            const ingredient = inventory.find(inv => inv.id === item.ingredientId);
            if (ingredient) {
                const convertedQty = convertToMatchStockUnit(item.quantity || 0, item.unit, ingredient.unit);
                total += Number(ingredient.costPrice || 0) * convertedQty;
            }
        });
        return {
            total,
            perUnit: formData.outputQuantity > 0 ? total / formData.outputQuantity : 0
        };
    }, [formData.items, formData.outputQuantity, inventory]);

    const loadInventory = async () => {
        const res = await getStockAction(brandId);
        if (res.success) setInventory(res.data);
    };

    useEffect(() => {
        loadInventory();
    }, [brandId]);

    const handleUpdateCost = async () => {
        if (!editingCostItem || !calcData.packPrice || !calcData.packSize) return;

        const price = parseFloat(calcData.packPrice);
        const size = parseFloat(calcData.packSize);

        if (isNaN(price) || isNaN(size) || size <= 0) {
            toast.error('Mohon masukkan angka yang valid');
            return;
        }

        const newUnitCost = parseFloat((price / size).toFixed(2));

        setIsUpdatingCost(true);
        try {
            const res = await updateIngredientAction({
                variantId: editingCostItem.id,
                productName: editingCostItem.product.name,
                inventoryCategoryId: editingCostItem.product.inventoryCategoryId,
                storageType: editingCostItem.product.storageType,
                shelfLife: editingCostItem.product.shelfLife || 0,
                unitName: editingCostItem.unit,
                costPrice: newUnitCost,
                inventoryType: editingCostItem.product.inventoryType
            });

            if (res.success) {
                toast.success(`Harga ${editingCostItem.product.name} berhasil diperbarui jadi Rp ${newUnitCost}/${editingCostItem.unit}`);
                setEditingCostItem(null);
                setCalcData({ packPrice: '', packSize: '' });
                await loadInventory(); // Refresh Master Data
            } else {
                toast.error('Gagal update: ' + res.error);
            }
        } catch (error: any) {
            toast.error('Error: ' + error.message);
        } finally {
            setIsUpdatingCost(false);
        }
    };

    const handleSave = async () => {
        if (!formData.name || !formData.frozenVariantId || formData.items.length === 0) {
            toast.error('Mohon lengkapi nama, produk hasil, dan minimal 1 bahan.');
            return;
        }

        const res = await upsertRecipeAction({
            ...formData,
            id: editingRecipe?.id,
            brandId
        });

        if (res.success) {
            setIsAdding(false);
            setEditingRecipe(null);
            onRefresh();
        } else {
            toast.error('Gagal menyimpan resep: ' + res.error);
        }
    };

    const addIngredient = () => {
        setFormData({
            ...formData,
            items: [...formData.items, { ingredientId: '', quantity: 0, unit: 'gram', note: '' }]
        });
    };

    const removeIngredient = (index: number) => {
        const newItems = [...formData.items];
        newItems.splice(index, 1);
        setFormData({ ...formData, items: newItems });
    };

    const updateIngredient = (index: number, field: string, value: any) => {
        const newItems = [...formData.items];
        newItems[index] = { ...newItems[index], [field]: value };
        setFormData({ ...formData, items: newItems });
    };

    const filteredRecipes = recipes.filter(r =>
        r.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (isAdding || editingRecipe) {
        return (
            <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
                <div className="flex items-center justify-between">
                    <div>
                        <h3 className="text-xl font-black text-[#2D3A2D]">{editingRecipe ? 'Edit Resep' : 'Tambah Resep Baru'}</h3>
                        <p className="text-xs text-slate-400 font-medium">Definisikan bahan-bahan untuk setiap menu.</p>
                    </div>
                    <button
                        onClick={() => { setIsAdding(false); setEditingRecipe(null); }}
                        className="text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-colors"
                    >
                        Batal
                    </button>
                </div>

                <div className="grid grid-cols-2 gap-8">
                    {/* Basic Info */}
                    <div className="space-y-6 bg-slate-50/50 p-8 rounded-[2rem] border border-slate-100">
                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Nama Resep</label>
                            <input
                                value={formData.name}
                                onChange={e => setFormData({ ...formData, name: e.target.value })}
                                className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 font-bold text-[#2D3A2D] focus:ring-2 focus:ring-emerald-500 outline-none"
                                placeholder="Misal: Risol Mayo Mamah"
                            />
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Produk Hasil (Output)</label>
                            <select
                                value={formData.frozenVariantId}
                                onChange={e => setFormData({ ...formData, frozenVariantId: e.target.value })}
                                className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 font-bold text-[#2D3A2D] focus:ring-2 focus:ring-emerald-500 outline-none"
                            >
                                <option value="">Pilih Produk Finished Good</option>
                                {inventory.filter(item => item.product.inventoryType === 'FINISHED_GOOD').map(item => (
                                    <option key={item.id} value={item.id}>{item.product.name} ({item.sku})</option>
                                ))}
                            </select>
                        </div>

                        <div className="space-y-2">
                            <label className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Jumlah PCS per Masak</label>
                            <input
                                type="number"
                                value={formData.outputQuantity}
                                onChange={e => setFormData({ ...formData, outputQuantity: parseInt(e.target.value) })}
                                className="w-full bg-white border border-[#E5E1D8] rounded-xl px-4 py-3 font-bold text-[#2D3A2D] focus:ring-2 focus:ring-emerald-500 outline-none"
                            />
                        </div>
                    </div>

                    {/* HPP Preview Card */}
                    <div className="lg:col-span-2 bg-rose-50 border border-rose-100 rounded-[2rem] p-8 flex items-center justify-between">
                        <div className="flex items-center gap-6">
                            <div className="p-4 bg-rose-600 text-white rounded-2xl shadow-lg shadow-rose-500/20">
                                <Info className="w-6 h-6" />
                            </div>
                            <div className="space-y-1">
                                <h4 className="text-xs font-black uppercase tracking-widest text-rose-900">Estimasi HPP Otomatis</h4>
                                <p className="text-[10px] text-rose-700 font-bold">Kalkulasi berdasarkan harga beli bahan baku terbaru.</p>
                            </div>
                        </div>
                        <div className="text-right space-y-1">
                            <p className="text-[10px] font-black text-rose-400 uppercase tracking-widest text-right">HPP per Porsi</p>
                            <p className="text-3xl font-black text-rose-950">
                                Rp {estimatedHPP.perUnit.toLocaleString('id-ID')}
                            </p>
                            <p className="text-[9px] font-bold text-rose-600">Total Modal Masak: Rp {estimatedHPP.total.toLocaleString('id-ID')}</p>
                            <p className="text-[8px] text-rose-400 font-medium italic mt-1">
                                (Total Modal ÷ {formData.outputQuantity} pcs)
                            </p>
                        </div>
                    </div>

                    {/* Ingredients List */}
                    <div className="space-y-6">
                        <div className="flex items-center justify-between">
                            <label className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Bahan-bahan & Takaran</label>
                            <button
                                onClick={addIngredient}
                                className="flex items-center gap-1 text-[10px] font-black uppercase tracking-widest text-emerald-600 hover:text-emerald-700"
                            >
                                <Plus className="w-3 h-3" /> Tambah Bahan
                            </button>
                        </div>

                        <div className="space-y-3">
                            {formData.items.map((item, idx) => (
                                <React.Fragment key={idx}>
                                    <div className="flex gap-3 group">
                                        <select
                                            value={item.ingredientId}
                                            onChange={e => updateIngredient(idx, 'ingredientId', e.target.value)}
                                            className="flex-1 bg-white border border-[#E5E1D8] rounded-xl px-4 py-2 text-sm font-bold text-[#2D3A2D]"
                                        >
                                            <option value="">Pilih Bahan/Kemasan</option>
                                            {inventory.filter(inv => ['RAW_MATERIAL', 'PACKAGING', 'SUPPLY'].includes(inv.product.inventoryType)).map(inv => (
                                                <option key={inv.id} value={inv.id}>
                                                    [{inv.product.inventoryType === 'RAW_MATERIAL' ? 'Bahan' : inv.product.inventoryType === 'PACKAGING' ? 'Kemasan' : 'Alat'}] {inv.product.name} {inv.name !== 'Default' ? `- ${inv.name}` : ''}
                                                </option>
                                            ))}
                                        </select>

                                        {/* Cost Correction Button */}
                                        {item.ingredientId && (
                                            <button
                                                onClick={() => {
                                                    const inv = inventory.find(i => i.id === item.ingredientId);
                                                    if (inv) {
                                                        setEditingCostItem(inv);
                                                        setCalcData({ packPrice: '', packSize: '' });
                                                    }
                                                }}
                                                className="p-2 bg-amber-50 text-amber-600 rounded-xl hover:bg-amber-100 transition-colors"
                                                title="Koreksi Harga (Jika Salah)"
                                            >
                                                <Calculator className="w-4 h-4" />
                                            </button>
                                        )}

                                        <input
                                            type="number"
                                            placeholder="Qty"
                                            value={item.quantity}
                                            onChange={e => updateIngredient(idx, 'quantity', parseFloat(e.target.value))}
                                            className="w-20 bg-white border border-[#E5E1D8] rounded-xl px-4 py-2 text-sm font-bold text-[#2D3A2D]"
                                        />
                                        <select
                                            value={item.unit}
                                            onChange={e => updateIngredient(idx, 'unit', e.target.value)}
                                            className="w-24 bg-white border border-[#E5E1D8] rounded-xl px-3 py-2 text-sm font-bold text-[#2D3A2D]"
                                        >
                                            <option value="gram">gram</option>
                                            <option value="ml">ml</option>
                                            <option value="pcs">pcs</option>
                                            <option value="kg">kg</option>
                                            <option value="liter">liter</option>
                                        </select>
                                        <button
                                            onClick={() => removeIngredient(idx)}
                                            className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                    {/* Cost Breakdown for this item */}
                                    {item.ingredientId && (() => {
                                        const inv = inventory.find(i => i.id === item.ingredientId);
                                        if (inv) {
                                            const originalQty = Number(item.quantity || 0);
                                            const convertedQty = convertToMatchStockUnit(originalQty, item.unit, inv.unit);
                                            const cost = Number(inv.costPrice || 0) * convertedQty;

                                            const showConversion = item.unit !== inv.unit && originalQty !== convertedQty;

                                            return (
                                                <div className="flex justify-end -mt-2 mb-2 px-11">
                                                    <p className="text-[10px] text-slate-400 font-medium bg-slate-50 px-2 py-0.5 rounded-md flex items-center gap-1">
                                                        {showConversion && (
                                                            <span className="text-amber-600 bg-amber-50 px-1 rounded mr-1" title={`Konversi: ${item.unit} ke ${inv.unit}`}>
                                                                ({convertedQty} {inv.unit})
                                                            </span>
                                                        )}
                                                        {originalQty} {item.unit} x <span className="text-[#2D3A2D] font-bold">Rp {Number(inv.costPrice).toLocaleString('id-ID')} / {inv.unit}</span>
                                                        <span className="opacity-50 mx-1">=</span>
                                                        <span className="font-bold text-slate-600 underline decoration-slate-200">Rp {cost.toLocaleString('id-ID')}</span>
                                                    </p>
                                                </div>
                                            );
                                        }
                                    })()}
                                </React.Fragment>
                            ))}
                        </div>

                        <button
                            onClick={handleSave}
                            className="w-full bg-[#2D3A2D] text-white py-4 rounded-2xl font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-[#1A241A] transition-all shadow-lg shadow-[#2D3A2D]/20 active:scale-95 mt-4"
                        >
                            <Save className="w-4 h-4" /> Simpan Resep
                        </button>
                    </div>
                </div>

                {/* Cost Editor Modal */}
                {editingCostItem && (
                    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
                        <div className="bg-white rounded-[2rem] w-full max-w-md p-8 space-y-6 shadow-2xl scale-100 animate-in zoom-in-95 duration-200">
                            <div className="flex justify-between items-start">
                                <div>
                                    <h4 className="text-xl font-black text-[#2D3A2D]">Koreksi Harga Bahan</h4>
                                    <p className="text-sm font-bold text-emerald-600">{editingCostItem.product.name}</p>
                                </div>
                                <button onClick={() => setEditingCostItem(null)} className="p-2 hover:bg-slate-100 rounded-full">
                                    <X className="w-5 h-5 text-slate-400" />
                                </button>
                            </div>

                            <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100 space-y-2">
                                <p className="text-[10px] font-black uppercase tracking-widest text-amber-700">Harga Saat Ini (Salah)</p>
                                <p className="text-2xl font-black text-amber-900">
                                    Rp {Number(editingCostItem.costPrice).toLocaleString('id-ID')} <span className="text-sm font-medium opacity-50">/ {editingCostItem.unit}</span>
                                </p>
                            </div>

                            <div className="space-y-4">
                                <div className="space-y-1">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Biaya Total Beli (Rp)</label>
                                    <input
                                        type="number"
                                        className="w-full p-4 bg-white border border-[#E5E1D8] rounded-xl font-bold focus:ring-2 focus:ring-emerald-500 outline-none"
                                        placeholder="Contoh: 50800"
                                        value={calcData.packPrice}
                                        onChange={e => setCalcData({ ...calcData, packPrice: e.target.value })}
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Berat atau Total Stock (Isi)</label>
                                    <input
                                        type="number"
                                        className="w-full p-4 bg-white border border-[#E5E1D8] rounded-xl font-bold focus:ring-2 focus:ring-emerald-500 outline-none"
                                        placeholder="Contoh: 1000"
                                        value={calcData.packSize}
                                        onChange={e => setCalcData({ ...calcData, packSize: e.target.value })}
                                    />
                                </div>
                            </div>

                            {calcData.packPrice && calcData.packSize && (
                                <div className="p-4 bg-emerald-50 rounded-2xl border border-emerald-100 flex justify-between items-center animate-in slide-in-from-top-2">
                                    <span className="text-xs font-bold text-emerald-700 uppercase">Harga Baru:</span>
                                    <span className="text-xl font-black text-emerald-600">
                                        Rp {(parseFloat(calcData.packPrice) / parseFloat(calcData.packSize)).toLocaleString('id-ID', { maximumFractionDigits: 2 })} <span className="text-xs opacity-50">/{editingCostItem.unit}</span>
                                    </span>
                                </div>
                            )}

                            <button
                                onClick={handleUpdateCost}
                                disabled={isUpdatingCost || !calcData.packPrice || !calcData.packSize}
                                className="w-full py-4 bg-emerald-600 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-emerald-700 transition-all shadow-lg active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {isUpdatingCost ? 'Menyimpan...' : 'Simpan Harga Baru'}
                            </button>
                        </div>
                    </div>
                )
                }
            </div>
        );
    }


    return (
        <div className="space-y-8">
            <div className="flex items-center justify-between">
                <div className="relative flex-1 max-w-md">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input
                        value={searchTerm}
                        onChange={e => setSearchTerm(e.target.value)}
                        placeholder="Cari resep..."
                        className="w-full bg-[#F9F7F2] border border-[#E5E1D8] rounded-2xl pl-12 pr-4 py-3 text-sm font-bold text-[#2D3A2D] focus:ring-2 focus:ring-emerald-500 outline-none"
                    />
                </div>
                <button
                    onClick={() => {
                        setFormData({ name: '', description: '', frozenVariantId: '', outputQuantity: 1, items: [] });
                        setIsAdding(true);
                    }}
                    className="flex items-center gap-2 bg-emerald-600 text-white px-6 py-3 rounded-2xl font-black uppercase tracking-widest text-[10px] hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/20 active:scale-95"
                >
                    <Plus className="w-4 h-4" /> Buat Resep Baru
                </button>
            </div>

            <div className="grid grid-cols-2 gap-6">
                {filteredRecipes.map((recipe) => (
                    <div
                        key={recipe.id}
                        className="p-6 rounded-[2rem] border border-[#E5E1D8] hover:border-emerald-200 hover:shadow-xl hover:shadow-emerald-900/5 transition-all group bg-white"
                    >
                        <div className="flex justify-between items-start mb-4">
                            <div className="space-y-1">
                                <h4 className="text-lg font-black text-[#2D3A2D] group-hover:text-emerald-700 transition-colors uppercase tracking-tight">{recipe.name}</h4>
                                <div className="flex items-center gap-2">
                                    <div className="px-2 py-0.5 bg-slate-100 rounded text-[8px] font-black uppercase text-slate-500 tracking-wider">
                                        Hasil: {recipe.outputQuantity} {recipe.frozenVariant?.unit || 'pcs'}
                                    </div>
                                    <div className="px-2 py-0.5 bg-emerald-50 rounded text-[8px] font-black uppercase text-emerald-600 tracking-wider">
                                        {recipe.items.length} Bahan
                                    </div>
                                </div>
                            </div>
                            <button
                                onClick={() => {
                                    setEditingRecipe(recipe);
                                    setFormData({
                                        name: recipe.name,
                                        description: recipe.description || '',
                                        frozenVariantId: recipe.frozenVariantId,
                                        outputQuantity: recipe.outputQuantity,
                                        items: recipe.items.map((i: any) => ({
                                            ingredientId: i.ingredientId,
                                            quantity: Number(i.quantity),
                                            unit: i.unit || 'gram',
                                            note: i.note || ''
                                        }))
                                    });
                                }}
                                className="p-3 bg-slate-50 rounded-xl text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 transition-all"
                            >
                                <ChevronRight className="w-5 h-5" />
                            </button>
                        </div>

                        <div className="space-y-2 pt-4 border-t border-slate-50">
                            {recipe.items.slice(0, 3).map((item: any) => (
                                <div key={item.id} className="flex justify-between items-center text-[10px]">
                                    <span className="text-slate-500 font-bold">{item.ingredient.product.name}</span>
                                    <span className="text-[#8B7E66] font-black">{item.quantity} {item.unit || 'gram'}</span>
                                </div>
                            ))}
                            {recipe.items.length > 3 && (
                                <p className="text-[8px] text-slate-400 font-bold text-center pt-2">+{recipe.items.length - 3} bahan lainnya</p>
                            )}
                        </div>
                    </div>
                ))}

                {filteredRecipes.length === 0 && (
                    <div className="col-span-2 py-20 bg-slate-50/50 rounded-[3rem] border border-dashed border-slate-200 flex flex-col items-center justify-center space-y-4">
                        <Book className="w-12 h-12 text-slate-200" />
                        <p className="text-[10px] font-black uppercase tracking-widest text-[#8B7E66]">Belum ada resep yang terdaftar.</p>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import React, { useRef, useState } from 'react';
import { Upload, FileText, Loader2, AlertCircle, CheckCircle2 } from 'lucide-react';
import { toast } from 'sonner';
import { uploadSettlementReportAction } from '@/lib/actions/rasa-ibu/reconciliation';

interface SettlementUploaderProps {
    brandId: string;
    onUploadComplete?: () => void;
}

export default function SettlementUploader({ brandId, onUploadComplete }: SettlementUploaderProps) {
    const [isDragging, setIsDragging] = useState(false);
    const [isUploading, setIsUploading] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFile = async (file: File) => {
        if (!file.name.endsWith('.csv')) {
            toast.error('Mohon upload file .CSV ya Bunda');
            return;
        }

        setIsUploading(true);
        const formData = new FormData();
        formData.append('file', file);
        formData.append('platform', 'SHOPEE'); // Default for now

        try {
            const res = await uploadSettlementReportAction(brandId, formData);
            if (res.success) {
                toast.success(res.message);
                if (onUploadComplete) onUploadComplete();
            } else {
                toast.error('Gagal memproses file: ' + res.error);
            }
        } catch (error) {
            toast.error('Terjadi kesalahan saat upload');
        } finally {
            setIsUploading(false);
        }
    };

    const onDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        if (e.dataTransfer.files?.[0]) {
            handleFile(e.dataTransfer.files[0]);
        }
    };

    return (
        <div
            className={`
                relative border-2 border-dashed rounded-2xl p-8 text-center transition-all cursor-pointer
                ${isDragging ? 'border-emerald-500 bg-emerald-50' : 'border-slate-200 hover:border-emerald-400 hover:bg-emerald-50/30'}
                ${isUploading ? 'opacity-50 pointer-events-none' : ''}
            `}
            onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
            onDragLeave={() => setIsDragging(false)}
            onDrop={onDrop}
            onClick={() => fileInputRef.current?.click()}
        >
            <input
                type="file"
                ref={fileInputRef}
                className="hidden"
                accept=".csv"
                onChange={(e) => e.target.files?.[0] && handleFile(e.target.files[0])}
            />

            <div className="flex flex-col items-center gap-3">
                <div className="w-12 h-12 bg-white rounded-xl shadow-sm flex items-center justify-center text-emerald-600">
                    {isUploading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Upload className="w-6 h-6" />}
                </div>
                <div>
                    <h3 className="text-sm font-bold text-slate-800">
                        {isUploading ? 'Sedang Memproses...' : 'Upload Laporan Settlement'}
                    </h3>
                    <p className="text-xs text-slate-500 mt-1">
                        Drag & drop file CSV dari Shopee disini
                    </p>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { toast } from 'sonner';
import { Plus, Trash2, Loader2 } from 'lucide-react';
import ProductSelector from './ProductSelector';

interface BundleFormProps {
    brandId: string;
    campaignId: string;
    initialData?: any;
    onCancel: () => void;
    onSuccess: () => void;
}

export default function BundleForm({ brandId, campaignId, initialData, onCancel, onSuccess }: BundleFormProps) {
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        name: initialData?.name || '',
        description: initialData?.description || '',
        price: initialData?.price || 0,
        quota: initialData?.quota || 0,
        isActive: initialData?.isActive ?? true,
        items: initialData?.items?.map((item: any) => ({
            variantId: item.variantId,
            quantity: item.quantity,
            name: item.variant?.product?.name || 'Unknown Item'
        })) || []
    });

    const handleAddItem = (variant: any) => {
        if (formData.items.find((i: any) => i.variantId === variant.id)) {
            toast.error('Item sudah ada dalam bundle');
            return;
        }

        setFormData({
            ...formData,
            items: [...formData.items, {
                variantId: variant.id,
                quantity: 1,
                name: variant.product.name + (variant.name !== 'Default' ? ` (${variant.name})` : '')
            }]
        });
        setSearchQuery('');
        setProducts([]);
    };

    const handleRemoveItem = (index: number) => {
        const newItems = [...formData.items];
        newItems.splice(index, 1);
        setFormData({ ...formData, items: newItems });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (formData.items.length === 0) {
            toast.error('Bundle harus berisi minimal 1 item.');
            return;
        }

        setLoading(true);
        try {
            const res = await fetch(`/api/brands/${brandId}/campaigns/${campaignId}/bundles`, {
                method: initialData ? 'POST' : 'POST', // We use POST for both as upsert logic is in server action
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    ...formData,
                    id: initialData?.id
                })
            });

            if (!res.ok) throw new Error('Gagal menyimpan bundle');

            toast.success('Bundle berhasil disimpan');
            onSuccess();
        } catch (error: any) {
            toast.error(error.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label>Nama Paket (Bundle)</Label>
                    <Input
                        value={formData.name}
                        onChange={e => setFormData({ ...formData, name: e.target.value })}
                        placeholder="Contoh: Paket Kenyang Keluarga"
                        required
                    />
                </div>
                <div className="space-y-2">
                    <Label>Harga Paket (Rp)</Label>
                    <Input
                        type="number"
                        value={formData.price}
                        onChange={e => setFormData({ ...formData, price: Number(e.target.value) })}
                        required
                    />
                </div>
            </div>

            <div className="space-y-2">
                <Label>Deskripsi Singkat</Label>
                <Textarea
                    value={formData.description}
                    onChange={e => setFormData({ ...formData, description: e.target.value })}
                    placeholder="Apa isi paket ini?"
                />
            </div>

            <div className="space-y-4 border-t pt-4">
                <div className="flex justify-between items-center">
                    <Label className="text-lg font-bold">Isi Produk</Label>
                    <div className="relative w-64">
                        <ProductSelector
                            brandId={brandId}
                            onSelect={(product) => {
                                // Default to first variant or show selection? 
                                // Since Bundle needs specific variant, we might need to adjust ProductSelector or iterate variants here.
                                // For now, let's assume Bundle simply adds the main product or first variant as per current logic flow?
                                // Actually, current logic iterates `p.variants`. ProductSelector select `product`.

                                // Let's try to smart-add: Add all variants or prompt user? 
                                // To keep it simple and consistent: Add the first variant found.
                                if (product.variants && product.variants.length > 0) {
                                    handleAddItem({ ...product.variants[0], product: product });
                                } else {
                                    // Fallback if no variants loaded
                                    toast.error('Produk ini tidak memiliki varian.');
                                }
                            }}
                            placeholder="Cari produk..."
                        />
                    </div>
                </div>

                <div className="space-y-2 max-h-48 overflow-y-auto pr-2">
                    {formData.items.map((item, index) => (
                        <div key={item.variantId} className="flex items-center gap-3 bg-[#F9F7F2] p-3 rounded-xl border border-[#E5E1D8]">
                            <div className="flex-1">
                                <p className="text-sm font-bold text-[#1A241A]">{item.name}</p>
                            </div>
                            <div className="w-20">
                                <Input
                                    type="number"
                                    min="1"
                                    value={item.quantity}
                                    onChange={e => {
                                        const newItems = [...formData.items];
                                        newItems[index].quantity = Math.max(1, Number(e.target.value));
                                        setFormData({ ...formData, items: newItems });
                                    }}
                                    className="h-8 text-center"
                                />
                            </div>
                            <Button
                                type="button"
                                variant="ghost"
                                size="icon"
                                className="h-8 w-8 text-red-400 hover:text-red-600"
                                onClick={() => handleRemoveItem(index)}
                            >
                                <Trash2 className="h-4 w-4" />
                            </Button>
                        </div>
                    ))}
                    {formData.items.length === 0 && (
                        <div className="text-center py-6 text-gray-400 text-sm italic border-2 border-dashed rounded-xl">
                            Belum ada produk terpilih. Gunakan pencarian diatas.
                        </div>
                    )}
                </div>
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t">
                <Button type="button" variant="outline" onClick={onCancel} disabled={loading}>
                    Batal
                </Button>
                <Button type="submit" disabled={loading} className="bg-[#2D3A2D] hover:bg-[#1A241A]">
                    {loading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                    Simpan Paket
                </Button>
            </div>
        </form>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { ChevronLeft, Plus, Trash2, Loader2, Edit2 } from 'lucide-react';
import BundleForm from './BundleForm';
import { toast } from 'sonner';
import { useConfirm } from '@/components/ui/BrandConfirm';

interface BundleManagerProps {
    brandId: string;
    campaign: any;
    onClose: () => void;
}

export default function BundleManager({ brandId, campaign, onClose }: BundleManagerProps) {
    const [bundles, setBundles] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [view, setView] = useState<'LIST' | 'FORM'>('LIST');
    const [selectedBundle, setSelectedBundle] = useState<any>(null);
    const confirm = useConfirm();

    const fetchBundles = async () => {
        setLoading(true);
        try {
            const res = await fetch(`/api/brands/${brandId}/campaigns/${campaign.id}/bundles`);
            const data = await res.json();
            setBundles(data);
        } catch (error) {
            console.error('Failed to fetch bundles', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchBundles();
    }, [campaign.id]);

    const handleDelete = async (id: string) => {
        const confirmed = await confirm({
            title: 'Hapus Paket?',
            message: 'Bunda yakin ingin menghapus paket bundling ini?',
            confirmText: 'Ya, Hapus',
            cancelText: 'Batal',
            variant: 'danger'
        });

        if (!confirmed) return;
        try {
            const res = await fetch(`/api/brands/${brandId}/campaigns/${campaign.id}/bundles?id=${id}`, {
                method: 'DELETE'
            });
            if (res.ok) {
                toast.success('Paket dihapus');
                fetchBundles();
            }
        } catch (error) {
            toast.error('Gagal menghapus');
        }
    };

    if (view === 'FORM') {
        return (
            <div className="space-y-6">
                <div className="flex items-center gap-4 mb-2">
                    <Button variant="ghost" size="icon" onClick={() => setView('LIST')} className="rounded-full hover:bg-stone-100">
                        <ChevronLeft className="w-5 h-5 text-stone-600" />
                    </Button>
                    <div>
                        <h1 className="text-2xl font-bold tracking-tight text-[#1A241A]">
                            {selectedBundle ? 'Edit Paket' : 'Tambah Paket Baru'}
                        </h1>
                        <p className="text-[#8B7E66] text-sm">Kampanye: {campaign.name}</p>
                    </div>
                </div>
                <div className="bg-white rounded-[2rem] border border-[#E5E1D8] p-8 shadow-sm">
                    <BundleForm
                        brandId={brandId}
                        campaignId={campaign.id}
                        initialData={selectedBundle}
                        onCancel={() => setView('LIST')}
                        onSuccess={() => {
                            setView('LIST');
                            fetchBundles();
                        }}
                    />
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-4">
                    <Button variant="ghost" size="icon" onClick={onClose} className="rounded-full hover:bg-stone-100">
                        <ChevronLeft className="w-5 h-5 text-stone-600" />
                    </Button>
                    <div>
                        <h1 className="text-3xl font-bold tracking-tight text-[#1A241A]">Daftar Paket Bundling</h1>
                        <p className="text-[#8B7E66] text-sm">Kelola paket hemat untuk kampanye **{campaign.name}**.</p>
                    </div>
                </div>
                <Button onClick={() => { setSelectedBundle(null); setView('FORM'); }} className="bg-red-600 hover:bg-red-700 text-white rounded-xl">
