                    {bundles.map(bundle => (
                        <div key={bundle.id} className="border border-[#E5E1D8] rounded-[2rem] p-8 bg-white shadow-sm hover:shadow-xl transition-all relative group overflow-hidden">
                            {/* Decorative badge */}
                            <div className="absolute top-0 right-0 p-4">
