                                        <Trash2 className="w-4 h-4" />
                                    </Button>
                                </div>
                            </div>
                        </div>
                    ))}

                    {bundles.length === 0 && (
                        <div className="col-span-full py-24 text-center border-2 border-dashed border-[#E5E1D8] rounded-[3rem] bg-[#FDFBF7]">
                            <div className="w-20 h-20 bg-stone-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-stone-100">
                                <Plus className="w-10 h-10 text-stone-200" />
                            </div>
                            <p className="text-[#8B7E66] font-bold text-lg">Belum ada paket untuk kampanye ini.</p>
                            <p className="text-[#8B7E66]/60 text-sm max-w-xs mx-auto mt-1">Buat paket bundling pertama Anda untuk meningkatkan penjualan!</p>
                            <Button variant="outline" className="mt-6 rounded-xl border-stone-200" onClick={() => { setSelectedBundle(null); setView('FORM'); }}>
                                Tambah Sekarang
                            </Button>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { toast } from 'sonner';

interface CampaignFormProps {
    brandId: string;
    initialData?: any;
    onCancel: () => void;
    onSuccess: () => void;
}

export default function CampaignForm({ brandId, initialData, onCancel, onSuccess }: CampaignFormProps) {
    const [loading, setLoading] = useState(false);

    // Simple state form
    const [formData, setFormData] = useState({
        title: initialData?.title || '',
        slug: initialData?.slug || '',
        description: initialData?.description || '',
        startDate: initialData?.startDate ? new Date(initialData.startDate).toISOString().split('T')[0] : '',
        endDate: initialData?.endDate ? new Date(initialData.endDate).toISOString().split('T')[0] : '',
        isActive: initialData?.isActive ?? false,
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);

        try {
            const res = await fetch(`/api/brands/${brandId}/campaigns`, {
                method: initialData ? 'PUT' : 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    ...formData,
                    id: initialData?.id,
                    brandId
                })
            });

            console.log('[CampaignForm] Sending payload:', { ...formData, id: initialData?.id, brandId });

            const result = await res.json();

            if (!res.ok) {
                if (result.error?.includes('Unique constraint') && result.error?.includes('slug')) {
                    throw new Error('URL (Slug) sudah digunakan. Silakan gunakan URL lain.');
                }
                throw new Error(result.error || 'Failed to save');
            }

            toast.success('Campaign saved');
            onSuccess();
        } catch (error: any) {
            console.error(error);
            toast.error(error.message || 'Gagal menyimpan campaign');
        } finally {
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-6 bg-white p-6 rounded-xl shadow-sm border max-w-2xl mx-auto mt-6">
            <h2 className="text-2xl font-bold text-[#1A241A] mb-4">
                {initialData ? 'Edit Campaign' : 'Buat Campaign Baru'}
            </h2>

            <div className="space-y-2">
                <Label>Judul Campaign</Label>
                <Input
                    value={formData.title}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    required
                    placeholder="Contoh: Pahlawan Gizi 2024"
                />
            </div>

            <div className="space-y-2">
                <Label>Slug (URL)</Label>
                <Input
                    value={formData.slug}
                    onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                    required
                    placeholder="pahlawan-gizi"
                />
            </div>

            <div className="space-y-2">
                <Label>Deskripsi</Label>
                <Textarea
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    placeholder="Ceritakan tentang campaign ini..."
                />
            </div>

            <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                    <Label>Tanggal Mulai</Label>
                    <Input
                        type="date"
                        value={formData.startDate}
                        onChange={(e) => setFormData({ ...formData, startDate: e.target.value })}
                        required
                    />
                </div>
                <div className="space-y-2">
                    <Label>Tanggal Selesai</Label>
                    <Input
                        type="date"
                        value={formData.endDate}
                        onChange={(e) => setFormData({ ...formData, endDate: e.target.value })}
                        required
                    />
                </div>
            </div>

            <div className="flex items-center gap-2 pt-4">
                <Switch
                    checked={formData.isActive}
                    onCheckedChange={(c) => setFormData({ ...formData, isActive: c })}
                />
                <span className="text-sm font-bold">{formData.isActive ? 'PUBLIK (AKTIF)' : 'DRAFT (NON-AKTIF)'}</span>
            </div>

            <div className="flex justify-end gap-4 pt-4 border-t border-gray-100">
                <Button type="button" variant="outline" onClick={onCancel}>
                    Batal
                </Button>
                <Button type="submit" disabled={loading} className="bg-[#2D3A2D] hover:bg-[#1A241A]">
                    {loading ? 'Menyimpan...' : 'Simpan Campaign'}
                </Button>
            </div>
        </form>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Calendar, Loader2, Plus, Trash2, ShoppingBasket, Search, Edit } from 'lucide-react';
import { toast } from 'sonner';
import { useConfirm } from '@/components/ui/BrandConfirm';
import Link from 'next/link';

interface Campaign {
    id: string;
    title: string;
    description: string | null;
    startDate: string;
    endDate: string;
    isActive: boolean;
    bundles: any[];
}

interface CampaignManagerProps {
    brandId: string;
    onClose: () => void;
    onCreate: () => void;
    onEdit: (campaign: any) => void;
    onManageBundles: (campaign: any) => void;
}

export default function CampaignManager({ brandId, onClose, onCreate, onEdit, onManageBundles }: CampaignManagerProps) {
    const [campaigns, setCampaigns] = useState<Campaign[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const confirm = useConfirm();

    const filteredCampaigns = campaigns.filter(c =>
        c.title.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const fetchCampaigns = async () => {
        setLoading(true);
        try {
            const res = await fetch(`/api/brands/${brandId}/campaigns`);
            const data = await res.json();
            setCampaigns(data);
        } catch (error) {
            console.error('Failed to fetch campaigns', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchCampaigns();
    }, [brandId]);

    const handleDelete = async (id: string) => {
        const confirmed = await confirm({
            title: 'Hapus Kampanye?',
            message: 'Semua paket (bundles) di dalam kampanye ini juga akan terhapus. Bunda yakin?',
            confirmText: 'Ya, Hapus',
            cancelText: 'Batal',
            variant: 'danger'
        });

        if (!confirmed) return;

        try {
            const res = await fetch(`/api/brands/${brandId}/campaigns/${id}`, {
                method: 'DELETE'
            });
            if (res.ok) {
                toast.success('Kampanye berhasil dihapus');
                fetchCampaigns();
            } else {
                throw new Error('Gagal menghapus');
            }
        } catch (error: any) {
            toast.error(error.message);
        }
    };

    if (loading) {
        return <div className="p-12 flex justify-center"><Loader2 className="w-8 h-8 animate-spin text-gray-400" /></div>;
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight text-[#1A241A]">Manage Campaigns</h1>
                    <p className="text-[#8B7E66]">
                        Kelola program kampanye bundling (contoh: "Pahlawan Gizi").
                    </p>
                </div>
                <div className="flex gap-3">
                    <Button variant="outline" onClick={onClose}>
                        Kembali
                    </Button>
                    <Button
                        onClick={onCreate}
                        className="bg-[#2D3A2D] hover:bg-[#1A241A]"
                    >
                        + Buat Campaign Baru
                    </Button>
                </div>
            </div>

            <div className="bg-white border boundary-[#E5E1D8] rounded-[2rem] p-6 shadow-sm">
                {/* Search & Filter */}
                <div className="mb-6 flex items-center justify-between">
                    <div className="relative w-full max-w-sm">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                        <Input
                            placeholder="Cari campaign..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            className="pl-9 rounded-xl border-[#E5E1D8]"
                        />
                    </div>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-left text-sm">
                        <thead>
                            <tr className="border-b border-[#E5E1D8]">
                                <th className="pb-3 font-bold text-[#1A241A] pl-4">Nama Campaign</th>
                                <th className="pb-3 font-bold text-[#1A241A]">Periode</th>
                                <th className="pb-3 font-bold text-[#1A241A]">Paket (Bundles)</th>
                                <th className="pb-3 font-bold text-[#1A241A]">Status</th>
                                <th className="pb-3 font-bold text-[#1A241A] text-right pr-4">Aksi</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-[#E5E1D8]">
                            {filteredCampaigns.length === 0 ? (
                                <tr>
                                    <td colSpan={5} className="py-8 text-center text-gray-400 italic">
                                        Tidak ada data ditemukan.
                                    </td>
                                </tr>
                            ) : (
                                filteredCampaigns.map(campaign => (
                                    <tr key={campaign.id} className="group hover:bg-stone-50 transition-colors">
                                        <td className="py-4 pl-4">
                                            <div className="font-bold text-[#1A241A]">{campaign.title}</div>
                                            {campaign.description && (
                                                <div className="text-[10px] text-gray-500 max-w-[200px] truncate">{campaign.description}</div>
                                            )}
                                        </td>
                                        <td className="py-4 text-[#8B7E66]">
                                            <div className="flex items-center gap-2 text-xs">
                                                <Calendar className="w-3 h-3" />
                                                {new Date(campaign.startDate).toLocaleDateString()} - {new Date(campaign.endDate).toLocaleDateString()}
                                            </div>
                                        </td>
                                        <td className="py-4">
                                            <div className="flex flex-col gap-1">
                                                <div className="flex items-center gap-1.5 font-bold text-[#1A241A]">
                                                    <ShoppingBasket className="w-3.5 h-3.5 text-amber-600" />
                                                    {campaign.bundles?.length || 0} Paket
                                                </div>
                                                <Button
                                                    onClick={() => onManageBundles(campaign)}
                                                    variant="link"
                                                    className="h-auto p-0 text-[10px] text-amber-600 hover:text-amber-700 justify-start"
                                                >
                                                    Kelola Isi Paket &rarr;
                                                </Button>
                                            </div>
                                        </td>
                                        <td className="py-4">
                                            <span className={`text-[10px] px-2 py-1 round-full font-bold uppercase tracking-wider ${campaign.isActive ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>
                                                {campaign.isActive ? 'AKTIF' : 'NON-AKTIF'}
                                            </span>
                                        </td>
                                        <td className="py-4 pr-4 text-right">
                                            <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <Button variant="ghost" size="sm" className="h-8 w-8 p-0 text-stone-500 hover:text-[#1A241A]" onClick={() => onEdit(campaign)}>
                                                    <Edit className="w-4 h-4" />
                                                </Button>
                                                <Button variant="ghost" size="sm" className="h-8 w-8 p-0 text-red-400 hover:text-red-600 hover:bg-red-50" onClick={() => handleDelete(campaign.id)}>
                                                    <Trash2 className="w-4 h-4" />
                                                </Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Timer, Zap } from 'lucide-react';
import { useRouter } from 'next/navigation';

interface FlashSaleBannerProps {
    activeFlashSale: any;
}

export default function FlashSaleBanner({ activeFlashSale }: FlashSaleBannerProps) {
    const [timeLeft, setTimeLeft] = useState('');
    const router = useRouter();

    useEffect(() => {
        console.log('[FlashSaleBanner] Active Data:', activeFlashSale);
        if (!activeFlashSale) return;

        const isUpcoming = activeFlashSale.status === 'UPCOMING';
        const timeToTarget = isUpcoming ? activeFlashSale.startTime : activeFlashSale.endTime;

        if (!timeToTarget) return;

        // Parse endTime (assuming HH:mm format for daily flash sale or specific Date)
        // Adjust logic based on your actual data structure in FlashSaleService
        // For now, assuming generic target time or just showing the time string if simple

        // If endTime is full ISO string
        // const target = new Date(activeFlashSale.endDate || new Date().setHours(23, 59, 59));

        // Let's assume for now we just show the static info or simple countdown if possible
        // Ideally we need a real countdown. 

        const calculateTimeLeft = () => {
            const now = new Date();
            const target = new Date();

            if (timeToTarget) {
                const [hours, minutes] = timeToTarget.split(':').map(Number);
                target.setHours(hours, minutes, 0, 0);
            } else {
                target.setHours(23, 59, 59, 999);
            }

            const diff = target.getTime() - now.getTime();
            if (diff <= 0) return "00:00:00";

            const hours = Math.floor(diff / (1000 * 60 * 60));
            const minutes = Math.floor((diff / (1000 * 60)) % 60);
            const seconds = Math.floor((diff / 1000) % 60);

            return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
        };

        const timer = setInterval(() => {
            setTimeLeft(calculateTimeLeft());
        }, 1000);

        // Initial call
        setTimeLeft(calculateTimeLeft());

        return () => clearInterval(timer);
    }, [activeFlashSale]);

    if (!activeFlashSale) return null;

    const isUpcoming = activeFlashSale.status === 'UPCOMING';
    const bgColor = isUpcoming ? 'bg-gradient-to-r from-amber-500 to-amber-600' : 'bg-gradient-to-r from-orange-600 to-red-600';
    const mainText = isUpcoming ? 'Flash Sale Segera Hadir!' : 'Flash Sale Sedang Berlangsung!';
    const timeLabel = isUpcoming ? 'Dimulai Dalam' : 'Berakhir Dalam';

    return (
        <div
            className={`relative w-full z-[9999] ${bgColor} text-white py-2 px-4 shadow-lg cursor-pointer transition-colors duration-500`}
            onClick={() => {
                // Scroll to Flash Sale section or Product section
                const el = document.getElementById('menu') || document.getElementById('flash-sale-section');
                if (el) el.scrollIntoView({ behavior: 'smooth' });
            }}
        >
            <div className="container mx-auto max-w-7xl flex items-center justify-between text-[10px] md:text-sm font-bold tracking-wider uppercase">
                <div className="flex items-center gap-2">
                    <Zap className={`w-4 h-4 ${isUpcoming ? 'text-white' : 'fill-yellow-300 text-yellow-300'} animate-pulse`} />
                    <span className="hidden sm:inline">{mainText}</span>
                    <span className="sm:hidden">{isUpcoming ? 'Segera!' : 'Live!'}</span>
                </div>

                <div className="flex items-center gap-2 md:gap-4">
                    <span className="hidden md:inline bg-white/20 px-2 py-0.5 rounded">
                        Diskon {activeFlashSale.discountPercentage}% {activeFlashSale.targetType === 'SPECIFIC' ? 'Item Pilihan' : 'Semua Menu'}
                    </span>
                    <div className="flex items-center gap-1.5 font-black font-mono bg-black/20 px-3 py-1 rounded-lg">
                        <span className="text-[8px] md:text-[10px] opacity-70 hidden xs:inline">{timeLabel}</span>
                        <Timer className="w-3 h-3" />
                        <span>{timeLeft}</span>
                    </div>
                </div>
            </div>
        </div>
    );
}

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { toast } from 'sonner';
import { ChevronLeft, X, Plus } from 'lucide-react';
import ProductSelector from './ProductSelector';


interface FlashSaleFormProps {
    brandId: string;
    initialData?: any;
    onSuccess?: () => void;
}

export default function FlashSaleForm({ brandId, initialData, onSuccess }: FlashSaleFormProps) {
    const router = useRouter();
    const [loading, setLoading] = useState(false);

    // Simple state form for speed (can upgrade to zod later)
    const [formData, setFormData] = useState({
        id: initialData?.id || '',
        name: initialData?.name || '',
        // description removed as per schema
        discountPercentage: initialData?.discountPercentage || 0,
        startTime: initialData?.startTime || '12:00',
        endTime: initialData?.endTime || '13:00',
        startDate: initialData?.startDate ? new Date(initialData.startDate).toISOString().split('T')[0] : '',
        endDate: initialData?.endDate ? new Date(initialData.endDate).toISOString().split('T')[0] : '',
        minPurchaseAmount: initialData?.minPurchaseAmount || 0,
        targetType: initialData?.targetType || 'ALL',
        targetIds: initialData?.targetIds || [],
        isActive: initialData?.isActive ?? true,
    });

    const [targetMeta, setTargetMeta] = useState<Record<string, string>>({});


    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);

        try {
            const payload = {
                ...formData,
                discountPercentage: Number(formData.discountPercentage) || 0,
                minPurchaseAmount: Number(formData.minPurchaseAmount) || 0,
                id: initialData?.id // Include ID if updating
            };

            console.log('[FlashSaleForm] Sending payload:', payload);

            const res = await fetch(`/api/brands/${brandId}/flash-sale`, {
                method: initialData ? 'PUT' : 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });

            const result = await res.json();

            if (!res.ok) throw new Error(result.error || 'Failed to save');

            toast.success('Flash Sale updated');
            if (onSuccess) onSuccess();
            router.refresh();
        } catch (error: any) {
            console.error(error);
            toast.error(error.message || 'Gagal menyimpan konfigurasi');
        } finally {
            setLoading(false);
        }
    };

    return (
        <form onSubmit={handleSubmit} className="space-y-8 bg-white p-6 rounded-xl shadow-sm border">

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                    <Label>Nama Campaign</Label>
                    <Input
                        value={formData.name}
                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                        required
                    />
                </div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="space-y-2">
                    <Label className="text-orange-900 font-bold">Cakupan Flash Sale</Label>
                    <div className="relative">
                        <select
                            value={formData.targetType}
                            onChange={(e) => setFormData({ ...formData, targetType: e.target.value })}
                            className="w-full h-10 px-3 rounded-xl border-[#E5E1D8] bg-white text-sm focus:ring-2 focus:ring-orange-500 appearance-none shadow-sm"
                        >
                            <option value="ALL">Semua Produk (Seluruh Toko)</option>
                            <option value="CATEGORY">Kategori Spesifik</option>
                            <option value="SPECIFIC">Produk Tertentu Sahaja</option>
                        </select>
                        <div className="absolute right-3 top-3 pointer-events-none text-stone-400">
                            <ChevronLeft className="w-4 h-4 rotate-[270deg]" />
                        </div>
                    </div>
                </div>

                {formData.targetType === 'SPECIFIC' && (
                    <div className="col-span-1 md:col-span-2 space-y-4 bg-orange-50/30 p-4 rounded-2xl border border-orange-100">
                        <Label className="text-orange-800 font-bold">Pilih Produk (Dumped Flash Sale)</Label>

                        <ProductSelector
                            brandId={brandId}
                            onSelect={(product) => {
                                if (!formData.targetIds.includes(product.id)) {
                                    setFormData({
                                        ...formData,
                                        targetIds: [...formData.targetIds, product.id]
                                    });
                                    // Also meta storage for names
                                    setTargetMeta({
                                        ...targetMeta,
                                        [product.id]: product.name
                                    });
                                }
                            }}
                            placeholder="Cari & Pilih Produk..."
                        />

                        {/* Selected Products List */}
                        <div className="flex flex-wrap gap-2">
                            {formData.targetIds.map(id => (
                                <div key={id} className="flex items-center gap-2 bg-white border border-orange-200 px-3 py-1.5 rounded-full shadow-sm animate-in fade-in zoom-in-95">
                                    <span className="text-xs font-bold text-orange-700">{targetMeta[id] || id}</span>
                                    <button
                                        type="button"
                                        onClick={() => setFormData({
                                            ...formData,
                                            targetIds: formData.targetIds.filter(i => i !== id)
                                        })}
                                        className="text-orange-400 hover:text-orange-600"
                                    >
                                        <X className="w-3.5 h-3.5" />
                                    </button>
                                </div>
                            ))}
                            {formData.targetIds.length === 0 && (
                                <p className="text-xs text-orange-400 italic">Belum ada produk dipilih.</p>
                            )}
                        </div>
                    </div>
                )}
                <div className="space-y-2">
                    <Label>Diskon (%)</Label>
                    <Input
                        type="number"
                        min="0"
                        max="100"
                        value={formData.discountPercentage}
                        onChange={(e) => setFormData({ ...formData, discountPercentage: Number(e.target.value) })}
                        required
                    />
                </div>
                <div className="space-y-2">
                    <Label>Min. Belanja</Label>
                    <Input
                        type="number"
                        value={formData.minPurchaseAmount}
                        onChange={(e) => setFormData({ ...formData, minPurchaseAmount: Number(e.target.value) })}
                    />
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                    <Label>Tanggal Mulai</Label>
                    <div className="flex gap-2">
                        <Input
                            type="date"
                            className="flex-1"
                            value={formData.startDate}
                            onChange={(e) => setFormData({ ...formData, startDate: e.target.value })}
                            required
                        />
                        <Input
                            type="time"
                            className="w-32"
                            value={formData.startTime}
                            onChange={(e) => setFormData({ ...formData, startTime: e.target.value })}
                            required
                        />
                    </div>
                </div>
                <div className="space-y-2">
                    <Label>Tanggal Selesai</Label>
                    <div className="flex gap-2">
                        <Input
                            type="date"
                            className="flex-1"
                            value={formData.endDate}
                            onChange={(e) => setFormData({ ...formData, endDate: e.target.value })}
                            required
                        />
                        <Input
                            type="time"
                            className="w-32"
                            value={formData.endTime}
                            onChange={(e) => setFormData({ ...formData, endTime: e.target.value })}
                            required
                        />
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-4 pt-4 border-t">
                <div className="flex items-center gap-2">
                    <Switch
                        checked={formData.isActive}
                        onCheckedChange={(c) => setFormData({ ...formData, isActive: c })}
                    />
                    <span className="text-sm font-bold">{formData.isActive ? 'AKTIF' : 'NON-AKTIF'}</span>
                </div>

                <div className="flex-1"></div>

                <Button type="submit" disabled={loading}>
                    {loading ? 'Menyimpan...' : 'Simpan Konfigurasi'}
                </Button>
            </div>

        </form>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { ChevronLeft, Loader2, Plus, Calendar, Clock, Trash2, Search, Edit } from 'lucide-react';
import FlashSaleForm from '@/components/marketing/FlashSaleForm';
import { toast } from 'sonner';
import { useConfirm } from '@/components/ui/BrandConfirm';

export default function FlashSaleManager({ brandId, onClose }: { brandId: string, onClose: () => void }) {
    const [configs, setConfigs] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [view, setView] = useState<'LIST' | 'FORM'>('LIST');
    const [selectedConfig, setSelectedConfig] = useState<any>(null);
    const [searchTerm, setSearchTerm] = useState('');
    const confirm = useConfirm();

    const filteredConfigs = configs.filter(c =>
        c.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const fetchConfigs = async () => {
        setLoading(true);
        try {
            const res = await fetch(`/api/brands/${brandId}/flash-sale/list`); // Need to create this or update route
            // For now, let's use the main route which should ideally return a list if optimized
            const mainRes = await fetch(`/api/brands/${brandId}/flash-sale`);
            const data = await mainRes.json();
            setConfigs(Array.isArray(data) ? data : (data ? [data] : []));
        } catch (error) {
            console.error('Failed to fetch flash sale configs', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchConfigs();
    }, [brandId]);

    const handleDelete = async (id: string) => {
        const confirmed = await confirm({
            title: 'Hapus Flash Sale?',
            message: 'Konfigurasi Flash Sale ini akan dihapus permanen. Lanjutkan?',
            confirmText: 'Ya, Hapus',
            cancelText: 'Batal',
            variant: 'danger'
        });

        if (!confirmed) return;

        try {
            const res = await fetch(`/api/brands/${brandId}/flash-sale/${id}`, {
                method: 'DELETE'
            });
            if (res.ok) {
                toast.success('Konfigurasi dihapus');
                fetchConfigs();
            } else {
                throw new Error('Gagal menghapus');
            }
        } catch (error: any) {
            toast.error(error.message);
        }
    };

    if (view === 'FORM') {
        return (
            <div className="space-y-6">
                <div className="flex items-center gap-4 mb-2">
                    <Button variant="ghost" size="icon" onClick={() => setView('LIST')} className="rounded-full hover:bg-stone-100">
                        <ChevronLeft className="w-5 h-5 text-stone-600" />
                    </Button>
                    <div>
                        <h1 className="text-3xl font-bold tracking-tight text-[#1A241A]">
                            {selectedConfig ? 'Edit Flash Sale' : 'Buat Flash Sale Baru'}
                        </h1>
                    </div>
                </div>
                <div className="bg-white rounded-[2rem] border border-[#E5E1D8] p-8 shadow-sm">
                    <FlashSaleForm
                        brandId={brandId}
                        initialData={selectedConfig}
                        onSuccess={() => {
                            setView('LIST');
                            fetchConfigs();
                        }}
                    />
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-4">
                    <Button variant="ghost" size="icon" onClick={onClose} className="rounded-full hover:bg-stone-100">
                        <ChevronLeft className="w-5 h-5 text-stone-600" />
                    </Button>
                    <div>
                        <h1 className="text-3xl font-bold tracking-tight text-[#1A241A]">Flash Sale Manager</h1>
                        <p className="text-[#8B7E66] text-sm">Kelola jadwal promo Flash Sale Anda.</p>
                    </div>
                </div>
                <Button onClick={() => { setSelectedConfig(null); setView('FORM'); }} className="bg-[#2D3A2D] hover:bg-[#1A241A]">
                    <Plus className="w-4 h-4 mr-2" /> Buat Baru
                </Button>
            </div>

            {loading ? (
                <div className="p-12 flex justify-center"><Loader2 className="w-8 h-8 animate-spin text-gray-400" /></div>
            ) : (
                <div className="bg-white border boundary-[#E5E1D8] rounded-[2rem] p-6 shadow-sm">
                    {/* Search & Filter */}
                    <div className="mb-6 flex items-center justify-between">
                        <div className="relative w-full max-w-sm">
                            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
                            <Input
                                placeholder="Cari flash sale..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="pl-9 rounded-xl border-[#E5E1D8]"
                            />
                        </div>
                    </div>

                    <div className="overflow-x-auto">
                        <table className="w-full text-left text-sm">
                            <thead>
                                <tr className="border-b border-[#E5E1D8]">
                                    <th className="pb-3 font-bold text-[#1A241A] pl-4">Nama Campaign</th>
                                    <th className="pb-3 font-bold text-[#1A241A]">Jadwal</th>
                                    <th className="pb-3 font-bold text-[#1A241A]">Diskon</th>
                                    <th className="pb-3 font-bold text-[#1A241A]">Status</th>
                                    <th className="pb-3 font-bold text-[#1A241A] text-right pr-4">Aksi</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-[#E5E1D8]">
                                {filteredConfigs.length === 0 ? (
                                    <tr>
                                        <td colSpan={5} className="py-8 text-center text-gray-400 italic">
                                            Tidak ada data ditemukan.
                                        </td>
                                    </tr>
                                ) : (
                                    filteredConfigs.map(config => (
                                        <tr key={config.id} className="group hover:bg-stone-50 transition-colors">
                                            <td className="py-4 pl-4 font-medium text-[#1A241A]">
                                                {config.name}
                                                <div className="text-[10px] text-gray-500 font-normal mt-0.5">
                                                    Target: {config.targetType || 'ALL'}
                                                </div>
                                            </td>
                                            <td className="py-4 text-[#8B7E66]">
                                                <div className="flex flex-col gap-1 text-xs">
                                                    <span className="flex items-center gap-1">
                                                        <Calendar className="w-3 h-3" />
                                                        {config.startDate ? new Date(config.startDate).toLocaleDateString() : 'N/A'} - {config.endDate ? new Date(config.endDate).toLocaleDateString() : 'N/A'}
                                                    </span>
                                                    <span className="flex items-center gap-1 text-stone-400">
                                                        <Clock className="w-3 h-3" />
                                                        {config.startTime} - {config.endTime}
                                                    </span>
                                                </div>
                                            </td>
                                            <td className="py-4 font-bold text-orange-600">
                                                {config.discountPercentage}% <span className="text-[10px] text-gray-400 font-normal">OFF</span>
                                            </td>
                                            <td className="py-4">
                                                <span className={`text-[10px] px-2 py-1.5 rounded-full font-bold uppercase tracking-wider ${config.isActive ? 'bg-orange-100 text-orange-700' : 'bg-gray-100 text-gray-500'}`}>
                                                    {config.isActive ? 'LIVE' : 'OFF'}
                                                </span>
                                            </td>
                                            <td className="py-4 pr-4 text-right">
                                                <div className="flex justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <Button variant="ghost" size="sm" className="h-8 w-8 p-0 text-stone-500 hover:text-[#1A241A]" onClick={() => { setSelectedConfig(config); setView('FORM'); }}>
                                                        <Edit className="w-4 h-4" />
                                                    </Button>
                                                    <Button variant="ghost" size="sm" className="h-8 w-8 p-0 text-red-400 hover:text-red-600 hover:bg-red-50" onClick={() => handleDelete(config.id)}>
                                                        <Trash2 className="w-4 h-4" />
                                                    </Button>
                                                </div>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { getMarketingAnalyticsAction } from '@/lib/actions/commerce/marketingAnalytics';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

export default function MarketingAnalyticsDashboard({ brandId }: { brandId: string }) {
    const [data, setData] = useState<any>(null);

    useEffect(() => {
        getMarketingAnalyticsAction(brandId).then(setData);
