'use client';

import { useEffect, useState } from 'react';
import { AlertCircle, X, Loader2 } from 'lucide-react';

interface ConfirmationModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: () => Promise<void> | void;
    title: string;
    message: string;
    confirmText?: string;
    cancelText?: string;
    variant?: 'danger' | 'warning' | 'info';
    isLoading?: boolean;
}

export default function ConfirmationModal({
    isOpen,
    onClose,
    onConfirm,
    title,
    message,
    confirmText = 'Confirm',
    cancelText = 'Cancel',
    variant = 'danger',
    isLoading = false
}: ConfirmationModalProps) {
    const [isAnimating, setIsAnimating] = useState(false);

    useEffect(() => {
        if (isOpen) setIsAnimating(true);
    }, [isOpen]);

    if (!isOpen && !isAnimating) return null;

    const variantStyles = {
        danger: 'bg-red-600 hover:bg-red-700 focus:ring-red-500',
        warning: 'bg-amber-500 hover:bg-amber-600 focus:ring-amber-500',
        info: 'bg-blue-600 hover:bg-blue-700 focus:ring-blue-500',
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
            {/* Backdrop */}
            <div
                className={`absolute inset-0 bg-black/50 backdrop-blur-sm transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0'}`}
                onClick={!isLoading ? onClose : undefined}
            />

            {/* Modal Content */}
            <div
                className={`relative bg-white rounded-xl shadow-2xl w-full max-w-sm overflow-hidden transform transition-all duration-300 ${isOpen ? 'scale-100 opacity-100 translate-y-0' : 'scale-95 opacity-0 translate-y-4'}`}
                onTransitionEnd={() => !isOpen && setIsAnimating(false)}
            >
                <div className="p-6">
                    <div className="flex items-start gap-4">
                        <div className={`p-3 rounded-full flex-shrink-0 ${variant === 'danger' ? 'bg-red-100 text-red-600' : 'bg-amber-100 text-amber-600'}`}>
                            <AlertCircle className="w-6 h-6" />
                        </div>
                        <div className="div">
                            <h3 className="text-lg font-semibold text-stone-900 mb-2">
                                {title}
                            </h3>
                            <p className="text-stone-500 text-sm leading-relaxed">
                                {message}
                            </p>
                        </div>
                    </div>
                </div>

                <div className="bg-stone-50 px-6 py-4 flex gap-3 justify-end border-t border-stone-100">
                    <button
                        onClick={onClose}
                        disabled={isLoading}
                        className="px-4 py-2 text-sm font-medium text-stone-700 bg-white border border-stone-300 rounded-lg hover:bg-stone-50 focus:outline-none focus:ring-2 focus:ring-stone-200 disabled:opacity-50"
                    >
                        {cancelText}
                    </button>
                    <button
                        onClick={onConfirm}
                        disabled={isLoading}
                        className={`px-4 py-2 text-sm font-medium text-white rounded-lg focus:outline-none focus:ring-2 focus:ring-offset-2 flex items-center gap-2 disabled:opacity-75 ${variantStyles[variant]}`}
                    >
                        {isLoading && <Loader2 className="w-4 h-4 animate-spin" />}
                        {confirmText}
                    </button>
                </div>

                {!isLoading && (
                    <button
                        onClick={onClose}
                        className="absolute top-4 right-4 p-1 text-stone-400 hover:text-stone-600 rounded-lg transition-colors"
                    >
                        <X className="w-5 h-5" />
                    </button>
                )}
            </div>
        </div>
    );
}

'use client';

import React, { useEffect, useState } from 'react';
import { Zap, Clock } from 'lucide-react';
import { checkFlashSaleAction } from '@/lib/actions/commerce/flashSale';

export default function FlashSaleBanner() {
    const [activeSale, setActiveSale] = useState<any>(null);
    const [isVisible, setIsVisible] = useState(false);

    useEffect(() => {
        const fetchSale = async () => {
            try {
                const sale = await checkFlashSaleAction('rasa-ibu');
                if (sale) {
                    setActiveSale(sale);
                    setIsVisible(true);
                }
            } catch (error) {
                console.error('Failed to fetch flash sale', error);
            }
        };
        fetchSale();

        // Check every 5 minutes
        const interval = setInterval(fetchSale, 5 * 60 * 1000);
        return () => clearInterval(interval);
    }, []);

    if (!activeSale || !isVisible) return null;

    return (
        <div
            className={`fixed top-0 inset-x-0 z-[60] bg-[#BD302D] text-white overflow-hidden shadow-lg transition-transform duration-500 ease-in-out`}
        >
            <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/food.png')]"></div>

            <div className="max-w-7xl mx-auto px-4 py-3 flex items-center justify-between relative z-10">
                <div className="flex items-center gap-4">
                    <div className="bg-white/20 p-2 rounded-full animate-pulse">
                        <Zap className="w-5 h-5 text-yellow-300 fill-current" />
                    </div>
                    <div>
                        <p className="font-bold text-sm md:text-base leading-tight">
                            {activeSale.name} <span className="text-yellow-300 font-black text-lg">DISKON {activeSale.discount}%</span>
                        </p>
                        <p className="text-xs text-white/80">
                            Berlaku untuk Menu Pilihan!
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-4">
                    <div className="hidden md:flex items-center gap-2 bg-black/20 px-3 py-1 rounded-lg">
                        <Clock className="w-4 h-4 text-white/70" />
                        <span className="font-mono font-bold text-yellow-300">
                            Hingga {activeSale.endTime}
                        </span>
                    </div>
                    <button
                        onClick={() => setIsVisible(false)}
                        className="bg-white/10 hover:bg-white/20 p-1 rounded-full transition-colors"
                    >
                        <span className="sr-only">Tutup</span>
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                    </button>
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { Upload, X, Loader2, Image as ImageIcon } from 'lucide-react';
import { toast } from 'sonner';

interface ImageUploadProps {
    value: string;
    onChange: (url: string) => void;
    label?: string;
    disabled?: boolean;
}

export default function ImageUpload({ value, onChange, label = "Image", disabled }: ImageUploadProps) {
    const [isUploading, setIsUploading] = useState(false);

    const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        try {
            setIsUploading(true);
            const formData = new FormData();
            formData.append('file', file);

            const res = await fetch('/api/upload', {
                method: 'POST',
                body: formData
            });

            if (!res.ok) throw new Error('Upload failed');

            const data = await res.json();
            onChange(data.url);
            toast.success('Image uploaded!');
        } catch (error) {
            toast.error('Failed to upload image');
            console.error(error);
        } finally {
            setIsUploading(false);
        }
    };

    return (
        <div className="space-y-2">
            <span className="block text-xs font-bold uppercase text-gray-500 mb-2">{label}</span>

            {value ? (
                <div className="relative aspect-video w-full rounded-xl overflow-hidden border border-gray-200 group">
                    <img
                        src={value}
                        alt="Upload"
                        className="object-cover w-full h-full"
                    />
                    <button
                        onClick={() => onChange('')}
                        disabled={disabled}
                        className="absolute top-2 right-2 p-1 bg-red-500 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity disabled:opacity-0"
                    >
                        <X className="w-4 h-4" />
                    </button>
                    <div className="absolute bottom-2 left-2 bg-black/50 text-white text-[10px] px-2 py-1 rounded">
                        {value}
                    </div>
                </div>
