        const user = await prisma.user.findUnique({
            where: { id: userId },
            select: { email: true }
        });

        if (!user?.email) {
            return [];
        }

        const orders = await prisma.order.findMany({
            where: {
                customerEmail: user.email
            },
            include: {
                orderItems: {
                    include: {
                        frozenVariant: {
                            include: {
                                product: true
                            }
                        }
                    }
                },
                brand: {
                    select: {
                        name: true,
                        slug: true
                    }
                }
            },
            orderBy: {
                createdAt: 'desc'
            },
            take: 50 // Limit to last 50 orders
        });

        return orders;
    } catch (error) {
        console.error('[getUserOrdersAction] Error:', error);
        return [];
    }
}

