export async function deleteInventoryCategory(id: string) {
    try {
        const productsCount = await prisma.frozenProduct.count({
            where: { inventoryCategoryId: id } as any
        });

        if (productsCount > 0) {
            return {
                success: false,
                error: `Tidak bisa menghapus kategori ini karena masih digunakan oleh ${productsCount} item.`
            };
        }

        await (prisma as any).inventoryCategory.delete({ where: { id } });
        revalidatePath('/dashboard/rasa-ibu');
        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message };
    }
}

'use server';

import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';
import { emailAlertService } from '@/lib/services/EmailAlertService';

interface ContactMessageData {
    name: string;
    phone: string;
    message: string;
    targetEmail: string;
}

/**
 * Action to handle contact form submissions for Rasa Ibu.
 * Integrates with Intelligence Hub for tracking.
 */
export async function sendContactMessageAction(data: ContactMessageData) {
    try {
        console.log('[Contact Form Submission]', data);

        // 1. Find Rasa Ibu Brand
        const brand = await prisma.brand.findUnique({
            where: { slug: 'rasa-ibu' }
        });

        if (!brand) {
            return { success: false, error: 'Brand tidak ditemukan.' };
        }

        // 2. Track as Analytics Event (Intelligence Hub)
        await prisma.analyticsEvent.create({
            data: {
                brandId: brand.id,
                type: 'HERO_CTA_CLICK', // Using valid enum value from schema.prisma
                metadata: {
                    source: 'CONTACT_FORM',
                    name: data.name,
                    phone: data.phone,
                    email: data.targetEmail,
                    message: data.message.substring(0, 100) + '...'
                }
            }
        });

        // 3. Send Email Notification to Owner (achiera25.id@gmail.com)
        await emailAlertService.sendContactLead({
            name: data.name,
            phone: data.phone,
            email: 'via-contact-form@achiera.com', // Placeholder for from, data.targetEmail is where it goes
            message: data.message,
            targetEmail: data.targetEmail,
            brandName: brand.name
        });

        console.log(`[Intelligence Lead Email Sent to ${data.targetEmail}]`);

        revalidatePath('/rasa-ibu/contact');
        return { success: true };

    } catch (error: any) {
        console.error('[Contact Action Error]', error);
        return { success: false, error: 'Gagal mengirim pesan. Silakan coba lagi.' };
    }
}

'use server';

import { prisma } from '@/lib/prisma';
import { demandForecastEngine } from '@/lib/intelligence/demandForecastEngine';
import { revalidatePath } from 'next/cache';

// ===== DEMAND FORECASTING =====
export async function generateDemandForecasts(brandId: string, variantId: string, days: number = 7) {
    try {
        const forecasts = await demandForecastEngine.generateForecast(brandId, variantId, days);
        await demandForecastEngine.generateStockAlerts(brandId);

        revalidatePath('/dashboard/rasa-ibu');
        return { success: true, data: JSON.parse(JSON.stringify(forecasts)) };
    } catch (error: any) {
        return { success: false, error: error.message };
    }
}

export async function generateAllForecasts(brandId: string) {
    try {
        const variants = await prisma.frozenVariant.findMany({
            where: { product: { category: { brandId: brandId } } },
            select: { id: true }
        });

        for (const variant of variants) {
            await demandForecastEngine.generateForecast(brandId, variant.id, 7);
        }

        await demandForecastEngine.generateStockAlerts(brandId);

        revalidatePath('/dashboard/rasa-ibu');
        return { success: true, message: `Generated forecasts for ${variants.length} products` };
    } catch (error: any) {
        return { success: false, error: error.message };
    }
}

export async function getDemandForecasts(brandId: string, variantId?: string) {
    try {
        const forecasts = await (prisma as any).demandForecast.findMany({
            where: {
                brandId,
                ...(variantId && { variantId }),
                forecastDate: { gte: new Date() }
            },
            include: {
                variant: {
                    include: {
                        product: { select: { name: true } }
                    }
                }
            },
            orderBy: { forecastDate: 'asc' }
        });

        return { success: true, data: JSON.parse(JSON.stringify(forecasts)) };
    } catch (error: any) {
        return { success: false, error: error.message };
    }
}

export async function getForecastAccuracy(brandId: string) {
    try {
        const forecasts = await (prisma as any).demandForecast.findMany({
            where: {
                brandId,
                actualDemand: { not: null },
                accuracy: { not: null }
            },
            select: { accuracy: true }
        });

        const avgAccuracy = (forecasts as any[]).length > 0
            ? (forecasts as any[]).reduce((sum: number, f: any) => sum + Number(f.accuracy || 0), 0) / (forecasts as any[]).length
            : 0;

        return { success: true, data: { avgAccuracy: Math.round(avgAccuracy), totalForecasts: (forecasts as any[]).length } };
    } catch (error: any) {
        return { success: false, error: error.message };
    }
}

