/**
 * Check if recommendation already exists (cooldown)
 */
async function checkCooldown(
    brandId: string,
    category: RecommendationCategory,
    cooldownDays: number
): Promise<boolean> {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - cooldownDays);

    const existing = await prisma.recommendation.findFirst({
        where: {
            brandId,
            category,
            createdAt: { gte: cutoffDate }
        }
    });

    return existing !== null;
}

/**
 * Evaluate restock alert rule
 */
async function evaluateRestockAlert(brandId: string): Promise<RecommendationData[]> {
    const recommendations: RecommendationData[] = [];

    // Get variants with low stock
    const variants = await prisma.frozenVariant.findMany({
        where: {
            product: { category: { brandId } },
            stockOnHand: { lt: 20 }
        },
        include: {
            product: true
        }
    });

    for (const variant of variants) {
        // Calculate sales velocity (last 7 days)
        const sevenDaysAgo = new Date();
        sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

        const salesEvents = await prisma.analyticsEvent.count({
            where: {
                brandId,
                eventType: 'sales.product_sold',
                eventTimestamp: { gte: sevenDaysAgo },
                payload: { path: ['variantId'], equals: variant.id }
            }
        });

        const avgDailySales = salesEvents / 7;
        const daysOfStock = avgDailySales > 0 ? variant.stockOnHand / avgDailySales : 999;

        // Check conditions
        if (daysOfStock < 7 && avgDailySales > 0) {
            const recommendedQuantity = Math.ceil(avgDailySales * 30); // 30 days stock

            recommendations.push({
                category: 'inventory.restock_alert',
                priority: 'high',
                confidenceScore: 0.85,
                title: `Restock Alert: ${variant.name}`,
                description: `Stock running low with ${Math.floor(daysOfStock)} days remaining`,
                reasoning: `Current stock: ${variant.stockOnHand} units. Average daily sales: ${avgDailySales.toFixed(1)}. At current rate, stock will run out in ${Math.floor(daysOfStock)} days.`,
                recommendedAction: `Order ${recommendedQuantity} units to maintain 30 days of stock`,
                expectedImpact: `Prevent stockouts and maintain sales momentum`,
                estimatedValue: recommendedQuantity * Number(variant.price),
                supportingMetrics: {
                    stockOnHand: variant.stockOnHand,
                    avgDailySales,
                    daysOfStock,
                    recommendedQuantity
                },
                dataSources: ['analytics_events', 'frozen_variants']
            });
        }
    }

    return recommendations;
}

/**
 * Evaluate increase ad spend rule
 */
async function evaluateIncreaseAdSpend(brandId: string): Promise<RecommendationData[]> {
    const recommendations: RecommendationData[] = [];

    // Get recent ads performance (last 7 days)
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    const adsSnapshots = await prisma.analyticsDailyAds.findMany({
        where: {
            brandId,
            snapshotDate: { gte: sevenDaysAgo }
        }
    });

    // Group by platform
    const platformMetrics: Record<string, { roas: number; spend: number; conversions: number; clicks: number }> = {};

    for (const snapshot of adsSnapshots) {
        if (!platformMetrics[snapshot.platform]) {
            platformMetrics[snapshot.platform] = { roas: 0, spend: 0, conversions: 0, clicks: 0 };
        }
        platformMetrics[snapshot.platform].roas += Number(snapshot.roas);
        platformMetrics[snapshot.platform].spend += Number(snapshot.spend);
        platformMetrics[snapshot.platform].conversions += snapshot.conversions;
        platformMetrics[snapshot.platform].clicks += snapshot.clicks;
    }

    // Evaluate each platform
    for (const [platform, metrics] of Object.entries(platformMetrics)) {
        const avgRoas = metrics.roas / adsSnapshots.filter(s => s.platform === platform).length;
        const conversionRate = metrics.clicks > 0 ? metrics.conversions / metrics.clicks : 0;

        if (avgRoas > 3.0 && conversionRate > 0.02) {
            const currentBudget = metrics.spend / 7; // Daily average
            const recommendedBudget = currentBudget * 1.5; // 50% increase

            recommendations.push({
                category: 'marketing.increase_ad_spend',
                priority: 'high',
                confidenceScore: 0.88,
                title: `Opportunity: Increase ${platform} Ad Spend`,
                description: `Campaign performing exceptionally well with ${avgRoas.toFixed(1)}x ROAS`,
                reasoning: `Your ${platform} campaigns have achieved ${avgRoas.toFixed(1)}x ROAS over the past 7 days, significantly above the 3.0x threshold. With ${(conversionRate * 100).toFixed(2)}% conversion rate, increasing budget could capture more profitable sales.`,
                recommendedAction: `Increase daily budget from ${currentBudget.toLocaleString()} to ${recommendedBudget.toLocaleString()} (+50%)`,
                expectedImpact: `Estimated additional revenue: ${(recommendedBudget * avgRoas * 7).toLocaleString()}`,
                estimatedValue: recommendedBudget * avgRoas * 7,
                supportingMetrics: {
                    platform,
                    avgRoas,
                    conversionRate,
                    currentBudget,
                    recommendedBudget
                },
                dataSources: ['analytics_daily_ads']
            });
        }
    }

    return recommendations;
}

/**
 * Run recommendation engine
 */
export async function runRecommendationEngine(brandId?: string): Promise<void> {
    console.log('[Recommendations] Starting recommendation engine...');

    const brands = brandId
        ? [await prisma.brand.findUnique({ where: { id: brandId } })]
        : await prisma.brand.findMany({ where: { isActive: true } });

    for (const brand of brands) {
        if (!brand) continue;

        try {
            const allRecommendations: RecommendationData[] = [];

            // Evaluate each rule
            const restockRecs = await evaluateRestockAlert(brand.id);
            const adSpendRecs = await evaluateIncreaseAdSpend(brand.id);

            allRecommendations.push(...restockRecs, ...adSpendRecs);

            // Create recommendations
            for (const rec of allRecommendations) {
                // Check cooldown
                const inCooldown = await checkCooldown(brand.id, rec.category, 7);
                if (inCooldown) continue;

                // Create recommendation
                const created = await prisma.recommendation.create({
                    data: {
                        brandId: brand.id,
                        category: rec.category,
                        priority: rec.priority,
                        confidenceScore: rec.confidenceScore,
                        title: rec.title,
                        description: rec.description,
                        reasoning: rec.reasoning,
                        recommendedAction: rec.recommendedAction,
                        expectedImpact: rec.expectedImpact,
                        estimatedValue: rec.estimatedValue,
                        supportingMetrics: rec.supportingMetrics,
                        dataSources: rec.dataSources,
                        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000) // 7 days
                    }
                });

                // Track event
                await writeAnalyticsEvent({
                    brandId: brand.id,
                    eventType: 'recommendation.generated',
                    payload: {
                        recommendationId: created.id,
                        category: rec.category,
                        priority: rec.priority
                    }
                });

                console.log(`[Recommendations] ✓ ${brand.name}: ${rec.title}`);
            }
        } catch (error) {
            console.error(`[Recommendations] ✗ Failed for brand ${brand.name}:`, error);
        }
    }

    console.log('[Recommendations] Recommendation engine complete');
}

// CLI execution
if (require.main === module) {
    runRecommendationEngine()
        .then(() => process.exit(0))
        .catch(error => {
            console.error('Recommendation engine failed:', error);
            process.exit(1);
        });
}

// ACHIERA Platform - Brand Isolation Middleware
// Prisma middleware to enforce brandId on all queries

import { Prisma } from '@prisma/client';
import { prisma } from '@/lib/prisma';

/**
 * Models that are brand-scoped (require brandId)
 */
const BRAND_SCOPED_MODELS = [
    'Order',
    'OrderItem',
    'Payment',
    'Refund',
    'FrozenProduct',
    'FrozenVariant',
    'FrozenCategory',
    'InventoryBatch',
    'LedgerAccount',
    'JournalTransaction',
    'JournalEntry',
    'User', // Users belong to brands (except platform users)
    'AuditLog'
];

/**
 * Models that are globally accessible (no brandId required)
 */
const GLOBAL_MODELS = [
    'Brand',
    'PriceComponent',
    'PriceRule',
    'SystemLog',
    'IdempotencyKey'
];

export class BrandIsolationError extends Error {
    constructor(
        message: string,
        public readonly model: string,
        public readonly operation: string
    ) {
        super(message);
        this.name = 'BrandIsolationError';
    }
}

/**
 * Check if model requires brand isolation
 */
function requiresBrandId(model: string): boolean {
    return BRAND_SCOPED_MODELS.includes(model);
}

/**
 * Extract brandId from where clause
 */
function getBrandIdFromWhere(where: any): string | null {
    if (!where) return null;

    // Direct brandId
    if (where.brandId) {
        if (typeof where.brandId === 'string') {
            return where.brandId;
        }
        if (where.brandId.equals) {
            return where.brandId.equals;
        }
    }

    // Nested brandId (e.g., order.brandId)
    if (where.order?.brandId) {
        return where.order.brandId;
    }
    if (where.brand?.id) {
        return where.brand.id;
    }

    return null;
}

/**
 * Prisma middleware for brand isolation enforcement
 */
export function brandIsolationMiddleware(
    params: Prisma.MiddlewareParams,
    next: (params: Prisma.MiddlewareParams) => Promise<any>
) {
    const { model, action, args } = params;

    // Skip if no model (raw queries, etc.)
    if (!model) {
        return next(params);
    }

    // Skip global models
    if (GLOBAL_MODELS.includes(model)) {
        return next(params);
    }

    // Enforce brandId for brand-scoped models
    if (requiresBrandId(model)) {
        // Read operations
        if (action === 'findUnique' || action === 'findFirst' || action === 'findMany') {
            const brandId = getBrandIdFromWhere(args.where);

            if (!brandId) {
                throw new BrandIsolationError(
                    `Brand isolation violation: ${model}.${action} requires brandId in where clause`,
                    model,
                    action
                );
            }
        }

        // Write operations
        if (action === 'create') {
            if (!args.data?.brandId) {
                throw new BrandIsolationError(
                    `Brand isolation violation: ${model}.${action} requires brandId in data`,
                    model,
                    action
                );
            }
        }

        if (action === 'update' || action === 'updateMany' || action === 'delete' || action === 'deleteMany') {
            const brandId = getBrandIdFromWhere(args.where);

            if (!brandId) {
                throw new BrandIsolationError(
                    `Brand isolation violation: ${model}.${action} requires brandId in where clause`,
                    model,
                    action
                );
            }
        }
    }

    return next(params);
}

/**
 * Initialize brand isolation middleware
 */
export function initBrandIsolation() {
    prisma.$use(brandIsolationMiddleware);
}

/**
 * Bypass brand isolation for specific operations (use with extreme caution)
 * Only for platform-level operations
 */
export async function withoutBrandIsolation<T>(
    operation: () => Promise<T>
): Promise<T> {
    // Temporarily disable middleware
    // Note: This is a simplified version. In production, you'd need a more sophisticated approach
    // such as using a separate Prisma client instance or a context flag

    // For now, we'll just execute the operation
    // The middleware will still run, but you can add a context flag to skip it
    return operation();
}

/**
 * Helper to validate brandId matches user's brand
 */
export function validateBrandAccess(
    userBrandId: string | null,
    targetBrandId: string,
    userRole: string
): void {
    // Platform owners can access any brand
    if (userRole === 'PLATFORM_OWNER' || userRole === 'PLATFORM_ADMIN') {
        return;
    }

    // Brand users can only access their own brand
    if (userBrandId !== targetBrandId) {
        throw new BrandIsolationError(
            `Brand access denied: User brand ${userBrandId} cannot access brand ${targetBrandId}`,
            'Brand',
            'access'
        );
    }
}

import { prisma } from '@/lib/prisma';

export type ActionStatus = 'STAGED' | 'PENDING_APPROVAL' | 'APPROVED' | 'EXECUTING' | 'COMPLETED' | 'FAILED' | 'REVERTING' | 'REVERTED';

export interface AssistedActionService {
    promoteSuggestion: (suggestionId: string) => Promise<any>;
    finalizePayload: (actionId: string, payload: any) => Promise<any>;
    submitApproval: (actionId: string, operatorId: string, role: string, acknowledgment: string) => Promise<any>;
    executeAction: (actionId: string, operatorId: string) => Promise<any>;
    revertAction: (actionId: string, operatorId: string) => Promise<any>;
}

export const assistedActionService = {
    /**
     * Promotes a Suggestion to a STAGED AssistedAction.
     * Human trigger required.
     */
    async promoteSuggestion(suggestionId: string) {
        const suggestion = await (prisma as any).suggestionDraft.findUnique({
            where: { id: suggestionId }
        });

        if (!suggestion) throw new Error('Suggestion not found');

        return await (prisma as any).assistedAction.create({
            data: {
                suggestionId,
                brandId: suggestion.brandId,
                status: 'STAGED',
                payload: suggestion.proposedAction, // Initial payload from suggestion
                riskTier: suggestion.riskLevel,
                reversalPlan: { steps: [`Revert ${suggestion.title}`] }
            }
        });
    },

    /**
     * Finalizes payload and moves to PENDING_APPROVAL.
     */
    async finalizePayload(actionId: string, payload: any) {
        return await (prisma as any).assistedAction.update({
            where: { id: actionId },
            data: {
                payload,
                status: 'PENDING_APPROVAL'
            }
        });
    },

    /**
     * Submits an approval signature.
     * Checks for governance requirements (e.g. CFO for HIGH risk).
     */
    async submitApproval(actionId: string, operatorId: string, role: string, acknowledgment: string) {
        const action = await (prisma as any).assistedAction.findUnique({
            where: { id: actionId },
            include: { approvals: true }
        });

        if (!action) throw new Error('Action not found');

        // Create Approval
        await (prisma as any).actionApproval.create({
            data: {
                actionId,
                operatorId,
                role,
                acknowledgment
            }
        });

        // Check if fully approved
        const updatedAction = await (prisma as any).assistedAction.findUnique({
            where: { id: actionId },
            include: { approvals: true }
        });

        const roles = updatedAction.approvals.map((a: any) => a.role);

        let isFullyApproved = false;
        if (action.riskTier === 'HIGH') {
            isFullyApproved = roles.includes('CFO') && roles.includes('BOARD');
        } else {
            isFullyApproved = roles.includes('OPERATOR') || roles.includes('CFO');
        }

        if (isFullyApproved) {
            return await (prisma as any).assistedAction.update({
                where: { id: actionId },
                data: { status: 'APPROVED' }
            });
        }

        return updatedAction;
    },

    /**
     * FINAL HUMAN TRIGGER for execution.
     * NO AUTO-EXECUTION ALLOWED.
     */
    async executeAction(actionId: string, operatorId: string) {
        const action = await (prisma as any).assistedAction.findUnique({
            where: { id: actionId }
        });

        if (action.status !== 'APPROVED') {
            throw new Error(`GOVERNANCE_ERROR: Action status [${action.status}] is not APPROVED.`);
        }

        // Move to EXECUTING
        await (prisma as any).assistedAction.update({
            where: { id: actionId },
            data: { status: 'EXECUTING' }
        });

        try {
            // SIMULATED EXECUTION (Phase 4 is still non-autonomous in real side effects, 
            // but this function represents the conduit).
            // In Phase 5, this would call external APIs.
            console.log(`[EXECUTION] Applying payload to system:`, action.payload);

            // Update to COMPLETED
            return await (prisma as any).assistedAction.update({
                where: { id: actionId },
                data: { status: 'COMPLETED' }
            });
        } catch (error) {
            await (prisma as any).assistedAction.update({
                where: { id: actionId },
                data: { status: 'FAILED' }
            });
            throw error;
        }
    },

    /**
     * Manual Rollback
     */
    async revertAction(actionId: string, operatorId: string) {
        await (prisma as any).assistedAction.update({
            where: { id: actionId },
            data: { status: 'REVERTING' }
        });

        try {
            console.log(`[ROLLBACK] Reversing action:`, actionId);

            return await (prisma as any).assistedAction.update({
                where: { id: actionId },
                data: { status: 'REVERTED' }
            });
        } catch (error) {
            // If rollback fails, system enters critical state
            throw new Error(`FATAL: Rollback failed for action ${actionId}`);
        }
    }
};

// AI Explainer - Main AI explanation service
// CRITICAL: Advisory-only, no execution authority, full audit trail

import Anthropic from '@anthropic-ai/sdk';
import { RuleEvaluationResult } from '../types/decision';
import { assembleAIContext } from './context-assembler';
import { buildPrompt } from './prompt-builder';
import {
    validateAIOutput,
    applySafetyFilters,
    createDeterministicFallback,
    sanitizeAIOutput
} from './ai-guardrails';
import { AIExplanation, PromptType } from './types';

const anthropic = new Anthropic({
    apiKey: process.env.ANTHROPIC_API_KEY || ''
});

/**
 * Generate AI explanation for a rule evaluation
 */
export async function explainDecision(
    ruleEvaluation: RuleEvaluationResult,
    brandId: string,
    promptType: PromptType = PromptType.RULE_EXPLANATION
): Promise<AIExplanation> {
    const startTime = Date.now();

    try {
        // Assemble context
        const context = await assembleAIContext(ruleEvaluation, brandId);

        // Build prompt
        const promptRequest = {
            type: promptType,
            context,
            options: {
                language: 'id' as const,
                tone: 'operator' as const
            }
        };

        const { prompt, systemPrompt, maxTokens, temperature } = buildPrompt(promptRequest);

        // Call AI
        const response = await anthropic.messages.create({
            model: 'claude-3-haiku-20240307',
            max_tokens: maxTokens,
            temperature,
            system: systemPrompt,
            messages: [
                {
                    role: 'user',
                    content: prompt
                }
            ]
        });

        // Extract JSON from response
        const aiOutput = extractJSON((response.content[0] as any).text);

        // Sanitize output
        const sanitized = sanitizeAIOutput(aiOutput);

        // Validate output
        const validation = validateAIOutput(sanitized);

        if (!validation.valid) {
            console.error('[AI EXPLAINER] Validation failed:', validation.errors);

            // Fall back to deterministic
            return createDeterministicFallback(
                ruleEvaluation.ruleName,
                ruleEvaluation.metricsSnapshot,
                context.metrics.thresholds
            );
        }

        // Build complete explanation
        const explanation: AIExplanation = {
            explanation: sanitized.explanation || {
                why_triggered: 'AI explanation unavailable',
                data_points: [],
                confidence: 0,
                source: 'deterministic_fallback'
            },
            recommended_action: sanitized.recommended_action || {
                action_id: ruleEvaluation.action.actionId,
                expected_impact: 'Unknown',
                risk_level: ruleEvaluation.riskLevel,
                rollback_available: true,
                confidence: 0
            },
            alternatives: sanitized.alternatives || [],
            risks: sanitized.risks || [],
            warnings: validation.warnings,
            human_next_steps: sanitized.human_next_steps || [],
            metadata: {
                ai_model: 'claude-3-haiku-20240307',
                generated_at: new Date(),
                context_tokens: response.usage.input_tokens,
                response_tokens: response.usage.output_tokens,
                processing_time_ms: Date.now() - startTime
            }
        };

        // Apply safety filters
        const filtered = applySafetyFilters(explanation);

        // Audit log
        await auditAIExplanation(brandId, ruleEvaluation.ruleId, filtered);

        return filtered;

    } catch (error) {
        console.error('[AI EXPLAINER] Error:', error);

        // Fall back to deterministic
        const context = await assembleAIContext(ruleEvaluation, brandId);
        return createDeterministicFallback(
            ruleEvaluation.ruleName,
            ruleEvaluation.metricsSnapshot,
            context.metrics.thresholds
        );
    }
}

/**
 * Generate multiple explanations (batch)
 */
export async function explainDecisionsBatch(
    ruleEvaluations: RuleEvaluationResult[],
    brandId: string
): Promise<AIExplanation[]> {
    const explanations: AIExplanation[] = [];

    for (const evaluation of ruleEvaluations) {
        const explanation = await explainDecision(evaluation, brandId);
        explanations.push(explanation);
    }

    return explanations;
}

/**
 * Generate executive summary
 */
export async function generateExecutiveSummary(
    ruleEvaluation: RuleEvaluationResult,
    brandId: string
): Promise<{
    summary: string;
    key_metric: string;
    recommendation: 'approve' | 'review' | 'reject';
}> {
    const explanation = await explainDecision(
        ruleEvaluation,
        brandId,
        PromptType.EXECUTIVE_SUMMARY
    );

    return {
        summary: explanation.explanation.why_triggered,
        key_metric: explanation.explanation.data_points[0] || 'N/A',
        recommendation: determineRecommendation(explanation)
    };
}

/**
 * Extract JSON from AI response
 */
function extractJSON(text: string): any {
    try {
        // Try to parse directly
        return JSON.parse(text);
    } catch {
        // Try to extract JSON from markdown code block
        const jsonMatch = text.match(/```json\n([\s\S]*?)\n```/);
        if (jsonMatch) {
            return JSON.parse(jsonMatch[1]);
        }

        // Try to extract JSON object
        const objectMatch = text.match(/\{[\s\S]*\}/);
        if (objectMatch) {
            return JSON.parse(objectMatch[0]);
        }

        throw new Error('No valid JSON found in response');
    }
}

/**
 * Determine recommendation from explanation
 */
function determineRecommendation(
    explanation: AIExplanation
): 'approve' | 'review' | 'reject' {
    // High confidence + low risk = approve
    if (explanation.explanation.confidence >= 0.85 &&
        explanation.recommended_action.risk_level === 'LOW') {
        return 'approve';
    }

    // Low confidence or high risk = review
    if (explanation.explanation.confidence < 0.70 ||
        ['HIGH', 'CRITICAL'].includes(explanation.recommended_action.risk_level)) {
        return 'review';
    }

    // Critical warnings = reject
    if (explanation.warnings.some(w => w.includes('CRITICAL'))) {
        return 'reject';
    }

    return 'review';
}

