    };

    return actionMap[ruleName] || ruleName;
}

function getPrimaryMetric(metrics: Record<string, number>): {
    name: string;
    value: number;
    comparison: string;
    context: string;
} {
    // Find the most important metric (usually the first one)
    const [key, value] = Object.entries(metrics)[0];

    return {
        name: key,
        value: value,
        comparison: value < 1 ? 'turun ke' : 'naik ke',
        context: `pengeluaran Rp ${formatCurrency(metrics.ad_spend_7d || 0)} dalam 7 hari terakhir`
    };
}

function getPrimaryThreshold(thresholds: Record<string, number>): {
    key: string;
    value: string;
} {
    const [key, value] = Object.entries(thresholds)[0];
    return {
        key,
        value: `${value}x`
    };
}

function getAutonomyLevelName(level: number): string {
    const names = [
        'Level 0 (Observe)',
        'Level 1 (Suggest)',
        'Level 2 (Assisted)',
        'Level 3 (Guarded)'
    ];
    return names[level] || `Level ${level}`;
}

function getRiskDescription(riskTier: string): string {
    const descriptions: Record<string, string> = {
        'LOW': 'hanya mengubah state sementara, tidak ada perubahan permanen',
        'MEDIUM': 'memiliki dampak finansial terbatas dan dapat di-rollback',
        'HIGH': 'memiliki dampak finansial signifikan, memerlukan approval',
        'CRITICAL': 'memiliki dampak finansial besar, memerlukan CFO approval'
    };

    return descriptions[riskTier] || 'tidak diketahui';
}

function getSafetyGateDetails(gatesPassed: number): string[] {
    return [
        'cooldown period (tidak ada eksekusi serupa 60 menit terakhir)',
        'daily cap (belum mencapai limit eksekusi harian)',
        'blackout period (di luar jam 00:00-06:00)',
        'autonomy level sesuai (tidak melebihi maksimal yang diizinkan)',
        'confidence score memenuhi threshold',
        'data completeness mencukupi (semua metrik tersedia)',
        'tidak ada konflik dengan eksekusi pending lainnya'
    ].slice(0, gatesPassed);
}

function estimateFinancialImpact(impact: any): {
    description: string;
    risk: string;
} {
    if (impact.type === 'cost_savings') {
        return {
            description: `maksimal penghematan Rp ${formatCurrency(impact.amount || 0)}/minggu`,
            risk: 'tidak ada risiko revenue loss'
        };
    } else if (impact.type === 'revenue_increase') {
        return {
            description: `potensi peningkatan revenue Rp ${formatCurrency(impact.amount || 0)}/minggu`,
            risk: `risiko revenue loss jika gagal: Rp ${formatCurrency(impact.revenueRisk || 0)}`
        };
    }

    return {
        description: 'dampak finansial minimal',
        risk: 'risiko terbatas'
    };
}

function formatMetricValue(key: string, value: number): string {
    if (key.includes('roas') || key.includes('rate')) {
        return `${value.toFixed(2)}x`;
    } else if (key.includes('spend') || key.includes('revenue')) {
        return `Rp ${formatCurrency(value)}`;
    } else {
        return value.toLocaleString('id-ID');
    }
}

function formatCurrency(value: number): string {
    if (value >= 1000000) {
        return `${(value / 1000000).toFixed(1)}jt`;
    } else if (value >= 1000) {
        return `${(value / 1000).toFixed(0)}rb`;
    }
    return value.toLocaleString('id-ID');
}

// Context Assembler - Build AI context from decision data
// CRITICAL: PII-safe, brand-isolated, read-only

import { prisma } from '@/lib/prisma';
import { RuleEvaluationResult } from '../types/decision';
import { AIContext, MetricsTimeSeries } from './types';

/**
 * Assemble AI context for explanation
 */
export async function assembleAIContext(
    ruleEvaluation: RuleEvaluationResult,
    brandId: string
): Promise<AIContext> {
    // Load rule metadata
    const rule = await loadRuleMetadata(ruleEvaluation.ruleId);

    // Load current metrics
    const currentMetrics = ruleEvaluation.metricsSnapshot;

    // Load historical metrics (last 90 days)
    const historicalMetrics = await fetchHistoricalMetrics(
        brandId,
        rule.metricsUsed,
        90
    );

    // Load brand context (PII-safe)
    const brandContext = await loadBrandContext(brandId);

    // Load historical executions
    const history = await loadExecutionHistory(
        brandId,
        ruleEvaluation.ruleId,
        30 // last 30 days
    );

    // Calculate token budget
    const maxTokens = calculateTokenBudget(rule, currentMetrics, historicalMetrics);

    return {
        rule: {
            ruleId: rule.ruleId,
            name: rule.name,
            domain: rule.domain,
            priority: rule.priority,
            confidenceThreshold: rule.confidenceThreshold
        },
        metrics: {
            current: currentMetrics,
            thresholds: extractThresholds(rule.conditions),
            historical: historicalMetrics
        },
        decision: {
            riskTier: ruleEvaluation.riskLevel,
            autonomyLevel: ruleEvaluation.action.autonomyLevel,
            estimatedImpact: ruleEvaluation.estimatedImpact,
            approvalRequired: determineApprovalRequired(ruleEvaluation)
        },
        brand: {
            brandId: brandContext.brandId,
            industry: brandContext.industry,
            size: determineBrandSize(brandContext),
            constraints: brandContext.constraints
        },
        history: {
            similarDecisions: history.length,
            successRate: calculateSuccessRate(history),
            lastExecution: history[0]?.executedAt
        },
        maxTokens
    };
}

/**
 * Load rule metadata
 */
async function loadRuleMetadata(ruleId: string) {
    const rule = await prisma.decisionRule.findUnique({
        where: { ruleId }
    });

    if (!rule) {
        throw new Error(`Rule not found: ${ruleId}`);
    }

    return {
        ruleId: rule.ruleId,
        name: rule.name,
        domain: rule.domain,
        priority: rule.priority,
        confidenceThreshold: rule.confidenceThreshold,
        metricsUsed: rule.metricsUsed as string[],
        conditions: rule.conditions as any[]
    };
}

/**
 * Fetch historical metrics (PII-safe)
 */
async function fetchHistoricalMetrics(
    brandId: string,
    metricsUsed: string[],
    days: number
): Promise<MetricsTimeSeries | undefined> {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    // Fetch daily aggregations
    const aggregations = await prisma.aggDailySales.findMany({
        where: {
            brandId,
            date: { gte: startDate }
        },
        orderBy: { date: 'asc' },
        take: days
    });

    if (aggregations.length === 0) {
        return undefined;
    }

    // Build time series
    const dates = aggregations.map(a => a.date);
    const values: Record<string, number[]> = {};

    for (const metric of metricsUsed) {
        values[metric] = aggregations.map(a => {
            // Map metric names to aggregation fields
            switch (metric) {
                case 'revenue_7d':
                    return a.totalRevenue;
                case 'orders_7d':
                    return a.totalOrders;
                default:
                    return 0;
            }
        });
    }

    return { dates, values };
}

/**
 * Load brand context (PII-safe)
 */
async function loadBrandContext(brandId: string) {
    const brand = await prisma.brand.findUnique({
        where: { id: brandId }
    });

    if (!brand) {
        throw new Error(`Brand not found: ${brandId}`);
    }

    return {
        brandId: brand.id,
        industry: brand.industry || 'e-commerce',
        constraints: [
            // Only include non-PII constraints
            'budget_cap',
            'risk_tolerance'
        ]
        // NEVER include:
        // - Brand name
        // - Owner name
        // - Contact info
    };
}

/**
 * Load execution history
 */
async function loadExecutionHistory(
    brandId: string,
    ruleId: string,
    days: number
) {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    const executions = await prisma.executionLog.findMany({
        where: {
            brandId,
            ruleId,
            executedAt: { gte: startDate }
        },
        orderBy: { executedAt: 'desc' },
        take: 10
    });

    return executions;
}

/**
 * Extract thresholds from rule conditions
 */
function extractThresholds(conditions: any[]): Record<string, number> {
    const thresholds: Record<string, number> = {};

    for (const condition of conditions) {
        thresholds[condition.metric] = condition.value;
    }

    return thresholds;
}

/**
 * Determine if approval is required
 */
function determineApprovalRequired(ruleEvaluation: RuleEvaluationResult): boolean {
    // Level 2-3 with MEDIUM+ risk requires approval
    if (ruleEvaluation.action.autonomyLevel >= 2 &&
        ['MEDIUM', 'HIGH', 'CRITICAL'].includes(ruleEvaluation.riskLevel)) {
        return true;
    }

    return false;
}

/**
 * Determine brand size
 */
function determineBrandSize(brand: any): 'small' | 'medium' | 'large' {
    // Simple heuristic based on brand data
    // In production, this would use actual revenue/order data
    return 'medium';
}

/**
 * Calculate success rate from execution history
 */
function calculateSuccessRate(executions: any[]): number {
    if (executions.length === 0) return 0;

    const successful = executions.filter(e => e.executionStatus === 'success').length;
    return successful / executions.length;
}

/**
 * Calculate token budget
 */
function calculateTokenBudget(
    rule: any,
    currentMetrics: Record<string, number>,
    historicalMetrics?: MetricsTimeSeries
): number {
    const baseTokens = 2000; // Base budget
    const metricsTokens = Object.keys(currentMetrics).length * 50;
    const historyTokens = historicalMetrics
        ? Math.min(historicalMetrics.dates.length * 20, 500)
        : 0;

    const total = baseTokens + metricsTokens + historyTokens;
    const max = 4000; // Hard cap

    return Math.min(total, max);
}

// AI Cost Monitoring - Track and optimize AI usage costs
// CRITICAL: Optimize costs without reducing safety or audit quality

import { prisma } from '@/lib/prisma';

interface AICostReport {
    summary: string;
    daily_cost_estimate: number;
    top_cost_drivers: string[];
    safe_optimizations: string[];
    no_action_needed: boolean;
}

interface AIUsageStats {
    total_calls: number;
    total_input_tokens: number;
    total_output_tokens: number;
    avg_tokens_per_call: number;
    duplicate_calls: number;
    cacheable_calls: number;
}

/**
 * Generate AI cost optimization report
 */
export async function generateCostReport(
    brandId: string,
    startDate: Date,
    endDate: Date
): Promise<AICostReport> {
    // Fetch AI usage data
    const usageStats = await fetchAIUsageStats(brandId, startDate, endDate);

    // Calculate costs (Anthropic Claude 3.5 Sonnet pricing)
    const inputCost = (usageStats.total_input_tokens / 1_000_000) * 3; // $3 per 1M tokens
    const outputCost = (usageStats.total_output_tokens / 1_000_000) * 15; // $15 per 1M tokens
    const totalCost = inputCost + outputCost;

    // Calculate daily average
    const days = Math.ceil((endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24));
    const dailyCostEstimate = totalCost / days;

    // Identify cost drivers
    const topCostDrivers = identifyCostDrivers(usageStats);

    // Identify safe optimizations
    const safeOptimizations = identifySafeOptimizations(usageStats);

    // Build summary
    const summary = buildCostSummary(
        usageStats,
        dailyCostEstimate,
        safeOptimizations.length
    );

    // Determine if action is needed
    const noActionNeeded = safeOptimizations.length === 0 && dailyCostEstimate < 5;

    return {
        summary,
        daily_cost_estimate: parseFloat(dailyCostEstimate.toFixed(2)),
        top_cost_drivers: topCostDrivers,
        safe_optimizations: safeOptimizations,
        no_action_needed: noActionNeeded
    };
}

/**
 * Fetch AI usage statistics
 */
async function fetchAIUsageStats(
    brandId: string,
    startDate: Date,
    endDate: Date
): Promise<AIUsageStats> {
    // Fetch AI explanation logs
    const aiLogs = await prisma.aiExplanationLog.findMany({
        where: {
            brandId,
            createdAt: {
                gte: startDate,
                lt: endDate
            }
        }
    });

    const totalCalls = aiLogs.length;
    const totalInputTokens = aiLogs.reduce((sum, log) => sum + (log.inputTokens || 0), 0);
    const totalOutputTokens = aiLogs.reduce((sum, log) => sum + (log.outputTokens || 0), 0);
    const avgTokensPerCall = totalCalls > 0
        ? (totalInputTokens + totalOutputTokens) / totalCalls
        : 0;

    // Identify duplicates (same ruleId + similar metrics within 1 hour)
    const duplicateCalls = identifyDuplicateCalls(aiLogs);

    // Identify cacheable calls (same context, different timestamps)
    const cacheableCalls = identifyCacheableCalls(aiLogs);

    return {
        total_calls: totalCalls,
        total_input_tokens: totalInputTokens,
        total_output_tokens: totalOutputTokens,
        avg_tokens_per_call: Math.round(avgTokensPerCall),
        duplicate_calls: duplicateCalls,
        cacheable_calls: cacheableCalls
    };
}

/**
 * Identify duplicate AI calls
 */
function identifyDuplicateCalls(logs: any[]): number {
    const seen = new Map<string, Date>();
    let duplicates = 0;

    for (const log of logs) {
        const key = `${log.ruleId}_${JSON.stringify(log.metricsSnapshot)}`;
        const lastSeen = seen.get(key);

        if (lastSeen) {
            const hoursSince = (log.createdAt.getTime() - lastSeen.getTime()) / (1000 * 60 * 60);

            // If same context within 1 hour, it's a duplicate
            if (hoursSince < 1) {
                duplicates++;
            }
        }

        seen.set(key, log.createdAt);
    }

    return duplicates;
}

/**
 * Identify cacheable calls
 */
function identifyCacheableCalls(logs: any[]): number {
    const contextCounts = new Map<string, number>();

    for (const log of logs) {
        const contextKey = `${log.ruleId}_${log.promptType}`;
        contextCounts.set(contextKey, (contextCounts.get(contextKey) || 0) + 1);
    }

    // Count calls that could benefit from caching (repeated contexts)
    let cacheable = 0;
    for (const count of contextCounts.values()) {
        if (count > 1) {
            cacheable += count - 1; // First call can't be cached
        }
    }

    return cacheable;
}

/**
 * Identify top cost drivers
 */
function identifyCostDrivers(stats: AIUsageStats): string[] {
    const drivers: string[] = [];

    // High token usage per call
    if (stats.avg_tokens_per_call > 3000) {
        drivers.push(
            `Token usage tinggi: rata-rata ${stats.avg_tokens_per_call} tokens per call (threshold: 3000)`
        );
    }

    // High call volume
    if (stats.total_calls > 100) {
        drivers.push(
            `Volume call tinggi: ${stats.total_calls} AI calls (dapat dikurangi dengan caching)`
        );
    }

    // Duplicate calls
    if (stats.duplicate_calls > 10) {
        drivers.push(
            `Duplicate calls: ${stats.duplicate_calls} calls dengan context identik dalam 1 jam`
        );
    }

    return drivers;
}

/**
 * Identify safe optimization opportunities
 */
function identifySafeOptimizations(stats: AIUsageStats): string[] {
    const optimizations: string[] = [];

    // Caching opportunity
    if (stats.cacheable_calls > 20) {
        const savingsPercent = ((stats.cacheable_calls / stats.total_calls) * 100).toFixed(0);
        optimizations.push(
            `CACHING: Implementasi cache untuk context yang sama dapat menghemat ${savingsPercent}% biaya (${stats.cacheable_calls} dari ${stats.total_calls} calls)`
        );
    }

    // Reduce duplicate calls
    if (stats.duplicate_calls > 10) {
        const savingsPercent = ((stats.duplicate_calls / stats.total_calls) * 100).toFixed(0);
        optimizations.push(
            `DEDUPLICATION: Hindari duplicate calls dalam 1 jam dapat menghemat ${savingsPercent}% biaya (${stats.duplicate_calls} duplicate calls terdeteksi)`
        );
    }

    // Token optimization
    if (stats.avg_tokens_per_call > 3000) {
        optimizations.push(
            `TOKEN OPTIMIZATION: Kurangi historical data dari 90 hari ke 30 hari dapat menghemat ~20% token tanpa mengurangi kualitas explanation`
        );
    }

    // Batch processing
    if (stats.total_calls > 50) {
        optimizations.push(
            `BATCH PROCESSING: Batch multiple decisions dalam single AI call dapat menghemat ~30% overhead cost`
        );
    }

    // Prompt optimization
    if (stats.avg_tokens_per_call > 2500) {
        optimizations.push(
            `PROMPT OPTIMIZATION: Simplifikasi prompt template tanpa mengurangi kualitas output dapat menghemat ~15% token`
        );
    }

    return optimizations;
}

/**
 * Build cost summary in Indonesian
 */
function buildCostSummary(
    stats: AIUsageStats,
    dailyCost: number,
    optimizationCount: number
): string {
    const monthlyCost = dailyCost * 30;

    let summary = `Biaya AI harian: $${dailyCost.toFixed(2)} (~Rp ${(dailyCost * 15000).toLocaleString('id-ID')}/hari, Rp ${(monthlyCost * 15000).toLocaleString('id-ID')}/bulan). `;
    summary += `Total ${stats.total_calls} AI calls dengan rata-rata ${stats.avg_tokens_per_call} tokens per call. `;

    if (optimizationCount > 0) {
        summary += `Terdapat ${optimizationCount} peluang optimasi yang aman tanpa mengurangi kualitas.`;
    } else {
        summary += `Tidak ada optimasi yang diperlukan - biaya sudah efisien.`;
    }

    return summary;
}

/**
 * Calculate potential savings from optimizations
 */
export function calculatePotentialSavings(
    currentDailyCost: number,
    optimizations: string[]
): {
    daily_savings: number;
    monthly_savings: number;
    annual_savings: number;
} {
    let totalSavingsPercent = 0;

    for (const opt of optimizations) {
        if (opt.includes('CACHING')) {
            const match = opt.match(/(\d+)%/);
            if (match) totalSavingsPercent += parseInt(match[1]) * 0.8; // 80% cache hit rate
        } else if (opt.includes('DEDUPLICATION')) {
            const match = opt.match(/(\d+)%/);
            if (match) totalSavingsPercent += parseInt(match[1]);
        } else if (opt.includes('TOKEN OPTIMIZATION')) {
            totalSavingsPercent += 20;
        } else if (opt.includes('BATCH PROCESSING')) {
            totalSavingsPercent += 30;
        } else if (opt.includes('PROMPT OPTIMIZATION')) {
            totalSavingsPercent += 15;
        }
    }

    // Cap at 70% max savings (conservative)
    totalSavingsPercent = Math.min(totalSavingsPercent, 70);

    const dailySavings = currentDailyCost * (totalSavingsPercent / 100);

    return {
        daily_savings: parseFloat(dailySavings.toFixed(2)),
        monthly_savings: parseFloat((dailySavings * 30).toFixed(2)),
        annual_savings: parseFloat((dailySavings * 365).toFixed(2))
    };
}

