// Enterprise Audit Export - CSV and PDF export with brand isolation
// CRITICAL: Time-range filtering, brand isolation enforced

import { prisma } from '@/lib/prisma';

/**
 * Audit export request
 */
export interface AuditExportRequest {
    brandId: string;
    startDate: Date;
    endDate: Date;
    format: 'csv' | 'pdf';
    includeExecutions?: boolean;
    includeApprovals?: boolean;
    includeOverrides?: boolean;
    includeRollbacks?: boolean;
}

/**
 * Export audit logs to CSV
 */
export async function exportAuditCSV(
    request: AuditExportRequest
): Promise<string> {
    // Fetch audit logs with brand isolation
    const logs = await fetchAuditLogs(request);

    // Build CSV header
    const header = [
        'Timestamp',
        'Event Type',
        'Performed By',
        'Rule ID',
        'Action ID',
        'Execution ID',
        'Status',
        'Risk Level',
        'Financial Impact',
        'Details'
    ].join(',');

    // Build CSV rows
    const rows = logs.map(log => {
        const metadata = log.metadata as any;

        return [
            log.timestamp.toISOString(),
            log.eventType,
            log.performedBy,
            metadata?.ruleId || '',
            metadata?.actionId || '',
            metadata?.executionId || '',
            metadata?.status || '',
            metadata?.riskLevel || '',
            metadata?.financialImpact || '',
            JSON.stringify(metadata).replace(/"/g, '""') // Escape quotes
        ].join(',');
    }).join('\n');

    return `${header}\n${rows}`;
}

