// ACHIERA Autonomous Analytics - Header Inference Engine
// 5-Layer Hybrid Inference: Keyword → Regex → Statistical → Platform → Manual

export type InferenceMethod = 'keyword' | 'regex' | 'statistical' | 'platform_heuristic' | 'manual';
export type DataType = 'string' | 'number' | 'date' | 'boolean';
export type CanonicalField =
    // Sales fields
    | 'transaction_date' | 'transaction_time' | 'order_id'
    | 'sku' | 'product_name' | 'product_category' | 'variant_name'
    | 'quantity' | 'unit_price' | 'total_amount' | 'discount_amount' | 'net_amount'
    | 'platform' | 'channel' | 'store_name'
    | 'customer_id' | 'customer_name' | 'customer_phone' | 'customer_email'
    | 'promotion_code' | 'promotion_name'
    | 'payment_method' | 'shipping_cost' | 'notes'
    // Ads fields
    | 'campaign_id' | 'campaign_name' | 'ad_set_id' | 'ad_set_name' | 'ad_id' | 'ad_name'
    | 'date' | 'impressions' | 'clicks' | 'spend' | 'conversions' | 'revenue'
    | 'reach' | 'frequency' | 'video_views' | 'engagement'
    | 'ctr' | 'cpc' | 'cpa' | 'roas';

export interface ColumnMapping {
    sourceColumnName: string;
    sourceColumnIndex: number;
    canonicalField: CanonicalField | null;
    inferenceMethod: InferenceMethod;
    confidence: number;
    dataType: DataType;
    sampleValues: any[];
}

export interface InferenceResult {
    mappings: ColumnMapping[];
    overallConfidence: number;
    blockingIssues: string[];
    warnings: string[];
}

// ============================================
// LAYER 1: KEYWORD DICTIONARY
// ============================================

const KEYWORD_MAPPINGS: Record<CanonicalField, string[]> = {
    // Transaction
    transaction_date: ['tanggal', 'date', 'tgl', 'transaction_date', 'order_date', 'waktu', 'time', 'datetime', 'created_at', 'timestamp', 'tgl_transaksi'],
    transaction_time: ['waktu', 'time', 'jam', 'hour'],
    order_id: ['order_id', 'no_order', 'nomor_order', 'invoice', 'no_invoice', 'transaction_id', 'receipt', 'kwitansi', 'no_pesanan'],

    // Product
    sku: ['sku', 'kode_produk', 'product_code', 'item_code', 'barcode', 'kode_barang'],
    product_name: ['produk', 'product', 'nama_produk', 'product_name', 'item', 'barang', 'nama_barang', 'item_name', 'description', 'deskripsi'],
    product_category: ['kategori', 'category', 'jenis', 'type', 'product_category'],
    variant_name: ['variasi', 'variant', 'varian', 'option', 'pilihan'],

    // Quantity & Pricing
    quantity: ['qty', 'quantity', 'jumlah', 'jml', 'amount', 'units', 'kuantitas'],
    unit_price: ['harga', 'price', 'harga_satuan', 'unit_price', 'price_per_unit', 'harga_asli'],
    total_amount: ['total', 'total_amount', 'total_harga', 'subtotal', 'amount', 'jumlah_total'],
    discount_amount: ['diskon', 'discount', 'potongan', 'discount_amount', 'cashback'],
    net_amount: ['net', 'net_amount', 'total_bersih', 'nett'],

    // Platform & Channel
    platform: ['platform', 'marketplace', 'channel', 'source', 'sumber', 'toko'],
    channel: ['channel', 'saluran', 'jalur'],
    store_name: ['toko', 'store', 'nama_toko', 'store_name', 'outlet'],

    // Customer
    customer_id: ['customer_id', 'id_pelanggan', 'user_id', 'member_id'],
    customer_name: ['nama', 'name', 'customer_name', 'nama_pelanggan', 'pembeli', 'buyer'],
    customer_phone: ['hp', 'phone', 'telepon', 'no_hp', 'nomor_hp', 'whatsapp', 'wa'],
    customer_email: ['email', 'e-mail', 'surel'],

    // Promotion
    promotion_code: ['kode_promo', 'promo_code', 'voucher', 'coupon', 'kode_voucher'],
    promotion_name: ['promo', 'promotion', 'nama_promo', 'promotion_name'],

    // Metadata
    payment_method: ['pembayaran', 'payment', 'metode_bayar', 'payment_method', 'cara_bayar'],
    shipping_cost: ['ongkir', 'shipping', 'biaya_kirim', 'shipping_cost', 'delivery_fee'],
    notes: ['catatan', 'notes', 'keterangan', 'remarks', 'note'],

    // Ads - Campaign
    campaign_id: ['campaign_id', 'id_kampanye'],
    campaign_name: ['campaign', 'kampanye', 'campaign_name', 'nama_kampanye'],
    ad_set_id: ['ad_set_id', 'adset_id'],
    ad_set_name: ['ad_set', 'adset', 'ad_set_name'],
    ad_id: ['ad_id', 'iklan_id'],
    ad_name: ['ad_name', 'nama_iklan', 'ad'],

    // Ads - Date
    date: ['date', 'tanggal', 'tgl', 'day'],

    // Ads - Metrics
    impressions: ['impressions', 'impresi', 'views', 'tayangan', 'reach', 'jangkauan'],
    clicks: ['clicks', 'klik', 'click', 'link_clicks'],
    spend: ['spend', 'cost', 'biaya', 'budget', 'pengeluaran', 'amount_spent', 'belanja'],
    conversions: ['conversions', 'konversi', 'purchases', 'pembelian'],
    revenue: ['revenue', 'pendapatan', 'sales', 'penjualan'],
    reach: ['reach', 'jangkauan'],
    frequency: ['frequency', 'frekuensi'],
    video_views: ['video_views', 'video_play'],
    engagement: ['engagement', 'keterlibatan', 'interactions'],

    // Ads - Calculated
    ctr: ['ctr', 'click_through_rate'],
    cpc: ['cpc', 'cost_per_click'],
    cpa: ['cpa', 'cost_per_action', 'cost_per_conversion'],
    roas: ['roas', 'return_on_ad_spend']
};

function matchKeyword(columnName: string): { field: CanonicalField | null; confidence: number } {
    const normalized = columnName.toLowerCase().trim().replace(/[_\s-]/g, '');

    for (const [field, keywords] of Object.entries(KEYWORD_MAPPINGS)) {
        for (const keyword of keywords) {
            const normalizedKeyword = keyword.toLowerCase().replace(/[_\s-]/g, '');

            // Exact match
            if (normalized === normalizedKeyword) {
                return { field: field as CanonicalField, confidence: 0.95 };
            }

            // Contains match
            if (normalized.includes(normalizedKeyword) || normalizedKeyword.includes(normalized)) {
                return { field: field as CanonicalField, confidence: 0.85 };
            }
        }
    }

    return { field: null, confidence: 0 };
}

// ============================================
// LAYER 2: REGEX PATTERNS
// ============================================

const REGEX_PATTERNS: Record<string, { pattern: RegExp; field: CanonicalField; confidence: number }> = {
    date: { pattern: /\d{4}-\d{2}-\d{2}|\d{2}\/\d{2}\/\d{4}|\d{2}-\d{2}-\d{4}/, field: 'transaction_date', confidence: 0.9 },
    sku: { pattern: /^[A-Z0-9]{6,}$/, field: 'sku', confidence: 0.85 },
    phone: { pattern: /^(\+62|62|0)[0-9]{9,12}$/, field: 'customer_phone', confidence: 0.9 },
    email: { pattern: /@[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}/, field: 'customer_email', confidence: 0.95 }
};

function matchRegex(sampleValues: any[]): { field: CanonicalField | null; confidence: number } {
    for (const [, { pattern, field, confidence }] of Object.entries(REGEX_PATTERNS)) {
        const matchCount = sampleValues.filter(v =>
            typeof v === 'string' && pattern.test(v)
        ).length;

        const matchRate = matchCount / sampleValues.length;

        if (matchRate > 0.7) {
            return { field, confidence: confidence * matchRate };
        }
    }

    return { field: null, confidence: 0 };
}

// ============================================
// LAYER 3: STATISTICAL INFERENCE
// ============================================

function inferFromStatistics(sampleValues: any[]): {
    dataType: DataType;
    likelyField: CanonicalField | null;
    confidence: number
} {
    // Filter out null/undefined
    const validSamples = sampleValues.filter(v => v !== null && v !== undefined);
    if (validSamples.length === 0) {
        return { dataType: 'string', likelyField: null, confidence: 0 };
    }

    // Check if numeric
    const numericSamples = validSamples.filter(v => !isNaN(Number(v)));
    const isNumeric = numericSamples.length / validSamples.length > 0.8;

    if (isNumeric) {
        const numbers = numericSamples.map(v => Number(v));
        const min = Math.min(...numbers);
        const max = Math.max(...numbers);
        const avg = numbers.reduce((sum, n) => sum + n, 0) / numbers.length;

        // Quantity detection (small integers)
        if (min >= 0 && max <= 1000 && numbers.every(n => Number.isInteger(n))) {
            return { dataType: 'number', likelyField: 'quantity', confidence: 0.75 };
        }

        // Price detection (larger numbers)
        if (min >= 1000 && max <= 100000000) {
            return { dataType: 'number', likelyField: 'unit_price', confidence: 0.7 };
        }

        // Percentage detection
        if (min >= 0 && max <= 100) {
            return { dataType: 'number', likelyField: null, confidence: 0.6 };
        }

        // Large numbers (impressions, clicks)
        if (max > 1000000) {
            return { dataType: 'number', likelyField: 'impressions', confidence: 0.65 };
        }

        return { dataType: 'number', likelyField: null, confidence: 0.5 };
    }

    // Cardinality analysis for strings
    const uniqueCount = new Set(validSamples).size;
    const cardinality = uniqueCount / validSamples.length;

    // High cardinality = likely ID
    if (cardinality > 0.9) {
        return { dataType: 'string', likelyField: 'order_id', confidence: 0.7 };
    }

    // Low cardinality = likely category
    if (cardinality < 0.1) {
        return { dataType: 'string', likelyField: 'product_category', confidence: 0.65 };
    }

    return { dataType: 'string', likelyField: null, confidence: 0.4 };
}

// ============================================
// LAYER 4: PLATFORM HEURISTICS
// ============================================

interface PlatformHeuristic {
    fileNamePattern: RegExp;
    requiredColumns: string[];
    columnMappings: Record<string, CanonicalField>;
}

const PLATFORM_HEURISTICS: Record<string, PlatformHeuristic> = {
    shopee: {
        fileNamePattern: /shopee|spee/i,
        requiredColumns: ['No. Pesanan', 'Nama Produk'],
        columnMappings: {
            'No. Pesanan': 'order_id',
            'Nama Produk': 'product_name',
            'Variasi': 'variant_name',
            'Harga Asli': 'unit_price',
            'Jumlah': 'quantity',
            'Total Harga Produk': 'total_amount',
            'Nama Pembeli': 'customer_name',
            'No. Telepon': 'customer_phone'
        }
    },
    tokopedia: {
        fileNamePattern: /tokopedia|tokped/i,
        requiredColumns: ['Invoice', 'Nama Barang'],
        columnMappings: {
            'Invoice': 'order_id',
            'Nama Barang': 'product_name',
            'Jumlah': 'quantity',
            'Harga': 'unit_price',
            'Total': 'total_amount'
        }
    },
    meta: {
        fileNamePattern: /facebook|meta|instagram/i,
        requiredColumns: ['Campaign name', 'Impressions', 'Clicks'],
        columnMappings: {
            'Campaign name': 'campaign_name',
            'Campaign ID': 'campaign_id',
            'Impressions': 'impressions',
            'Clicks': 'clicks',
            'Amount spent (IDR)': 'spend',
            'Amount spent': 'spend',
            'Purchases': 'conversions',
            'Purchase conversion value': 'revenue'
        }
    },
    google: {
        fileNamePattern: /google|adwords/i,
        requiredColumns: ['Campaign', 'Impressions', 'Clicks'],
        columnMappings: {
            'Campaign': 'campaign_name',
            'Campaign ID': 'campaign_id',
            'Impressions': 'impressions',
            'Clicks': 'clicks',
            'Cost': 'spend',
            'Conversions': 'conversions',
            'Conv. value': 'revenue'
        }
    }
};

function matchPlatformHeuristic(
    fileName: string,
    headers: string[]
): { platform: string | null; mappings: Record<string, CanonicalField>; confidence: number } {
    for (const [platform, heuristic] of Object.entries(PLATFORM_HEURISTICS)) {
        // Check file name pattern
        if (heuristic.fileNamePattern.test(fileName)) {
            // Check if required columns present
            const hasRequiredColumns = heuristic.requiredColumns.every(req =>
                headers.some(h => h.toLowerCase().includes(req.toLowerCase()))
            );

            if (hasRequiredColumns) {
                return { platform, mappings: heuristic.columnMappings, confidence: 0.95 };
            }
        }
    }

    return { platform: null, mappings: {}, confidence: 0 };
}

// ============================================
// MAIN INFERENCE ENGINE
// ============================================

export async function inferHeaders(
    fileName: string,
    headers: string[],
    sampleRows: any[][]
): Promise<InferenceResult> {
    const mappings: ColumnMapping[] = [];

    // Try platform heuristic first
    const platformMatch = matchPlatformHeuristic(fileName, headers);

    for (let i = 0; i < headers.length; i++) {
        const columnName = headers[i];
        const sampleValues = sampleRows.map(row => row[i]);

        let mapping: ColumnMapping = {
            sourceColumnName: columnName,
            sourceColumnIndex: i,
            canonicalField: null,
            inferenceMethod: 'keyword',
            confidence: 0,
            dataType: 'string',
            sampleValues: sampleValues.slice(0, 5)
        };

        // Layer 4: Platform heuristic (highest priority)
        if (platformMatch.platform && platformMatch.mappings[columnName]) {
            mapping.canonicalField = platformMatch.mappings[columnName];
            mapping.inferenceMethod = 'platform_heuristic';
            mapping.confidence = platformMatch.confidence;
            mapping.dataType = inferDataType(sampleValues);
            mappings.push(mapping);
            continue;
        }

        // Layer 1: Keyword matching
        const keywordMatch = matchKeyword(columnName);
        if (keywordMatch.field && keywordMatch.confidence > 0.8) {
            mapping.canonicalField = keywordMatch.field;
            mapping.inferenceMethod = 'keyword';
            mapping.confidence = keywordMatch.confidence;
            mapping.dataType = inferDataType(sampleValues);
            mappings.push(mapping);
            continue;
        }

        // Layer 2: Regex pattern matching
        const regexMatch = matchRegex(sampleValues);
        if (regexMatch.field && regexMatch.confidence > 0.7) {
            mapping.canonicalField = regexMatch.field;
            mapping.inferenceMethod = 'regex';
            mapping.confidence = regexMatch.confidence;
            mapping.dataType = inferDataType(sampleValues);
            mappings.push(mapping);
            continue;
        }

        // Layer 3: Statistical inference
        const statsInference = inferFromStatistics(sampleValues);
        if (statsInference.likelyField && statsInference.confidence > 0.6) {
            mapping.canonicalField = statsInference.likelyField;
            mapping.inferenceMethod = 'statistical';
            mapping.confidence = statsInference.confidence;
            mapping.dataType = statsInference.dataType;
            mappings.push(mapping);
            continue;
        }

        // No match found - use keyword with lower confidence
        if (keywordMatch.field) {
            mapping.canonicalField = keywordMatch.field;
            mapping.confidence = keywordMatch.confidence;
            mapping.dataType = inferDataType(sampleValues);
        }

        mappings.push(mapping);
    }

    // Calculate overall confidence and identify issues
    return calculateConfidence(mappings);
}

function inferDataType(sampleValues: any[]): DataType {
    const validSamples = sampleValues.filter(v => v !== null && v !== undefined);
    if (validSamples.length === 0) return 'string';

    // Check numeric
    const numericCount = validSamples.filter(v => !isNaN(Number(v))).length;
    if (numericCount / validSamples.length > 0.8) return 'number';

    // Check date
    const datePattern = /\d{4}-\d{2}-\d{2}|\d{2}\/\d{2}\/\d{4}/;
    const dateCount = validSamples.filter(v =>
        typeof v === 'string' && datePattern.test(v)
    ).length;
    if (dateCount / validSamples.length > 0.8) return 'date';

    // Check boolean
    const booleanValues = ['true', 'false', 'yes', 'no', '1', '0'];
    const booleanCount = validSamples.filter(v =>
        booleanValues.includes(String(v).toLowerCase())
    ).length;
    if (booleanCount / validSamples.length > 0.8) return 'boolean';

    return 'string';
}

function calculateConfidence(mappings: ColumnMapping[]): InferenceResult {
    const requiredFields: CanonicalField[] = [
        'transaction_date',
        'product_name',
        'quantity',
        'unit_price'
    ];

    const blockingIssues: string[] = [];
    const warnings: string[] = [];

    // Check required fields
    for (const field of requiredFields) {
        const mapping = mappings.find(m => m.canonicalField === field);
        if (!mapping) {
            blockingIssues.push(`Missing required field: ${field}`);
        } else if (mapping.confidence < 0.5) {
            blockingIssues.push(`Low confidence for required field: ${field} (${mapping.confidence.toFixed(2)})`);
        }
    }

    // Check optional fields with low confidence
    for (const mapping of mappings) {
        if (mapping.canonicalField && !requiredFields.includes(mapping.canonicalField)) {
            if (mapping.confidence < 0.6) {
                warnings.push(`Low confidence for ${mapping.canonicalField}: ${mapping.confidence.toFixed(2)}`);
            }
        }
    }

    // Calculate overall confidence
    const avgConfidence = mappings.reduce((sum, m) => sum + m.confidence, 0) / mappings.length;
    const overallConfidence = blockingIssues.length > 0 ? 0 : avgConfidence;

    return {
        mappings,
        overallConfidence,
        blockingIssues,
        warnings
    };
}

// ACHIERA Autonomous Analytics - Daily Ads Aggregation
// Aggregates ads performance facts into daily snapshots

import { prisma } from '@/lib/prisma';

/**
 * Run daily ads aggregation
 */
export async function runDailyAdsAggregation(date?: Date): Promise<void> {
    const targetDate = date || new Date(Date.now() - 24 * 60 * 60 * 1000); // Yesterday
    targetDate.setHours(0, 0, 0, 0);

    console.log(`[Aggregation] Running daily ads aggregation for ${targetDate.toISOString().split('T')[0]}`);

    const brands = await prisma.brand.findMany({
        where: { isActive: true },
        select: { id: true, name: true }
    });

    for (const brand of brands) {
        try {
            // Get all ads facts for the day, grouped by platform
            const facts = await prisma.adsPerformanceFact.findMany({
                where: {
                    brandId: brand.id,
                    dateKey: targetDate
                }
            });

            // Group by platform
            const platformMetrics: Record<string, any> = {};

            for (const fact of facts) {
                if (!platformMetrics[fact.platform]) {
                    platformMetrics[fact.platform] = {
                        impressions: BigInt(0),
                        clicks: 0,
                        spend: 0,
                        conversions: 0,
                        revenue: 0,
                        campaigns: []
                    };
                }

                const pm = platformMetrics[fact.platform];
                pm.impressions += fact.impressions;
                pm.clicks += fact.clicks;
                pm.spend += Number(fact.spend);
                pm.conversions += fact.conversions;
                pm.revenue += Number(fact.revenue);
                pm.campaigns.push({
                    campaignId: fact.campaignId,
                    campaignName: fact.campaignName,
                    spend: Number(fact.spend),
                    roas: Number(fact.roas)
                });
            }

            // Create aggregations for each platform
            for (const [platform, metrics] of Object.entries(platformMetrics)) {
                const ctr = Number(metrics.impressions) > 0
                    ? metrics.clicks / Number(metrics.impressions)
                    : 0;
                const cpc = metrics.clicks > 0
                    ? metrics.spend / metrics.clicks
                    : 0;
                const cpa = metrics.conversions > 0
                    ? metrics.spend / metrics.conversions
                    : 0;
                const roas = metrics.spend > 0
                    ? metrics.revenue / metrics.spend
                    : 0;

                await prisma.aggDailyAds.upsert({
                    where: {
                        unique_brand_date_platform: {
                            brandId: brand.id,
                            snapshotDate: targetDate,
                            platform
                        }
                    },
                    create: {
                        brandId: brand.id,
                        snapshotDate: targetDate,
                        platform,
                        impressions: metrics.impressions,
                        clicks: metrics.clicks,
                        spend: metrics.spend,
                        conversions: metrics.conversions,
                        revenue: metrics.revenue,
                        ctr,
                        cpc,
                        cpa,
                        roas,
                        campaigns: metrics.campaigns
                    },
                    update: {
                        impressions: metrics.impressions,
                        clicks: metrics.clicks,
                        spend: metrics.spend,
                        conversions: metrics.conversions,
                        revenue: metrics.revenue,
                        ctr,
                        cpc,
                        cpa,
                        roas,
                        campaigns: metrics.campaigns
                    }
                });
            }

            console.log(`[Aggregation] ✓ ${brand.name}: ${Object.keys(platformMetrics).length} platforms aggregated`);
        } catch (error) {
            console.error(`[Aggregation] ✗ Failed for brand ${brand.name}:`, error);
        }
    }

    console.log('[Aggregation] Daily ads aggregation complete');
}

// CLI execution
if (require.main === module) {
    runDailyAdsAggregation()
        .then(() => process.exit(0))
        .catch(error => {
            console.error('Aggregation failed:', error);
            process.exit(1);
        });
}

// Autonomy Gate - Control Level 3 execution access
// CRITICAL: Multi-layer checks, force downgrade if ANY fails

import { prisma } from '@/lib/prisma';
import { calculateTrustScore } from '../trust/trust-score';
import { calculateTrustMetrics } from '../trust/trust-metrics';

/**
 * Autonomy gate result
 */
export interface AutonomyGateResult {
    allowed: boolean;
    effective_level: 0 | 1 | 2 | 3;
    checks: {
        trust_score: { passed: boolean; score: number; threshold: number };
        risk_exposure: { passed: boolean; current: number; limit: number };
        cfo_whitelist: { passed: boolean; whitelisted: boolean };
        owner_toggle: { passed: boolean; enabled: boolean };
        emergency_readiness: { passed: boolean; rollback_available: boolean };
    };
    downgrade_reason?: string;
}

/**
 * Check if Level 3 execution is allowed
 */
export async function checkAutonomyGate(
    brandId: string,
    ruleId: string,
    requestedLevel: 0 | 1 | 2 | 3
): Promise<AutonomyGateResult> {
    // If requesting Level 0-2, allow (handled by existing approval system)
    if (requestedLevel <= 2) {
        return {
            allowed: true,
            effective_level: requestedLevel,
            checks: {
                trust_score: { passed: true, score: 0, threshold: 0 },
                risk_exposure: { passed: true, current: 0, limit: 0 },
                cfo_whitelist: { passed: true, whitelisted: false },
                owner_toggle: { passed: true, enabled: false },
                emergency_readiness: { passed: true, rollback_available: false }
            }
        };
    }

    // Level 3 requires all checks to pass
    const checks = {
        trust_score: await checkTrustScore(brandId),
        risk_exposure: await checkRiskExposure(brandId),
        cfo_whitelist: await checkCFOWhitelist(brandId, ruleId),
        owner_toggle: await checkOwnerToggle(brandId),
        emergency_readiness: await checkEmergencyReadiness(brandId)
    };

    // Determine if all checks passed
    const allPassed = Object.values(checks).every(check => check.passed);

    if (!allPassed) {
        // Find first failed check
        const failedCheck = Object.entries(checks).find(([_, check]) => !check.passed);
        const downgradeReason = failedCheck
            ? `Level 3 blocked: ${failedCheck[0]} check failed`
            : 'Level 3 blocked: unknown reason';

        return {
            allowed: false,
            effective_level: 2, // Force downgrade to Level 2
            checks,
            downgrade_reason: downgradeReason
        };
    }

    return {
        allowed: true,
        effective_level: 3,
        checks
    };
}

/**
 * Check 1: Trust Score
 * Requirement: Trust score >= 70/100
 */
async function checkTrustScore(
    brandId: string
): Promise<{ passed: boolean; score: number; threshold: number }> {
    const threshold = 70;

    // Calculate trust metrics for last 7 days
    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - 7);

    const metrics = await calculateTrustMetrics(brandId, startDate, endDate);
    const trustScore = calculateTrustScore(metrics);

    return {
        passed: trustScore.overall_score >= threshold,
        score: trustScore.overall_score,
        threshold
    };
}

/**
 * Check 2: Risk Exposure
 * Requirement: Current risk exposure < daily limit
 */
async function checkRiskExposure(
    brandId: string
): Promise<{ passed: boolean; current: number; limit: number }> {
    const dailyLimit = 5000000; // Rp 5 juta per day

    // Calculate today's risk exposure
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const executions = await prisma.executionLog.findMany({
        where: {
            brandId,
            executedAt: { gte: today },
            executionStatus: { in: ['success', 'pending'] }
        }
    });

    const currentExposure = executions.reduce((sum, e) => {
        const auditData = e.auditData as any;
        const estimatedImpact = auditData?.estimatedImpact?.amount || 0;
        return sum + Math.abs(estimatedImpact);
    }, 0);

    return {
        passed: currentExposure < dailyLimit,
        current: currentExposure,
        limit: dailyLimit
    };
}

/**
 * Check 3: CFO Whitelist
 * Requirement: Rule must be whitelisted for Level 3
 */
async function checkCFOWhitelist(
    brandId: string,
    ruleId: string
): Promise<{ passed: boolean; whitelisted: boolean }> {
    // Check if rule is whitelisted for Level 3
    const whitelist = await prisma.level3Whitelist.findFirst({
        where: {
            brandId,
            ruleId,
            isActive: true
        }
    });

    return {
        passed: whitelist !== null,
        whitelisted: whitelist !== null
    };
}

/**
 * Check 4: Owner Toggle
 * Requirement: Brand owner has enabled Level 3
 */
async function checkOwnerToggle(
    brandId: string
): Promise<{ passed: boolean; enabled: boolean }> {
    const brand = await prisma.brand.findUnique({
        where: { id: brandId }
    });

    const level3Enabled = (brand?.settings as any)?.autonomy?.level3Enabled || false;

    return {
        passed: level3Enabled,
        enabled: level3Enabled
    };
}

/**
 * Check 5: Emergency Readiness
 * Requirement: Rollback system must be operational
 */
async function checkEmergencyReadiness(
    brandId: string
): Promise<{ passed: boolean; rollback_available: boolean }> {
    // Check if rollback system is operational
    // by verifying recent snapshots exist
    const recentSnapshot = await prisma.executionSnapshot.findFirst({
        where: {
            brandId,
            createdAt: {
                gte: new Date(Date.now() - 24 * 60 * 60 * 1000) // Last 24 hours
            }
        }
    });

    return {
        passed: recentSnapshot !== null,
        rollback_available: recentSnapshot !== null
    };
}

/**
 * Log autonomy gate decision
 */
export async function logAutonomyGateDecision(
    brandId: string,
    ruleId: string,
    result: AutonomyGateResult
): Promise<void> {
    await prisma.auditLog.create({
        data: {
            brandId,
            eventType: 'autonomy_gate_check',
            performedBy: 'system',
            timestamp: new Date(),
            metadata: {
                ruleId,
                allowed: result.allowed,
                effective_level: result.effective_level,
                checks: result.checks,
                downgrade_reason: result.downgrade_reason
            }
        }
    });
}

// Executive Override - Kill switch and manual controls for Level 3
// CRITICAL: Instant effect, full audit trail, CFO-grade controls

import { prisma } from '@/lib/prisma';

/**
 * Kill switch - Disable Level 3 globally for brand
 */
export async function killSwitchLevel3(
    brandId: string,
    performedBy: string,
    reason: string
): Promise<{
    success: boolean;
    affected_rules: number;
    cancelled_executions: number;
}> {
    try {
        // Step 1: Disable Level 3 in brand settings
        await prisma.brand.update({
            where: { id: brandId },
            data: {
                settings: {
                    ...((await prisma.brand.findUnique({ where: { id: brandId } }))?.settings as any),
                    autonomy: {
                        level3Enabled: false,
                        disabledAt: new Date(),
                        disabledBy: performedBy,
                        disabledReason: reason
                    }
                }
            }
        });

        // Step 2: Deactivate all Level 3 whitelisted rules
        const affectedRules = await prisma.level3Whitelist.updateMany({
            where: {
                brandId,
                isActive: true
            },
            data: {
                isActive: false,
                deactivatedAt: new Date(),
                deactivatedBy: performedBy
            }
        });

        // Step 3: Cancel pending Level 3 executions
        const cancelledExecutions = await prisma.executionLog.updateMany({
            where: {
                brandId,
                executionStatus: 'pending',
                auditData: {
                    path: ['autonomyLevel'],
                    equals: 3
                }
            },
            data: {
                executionStatus: 'cancelled',
                cancelledAt: new Date(),
                cancelledBy: performedBy
            }
        });

        // Step 4: Log kill switch activation
        await prisma.auditLog.create({
            data: {
                brandId,
                eventType: 'level3_kill_switch',
                performedBy,
                timestamp: new Date(),
                metadata: {
                    reason,
                    affected_rules: affectedRules.count,
                    cancelled_executions: cancelledExecutions.count
                }
            }
        });

        return {
            success: true,
            affected_rules: affectedRules.count,
            cancelled_executions: cancelledExecutions.count
        };

    } catch (error) {
        console.error('[KILL SWITCH] Failed:', error);
        throw error;
    }
}

/**
 * Manual downgrade - Downgrade specific rule from Level 3 to Level 2
 */
export async function manualDowngradeRule(
    brandId: string,
    ruleId: string,
    performedBy: string,
    reason: string
): Promise<{
    success: boolean;
    previous_level: number;
    new_level: number;
}> {
    try {
        // Step 1: Remove from Level 3 whitelist
        await prisma.level3Whitelist.updateMany({
            where: {
                brandId,
                ruleId,
                isActive: true
            },
            data: {
                isActive: false,
                deactivatedAt: new Date(),
                deactivatedBy: performedBy
            }
        });

        // Step 2: Update rule autonomy level
        const rule = await prisma.decisionRule.update({
            where: { ruleId },
            data: {
                autonomyLevel: 2, // Force downgrade to Level 2
                lastModifiedAt: new Date(),
                lastModifiedBy: performedBy
            }
        });

        // Step 3: Cancel pending executions for this rule
        await prisma.executionLog.updateMany({
            where: {
                brandId,
                ruleId,
                executionStatus: 'pending'
            },
            data: {
                executionStatus: 'cancelled',
                cancelledAt: new Date(),
                cancelledBy: performedBy
            }
        });

        // Step 4: Log downgrade
        await prisma.auditLog.create({
            data: {
                brandId,
                eventType: 'rule_downgraded',
                performedBy,
                timestamp: new Date(),
                metadata: {
                    ruleId,
                    previous_level: 3,
                    new_level: 2,
                    reason
                }
            }
        });

        return {
            success: true,
            previous_level: 3,
            new_level: 2
        };

    } catch (error) {
        console.error('[MANUAL DOWNGRADE] Failed:', error);
        throw error;
    }
}

/**
 * Get full execution trace
 */
export async function getExecutionTrace(
    executionId: string
): Promise<{
    execution: any;
    snapshot: any;
    audit_trail: any[];
    rollback_history: any[];
}> {
    // Fetch execution
    const execution = await prisma.executionLog.findUnique({
        where: { id: executionId },
        include: {
            snapshot: true
        }
    });

    if (!execution) {
        throw new Error(`Execution not found: ${executionId}`);
    }

    // Fetch audit trail
    const auditTrail = await prisma.auditLog.findMany({
        where: {
            brandId: execution.brandId,
            metadata: {
                path: ['executionId'],
                equals: executionId
            }
        },
        orderBy: { timestamp: 'asc' }
    });

    // Fetch rollback history
    const rollbackHistory = await prisma.auditLog.findMany({
        where: {
            brandId: execution.brandId,
            eventType: 'rollback_executed',
            metadata: {
                path: ['executionId'],
                equals: executionId
            }
        },
        orderBy: { timestamp: 'asc' }
    });

    return {
        execution,
        snapshot: execution.snapshot,
        audit_trail: auditTrail,
        rollback_history: rollbackHistory
    };
}

/**
 * Emergency pause - Pause all autonomous execution
 */
export async function emergencyPause(
    brandId: string,
    performedBy: string,
    reason: string
): Promise<{
    success: boolean;
    paused_rules: number;
    cancelled_executions: number;
}> {
    try {
        // Step 1: Disable all autonomy levels
        await prisma.brand.update({
            where: { id: brandId },
            data: {
                settings: {
                    ...((await prisma.brand.findUnique({ where: { id: brandId } }))?.settings as any),
                    autonomy: {
                        level1Enabled: false,
                        level2Enabled: false,
                        level3Enabled: false,
                        emergencyPaused: true,
                        pausedAt: new Date(),
                        pausedBy: performedBy,
                        pausedReason: reason
                    }
                }
            }
        });

        // Step 2: Deactivate all rules
        const pausedRules = await prisma.decisionRule.updateMany({
            where: {
                brandId,
                isActive: true
            },
            data: {
                isActive: false,
                lastModifiedAt: new Date(),
                lastModifiedBy: performedBy
            }
        });

        // Step 3: Cancel all pending executions
        const cancelledExecutions = await prisma.executionLog.updateMany({
            where: {
                brandId,
                executionStatus: 'pending'
            },
            data: {
                executionStatus: 'cancelled',
                cancelledAt: new Date(),
                cancelledBy: performedBy
            }
        });

        // Step 4: Log emergency pause
        await prisma.auditLog.create({
            data: {
                brandId,
                eventType: 'emergency_pause',
                performedBy,
                timestamp: new Date(),
                metadata: {
                    reason,
                    paused_rules: pausedRules.count,
                    cancelled_executions: cancelledExecutions.count
                }
            }
        });

        return {
            success: true,
            paused_rules: pausedRules.count,
            cancelled_executions: cancelledExecutions.count
        };

    } catch (error) {
        console.error('[EMERGENCY PAUSE] Failed:', error);
        throw error;
    }
}

// Guarded Executor - Level 3 execution with atomic rollback
// CRITICAL: Pre-execution snapshot, idempotent, <60s rollback SLA

import { v4 as uuidv4 } from 'uuid';
import { prisma } from '@/lib/prisma';
import { RuleEvaluationResult } from '../types/decision';

/**
 * Execution result
 */
export interface GuardedExecutionResult {
    executionId: string;
    status: 'success' | 'failed' | 'rolled_back';
    snapshotId: string;
    executedAt: Date;
    rollbackAvailable: boolean;
    rollbackSLA: number; // seconds
    auditTrail: string[];
}

/**
 * Execute with guarded protection
 */
export async function executeGuarded(
    brandId: string,
    ruleEvaluation: RuleEvaluationResult,
    actionParams: any
): Promise<GuardedExecutionResult> {
    const executionId = uuidv4();
    const auditTrail: string[] = [];

    try {
        // Step 1: Create pre-execution snapshot
        auditTrail.push(`[${new Date().toISOString()}] Creating pre-execution snapshot`);
        const snapshotId = await createPreExecutionSnapshot(brandId, ruleEvaluation);
        auditTrail.push(`[${new Date().toISOString()}] Snapshot created: ${snapshotId}`);

        // Step 2: Verify snapshot integrity
        auditTrail.push(`[${new Date().toISOString()}] Verifying snapshot integrity`);
        const snapshotValid = await verifySnapshot(snapshotId);
        if (!snapshotValid) {
            throw new Error('Snapshot verification failed');
        }
        auditTrail.push(`[${new Date().toISOString()}] Snapshot verified`);

        // Step 3: Execute action (idempotent)
        auditTrail.push(`[${new Date().toISOString()}] Executing action: ${ruleEvaluation.action.actionId}`);
        const executionResult = await executeAction(
            brandId,
            ruleEvaluation.action.actionId,
            actionParams
        );
        auditTrail.push(`[${new Date().toISOString()}] Action executed successfully`);

        // Step 4: Log execution
        await logExecution(brandId, executionId, ruleEvaluation, snapshotId, 'success');
        auditTrail.push(`[${new Date().toISOString()}] Execution logged`);

        // Step 5: Schedule auto-rollback (if configured)
        const autoRollbackHours = ruleEvaluation.action.autoRollbackHours;
        if (autoRollbackHours) {
            await scheduleAutoRollback(executionId, autoRollbackHours);
            auditTrail.push(`[${new Date().toISOString()}] Auto-rollback scheduled: ${autoRollbackHours}h`);
        }

        return {
            executionId,
            status: 'success',
            snapshotId,
            executedAt: new Date(),
            rollbackAvailable: true,
            rollbackSLA: 60, // 60 seconds
            auditTrail
        };

    } catch (error) {
        auditTrail.push(`[${new Date().toISOString()}] Execution failed: ${error.message}`);

        // Log failure
        await logExecution(brandId, executionId, ruleEvaluation, null, 'failed');

        throw error;
    }
}

/**
 * Create pre-execution snapshot
 */
async function createPreExecutionSnapshot(
    brandId: string,
    ruleEvaluation: RuleEvaluationResult
): Promise<string> {
    const snapshotId = uuidv4();

