/**
 * Schedule auto-rollback
 */
export async function scheduleAutoRollback(
    executionId: string,
    hoursUntilRollback: number
): Promise<void> {
    const rollbackAt = new Date(Date.now() + hoursUntilRollback * 60 * 60 * 1000);

    await prisma.scheduledRollback.create({
        data: {
            executionId,
            scheduledAt: rollbackAt,
            reason: 'auto_rollback_timer',
            status: 'pending'
        }
    });

    console.log(`[ROLLBACK] Scheduled auto-rollback for execution ${executionId} at ${rollbackAt.toISOString()}`);
}

/**
 * Process pending auto-rollbacks (should be called by cron job)
 */
export async function processPendingRollbacks(): Promise<void> {
    const pendingRollbacks = await prisma.scheduledRollback.findMany({
        where: {
            status: 'pending',
            scheduledAt: {
                lte: new Date()
            }
        }
    });

    for (const rollback of pendingRollbacks) {
        console.log(`[ROLLBACK] Processing auto-rollback for execution ${rollback.executionId}`);

        const result = await executeRollback(rollback.executionId, 'auto');

        await prisma.scheduledRollback.update({
            where: { id: rollback.id },
            data: {
                status: result.success ? 'completed' : 'failed',
                executedAt: new Date(),
                error: result.error
            }
        });
    }
}

/**
 * Cancel scheduled rollback
 */
export async function cancelScheduledRollback(executionId: string): Promise<void> {
    await prisma.scheduledRollback.updateMany({
        where: {
            executionId,
            status: 'pending'
        },
        data: {
            status: 'cancelled',
            executedAt: new Date()
        }
    });
}

// Safety Gates - Reusable safety checks for autonomous execution
// All gates return explicit BLOCK reasons and are logged

import { prisma } from '@/lib/prisma';
import { SafetyCheckResult, RuleDefinition, AutonomyLevel } from './types/decision';

export interface BrandAutonomyPolicy {
    enabled: boolean;
    maxAutonomyLevel: AutonomyLevel;
    confidenceThreshold: number;
    blackoutPeriods: BlackoutPeriod[];
    maxActionsPerDay: number;
}

export interface BlackoutPeriod {
    startTime: string; // HH:mm
    endTime: string;
    timezone: string;
    reason: string;
}

const DEFAULT_COOLDOWN_MINUTES = 60;
const DEFAULT_TARGET_COOLDOWN_MINUTES = 120;

/**
 * Check if action is in cooldown period
 */
export async function checkCooldown(
    brandId: string,
    actionId: string,
    targetId?: string
): Promise<SafetyCheckResult> {
    // Check same action cooldown
    const lastExecution = await prisma.executionLog.findFirst({
        where: {
            brandId,
            actionId,
            executionStatus: 'success'
        },
        orderBy: { executedAt: 'desc' }
    });

    if (lastExecution) {
        const minutesSince = (Date.now() - lastExecution.executedAt.getTime()) / 60000;
        if (minutesSince < DEFAULT_COOLDOWN_MINUTES) {
            return {
                gateName: 'Cooldown Check',
                passed: false,
                reason: `Action ${actionId} in cooldown. ${Math.ceil(DEFAULT_COOLDOWN_MINUTES - minutesSince)} minutes remaining`,
                timestamp: new Date()
            };
        }
    }

    // Check same target cooldown if targetId provided
    if (targetId) {
        const lastTargetExecution = await prisma.executionLog.findFirst({
            where: {
                brandId,
                auditData: {
                    path: ['targetId'],
                    equals: targetId
                }
            },
            orderBy: { executedAt: 'desc' }
        });

        if (lastTargetExecution) {
            const minutesSince = (Date.now() - lastTargetExecution.executedAt.getTime()) / 60000;
            if (minutesSince < DEFAULT_TARGET_COOLDOWN_MINUTES) {
                return {
                    gateName: 'Target Cooldown Check',
                    passed: false,
                    reason: `Target ${targetId} in cooldown. ${Math.ceil(DEFAULT_TARGET_COOLDOWN_MINUTES - minutesSince)} minutes remaining`,
                    timestamp: new Date()
                };
            }
        }
    }

    return {
        gateName: 'Cooldown Check',
        passed: true,
        timestamp: new Date()
    };
}

/**
 * Check if daily execution cap is reached
 */
export async function checkDailyCap(
    brandId: string,
    actionId: string,
    maxExecutionsPerDay: number
): Promise<SafetyCheckResult> {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const executionsToday = await prisma.executionLog.count({
        where: {
            brandId,
            actionId,
            executedAt: {
                gte: today
            },
            executionStatus: 'success'
        }
    });

    if (executionsToday >= maxExecutionsPerDay) {
        return {
            gateName: 'Daily Cap Check',
            passed: false,
            reason: `Daily limit reached: ${executionsToday}/${maxExecutionsPerDay} executions`,
            timestamp: new Date()
        };
    }

    return {
        gateName: 'Daily Cap Check',
        passed: true,
        timestamp: new Date()
    };
}

/**
 * Check if current time is in blackout period
 */
export function checkBlackout(
    blackoutPeriods: BlackoutPeriod[]
): SafetyCheckResult {
    const now = new Date();
    const hour = now.getHours();
    const minute = now.getMinutes();
    const currentTime = hour * 60 + minute; // minutes since midnight

    for (const blackout of blackoutPeriods) {
        const [startHour, startMinute] = blackout.startTime.split(':').map(Number);
        const [endHour, endMinute] = blackout.endTime.split(':').map(Number);

        const startTime = startHour * 60 + startMinute;
        const endTime = endHour * 60 + endMinute;

        if (currentTime >= startTime && currentTime < endTime) {
            return {
                gateName: 'Blackout Period Check',
                passed: false,
                reason: `In blackout period: ${blackout.startTime}-${blackout.endTime} (${blackout.reason})`,
                timestamp: new Date()
            };
        }
    }

    return {
        gateName: 'Blackout Period Check',
        passed: true,
        timestamp: new Date()
    };
}

/**
 * Check if rule's autonomy level is allowed by brand policy
 */
export function checkAutonomyLevel(
    ruleAutonomyLevel: AutonomyLevel,
    brandMaxAutonomyLevel: AutonomyLevel
): SafetyCheckResult {
    if (ruleAutonomyLevel > brandMaxAutonomyLevel) {
        return {
            gateName: 'Autonomy Level Check',
            passed: false,
            reason: `Rule autonomy level ${ruleAutonomyLevel} exceeds brand max ${brandMaxAutonomyLevel}`,
            timestamp: new Date()
        };
    }

    return {
        gateName: 'Autonomy Level Check',
        passed: true,
        timestamp: new Date()
    };
}

/**
 * Check if confidence score meets threshold
 */
export function checkConfidenceThreshold(
    confidenceScore: number,
    threshold: number
): SafetyCheckResult {
    if (confidenceScore < threshold) {
        return {
            gateName: 'Confidence Threshold Check',
            passed: false,
            reason: `Confidence ${confidenceScore.toFixed(2)} below threshold ${threshold}`,
            timestamp: new Date()
        };
    }

    return {
        gateName: 'Confidence Threshold Check',
        passed: true,
        timestamp: new Date()
    };
}

/**
 * Check if all required metrics are available
 */
export function checkDataCompleteness(
    requiredMetrics: string[],
    availableMetrics: Record<string, number>
): SafetyCheckResult {
    const missingMetrics = requiredMetrics.filter(
        metric => !(metric in availableMetrics) || availableMetrics[metric] === null
    );

    if (missingMetrics.length > 0) {
        return {
            gateName: 'Data Completeness Check',
            passed: false,
            reason: `Missing metrics: ${missingMetrics.join(', ')}`,
            timestamp: new Date()
        };
    }

    return {
        gateName: 'Data Completeness Check',
        passed: true,
        timestamp: new Date()
    };
}

/**
 * Check for conflicting rules targeting same resource
 */
export async function checkConflicts(
    brandId: string,
    targetId: string,
    actionId: string
): Promise<SafetyCheckResult> {
    // Check if there's a pending execution for same target
    const pendingExecution = await prisma.executionLog.findFirst({
        where: {
            brandId,
            executionStatus: 'pending',
            auditData: {
                path: ['targetId'],
                equals: targetId
            }
        }
    });

    if (pendingExecution) {
        return {
            gateName: 'Conflict Check',
            passed: false,
            reason: `Pending execution exists for target ${targetId}`,
            timestamp: new Date()
        };
    }

    return {
        gateName: 'Conflict Check',
        passed: true,
        timestamp: new Date()
    };
}

/**
 * Run all safety gates for a rule evaluation
 */
export async function runAllSafetyGates(
    brandId: string,
    rule: RuleDefinition,
    policy: BrandAutonomyPolicy,
    confidenceScore: number,
    metricsSnapshot: Record<string, number>,
    targetId?: string
): Promise<SafetyCheckResult[]> {
    const results: SafetyCheckResult[] = [];

    // 1. Autonomy Level Check
    results.push(checkAutonomyLevel(rule.action.autonomyLevel, policy.maxAutonomyLevel));

    // 2. Confidence Threshold Check
    results.push(checkConfidenceThreshold(confidenceScore, Math.max(rule.confidenceThreshold, policy.confidenceThreshold)));

    // 3. Data Completeness Check
    results.push(checkDataCompleteness(rule.metricsUsed, metricsSnapshot));

    // 4. Blackout Period Check
    results.push(checkBlackout(policy.blackoutPeriods));

    // 5. Daily Cap Check
    results.push(await checkDailyCap(brandId, rule.action.actionId, rule.action.maxExecutionsPerDay));

    // 6. Cooldown Check
    results.push(await checkCooldown(brandId, rule.action.actionId, targetId));

    // 7. Conflict Check (if targetId provided)
    if (targetId) {
        results.push(await checkConflicts(brandId, targetId, rule.action.actionId));
    }

    return results;
}

/**
 * Check if all safety gates passed
 */
export function allGatesPassed(results: SafetyCheckResult[]): boolean {
    return results.every(result => result.passed);
}

/**
 * Get first blocking reason
 */
export function getBlockingReason(results: SafetyCheckResult[]): string | undefined {
    const blocked = results.find(result => !result.passed);
    return blocked?.reason;
}

// Rule Trust - Track rule trust and enable expansion/demotion
// CRITICAL: Sustained trust required, auto-demotion on anomaly

import { prisma } from '@/lib/prisma';
import { calculateTrustMetrics } from '../trust/trust-metrics';
import { calculateTrustScore } from '../trust/trust-score';
import { evaluateRulePerformance } from '../trust/rule-performance';

/**
 * Rule trust assessment
 */
export interface RuleTrustAssessment {
    ruleId: string;
    ruleName: string;

    // Current level
    current_level: 0 | 1 | 2 | 3;

    // Trust metrics
    trust_score: number;
    approval_rate: number;
    outcome_success_rate: number;
    rollback_rate: number;

    // Expansion eligibility
    eligible_for_expansion: boolean;
    expansion_target_level: 0 | 1 | 2 | 3;
    expansion_blockers: string[];

    // Demotion risk
    demotion_risk: 'none' | 'low' | 'medium' | 'high';
    demotion_reasons: string[];

    // History
    days_at_current_level: number;
    total_executions: number;

    // Recommendation
    recommendation: 'expand' | 'maintain' | 'demote';
}

/**
 * Assess rule trust for expansion/demotion
 */
export async function assessRuleTrust(
    brandId: string,
    ruleId: string
): Promise<RuleTrustAssessment> {
    // Fetch rule
    const rule = await prisma.decisionRule.findUnique({
        where: { ruleId }
    });

    if (!rule) {
        throw new Error(`Rule not found: ${ruleId}`);
    }

    // Calculate metrics for last 30 days
    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - 30);

    const performance = await evaluateRulePerformance(brandId, ruleId, startDate, endDate);

    // Calculate brand trust score
    const brandMetrics = await calculateTrustMetrics(brandId, startDate, endDate);
    const brandTrustScore = calculateTrustScore(brandMetrics);

    // Determine expansion eligibility
    const { eligible, targetLevel, blockers } = checkExpansionEligibility(
        rule.autonomyLevel as any,
        performance,
        brandTrustScore.overall_score
    );

    // Determine demotion risk
    const { risk, reasons } = checkDemotionRisk(
        rule.autonomyLevel as any,
        performance
    );

    // Calculate days at current level
    const daysAtLevel = calculateDaysAtLevel(rule);

    // Determine recommendation
    const recommendation = determineRecommendation(
        eligible,
        risk,
        performance.status
    );

    return {
        ruleId,
        ruleName: rule.name,
        current_level: rule.autonomyLevel as any,
        trust_score: brandTrustScore.overall_score,
        approval_rate: performance.approval_ratio,
        outcome_success_rate: performance.outcome_success_rate,
        rollback_rate: 1 - performance.outcome_success_rate,
        eligible_for_expansion: eligible,
        expansion_target_level: targetLevel,
        expansion_blockers: blockers,
        demotion_risk: risk,
        demotion_reasons: reasons,
        days_at_current_level: daysAtLevel,
        total_executions: performance.trigger_count,
        recommendation
    };
}

/**
 * Check if rule is eligible for expansion
 */
function checkExpansionEligibility(
    currentLevel: 0 | 1 | 2 | 3,
    performance: any,
    brandTrustScore: number
): {
    eligible: boolean;
    targetLevel: 0 | 1 | 2 | 3;
    blockers: string[];
} {
    const blockers: string[] = [];
    let targetLevel = currentLevel;

    // Cannot expand beyond Level 3
    if (currentLevel >= 3) {
        return { eligible: false, targetLevel, blockers: ['Already at max level'] };
    }

    // Requirements for expansion to next level
    const requirements = {
        1: { // Level 0 → 1
            minApprovalRate: 0.70,
            minOutcomeSuccess: 0.60,
            minExecutions: 10,
            minBrandTrust: 50
        },
        2: { // Level 1 → 2
            minApprovalRate: 0.75,
            minOutcomeSuccess: 0.70,
            minExecutions: 30,
            minBrandTrust: 60
        },
        3: { // Level 2 → 3
            minApprovalRate: 0.85,
            minOutcomeSuccess: 0.80,
            minExecutions: 50,
            minBrandTrust: 70
        }
    };

    targetLevel = (currentLevel + 1) as any;
    const req = requirements[targetLevel];

    // Check approval rate
    if (performance.approval_ratio < req.minApprovalRate) {
        blockers.push(
            `Approval rate too low (${(performance.approval_ratio * 100).toFixed(0)}% < ${(req.minApprovalRate * 100).toFixed(0)}%)`
        );
    }

    // Check outcome success rate
    if (performance.outcome_success_rate < req.minOutcomeSuccess) {
        blockers.push(
            `Outcome success rate too low (${(performance.outcome_success_rate * 100).toFixed(0)}% < ${(req.minOutcomeSuccess * 100).toFixed(0)}%)`
        );
    }

    // Check execution count
    if (performance.trigger_count < req.minExecutions) {
        blockers.push(
            `Insufficient executions (${performance.trigger_count} < ${req.minExecutions})`
        );
    }

    // Check brand trust
    if (brandTrustScore < req.minBrandTrust) {
        blockers.push(
            `Brand trust score too low (${brandTrustScore.toFixed(0)} < ${req.minBrandTrust})`
        );
    }

    // Check rule status
    if (performance.status !== 'OK') {
        blockers.push(`Rule status is ${performance.status} (must be OK)`);
    }

    return {
        eligible: blockers.length === 0,
        targetLevel,
        blockers
    };
}

/**
 * Check demotion risk
 */
function checkDemotionRisk(
    currentLevel: 0 | 1 | 2 | 3,
    performance: any
): {
    risk: 'none' | 'low' | 'medium' | 'high';
    reasons: string[];
} {
    const reasons: string[] = [];

    // Level 0 cannot be demoted
    if (currentLevel === 0) {
        return { risk: 'none', reasons: [] };
    }

    // Check for demotion triggers
    if (performance.approval_ratio < 0.50) {
        reasons.push(`Very low approval rate (${(performance.approval_ratio * 100).toFixed(0)}%)`);
    }

    if (performance.outcome_success_rate < 0.50) {
        reasons.push(`Very low outcome success (${(performance.outcome_success_rate * 100).toFixed(0)}%)`);
    }

    if (performance.status === 'PAUSE') {
        reasons.push('Rule status is PAUSE');
    }

    if (performance.risk_trend === 'worsening') {
        reasons.push('Risk trend is worsening');
    }

    // Determine risk level
    let risk: 'none' | 'low' | 'medium' | 'high' = 'none';

    if (reasons.length >= 3) {
        risk = 'high';
    } else if (reasons.length === 2) {
        risk = 'medium';
    } else if (reasons.length === 1) {
        risk = 'low';
    }

    return { risk, reasons };
}

/**
 * Calculate days at current level
 */
function calculateDaysAtLevel(rule: any): number {
    const lastModified = rule.lastModifiedAt || rule.createdAt;
    const now = new Date();
    const diffMs = now.getTime() - lastModified.getTime();
    return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/**
 * Determine recommendation
 */
function determineRecommendation(
    eligible: boolean,
    demotionRisk: 'none' | 'low' | 'medium' | 'high',
    status: 'OK' | 'REVIEW' | 'PAUSE'
): 'expand' | 'maintain' | 'demote' {
    // Demote if high risk or PAUSE status
    if (demotionRisk === 'high' || status === 'PAUSE') {
        return 'demote';
    }

    // Expand if eligible and no demotion risk
    if (eligible && demotionRisk === 'none') {
        return 'expand';
    }

    // Otherwise maintain
    return 'maintain';
}

/**
 * Auto-expand rule to next level
 */
export async function autoExpandRule(
    brandId: string,
    ruleId: string,
    performedBy: string
): Promise<{
    success: boolean;
    previous_level: number;
    new_level: number;
}> {
    const assessment = await assessRuleTrust(brandId, ruleId);

    if (!assessment.eligible_for_expansion) {
        throw new Error(
            `Rule not eligible for expansion: ${assessment.expansion_blockers.join(', ')}`
        );
    }

    // Update rule level
    await prisma.decisionRule.update({
        where: { ruleId },
        data: {
            autonomyLevel: assessment.expansion_target_level,
            lastModifiedAt: new Date(),
            lastModifiedBy: performedBy
        }
    });

    // Add to Level 3 whitelist if expanding to Level 3
    if (assessment.expansion_target_level === 3) {
        await prisma.level3Whitelist.create({
            data: {
                brandId,
                ruleId,
                isActive: true,
                whitelistedBy: performedBy,
                whitelistedAt: new Date()
            }
        });
    }

    // Log expansion
    await prisma.auditLog.create({
        data: {
            brandId,
            eventType: 'rule_expanded',
            performedBy,
            timestamp: new Date(),
            metadata: {
                ruleId,
                previous_level: assessment.current_level,
                new_level: assessment.expansion_target_level,
                trust_score: assessment.trust_score,
                approval_rate: assessment.approval_rate
            }
        }
    });

    return {
        success: true,
        previous_level: assessment.current_level,
        new_level: assessment.expansion_target_level
    };
}

/**
 * Auto-demote rule on anomaly
 */
export async function autoDemoteRule(
    brandId: string,
    ruleId: string,
    reason: string
): Promise<{
    success: boolean;
    previous_level: number;
    new_level: number;
}> {
    const rule = await prisma.decisionRule.findUnique({
        where: { ruleId }
    });

    if (!rule) {
        throw new Error(`Rule not found: ${ruleId}`);
    }

    const previousLevel = rule.autonomyLevel;
    const newLevel = Math.max(0, previousLevel - 1);

    // Update rule level
    await prisma.decisionRule.update({
        where: { ruleId },
        data: {
            autonomyLevel: newLevel,
            lastModifiedAt: new Date(),
            lastModifiedBy: 'system'
        }
    });

    // Remove from Level 3 whitelist if demoting from Level 3
    if (previousLevel === 3) {
        await prisma.level3Whitelist.updateMany({
            where: {
                brandId,
                ruleId,
                isActive: true
            },
            data: {
                isActive: false,
                deactivatedAt: new Date(),
                deactivatedBy: 'system'
            }
        });
    }

    // Log demotion
    await prisma.auditLog.create({
        data: {
            brandId,
            eventType: 'rule_demoted',
            performedBy: 'system',
            timestamp: new Date(),
            metadata: {
                ruleId,
                previous_level: previousLevel,
                new_level: newLevel,
                reason
            }
        }
    });

    return {
        success: true,
        previous_level: previousLevel,
        new_level: newLevel
    };
}

// Simulation Engine - Read-only dry-run evaluation
// CRITICAL: NO database mutations, NO external API calls

import { prisma } from '@/lib/prisma';
import {
    DecisionInput,
    DecisionResult,
    RuleDefinition,
    RuleEvaluationResult,
    ExecutionIntent,
    RiskLevel,
    EstimatedImpact
} from './types/decision';
import { BrandAutonomyPolicy, runAllSafetyGates, allGatesPassed, getBlockingReason } from './safety-gates';

/**
 * Run simulation (dry-run) - NO side effects
 */
export async function runSimulation(input: DecisionInput): Promise<DecisionResult> {
    const decisionId = `sim_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Load brand autonomy policy
    const policy = await loadBrandAutonomyPolicy(input.brandId);

    if (!policy.enabled) {
        return {
            decisionId,
            brandId: input.brandId,
            triggeredAt: new Date(),
            rulesEvaluated: 0,
            rulesTriggered: 0,
            executionIntents: [],
            results: [],
            simulationMode: true
        };
    }

    // Load active rules
    const rules = await loadActiveRules(input.brandId, input.ruleIds);

    // Fetch metrics (read-only)
    const metrics = await fetchMetrics(input.brandId);

    // Evaluate each rule
    const results: RuleEvaluationResult[] = [];
    for (const rule of rules) {
        const result = await evaluateRuleSimulation(rule, metrics, policy);
        results.push(result);
    }

    // Determine execution intents
    const executionIntents = results
        .filter(r => r.triggered)
        .map(r => determineExecutionIntent(r, policy));

    return {
        decisionId,
        brandId: input.brandId,
        triggeredAt: new Date(),
        rulesEvaluated: rules.length,
        rulesTriggered: results.filter(r => r.triggered).length,
        executionIntents,
        results,
        simulationMode: true
    };
}

/**
 * Evaluate a single rule in simulation mode (read-only)
 */
async function evaluateRuleSimulation(
    rule: RuleDefinition,
    metrics: Record<string, number>,
    policy: BrandAutonomyPolicy
): Promise<RuleEvaluationResult> {
    // Extract metrics for this rule
    const metricsSnapshot = extractMetrics(rule.metricsUsed, metrics);

    // Check exclusions
    const exclusionApplied = checkExclusions(rule.exclusions, metricsSnapshot);
    if (exclusionApplied) {
        return {
            ruleId: rule.ruleId,
            ruleName: rule.name,
            triggered: false,
            blockReason: `Exclusion applied: ${exclusionApplied}`,
            confidenceScore: 0,
            metricsSnapshot,
            estimatedImpact: { type: 'cost_savings' },
            riskLevel: RiskLevel.LOW,
            safetyGateResults: [],
            action: rule.action
        };
    }

    // Evaluate conditions
    const conditionsMet = evaluateConditions(rule.conditions, metricsSnapshot);
    if (!conditionsMet) {
        return {
            ruleId: rule.ruleId,
            ruleName: rule.name,
            triggered: false,
            blockReason: 'Conditions not met',
            confidenceScore: 0,
            metricsSnapshot,
            estimatedImpact: { type: 'cost_savings' },
            riskLevel: RiskLevel.LOW,
            safetyGateResults: [],
            action: rule.action
        };
    }

    // Calculate confidence score
    const confidenceScore = calculateConfidenceScore(rule, metricsSnapshot);

    // Run safety gates (simulation mode - read-only)
    const safetyGateResults = await runAllSafetyGates(
        '', // No brandId in simulation
        rule,
        policy,
        confidenceScore,
        metricsSnapshot
    );

    // Estimate impact
    const estimatedImpact = estimateImpact(rule, metricsSnapshot);

    // Determine risk level
    const riskLevel = determineRiskLevel(rule, estimatedImpact);

    return {
        ruleId: rule.ruleId,
        ruleName: rule.name,
        triggered: true,
        blockReason: allGatesPassed(safetyGateResults) ? undefined : getBlockingReason(safetyGateResults),
        confidenceScore,
        metricsSnapshot,
        estimatedImpact,
        riskLevel,
        safetyGateResults,
        action: rule.action
    };
}

/**
 * Load brand autonomy policy (read-only)
 */
async function loadBrandAutonomyPolicy(brandId: string): Promise<BrandAutonomyPolicy> {
    const policy = await prisma.autonomyPolicy.findUnique({
        where: { brandId }
    });

    if (!policy) {
        // Return default disabled policy
        return {
            enabled: false,
            maxAutonomyLevel: 0,
            confidenceThreshold: 0.95,
            blackoutPeriods: [],
            maxActionsPerDay: 0
        };
    }

    return {
        enabled: policy.enabled,
        maxAutonomyLevel: policy.maxAutonomyLevel,
        confidenceThreshold: policy.confidenceThreshold,
        blackoutPeriods: policy.blackoutPeriods as any[],
        maxActionsPerDay: policy.maxActionsPerDay
    };
}

/**
 * Load active rules (read-only)
 */
async function loadActiveRules(
    brandId: string,
    ruleIds?: string[]
): Promise<RuleDefinition[]> {
    const rules = await prisma.decisionRule.findMany({
        where: {
            ...(ruleIds && { ruleId: { in: ruleIds } }),
            enabled: true
        },
        orderBy: [
            { priority: 'asc' }, // HIGH = 0, MEDIUM = 1, LOW = 2
            { ruleId: 'asc' }
        ]
    });

    return rules.map(rule => ({
        ruleId: rule.ruleId,
        name: rule.name,
        domain: rule.domain,
        version: rule.version,
        priority: rule.priority as any,
        confidenceThreshold: rule.confidenceThreshold,
        metricsUsed: rule.metricsUsed as string[],
        timeWindow: rule.timeWindow,
        conditions: rule.conditions as any[],
        exclusions: rule.exclusions as string[],
        action: rule.action as any,
        explanationTemplate: rule.explanationTemplate,
        rollbackAction: rule.rollbackAction,
        auditLevel: rule.auditLevel as any,
        ownerApprovalRequired: rule.ownerApprovalRequired
    }));
}

/**
 * Fetch metrics from aggregation tables (read-only)
 */
async function fetchMetrics(brandId: string): Promise<Record<string, number>> {
    // Fetch latest daily sales aggregation
    const latestSales = await prisma.aggDailySales.findFirst({
        where: { brandId },
        orderBy: { date: 'desc' }
    });

    // Fetch latest daily ads aggregation
    const latestAds = await prisma.aggDailyAds.findFirst({
        where: { brandId },
        orderBy: { date: 'desc' }
    });

    // Combine metrics
    const metrics: Record<string, number> = {};

    if (latestSales) {
        metrics['revenue_7d'] = latestSales.totalRevenue;
        metrics['orders_7d'] = latestSales.totalOrders;
        metrics['sales_week_current'] = latestSales.totalRevenue;
    }

    if (latestAds) {
        metrics['ad_spend_7d'] = latestAds.totalSpend;
        metrics['roas_7d'] = latestAds.avgRoas;
        metrics['clicks_7d'] = latestAds.totalClicks;
        metrics['impressions_7d'] = latestAds.totalImpressions;
    }

    return metrics;
}

/**
 * Extract metrics needed for a rule
 */
function extractMetrics(
    metricsUsed: string[],
    allMetrics: Record<string, number>
): Record<string, number> {
    const extracted: Record<string, number> = {};

    for (const metric of metricsUsed) {
        if (metric in allMetrics) {
            extracted[metric] = allMetrics[metric];
        }
    }

    return extracted;
}

/**
 * Check exclusions
 */
function checkExclusions(
    exclusions: string[],
    metrics: Record<string, number>
): string | null {
    // TODO: Implement exclusion logic
    // For now, return null (no exclusions)
    return null;
}

/**
 * Evaluate conditions
 */
function evaluateConditions(
    conditions: any[],
    metrics: Record<string, number>
): boolean {
    for (const condition of conditions) {
        const metricValue = metrics[condition.metric];

        if (metricValue === undefined) {
            return false; // Missing metric
        }

        const threshold = condition.value;

        switch (condition.operator) {
            case '<':
                if (!(metricValue < threshold)) return false;
                break;
            case '<=':
                if (!(metricValue <= threshold)) return false;
                break;
            case '=':
                if (!(metricValue === threshold)) return false;
                break;
            case '>=':
                if (!(metricValue >= threshold)) return false;
                break;
            case '>':
                if (!(metricValue > threshold)) return false;
                break;
            default:
                return false;
        }
    }

    return true;
}

/**
 * Calculate confidence score
 */
function calculateConfidenceScore(
    rule: RuleDefinition,
    metrics: Record<string, number>
): number {
    // Simple confidence: percentage of metrics available
    const availableMetrics = rule.metricsUsed.filter(m => m in metrics && metrics[m] !== null);
    const completeness = availableMetrics.length / rule.metricsUsed.length;

    // Base confidence from rule threshold
    const baseConfidence = rule.confidenceThreshold;

    // Adjust based on data completeness
    return Math.min(baseConfidence * completeness, 1.0);
}

/**
 * Estimate impact
 */
function estimateImpact(
    rule: RuleDefinition,
    metrics: Record<string, number>
): EstimatedImpact {
    // TODO: Implement impact estimation logic per rule
    // For now, return placeholder
    return {
        type: 'cost_savings',
        amount: 0,
        percentage: 0
    };
}

/**
 * Determine risk level
 */
function determineRiskLevel(
    rule: RuleDefinition,
    impact: EstimatedImpact
): RiskLevel {
    // Simple risk determination based on impact amount
    if (!impact.amount) return RiskLevel.LOW;

    if (impact.amount > 1000000) return RiskLevel.HIGH;
    if (impact.amount > 500000) return RiskLevel.MEDIUM;
    return RiskLevel.LOW;
}

/**
 * Determine execution intent
 */
function determineExecutionIntent(
    result: RuleEvaluationResult,
    policy: BrandAutonomyPolicy
): ExecutionIntent {
    if (result.blockReason) {
        return ExecutionIntent.BLOCKED;
    }

    if (result.action.autonomyLevel === 0 || result.action.autonomyLevel === 1) {
        return ExecutionIntent.PENDING; // Suggestions only
    }

    if (result.action.autonomyLevel === 2) {
        return ExecutionIntent.APPROVAL_REQUIRED;
    }

    if (result.action.autonomyLevel === 3) {
        return ExecutionIntent.READY_TO_EXECUTE;
    }

    return ExecutionIntent.BLOCKED;
}

import { prisma } from '@/lib/prisma';
import crypto from 'crypto';

export type FailureScenario =
    | 'INCORRECT_PAYLOAD'
    | 'INCORRECT_TIMING'
    | 'OVERCONFIDENCE_BIAS'
    | 'ROLLBACK_FAILURE'
    | 'APPROVAL_CHAIN_BREAKDOWN'
    | 'HUMAN_PANIC_RESPONSE';

export interface SimulationInput {
    brandId: string;
    assistedActionId: string;
    failureScenario: FailureScenario;
    parameters: any;
}

export interface FailureOutcomeReport {
    simulationId: string;
    failureType: FailureScenario;
    parameters: any;
    simulatedImpact: {
        financial: number;
        operational: string;
    };
    rollbackSuccess: boolean;
    rollbackLatency: number; // seconds
    residualRisk: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
    governanceBreachFlags: string[];
}

/**
 * Deterministic Failure Simulation Engine
 * STRICTLY NON-PRODUCTION
 */
export async function runFailureSimulation(input: SimulationInput): Promise<FailureOutcomeReport> {
    const { brandId, assistedActionId, failureScenario, parameters } = input;

    // 1. Fetch Action Template
    const action = await (prisma as any).assistedAction.findUnique({
        where: { id: assistedActionId },
        include: { suggestion: true }
    });

    if (!action) {
        throw new Error('GOVERNANCE_ERROR: AssistedAction template not found.');
    }

    const simulationId = `sim_${Math.random().toString(36).substring(2, 11)}`;
    let simulatedImpact = { financial: 0, operational: 'STABLE' };
    let rollbackSuccess = true;
    let rollbackLatency = 30;
    let residualRisk: FailureOutcomeReport['residualRisk'] = 'LOW';
    let governanceBreachFlags: string[] = [];

    // 2. Deterministic Logic per Taxonomy
    switch (failureScenario) {
        case 'INCORRECT_PAYLOAD':
            const originalValue = action.payload.value || 0;
            const injectedValue = parameters.injectedValue || originalValue * 10;
            const delta = (injectedValue / originalValue) * 100;

            simulatedImpact.financial = -Math.abs(injectedValue - originalValue) * 100; // Simulated scale
            simulatedImpact.operational = 'MARGIN_COLLAPSE';

            if (delta > 500) {
                governanceBreachFlags.push('PAYLOAD_OUTSIDE_SAFETY_BOUNDS');
                residualRisk = 'HIGH';
            }
            break;

        case 'INCORRECT_TIMING':
            simulatedImpact.financial = -5000000;
            simulatedImpact.operational = 'STALE_DATA_SKEW';
            rollbackLatency = 120;
            residualRisk = 'MEDIUM';
            break;

        case 'OVERCONFIDENCE_BIAS':
            simulatedImpact.financial = -2000000;
            simulatedImpact.operational = 'STOCK_OUT_RISK';
            governanceBreachFlags.push('MANUAL_VALIDATION_SKIPPED');
            residualRisk = 'MEDIUM';
            break;

        case 'ROLLBACK_FAILURE':
            simulatedImpact.financial = -25000000;
            simulatedImpact.operational = 'SYSTEM_ERROR_STATE';
            rollbackSuccess = false;
            rollbackLatency = 3600;
            residualRisk = 'CRITICAL';
            governanceBreachFlags.push('ROLLBACK_TIMEOUT');
            break;

        case 'APPROVAL_CHAIN_BREAKDOWN':
            simulatedImpact.financial = -1000000;
            simulatedImpact.operational = 'BYPASS_SECURITY';
            governanceBreachFlags.push('INSUFFICIENT_SIGNATURE_QUORUM');
            residualRisk = 'HIGH';
            break;

        case 'HUMAN_PANIC_RESPONSE':
            simulatedImpact.financial = -8000000;
            simulatedImpact.operational = 'OSCILLATION_INSTABILITY';
            residualRisk = 'MEDIUM';
            break;

        default:
            throw new Error(`GOVERNANCE_ERROR: Unknown failure scenario ${failureScenario}`);
    }

    // 3. Rollback Stress Simulation Adjustments
    if (parameters.stressLevel === 'HIGH') {
        rollbackLatency *= 2;
        if (Math.random() > 0.8) rollbackSuccess = false; // Simulated stress failure
    }

    const report: FailureOutcomeReport = {
        simulationId,
        failureType: failureScenario,
        parameters,
        simulatedImpact,
        rollbackSuccess,
        rollbackLatency,
        residualRisk: rollbackSuccess ? residualRisk : 'CRITICAL',
        governanceBreachFlags
    };

    // 4. Persistence of Audit Artifact
    const reproducibilityHash = await generateReproHash(input);

    await (prisma as any).failureSimulation.create({
        data: {
            brandId,
            assistedActionId,
            simulationId,
            failureType: failureScenario,
            parameters,
            simulatedImpact,
            rollbackSuccess,
            rollbackLatency,
            residualRisk: report.residualRisk,
            governanceBreachFlags,
            reproducibilityHash
        }
    });

    return report;
}

/**
 * Generate SHA-256 hash for audit reproducibility
 */
async function generateReproHash(input: any): Promise<string> {
    const content = JSON.stringify(input);
    return require('crypto').createHash('sha256').update(content).digest('hex');
}

