import { prisma } from '@/lib/prisma';
import { differenceInDays } from 'date-fns';

export interface QualityReport {
    brandId: string;
    acceptanceRatio: number; // accepted / (accepted + rejected)
    deferredAgingIndex: number; // avg days in DEFERRED
    rejectionReasonClusters: { reason: string; count: number }[];
    noiseAlerts: { domain: string; count: number; risk: 'LOW' | 'HIGH' }[];
    consistencyWarnings: {
        sku: string;
        conflicts: { id: string; action: string; date: string }[]
    }[];
    status: 'HEALTHY' | 'NOISY' | 'LOW_SIGNAL' | 'INCONSISTENT';
    lastUpdated: string;
    statement: string;
}

/**
 * Evaluates AI suggestion quality without enabling autonomy.
 * STRICTLY INFORMATIONAL.
 */
export async function generateQualityAudit(brandId: string): Promise<QualityReport> {
    const statement = "Phase 3.5 evaluates AI suggestion quality only. It does not enable, recommend, or imply autonomy.";

    // 1. Fetch data
    const drafts = await (prisma as any).suggestionDraft.findMany({
        where: { brandId },
        include: { feedbacks: true },
        orderBy: { createdAt: 'desc' }
    });

    if (drafts.length === 0) {
        return {
            brandId,
            acceptanceRatio: 0,
            deferredAgingIndex: 0,
            rejectionReasonClusters: [],
            noiseAlerts: [],
            consistencyWarnings: [],
            status: 'LOW_SIGNAL',
            lastUpdated: new Date().toISOString(),
            statement
        };
    }

    // A. Suggestion Acceptance Ratio
    let accepted = 0;
    let rejected = 0;
    let deferredTotalDays = 0;
    let deferredCount = 0;
    const rejectionReasons: Record<string, number> = {};

    drafts.forEach((draft: any) => {
        draft.feedbacks.forEach((fb: any) => {
            if (fb.decision === 'ACCEPTED') accepted++;
            if (fb.decision === 'REJECTED') {
                rejected++;
                const reason = fb.reason || 'Unspecified';
                rejectionReasons[reason] = (rejectionReasons[reason] || 0) + 1;
            }
            if (fb.decision === 'DEFERRED') {
                deferredCount++;
                deferredTotalDays += differenceInDays(new Date(), new Date(fb.createdAt));
            }
        });
    });

    const acceptanceRatio = (accepted + rejected) > 0 ? (accepted / (accepted + rejected)) : 0;
    const deferredAgingIndex = deferredCount > 0 ? (deferredTotalDays / deferredCount) : 0;

    // B. Rejection Clusters
    const rejectionReasonClusters = Object.entries(rejectionReasons)
        .map(([reason, count]) => ({ reason, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 3);

    // C. Noise & Fatigue Detection (7-day window)
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    const recentDrafts = drafts.filter((d: any) => new Date(d.createdAt) >= sevenDaysAgo);
    const domainCounts: Record<string, number> = {};
    recentDrafts.forEach((d: any) => {
        domainCounts[d.domain] = (domainCounts[d.domain] || 0) + 1;
    });

    const noiseAlerts = Object.entries(domainCounts)
        .map(([domain, count]) => ({
            domain,
            count,
            risk: (count > 5 ? 'HIGH' : 'LOW') as 'LOW' | 'HIGH'
        }))
        .filter(alert => alert.risk === 'HIGH');

    // D. Consistency Validator (Same SKU/Topic within 14 days)
    const consistencyWarnings: QualityReport['consistencyWarnings'] = [];
    const draftsByTitle: Record<string, any[]> = {};

    drafts.forEach((d: any) => {
        if (!draftsByTitle[d.title]) draftsByTitle[d.title] = [];
        draftsByTitle[d.title].push(d);
    });

    Object.entries(draftsByTitle).forEach(([title, group]) => {
        if (group.length > 1) {
            const sortedGroup = group.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
            // Simplistic check: If actions differ significantly (mock logic)
            // In a real system, we'd compare the actual payload values
            const latest = sortedGroup[0];
            const previous = sortedGroup[1];

            if (latest.proposedAction !== previous.proposedAction && differenceInDays(new Date(latest.createdAt), new Date(previous.createdAt)) <= 14) {
                consistencyWarnings.push({
                    sku: title,
                    conflicts: sortedGroup.slice(0, 2).map(d => ({
                        id: d.id,
                        action: d.proposedAction,
                        date: new Date(d.createdAt).toLocaleDateString()
                    }))
                });
            }
        }
    });

    // E. Quality Gate Verdict
    let status: QualityReport['status'] = 'HEALTHY';
    if (consistencyWarnings.length > 0) status = 'INCONSISTENT';
    else if (noiseAlerts.length > 0) status = 'NOISY';
    else if (acceptanceRatio < 0.4 || drafts.length < 5) status = 'LOW_SIGNAL';
    else if (acceptanceRatio >= 0.7) status = 'HEALTHY';

    return {
        brandId,
        acceptanceRatio,
        deferredAgingIndex,
        rejectionReasonClusters,
        noiseAlerts,
        consistencyWarnings,
        status,
        lastUpdated: new Date().toISOString(),
        statement
    };
}

import { prisma } from '@/lib/prisma';

export type AgreementSignal = 'AGREE' | 'UNSURE' | 'DISAGREE';

export interface TrustGapReport {
    system_confidence_avg: number;
    human_agreement_rate: number;
    disagreement_clusters: string[];
    disagreement_clusters_full: any[];
    trust_gap_score: number; // 0-100
    red_flag: boolean;
}

export interface HumanReadinessSummary {
    trust_alignment: 'LOW' | 'MEDIUM' | 'HIGH';
    primary_concerns: string[];
    recommendation: 'CONTINUE OBSERVE' | 'EXTEND CALIBRATION';
}

/**
 * Record human agreement signal
 * CRITICAL: NO persistence to execution tables
 */
export async function recordAgreementSignal(
    decisionId: string,
    brandId: string,
    agreement: AgreementSignal,
    reason?: string
) {
    return await prisma.humanAgreementSignal.create({
        data: {
            decisionId,
            brandId,
            agreement,
            reason
        }
    });
}

/**
 * Calculate trust gap report
 * Measures deltas between System Confidence and Human Agreement
 */
export async function calculateTrustGapReport(brandId: string): Promise<TrustGapReport> {
    const signals = await prisma.humanAgreementSignal.findMany({
        where: { brandId },
        take: 100,
        orderBy: { createdAt: 'desc' }
    });

    if (signals.length === 0) {
        return {
            system_confidence_avg: 0,
            human_agreement_rate: 0,
            disagreement_clusters: [],
            disagreement_clusters_full: [],
            trust_gap_score: 0,
            red_flag: false
        };
    }

    // Fetch related execution logs to get system confidence
    const decisionIds = signals.map(s => s.decisionId);
    const executions = await prisma.executionLog.findMany({
        where: {
            brandId,
            decisionId: { in: decisionIds }
        } as any
    });

    let totalSystemConfidence = 0;
    let agreementCount = 0;

    signals.forEach(signal => {
        if (signal.agreement === 'AGREE') agreementCount++;

        const exec = (executions as any[]).find(e => e.decisionId === signal.decisionId);
        if (exec) {
            const meta = exec.metadata as any;
            totalSystemConfidence += meta?.confidenceScore || 0;
        }
    });

    const avgSystemConfidence = totalSystemConfidence / Math.max(executions.length, 1);
    const humanAgreementRate = agreementCount / signals.length;

    // Trust Gap = Delta between system confidence and human agreement
    const delta = Math.abs(avgSystemConfidence - humanAgreementRate);
    const trustGapScore = Math.max(0, 100 - (delta * 100));

    // Red Flag Rule: Delta > 30%
    const redFlag = delta > 0.30;

    const clusters = await analyzeDisagreementHeatmap(brandId);
    const disagreement_clusters = clusters.filter(c => c.warning_level === 'HIGH').map(c => c.domain);

    return {
        system_confidence_avg: parseFloat(avgSystemConfidence.toFixed(3)),
        human_agreement_rate: parseFloat(humanAgreementRate.toFixed(3)),
        disagreement_clusters: disagreement_clusters,
        disagreement_clusters_full: clusters,
        trust_gap_score: parseFloat(trustGapScore.toFixed(1)),
        red_flag: redFlag
    };
}

/**
 * Analyze disagreement clusters by domain and SKU
 */
export async function analyzeDisagreementHeatmap(brandId: string) {
    const signals = await prisma.humanAgreementSignal.findMany({
        where: { brandId, agreement: 'DISAGREE' },
        take: 50
    });

    const domains = ['ADS', 'INVENTORY', 'SALES', 'PRICING'];
    const clusters: any[] = [];

    for (const domain of domains) {
        // In a real system, we'd join with decisionRule to get domain
        // For now, we'll mock the domain mapping or fetch rules
        const disagreeInDomain = signals.length > 0 ? Math.random() * signals.length : 0; // Placeholder

        clusters.push({
            domain,
            count: Math.round(disagreeInDomain),
            warning_level: disagreeInDomain > 5 ? 'HIGH' : 'LOW'
        });
    }

    return clusters;
}

/**
 * Produce human-centric readiness summary
 */
export function getHumanReadinessSummary(report: TrustGapReport): HumanReadinessSummary {
    let trust_alignment: HumanReadinessSummary['trust_alignment'] = 'LOW';
    if (report.trust_gap_score > 80) trust_alignment = 'HIGH';
    else if (report.trust_gap_score > 60) trust_alignment = 'MEDIUM';

    const primary_concerns: string[] = [];
    if (report.red_flag) {
        primary_concerns.push('Significant divergence between system confidence and human judgment detected.');
    }
    if (report.human_agreement_rate < 0.70) {
        primary_concerns.push(`Operators hesitate on ${(100 - report.human_agreement_rate * 100).toFixed(0)}% of system evaluations.`);
    }

    return {
        trust_alignment,
        primary_concerns,
        recommendation: report.red_flag || report.human_agreement_rate < 0.6 ? 'EXTEND CALIBRATION' : 'CONTINUE OBSERVE'
    };
}

import { prisma } from '@/lib/prisma';

export interface ConfidenceDimensions {
    operational: number; // 30%
    risk: number;        // 30%
    explainability: number; // 20%
    psychological: number; // 20%
}

export interface ExecutiveConfidenceReport {
    brand_id: string;
    aggregated_score: number;
    dimensions: ConfidenceDimensions;
    status: 'CRITICAL' | 'CAUTION' | 'ALIGNED' | 'PENDING';
    is_governance_frozen: boolean;
    reviews_count: number;
    last_updated: string;
    statement: string;
}

/**
 * Calculates aggregated executive confidence.
 * ZERO AI DECISION POWER - Deterministic aggregation only.
 */
export async function calculateExecutiveConfidence(brandId: string): Promise<ExecutiveConfidenceReport> {
    const reviews = await (prisma as any).executiveConfidenceReview.findMany({
        where: { brandId },
        orderBy: { createdAt: 'desc' }
    });

    const statement = "Executive confidence does not equal system permission.";

    if (reviews.length === 0) {
        return {
            brand_id: brandId,
            aggregated_score: 0,
            dimensions: { operational: 0, risk: 0, explainability: 0, psychological: 0 },
            status: 'PENDING',
            is_governance_frozen: false,
            reviews_count: 0,
            last_updated: new Date().toISOString(),
            statement
        };
    }

    // Latest review from each role
    const roles = ['CFO', 'BOARD', 'OPERATOR'];
    const latestReviews = roles.map(role => reviews.find((r: any) => r.reviewerRole === role)).filter(Boolean);

    const dims: ConfidenceDimensions = {
        operational: 0,
        risk: 0,
        explainability: 0,
        psychological: 0
    };

    latestReviews.forEach((r: any) => {
        const d = r.dimensions as any;
        dims.operational += d.operational;
        dims.risk += d.risk;
        dims.explainability += d.explainability;
        dims.psychological += d.psychological;
    });

    const count = latestReviews.length;
    dims.operational /= count;
    dims.risk /= count;
    dims.explainability /= count;
    dims.psychological /= count;

    // Weighted Score
    const aggregated_score = (
        (dims.operational * 0.3) +
        (dims.risk * 0.3) +
        (dims.explainability * 0.2) +
        (dims.psychological * 0.2)
    );

    // Block Conditions
    // 1. Any individual dimension in any latest review < 30 triggers GOVERNANCE_FREEZE
    const hasCriticalDimension = latestReviews.some((r: any) =>
        Object.values(r.dimensions as any).some((v: any) => v < 30)
    );
    const is_governance_frozen = hasCriticalDimension;

    let status: ExecutiveConfidenceReport['status'] = 'CAUTION';
    if (aggregated_score >= 85 && count >= 2) status = 'ALIGNED';
    else if (aggregated_score < 40 || is_governance_frozen) status = 'CRITICAL';

    return {
        brand_id: brandId,
        aggregated_score: Math.round(aggregated_score),
        dimensions: {
            operational: Math.round(dims.operational),
            risk: Math.round(dims.risk),
            explainability: Math.round(dims.explainability),
            psychological: Math.round(dims.psychological)
        },
        status,
        is_governance_frozen,
        reviews_count: reviews.length,
        last_updated: latestReviews[0].createdAt.toISOString(),
        statement
    };
}

import { prisma } from '@/lib/prisma';
import { calculateTrustMetrics, TrustMetrics } from './trust-metrics';
import { RiskLevel } from '../types/decision';

export interface TrustTrendSnapshot {
    period: '7d' | '14d' | '30d';
    rule_acceptance: number;
    ai_agreement: number;
    rollback_rate: number;
    manual_override_rate: number;
    avg_confidence: number;
    safety_gate_failures: number;
}

export interface AutonomyReadiness {
    score: number;
    status: 'NOT_READY' | 'CONDITIONAL' | 'READY_FOR_REVIEW';
    blocking_factors: string[];
    computed_at: string; // ISODate
}

export interface RiskCluster {
    domain: string;
    concentration_pct: number;
    top_rules: string[];
    warning_level: 'LOW' | 'MEDIUM' | 'HIGH';
}

/**
 * Calculate trend snapshot for a given window
 */
export async function calculateTrustTrendSnapshot(
    brandId: string,
    period: '7d' | '14d' | '30d'
): Promise<TrustTrendSnapshot> {
    const windowDays = parseInt(period.replace('d', ''));
    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(endDate.getDate() - windowDays);

    const metrics = await calculateTrustMetrics(brandId, startDate, endDate);

    // Fetch extra data for Phase 2 (avg_confidence, safety_gate_failures)
    const executions = await prisma.executionLog.findMany({
        where: {
            brandId,
            executedAt: { gte: startDate, lt: endDate }
        }
    });

    let totalConfidence = 0;
    let failedGates = 0;

    executions.forEach(exec => {
        const meta = exec.metadata as any;
        if (meta?.confidenceScore) totalConfidence += meta.confidenceScore;

        // Count failure if status reflects a block or failed gate
        if (exec.status === 'BLOCKED' || (meta?.safetyGateResults && meta.safetyGateResults.some((g: any) => !g.passed))) {
            failedGates++;
        }
    });

    const avgConfidence = executions.length > 0 ? totalConfidence / executions.length : 0;
    const gateFailureRate = executions.length > 0 ? failedGates / executions.length : 0;

    return {
        period,
        rule_acceptance: metrics.rule_acceptance_rate,
        ai_agreement: metrics.ai_agreement_rate,
        rollback_rate: metrics.rollback_frequency,
        manual_override_rate: metrics.manual_override_rate,
        avg_confidence: parseFloat(avgConfidence.toFixed(3)),
        safety_gate_failures: parseFloat(gateFailureRate.toFixed(3))
    };
}

/**
 * Compute readiness score (0-100) based on trend snapshot
 */
export function calculateAutonomyReadiness(
    brandId: string,
    snapshot: TrustTrendSnapshot,
    isTrendDegrading: boolean = false
): AutonomyReadiness {
    const blocking_factors: string[] = [];

    // Weights:
    // Rule Acceptance: 25%
    // AI Agreement: 25%
    // Confidence Stability: 20%
    // Rollback Suppression: 20%
    // Safety Gate Reliability: 10%

    let score = (snapshot.rule_acceptance * 25) +
        (snapshot.ai_agreement * 25) +
        (snapshot.avg_confidence * 20) +
        ((1 - snapshot.rollback_rate) * 20) +
        ((1 - snapshot.safety_gate_failures) * 10);

    // Hard Rules
    if (isTrendDegrading) {
        score = Math.min(score, 60);
        blocking_factors.push('Systemic trust trend is degrading');
    }

    if (snapshot.rollback_rate > 0.02) {
        score = Math.min(score, 40);
        blocking_factors.push(`Rollback rate (${(snapshot.rollback_rate * 100).toFixed(1)}%) exceeds 2% risk threshold`);
    }

    if (snapshot.avg_confidence < 0.85) {
        score = Math.min(score, 50); // Capped below review threshold
        blocking_factors.push(`Average confidence score (${snapshot.avg_confidence}) is below 0.85 requirement`);
    }

    if (snapshot.rule_acceptance < 0.80) {
        blocking_factors.push(`Rule acceptance rate (${(snapshot.rule_acceptance * 100).toFixed(0)}%) is too low`);
    }

    let status: AutonomyReadiness['status'] = 'NOT_READY';
    if (score >= 85 && blocking_factors.length === 0) {
        status = 'READY_FOR_REVIEW';
    } else if (score >= 60) {
        status = 'CONDITIONAL';
    }

    return {
        score: parseFloat(score.toFixed(1)),
        status,
        blocking_factors,
        computed_at: new Date().toISOString()
    };
}

/**
 * Detect risk clusters hidden behind averages
 */
export async function analyzeRiskConcentration(brandId: string): Promise<RiskCluster[]> {
    const rules = await prisma.decisionRule.findMany({
        where: { brandId },
        include: { executions: { take: 50, orderBy: { executedAt: 'desc' } } }
    });

    const domains = ['ADS', 'INVENTORY', 'SALES', 'PRICING'];
    const clusters: RiskCluster[] = [];

    domains.forEach(domain => {
        const domainRules = rules.filter(r => r.domain === domain || (r.category === domain));
        if (domainRules.length === 0) return;

        const triggeredResults = domainRules.flatMap(r => r.executions);
        const failCount = triggeredResults.filter(e => e.status === 'FAILED' || e.status === 'BLOCKED').length;

        const concentration_pct = triggeredResults.length > 0 ? failCount / triggeredResults.length : 0;

        let warning_level: RiskCluster['warning_level'] = 'LOW';
        if (concentration_pct > 0.25) warning_level = 'HIGH';
        else if (concentration_pct > 0.1) warning_level = 'MEDIUM';

        clusters.push({
            domain,
            concentration_pct: parseFloat(concentration_pct.toFixed(3)),
            top_rules: domainRules.slice(0, 3).map(r => r.name),
            warning_level
        });
    });

    return clusters;
}

// Rule Performance Evaluation - Track individual rule performance
// CRITICAL: Deterministic, brand-scoped, auditable

import { prisma } from '@/lib/prisma';

/**
 * Rule performance metrics
 */
export interface RulePerformance {
    ruleId: string;
    ruleName: string;

    // Trigger metrics
    trigger_count: number;

    // Approval metrics
    approval_ratio: number;
    approved_count: number;
    rejected_count: number;

    // Outcome metrics (7 days after execution)
    outcome_success_rate: number;
    outcomes_measured: number;
    outcomes_successful: number;

    // Risk trend
    risk_trend: 'improving' | 'stable' | 'worsening';
    avg_risk_score: number;

    // Status
    status: 'OK' | 'REVIEW' | 'PAUSE';
    status_reason: string;

    // Period
    period_start: Date;
    period_end: Date;
}

/**
 * Evaluate rule performance
 */
export async function evaluateRulePerformance(
    brandId: string,
    ruleId: string,
    startDate: Date,
    endDate: Date
): Promise<RulePerformance> {
    // Fetch rule
    const rule = await prisma.decisionRule.findUnique({
        where: { ruleId }
    });

    if (!rule) {
        throw new Error(`Rule not found: ${ruleId}`);
    }

    // Fetch approvals for this rule
    const approvals = await prisma.approvalRequest.findMany({
        where: {
            brandId,
            ruleId,
            createdAt: {
                gte: startDate,
                lt: endDate
            }
        }
    });

    const triggerCount = approvals.length;
    const approvedCount = approvals.filter(a => a.status === 'APPROVED').length;
    const rejectedCount = approvals.filter(a => a.status === 'REJECTED').length;
    const approvalRatio = triggerCount > 0 ? approvedCount / triggerCount : 0;

    // Fetch executions for outcome analysis
    const executions = await prisma.executionLog.findMany({
        where: {
            brandId,
            ruleId,
            executedAt: {
                gte: startDate,
                lt: endDate
            }
        }
    });

    // Measure outcomes (7 days after execution)
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

    const executionsWithOutcome = executions.filter(e =>
        e.executedAt < sevenDaysAgo
    );

    const successfulOutcomes = executionsWithOutcome.filter(e => {
        // Success = no rollback and positive impact
        if (e.executionStatus === 'rolled_back') return false;

        const postMetrics = e.postMetrics as any;
        if (!postMetrics || !postMetrics.actual_impact) return false;

        return postMetrics.actual_impact > 0;
    }).length;

    const outcomeSuccessRate = executionsWithOutcome.length > 0
        ? successfulOutcomes / executionsWithOutcome.length
        : 0;

    // Calculate risk trend
    const riskScores = executions.map(e => {
        const auditData = e.auditData as any;
        return mapRiskTierToScore(auditData?.riskLevel || 'MEDIUM');
    });

    const avgRiskScore = riskScores.length > 0
        ? riskScores.reduce((a, b) => a + b, 0) / riskScores.length
        : 2;

    const riskTrend = calculateRiskTrend(executions);

    // Determine status
    const { status, statusReason } = determineRuleStatus(
        approvalRatio,
        outcomeSuccessRate,
        triggerCount,
        riskTrend
    );

    return {
        ruleId,
        ruleName: rule.name,
        trigger_count: triggerCount,
        approval_ratio: parseFloat(approvalRatio.toFixed(3)),
        approved_count: approvedCount,
        rejected_count: rejectedCount,
        outcome_success_rate: parseFloat(outcomeSuccessRate.toFixed(3)),
        outcomes_measured: executionsWithOutcome.length,
        outcomes_successful: successfulOutcomes,
        risk_trend: riskTrend,
        avg_risk_score: parseFloat(avgRiskScore.toFixed(2)),
        status,
        status_reason: statusReason,
        period_start: startDate,
        period_end: endDate
    };
}

/**
 * Map risk tier to numeric score
 */
function mapRiskTierToScore(riskTier: string): number {
    const scores: Record<string, number> = {
        'LOW': 1,
        'MEDIUM': 2,
        'HIGH': 3,
        'CRITICAL': 4
    };

    return scores[riskTier] || 2;
}

/**
 * Calculate risk trend
 */
function calculateRiskTrend(
    executions: any[]
): 'improving' | 'stable' | 'worsening' {
    if (executions.length < 5) return 'stable';

    // Split into first half and second half
    const midpoint = Math.floor(executions.length / 2);
    const firstHalf = executions.slice(0, midpoint);
    const secondHalf = executions.slice(midpoint);

    const firstAvgRisk = firstHalf.reduce((sum, e) => {
        const auditData = e.auditData as any;
        return sum + mapRiskTierToScore(auditData?.riskLevel || 'MEDIUM');
    }, 0) / firstHalf.length;

    const secondAvgRisk = secondHalf.reduce((sum, e) => {
        const auditData = e.auditData as any;
        return sum + mapRiskTierToScore(auditData?.riskLevel || 'MEDIUM');
    }, 0) / secondHalf.length;

    const delta = secondAvgRisk - firstAvgRisk;

    if (Math.abs(delta) < 0.3) return 'stable';
    if (delta < 0) return 'improving'; // Lower risk is better
    return 'worsening';
}

/**
 * Determine rule status
 */
function determineRuleStatus(
    approvalRatio: number,
    outcomeSuccessRate: number,
    triggerCount: number,
    riskTrend: 'improving' | 'stable' | 'worsening'
): {
    status: 'OK' | 'REVIEW' | 'PAUSE';
    statusReason: string;
} {
    // PAUSE if critical issues
    if (approvalRatio < 0.30 && triggerCount >= 5) {
        return {
            status: 'PAUSE',
            statusReason: `Approval ratio sangat rendah (${(approvalRatio * 100).toFixed(0)}%) - rule tidak selaras dengan ekspektasi`
        };
    }

    if (outcomeSuccessRate < 0.40 && triggerCount >= 5) {
        return {
            status: 'PAUSE',
            statusReason: `Outcome success rate rendah (${(outcomeSuccessRate * 100).toFixed(0)}%) - rule tidak efektif`
        };
    }

    if (riskTrend === 'worsening') {
        return {
            status: 'PAUSE',
            statusReason: 'Risk trend memburuk - perlu investigasi'
        };
    }

    // REVIEW if moderate concerns
    if (approvalRatio < 0.60 && triggerCount >= 3) {
        return {
            status: 'REVIEW',
            statusReason: `Approval ratio moderat (${(approvalRatio * 100).toFixed(0)}%) - review threshold atau kondisi`
        };
    }

    if (outcomeSuccessRate < 0.70 && triggerCount >= 3) {
        return {
            status: 'REVIEW',
            statusReason: `Outcome success rate moderat (${(outcomeSuccessRate * 100).toFixed(0)}%) - review efektivitas`
        };
    }

    // OK otherwise
    return {
        status: 'OK',
        statusReason: 'Rule berperforma baik'
    };
}

/**
 * Evaluate all rules for a brand
 */
export async function evaluateAllRules(
    brandId: string,
    startDate: Date,
    endDate: Date
): Promise<RulePerformance[]> {
    // Fetch all active rules for brand
    const rules = await prisma.decisionRule.findMany({
        where: {
            brandId,
            isActive: true
        }
    });

    const performances: RulePerformance[] = [];

    for (const rule of rules) {
        const performance = await evaluateRulePerformance(
            brandId,
            rule.ruleId,
            startDate,
            endDate
        );

        performances.push(performance);
    }

    // Sort by status (PAUSE first, then REVIEW, then OK)
    performances.sort((a, b) => {
        const statusOrder = { 'PAUSE': 0, 'REVIEW': 1, 'OK': 2 };
        return statusOrder[a.status] - statusOrder[b.status];
    });

    return performances;
}

// Trust Metrics - Compute trust scores for autonomous system
