    total_completed: number;
    rollbacks: number;
    auto_rollbacks: number;
    manual_rollbacks: number;

    // Forecast accuracy
    forecast_accuracy: number;
    predictions_made: number;
    predictions_within_20pct: number;

    // Time period
    period_start: Date;
    period_end: Date;
