// ACHIERA Platform - Brand Freeze Mechanisms
// Compliance and operational freeze controls

import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/observability/logger';
import { killSwitch } from './kill-switch';

export type FreezeReason =
    | 'COMPLIANCE_VIOLATION'
    | 'PAYMENT_DISPUTE'
    | 'LEGAL_HOLD'
    | 'SECURITY_INCIDENT'
    | 'FINANCIAL_AUDIT'
    | 'OWNER_REQUEST';

export type FreezeLevel =
    | 'SOFT_FREEZE'   // Read-only, no new transactions
    | 'HARD_FREEZE'   // Complete lockdown
    | 'DATA_FREEZE';  // Data export only

/**
 * Brand freeze service
 */
export class BrandFreezeService {
    /**
     * Freeze brand
     */
    async freeze(params: {
        brandId: string;
        reason: FreezeReason;
        level: FreezeLevel;
        frozenBy: string;
        notes?: string;
        expiresAt?: Date;
    }): Promise<void> {
        const log = logger.child({
            userId: params.frozenBy,
            brandId: params.brandId
        });

        // Create freeze record
        const freeze = await prisma.brandFreeze.create({
            data: {
                brandId: params.brandId,
                reason: params.reason,
                level: params.level,
                frozenBy: params.frozenBy,
                notes: params.notes,
                expiresAt: params.expiresAt,
                status: 'ACTIVE'
            }
        });

        // Activate kill-switch
        await killSwitch.activate({
            type: 'BRAND_FREEZE',
            reason: `${params.reason}: ${params.notes || ''}`,
            activatedBy: params.frozenBy,
            brandId: params.brandId,
            expiresAt: params.expiresAt
        });

        // Execute freeze actions
        await this.executeFreezeActions(params.brandId, params.level);

        // Critical alert
        log.critical(`Brand frozen: ${params.reason}`, undefined, {
            freezeId: freeze.id,
            level: params.level,
            reason: params.reason
        });

        // Audit log
        await prisma.auditLog.create({
            data: {
                userId: params.frozenBy,
                brandId: params.brandId,
                action: 'BRAND_FREEZE',
                entityType: 'BRAND',
                entityId: params.brandId,
                metadata: {
                    freezeId: freeze.id,
                    reason: params.reason,
                    level: params.level,
                    notes: params.notes
                }
            }
        });
    }

    /**
     * Unfreeze brand
     */
    async unfreeze(
        freezeId: string,
        unfrozenBy: string,
        notes: string
    ): Promise<void> {
        const freeze = await prisma.brandFreeze.findUnique({
            where: { id: freezeId }
        });

        if (!freeze) {
            throw new Error('Freeze record not found');
        }

        // Update freeze record
        await prisma.brandFreeze.update({
            where: { id: freezeId },
            data: {
                status: 'INACTIVE',
                unfrozenBy,
                unfrozenAt: new Date(),
                unfreezeNotes: notes
            }
        });

        // Reactivate brand
        await prisma.brand.update({
            where: { id: freeze.brandId },
            data: { isActive: true }
        });

        // Log
        logger.info('Brand unfrozen', {
            freezeId,
            brandId: freeze.brandId,
            reason: freeze.reason
        });

        // Audit log
        await prisma.auditLog.create({
            data: {
                userId: unfrozenBy,
                brandId: freeze.brandId,
                action: 'BRAND_UNFREEZE',
                entityType: 'BRAND',
                entityId: freeze.brandId,
                metadata: {
                    freezeId,
                    notes
                }
            }
        });
    }

    /**
     * Check if brand is frozen
     */
    async isFrozen(brandId: string): Promise<{
        frozen: boolean;
        level?: FreezeLevel;
        reason?: FreezeReason;
    }> {
        const freeze = await prisma.brandFreeze.findFirst({
            where: {
                brandId,
                status: 'ACTIVE',
                OR: [
                    { expiresAt: null },
                    { expiresAt: { gt: new Date() } }
                ]
            },
            orderBy: { createdAt: 'desc' }
        });

        if (!freeze) {
            return { frozen: false };
        }

        return {
            frozen: true,
            level: freeze.level as FreezeLevel,
            reason: freeze.reason as FreezeReason
        };
    }

    /**
     * Execute freeze actions based on level
     */
    private async executeFreezeActions(
        brandId: string,
        level: FreezeLevel
    ): Promise<void> {
        switch (level) {
            case 'SOFT_FREEZE':
                // Disable new orders and payments
                await this.disableNewTransactions(brandId);
                break;

            case 'HARD_FREEZE':
                // Complete lockdown
                await this.disableAllOperations(brandId);
                break;

            case 'DATA_FREEZE':
                // Allow data export only
                await this.enableDataExportOnly(brandId);
                break;
        }
    }

    /**
     * Disable new transactions
     */
    private async disableNewTransactions(brandId: string): Promise<void> {
        // Update brand config
        await prisma.brandConfig.upsert({
            where: { brandId },
            create: {
                brandId,
                features: {
                    orders: false,
                    payments: false
                }
            },
            update: {
                features: {
                    orders: false,
                    payments: false
                }
            }
        });
    }

    /**
     * Disable all operations
     */
    private async disableAllOperations(brandId: string): Promise<void> {
        await prisma.brand.update({
            where: { id: brandId },
            data: { isActive: false }
        });
    }

    /**
     * Enable data export only
     */
    private async enableDataExportOnly(brandId: string): Promise<void> {
        await prisma.brandConfig.upsert({
            where: { brandId },
            create: {
                brandId,
                features: {
                    dataExport: true,
                    orders: false,
                    payments: false
                }
            },
            update: {
                features: {
                    dataExport: true,
                    orders: false,
                    payments: false
                }
            }
        });
    }

    /**
     * Get freeze history for brand
     */
    async getFreezeHistory(brandId: string): Promise<any[]> {
        return prisma.brandFreeze.findMany({
            where: { brandId },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Get all frozen brands
     */
    async getAllFrozen(): Promise<any[]> {
        return prisma.brandFreeze.findMany({
            where: {
                status: 'ACTIVE',
                OR: [
                    { expiresAt: null },
                    { expiresAt: { gt: new Date() } }
                ]
            },
            include: {
                brand: {
                    select: {
                        id: true,
                        slug: true,
                        name: true
                    }
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    }
}

/**
 * Freeze check middleware
 */
export async function checkBrandFreeze(brandId: string): Promise<void> {
    const freezeService = new BrandFreezeService();
    const status = await freezeService.isFrozen(brandId);

    if (status.frozen) {
        throw new Error(
            `Brand is frozen: ${status.reason}. Level: ${status.level}`
        );
    }
}

// Export singleton
export const brandFreeze = new BrandFreezeService();

// ACHIERA Platform - Owner Kill-Switch
// Emergency shutdown and control mechanisms

import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/observability/logger';

export type KillSwitchType =
    | 'PLATFORM_SHUTDOWN'      // Complete platform shutdown
    | 'BRAND_FREEZE'           // Freeze specific brand
    | 'PAYMENTS_DISABLED'      // Disable all payments
    | 'ORDERS_DISABLED'        // Disable new orders
    | 'API_DISABLED'           // Disable API access
    | 'FEATURE_DISABLED';      // Disable specific feature

export type KillSwitchStatus = 'ACTIVE' | 'INACTIVE';

/**
 * Kill-switch service for emergency controls
 */
export class KillSwitchService {
    /**
     * Activate kill-switch
     */
    async activate(params: {
        type: KillSwitchType;
        reason: string;
        activatedBy: string;
        brandId?: string;
        featureName?: string;
        expiresAt?: Date;
    }): Promise<void> {
        const log = logger.child({
            userId: params.activatedBy,
            brandId: params.brandId
        });

        // Create kill-switch record
        const killSwitch = await prisma.killSwitch.create({
            data: {
                type: params.type,
                status: 'ACTIVE',
                reason: params.reason,
                activatedBy: params.activatedBy,
                brandId: params.brandId,
                featureName: params.featureName,
                expiresAt: params.expiresAt,
                activatedAt: new Date()
            }
        });

        // Critical alert
        log.critical(`Kill-switch activated: ${params.type}`, undefined, {
            killSwitchId: killSwitch.id,
            reason: params.reason,
            brandId: params.brandId
        });

        // Audit log
        await prisma.auditLog.create({
            data: {
                userId: params.activatedBy,
                brandId: params.brandId,
                action: 'KILL_SWITCH_ACTIVATED',
                entityType: 'SYSTEM',
                entityId: killSwitch.id,
                metadata: {
                    type: params.type,
                    reason: params.reason
                }
            }
        });

        // Execute kill-switch actions
        await this.executeKillSwitch(params.type, params.brandId);
    }

    /**
     * Deactivate kill-switch
     */
    async deactivate(
        killSwitchId: string,
        deactivatedBy: string,
        reason: string
    ): Promise<void> {
        const killSwitch = await prisma.killSwitch.findUnique({
            where: { id: killSwitchId }
        });

        if (!killSwitch) {
            throw new Error('Kill-switch not found');
        }

        // Update kill-switch
        await prisma.killSwitch.update({
            where: { id: killSwitchId },
            data: {
                status: 'INACTIVE',
                deactivatedBy,
                deactivatedAt: new Date(),
                deactivationReason: reason
            }
        });

        // Log
        logger.info('Kill-switch deactivated', {
            killSwitchId,
            type: killSwitch.type,
            reason
        });

        // Audit log
        await prisma.auditLog.create({
            data: {
                userId: deactivatedBy,
                brandId: killSwitch.brandId,
                action: 'KILL_SWITCH_DEACTIVATED',
                entityType: 'SYSTEM',
                entityId: killSwitchId,
                metadata: {
                    type: killSwitch.type,
                    reason
                }
            }
        });
    }

    /**
     * Check if kill-switch is active
     */
    async isActive(
        type: KillSwitchType,
        brandId?: string
    ): Promise<boolean> {
        const killSwitch = await prisma.killSwitch.findFirst({
            where: {
                type,
                status: 'ACTIVE',
                ...(brandId ? { brandId } : {}),
                OR: [
                    { expiresAt: null },
                    { expiresAt: { gt: new Date() } }
                ]
            }
        });

        return !!killSwitch;
    }

    /**
     * Get active kill-switches
     */
    async getActive(): Promise<any[]> {
        return prisma.killSwitch.findMany({
            where: {
                status: 'ACTIVE',
                OR: [
                    { expiresAt: null },
                    { expiresAt: { gt: new Date() } }
                ]
            },
            orderBy: { activatedAt: 'desc' }
        });
    }

    /**
     * Execute kill-switch actions
     */
    private async executeKillSwitch(
        type: KillSwitchType,
        brandId?: string
    ): Promise<void> {
        switch (type) {
            case 'PLATFORM_SHUTDOWN':
                // Set maintenance mode flag
                await this.setMaintenanceMode(true);
                break;

            case 'BRAND_FREEZE':
                if (brandId) {
                    await this.freezeBrand(brandId);
                }
                break;

            case 'PAYMENTS_DISABLED':
                // Payments will be blocked by middleware check
                break;

            case 'ORDERS_DISABLED':
                // Orders will be blocked by middleware check
                break;

            case 'API_DISABLED':
                // API will be blocked by middleware check
                break;

            case 'FEATURE_DISABLED':
                // Feature will be blocked by feature flag check
                break;
        }
    }

    /**
     * Set maintenance mode
     */
    private async setMaintenanceMode(enabled: boolean): Promise<void> {
        await prisma.systemConfig.upsert({
            where: { key: 'MAINTENANCE_MODE' },
            create: {
                key: 'MAINTENANCE_MODE',
                value: enabled.toString()
            },
            update: {
                value: enabled.toString()
            }
        });
    }

    /**
     * Freeze brand
     */
    private async freezeBrand(brandId: string): Promise<void> {
        await prisma.brand.update({
            where: { id: brandId },
            data: { isActive: false }
        });
    }

    /**
     * Check if operation is allowed
     */
    async checkOperation(
        operation: 'PAYMENT' | 'ORDER' | 'API',
        brandId?: string
    ): Promise<{ allowed: boolean; reason?: string }> {
        // Check platform shutdown
        if (await this.isActive('PLATFORM_SHUTDOWN')) {
            return {
                allowed: false,
                reason: 'Platform is in maintenance mode'
            };
        }

        // Check brand freeze
        if (brandId && await this.isActive('BRAND_FREEZE', brandId)) {
            return {
                allowed: false,
                reason: 'Brand is frozen'
            };
        }

        // Check operation-specific kill-switches
        const killSwitchMap = {
            PAYMENT: 'PAYMENTS_DISABLED',
            ORDER: 'ORDERS_DISABLED',
            API: 'API_DISABLED'
        };

        const killSwitchType = killSwitchMap[operation] as KillSwitchType;
        if (await this.isActive(killSwitchType)) {
            return {
                allowed: false,
                reason: `${operation.toLowerCase()}s are currently disabled`
            };
        }

        return { allowed: true };
    }
}

/**
 * Kill-switch middleware
 */
export async function killSwitchMiddleware(
    operation: 'PAYMENT' | 'ORDER' | 'API',
    brandId?: string
): Promise<void> {
    const killSwitch = new KillSwitchService();
    const check = await killSwitch.checkOperation(operation, brandId);

    if (!check.allowed) {
        throw new Error(check.reason || 'Operation not allowed');
    }
}

