// ACHIERA Platform - Hardened Order Creation Example
// Shows integration of all hardening utilities

import { NextRequest, NextResponse } from 'next/server';
import { withTransaction } from '@/lib/hardening/transaction';
import { withIdempotency, generateIdempotencyKey } from '@/lib/hardening/idempotency';
import { safeStockDeduction } from '@/lib/hardening/stock-safety';
import { recordRevenue } from '@/lib/hardening/ledger-integrity';
import { createLogger } from '@/lib/hardening/logger';
import { extractCorrelationId, createCorrelationContext } from '@/lib/hardening/correlation';
import { handleError } from '@/lib/hardening/error-handler';
import { BusinessErrors } from '@/lib/hardening/errors';
import { auditPaymentConfirm, auditStockMutation } from '@/lib/hardening/audit';
import { checkKillSwitch } from '@/lib/hardening/kill-switch';
import { checkWriteAllowed } from '@/lib/hardening/degradation';

export async function POST(request: NextRequest) {
    // Extract correlation ID
    const correlationId = extractCorrelationId(request.headers);

    try {
        const body = await request.json();
        const { userId, brandId, items, total, paymentMethod } = body;

        // Create correlation context
        const context = createCorrelationContext(correlationId, brandId, userId);
        const logger = createLogger({ ...context, action: 'ORDER_CREATE' });

        logger.info('Creating order', { itemCount: items.length, total });

        // Check kill switch
        const killSwitchCheck = await checkKillSwitch('FREEZE_ALL_ORDERS', brandId);
        if (!killSwitchCheck.allowed) {
            throw BusinessErrors.BRAND_FROZEN(brandId);
        }

        // Check degradation mode
        const writeCheck = await checkWriteAllowed();
        if (!writeCheck.allowed) {
            throw new Error(writeCheck.reason);
        }

        // Generate idempotency key
        const idempotencyKey = generateIdempotencyKey('create_order', userId, items, total);

        // Execute with idempotency
        const order = await withIdempotency(idempotencyKey, async () => {
            return withTransaction(async (tx) => {
                // 1. Create order
                const order = await tx.order.create({
                    data: {
                        brandId,
                        userId,
                        orderNumber: `ORD-${Date.now()}`,
                        total,
                        paymentMethod,
                        status: 'PENDING',
                        paymentStatus: 'UNPAID'
                    }
                });

                logger.info('Order created', { orderId: order.id });

                // 2. Create order items
                for (const item of items) {
                    await tx.orderItem.create({
                        data: {
                            orderId: order.id,
                            variantId: item.variantId,
                            quantity: item.quantity,
                            price: item.price
                        }
                    });
                }

                // 3. Deduct stock (FIFO-safe)
                for (const item of items) {
                    const beforeStock = await tx.frozenVariant.findUnique({
                        where: { id: item.variantId },
                        select: { stockOnHand: true }
                    });

                    await safeStockDeduction(tx, item.variantId, item.quantity, order.id);

                    const afterStock = await tx.frozenVariant.findUnique({
                        where: { id: item.variantId },
                        select: { stockOnHand: true }
                    });

                    // Audit stock mutation
                    await auditStockMutation(
                        context,
                        item.variantId,
                        item.quantity,
                        'DEDUCT',
                        beforeStock?.stockOnHand || 0,
                        afterStock?.stockOnHand || 0
                    );
                }

                // 4. Record payment
                const payment = await tx.payment.create({
                    data: {
                        orderId: order.id,
                        amount: total,
                        method: paymentMethod,
                        status: 'PAID',
                        paidAt: new Date()
                    }
                });

                // 5. Update order status
                await tx.order.update({
                    where: { id: order.id },
                    data: {
                        paymentStatus: 'PAID',
                        status: 'PROCESSING',
                        paidAt: new Date()
                    }
                });

                // 6. Record revenue in ledger (double-entry)
                await recordRevenue(brandId, total, order.id);

                // 7. Audit payment confirmation
                await auditPaymentConfirm(context, order.id, total, paymentMethod);

                logger.info('Order completed', { orderId: order.id });

                return order;
            });
        });

        // Return success response with correlation ID
        return NextResponse.json(
            { order, correlationId },
            {
                headers: {
                    'X-Correlation-ID': correlationId
                }
            }
        );

    } catch (error) {
        const context = createCorrelationContext(correlationId);
        return handleError(error as Error, context);
    }
}

// ACHIERA Platform - Health & Integrity Checks
// Ledger balance, stock consistency, orphan transaction detection

import { prisma } from '@/lib/prisma';
import { verifyLedgerIntegrity } from './ledger-integrity';
import { triggerReadOnlyMode } from './degradation';
import { createLogger } from './logger';

type HealthCheckResult = {
    healthy: boolean;
    checks: {
        ledgerBalance: { passed: boolean; errors?: any[] };
        stockConsistency: { passed: boolean; errors?: any[] };
        orphanTransactions: { passed: boolean; count?: number };
    };
};

/**
 * Run all health checks
 */
export async function runHealthChecks(brandId?: string): Promise<HealthCheckResult> {
    const logger = createLogger({
        correlationId: 'HEALTH_CHECK',
        brandId,
        action: 'HEALTH_CHECK'
    });

    const result: HealthCheckResult = {
        healthy: true,
        checks: {
            ledgerBalance: { passed: true },
            stockConsistency: { passed: true },
            orphanTransactions: { passed: true }
        }
    };

    // Check ledger balance
    try {
        const ledgerCheck = await checkLedgerBalance(brandId);
        result.checks.ledgerBalance = ledgerCheck;

        if (!ledgerCheck.passed) {
            result.healthy = false;
            logger.error('Ledger balance check failed', undefined, {
                errors: ledgerCheck.errors
            });

            // Trigger read-only mode
            await triggerReadOnlyMode('Ledger imbalance detected');
        }
    } catch (error) {
        result.checks.ledgerBalance = { passed: false };
        result.healthy = false;
    }

    // Check stock consistency
    try {
        const stockCheck = await checkStockConsistency();
        result.checks.stockConsistency = stockCheck;

        if (!stockCheck.passed) {
            result.healthy = false;
            logger.error('Stock consistency check failed', undefined, {
                errors: stockCheck.errors
            });
        }
    } catch (error) {
        result.checks.stockConsistency = { passed: false };
        result.healthy = false;
    }

    // Check orphan transactions
    try {
        const orphanCheck = await checkOrphanTransactions();
        result.checks.orphanTransactions = orphanCheck;

        if (!orphanCheck.passed) {
            result.healthy = false;
            logger.warn('Orphan transactions detected', {
                count: orphanCheck.count
            });
        }
    } catch (error) {
        result.checks.orphanTransactions = { passed: false };
        result.healthy = false;
    }

    return result;
}

/**
 * Check ledger balance
 */
async function checkLedgerBalance(brandId?: string): Promise<{
    passed: boolean;
    errors?: any[];
}> {
    if (brandId) {
        const result = await verifyLedgerIntegrity(brandId);
        return {
            passed: result.isValid,
            errors: result.errors
        };
    }

    // Check all brands
    const brands = await prisma.brand.findMany({
        where: { isActive: true },
        select: { id: true }
    });

    const allErrors = [];

    for (const brand of brands) {
        const result = await verifyLedgerIntegrity(brand.id);
        if (!result.isValid) {
            allErrors.push(...result.errors);
        }
    }

    return {
        passed: allErrors.length === 0,
        errors: allErrors
    };
}

/**
 * Check stock consistency
 */
async function checkStockConsistency(): Promise<{
    passed: boolean;
    errors?: any[];
}> {
    const negativeStock = await prisma.frozenVariant.findMany({
        where: {
            stockOnHand: { lt: 0 }
        },
        select: {
            id: true,
            sku: true,
            stockOnHand: true
        }
    });

    return {
        passed: negativeStock.length === 0,
        errors: negativeStock
    };
}

/**
 * Check orphan transactions
 */
async function checkOrphanTransactions(): Promise<{
    passed: boolean;
    count?: number;
}> {
    // Find journal transactions without entries
    const orphans = await prisma.journalTransaction.findMany({
        where: {
            entries: {
                none: {}
            }
        }
    });

    return {
        passed: orphans.length === 0,
        count: orphans.length
    };
}

// ACHIERA Platform - Idempotency System
// Prevents duplicate payments, webhooks, and critical retries

import { prisma } from '@/lib/prisma';
import { withTransaction } from './transaction';
import crypto from 'crypto';

export class IdempotencyError extends Error {
    constructor(
        message: string,
        public readonly existingResult?: any
    ) {
        super(message);
        this.name = 'IdempotencyError';
    }
}

type IdempotencyStatus = 'PROCESSING' | 'COMPLETED' | 'FAILED';

/**
 * Generate idempotency key from inputs
 */
export function generateIdempotencyKey(
    operation: string,
    ...params: any[]
): string {
    const data = JSON.stringify({ operation, params });
    return crypto.createHash('sha256').update(data).digest('hex');
}

/**
 * Execute operation with idempotency guarantee
 * Used by: Payments, Webhooks, Critical retries
 */
export async function withIdempotency<T>(
    key: string,
    operation: () => Promise<T>,
    ttlSeconds: number = 86400 // 24 hours
): Promise<T> {
    return withTransaction(async (tx) => {
        // Check existing
        const existing = await tx.idempotencyKey.findUnique({
            where: { key }
        });

        if (existing) {
            if (existing.status === 'COMPLETED') {
                // Return cached result
                return existing.result as T;
            }

            if (existing.status === 'PROCESSING') {
                throw new IdempotencyError(
                    'Operation already in progress',
                    existing.result
                );
            }

            // FAILED - allow retry, delete old record
            await tx.idempotencyKey.delete({
                where: { key }
            });
        }

        // Create PROCESSING record
        await tx.idempotencyKey.create({
            data: {
                key,
                status: 'PROCESSING',
                expiresAt: new Date(Date.now() + ttlSeconds * 1000)
            }
        });

        try {
            // Execute operation
            const result = await operation();

            // Update to COMPLETED
            await tx.idempotencyKey.update({
                where: { key },
                data: {
                    status: 'COMPLETED',
                    result: result as any,
                    completedAt: new Date()
                }
            });

            return result;

        } catch (error) {
            // Update to FAILED
            await tx.idempotencyKey.update({
                where: { key },
                data: {
                    status: 'FAILED',
                    result: { error: (error as Error).message }
                }
            });

            throw error;
        }
    });
}

/**
 * Cleanup expired idempotency keys (run via cron)
 */
export async function cleanupExpiredKeys(): Promise<number> {
    const result = await prisma.idempotencyKey.deleteMany({
        where: {
            expiresAt: {
                lt: new Date()
            }
        }
    });

    return result.count;
}

// ACHIERA Platform - System Kill Switch
// OWNER can freeze orders, brand, or finance operations

import { prisma } from '@/lib/prisma';
import { createLogger } from './logger';
import type { CorrelationContext } from './correlation';

export type KillSwitchType =
    | 'FREEZE_ALL_ORDERS'
    | 'FREEZE_BRAND'
    | 'FREEZE_FINANCE';

/**
 * Check if operation is allowed (enforced server-side)
 */
export async function checkKillSwitch(
    type: KillSwitchType,
    brandId?: string
): Promise<{ allowed: boolean; reason?: string }> {
    const active = await prisma.killSwitch.findFirst({
        where: {
            type,
            status: 'ACTIVE',
            ...(brandId ? { brandId } : {}),
            OR: [
                { expiresAt: null },
                { expiresAt: { gt: new Date() } }
            ]
        }
    });

    if (active) {
        return {
            allowed: false,
            reason: active.reason
        };
    }

    return { allowed: true };
}

/**
 * Activate kill switch (OWNER only)
 */
export async function activateKillSwitch(
    context: CorrelationContext,
    type: KillSwitchType,
    reason: string,
    brandId?: string,
    expiresAt?: Date
): Promise<void> {
    const logger = createLogger({
        ...context,
        action: 'KILL_SWITCH_ACTIVATE'
    });

    const killSwitch = await prisma.killSwitch.create({
        data: {
            type,
            status: 'ACTIVE',
            reason,
            activatedBy: context.userId!,
            brandId,
            expiresAt,
            activatedAt: new Date()
        }
    });

    logger.critical(`Kill switch activated: ${type}`, undefined, {
        killSwitchId: killSwitch.id,
        reason,
        brandId
    });

    // Audit log
    await prisma.auditLog.create({
        data: {
            userId: context.userId,
            brandId,
            action: 'KILL_SWITCH_ACTIVATED',
            entityType: 'SYSTEM',
            entityId: killSwitch.id,
            metadata: {
                type,
                reason,
                correlationId: context.correlationId
            } as any
        }
    });
}

/**
 * Deactivate kill switch
 */
export async function deactivateKillSwitch(
    context: CorrelationContext,
    killSwitchId: string
): Promise<void> {
    await prisma.killSwitch.update({
        where: { id: killSwitchId },
        data: {
            status: 'INACTIVE',
            deactivatedBy: context.userId!,
            deactivatedAt: new Date()
        }
    });

    const logger = createLogger({
        ...context,
        action: 'KILL_SWITCH_DEACTIVATE'
    });

    logger.info('Kill switch deactivated', { killSwitchId });
}

// ACHIERA Platform - Ledger Integrity Guard
// Debit = Credit enforcement with brand isolation

import { Prisma, PrismaClient } from '@prisma/client';
import { prisma } from '@/lib/prisma';
import { withTransaction } from './transaction';

export class LedgerImbalanceError extends Error {
    constructor(
        message: string,
        public readonly debit: number,
        public readonly credit: number
    ) {
        super(message);
        this.name = 'LedgerImbalanceError';
    }
}

type LedgerEntry = {
    accountCode: string;
    debit: number;
    credit: number;
};

/**
 * Post balanced ledger entry (double-entry enforced)
 * Brand-isolated ledger with automatic imbalance detection
 */
export async function postLedgerEntry(
    brandId: string,
    description: string,
    entries: LedgerEntry[],
    referenceId?: string,
    tx?: PrismaClient
): Promise<string> {
    const operation = async (client: PrismaClient) => {
        // Validate balance
        const totalDebit = entries.reduce((sum: number, e: LedgerEntry) => sum + e.debit, 0);
        const totalCredit = entries.reduce((sum: number, e: LedgerEntry) => sum + e.credit, 0);

        if (Math.abs(totalDebit - totalCredit) > 0.01) {
            throw new LedgerImbalanceError(
                'Ledger entries do not balance',
                totalDebit,
                totalCredit
            );
        }

        // Create transaction
        const transaction = await client.journalTransaction.create({
            data: {
                brandId,
                description,
                referenceId,
                date: new Date()
            }
        });

        // Create entries
        for (const entry of entries) {
            // Get account
            const account = await client.ledgerAccount.findFirst({
                where: {
                    brandId,
                    code: entry.accountCode
                }
            });

            if (!account) {
                throw new Error(`Account ${entry.accountCode} not found for brand ${brandId}`);
            }

            // Create entry
            await client.journalEntry.create({
                data: {
                    transactionId: transaction.id,
                    accountId: account.id,
                    debit: entry.debit,
                    credit: entry.credit
                }
            });
        }

        // Verify transaction balance (double-check)
        const createdEntries = await client.journalEntry.findMany({
            where: { transactionId: transaction.id }
        });

        const verifyDebit = createdEntries.reduce((sum: number, e: any) => sum + Number(e.debit), 0);
        const verifyCredit = createdEntries.reduce((sum: number, e: any) => sum + Number(e.credit), 0);

        if (Math.abs(verifyDebit - verifyCredit) > 0.01) {
            throw new LedgerImbalanceError(
                'Transaction verification failed',
                verifyDebit,
                verifyCredit
            );
        }

        return transaction.id;
    };

    if (tx) {
        return operation(tx);
    }
    return withTransaction(operation);
}

/**
 * Verify all transactions balance (integrity check)
 */
export async function verifyLedgerIntegrity(brandId: string): Promise<{
    isValid: boolean;
    errors: Array<{ transactionId: string; debit: number; credit: number }>;
}> {
    const transactions = await prisma.journalTransaction.findMany({
        where: { brandId },
        include: { entries: true }
    });

    const errors = [];

    for (const tx of transactions) {
        const debit = tx.entries.reduce((sum: number, e: any) => sum + Number(e.debit), 0);
        const credit = tx.entries.reduce((sum: number, e: any) => sum + Number(e.credit), 0);

        if (Math.abs(debit - credit) > 0.01) {
            errors.push({
                transactionId: tx.id,
                debit,
                credit
            });
        }
    }

    return {
        isValid: errors.length === 0,
        errors
    };
}

/**
 * Record revenue (helper)
 */
export async function recordRevenue(
    brandId: string,
    amount: number,
    orderId: string,
    tx?: PrismaClient
): Promise<string> {
    return postLedgerEntry(
        brandId,
        `Revenue from order ${orderId}`,
        [
            { accountCode: '1000-CASH', debit: amount, credit: 0 },
            { accountCode: '4000-REVENUE', debit: 0, credit: amount }
        ],
        orderId,
        tx
    );
}

/**
 * Record refund (helper)
 */
export async function recordRefund(
    brandId: string,
    amount: number,
    orderId: string,
    tx?: PrismaClient
): Promise<string> {
    return postLedgerEntry(
        brandId,
        `Refund for order ${orderId}`,
        [
            { accountCode: '4000-REVENUE', debit: amount, credit: 0 },
            { accountCode: '1000-CASH', debit: 0, credit: amount }
        ],
        orderId,
        tx
    );
}

// ACHIERA Platform - Structured Logging System
// JSON logs with mandatory correlation tracking

import { prisma } from '@/lib/prisma';

export type LogSeverity = 'DEBUG' | 'INFO' | 'WARN' | 'ERROR' | 'CRITICAL';

export type LogContext = {
    correlationId: string;
    brandId?: string;
    userId?: string;
    action: string;
    entityId?: string;
};

/**
 * Sensitive field patterns to mask in logs
 */
const SENSITIVE_FIELDS = [
    'password', 'token', 'apiKey', 'secret', 'authorization',
    'cardNumber', 'cvv', 'pin', 'ssn', 'taxId',
    'privateKey', 'accessToken', 'refreshToken'
];

/**
 * Mask sensitive data in logs (PII protection)
 */
function sanitizeLogData(data: any): any {
    if (!data || typeof data !== 'object') {
        return data;
    }

    if (Array.isArray(data)) {
        return data.map(item => sanitizeLogData(item));
    }

    const sanitized: any = {};
    for (const [key, value] of Object.entries(data)) {
        const lowerKey = key.toLowerCase();

        // Mask sensitive fields
        if (SENSITIVE_FIELDS.some(field => lowerKey.includes(field))) {
            sanitized[key] = '[REDACTED]';
        }
        // Partially mask email
        else if (lowerKey === 'email' && typeof value === 'string') {
            const [local, domain] = value.split('@');
            if (local && domain) {
                sanitized[key] = `${local[0]}***@${domain}`;
            } else {
                sanitized[key] = '[REDACTED]';
            }
        }
        // Partially mask phone
        else if (lowerKey === 'phone' && typeof value === 'string') {
            const digits = value.replace(/\D/g, '');
            if (digits.length >= 4) {
                sanitized[key] = `***${digits.slice(-4)}`;
            } else {
                sanitized[key] = '[REDACTED]';
            }
        }
        // Recursively sanitize nested objects
        else if (typeof value === 'object' && value !== null) {
            sanitized[key] = sanitizeLogData(value);
        }
        else {
            sanitized[key] = value;
        }
    }
    return sanitized;
}

type LogEntry = LogContext & {
    severity: LogSeverity;
    message: string;
    metadata?: Record<string, any>;
    error?: {
        name: string;
        message: string;
        stack?: string;
    };
    timestamp: string;
};

/**
 * Structured logger with mandatory fields
 */
export class Logger {
    private context: Partial<LogContext>;

    constructor(context: Partial<LogContext> = {}) {
        this.context = context;
    }

    /**
     * Create child logger with additional context
     */
    child(context: Partial<LogContext>): Logger {
        return new Logger({
            ...this.context,
            ...context
        });
    }

    /**
     * Log info
     */
    info(message: string, metadata?: Record<string, any>): void {
        this.log('INFO', message, metadata);
    }

    /**
     * Log warning
     */
    warn(message: string, metadata?: Record<string, any>): void {
        this.log('WARN', message, metadata);
    }

    /**
     * Log error
     */
    error(message: string, error?: Error, metadata?: Record<string, any>): void {
        this.log('ERROR', message, metadata, error);
    }

    /**
     * Log critical (triggers alerts)
     */
    critical(message: string, error?: Error, metadata?: Record<string, any>): void {
        this.log('CRITICAL', message, metadata, error);
    }

    /**
     * Core log method
     */
    private log(
        severity: LogSeverity,
        message: string,
        metadata?: Record<string, any>,
        error?: Error
    ): void {
        const entry: LogEntry = {
            correlationId: this.context.correlationId || 'MISSING',
            brandId: this.context.brandId,
            userId: this.context.userId,
            action: this.context.action || 'UNKNOWN',
            entityId: this.context.entityId,
            severity,
            message,
            metadata: metadata ? sanitizeLogData(metadata) : undefined,
            timestamp: new Date().toISOString()
        };

        if (error) {
            entry.error = {
                name: error.name,
                message: error.message,
                stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
            };
        }

        // JSON output
        console.log(JSON.stringify(entry));

        // Persist critical logs
        if (severity === 'ERROR' || severity === 'CRITICAL') {
            this.persistLog(entry).catch(err => {
                console.error('Failed to persist log:', err);
            });
        }
    }

    /**
     * Persist log to database
     */
    private async persistLog(entry: LogEntry): Promise<void> {
        try {
            await prisma.systemLog.create({
                data: {
                    level: entry.severity,
                    message: entry.message,
                    context: {
                        correlationId: entry.correlationId,
                        brandId: entry.brandId,
                        userId: entry.userId,
                        action: entry.action,
                        entityId: entry.entityId
                    } as any,
                    error: entry.error as any,
                    metadata: entry.metadata as any,
                    timestamp: new Date(entry.timestamp)
                }
            });
        } catch (error) {
            // Silent fail - don't break app for logging
            console.error('Log persistence failed:', error);
        }
    }
}

/**
 * Create logger with correlation ID
 */
export function createLogger(context: Partial<LogContext>): Logger {
    return new Logger(context);
}

// ACHIERA Platform - Refund Process
// Transactional refund with stock restoration and ledger reversal

import { PrismaClient } from '@prisma/client';
import { withTransaction } from './transaction';
import { withIdempotency, generateIdempotencyKey } from './idempotency';
import { recordRefund } from './ledger-integrity';
import { BusinessErrors } from './errors';
import { CorrelationContext } from './correlation';
import { auditRefund } from './audit';

/**
 * Safe stock addition (reverse of deduction)
 */
async function safeStockAddition(
    tx: PrismaClient,
    variantId: string,
    quantity: number,
    referenceId: string
): Promise<void> {
    // Update stock on hand
    await tx.frozenVariant.update({
        where: { id: variantId },
        data: {
            stockOnHand: {
                increment: quantity
            }
        }
    });

    // Create inventory batch for restored stock
    await tx.inventoryBatch.create({
        data: {
            variantId,
            quantity,
            receivedAt: new Date(),
            expiryDate: null, // Restored stock doesn't have expiry
            batchNumber: `REFUND-${referenceId}`,
            cost: 0 // Cost already recorded in original purchase
        }
    });
}

/**
 * Process refund with full transaction safety
 */
export async function processRefund(
    orderId: string,
    amount: number,
    context: CorrelationContext
): Promise<{ id: string; status: string }> {
    const idempotencyKey = generateIdempotencyKey('refund', orderId, amount);

    return withIdempotency(idempotencyKey, async () => {
        return withTransaction(async (tx) => {
            // 1. Verify order is refundable
            const order = await tx.order.findUnique({
                where: { id: orderId },
                include: {
                    items: {
                        include: {
                            variant: true
                        }
                    }
                }
            });

            if (!order) {
                throw BusinessErrors.ORDER_NOT_FOUND(orderId);
            }

            if (order.status === 'REFUNDED') {
                throw BusinessErrors.ALREADY_REFUNDED(orderId);
            }

            if (order.paymentStatus !== 'PAID') {
                throw new Error('Cannot refund unpaid order');
            }

            // 2. Create refund record
            const refund = await tx.refund.create({
                data: {
                    orderId,
                    amount,
                    status: 'PROCESSING',
                    reason: 'Customer request',
                    createdAt: new Date()
                }
            });

            // 3. Restore stock for each item
            for (const item of order.items) {
                await safeStockAddition(
                    tx,
                    item.variantId,
                    item.quantity,
                    refund.id
                );
            }

            // 4. Record refund in ledger (reversal entry)
            await recordRefund(order.brandId, amount, orderId, tx);

            // 5. Update order status
            await tx.order.update({
                where: { id: orderId },
                data: {
                    status: 'REFUNDED',
                    paymentStatus: 'REFUNDED',
                    refundedAt: new Date()
                }
            });

            // 6. Update refund status
            await tx.refund.update({
                where: { id: refund.id },
                data: {
                    status: 'COMPLETED',
                    completedAt: new Date()
                }
            });

            // 7. Audit trail
            await auditRefund(context, orderId, amount);

            return {
                id: refund.id,
                status: 'COMPLETED'
            };
        });
    });
}

/**
 * Partial refund (for specific items)
 */
export async function processPartialRefund(
    orderId: string,
    items: Array<{ variantId: string; quantity: number; amount: number }>,
    context: CorrelationContext
): Promise<{ id: string; status: string }> {
    const totalAmount = items.reduce((sum, item) => sum + item.amount, 0);
    const idempotencyKey = generateIdempotencyKey('partial_refund', orderId, items);

    return withIdempotency(idempotencyKey, async () => {
        return withTransaction(async (tx) => {
            // 1. Verify order
            const order = await tx.order.findUnique({
                where: { id: orderId },
                include: { items: true }
            });

            if (!order) {
                throw BusinessErrors.ORDER_NOT_FOUND(orderId);
            }

            // 2. Create partial refund record
            const refund = await tx.refund.create({
                data: {
                    orderId,
                    amount: totalAmount,
                    status: 'PROCESSING',
                    reason: 'Partial refund',
                    metadata: { items } as any
                }
            });

            // 3. Restore stock for refunded items
            for (const item of items) {
                await safeStockAddition(
                    tx,
                    item.variantId,
                    item.quantity,
                    refund.id
                );
            }

            // 4. Record partial refund in ledger
            await recordRefund(order.brandId, totalAmount, orderId, tx);

            // 5. Update refund status
            await tx.refund.update({
                where: { id: refund.id },
                data: {
                    status: 'COMPLETED',
                    completedAt: new Date()
                }
            });

            // 6. Audit trail
            await auditRefund(context, orderId, totalAmount);

            return {
                id: refund.id,
                status: 'COMPLETED'
            };
        });
    });
}

// ACHIERA Platform - Stock Safety Enforcement
// Hard guard against negative stock with FIFO-safe mutation

import { PrismaClient } from '@prisma/client';
import { withTransaction } from './transaction';

export class StockViolationError extends Error {
    constructor(
        message: string,
        public readonly variantId: string,
        public readonly requested: number,
        public readonly available: number
    ) {
        super(message);
        this.name = 'StockViolationError';
    }
}

/**
 * Safely deduct stock with negative prevention
 * FIFO-safe mutation with automatic rollback on violation
 */
export async function safeStockDeduction(
    tx: PrismaClient,
    variantId: string,
    quantity: number,
    orderId: string
): Promise<void> {
    // Lock row for update
    const variant = await (tx as any).$queryRaw<Array<{ id: string; stockOnHand: number }>>`
    SELECT id, stockOnHand 
    FROM frozen_variants 
    WHERE id = ${variantId} 
    FOR UPDATE
  `;

    if (!variant || variant.length === 0) {
        throw new Error(`Variant ${variantId} not found`);
    }

    const currentStock = variant[0].stockOnHand;

    // Check sufficient stock
    if (currentStock < quantity) {
        throw new StockViolationError(
            'Insufficient stock',
            variantId,
            quantity,
            currentStock
        );
    }

    // Deduct stock
    await tx.frozenVariant.update({
        where: { id: variantId },
        data: {
            stockOnHand: {
                decrement: quantity
            }
        }
    });

    // Verify no negative (race condition check)
    const updated = await tx.frozenVariant.findUnique({
        where: { id: variantId },
        select: { stockOnHand: true }
    });

    if (updated && updated.stockOnHand < 0) {
        throw new StockViolationError(
            'Stock went negative - concurrent modification detected',
            variantId,
            quantity,
            currentStock
        );
    }
}

/**
 * Safely add stock
 */
export async function safeStockAddition(
    tx: PrismaClient,
    variantId: string,
    quantity: number,
    batchCode: string
): Promise<void> {
    await tx.frozenVariant.update({
        where: { id: variantId },
        data: {
            stockOnHand: {
                increment: quantity
            }
        }
    });
}

/**
 * Batch stock deduction (atomic)
 */
export async function batchStockDeduction(
    items: Array<{ variantId: string; quantity: number }>,
    orderId: string
): Promise<void> {
    await withTransaction(async (tx) => {
        for (const item of items) {
            await safeStockDeduction(tx, item.variantId, item.quantity, orderId);
        }
    });
}

