            // Verify stock didn't go negative
            const variant = await tx.frozenVariant.findUnique({
                where: { id: item.variantId },
                select: { stockOnHand: true }
            });

            if (variant && variant.stockOnHand < 0) {
                throw new Error('Insufficient stock');
            }
        }

