    );

    const totalMonthlyRevenue = pulses.reduce((sum, p) => sum + p.pulse.monthlyRevenue, 0);
    const totalMonthlyNetProfit = pulses.reduce((sum, p) => sum + p.pulse.monthlyNetProfit, 0);
    const totalMonthlyCOGS = pulses.reduce((sum, p) => sum + p.pulse.monthlyCOGS, 0);

    const brandPerformance = pulses.map(({ brand, pulse }) => ({
        brandName: brand.name,
        brandSlug: brand.slug,
        revenue: pulse.monthlyRevenue,
        profit: pulse.monthlyNetProfit,
        margin: pulse.monthlyRevenue > 0 ? (pulse.monthlyNetProfit / pulse.monthlyRevenue) * 100 : 0,
        contribution: totalMonthlyRevenue > 0 ? (pulse.monthlyRevenue / totalMonthlyRevenue) * 100 : 0
    }));

    // Combine revenue trends
    const trendMap: Record<string, number> = {};
    pulses.forEach(({ pulse }) => {
        pulse.revenueTrend.forEach((t) => {
            trendMap[t.date] = (trendMap[t.date] || 0) + t.amount;
        });
    });

    const combinedRevenueTrend = Object.entries(trendMap)
        .map(([date, amount]) => ({ date, amount }))
        .sort((a, b) => a.date.localeCompare(b.date));

    return {
        totalMonthlyRevenue,
        totalMonthlyNetProfit,
        totalMonthlyCOGS,
        brandPerformance,
        combinedRevenueTrend
    };
}
export interface PricingRecommendation {
    hpp: number;
    overhead: number;
    trueHpp: number;
    marketplaceFee: number;
    netMargin: number;
    recommendedPrice: number;
    breakdown: {
        label: string;
        value: number;
        percentage: number;
    }[];
    isDynamic: boolean;
    totalMonthlyOpex: number;
}

export async function getPricingRecommendation(brandId: string, costPrice: number): Promise<PricingRecommendation> {
    try {
        const now = new Date();
        const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

        const brand = await prisma.brand.findUnique({
            where: { id: brandId },
            select: { paymentSettings: true }
        });

        const config = await prisma.brandConfig.findUnique({
            where: { brandId }
        });

        // 1. Fetch Real Expenses (OPEX) for current month
        const ledgerExpenses = await prisma.journalEntry.aggregate({
            where: {
                account: {
                    brandId,
                    code: { startsWith: '5-', not: '5-1000' } // Exclude HPP
                },
                createdAt: { gte: startOfMonth }
            },
            _sum: { debit: true, credit: true }
        });

        const monthlyLedgerExpenses = Number(ledgerExpenses._sum.debit || 0) - Number(ledgerExpenses._sum.credit || 0);
        const targetVolume = Number(config?.targetMonthlyVolume || 100);

        // 2. Calculate Dynamic Overhead
        let overhead = Number(config?.defaultOverheadPerUnit || 0);
        let isDynamic = false;

        if (monthlyLedgerExpenses > 0) {
            overhead = monthlyLedgerExpenses / targetVolume;
            isDynamic = true;
        }

        // 3. Calculate True HPP
        const trueHpp = costPrice + overhead;

        // 4. Define Benchmark (Use config or fallback)
        const marketplaceFeeRate = Number(config?.marketplaceFeeRate || 0.15);
        const targetNetMarginRate = Number(config?.targetNetMarginRate || 0.30);

        // 5. Formula: Price = TrueHPP / (1 - (Fee% + Margin%))
        const divisor = 1 - (marketplaceFeeRate + targetNetMarginRate);
        const recommendedPrice = Math.ceil(trueHpp / divisor);

        const marketplaceFeeAmount = recommendedPrice * marketplaceFeeRate;
        const netProfitAmount = recommendedPrice - trueHpp - marketplaceFeeAmount;

        return {
            hpp: costPrice,
            overhead,
            trueHpp,
            marketplaceFee: marketplaceFeeAmount,
            netMargin: netProfitAmount,
            recommendedPrice,
            isDynamic,
            totalMonthlyOpex: monthlyLedgerExpenses,
            breakdown: [
                { label: 'Modal Bahan (HPP)', value: costPrice, percentage: (costPrice / recommendedPrice) * 100 },
                { label: 'Operasional (Overhead)', value: overhead, percentage: (overhead / recommendedPrice) * 100 },
                { label: 'Biaya Platform (Est. 15%)', value: marketplaceFeeAmount, percentage: marketplaceFeeRate * 100 },
                { label: 'Keuntungan Bersih (Margin)', value: netProfitAmount, percentage: (netProfitAmount / recommendedPrice) * 100 }
            ]
        };
    } catch (error) {
        console.error('Pricing Recommendation Error:', error);
        // Fallback to simple markup if something fails
        const fallbackPrice = costPrice * 2;
        return {
            hpp: costPrice,
            overhead: 0,
            trueHpp: costPrice,
            marketplaceFee: 0,
            netMargin: costPrice,
            recommendedPrice: fallbackPrice,
            isDynamic: false,
            totalMonthlyOpex: 0,
            breakdown: []
        };
    }
}

/**
 * Smart Recipe Costing & Optimization
 * Calculates True HPP based on real batch costs and flags volatility.
 */
export async function getRecipeCostingData(brandId: string) {
    if (!brandId) return { success: false, error: 'Missing Brand ID' };

    try {
        const recipes = await prisma.recipe.findMany({
            where: { brandId },
            include: {
                items: {
                    include: {
                        ingredient: true
                    }
                },
                frozenVariant: true
            }
        });

        const analysis = recipes.map(recipe => {
            let totalCost = 0;
            const itemDetails = recipe.items.map(item => {
                const cost = Number(item.ingredient.costPrice) * Number(item.quantity);
                totalCost += cost;
                return {
                    name: item.ingredient.name,
                    quantity: Number(item.quantity),
                    unit: item.unit,
                    costPerUnit: Number(item.ingredient.costPrice),
                    totalCost: cost
                };
            });

            const currentPrice = Number(recipe.frozenVariant?.price || 0);
            const currentMargin = currentPrice > 0 ? ((currentPrice - totalCost) / currentPrice) * 100 : 0;
            const targetMargin = Number(recipe.frozenVariant?.targetMargin || 0.3) * 100;

            return {
                recipeId: recipe.id,
                name: recipe.name,
                trueHpp: totalCost,
                currentPrice,
                currentMargin,
                targetMargin,
                isSuboptimal: currentMargin < targetMargin,
                items: itemDetails
            };
        });

        return {
            success: true,
            data: analysis.filter(a => a.currentPrice > 0).sort((a, b) => a.currentMargin - b.currentMargin)
        };
    } catch (error: any) {
        console.error('[IntelEngine] Recipe Costing Error:', error);
        return { success: false, error: error.message };
    }
}

import { prisma } from '@/lib/prisma';
import { AccountType } from '@prisma/client';
import { getAccountByCode } from './chartOfAccounts';

export type DateRange = {
    start: Date;
    end: Date;
};

/**
 * Financial Reports Engine
 */
export class FinancialReports {

    /**
     * Generate Profit & Loss Statement (Income Statement)
     * @param consolidated - If true, excludes inter-company revenue/expense accounts
     */
    static async getProfitLoss(brandId: string, range: DateRange, consolidated = false) {
        // 1. Fetch Tax Settings
        const brand = await prisma.brand.findUnique({
            where: { id: brandId },
            select: { paymentSettings: true }
        });
        const settings = (brand?.paymentSettings as any) || { taxRates: { PPN: 11, PPH: 0.5 } };
        const taxRate = settings.taxRates?.PPH || 0.5;

        // 2. Fetch Revenue and Expense Accounts
        const whereClause: any = {
            brandId,
            type: { in: ['REVENUE', 'EXPENSE'] }
        };

        if (consolidated) {
            whereClause.code = {
                notIn: ['IC_REVENUE', 'IC_EXPENSE', 'IC_RECEIVABLE', 'IC_PAYABLE']
            };
        }

        const accounts = await prisma.ledgerAccount.findMany({
            where: whereClause,
            include: {
                entries: {
                    where: {
                        createdAt: {
                            gte: range.start,
                            lte: range.end
                        }
                    }
                }
            }
        });

        const report = {
            revenue: { total: 0, items: [] as any[] },
            cogs: { total: 0, items: [] as any[] }, // Harga Pokok Penjualan
            grossProfit: 0,
            expenses: { total: 0, items: [] as any[] },
            operatingIncome: 0,
            otherIncomeExpense: { total: 0, items: [] as any[] },
            netIncomeBeforeTax: 0,
            taxAmount: 0,
            netProfit: 0,
            margin: 0
        };

        for (const acc of accounts) {
            let balance = 0;
            const debits = acc.entries.reduce((sum, e) => sum + Number(e.debit), 0);
            const credits = acc.entries.reduce((sum, e) => sum + Number(e.credit), 0);

            if (acc.type === 'REVENUE') {
                balance = credits - debits;
                if (balance !== 0) {
                    if (acc.code.startsWith('4-')) {
                        report.revenue.items.push({ code: acc.code, name: acc.name, amount: balance });
                        report.revenue.total += balance;
                    } else {
                        report.otherIncomeExpense.items.push({ code: acc.code, name: acc.name, amount: balance });
                        report.otherIncomeExpense.total += balance;
                    }
                }
            } else if (acc.code === '5-1000' || acc.code.startsWith('5-1')) { // HPP / COGS
                balance = debits - credits;
                if (balance !== 0) {
                    report.cogs.items.push({ code: acc.code, name: acc.name, amount: balance });
                    report.cogs.total += balance;
                }
            } else {
                balance = debits - credits;
                if (balance !== 0) {
                    if (acc.code.startsWith('5-9')) { // Non-operating expenses
                        report.otherIncomeExpense.items.push({ code: acc.code, name: acc.name, amount: -balance });
                        report.otherIncomeExpense.total -= balance;
                    } else {
                        report.expenses.items.push({ code: acc.code, name: acc.name, amount: balance });
                        report.expenses.total += balance;
                    }
                }
            }
        }

        report.grossProfit = report.revenue.total - report.cogs.total;
        report.operatingIncome = report.grossProfit - report.expenses.total;
        report.netIncomeBeforeTax = report.operatingIncome + report.otherIncomeExpense.total;

        // Calculate Tax (UMKM PPh Final is usually based on Gross Revenue)
        report.taxAmount = (report.revenue.total * (taxRate / 100));
        report.netProfit = report.netIncomeBeforeTax - report.taxAmount;

        const margin = report.revenue.total > 0 ? (report.netProfit / report.revenue.total) * 100 : 0;
        report.margin = isFinite(margin) ? margin : 0;

        return report;
    }

    /**
     * Generate Balance Sheet
     */
    static async getBalanceSheet(brandId: string, asOfDate: Date) {
        // 1. Fetch Asset, Liability, Equity Accounts
        const accounts = await prisma.ledgerAccount.findMany({
            where: {
                brandId,
                type: { in: ['ASSET', 'LIABILITY', 'EQUITY'] }
            }
        });

        // 2. Fetch Net Income (Retained Earnings adjustment) up to asOfDate
        const plAccounts = await prisma.ledgerAccount.findMany({
            where: {
                brandId,
                type: { in: ['REVENUE', 'EXPENSE'] }
            },
            include: {
                entries: {
                    where: { createdAt: { lte: asOfDate } }
                }
            }
        });

        let netIncomeAllTime = 0;
        for (const acc of plAccounts) {
            const debits = acc.entries.reduce((sum, e) => sum + Number(e.debit), 0);
            const credits = acc.entries.reduce((sum, e) => sum + Number(e.credit), 0);
            if (acc.type === 'REVENUE') netIncomeAllTime += (credits - debits);
            else netIncomeAllTime -= (debits - credits);
        }

        const report = {
            assets: { total: 0, items: [] as any[] },
            liabilities: { total: 0, items: [] as any[] },
            equity: { total: 0, items: [] as any[], retainedEarnings: 0 },
            isBalanced: false,
            difference: 0
        };

        for (const acc of accounts) {
            const entries = await prisma.journalEntry.aggregate({
                where: { accountId: acc.id, createdAt: { lte: asOfDate } },
                _sum: { debit: true, credit: true }
            });

            const debits = Number(entries._sum.debit || 0);
            const credits = Number(entries._sum.credit || 0);
            let balance = 0;

            if (acc.type === 'ASSET') {
                balance = debits - credits;
                if (balance !== 0) {
                    report.assets.items.push({ code: acc.code, name: acc.name, amount: balance });
                    report.assets.total += balance;
                }
            } else if (acc.type === 'LIABILITY') {
                balance = credits - debits;
                if (balance !== 0) {
                    report.liabilities.items.push({ code: acc.code, name: acc.name, amount: balance });
                    report.liabilities.total += balance;
                }
            } else if (acc.type === 'EQUITY') {
                balance = credits - debits;
                if (balance !== 0) {
                    report.equity.items.push({ code: acc.code, name: acc.name, amount: balance });
                    report.equity.total += balance;
                }
            }
        }

        // Add Net Income to Equity
        if (netIncomeAllTime !== 0) {
            report.equity.items.push({ code: 'CALC-RE', name: 'Laba/Rugi s.d Saat Ini', amount: netIncomeAllTime });
            report.equity.total += netIncomeAllTime;
        }

        report.difference = report.assets.total - (report.liabilities.total + report.equity.total);
        report.isBalanced = Math.abs(report.difference) < 1; // Tolerance for float precision

        return report;
    }

    /**
     * Generate Cash Flow Statement (Direct Method)
     */
    static async getCashFlow(brandId: string, range: DateRange) {
        // 1. Identify Cash & Bank Accounts (usually 1-1xxx)
        const cashAccounts = await prisma.ledgerAccount.findMany({
            where: {
                brandId,
                code: { startsWith: '1-1' } // Kas & Bank
            }
        });
        const cashAccountIds = cashAccounts.map(a => a.id);

        // 2. Fetch all entries involving these accounts in range
        const entries = await prisma.journalEntry.findMany({
            where: {
                accountId: { in: cashAccountIds },
                createdAt: { gte: range.start, lte: range.end }
            },
            include: {
                transaction: {
                    include: {
                        entries: {
                            where: { accountId: { notIn: cashAccountIds } },
                            include: { account: true }
                        }
                    }
                }
            }
        });

        const report = {
            operating: { total: 0, items: [] as any[] },
            investing: { total: 0, items: [] as any[] },
            financing: { total: 0, items: [] as any[] },
            netChange: 0,
            openingBalance: 0,
            closingBalance: 0
        };

        // Get Opening Balance
        const openingEntries = await prisma.journalEntry.aggregate({
            where: {
                accountId: { in: cashAccountIds },
                createdAt: { lt: range.start }
            },
            _sum: { debit: true, credit: true }
        });
        report.openingBalance = Number(openingEntries?._sum?.debit || 0) - Number(openingEntries?._sum?.credit || 0);

        for (const entry of entries) {
            const amount = Number(entry.debit) - Number(entry.credit);

            // Analyze the other side of the transaction to categorize
            const otherSide = (entry as any).transaction.entries[0];
            if (!otherSide) continue;

            const category = this.categorizeCashFlow(otherSide.account.type, otherSide.account.code);

            const group = (report as any)[category];
            const existing = group.items.find((i: any) => i.name === otherSide.account.name);
            if (existing) {
                existing.amount += amount;
            } else {
                group.items.push({ name: otherSide.account.name, amount });
            }
            group.total += amount;
        }

        report.netChange = report.operating.total + report.investing.total + report.financing.total;
        report.closingBalance = report.openingBalance + report.netChange;

        return report;
    }

    private static categorizeCashFlow(type: AccountType, code: string): 'operating' | 'investing' | 'financing' {
        if (type === 'REVENUE' || type === 'EXPENSE') return 'operating';
        if (code.startsWith('1-2')) return 'investing'; // Fixed Assets
        if (type === 'EQUITY' || code.startsWith('2-2')) return 'financing'; // Equity or Long-term Loans
        return 'operating'; // Default to operating for things like AR/AP shifts
    }

    /**
     * Generate Statement of Changes in Equity
     */
    static async getEquityStatement(brandId: string, range: DateRange) {
        // 1. Initial Balance (Sum all entries for Equity accounts before range)
        const accounts = await prisma.ledgerAccount.findMany({
            where: { brandId, type: 'EQUITY' }
        });
        const accountIds = accounts.map(a => a.id);

        const initialRes = await prisma.journalEntry.aggregate({
            where: { accountId: { in: accountIds }, createdAt: { lt: range.start } },
            _sum: { debit: true, credit: true }
        });
        const initialBalance = Number(initialRes?._sum?.credit || 0) - Number(initialRes?._sum?.debit || 0);

        // 2. Net Income for period
        const pl = await this.getProfitLoss(brandId, range);
        const netIncome = pl.netProfit;

        // 3. Transactions in period (Draws/Injections)
        const entries = await prisma.journalEntry.findMany({
            where: {
                accountId: { in: accountIds },
                createdAt: { gte: range.start, lte: range.end }
            },
            include: { account: true }
        });

        const injections = entries.filter(e => Number(e.credit) > 0).reduce((sum, e) => sum + Number(e.credit), 0);
        const withdrawals = entries.filter(e => Number(e.debit) > 0).reduce((sum, e) => sum + Number(e.debit), 0);

        return {
            period: range,
            initialBalance,
            netIncome,
            injections,
            withdrawals,
            closingBalance: initialBalance + netIncome + injections - withdrawals
        };
    }

    /**
     * Generate Tax Report
     */
    static async getTaxReport(brandId: string, range: DateRange) {
        const pl = await this.getProfitLoss(brandId, range);
        const taxableRevenue = pl.revenue.total;

        const brand = await prisma.brand.findUnique({
            where: { id: brandId },
            select: { paymentSettings: true }
        });
        const settings = (brand?.paymentSettings as any) || { taxRates: { PPN: 11, PPH: 0.5 } };
        const rates = settings.taxRates || { PPN: 11, PPH: 0.5 };

        const liabilities = [];
        let totalTaxDue = 0;

        if (rates.PPN > 0) {
            const amount = taxableRevenue * (rates.PPN / 100);
            liabilities.push({
                type: 'PPN / PB1',
                rate: rates.PPN,
                base: taxableRevenue,
                amount: amount,
                description: 'Pajak Penjualan/Restoran'
            });
            totalTaxDue += amount;
        }

        if (rates.PPH > 0) {
            const amount = taxableRevenue * (rates.PPH / 100);
            liabilities.push({
                type: 'PPh Final (UMKM)',
                rate: rates.PPH,
                base: taxableRevenue,
                amount: amount,
                description: 'Pajak Penghasilan (0.5% Bruto)'
            });
            totalTaxDue += amount;
        }

        return {
            period: range,
            grossRevenue: taxableRevenue,
            liabilities,
            totalTaxDue
        };
    }

    /**
     * Generate Notes to Financial Statements (CaLK)
     */
    static async getNotes(brandId: string, range: DateRange) {
        const pl = await this.getProfitLoss(brandId, range);
        const bs = await this.getBalanceSheet(brandId, range.end);

        // Dynamic analysis
        const notes = [
            {
                title: "Dasar Penyusunan",
                content: "Laporan keuangan disusun menggunakan basis akrual dan metode harga perolehan. Kebijakan akuntansi konsisten dengan standar pelaporan keuangan entitas mikro (EMKM)."
            },
            {
                title: "Pendapatan Usaha",
                content: `Total omset sebesar ${pl.revenue.total.toLocaleString('id-ID')} terkumpul dari ${pl.revenue.items.length} channel penjualan. Rata-rata margin bersih tercatat sebesar ${pl.margin.toFixed(2)}%.`
            },
            {
                title: "Biaya Operasional",
                content: `Beban operasional utama terdiri dari ${pl.expenses.items.slice(0, 3).map(i => i.name).join(', ')}. Kontribusi beban terhadap omset adalah ${((pl.expenses.total / pl.revenue.total) * 100).toFixed(2)}%.`
            },
            {
                title: "Posisi Kas",
                content: `Total aset lancar dalam bentuk Kas & Bank per tanggal ${range.end.toLocaleDateString()} adalah ${bs.assets.total.toLocaleString('id-ID')}.`
            },
            {
                title: "Kewajiban & Pajak",
                content: `Estimasi kewajiban pajak PPh Final (0.5%) untuk periode ini adalah ${pl.taxAmount.toLocaleString('id-ID')}. Total liabilitas tercatat ${bs.liabilities.total.toLocaleString('id-ID')}.`
            }
        ];

        return {
            period: range,
            notes
        };
    }


}

import { prisma } from '@/lib/prisma';

export interface IncentiveRule {
    type: 'PERCENT' | 'FIXED';
    value: number;
    category?: string; // e.g., 'Merch', 'Food'
}

export class IncentiveEngine {
    /**
     * Calculates and records commission for a specific order
     */
    static async processOrderIncentive(orderId: string, operatorId: string) {
        try {
            const order = await prisma.order.findUnique({
                where: { id: orderId },
                include: { brand: true, orderItems: true }
            });

            if (!order || !operatorId) return;

            // Logic: 
            // - If Merch (Achiera Merch): 5% of total
            // - If Food (Rasa Ibu): Rp 2,000 fixed per item
            let commissionAmount = 0;

            if (order.brand?.slug === 'achiera-merch') {
                commissionAmount = Number(order.total) * 0.05;
            } else if (order.brand?.slug === 'rasa-ibu') {
                commissionAmount = order.orderItems.length * 2000;
            } else {
                // Default: 2% of total
                commissionAmount = Number(order.total) * 0.02;
            }

            if (commissionAmount <= 0) return;

            // Record in AuditLog for tracking
            await (prisma as any).auditLog.create({
                data: {
                    userId: operatorId,
                    userName: 'System (Incentive Engine)',
                    userRole: 'BRAND_ADMIN',
                    action: 'COMMISSION_EARNED' as any,
                    entityType: 'Order',
                    entityId: orderId,
                    brandId: order.brandId,
                    metadata: {
                        amount: commissionAmount,
                        reason: `Commission for Order ${order.invoiceNo}`,
                        brandSlug: order.brand?.slug
                    },
                    severity: 'INFO'
                }
            });

            return commissionAmount;
        } catch (error) {
            console.error('Incentive Engine Error:', error);
            return 0;
        }
    }
}

import { prisma } from '@/lib/prisma';
import { subDays, startOfDay, endOfDay, differenceInDays } from 'date-fns';

export interface RFMResult {
    customerId: string;
    customerPhone: string;
    customerName: string;
    recency: number; // Days since last purchase
    frequency: number; // Total number of orders
    monetary: number; // Total spend
    segment: 'CHAMPION' | 'LOYAL' | 'AT_RISK' | 'NEW' | 'UNKNOWN';
}

export interface SalesForecast {
    date: string;
    actual?: number;
    forecast: number;
}

export class IntelligenceService {
    /**
     * Performs RFM (Recency, Frequency, Monetary) Analysis on customers
     * Classification logic:
     * - CHAMPION: High spend (> 5jt) AND high frequency (> 5) AND recent (< 30 days)
     * - LOYAL: High frequency (> 3) OR consistent spend
     * - AT_RISK: No purchase in > 60 days but was previously active
     * - NEW: First purchase in last 14 days
     */
    static async performRFMAnalysis(brandId?: string): Promise<RFMResult[]> {
        const orders = await prisma.order.findMany({
            where: brandId ? { brandId } : {},
            orderBy: { createdAt: 'desc' },
            select: {
                id: true,
                customerPhone: true,
                customerName: true,
                totalAmount: true,
                createdAt: true,
            }
        });

        const customerMap = new Map<string, {
            phone: string,
            name: string,
            lastDate: Date,
            count: number,
            total: number
        }>();

        const now = new Date();

        orders.forEach(order => {
            const phone = order.customerPhone || 'unknown';
            const existing = customerMap.get(phone);
            if (existing) {
                existing.count += 1;
                existing.total += Number(order.totalAmount);
                if (order.createdAt > existing.lastDate) {
                    existing.lastDate = order.createdAt;
                }
            } else {
                customerMap.set(phone, {
                    phone,
                    name: order.customerName || 'Customer',
                    lastDate: order.createdAt,
                    count: 1,
                    total: Number(order.totalAmount)
                });
            }
        });

        const results: RFMResult[] = Array.from(customerMap.values()).map(c => {
            const recency = differenceInDays(now, c.lastDate);
            let segment: RFMResult['segment'] = 'UNKNOWN';

            if (recency <= 14 && c.count === 1) segment = 'NEW';
            else if (c.total >= 5000000 && c.count >= 5 && recency <= 30) segment = 'CHAMPION';
            else if (c.count >= 3 && recency <= 45) segment = 'LOYAL';
            else if (recency > 60) segment = 'AT_RISK';
            else segment = 'LOYAL';

            return {
                customerId: c.phone,
                customerPhone: c.phone,
                customerName: c.name,
                recency,
                frequency: c.count,
                monetary: c.total,
                segment
            };
        });

        return results;
    }

    /**
     * Generates a 7-day sales forecast using simple linear trend analysis
     */
    static async getSalesForecast(brandId?: string): Promise<SalesForecast[]> {
        const daysToLookBack = 30;
        const startDate = startOfDay(subDays(new Date(), daysToLookBack));

        const historicalOrders = await prisma.order.findMany({
            where: {
                ...(brandId ? { brandId } : {}),
                createdAt: { gte: startDate }
            },
            select: {
                totalAmount: true,
                createdAt: true
            }
        });

        const dailyRevenue = new Map<string, number>();
        for (let i = 0; i < daysToLookBack; i++) {
            const dateStr = subDays(new Date(), i).toISOString().split('T')[0];
            dailyRevenue.set(dateStr, 0);
        }

        historicalOrders.forEach(o => {
            const dateStr = o.createdAt.toISOString().split('T')[0];
            if (dailyRevenue.has(dateStr)) {
                dailyRevenue.set(dateStr, (dailyRevenue.get(dateStr) || 0) + Number(o.totalAmount));
            }
        });

        // Simple Linear Regression calculation
        const dataArr = Array.from(dailyRevenue.entries())
            .map(([date, amount], index) => ({ x: index, y: amount }))
            .reverse();

        const n = dataArr.length;
        if (n < 2) return [];

        let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
        dataArr.forEach(d => {
            sumX += d.x;
            sumY += d.y;
            sumXY += d.x * d.y;
            sumX2 += d.x * d.x;
        });

        const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
        const intercept = (sumY - slope * sumX) / n;

        const results: SalesForecast[] = [];

        // Past 7 days (actual)
        for (let i = 6; i >= 0; i--) {
            const date = subDays(new Date(), i);
            const dateStr = date.toISOString().split('T')[0];
            results.push({
                date: dateStr,
                actual: dailyRevenue.get(dateStr) || 0,
                forecast: Math.max(0, slope * (n - 1 - i) + intercept)
            });
        }

        // Future 7 days (forecast)
        for (let i = 1; i <= 7; i++) {
            const date = new Date();
            date.setDate(date.getDate() + i);
            results.push({
                date: date.toISOString().split('T')[0],
                forecast: Math.max(0, slope * (n - 1 + i) + intercept)
            });
        }

        return results;
    }

    /**
     * Calculates Stock velocity (average units sold per day)
     */
    static async getStockVelocity(brandId?: string) {
        const thirtyDaysAgo = subDays(new Date(), 30);

        const items = await prisma.orderItem.findMany({
            where: {
                order: {
                    ...(brandId ? { brandId } : {}),
                    createdAt: { gte: thirtyDaysAgo }
                }
            },
            select: {
                variantId: true,
                quantity: true
            }
        });

        const velocityMap = new Map<string, number>();
        items.forEach(item => {
            if (!item.variantId) return;
            velocityMap.set(item.variantId, (velocityMap.get(item.variantId) || 0) + item.quantity);
        });

        const results: Record<string, number> = {};
        velocityMap.forEach((totalQty, variantId) => {
            results[variantId] = totalQty / 30; // Avg units per day
        });

        return results;
    }
}

import { prisma } from '@/lib/prisma';
import { Decimal } from '@prisma/client/runtime/library';

export class InventoryEngine {
    /**
     * Get imbalance insights across all warehouses for a brand
     */
    static async getImbalanceInsights(brandId: string) {
        // 1. Fetch all warehouses and their inventory
        const warehouses = await prisma.warehouse.findMany({
            where: { brandId },
            include: {
                batches: {
                    where: { quantity: { gt: 0 }, isExpired: false },
                    include: {
                        variant: {
                            include: { product: true }
                        }
                    }
                }
            }
        });

        if (warehouses.length < 2) {
            return {
                status: 'INSUFFICIENT_DATA',
                message: 'At least two warehouses are required for balancing analysis.',
                recommendations: []
            };
        }

        // 2. Aggregate stock by variant per warehouse
        const variantStockMap = new Map<string, {
            name: string,
            sku: string,
            distribution: Record<string, number>,
            total: number,
            avgPerWarehouse: number
        }>();

        for (const wh of warehouses) {
            for (const batch of wh.batches) {
                const variantId = batch.variantId;
                const existing = variantStockMap.get(variantId) || {
                    name: `${batch.variant.product.name} - ${batch.variant.name}`,
                    sku: batch.variant.sku,
                    distribution: {},
                    total: 0,
                    avgPerWarehouse: 0
                };

                existing.distribution[wh.id] = (existing.distribution[wh.id] || 0) + batch.quantity;
                existing.total += batch.quantity;
                variantStockMap.set(variantId, existing);
            }
        }

        const recommendations = [];

        // 3. Analyze disparity
        for (const [variantId, data] of variantStockMap.entries()) {
            data.avgPerWarehouse = data.total / warehouses.length;

            const sortedWh = warehouses
                .map(wh => ({
                    id: wh.id,
                    name: wh.name,
                    stock: data.distribution[wh.id] || 0
                }))
                .sort((a, b) => b.stock - a.stock);

            const source = sortedWh[0];
            const target = sortedWh[sortedWh.length - 1];

            // If the difference between max and min is more than 30% of total, suggest rebalance
            if (source.stock - target.stock > data.total * 0.3 && source.stock > data.avgPerWarehouse) {
                const suggestedQty = Math.floor((source.stock - target.stock) / 2);
                if (suggestedQty > 5) { // Only suggest if significant
                    recommendations.push({
                        variantId,
                        variantName: data.name,
                        sku: data.sku,
                        fromWarehouseId: source.id,
                        fromWarehouseName: source.name,
                        toWarehouseId: target.id,
                        toWarehouseName: target.name,
                        suggestedQuantity: suggestedQty,
                        reason: `High disparity: ${source.name} has ${source.stock} while ${target.name} has ${target.stock}.`
                    });
                }
            }
        }

        return {
            status: recommendations.length > 0 ? 'ACTION_REQUIRED' : 'BALANCED',
            recommendations
        };
    }

    /**
     * Identify stock at risk of waste (low velocity + near expiry)
     */
    static async getWasteRiskAlerts(brandId: string) {
        const nearExpiryBatches = await prisma.inventoryBatch.findMany({
            where: {
                warehouse: { brandId },
                quantity: { gt: 0 },
                isExpired: false,
                expiryDate: {
                    lte: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) // Next 30 days
                }
            },
            include: {
                variant: {
                    include: { product: true }
                },
                warehouse: true
            },
            orderBy: { expiryDate: 'asc' }
        });

        // Simplified logic: If a batch is expiring in < 30 days and its warehouse is NOT the default one,
        // suggest moving to the default warehouse (which usually has higher turnover)
        const defaultWh = await prisma.warehouse.findFirst({
            where: { brandId, isDefault: true }
        });

        const alerts = nearExpiryBatches
            .filter(b => defaultWh && b.warehouseId !== defaultWh.id)
            .map(b => ({
                id: b.id,
                variantId: b.variantId,
                variantName: `${b.variant.product.name} - ${b.variant.name}`,
                batchCode: b.batchCode,
                quantity: b.quantity,
                expiryDate: b.expiryDate,
                currentWarehouse: b.warehouse.name,
                currentWarehouseId: b.warehouseId,
                suggestedWarehouse: defaultWh?.name,
                suggestedWarehouseId: defaultWh?.id,
                reason: 'Moving expiring stock to high-turnover default warehouse to minimize waste.'
            }));

        return alerts;
    }
}

import { prisma } from '@/lib/prisma';
import { AccountType } from '@prisma/client';
import { getAccountByCode } from './chartOfAccounts';

export type JournalEntryInput = {
    accountCode: string;
    description?: string;
    debit: number;
    credit: number;
};

/**
 * Journal Service for handling double-entry bookkeeping
 */
export class JournalService {

    /**
     * Create a general journal transaction with multiple entries
     * Validates that Debit = Credit
     */
    static async createTransaction(
        brandId: string,
        date: Date,
        description: string,
        entries: JournalEntryInput[],
        referenceType?: string,
        referenceId?: string,
        userId: string = 'SYSTEM'
    ) {
        // 1. Validate Balance
        const totalDebit = entries.reduce((sum, e) => sum + e.debit, 0);
        const totalCredit = entries.reduce((sum, e) => sum + e.credit, 0);

        if (Math.abs(totalDebit - totalCredit) > 0.01) { // Allow small floating point diff
            throw new Error(`Transaction processing failed: Credits (${totalCredit}) do not equal Debits (${totalDebit})`);
        }

        return prisma.$transaction(async (tx) => {
            // 2. Create Transaction Header
            const transaction = await tx.journalTransaction.create({
                data: {
                    brandId,
                    date,
                    description,
                    referenceType,
                    referenceId,
                    createdBy: userId
                }
            });

            // 3. Process Entries and Update Account Balances
            for (const entry of entries) {
                const account = await tx.ledgerAccount.findUnique({
                    where: {
                        brandId_code: {
                            brandId,
                            code: entry.accountCode
                        }
                    }
                });

                if (!account) {
                    throw new Error(`Account code ${entry.accountCode} not found for brand ${brandId}`);
                }

                // Create Entry
                await tx.journalEntry.create({
                    data: {
                        transactionId: transaction.id,
                        accountId: account.id,
                        debit: entry.debit,
                        credit: entry.credit,
                        description: entry.description || description
                    }
                });

                // Update Account Balance
                // Asset/Expense: Debit increases, Credit decreases
                // Liability/Equity/Revenue: Credit increases, Debit decreases
                let balanceChange = 0;

                if (['ASSET', 'EXPENSE'].includes(account.type)) {
                    balanceChange = entry.debit - entry.credit;
                } else {
                    balanceChange = entry.credit - entry.debit;
                }

                await tx.ledgerAccount.update({
                    where: { id: account.id },
                    data: {
                        balance: {
                            increment: balanceChange
                        }
                    }
                });
            }

            return transaction;
        });
    }

    /**
     * Record a Sale (Revenue)
     * Dr. Cash/Receivable
     * Cr. Sales Revenue
     */
    static async recordSale(
        brandId: string,
        orderId: string,
        amount: number, // Net amount received
        channel: string = 'WEBSITE',
        hppAmount: number = 0,
        discountAmount: number = 0
    ) {
        // Resolve Debit Account based on channel
        let debitAccount = '1-1000'; // Default Cash

        if (['SHOPEE', 'TOKOPEDIA', 'GRABFOOD', 'GO_FOOD', 'TIKTOK_SHOP'].includes(channel)) {
            debitAccount = '1-1200'; // Piutang Usaha (Receivable)
        } else if (channel === 'WEBSITE') {
            debitAccount = '1-1100'; // Bank BCA (Default for Website Online)
        } else if (['WHATSAPP', 'OFFLINE', 'CASH'].includes(channel)) {
            debitAccount = '1-1000'; // Kas
        }

        const entries: JournalEntryInput[] = [
            { accountCode: debitAccount, debit: amount, credit: 0 },
            { accountCode: '4-1000', debit: 0, credit: amount + discountAmount } // Gross revenue
        ];

        // Add Discount entry if applicable
        if (discountAmount > 0) {
            entries.push({ accountCode: '4-3000', debit: discountAmount, credit: 0 }); // Sales Discount
        }

        // Add HPP entry if provided
        if (hppAmount > 0) {
            entries.push({ accountCode: '5-1000', debit: hppAmount, credit: 0 }); // HPP
            entries.push({ accountCode: '5-PANTRY', debit: 0, credit: hppAmount }); // Reduce Pantry Expense
        }

        return this.createTransaction(
            brandId,
            new Date(),
            `Penjualan Pesanan #${orderId.slice(-4)}`,
            entries,
            'ORDER',
            orderId
        );
    }

    /**
     * Record a Payment Received
     * Dr. Bank/Cash
     * Cr. Receivable
     */
    static async recordPayment(
        brandId: string,
        orderId: string,
        amount: number,
        paymentMethod: string = 'TRANSFER',
        destinationAccount: string = '1-1101', // Default Bank Mandiri
        deductions: { amount: number, accountCode: string, description?: string }[] = []
    ) {
        let debitAccount = destinationAccount;
        if (paymentMethod === 'CASH') {
            debitAccount = '1-1000';
        }

        const entries: JournalEntryInput[] = [
            { accountCode: debitAccount, debit: amount, credit: 0 }
        ];

        let totalDeduction = 0;
        for (const deduction of deductions) {
            if (deduction.amount > 0) {
                entries.push({
                    accountCode: deduction.accountCode,
                    debit: deduction.amount,
                    credit: 0,
                    description: deduction.description
                });
                totalDeduction += deduction.amount;
            }
        }

        // Credit Receivable with Total Amount (Net + Deductions)
        entries.push({
            accountCode: '1-1200',
            debit: 0,
            credit: amount + totalDeduction
        });

        return this.createTransaction(
            brandId,
            new Date(),
            `Penerimaan Pembayaran #${orderId.slice(-4)}`,
            entries,
            'PAYMENT',
            orderId
        );
    }

    /**
     * Record Manual Income (Non-Order)
     * Dr. Asset Account (Bank/Cash)
     * Cr. Revenue Account
     */
    static async recordIncome(
        brandId: string,
        amount: number,
        revenueAccountCode: string,
        description: string,
        assetAccountCode: string,
        date: Date = new Date()
    ) {
        return this.createTransaction(
            brandId,
            date,
            description,
            [
                { accountCode: assetAccountCode, debit: amount, credit: 0 },
                { accountCode: revenueAccountCode, debit: 0, credit: amount }
            ],
            'INCOME',
            undefined
        );
    }

    /**
     * Record an Operational Expense
     * Dr. Expense Account (5-xxxx)
     * Cr. Bank/Cash (1-xxxx)
     */
    static async recordExpense(
        brandId: string,
        amount: number,
        expenseAccountCode: string,
        description: string,
        date: Date = new Date(),
        sourceAccountId: string = '1-1000'
    ) {
        return this.createTransaction(
            brandId,
            date,
            description,
            [
                { accountCode: expenseAccountCode, debit: amount, credit: 0 },
                { accountCode: sourceAccountId, debit: 0, credit: amount }
            ],
            'EXPENSE',
            undefined
        );
    }

    /**
     * Get Ledger Entries for specific account or all
     */
    static async getLedgerEntries(brandId: string, accountCode?: string, limit: number = 100) {
        return prisma.journalEntry.findMany({
            where: {
                account: {
                    brandId,
                    ...(accountCode ? { code: accountCode } : {})
                }
            },
            include: {
                transaction: true,
                account: true
            },
            orderBy: {
                createdAt: 'desc'
            },
            take: limit
        });
    }
}

import { prisma } from '@/lib/prisma';

// Define types manually to avoid build errors if Prisma client is out of sync
export interface LoyaltyMember {
    id: string;
    brandId: string;
    customerPhone: string;
    customerName: string;
    customerEmail: string | null;
    totalPoints: number;
    availablePoints: number;
    lifetimePoints: number;
    tier: string;
    totalSpent: any;
    totalOrders: number;
    avgOrderValue: any;
    isActive: boolean;
    referralCode: string;
    birthday: Date | null;
    isMarketingAllowed: boolean;
}

interface LoyaltyConfig {
    pointsPerRupiah: number; // Default: 1 point per Rp 10,000
    tierThresholds: {
        SILVER: number;
        GOLD: number;
        PLATINUM: number;
    };
    pointExpiryDays: number; // Default: 365 days
    pointValueInRupiah: number; // Default: 100
}

const DEFAULT_CONFIG: LoyaltyConfig = {
    pointsPerRupiah: 0.0001, // 1 point per Rp 10,000
    tierThresholds: {
        SILVER: 1000000, // Rp 1 juta lifetime spend
        GOLD: 5000000,   // Rp 5 juta lifetime spend
        PLATINUM: 10000000 // Rp 10 juta lifetime spend
    },
    pointExpiryDays: 365,
    pointValueInRupiah: 100
};

export class LoyaltyEngine {
    private async getConfig(brandId: string): Promise<LoyaltyConfig> {
        const brand = await prisma.brand.findUnique({
            where: { id: brandId },
            select: { paymentSettings: true }
        });

        const settings = (brand?.paymentSettings as any)?.loyalty || {};
        return {
            pointsPerRupiah: settings.pointsPerRupiah || DEFAULT_CONFIG.pointsPerRupiah,
            tierThresholds: {
                SILVER: settings.tierThresholds?.SILVER || DEFAULT_CONFIG.tierThresholds.SILVER,
                GOLD: settings.tierThresholds?.GOLD || DEFAULT_CONFIG.tierThresholds.GOLD,
                PLATINUM: settings.tierThresholds?.PLATINUM || DEFAULT_CONFIG.tierThresholds.PLATINUM,
            },
            pointExpiryDays: settings.pointExpiryDays || DEFAULT_CONFIG.pointExpiryDays,
            pointValueInRupiah: settings.pointValueInRupiah || DEFAULT_CONFIG.pointValueInRupiah
        };
    }
    async getMemberByPhone(brandId: string, customerPhone: string): Promise<LoyaltyMember | null> {
        return await (prisma as any).loyaltyMember.findUnique({
            where: {
                brandId_customerPhone: {
                    brandId,
                    customerPhone
                }
            },
            include: {
                transactions: {
                    orderBy: { createdAt: 'desc' },
                    take: 10
                }
            }
        }) as any;
    }

    /**
     * Create or get loyalty member
     */
    async getOrCreateMember(
        brandId: string,
        customerPhone: string,
        customerName: string,
        customerEmail?: string,
        isMarketingAllowed?: boolean
    ): Promise<LoyaltyMember> {
        let member = await (prisma as any).loyaltyMember.findUnique({
            where: {
                brandId_customerPhone: {
                    brandId,
                    customerPhone
                }
            }
        });

        if (!member) {
            // Generate unique referral code
            const referralCode = `${customerName.substring(0, 3).toUpperCase()}${Math.random().toString(36).substring(2, 8).toUpperCase()}`;

            member = await (prisma as any).loyaltyMember.create({
                data: {
                    brandId,
                    customerPhone,
                    customerName,
                    customerEmail,
                    referralCode,
                    isMarketingAllowed: isMarketingAllowed !== undefined ? isMarketingAllowed : true
                } as any
            });
        } else if (isMarketingAllowed !== undefined && member.isMarketingAllowed !== isMarketingAllowed) {
            // Update if changed
            member = await (prisma as any).loyaltyMember.update({
                where: { id: member.id },
                data: { isMarketingAllowed }
            });
        }

        return member as LoyaltyMember;
    }

    /**
     * Award points for a purchase
     */
    async awardPoints(
        memberId: string,
        orderAmount: number,
        orderId: string,
        explicitConfig?: LoyaltyConfig
    ) {
        const member = await (prisma as any).loyaltyMember.findUnique({
            where: { id: memberId }
        });

        if (!member) throw new Error('Member not found');

        // Use explicit config or fetch dynamic config
        const config = explicitConfig || await this.getConfig(member.brandId);

        // Calculate points
        let points = Math.floor(orderAmount * config.pointsPerRupiah);

        // Tier multiplier
        const tierMultiplier = this.getTierMultiplier(member.tier);
        points = Math.floor(points * tierMultiplier);

        // Marketing opt-in multiplier (2x)
        let isMarketingBonus = false;
        if (member.isMarketingAllowed) {
            points *= 2;
            isMarketingBonus = true;
        }

        // Birthday bonus (2x points) - Exact day only
        let isBirthdayBonus = false;
        if (member.birthday) {
            const today = new Date();
            const birthday = new Date(member.birthday);
            if (today.getDate() === birthday.getDate() &&
                today.getMonth() === birthday.getMonth()) {
                points *= 2;
                isBirthdayBonus = true;
            }
        }

        // Update member stats
        const newTotalPoints = (member.totalPoints || 0) + points;
        const newAvailablePoints = (member.availablePoints || 0) + points;
        const newLifetimePoints = (member.lifetimePoints || 0) + points;
        const newTotalSpent = Number(member.totalSpent || 0) + orderAmount;
        const newTotalOrders = (member.totalOrders || 0) + 1;
        const newAvgOrderValue = newTotalSpent / newTotalOrders;

        // Check tier upgrade
        const newTier = this.calculateTier(newTotalSpent, config);

        await (prisma as any).loyaltyMember.update({
            where: { id: memberId },
            data: {
                totalPoints: newTotalPoints,
                availablePoints: newAvailablePoints,
                lifetimePoints: newLifetimePoints,
                totalSpent: newTotalSpent,
                totalOrders: newTotalOrders,
                avgOrderValue: newAvgOrderValue,
                tier: newTier,
                lastOrderDate: new Date(),
                daysSinceLastOrder: 0
            } as any
        });

        // Record transaction
        await (prisma as any).loyaltyTransaction.create({
            data: {
                memberId,
                type: 'EARN',
                points,
                orderId,
                description: `Earned ${points} points${isMarketingBonus ? ' (2x Subscriber Bonus)' : ''}${isBirthdayBonus ? ' (Birthday Bonus)' : ''} from order`,
                balanceBefore: member.availablePoints || 0,
                balanceAfter: newAvailablePoints,
                expiresAt: new Date(Date.now() + config.pointExpiryDays * 24 * 60 * 60 * 1000)
            } as any
        });

        return { points, newTier, tierUpgraded: newTier !== member.tier };
    }

    /**
     * Redeem points for reward
     */
    async redeemPoints(
        memberId: string,
        pointsCost: number,
        description: string
    ) {
        const member = await (prisma as any).loyaltyMember.findUnique({
            where: { id: memberId }
        });

        if (!member) throw new Error('Member not found');
        if ((member.availablePoints || 0) < pointsCost) {
            throw new Error('Insufficient points');
        }

        const newAvailablePoints = (member.availablePoints || 0) - pointsCost;

        await (prisma as any).loyaltyMember.update({
            where: { id: memberId },
            data: {
                availablePoints: newAvailablePoints,
                totalPoints: (member.totalPoints || 0) - pointsCost
            } as any
        });

        await (prisma as any).loyaltyTransaction.create({
            data: {
                memberId,
                type: 'REDEEM',
                points: -pointsCost,
                description,
                balanceBefore: member.availablePoints || 0,
                balanceAfter: newAvailablePoints
            } as any
        });

        return { success: true, newBalance: newAvailablePoints };
    }

    /**
     * Calculate tier based on lifetime spend
     */
    private calculateTier(totalSpent: number, config: LoyaltyConfig): string {
        if (totalSpent >= config.tierThresholds.PLATINUM) return 'PLATINUM';
        if (totalSpent >= config.tierThresholds.GOLD) return 'GOLD';
        if (totalSpent >= config.tierThresholds.SILVER) return 'SILVER';
        return 'BRONZE';
    }

    /**
     * Get tier multiplier
     */
    private getTierMultiplier(tier: string): number {
        switch (tier) {
            case 'PLATINUM': return 2.0;
            case 'GOLD': return 1.5;
            case 'SILVER': return 1.25;
            default: return 1.0;
        }
    }

    /**
     * Get global member info across all brands
     */
    async getGlobalMemberInfo(customerPhone: string) {
        const members = await (prisma as any).loyaltyMember.findMany({
            where: { customerPhone },
            include: { brand: true }
        });

        if (members.length === 0) return null;

        const totalPoints = members.reduce((sum: number, m: any) => sum + (m.availablePoints || 0), 0);
        const lifetimePoints = members.reduce((sum: number, m: any) => sum + (m.lifetimePoints || 0), 0);
        const totalSpent = members.reduce((sum: number, m: any) => sum + Number(m.totalSpent || 0), 0);

        // Find best tier across brands
        const tiers = ['BRONZE', 'SILVER', 'GOLD', 'PLATINUM'];
        let bestTier = 'BRONZE';
        members.forEach((m: any) => {
            if (tiers.indexOf(m.tier) > tiers.indexOf(bestTier)) {
                bestTier = m.tier;
            }
        });

        return {
            customerPhone,
            customerName: members[0].customerName, // Assume name consistency for simplicity
            globalAvailablePoints: totalPoints,
            globalLifetimePoints: lifetimePoints,
            globalTotalSpent: totalSpent,
            bestTier,
            brandBreakdown: members.map((m: any) => ({
                brandName: m.brand.name,
                brandId: m.brandId,
                points: m.availablePoints,
                tier: m.tier
            }))
        };
    }

    /**
     * Get total available points for a phone number across the holding
     */
    async getGlobalBalance(customerPhone: string): Promise<number> {
        const result = await (prisma as any).loyaltyMember.aggregate({
            where: { customerPhone },
            _sum: {
                availablePoints: true
            }
        });
        return result._sum.availablePoints || 0;
    }

    /**
     * Redeem points from the global pool. 
     * Strategy: Deduct from brands starting with the oldest account or largest balance.
     */
    async redeemGlobalPoints(
        customerPhone: string,
        targetBrandId: string,
        pointsCost: number,
        description: string
    ) {
        const members = await (prisma as any).loyaltyMember.findMany({
            where: { customerPhone },
            orderBy: { availablePoints: 'desc' } // Prioritize brands with higher balance
        });

        const globalBalance = members.reduce((sum: number, m: any) => sum + (m.availablePoints || 0), 0);
        if (globalBalance < pointsCost) throw new Error('Insufficient global points');

        let remainingToDeduct = pointsCost;

        for (const member of members) {
            if (remainingToDeduct <= 0) break;

            const canDeductFromThisMember = Math.min(member.availablePoints, remainingToDeduct);
            if (canDeductFromThisMember > 0) {
                await this.redeemPoints(member.id, canDeductFromThisMember, `${description} (Global Redemption for ${targetBrandId})`);
                remainingToDeduct -= canDeductFromThisMember;
            }
        }

        return { success: true, pointsRedeemed: pointsCost };
    }

    /**
     * Get member stats for a brand
     */
    async getMemberStats(brandId: string) {
        const [totalMembers, activeMembers, pointStats, tierResults] = await Promise.all([
            (prisma as any).loyaltyMember.count({ where: { brandId } }),
            (prisma as any).loyaltyMember.count({
                where: {
                    brandId,
                    isActive: true,
                    lastOrderDate: {
                        gte: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000)
                    }
                }
            }),
            (prisma as any).loyaltyMember.aggregate({
                where: { brandId },
                _sum: {
                    availablePoints: true,
                    lifetimePoints: true
                }
            }),
            (prisma as any).loyaltyMember.groupBy({
                by: ['tier'],
                where: { brandId },
                _count: {
                    id: true
                }
            })
        ]);

        const tierCounts: Record<string, number> = {};
        tierResults.forEach((res: any) => {
            tierCounts[res.tier] = res._count.id;
        });

        return {
            totalMembers,
            activeMembers,
            totalPointsAvailable: pointStats._sum.availablePoints || 0,
            totalPointsIssued: pointStats._sum.lifetimePoints || 0,
            tierCounts
        };
    }
}

