'use server';

import { prisma } from '@/lib/prisma';
import { OverheadEngine } from './overheadEngine';

export interface PriceAdjustment {
    variantId: string;
    variantName: string;
    currentPrice: number;
    recommendedPrice: number;
    multiplier: number;
    reason: string;
    type: 'SURGE' | 'SCARCITY' | 'DISCOUNT' | 'STABLE';
    velocity: number;
}

/**
 * Compares order data from the last 24 hours vs the 7 days prior to detect demand surges.
 */
export async function calculateDynamicPricing(brandId: string) {
    try {
        const now = new Date();
        const last24h = new Date(now.getTime() - 24 * 60 * 60 * 1000);
        const last7d = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

        // 1. Fetch Variants
        const variants = await prisma.frozenVariant.findMany({
            where: { product: { category: { brandId } } },
            include: { product: true }
        });

        // 2. Fetch Recent Orders (Mocking performance for velocity check)
        // In a real system, we'd aggregate orderItems. Here we analyze general brand velocity for now
        const recentOrders = await prisma.order.count({
            where: { brandId, createdAt: { gte: last24h } }
        });

        const weeklyAvgOrdersPerDay = (await prisma.order.count({
            where: { brandId, createdAt: { gte: last7d, lt: last24h } }
        })) / 6;

        const velocityIndex = weeklyAvgOrdersPerDay > 0 ? recentOrders / weeklyAvgOrdersPerDay : 1;

        // 3. Fetch Overhead Data (OAR)
        const overhead = await OverheadEngine.calculateOAR(brandId);
        const overheadBreakdown = await OverheadEngine.getOverheadBreakdown(brandId);

        // 4. Fetch Strategy Config
        const config = await prisma.brandConfig.findUnique({ where: { brandId } });
        const marketplaceFeeRate = Number(config?.marketplaceFeeRate || 0.15);
        const targetNetMarginRate = Number(config?.targetNetMarginRate || 0.30);

        const results: PriceAdjustment[] = variants.map(v => {
            let multiplier = 1;
            let reason = 'Market stable.';
            let type: 'SURGE' | 'SCARCITY' | 'DISCOUNT' | 'STABLE' = 'STABLE';

            const currentPrice = Number(v.price || 0);
            const costPrice = Number(v.costPrice || 0);

            // Scarcity Check (Stock < 10)
            if (v.stockOnHand <= 10 && v.stockOnHand > 0) {
                multiplier += 0.05;
                reason = 'Stok kritis (Scarcity).';
                type = 'SCARCITY';
            }

            // Demand Surge Check (Velocity > 150%)
            if (velocityIndex > 1.5) {
                multiplier += 0.10;
                reason = 'Permintaan tinggi (Surge).';
                type = 'SURGE';
            } else if (velocityIndex < 0.5 && v.stockOnHand > 50) {
                multiplier -= 0.05;
                reason = 'Promosi (Slow demand).';
                type = 'DISCOUNT';
            }

            let recommendedPrice = Math.ceil((currentPrice * multiplier) / 500) * 500;

            // Margin Guard: Fully Loaded Model
            // Fully Loaded Cost = Raw Cost + Overhead Per Unit
            const fullyLoadedCost = costPrice + overhead.perUnitDynamic;

            // Use Config Settings
            const minSafePrice = fullyLoadedCost / (1 - targetNetMarginRate - marketplaceFeeRate);

            if (recommendedPrice < minSafePrice) {
                recommendedPrice = Math.ceil(minSafePrice / 500) * 500;
                reason = `Margin Protection - Harga disesuaikan berdasarkan Overhead (Rp ${overhead.perUnitDynamic.toLocaleString()}/unit) & Target Profit.`;
            }

            return {
                variantId: v.id,
                variantName: v.product.name,
                currentPrice,
                recommendedPrice,
                multiplier,
                reason,
                type,
                velocity: velocityIndex
            };
        });

        return {
            success: true,
            data: {
                adjustments: results.filter(r => r.type !== 'STABLE' || r.recommendedPrice !== r.currentPrice),
                velocityIndex,
                overhead,
                overheadBreakdown,
                lastUpdate: now.toISOString()
            }
        };
    } catch (error: any) {
        return { success: false, error: error.message };
    }
}

/**
 * Applies a specific price adjustment to a variant.
 */
export async function applyPriceAdjustment(variantId: string, newPrice: number) {
    try {
        await prisma.frozenVariant.update({
            where: { id: variantId },
            data: { price: newPrice }
        });
        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message };
    }
}

import { prisma } from '@/lib/prisma';

export interface ProcurementSuggestion {
    ingredientId: string;
    ingredientName: string;
    sku: string;
    unit: string;
    stockOnHand: number;
    avgDailyUsage: number;
    predictedNeed7Days: number;
    suggestedPurchase: number;
    daysRemaining: number;
    isCritical: boolean;
}

export class ProcurementEngine {
    /**
     * Calculates ingredient consumption patterns and suggests procurement quantities.
     */
    static async generateProcurementSuggestions(brandId: string): Promise<ProcurementSuggestion[]> {
        const now = new Date();
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(now.getDate() - 30);

        // 1. Fetch all orders for the last 30 days with their items and variants
        const orders = await prisma.order.findMany({
            where: {
                brandId,
                createdAt: { gte: thirtyDaysAgo },
                status: { in: ['DIBAYAR', 'SELESAI', 'DISIAPKAN', 'DIKIRIM'] }
            },
            include: {
                orderItems: {
                    include: {
                        frozenVariant: {
                            include: {
                                recipes: {
                                    include: {
                                        items: {
                                            include: {
                                                ingredient: true
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        });

        // 2. Aggregate consumption per ingredient
        const consumptionMap: Record<string, {
            totalConsumed: number;
            name: string;
            sku: string;
            unit: string;
            stock: number;
        }> = {};

        orders.forEach((order: any) => {
            order.orderItems.forEach((item: any) => {
                const variant = item.frozenVariant;
                if (!variant || !variant.recipes) return;

                // Use the first recipe found for the variant (primary recipe)
                const recipe = variant.recipes[0];
                if (!recipe) return;

                recipe.items.forEach((recipeItem: any) => {
                    const ingId = recipeItem.ingredientId;
                    if (!consumptionMap[ingId]) {
                        consumptionMap[ingId] = {
                            totalConsumed: 0,
                            name: recipeItem.ingredient.name,
                            sku: recipeItem.ingredient.sku || '',
                            unit: recipeItem.ingredient.unit || 'unit',
                            stock: Number(recipeItem.ingredient.stockOnHand)
                        };
                    }

                    // Formula: Ingredient Consumption = (Order Quantity / Recipe Output) * Ingredient Quantity in Recipe
                    const factor = item.quantity / Number(recipe.outputQuantity);
                    const consumed = factor * Number(recipeItem.quantity);
                    consumptionMap[ingId].totalConsumed += consumed;
                });
            });
        });

        // 3. Compute suggestions
        const suggestions: ProcurementSuggestion[] = Object.entries(consumptionMap).map(([id, data]) => {
            const avgDailyUsage = data.totalConsumed / 30;
            const predictedNeed7Days = avgDailyUsage * 7;
            const suggestedPurchase = Math.max(0, predictedNeed7Days - data.stock);
            const daysRemaining = avgDailyUsage > 0 ? data.stock / avgDailyUsage : 999;

            return {
                ingredientId: id,
                ingredientName: data.name,
                sku: data.sku,
                unit: data.unit,
                stockOnHand: data.stock,
                avgDailyUsage: Number(avgDailyUsage.toFixed(3)),
                predictedNeed7Days: Number(predictedNeed7Days.toFixed(3)),
                suggestedPurchase: Number(Math.ceil(suggestedPurchase * 10) / 10), // Round up to 1 decimal
                daysRemaining: Math.round(daysRemaining),
                isCritical: daysRemaining < 2
            };
        });

        return suggestions.sort((a, b) => {
            if (a.isCritical && !b.isCritical) return -1;
            if (!a.isCritical && b.isCritical) return 1;
            return b.suggestedPurchase - a.suggestedPurchase;
        });
    }
}

import { prisma } from '@/lib/prisma';
import { Decimal } from '@prisma/client/runtime/library';

/**
 * Production Intelligence Engine
 * Handles recipes, production planning, and ingredient forecasting.
 */
export class ProductionEngine {

    /**
     * Calculate total ingredients needed for a production plan
     */
    static async calculateIngredientForecast(planId: string) {
        const plan = await prisma.productionPlan.findUnique({
            where: { id: planId },
            include: {
                items: {
                    include: {
                        recipe: {
                            include: {
                                items: {
                                    include: {
                                        ingredient: true
                                    }
                                }
                            }
                        }
                    }
                }
            }
        });

        if (!plan) throw new Error('Plan not found');

        const forecastMap = new Map<string, {
            name: string,
            sku: string,
            unit: string,
            totalQuantity: number,
            stockOnHand: number
        }>();

        for (const planItem of plan.items) {
            const multiplier = planItem.targetQuantity / planItem.recipe.outputQuantity;

            for (const ingredient of planItem.recipe.items) {
                const required = Number(ingredient.quantity) * multiplier;
                const existing = forecastMap.get(ingredient.ingredientId) || {
                    name: ingredient.ingredient.name,
                    sku: ingredient.ingredient.sku,
                    unit: 'gram', // Standardized for raw materials
                    totalQuantity: 0,
                    stockOnHand: ingredient.ingredient.stockOnHand
                };

                existing.totalQuantity += required;
                forecastMap.set(ingredient.ingredientId, existing);
            }
        }

        return Array.from(forecastMap.entries()).map(([id, data]) => ({
            id,
            ...data
        }));
    }

    /**
     * Generate a suggested production plan based on stock levels and sales rhythm
     */
    static async generateDailyPlan(brandId: string) {
        // Fetch all recipes for this brand
        const recipes = await prisma.recipe.findMany({
            where: { brandId },
            include: {
                frozenVariant: true
            }
        });

        // Current simplified logic: Suggest production if stock < daily average * 3 (Safety stock)
        // In a real scenario, this would integrate with rhythmEngine
        const suggestedItems = [];

        for (const recipe of recipes) {
            if (!recipe.frozenVariant) continue;

            const stock = recipe.frozenVariant.stockOnHand;
            // Mocking a "recommended" level for now
            const recommended = 50;

            if (stock < recommended) {
                suggestedItems.push({
                    recipeId: recipe.id,
                    recipeName: recipe.name,
                    suggestedQuantity: Math.max(0, recommended - stock)
                });
            }
        }

        return suggestedItems;
    }

    /**
     * Execute production completion: Increases finished goods, decreases ingredients
     */
    static async completeProduction(planItemId: string, actualQuantity: number, operatorId: string) {
        const item = await prisma.productionPlanItem.findUnique({
            where: { id: planItemId },
            include: {
                recipe: {
                    include: {
                        items: true
                    }
                },
                plan: true
            }
        });

        if (!item) throw new Error('Production item not found');

        return await prisma.$transaction(async (tx) => {
            // 1. Update finished product stock
            if (item.recipe.frozenVariantId) {
                await tx.frozenVariant.update({
                    where: { id: item.recipe.frozenVariantId },
                    data: {
                        stockOnHand: { increment: actualQuantity }
                    }
                });

                // Record Stock Mutation IN
                await tx.stockMutation.create({
                    data: {
                        variantId: item.recipe.frozenVariantId,
                        warehouseId: (await tx.warehouse.findFirst({ where: { brandId: item.plan.brandId, isDefault: true } }))?.id || '',
                        type: 'IN',
                        quantity: actualQuantity,
                        notes: `Production Completion: ${item.recipe.name}`,
                        createdBy: operatorId
                    }
                });

                // AUTO-HPP: Update costPrice of the finished good based on current ingredient costs
                const hppData = await this.calculateRecipeHPP(item.recipe.id);
                if (hppData.success) {
                    await tx.frozenVariant.update({
                        where: { id: item.recipe.frozenVariantId },
                        data: { costPrice: hppData.totalHPP }
                    });
                }
            }

            // 2. Clear ingredients stock
            const multiplier = actualQuantity / item.recipe.outputQuantity;
            for (const ingredient of item.recipe.items) {
                const deduction = Math.ceil(Number(ingredient.quantity) * multiplier);

                await tx.frozenVariant.update({
                    where: { id: ingredient.ingredientId },
                    data: {
                        stockOnHand: { decrement: deduction }
                    }
                });

                // Record Stock Mutation OUT
                await tx.stockMutation.create({
                    data: {
                        variantId: ingredient.ingredientId,
                        warehouseId: (await tx.warehouse.findFirst({ where: { brandId: item.plan.brandId, isDefault: true } }))?.id || '',
                        type: 'OUT',
                        quantity: deduction,
                        notes: `Production Raw Material: ${item.recipe.name}`,
                        createdBy: operatorId
                    }
                });
            }

            // 3. Mark item as completed
            return await tx.productionPlanItem.update({
                where: { id: planItemId },
                data: {
                    actualQuantity,
                    status: 'COMPLETED',
                    completedAt: new Date()
                }
            });
        });
    }

    /**
     * Calculate HPP (COGS) for a recipe based on current ingredient costs
     */
    static async calculateRecipeHPP(recipeId: string) {
        try {
            const recipe = await prisma.recipe.findUnique({
                where: { id: recipeId },
                include: {
                    items: {
                        include: {
                            ingredient: true
                        }
                    }
                }
            });

            if (!recipe) return { success: false, error: 'Recipe not found' };

            let totalCost = 0;
            const itemCosts = [];

            for (const item of recipe.items) {
                const cost = Number(item.ingredient.costPrice) * Number(item.quantity);
                totalCost += cost;
                itemCosts.push({
                    ingredientId: item.ingredientId,
                    name: item.ingredient.name,
                    quantity: Number(item.quantity),
                    unitCost: Number(item.ingredient.costPrice),
                    subtotal: cost
                });
            }

            const hppPerUnit = totalCost / recipe.outputQuantity;

            return {
                success: true,
                totalCost,
                totalHPP: hppPerUnit, // Cost per output quantity
                outputQuantity: recipe.outputQuantity,
                items: itemCosts
            };
        } catch (error: any) {
            return { success: false, error: error.message };
        }
    }
}

import { prisma } from '@/lib/prisma';
import { ReconciliationStatus } from '@prisma/client';
import { updateOrderStatus } from '@/lib/actions/rasa-ibu/orders';

export class ReconciliationService {

    /**
     * Create a new payment reconciliation request (e.g. customer uploads proof)
     */
    static async submitPaymentProof(
        orderId: string,
        brandId: string,
        amount: number,
        paymentMethod: string,
        proofUrl: string,
        bankAccount?: string,
        notes?: string
    ) {
        return prisma.paymentReconciliation.create({
            data: {
                brandId,
                orderId,
                amount,
                paymentMethod,
                paymentProof: proofUrl,
                bankAccount,
                notes,
                status: 'PENDING'
            }
        });
    }

    /**
     * Get pending reconciliations for dashboard
     */
    static async getPendingReconciliations(brandId: string) {
        return prisma.paymentReconciliation.findMany({
            where: {
                brandId,
                status: 'PENDING'
            },
            include: {
                order: {
                    select: {
                        id: true,
                        invoiceNo: true,
                        customerName: true,
                        totalAmount: true,
                        createdAt: true
                    }
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Verify a payment reconciliation
     * - Updates Reconciliation status to VERIFIED
     * - Updates Order status to DIBAYAR (which triggers Journal Entry)
     */
    static async verifyPayment(reconciliationId: string, verifiedBy: string) {
        return prisma.$transaction(async (tx) => {
            // 1. Get and specific reconciliation
            const recon = await tx.paymentReconciliation.findUnique({
                where: { id: reconciliationId }
            });

            if (!recon) throw new Error('Reconciliation not found');

            // 2. Update status
            const updatedRecon = await tx.paymentReconciliation.update({
                where: { id: reconciliationId },
                data: {
                    status: 'VERIFIED',
                    reconciledBy: verifiedBy,
                    reconciledAt: new Date()
                }
            });

            // 3. Update Order Status (This triggers Journal Entry via existing orders.ts logic)
            // We need to call the server action logic. calling imported function behaves as server-side call.
            await updateOrderStatus(recon.orderId, 'DIBAYAR');

            return updatedRecon;
        });
    }

    /**
     * Reject a payment reconciliation
     */
    static async rejectPayment(reconciliationId: string, reason: string, rejectedBy: string) {
        return prisma.paymentReconciliation.update({
            where: { id: reconciliationId },
            data: {
                status: 'REJECTED',
                notes: reason, // Append or overwrite notes? Overwrite for now or append logic needed
                reconciledBy: rejectedBy,
                reconciledAt: new Date()
            }
        });
    }
}

import { prisma } from '@/lib/prisma';
import { AnomalyType, AnomalySeverity, AnomalyStatus } from '@prisma/client';

/**
 * Proactively scans the database for suspicious operational patterns.
 * This should be triggered by specific events (e.g. order cancellation) 
 * or run as a scheduled job.
 */
export async function scanForAnomalies() {
    const findings: any[] = [];
    const now = new Date();
    const probePeriod = new Date(now.getTime() - 48 * 60 * 60 * 1000); // Scan last 48h

    // 1. High-Value Cancellations (Greater than Rp 1.000.000)
    const highValueCancellations = await prisma.order.findMany({
        where: {
            status: 'CANCELLED',
            totalAmount: { gte: 1000000 },
            updatedAt: { gte: probePeriod }
        },
        include: { brand: { select: { name: true } } }
    });

    for (const order of highValueCancellations) {
        findings.push({
            brandId: order.brandId,
            type: AnomalyType.HIGH_VALUE_CANCELLATION,
            severity: AnomalySeverity.CRITICAL,
            description: `High-value order ${order.invoiceNo} (Rp ${Number(order.totalAmount || 0).toLocaleString()}) was cancelled in brand ${order.brand?.name || 'Unknown'}.`,
            metadata: {
                orderId: order.id,
                invoiceNo: order.invoiceNo,
                amount: Number(order.totalAmount || 0),
                cancelledAt: order.updatedAt,
                brandName: order.brand?.name
            }
        });
    }

    // 2. Transfer Velocity (Detected as more than 3 transfers between same brands in 48h)
    const recentTransfers = await prisma.interBrandTransfer.findMany({
        where: {
            createdAt: { gte: probePeriod }
        },
        include: {
            sendingBrand: { select: { name: true } },
            receivingBrand: { select: { name: true } }
        }
    });

    const pairingCounts: Record<string, { count: number; sendName: string; recvName: string }> = {};
    recentTransfers.forEach(t => {
        const key = `${t.sendingBrandId}-${t.receivingBrandId}`;
        if (!pairingCounts[key]) {
            pairingCounts[key] = {
                count: 0,
                sendName: t.sendingBrand.name,
                recvName: t.receivingBrand.name
            };
        }
        pairingCounts[key].count++;
    });

    for (const [key, data] of Object.entries(pairingCounts)) {
        if (data.count >= 3) {
            const [sendId, recvId] = key.split('-');
            findings.push({
                type: AnomalyType.TRANSFER_VELOCITY,
                severity: AnomalySeverity.WARNING,
                description: `Suspicious transfer frequency (${data.count} transfers) between ${data.sendName} and ${data.recvName}.`,
                metadata: {
                    sendingBrandId: sendId,
                    receivingBrandId: recvId,
                    sendingBrandName: data.sendName,
                    receivingBrandName: data.recvName,
                    count: data.count,
                    period: '48h'
                }
            });
        }
    }

    // 3. Unauthorized Holding Access (Patterns of forbidden attempts in Audit Logs)
    const securityAlerts = await prisma.auditLog.findMany({
        where: {
            action: { in: ['UNAUTHORIZED_ACCESS', 'FORBIDDEN_ATTEMPT', 'HOLDING_ACCESS_DENIED'] },
            createdAt: { gte: probePeriod }
        },
        include: { user: { select: { name: true, email: true } } }
    });

    for (const log of securityAlerts) {
        findings.push({
            type: AnomalyType.UNAUTHORIZED_HOLDING_ACCESS,
            severity: AnomalySeverity.CRITICAL,
            description: `Unauthorized access attempt to sensitive data by user ${log.user.name}.`,
            metadata: {
                userId: log.userId,
                userName: log.user.name,
                userEmail: log.user.email,
                action: log.action,
                entityType: log.entityType,
                ipAddress: log.ipAddress
            }
        });
    }

    // 4. Low Stock Risk (Detection as variant stockOnHand < 50)
    const lowStockItems = await prisma.frozenVariant.findMany({
        where: { stockOnHand: { lt: 50 }, isActive: true },
        include: { brand: { select: { name: true } } }
    });

    for (const item of lowStockItems) {
        findings.push({
            brandId: item.brandId,
            type: 'LOW_STOCK' as any,
            severity: AnomalySeverity.WARNING,
            description: `Variant "${item.name}" (SKU: ${item.sku}) is running low on stock (${item.stockOnHand} left) in brand ${item.brand?.name || 'Unknown'}.`,
            metadata: {
                variantId: item.id,
                sku: item.sku,
                stockOnHand: item.stockOnHand,
                brandName: item.brand?.name
            }
        });
    }

    // 5. Expiring Inventory Risk (Detection as batches expiring within 30 days)
    const thirtyDaysFromNow = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
    const expiringBatches = await prisma.inventoryBatch.findMany({
        where: {
            expiryDate: { gte: now, lte: thirtyDaysFromNow },
            quantity: { gt: 0 }
        },
        include: {
            variant: { select: { name: true, sku: true, brand: { select: { name: true } } } }
        }
    });

    for (const batch of expiringBatches) {
        findings.push({
            brandId: batch.variant.brand.id,
            type: 'EXPIRING_INVENTORY' as any,
            severity: AnomalySeverity.CRITICAL,
            description: `Batch ${batch.batchCode} of "${batch.variant.name}" (${batch.quantity} units) is expiring on ${batch.expiryDate.toLocaleDateString()} in brand ${batch.variant.brand.name}.`,
            metadata: {
                batchId: batch.id,
                batchCode: batch.batchCode,
                variantId: batch.variantId,
                expiryDate: batch.expiryDate,
                quantity: batch.quantity,
                brandName: batch.variant.brand.name
            }
        });
    }

    // 6. Persistence with Deduplication
    let createdCount = 0;
    for (const finding of findings) {
        // Find if this specific anomaly was already reported recently to avoid spam
        const existing = await prisma.anomaly.findFirst({
            where: {
                type: finding.type,
                description: finding.description,
                status: AnomalyStatus.OPEN,
                createdAt: { gte: probePeriod }
            }
        });

        if (!existing) {
            await prisma.anomaly.create({
                data: {
                    ...finding,
                    status: AnomalyStatus.OPEN
                }
            });
            createdCount++;
        }
    }

    return createdCount;
}

import { prisma } from '@/lib/prisma';
import { addMonths, startOfMonth, endOfMonth, format } from 'date-fns';

export interface SimulationResult {
    date: string;
    baseline: number;
    simulated: number;
}

export interface ScenarioImpact {
    brandId: string;
    brandName: string;
    currentCash: number;
    projectedCash3Months: number;
    impactType: 'POSITIVE' | 'NEGATIVE' | 'NEUTRAL';
    riskLevel: 'LOW' | 'MEDIUM' | 'HIGH';
}

export class CFOSimulatorService {
    /**
     * Projects cash flow for a brand over 3 months
     */
    static async projectCashFlow(
        brandId: string,
        simulatedTransfer?: { amount: number; type: 'IN' | 'OUT' }
    ): Promise<SimulationResult[]> {
        // 1. Get average monthly revenue & expenses for the last 3 months
        const threeMonthsAgo = addMonths(new Date(), -3);

        const journalEntries = await (prisma as any).journalEntry.findMany({
            where: {
                account: { brandId },
                createdAt: { gte: threeMonthsAgo }
            },
            include: { account: true }
        });

        // Simplified calculation of monthly burn rate / growth
        const monthlyInflow = journalEntries
            .filter((e: any) => e.account.type === 'REVENUE')
            .reduce((sum: number, e: any) => sum + Number(e.credit || 0), 0) / 3;

        const monthlyOutflow = journalEntries
            .filter((e: any) => e.account.type === 'EXPENSE')
            .reduce((sum: number, e: any) => sum + Number(e.debit || 0), 0) / 3;

        const netMonthly = monthlyInflow - monthlyOutflow;

        // 2. Get current cash position
        const cashAccounts = await (prisma as any).ledgerAccount.findMany({
            where: { brandId, type: 'ASSET', name: { contains: 'Cash' } }
        });
        const currentCash = cashAccounts.reduce((sum: number, a: any) => sum + Number(a.balance || 0), 0);

        // 3. Generate projection for next 3 months
        const results: SimulationResult[] = [];
        let currentBaseline = currentCash;
        let currentSimulated = currentCash + (simulatedTransfer ? (simulatedTransfer.type === 'IN' ? simulatedTransfer.amount : -simulatedTransfer.amount) : 0);

        // Month 0 (Current)
        results.push({
            date: format(new Date(), 'MMM yyyy'),
            baseline: currentBaseline,
            simulated: currentSimulated
        });

        for (let i = 1; i <= 3; i++) {
            currentBaseline += netMonthly;
            currentSimulated += netMonthly;

            results.push({
                date: format(addMonths(new Date(), i), 'MMM yyyy'),
                baseline: currentBaseline,
                simulated: currentSimulated
            });
        }

        return results;
    }

    /**
     * Run a multi-brand simulation for a capital transfer
     */
    static async simulateTransfer(
        fromBrandId: string,
        toBrandId: string,
        amount: number
    ) {
        const [fromImpact, toImpact] = await Promise.all([
            this.projectCashFlow(fromBrandId, { amount, type: 'OUT' }),
            this.projectCashFlow(toBrandId, { amount, type: 'IN' })
        ]);

        return {
            fromBrand: fromImpact,
            toBrand: toImpact,
            summary: {
                isSafe: fromImpact[3].simulated > 0, // Is the source brand solvent after 3 months?
                recommended: fromImpact[3].simulated > (fromImpact[0].baseline * 0.2) // Recommended if still has 20% buffer
            }
        };
    }
}

import { prisma } from '@/lib/prisma';

export interface StaffMetric {
    staffId: string;
    staffName: string;
    ordersProcessed: number;
    totalValueProcessed: number;
    actionsCount: number; // Stock mutations etc.
    estimatedCommissions: number;
}

export class TalentService {
    /**
     * Aggregates productivity metrics for a brand's staff
     */
    static async getBrandStaffPerformance(brandId: string, days: number = 30): Promise<StaffMetric[]> {
        const since = new Date();
        since.setDate(since.getDate() - days);

        // 1. Get unique staff members active in this brand
        const brandRoles = await prisma.userBrandRole.findMany({
            where: { brandId },
            include: { user: { select: { id: true, name: true } } }
        });

        const performance: StaffMetric[] = [];

        for (const role of brandRoles) {
            const userId = role.user.id;

            // a. Orders processed (using operatorId)
            const orders = await prisma.order.findMany({
                where: {
                    brandId,
                    operatorId: userId,
                    createdAt: { gte: since }
                },
                select: { total: true }
            });

            // b. Actions (Stock mutations)
            const mutations = await prisma.stockMutation.count({
                where: {
                    createdBy: userId,
                    createdAt: { gte: since },
                    warehouse: { brandId }
                }
            });

            // c. Commissions from AuditLog
            const commissionLogs = await (prisma as any).auditLog.findMany({
                where: {
                    userId,
                    brandId,
                    action: 'COMMISSION_EARNED' as any,
                    timestamp: { gte: since }
                }
            });

            const totalCommission = commissionLogs.reduce((sum: number, log: any) => {
                const metadata = log.metadata as any;
                return sum + (metadata?.amount || 0);
            }, 0);

            performance.push({
                staffId: userId,
                staffName: role.user.name,
                ordersProcessed: orders.length,
                totalValueProcessed: orders.reduce((sum, o) => sum + Number(o.total || 0), 0),
                actionsCount: mutations,
                estimatedCommissions: totalCommission
            });
        }

        return performance.sort((a, b) => b.totalValueProcessed - a.totalValueProcessed);
    }

    /**
     * Get Holding-wide leaderboard
     */
    static async getGlobalLeaderboard() {
        // Aggregate across all brands
        const brands = await prisma.brand.findMany({ select: { id: true } });
        const allPerformance: StaffMetric[] = [];

        for (const brand of brands) {
            const brandPerf = await this.getBrandStaffPerformance(brand.id);
            allPerformance.push(...brandPerf);
        }

        // Consolidated duplicates (if staff works in multiple brands)
        const consolidated: Record<string, StaffMetric> = {};
        for (const p of allPerformance) {
            if (!consolidated[p.staffId]) {
                consolidated[p.staffId] = { ...p };
            } else {
                consolidated[p.staffId].ordersProcessed += p.ordersProcessed;
                consolidated[p.staffId].totalValueProcessed += p.totalValueProcessed;
                consolidated[p.staffId].actionsCount += p.actionsCount;
                consolidated[p.staffId].estimatedCommissions += p.estimatedCommissions;
            }
        }

        return Object.values(consolidated).sort((a, b) => b.totalValueProcessed - a.totalValueProcessed);
    }
}

import { AuditService } from '@/lib/services/AuditService';
import { AuditAction, AuditSeverity } from '@prisma/client';

const auditService = new AuditService();

export interface AuditContext {
    userId: string;
    userName: string;
    userRole: string;
    brandId?: string;
    ipAddress?: string;
    userAgent?: string;
}

export interface AuditMetadata {
    entityType: string;
    entityId: string;
    action: AuditAction;
    severity?: AuditSeverity;
    changes?: any;
    metadata?: any;
}

/**
 * Audit middleware wrapper for server actions
 * Automatically logs actions before and after execution
 */
export function withAudit<T extends (...args: any[]) => Promise<any>>(
    action: T,
    getAuditMetadata: (args: Parameters<T>, result?: any) => AuditMetadata
): T {
    return (async (...args: Parameters<T>) => {
        const context = extractAuditContext(args);
        let result: any;
        let error: any;

        try {
            // Execute the action
            result = await action(...args);

            // Log successful action
            const metadata = getAuditMetadata(args, result);
            await logAudit(context, metadata, result);

            return result;
        } catch (e) {
            error = e;

            // Log failed action
            const metadata = getAuditMetadata(args);
            await logAudit(context, {
                ...metadata,
                severity: 'CRITICAL',
                metadata: {
                    ...metadata.metadata,
                    error: error.message,
                    stack: error.stack
                }
            });

            throw error;
        }
    }) as T;
}

/**
 * Extract audit context from action arguments
 * Assumes first arg might contain userId, brandId, etc.
 */
function extractAuditContext(args: any[]): AuditContext {
    // Try to extract from first argument
    const firstArg = args[0];

    return {
        userId: firstArg?.userId || firstArg?.executedBy || 'system',
        userName: firstArg?.userName || 'System User',
        userRole: firstArg?.userRole || 'SYSTEM',
        brandId: firstArg?.brandId,
        ipAddress: firstArg?.ipAddress,
        userAgent: firstArg?.userAgent
    };
}

/**
 * Log audit entry (fire and forget)
 */
async function logAudit(
    context: AuditContext,
    metadata: AuditMetadata,
    result?: any
) {
    try {
        await auditService.log({
            userId: context.userId,
            userName: context.userName,
            userRole: context.userRole,
            action: metadata.action,
            entityType: metadata.entityType,
            entityId: metadata.entityId,
            brandId: context.brandId,
            ipAddress: context.ipAddress,
            userAgent: context.userAgent,
            severity: metadata.severity || 'INFO',
            changes: metadata.changes,
            metadata: {
                ...metadata.metadata,
                success: !result?.error,
                timestamp: new Date().toISOString()
            }
        });
    } catch (error) {
        // Log error but don't throw - audit logging should never break the action
        console.error('[Audit Middleware] Failed to log:', error);
    }
}

/**
 * Helper to create audit metadata for common actions
 */
export const AuditHelpers = {
    budgetCreated: (budgetId: string, changes: any): AuditMetadata => ({
        entityType: 'Budget',
        entityId: budgetId,
        action: 'BUDGET_CREATED',
        severity: 'INFO',
        changes
    }),

    budgetUpdated: (budgetId: string, changes: any): AuditMetadata => ({
        entityType: 'Budget',
        entityId: budgetId,
        action: 'BUDGET_UPDATED',
        severity: 'INFO',
        changes
    }),

    budgetApproved: (budgetId: string): AuditMetadata => ({
        entityType: 'Budget',
        entityId: budgetId,
        action: 'BUDGET_APPROVED',
        severity: 'WARNING',
        metadata: { requiresApproval: true }
    }),

    icTransactionCreated: (txId: string, amount: number, type: string): AuditMetadata => ({
        entityType: 'ICTransaction',
        entityId: txId,
        action: 'IC_TRANSACTION_CREATED',
        severity: 'INFO',
        metadata: { amount, type }
    }),

    icTransactionApproved: (txId: string, amount: number): AuditMetadata => ({
        entityType: 'ICTransaction',
        entityId: txId,
        action: 'IC_TRANSACTION_APPROVED',
        severity: 'WARNING',
        metadata: { amount, requiresApproval: true }
    }),

    journalPosted: (journalId: string, entries: number): AuditMetadata => ({
        entityType: 'Journal',
        entityId: journalId,
        action: 'JOURNAL_POSTED',
        severity: 'INFO',
        metadata: { entryCount: entries }
    }),

    invoicePaid: (invoiceId: string, amount: number): AuditMetadata => ({
        entityType: 'Invoice',
        entityId: invoiceId,
        action: 'INVOICE_PAID',
        severity: 'INFO',
        metadata: { amount }
    }),

    userLogin: (userId: string, success: boolean): AuditMetadata => ({
        entityType: 'User',
        entityId: userId,
        action: 'USER_LOGIN',
        severity: success ? 'INFO' : 'SECURITY',
        metadata: { success }
    }),

    dataExported: (entityType: string, recordCount: number): AuditMetadata => ({
        entityType,
        entityId: 'export',
        action: 'DATA_EXPORTED',
        severity: 'WARNING',
        metadata: { recordCount }
    })
};

/**
 * Simplified wrapper for actions that follow standard pattern
 */
export function auditAction<T extends (...args: any[]) => Promise<any>>(
    action: T,
    actionType: AuditAction,
    entityType: string,
    getEntityId: (args: Parameters<T>, result?: any) => string,
    severity: AuditSeverity = 'INFO'
): T {
    return withAudit(action, (args, result) => ({
        entityType,
        entityId: getEntityId(args, result),
        action: actionType,
        severity,
        metadata: { args: args[0] }
    }));
}

export interface LogoTransform {
    x: number;
    y: number;
    width: number;
    height: number;
    rotation: number;
}

export interface RenderParams {
    ctx: CanvasRenderingContext2D;
    canvasWidth: number;
    canvasHeight: number;
    productImg: HTMLImageElement;
    logoImg: HTMLImageElement | null;
    logoTransform?: LogoTransform;
    safeZone?: { x: number; y: number; width: number; height: number };
    showSafeZone?: boolean;
    backgroundColor?: string;

    // New Params for Tinting
    tintMaskImg?: HTMLImageElement | null;
    productColor?: string;
}

export function renderMockupCanvas({
    ctx,
    canvasWidth,
    canvasHeight,
    productImg,
    logoImg,
    logoTransform,
    safeZone,
    showSafeZone = false,
    backgroundColor = '',
    tintMaskImg = null,
    productColor = ''
}: RenderParams) {
    // 1. Clear & Background
    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    if (backgroundColor) {
        ctx.fillStyle = backgroundColor;
        ctx.fillRect(0, 0, canvasWidth, canvasHeight);
    }

    // 2. Draw Product Base
    // Fit Contain logic
    const scale = Math.min(canvasWidth / productImg.width, canvasHeight / productImg.height);
    const w = productImg.width * scale;
    const h = productImg.height * scale;
    const x = (canvasWidth - w) / 2;
    const y = (canvasHeight - h) / 2;

    ctx.drawImage(productImg, x, y, w, h);

    // 3. Apply Tint Mask (if available and color selected)
    if (tintMaskImg && productColor) {
        // Create offscreen canvas for tinting
        const offCanvas = document.createElement('canvas');
        offCanvas.width = canvasWidth;
        offCanvas.height = canvasHeight;
        const offCtx = offCanvas.getContext('2d');

        if (offCtx) {
            // Draw Mask
            offCtx.drawImage(tintMaskImg, x, y, w, h);

            // source-in to keep only the mask shape
            offCtx.globalCompositeOperation = 'source-in';
            offCtx.fillStyle = productColor;
            offCtx.fillRect(0, 0, canvasWidth, canvasHeight);

            // Draw tinted mask over product (Multiply for realistic shading)
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.drawImage(offCanvas, 0, 0);
            ctx.restore();

            // Optional: Draw again with 'soft-light' or 'overlay' if multiply is too dark?
            // Usually Multiply on a white base works best. 
            // If the base image is already shaded gray, multiply works perfectly.
        }
    }

    // 4. Draw Logo
    if (logoImg && logoTransform) {
        ctx.save();

        // Move to logo center
        ctx.translate(logoTransform.x, logoTransform.y);
        ctx.rotate((logoTransform.rotation * Math.PI) / 180);

        // Draw centered
        try {
            ctx.drawImage(
                logoImg,
                -logoTransform.width / 2,
                -logoTransform.height / 2,
                logoTransform.width,
                logoTransform.height
            );
        } catch (e) {
            // ignore if image not ready
        }

        ctx.restore();
    }

    // 5. Safe Zone Overlay
    if (showSafeZone && safeZone) {
        ctx.save();
        ctx.strokeStyle = '#d97706'; // amber-600
        ctx.lineWidth = 1;
        ctx.setLineDash([5, 5]);
        ctx.strokeRect(safeZone.x, safeZone.y, safeZone.width, safeZone.height);

        // Semi-transparent fill
        ctx.fillStyle = 'rgba(217, 119, 6, 0.1)';
        ctx.fillRect(safeZone.x, safeZone.y, safeZone.width, safeZone.height);
        ctx.restore();
    }
}

