export const correlationClient = new CorrelationClient();

// ACHIERA Platform - Error Boundaries
// React error boundaries with logging and recovery

'use client';

import React, { Component, ReactNode } from 'react';
import { logger } from './logger';

type ErrorBoundaryProps = {
    children: ReactNode;
    fallback?: ReactNode;
    onError?: (error: Error, errorInfo: React.ErrorInfo) => void;
    context?: {
        component?: string;
        userId?: string;
        brandId?: string;
    };
};

type ErrorBoundaryState = {
    hasError: boolean;
    error?: Error;
    errorInfo?: React.ErrorInfo;
};

/**
 * Error boundary component
 */
export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
    constructor(props: ErrorBoundaryProps) {
        super(props);
        this.state = { hasError: false };
    }

    static getDerivedStateFromError(error: Error): ErrorBoundaryState {
        return {
            hasError: true,
            error
        };
    }

    componentDidCatch(error: Error, errorInfo: React.ErrorInfo): void {
        // Log error
        const log = logger.child({
            component: this.props.context?.component || 'Unknown',
            userId: this.props.context?.userId,
            brandId: this.props.context?.brandId
        });

        log.error('React Error Boundary caught error', error, {
            componentStack: errorInfo.componentStack,
            errorBoundary: this.props.context?.component
        });

        // Call custom error handler
        this.props.onError?.(error, errorInfo);

        // Update state
        this.setState({
            error,
            errorInfo
        });
    }

    render(): ReactNode {
        if (this.state.hasError) {
            // Custom fallback UI
            if (this.props.fallback) {
                return this.props.fallback;
            }

            // Default error UI
            return (
                <div className="min-h-screen flex items-center justify-center bg-gray-50 px-4">
                    <div className="max-w-md w-full bg-white shadow-lg rounded-lg p-6">
                        <div className="flex items-center justify-center w-12 h-12 mx-auto bg-red-100 rounded-full">
                            <svg
                                className="w-6 h-6 text-red-600"
                                fill="none"
                                stroke="currentColor"
                                viewBox="0 0 24 24"
                            >
                                <path
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    strokeWidth={2}
                                    d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
                                />
                            </svg>
                        </div>

                        <h2 className="mt-4 text-center text-xl font-semibold text-gray-900">
                            Something went wrong
                        </h2>

                        <p className="mt-2 text-center text-sm text-gray-600">
                            We've been notified and are working on a fix.
                        </p>

                        {process.env.NODE_ENV === 'development' && this.state.error && (
                            <div className="mt-4 p-4 bg-gray-100 rounded text-xs overflow-auto">
                                <p className="font-semibold text-red-600">{this.state.error.message}</p>
                                <pre className="mt-2 text-gray-700 whitespace-pre-wrap">
                                    {this.state.error.stack}
                                </pre>
                            </div>
                        )}

                        <div className="mt-6 flex gap-3">
                            <button
                                onClick={() => window.location.reload()}
                                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
                            >
                                Reload Page
                            </button>
                            <button
                                onClick={() => window.history.back()}
                                className="flex-1 px-4 py-2 bg-gray-200 text-gray-700 rounded hover:bg-gray-300"
                            >
                                Go Back
                            </button>
                        </div>
                    </div>
                </div>
            );
        }

        return this.props.children;
    }
}

/**
 * HOC for wrapping components with error boundary
 */
export function withErrorBoundary<P extends object>(
    Component: React.ComponentType<P>,
    errorBoundaryProps?: Omit<ErrorBoundaryProps, 'children'>
) {
    return function WithErrorBoundary(props: P) {
        return (
            <ErrorBoundary {...errorBoundaryProps}>
                <Component {...props} />
            </ErrorBoundary>
        );
    };
}

/**
 * Error boundary for specific sections
 */
export function SectionErrorBoundary({
    children,
    section
}: {
    children: ReactNode;
    section: string;
}) {
    return (
        <ErrorBoundary
            context={{ component: section }}
            fallback={
                <div className="p-4 bg-red-50 border border-red-200 rounded">
                    <p className="text-sm text-red-800">
                        Failed to load {section}. Please try refreshing the page.
                    </p>
                </div>
            }
        >
            {children}
        </ErrorBoundary>
    );
}

/**
 * Global error handler for unhandled errors
 */
export function setupGlobalErrorHandlers(): void {
    // Unhandled promise rejections
    if (typeof window !== 'undefined') {
        window.addEventListener('unhandledrejection', (event) => {
            logger.error('Unhandled Promise Rejection', event.reason, {
                promise: event.promise
            });

            event.preventDefault();
        });

        // Global errors
        window.addEventListener('error', (event) => {
            logger.error('Global Error', event.error, {
                message: event.message,
                filename: event.filename,
                lineno: event.lineno,
                colno: event.colno
            });
        });
    }
}

// ACHIERA Platform - Structured Logger
// Production-ready logging with correlation IDs and context

import { prisma } from '@/lib/prisma';

export type LogLevel = 'debug' | 'info' | 'warn' | 'error' | 'critical';

export type LogContext = {
    correlationId?: string;
    userId?: string;
    brandId?: string;
    requestId?: string;
    sessionId?: string;
    [key: string]: any;
};

export type LogEntry = {
    timestamp: string;
    level: LogLevel;
    message: string;
    context: LogContext;
    error?: {
        name: string;
        message: string;
        stack?: string;
    };
    metadata?: Record<string, any>;
};

/**
 * Structured logger with correlation tracking
 */
export class Logger {
    private context: LogContext;
    private static instance: Logger;

    constructor(context: LogContext = {}) {
        this.context = context;
    }

    /**
     * Get singleton instance
     */
    static getInstance(): Logger {
        if (!Logger.instance) {
            Logger.instance = new Logger();
        }
        return Logger.instance;
    }

    /**
     * Create child logger with additional context
     */
    child(context: LogContext): Logger {
        return new Logger({
            ...this.context,
            ...context
        });
    }

    /**
     * Log debug message
     */
    debug(message: string, metadata?: Record<string, any>): void {
        this.log('debug', message, metadata);
    }

    /**
     * Log info message
     */
    info(message: string, metadata?: Record<string, any>): void {
        this.log('info', message, metadata);
    }

    /**
     * Log warning
     */
    warn(message: string, metadata?: Record<string, any>): void {
        this.log('warn', message, metadata);
    }

    /**
     * Log error
     */
    error(message: string, error?: Error, metadata?: Record<string, any>): void {
        this.log('error', message, metadata, error);
    }

    /**
     * Log critical error (triggers alerts)
     */
    critical(message: string, error?: Error, metadata?: Record<string, any>): void {
        this.log('critical', message, metadata, error);

        // Trigger critical alert
        this.triggerCriticalAlert(message, error, metadata);
    }

    /**
     * Core logging method
     */
    private log(
        level: LogLevel,
        message: string,
        metadata?: Record<string, any>,
        error?: Error
    ): void {
        const entry: LogEntry = {
            timestamp: new Date().toISOString(),
            level,
            message,
            context: this.context,
            metadata
        };

        if (error) {
            entry.error = {
                name: error.name,
                message: error.message,
                stack: error.stack
            };
        }

        // Console output (structured JSON in production)
        if (process.env.NODE_ENV === 'production') {
            console.log(JSON.stringify(entry));
        } else {
            // Pretty print in development
            const color = this.getColorForLevel(level);
            console.log(
                `${color}[${level.toUpperCase()}]${'\x1b[0m'} ${message}`,
                metadata || '',
                error || ''
            );
        }

        // Persist critical logs to database
        if (level === 'error' || level === 'critical') {
            this.persistLog(entry).catch(err => {
                console.error('Failed to persist log:', err);
            });
        }
    }

    /**
     * Persist log to database
     */
    private async persistLog(entry: LogEntry): Promise<void> {
        try {
            await prisma.systemLog.create({
                data: {
                    level: entry.level,
                    message: entry.message,
                    context: entry.context as any,
                    error: entry.error as any,
                    metadata: entry.metadata as any,
                    timestamp: new Date(entry.timestamp)
                }
            });
        } catch (error) {
            // Fallback to console if DB fails
            console.error('Failed to persist log to database:', error);
        }
    }

    /**
     * Trigger critical alert
     */
    private async triggerCriticalAlert(
        message: string,
        error?: Error,
        metadata?: Record<string, any>
    ): Promise<void> {
        try {
            // Create alert record
            await prisma.criticalAlert.create({
                data: {
                    message,
                    error: error ? {
                        name: error.name,
                        message: error.message,
                        stack: error.stack
                    } : undefined,
                    context: this.context as any,
                    metadata: metadata as any,
                    status: 'OPEN'
                }
            });

            // Send notifications (implement based on your needs)
            await this.sendAlertNotifications(message, error, metadata);

        } catch (err) {
            console.error('Failed to create critical alert:', err);
        }
    }

    /**
     * Send alert notifications (Slack, Email, PagerDuty, etc.)
     */
    private async sendAlertNotifications(
        message: string,
        error?: Error,
        metadata?: Record<string, any>
    ): Promise<void> {
        // Implement your notification channels here

        // Example: Slack webhook
        if (process.env.SLACK_WEBHOOK_URL) {
            try {
                await fetch(process.env.SLACK_WEBHOOK_URL, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        text: `🚨 CRITICAL ALERT: ${message}`,
                        blocks: [
                            {
                                type: 'section',
                                text: {
                                    type: 'mrkdwn',
                                    text: `*CRITICAL ALERT*\n${message}`
                                }
                            },
                            {
                                type: 'section',
                                fields: [
                                    {
                                        type: 'mrkdwn',
                                        text: `*Correlation ID:*\n${this.context.correlationId || 'N/A'}`
                                    },
                                    {
                                        type: 'mrkdwn',
                                        text: `*User ID:*\n${this.context.userId || 'N/A'}`
                                    }
                                ]
                            }
                        ]
                    })
                });
            } catch (err) {
                console.error('Failed to send Slack notification:', err);
            }
        }
    }

    /**
     * Get color for log level
     */
    private getColorForLevel(level: LogLevel): string {
        const colors = {
            debug: '\x1b[36m',    // Cyan
            info: '\x1b[32m',     // Green
            warn: '\x1b[33m',     // Yellow
            error: '\x1b[31m',    // Red
            critical: '\x1b[35m'  // Magenta
        };
        return colors[level];
    }
}

/**
 * Generate correlation ID
 */
export function generateCorrelationId(): string {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Extract correlation ID from headers
 */
export function extractCorrelationId(headers: Headers): string {
    return headers.get('x-correlation-id') || generateCorrelationId();
}

/**
 * Create logger with correlation ID
 */
export function createLogger(context?: LogContext): Logger {
    return new Logger({
        correlationId: generateCorrelationId(),
        ...context
    });
}

/**
 * Global logger instance
 */
export const logger = Logger.getInstance();

/**
 * Performance logger
 */
export class PerformanceLogger {
    private startTime: number;
    private logger: Logger;
    private operation: string;

    constructor(operation: string, context?: LogContext) {
        this.operation = operation;
        this.logger = createLogger(context);
        this.startTime = Date.now();

        this.logger.debug(`Starting: ${operation}`);
    }

    /**
     * End performance tracking
     */
    end(metadata?: Record<string, any>): void {
        const duration = Date.now() - this.startTime;

        this.logger.info(`Completed: ${this.operation}`, {
            duration,
            ...metadata
        });

        // Alert on slow operations
        if (duration > 5000) {
            this.logger.warn(`Slow operation: ${this.operation}`, {
                duration,
                threshold: 5000
            });
        }
    }

    /**
     * End with error
     */
    error(error: Error, metadata?: Record<string, any>): void {
        const duration = Date.now() - this.startTime;

        this.logger.error(`Failed: ${this.operation}`, error, {
            duration,
            ...metadata
        });
    }
}

/**
 * Performance tracking decorator
 */
export function trackPerformance(operation: string) {
    return function (
        target: any,
        propertyKey: string,
        descriptor: PropertyDescriptor
    ) {
        const originalMethod = descriptor.value;

        descriptor.value = async function (...args: any[]) {
            const perf = new PerformanceLogger(`${operation}.${propertyKey}`);

            try {
                const result = await originalMethod.apply(this, args);
                perf.end();
                return result;
            } catch (error) {
                perf.error(error as Error);
                throw error;
            }
        };

        return descriptor;
    };
}

// ACHIERA Platform - Monitoring & Metrics
// Application performance monitoring and health checks

import { logger } from './logger';

export type MetricType = 'counter' | 'gauge' | 'histogram' | 'summary';

export type Metric = {
    name: string;
    type: MetricType;
    value: number;
    labels?: Record<string, string>;
    timestamp: Date;
};

/**
 * Metrics collector
 */
export class MetricsCollector {
    private metrics: Map<string, Metric> = new Map();
    private static instance: MetricsCollector;

    static getInstance(): MetricsCollector {
        if (!MetricsCollector.instance) {
            MetricsCollector.instance = new MetricsCollector();
        }
        return MetricsCollector.instance;
    }

    /**
     * Increment counter
     */
    increment(name: string, labels?: Record<string, string>, value: number = 1): void {
        const key = this.getMetricKey(name, labels);
        const existing = this.metrics.get(key);

        this.metrics.set(key, {
            name,
            type: 'counter',
            value: (existing?.value || 0) + value,
            labels,
            timestamp: new Date()
        });
    }

    /**
     * Set gauge value
     */
    gauge(name: string, value: number, labels?: Record<string, string>): void {
        const key = this.getMetricKey(name, labels);

        this.metrics.set(key, {
            name,
            type: 'gauge',
            value,
            labels,
            timestamp: new Date()
        });
    }

    /**
     * Record histogram value
     */
    histogram(name: string, value: number, labels?: Record<string, string>): void {
        const key = this.getMetricKey(name, labels);

        this.metrics.set(key, {
            name,
            type: 'histogram',
            value,
            labels,
            timestamp: new Date()
        });
    }

    /**
     * Get all metrics
     */
    getMetrics(): Metric[] {
        return Array.from(this.metrics.values());
    }

    /**
     * Clear metrics
     */
    clear(): void {
        this.metrics.clear();
    }

    /**
     * Get metric key
     */
    private getMetricKey(name: string, labels?: Record<string, string>): string {
        if (!labels) return name;

        const labelStr = Object.entries(labels)
            .sort(([a], [b]) => a.localeCompare(b))
            .map(([k, v]) => `${k}="${v}"`)
            .join(',');

        return `${name}{${labelStr}}`;
    }
}

/**
 * Health check system
 */
export class HealthCheck {
    private checks: Map<string, () => Promise<boolean>> = new Map();

    /**
     * Register health check
     */
    register(name: string, check: () => Promise<boolean>): void {
        this.checks.set(name, check);
    }

    /**
     * Run all health checks
     */
    async runAll(): Promise<{
        healthy: boolean;
        checks: Record<string, { healthy: boolean; error?: string }>;
    }> {
        const results: Record<string, { healthy: boolean; error?: string }> = {};
        let allHealthy = true;

        for (const [name, check] of this.checks) {
            try {
                const healthy = await check();
                results[name] = { healthy };

                if (!healthy) {
                    allHealthy = false;
                }
            } catch (error) {
                results[name] = {
                    healthy: false,
                    error: (error as Error).message
                };
                allHealthy = false;
            }
        }

        return {
            healthy: allHealthy,
            checks: results
        };
    }
}

/**
 * Application monitoring
 */
export class ApplicationMonitor {
    private metrics = MetricsCollector.getInstance();
    private health = new HealthCheck();

    constructor() {
        this.setupDefaultHealthChecks();
        this.startMetricsCollection();
    }

    /**
     * Setup default health checks
     */
    private setupDefaultHealthChecks(): void {
        // Database health check
        this.health.register('database', async () => {
            try {
                const { prisma } = await import('@/lib/prisma');
                await prisma.$queryRaw`SELECT 1`;
                return true;
            } catch {
                return false;
            }
        });

        // Memory health check
        this.health.register('memory', async () => {
            if (typeof process === 'undefined') return true;

            const usage = process.memoryUsage();
            const heapUsedPercent = (usage.heapUsed / usage.heapTotal) * 100;

            return heapUsedPercent < 90; // Alert if > 90% heap used
        });
    }

    /**
     * Start metrics collection
     */
    private startMetricsCollection(): void {
        if (typeof process === 'undefined') return;

        // Collect system metrics every 30 seconds
        setInterval(() => {
            const usage = process.memoryUsage();

            this.metrics.gauge('nodejs_memory_heap_used_bytes', usage.heapUsed);
            this.metrics.gauge('nodejs_memory_heap_total_bytes', usage.heapTotal);
            this.metrics.gauge('nodejs_memory_external_bytes', usage.external);

            if (process.cpuUsage) {
                const cpu = process.cpuUsage();
                this.metrics.gauge('nodejs_cpu_user_microseconds', cpu.user);
                this.metrics.gauge('nodejs_cpu_system_microseconds', cpu.system);
            }
        }, 30000);
    }

    /**
     * Track HTTP request
     */
    trackRequest(
        method: string,
        path: string,
        statusCode: number,
        duration: number
    ): void {
        this.metrics.increment('http_requests_total', {
            method,
            path,
            status: statusCode.toString()
        });

        this.metrics.histogram('http_request_duration_ms', duration, {
            method,
            path
        });
    }

    /**
     * Track database query
     */
    trackQuery(operation: string, duration: number): void {
        this.metrics.increment('db_queries_total', { operation });
        this.metrics.histogram('db_query_duration_ms', duration, { operation });
    }

    /**
     * Track business metric
     */
    trackBusinessMetric(name: string, value: number, labels?: Record<string, string>): void {
        this.metrics.gauge(name, value, labels);
    }

    /**
     * Get health status
     */
    async getHealth(): Promise<any> {
        return this.health.runAll();
    }

    /**
     * Get metrics
     */
    getMetrics(): Metric[] {
        return this.metrics.getMetrics();
    }
}

// Export singleton
export const monitor = new ApplicationMonitor();

/**
 * Request tracking middleware
 */
export function trackRequestMetrics(
    method: string,
    path: string,
    handler: () => Promise<Response>
): Promise<Response> {
    const start = Date.now();

    return handler()
        .then(response => {
            const duration = Date.now() - start;
            monitor.trackRequest(method, path, response.status, duration);
            return response;
        })
        .catch(error => {
            const duration = Date.now() - start;
            monitor.trackRequest(method, path, 500, duration);
            throw error;
        });
}

