import { prisma } from '@/lib/prisma';
import { PriceComponentType } from '@prisma/client';

export interface PriceContext {
    brandId: string;
    productId: string;
    variantId: string;
    quantity: number;
    options: {
        printMethod?: string; // 'dtf' | 'plastisol'
        designSize?: string;  // 'A4' | 'A3'
        colorCount?: number;  // for plastisol
        [key: string]: any;
    };
}

export interface PriceBreakdown {
    basePrice: number;
    unitPrice: number;
    totalPrice: number;
    currency: string;
    components: {
        name: string;
        amount: number;
        type: string;
        note?: string;
    }[];
}

export class PriceCalculator {
    static async calculate(ctx: PriceContext): Promise<PriceBreakdown> {
        // 1. Fetch Variant Base Price
        const variant = await prisma.productVariant.findUnique({
            where: { id: ctx.variantId },
            include: { product: true }
        });

        if (!variant) throw new Error('Variant not found');

        // Auto-fill context hierarchy from database if missing
        if (!ctx.productId) ctx.productId = variant.productId;
        if (!ctx.brandId) ctx.brandId = variant.product.brandId;

        let unitPrice = Number(variant.basePrice);
        const components = [{
            name: 'Base Price',
            amount: unitPrice,
            type: 'BASE',
            note: variant.name
        }];

        // 2. Fetch Applicable Rules
        // We fetch ALL active rules for this scope hierarchy and filter in memory for efficiency with complex JSON logic
        const rules = await prisma.priceRule.findMany({
            where: {
                isActive: true,
                OR: [
                    { scope: 'GLOBAL' },
                    { scope: 'BRAND', scopeId: ctx.brandId },
                    { scope: 'PRODUCT', scopeId: ctx.productId },
                    { scope: 'VARIANT', scopeId: ctx.variantId }
                ],
                AND: [
                    { OR: [{ minQty: null }, { minQty: { lte: ctx.quantity } }] },
                    { OR: [{ maxQty: null }, { maxQty: { gte: ctx.quantity } }] }
                ]
            },
            include: { component: true },
            orderBy: { priority: 'asc' } // Apply lower priority first? Or High? Usually additive doesn't matter, but Multipliers matter. 
            // Let's assume standard order: Unit additions -> Multipliers -> Fixed additions
        });

        // 3. Process Rules
        let multiplier = 1;
        let fixedAdditions = 0; // Added ONCE per total order? Or per unit?
        // Schema says: PriceComponentType. 
        // We need to define if "FIXED" means "Per Order" or "Per Unit fixed fee".
        // Usually PER_UNIT is per item. FIXED is One-time setup fee.

        for (const rule of rules) {
            // METADATA MATCHING
            if (!this.matchesMetadata(rule.metadata, ctx.options)) continue;

            const amount = Number(rule.amount);

            switch (rule.component.type) {
                case 'PER_UNIT':
                    unitPrice += amount;
                    components.push({
                        name: rule.component.name,
                        amount: amount,
                        type: 'PER_UNIT',
                        note: `+${amount}`
                    });
                    break;
                case 'PERCENT':
                    // Percent of what? Usually current unit price.
                    const pVal = unitPrice * (amount / 100);
                    unitPrice += pVal;
                    components.push({
                        name: rule.component.name,
                        amount: pVal,
                        type: 'PERCENT',
                        note: `${amount}%`
                    });
                    break;
                case 'MULTIPLIER':
                    multiplier *= amount;
                    components.push({
                        name: rule.component.name,
                        amount: amount,
                        type: 'MULTIPLIER',
                        note: `x${amount}`
                    });
                    break;
                case 'FIXED':
                    fixedAdditions += amount;
                    components.push({
                        name: rule.component.name,
                        amount: amount,
                        type: 'FIXED',
                        note: `Flat Fee`
                    });
                    break;
            }
        }

        // Final Calculation
        // (Unit * Multiplier) * Qty + Fixed
        const finalUnitPrice = unitPrice * multiplier;
        const total = (finalUnitPrice * ctx.quantity) + fixedAdditions;

        return {
            basePrice: Number(variant.basePrice),
            unitPrice: finalUnitPrice,
            totalPrice: total,
            currency: 'IDR',
            components
        };
    }

    private static matchesMetadata(ruleMeta: any, contextOptions: any): boolean {
        if (!ruleMeta || Object.keys(ruleMeta).length === 0) return true;

        // Simple subset match: All keys in ruleMeta must match contextOptions
        for (const [key, value] of Object.entries(ruleMeta)) {
            if (contextOptions[key] !== value) return false;
        }
        return true;
    }
}

import { prisma } from '@/lib/prisma';
import { Decimal } from '@prisma/client/runtime/library';
import { PriceComponentType, PriceScope } from '@prisma/client';
import {
    OrderInput,
    PriceCalculationResult,
    BreakdownItem,
    AppliedRule,
    PriceRuleWithComponent,
    VariantWithRelations
} from './types';

/**
 * Main pricing calculation engine
 * Calculates total price with detailed breakdown based on pricing rules
 * Falls back to MockupVariant.price if no pricing rules are active
 */
export async function calculatePrice(order: OrderInput): Promise<PriceCalculationResult> {
    // 1. Load variant with relations
    const variant = await loadVariant(order.variantId);
    if (!variant) {
        throw new Error(`Variant ${order.variantId} not found`);
    }

    // 2. Load all active pricing rules
    const rules = await loadActivePricingRules(variant, order.currency || 'IDR');

    // 3. If no pricing rules exist, use fallback (existing MockupVariant.price)
    if (rules.length === 0) {
        return createFallbackPricing(variant, order.qty);
    }

    // 4. Calculate price using rules
    const breakdown: BreakdownItem[] = [];
    const appliedRules: AppliedRule[] = [];

    // 4a. Base unit price (with bulk tier if applicable)
    const basePrice = calculateBasePrice(rules, order.qty, breakdown, appliedRules);

    // 4b. Printing costs (if applicable)
    if (order.printing) {
        calculatePrintingCosts(rules, order, breakdown, appliedRules);
    }

    // 5. Calculate total
    const total = breakdown.reduce((sum, item) => {
        return new Decimal(sum).plus(new Decimal(item.amount));
    }, new Decimal(0));

    return {
        total,
        breakdown,
        appliedRules,
        usedFallback: false
    };
}

/**
 * Load variant with product and brand relations
 */
async function loadVariant(variantId: string): Promise<VariantWithRelations | null> {
    return await prisma.frozenVariant.findUnique({
        where: { id: variantId },
        select: {
            id: true,
            price: true,
            product: {
                select: {
                    id: true,
                    category: {
                        select: {
                            brandId: true
                        }
                    }
                }
            }
        }
    });
}

/**
 * Load all active pricing rules for this variant
 * Includes rules from all scopes (GLOBAL, BRAND, PRODUCT, VARIANT)
 */
async function loadActivePricingRules(
    variant: VariantWithRelations,
    currency: string
): Promise<PriceRuleWithComponent[]> {
    const now = new Date();

    const rules = await prisma.priceRule.findMany({
        where: {
            isActive: true,
            currency,
            OR: [
                // GLOBAL rules
                { scope: PriceScope.GLOBAL, scopeId: null },
                // BRAND rules
                { scope: PriceScope.BRAND, scopeId: variant.product.category.brandId },
                // PRODUCT rules
                { scope: PriceScope.PRODUCT, scopeId: variant.product.id },
                // VARIANT rules
                { scope: PriceScope.VARIANT, scopeId: variant.id }
            ],
            AND: [
                {
                    OR: [
                        { startAt: null },
                        { startAt: { lte: now } }
                    ]
                },
                {
                    OR: [
                        { endAt: null },
                        { endAt: { gte: now } }
                    ]
                }
            ]
        },
        include: {
            component: {
                select: {
                    code: true,
                    name: true,
                    type: true
                }
            }
        },
        orderBy: {
            priority: 'desc' // Higher priority first
        }
    });

    return rules as PriceRuleWithComponent[];
}

/**
 * Create fallback pricing using existing MockupVariant.price
 */
function createFallbackPricing(variant: VariantWithRelations, qty: number): PriceCalculationResult {
    const unitPrice = new Decimal(variant.price);
    const total = unitPrice.times(qty);

    return {
        total,
        breakdown: [
            {
                code: 'LEGACY_PRICE',
                name: 'Base Price (Legacy)',
                componentType: PriceComponentType.PER_UNIT,
                unit: unitPrice,
                qty,
                amount: total
            }
        ],
        appliedRules: [],
        usedFallback: true
    };
}

/**
 * Calculate base unit price with bulk tier logic
 */
function calculateBasePrice(
    rules: PriceRuleWithComponent[],
    qty: number,
    breakdown: BreakdownItem[],
    appliedRules: AppliedRule[]
): Decimal {
    // Try to find bulk tier rule first (higher priority)
    const bulkTierRules = filterRulesByComponent(rules, 'BULK_TIER');
    const bulkTierRule = findMatchingRule(bulkTierRules, qty);

    if (bulkTierRule) {
        const unitPrice = new Decimal(bulkTierRule.amount);
        const total = unitPrice.times(qty);

        breakdown.push({
            code: 'BULK_TIER',
            name: `${bulkTierRule.component.name} (${bulkTierRule.minQty}-${bulkTierRule.maxQty || '∞'} pcs)`,
            componentType: bulkTierRule.component.type,
            unit: unitPrice,
            qty,
            amount: total,
            ruleId: bulkTierRule.id
        });

        appliedRules.push({
            ruleId: bulkTierRule.id,
            componentCode: 'BULK_TIER',
            scope: bulkTierRule.scope,
            scopeId: bulkTierRule.scopeId,
            priority: bulkTierRule.priority
        });

        return total;
    }

    // Fallback to BASE_UNIT
    const baseUnitRules = filterRulesByComponent(rules, 'BASE_UNIT');
    const baseUnitRule = findBestRule(baseUnitRules);

    if (baseUnitRule) {
        const unitPrice = new Decimal(baseUnitRule.amount);
        const total = unitPrice.times(qty);

        breakdown.push({
            code: 'BASE_UNIT',
            name: baseUnitRule.component.name,
            componentType: baseUnitRule.component.type,
            unit: unitPrice,
            qty,
            amount: total,
            ruleId: baseUnitRule.id
        });

        appliedRules.push({
            ruleId: baseUnitRule.id,
            componentCode: 'BASE_UNIT',
            scope: baseUnitRule.scope,
            scopeId: baseUnitRule.scopeId,
            priority: baseUnitRule.priority
        });

        return total;
    }

    // No base price found - return 0 (should not happen with proper seed data)
    return new Decimal(0);
}

/**
 * Calculate printing costs (setup fee, per-color, size multiplier, DTF per-meter)
 */
function calculatePrintingCosts(
    rules: PriceRuleWithComponent[],
    order: OrderInput,
    breakdown: BreakdownItem[],
    appliedRules: AppliedRule[]
): void {
    if (!order.printing) return;

    const { method, colors, size, lengthMeter } = order.printing;

    // 1. Setup fee (FIXED)
    const setupRules = filterRulesByComponent(rules, 'PRINT_SETUP');
    const setupRule = setupRules.find(r => r.metadata?.printMethod === method);

    if (setupRule) {
        const amount = new Decimal(setupRule.amount);

        breakdown.push({
            code: 'PRINT_SETUP',
            name: `${method.toUpperCase()} Setup Fee`,
            componentType: setupRule.component.type,
            amount,
            metadata: { printMethod: method },
            ruleId: setupRule.id
        });

        appliedRules.push({
            ruleId: setupRule.id,
            componentCode: 'PRINT_SETUP',
            scope: setupRule.scope,
            scopeId: setupRule.scopeId,
            priority: setupRule.priority
        });
    }

    // 2. Per-color cost (PER_UNIT)
    if (colors && colors > 0 && method === 'plastisol') {
        const perColorRules = filterRulesByComponent(rules, 'PER_COLOR');
        const perColorRule = perColorRules.find(r => r.metadata?.printMethod === method);

        if (perColorRule) {
            const perColorAmount = new Decimal(perColorRule.amount);
            const total = perColorAmount.times(colors).times(order.qty);

            breakdown.push({
                code: 'PER_COLOR',
                name: `Per Color (${colors} colors)`,
                componentType: perColorRule.component.type,
                unit: perColorAmount,
                qty: order.qty,
                colors,
                amount: total,
                metadata: { printMethod: method, colors },
                ruleId: perColorRule.id
            });

            appliedRules.push({
                ruleId: perColorRule.id,
                componentCode: 'PER_COLOR',
                scope: perColorRule.scope,
                scopeId: perColorRule.scopeId,
                priority: perColorRule.priority
            });
        }
    }

    // 3. Size multiplier (MULTIPLIER)
    if (size) {
        const sizeRules = filterRulesByComponent(rules, 'SIZE_MULT');
        const sizeRule = sizeRules.find(r => r.metadata?.size === size);

        if (sizeRule) {
            // Get multiplier from metadata (e.g., "1.2") instead of amount
            const multiplierValue = sizeRule.metadata?.multiplier || sizeRule.amount;
            const multiplier = new Decimal(multiplierValue);

            // Apply multiplier to base unit price
            // Find base price from breakdown
            const baseItem = breakdown.find(b => b.code === 'BASE_UNIT' || b.code === 'BULK_TIER');
            if (baseItem && baseItem.unit) {
                const baseUnitPrice = new Decimal(baseItem.unit);
                const extra = baseUnitPrice.times(multiplier.minus(1)).times(order.qty);

                breakdown.push({
                    code: 'SIZE_MULT',
                    name: `Size ${size} Multiplier (${multiplier}x)`,
                    componentType: sizeRule.component.type,
                    unit: multiplier,
                    qty: order.qty,
                    amount: extra,
                    metadata: { size, multiplier: multiplier.toString() },
                    ruleId: sizeRule.id
                });

                appliedRules.push({
                    ruleId: sizeRule.id,
                    componentCode: 'SIZE_MULT',
                    scope: sizeRule.scope,
                    scopeId: sizeRule.scopeId,
                    priority: sizeRule.priority
                });
            }
        }
    }

    // 4. DTF per-meter (PER_METER)
    if (method === 'dtf' && lengthMeter) {
        const perMeterRules = filterRulesByComponent(rules, 'PER_METER');
        const perMeterRule = perMeterRules.find(r => r.metadata?.printMethod === method);

        if (perMeterRule) {
            const minMeter = perMeterRule.minOrderMeter ? new Decimal(perMeterRule.minOrderMeter) : new Decimal(1);
            const actualMeter = new Decimal(lengthMeter).greaterThanOrEqualTo(minMeter)
                ? new Decimal(lengthMeter)
                : minMeter;

            const perMeterAmount = new Decimal(perMeterRule.amount);
            const total = perMeterAmount.times(actualMeter);

            breakdown.push({
                code: 'PER_METER',
                name: `DTF Per Meter (${actualMeter}m)`,
                componentType: perMeterRule.component.type,
                unit: perMeterAmount,
                qty: actualMeter.toNumber(),
                amount: total,
                metadata: { printMethod: method, lengthMeter: actualMeter.toString() },
                ruleId: perMeterRule.id
            });

            appliedRules.push({
                ruleId: perMeterRule.id,
                componentCode: 'PER_METER',
                scope: perMeterRule.scope,
                scopeId: perMeterRule.scopeId,
                priority: perMeterRule.priority
            });
        }
    }
}

/**
 * Filter rules by component code
 */
function filterRulesByComponent(rules: PriceRuleWithComponent[], componentCode: string): PriceRuleWithComponent[] {
    return rules.filter(r => r.component.code === componentCode);
}

/**
 * Find matching rule based on quantity range
 */
function findMatchingRule(rules: PriceRuleWithComponent[], qty: number): PriceRuleWithComponent | undefined {
    return rules.find(r => {
        const min = r.minQty ?? 0;
        const max = r.maxQty ?? Infinity;
        return qty >= min && qty <= max;
    });
}

/**
 * Find best rule based on scope priority (VARIANT > PRODUCT > BRAND > GLOBAL)
 * and then by priority number
 */
function findBestRule(rules: PriceRuleWithComponent[]): PriceRuleWithComponent | undefined {
    if (rules.length === 0) return undefined;

    // Scope priority weights
    const scopeWeight = {
        [PriceScope.VARIANT]: 4,
        [PriceScope.PRODUCT]: 3,
        [PriceScope.BRAND]: 2,
        [PriceScope.GLOBAL]: 1
    };

    // Sort by scope weight (desc) then by priority (desc)
    const sorted = [...rules].sort((a, b) => {
        const scopeDiff = scopeWeight[b.scope] - scopeWeight[a.scope];
        if (scopeDiff !== 0) return scopeDiff;
        return b.priority - a.priority;
    });

    return sorted[0];
}

import { Decimal } from '@prisma/client/runtime/library';
import { PriceComponentType, PriceScope } from '@prisma/client';

/**
 * Input for price calculation
 */
export type OrderInput = {
    variantId: string;
    qty: number;
    printing?: {
        method: 'plastisol' | 'dtf' | 'heatpress';
        colors?: number;
        size?: 'S' | 'M' | 'L' | 'XL' | 'XXL';
        lengthMeter?: number; // for DTF
    };
    currency?: string;
};

/**
 * Individual breakdown item in price calculation
 */
export type BreakdownItem = {
    code: string;
    name: string;
    componentType: PriceComponentType;
    unit?: Decimal | number;
    qty?: number;
    colors?: number;
    amount: Decimal | number;
    metadata?: any;
    ruleId?: string;
};

/**
 * Complete price calculation result
 */
export type PriceCalculationResult = {
    total: Decimal;
    breakdown: BreakdownItem[];
    appliedRules: AppliedRule[];
    usedFallback: boolean; // true if using MockupVariant.price
};

/**
 * Information about which rule was applied
 */
export type AppliedRule = {
    ruleId: string;
    componentCode: string;
    scope: PriceScope;
    scopeId?: string | null;
    priority: number;
};

/**
 * Price rule with component info (for internal use)
 */
export type PriceRuleWithComponent = {
    id: string;
    componentId: string;
    scope: PriceScope;
    scopeId: string | null;
    priority: number;
    currency: string;
    amount: Decimal;
    minQty: number | null;
    maxQty: number | null;
    minOrderMeter: Decimal | null;
    metadata: any;
    isActive: boolean;
    startAt: Date | null;
    endAt: Date | null;
    component: {
        code: string;
        name: string;
        type: PriceComponentType;
    };
};

/**
 * Variant with product and brand info (for scope resolution)
 */
export type VariantWithRelations = {
    id: string;
    price: Decimal;
    product: {
        id: string;
        category: {
            brandId: string;
        };
    };
};

// ACHIERA Platform - Security Audit Service
// Comprehensive security event logging and monitoring

import { prisma } from '@/lib/prisma';

export type SecurityEventType =
    | 'LOGIN_SUCCESS'
    | 'LOGIN_FAILURE'
    | 'LOGOUT'
    | 'PASSWORD_CHANGE'
    | 'ROLE_CHANGE'
    | 'UNAUTHORIZED_ACCESS'
    | 'CSRF_ATTEMPT'
    | 'RATE_LIMIT_EXCEEDED'
    | 'SUSPICIOUS_ACTIVITY'
    | 'DATA_EXPORT'
    | 'SENSITIVE_DATA_ACCESS'
    | 'PERMISSION_DENIED'
    | 'API_ERROR';

export type SecurityEvent = {
    type: SecurityEventType;
    userId?: string;
    brandId?: string;
    ip?: string;
    userAgent?: string;
    metadata?: Record<string, any>;
};

export class SecurityAuditService {
    /**
     * Log security event
     */
    async logEvent(event: SecurityEvent): Promise<void> {
        try {
            await prisma.auditLog.create({
                data: {
                    userId: event.userId || null,
                    brandId: event.brandId || null,
                    action: `SECURITY_${event.type}`,
                    entityType: 'SECURITY',
                    entityId: 'SYSTEM',
                    metadata: {
                        ...event.metadata,
                        ip: event.ip,
                        userAgent: event.userAgent,
                        timestamp: new Date().toISOString()
                    }
                }
            });

            // Check for suspicious patterns
            await this.detectSuspiciousActivity(event);

        } catch (error) {
            console.error('Failed to log security event:', error);
        }
    }

    /**
     * Log login attempt
     */
    async logLogin(
        email: string,
        success: boolean,
        ip: string,
        userAgent?: string
    ): Promise<void> {
        await this.logEvent({
            type: success ? 'LOGIN_SUCCESS' : 'LOGIN_FAILURE',
            ip,
            userAgent,
            metadata: { email }
        });

        // Check for brute force
        if (!success) {
            await this.checkBruteForce(email, ip);
        }
    }

    /**
     * Log sensitive data access
     */
    async logSensitiveAccess(
        userId: string,
        brandId: string,
        dataType: string,
        entityId: string
    ): Promise<void> {
        await this.logEvent({
            type: 'SENSITIVE_DATA_ACCESS',
            userId,
            brandId,
            metadata: {
                dataType,
                entityId
            }
        });
    }

    /**
     * Log data export
     */
    async logDataExport(
        userId: string,
        brandId: string,
        exportType: string,
        recordCount: number
    ): Promise<void> {
        await this.logEvent({
            type: 'DATA_EXPORT',
            userId,
            brandId,
            metadata: {
                exportType,
                recordCount
            }
        });
    }

    /**
     * Detect brute force attempts
     */
    private async checkBruteForce(email: string, ip: string): Promise<void> {
        const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);

        const recentFailures = await prisma.auditLog.count({
            where: {
                action: 'SECURITY_LOGIN_FAILURE',
                metadata: {
                    path: ['email'],
                    equals: email
                },
                createdAt: {
                    gte: fiveMinutesAgo
                }
            }
        });

        if (recentFailures >= 5) {
            await this.logEvent({
                type: 'SUSPICIOUS_ACTIVITY',
                ip,
                metadata: {
                    reason: 'BRUTE_FORCE_DETECTED',
                    email,
                    failureCount: recentFailures
                }
            });

            // TODO: Implement account lockout or IP blocking
        }
    }

    /**
     * Detect suspicious activity patterns
     */
    private async detectSuspiciousActivity(event: SecurityEvent): Promise<void> {
        if (!event.userId) return;

        const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);

        // Check for rapid role changes
        if (event.type === 'ROLE_CHANGE') {
            const recentRoleChanges = await prisma.auditLog.count({
                where: {
                    userId: event.userId,
                    action: 'SECURITY_ROLE_CHANGE',
                    createdAt: {
                        gte: oneHourAgo
                    }
                }
            });

            if (recentRoleChanges >= 3) {
                await this.logEvent({
                    type: 'SUSPICIOUS_ACTIVITY',
                    userId: event.userId,
                    metadata: {
                        reason: 'RAPID_ROLE_CHANGES',
                        count: recentRoleChanges
                    }
                });
            }
        }

        // Check for unusual access patterns
        if (event.type === 'UNAUTHORIZED_ACCESS') {
            const recentUnauthorized = await prisma.auditLog.count({
                where: {
                    userId: event.userId,
                    action: 'SECURITY_UNAUTHORIZED_ACCESS',
                    createdAt: {
                        gte: oneHourAgo
                    }
                }
            });

            if (recentUnauthorized >= 10) {
                await this.logEvent({
                    type: 'SUSPICIOUS_ACTIVITY',
                    userId: event.userId,
                    metadata: {
                        reason: 'REPEATED_UNAUTHORIZED_ACCESS',
                        count: recentUnauthorized
                    }
                });
            }
        }
    }

    /**
     * Get security events for user
     */
    async getUserSecurityEvents(
        userId: string,
        limit: number = 50
    ): Promise<any[]> {
        return prisma.auditLog.findMany({
            where: {
                userId,
                action: {
                    startsWith: 'SECURITY_'
                }
            },
            orderBy: {
                createdAt: 'desc'
            },
            take: limit
        });
    }

    /**
     * Get security events for brand
     */
    async getBrandSecurityEvents(
        brandId: string,
        limit: number = 100
    ): Promise<any[]> {
        return prisma.auditLog.findMany({
            where: {
                brandId,
                action: {
                    startsWith: 'SECURITY_'
                }
            },
            orderBy: {
                createdAt: 'desc'
            },
            take: limit
        });
    }

    /**
     * Get suspicious activity summary
     */
    async getSuspiciousActivitySummary(days: number = 7): Promise<any> {
        const startDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000);

        const events = await prisma.auditLog.findMany({
            where: {
                action: 'SECURITY_SUSPICIOUS_ACTIVITY',
                createdAt: {
                    gte: startDate
                }
            }
        });

        const summary = {
            totalEvents: events.length,
            byReason: {} as Record<string, number>,
            byUser: {} as Record<string, number>
        };

        for (const event of events) {
            const reason = event.metadata?.reason || 'UNKNOWN';
            summary.byReason[reason] = (summary.byReason[reason] || 0) + 1;

            if (event.userId) {
                summary.byUser[event.userId] = (summary.byUser[event.userId] || 0) + 1;
            }
        }

        return summary;
    }

    /**
     * Generate security report
     */
    async generateSecurityReport(
        brandId: string,
        startDate: Date,
        endDate: Date
    ): Promise<any> {
        const events = await prisma.auditLog.findMany({
            where: {
                brandId,
                action: {
                    startsWith: 'SECURITY_'
                },
                createdAt: {
                    gte: startDate,
                    lte: endDate
                }
            }
        });

        const report = {
            period: { start: startDate, end: endDate },
            totalEvents: events.length,
            byType: {} as Record<string, number>,
            loginAttempts: {
                success: 0,
                failure: 0
            },
            unauthorizedAccess: 0,
            suspiciousActivity: 0
        };

        for (const event of events) {
            const type = event.action.replace('SECURITY_', '');
            report.byType[type] = (report.byType[type] || 0) + 1;

            if (type === 'LOGIN_SUCCESS') report.loginAttempts.success++;
            if (type === 'LOGIN_FAILURE') report.loginAttempts.failure++;
            if (type === 'UNAUTHORIZED_ACCESS') report.unauthorizedAccess++;
            if (type === 'SUSPICIOUS_ACTIVITY') report.suspiciousActivity++;
        }

        return report;
    }
}

