// ACHIERA Platform - Sensitive Data Protection
// Encryption, masking, and secure data handling

import crypto from 'crypto';

const ENCRYPTION_KEY = process.env.ENCRYPTION_KEY || '';
const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 16;
const AUTH_TAG_LENGTH = 16;

/**
 * Encrypt sensitive data
 */
export function encrypt(text: string): string {
    if (!ENCRYPTION_KEY) {
        throw new Error('ENCRYPTION_KEY not configured');
    }

    const iv = crypto.randomBytes(IV_LENGTH);
    const cipher = crypto.createCipheriv(
        ALGORITHM,
        Buffer.from(ENCRYPTION_KEY, 'hex'),
        iv
    );

    let encrypted = cipher.update(text, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const authTag = cipher.getAuthTag();

    // Format: iv:authTag:encrypted
    return `${iv.toString('hex')}:${authTag.toString('hex')}:${encrypted}`;
}

/**
 * Decrypt sensitive data
 */
export function decrypt(encryptedText: string): string {
    if (!ENCRYPTION_KEY) {
        throw new Error('ENCRYPTION_KEY not configured');
    }

    const parts = encryptedText.split(':');
    if (parts.length !== 3) {
        throw new Error('Invalid encrypted data format');
    }

    const [ivHex, authTagHex, encrypted] = parts;
    const iv = Buffer.from(ivHex, 'hex');
    const authTag = Buffer.from(authTagHex, 'hex');

    const decipher = crypto.createDecipheriv(
        ALGORITHM,
        Buffer.from(ENCRYPTION_KEY, 'hex'),
        iv
    );

    decipher.setAuthTag(authTag);

    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
}

/**
 * Hash password (one-way)
 */
export async function hashPassword(password: string): Promise<string> {
    const bcrypt = await import('bcrypt');
    return bcrypt.hash(password, 12);
}

/**
 * Verify password
 */
export async function verifyPassword(
    password: string,
    hash: string
): Promise<boolean> {
    const bcrypt = await import('bcrypt');
    return bcrypt.compare(password, hash);
}

/**
 * Mask sensitive data for display
 */
export function maskEmail(email: string): string {
    const [local, domain] = email.split('@');
    if (!local || !domain) return '***@***.***';

    const maskedLocal = local.length > 2
        ? `${local[0]}${'*'.repeat(local.length - 2)}${local[local.length - 1]}`
        : '**';

    return `${maskedLocal}@${domain}`;
}

/**
 * Mask phone number
 */
export function maskPhone(phone: string): string {
    if (phone.length < 4) return '****';

    return `${phone.slice(0, 2)}${'*'.repeat(phone.length - 4)}${phone.slice(-2)}`;
}

/**
 * Mask credit card (show last 4 digits)
 */
export function maskCardNumber(cardNumber: string): string {
    const cleaned = cardNumber.replace(/\s/g, '');
    if (cleaned.length < 4) return '****';

    return `**** **** **** ${cleaned.slice(-4)}`;
}

/**
 * Sanitize user input (prevent XSS)
 */
export function sanitizeInput(input: string): string {
    return input
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#x27;')
        .replace(/\//g, '&#x2F;');
}

/**
 * Generate secure random token
 */
export function generateSecureToken(length: number = 32): string {
    return crypto.randomBytes(length).toString('hex');
}

/**
 * Hash data for comparison (deterministic)
 */
export function hashData(data: string): string {
    return crypto
        .createHash('sha256')
        .update(data)
        .digest('hex');
}

/**
 * Redact sensitive fields from object
 */
export function redactSensitiveFields<T extends Record<string, any>>(
    obj: T,
    sensitiveFields: string[] = ['password', 'passwordHash', 'token', 'secret']
): T {
    const redacted = { ...obj };

    for (const field of sensitiveFields) {
        if (field in redacted) {
            redacted[field] = '[REDACTED]';
        }
    }

    return redacted;
}

/**
 * Validate password strength
 */
export function validatePasswordStrength(password: string): {
    isValid: boolean;
    errors: string[];
} {
    const errors: string[] = [];

    if (password.length < 8) {
        errors.push('Password must be at least 8 characters');
    }

    if (!/[A-Z]/.test(password)) {
        errors.push('Password must contain at least one uppercase letter');
    }

    if (!/[a-z]/.test(password)) {
        errors.push('Password must contain at least one lowercase letter');
    }

    if (!/[0-9]/.test(password)) {
        errors.push('Password must contain at least one number');
    }

    if (!/[^A-Za-z0-9]/.test(password)) {
        errors.push('Password must contain at least one special character');
    }

    return {
        isValid: errors.length === 0,
        errors
    };
}

/**
 * Secure comparison (timing-safe)
 */
export function secureCompare(a: string, b: string): boolean {
    if (a.length !== b.length) return false;

    return crypto.timingSafeEqual(
        Buffer.from(a),
        Buffer.from(b)
    );
}

/**
 * Generate TOTP secret (for 2FA)
 */
export function generateTOTPSecret(): string {
    return crypto.randomBytes(20).toString('base32');
}

// ACHIERA Platform - Role Escalation Prevention
// Prevents unauthorized role changes and privilege escalation

import { prisma } from '@/lib/prisma';
import { BrandRole, GlobalRole } from '@prisma/client';

/**
 * Role hierarchy (lower number = higher privilege)
 */
const ROLE_HIERARCHY: Record<BrandRole, number> = {
    BRAND_ADMIN: 1,
    BRAND_FINANCE: 2,
    BRAND_WAREHOUSE_ADMIN: 2,
    BRAND_MARKETING: 3,
    WAREHOUSE_STAFF: 4,
    CUSTOMER_SUPPORT: 4,
    RESELLER: 5,
    CONSUMER: 6
};

const GLOBAL_ROLE_HIERARCHY: Record<GlobalRole, number> = {
    OWNER: 1,
    PLATFORM_ADMIN: 2,
    PLATFORM_FINANCE: 3,
    PLATFORM_ANALYST: 4,
    USER: 5
};

export class RoleEscalationError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'RoleEscalationError';
    }
}

/**
 * Validate role assignment (prevent escalation)
 */
export async function validateRoleAssignment(
    assignerId: string,
    targetUserId: string,
    brandId: string,
    newRole: BrandRole
): Promise<void> {
    // Get assigner's role
    const assigner = await prisma.user.findUnique({
        where: { id: assignerId },
        include: {
            brandRoles: {
                where: { brandId }
            }
        }
    });

    if (!assigner) {
        throw new RoleEscalationError('Assigner not found');
    }

    // OWNER bypass
    if (assigner.globalRole === 'OWNER') {
        await logRoleChange(assignerId, targetUserId, brandId, newRole, 'OWNER_BYPASS');
        return;
    }

    // Get assigner's brand role
    const assignerRole = assigner.brandRoles[0]?.role;
    if (!assignerRole) {
        throw new RoleEscalationError('Assigner has no role in this brand');
    }

    // Only BRAND_ADMIN can assign roles
    if (assignerRole !== 'BRAND_ADMIN') {
        throw new RoleEscalationError('Only BRAND_ADMIN can assign roles');
    }

    // Cannot assign role higher than own role
    if (ROLE_HIERARCHY[newRole] <= ROLE_HIERARCHY[assignerRole]) {
        throw new RoleEscalationError('Cannot assign role equal to or higher than your own');
    }

    // Get target user's current role
    const targetRole = await prisma.userBrandRole.findUnique({
        where: {
            userId_brandId: {
                userId: targetUserId,
                brandId
            }
        }
    });

    // Cannot modify users with higher or equal roles
    if (targetRole && ROLE_HIERARCHY[targetRole.role] <= ROLE_HIERARCHY[assignerRole]) {
        throw new RoleEscalationError('Cannot modify users with equal or higher roles');
    }

    // Log the role change
    await logRoleChange(assignerId, targetUserId, brandId, newRole, 'APPROVED');
}

/**
 * Validate global role change (platform-level)
 */
export async function validateGlobalRoleChange(
    assignerId: string,
    targetUserId: string,
    newGlobalRole: GlobalRole
): Promise<void> {
    const assigner = await prisma.user.findUnique({
        where: { id: assignerId }
    });

    if (!assigner) {
        throw new RoleEscalationError('Assigner not found');
    }

    // Only OWNER can change global roles
    if (assigner.globalRole !== 'OWNER') {
        throw new RoleEscalationError('Only OWNER can change global roles');
    }

    // Cannot assign OWNER role (must be done manually in database)
    if (newGlobalRole === 'OWNER') {
        throw new RoleEscalationError('OWNER role cannot be assigned programmatically');
    }

    // Get target user
    const target = await prisma.user.findUnique({
        where: { id: targetUserId }
    });

    if (!target) {
        throw new RoleEscalationError('Target user not found');
    }

    // Cannot modify other OWNERs
    if (target.globalRole === 'OWNER') {
        throw new RoleEscalationError('Cannot modify OWNER users');
    }

    await logGlobalRoleChange(assignerId, targetUserId, newGlobalRole);
}

/**
 * Prevent self-role modification
 */
export async function preventSelfRoleModification(
    userId: string,
    targetUserId: string
): Promise<void> {
    if (userId === targetUserId) {
        throw new RoleEscalationError('Cannot modify your own role');
    }
}

/**
 * Validate permission for sensitive actions
 */
export async function validateSensitiveAction(
    userId: string,
    brandId: string,
    action: string,
    requiredRoles: BrandRole[]
): Promise<void> {
    const user = await prisma.user.findUnique({
        where: { id: userId },
        include: {
            brandRoles: {
                where: { brandId }
            }
        }
    });

    if (!user) {
        throw new RoleEscalationError('User not found');
    }

    // OWNER bypass
    if (user.globalRole === 'OWNER') {
        await logSensitiveAction(userId, brandId, action, 'OWNER_BYPASS');
        return;
    }

    const userRole = user.brandRoles[0]?.role;
    if (!userRole || !requiredRoles.includes(userRole)) {
        await logSensitiveAction(userId, brandId, action, 'DENIED');
        throw new RoleEscalationError(`Action '${action}' requires one of: ${requiredRoles.join(', ')}`);
    }

    await logSensitiveAction(userId, brandId, action, 'APPROVED');
}

/**
 * Log role changes for audit
 */
async function logRoleChange(
    assignerId: string,
    targetUserId: string,
    brandId: string,
    newRole: BrandRole,
    status: string
) {
    await prisma.auditLog.create({
        data: {
            userId: assignerId,
            brandId,
            action: 'ROLE_CHANGE',
            entityType: 'USER_ROLE',
            entityId: targetUserId,
            metadata: {
                targetUserId,
                newRole,
                status,
                timestamp: new Date().toISOString()
            }
        }
    });
}

/**
 * Log global role changes
 */
async function logGlobalRoleChange(
    assignerId: string,
    targetUserId: string,
    newGlobalRole: GlobalRole
) {
    await prisma.auditLog.create({
        data: {
            userId: assignerId,
            brandId: null,
            action: 'GLOBAL_ROLE_CHANGE',
            entityType: 'USER',
            entityId: targetUserId,
            metadata: {
                targetUserId,
                newGlobalRole,
                timestamp: new Date().toISOString()
            }
        }
    });
}

/**
 * Log sensitive actions
 */
async function logSensitiveAction(
    userId: string,
    brandId: string,
    action: string,
    status: string
) {
    await prisma.auditLog.create({
        data: {
            userId,
            brandId,
            action: `SENSITIVE_${action}`,
            entityType: 'SECURITY',
            entityId: 'SYSTEM',
            metadata: {
                action,
                status,
                timestamp: new Date().toISOString()
            }
        }
    });
}

/**
 * Get role hierarchy level
 */
export function getRoleLevel(role: BrandRole): number {
    return ROLE_HIERARCHY[role];
}

/**
 * Check if role A can manage role B
 */
export function canManageRole(managerRole: BrandRole, targetRole: BrandRole): boolean {
    return ROLE_HIERARCHY[managerRole] < ROLE_HIERARCHY[targetRole];
}

// ACHIERA Platform - Secure API Route Pattern
// Template for creating secure API endpoints with RBAC

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth/config';
import { requireAccess } from '@/lib/auth/rbac';
import { z } from 'zod';
import { prisma } from '@/lib/prisma';
import { BrandRole } from '@prisma/client';

/**
 * Secure API handler wrapper
 */
export function secureAPIRoute<T = any>(config: {
    allowedRoles: BrandRole[];
    requireBrandId?: boolean;
    schema?: z.ZodSchema<T>;
    handler: (params: {
        session: any;
        brandId?: string;
        data?: T;
        request: NextRequest;
    }) => Promise<any>;
}) {
    return async function (request: NextRequest, context?: { params: any }) {
        try {
            // 1. Authentication check
            const session = await getServerSession(authOptions);
            if (!session) {
                return NextResponse.json(
                    { error: 'Unauthorized' },
                    { status: 401 }
                );
            }

            // 2. Extract brandId from URL or body
            let brandId: string | undefined;
            if (config.requireBrandId) {
                brandId = context?.params?.brandSlug
                    ? await getBrandIdFromSlug(context.params.brandSlug)
                    : undefined;

                if (!brandId) {
                    return NextResponse.json(
                        { error: 'Brand not found' },
                        { status: 404 }
                    );
                }
            }

            // 3. RBAC check
            if (brandId) {
                try {
                    await requireAccess(brandId, config.allowedRoles);
                } catch (error) {
                    return NextResponse.json(
                        { error: 'Access denied' },
                        { status: 403 }
                    );
                }
            }

            // 4. Validate request body (if schema provided)
            let data: T | undefined;
            if (config.schema && request.method !== 'GET') {
                try {
                    const body = await request.json();
                    data = config.schema.parse(body);
                } catch (error) {
                    if (error instanceof z.ZodError) {
                        return NextResponse.json(
                            { error: 'Validation failed', details: error.errors },
                            { status: 400 }
                        );
                    }
                    return NextResponse.json(
                        { error: 'Invalid request body' },
                        { status: 400 }
                    );
                }
            }

            // 5. Execute handler
            const result = await config.handler({
                session,
                brandId,
                data,
                request
            });

            return NextResponse.json(result);

        } catch (error) {
            console.error('API Error:', error);

            // Log error for monitoring
            await logAPIError(error, request);

            return NextResponse.json(
                { error: 'Internal server error' },
                { status: 500 }
            );
        }
    };
}

/**
 * Example: Secure product creation endpoint
 */
const CreateProductSchema = z.object({
    name: z.string().min(1).max(255),
    slug: z.string().min(1).max(255),
    categoryId: z.string(),
    price: z.number().positive()
});

export const POST = secureAPIRoute({
    allowedRoles: ['BRAND_ADMIN'],
    requireBrandId: true,
    schema: CreateProductSchema,
    handler: async ({ session, brandId, data }) => {
        // Business logic here
        const product = await prisma.frozenProduct.create({
            data: {
                categoryId: data!.categoryId,
                name: data!.name,
                slug: data!.slug
            }
        });

        // Audit log
        await prisma.auditLog.create({
            data: {
                userId: session.user.id,
                brandId,
                action: 'PRODUCT_CREATE',
                entityType: 'PRODUCT',
                entityId: product.id
            }
        });

        return { product };
    }
});

/**
 * Helper: Get brand ID from slug
 */
async function getBrandIdFromSlug(slug: string): Promise<string | undefined> {
    const brand = await prisma.brand.findUnique({
        where: { slug },
        select: { id: true }
    });
    return brand?.id;
}

/**
 * Log API errors
 */
async function logAPIError(error: any, request: NextRequest) {
    try {
        await prisma.auditLog.create({
            data: {
                userId: null,
                brandId: null,
                action: 'API_ERROR',
                entityType: 'SYSTEM',
                entityId: 'ERROR',
                metadata: {
                    error: error.message,
                    stack: error.stack,
                    path: request.nextUrl.pathname,
                    method: request.method,
                    timestamp: new Date().toISOString()
                }
            }
        });
    } catch (logError) {
        console.error('Failed to log API error:', logError);
    }
}

/**
 * Rate limiting decorator
 */
export function withRateLimit(
    handler: Function,
    limit: number = 100,
    windowMs: number = 60000
) {
    const requests = new Map<string, number[]>();

    return async function (request: NextRequest, ...args: any[]) {
        const ip = request.ip || request.headers.get('x-forwarded-for') || 'unknown';
        const now = Date.now();

        // Get request timestamps for this IP
        const timestamps = requests.get(ip) || [];

        // Remove old timestamps outside the window
        const recentTimestamps = timestamps.filter(t => now - t < windowMs);

        // Check if limit exceeded
        if (recentTimestamps.length >= limit) {
            return NextResponse.json(
                { error: 'Rate limit exceeded' },
                { status: 429 }
            );
        }

        // Add current timestamp
        recentTimestamps.push(now);
        requests.set(ip, recentTimestamps);

        // Execute handler
        return handler(request, ...args);
    };
}

/**
 * CORS configuration
 */
export function withCORS(handler: Function, allowedOrigins: string[] = []) {
    return async function (request: NextRequest, ...args: any[]) {
        const origin = request.headers.get('origin');

        const response = await handler(request, ...args);

        if (origin && allowedOrigins.includes(origin)) {
            response.headers.set('Access-Control-Allow-Origin', origin);
            response.headers.set('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
            response.headers.set('Access-Control-Allow-Headers', 'Content-Type, Authorization');
        }

        return response;
    };
}

// ACHIERA Platform - Ads Service
// Campaign management and ROAS tracking (Shopee-like)

import { prisma } from '@/lib/prisma';
import type { ServiceContext } from './WarehouseService';

export type CreateCampaignInput = {
    name: string;
    budget: number;
    startDate: Date;
    endDate?: Date;
};

export type CreateAdGroupInput = {
    campaignId: string;
    name: string;
    bidAmount: number;
};

export type CreateCreativeInput = {
    groupId: string;
    headline: string;
    description?: string;
    imageUrl: string;
    targetUrl: string;
};

export class AdsService {
    /**
     * Create ad campaign
     */
    async createCampaign(ctx: ServiceContext, input: CreateCampaignInput) {
        return prisma.$transaction(async (tx) => {
            const campaign = await tx.adCampaign.create({
                data: {
                    brandId: ctx.brandId,
                    name: input.name,
                    budget: input.budget,
                    startDate: input.startDate,
                    endDate: input.endDate,
                    status: 'DRAFT'
                }
            });

            // Audit log
            await tx.auditLog.create({
                data: {
                    userId: ctx.userId,
                    brandId: ctx.brandId,
                    action: 'CAMPAIGN_CREATE',
                    entityType: 'AD_CAMPAIGN',
                    entityId: campaign.id,
                    metadata: { name: campaign.name, budget: input.budget }
                }
            });

            return campaign;
        });
    }

    /**
     * Create ad group
     */
    async createAdGroup(ctx: ServiceContext, input: CreateAdGroupInput) {
        const group = await prisma.adGroup.create({
            data: {
                campaignId: input.campaignId,
                name: input.name,
                bidAmount: input.bidAmount
            }
        });

        return group;
    }

    /**
     * Create ad creative
     */
    async createCreative(ctx: ServiceContext, input: CreateCreativeInput) {
        const creative = await prisma.adCreative.create({
            data: {
                groupId: input.groupId,
                headline: input.headline,
                description: input.description,
                imageUrl: input.imageUrl,
                targetUrl: input.targetUrl
            }
        });

        return creative;
    }

    /**
     * Get best ad to display (ranking algorithm)
     */
    async getBestAd(brandId: string, placement: string = 'homepage') {
        const now = new Date();

        // Get active creatives
        const creatives = await prisma.adCreative.findMany({
            where: {
                group: {
                    campaign: {
                        brandId,
                        status: 'ACTIVE',
                        startDate: { lte: now },
                        OR: [
                            { endDate: null },
                            { endDate: { gte: now } }
                        ]
                    }
                }
            },
            include: {
                group: {
                    include: {
                        campaign: true
                    }
                }
            }
        });

        if (creatives.length === 0) return null;

        // Rank by: Bid × CTR × CVR (Quality Score)
        const ranked = creatives.map(creative => {
            const ctr = Number(creative.cachedCtr) || 0.01; // Default 1% CTR
            const cvr = Number(creative.cachedCvr) || 0.01; // Default 1% CVR
            const bid = Number(creative.group.bidAmount);

            const score = bid * ctr * cvr;

            return { creative, score };
        }).sort((a, b) => b.score - a.score);

        const winner = ranked[0].creative;

        // Record impression
        await this.trackEvent(winner.id, 'IMPRESSION');

        return winner;
    }

    /**
     * Track ad event (impression, click, conversion)
     */
    async trackEvent(
        creativeId: string,
        type: 'IMPRESSION' | 'CLICK' | 'CONVERSION',
        userId?: string,
        revenue?: number
    ) {
        const creative = await prisma.adCreative.findUnique({
            where: { id: creativeId },
            include: { group: true }
        });

        if (!creative) return;

        // Calculate cost
        let cost = 0;
        if (type === 'CLICK') {
            cost = Number(creative.group.bidAmount);
        }

        // Record event
        await prisma.adEvent.create({
            data: {
                creativeId,
                type,
                userId,
                cost,
                revenue: revenue || 0
            }
        });

        // Update cached metrics (async in production)
        await this.updateMetrics(creativeId);
    }

    /**
     * Update cached CTR and CVR metrics
     */
    private async updateMetrics(creativeId: string) {
        const events = await prisma.adEvent.findMany({
            where: { creativeId }
        });

        const impressions = events.filter(e => e.type === 'IMPRESSION').length;
        const clicks = events.filter(e => e.type === 'CLICK').length;
        const conversions = events.filter(e => e.type === 'CONVERSION').length;

        const ctr = impressions > 0 ? clicks / impressions : 0;
        const cvr = clicks > 0 ? conversions / clicks : 0;

        await prisma.adCreative.update({
            where: { id: creativeId },
            data: {
                cachedCtr: ctr,
                cachedCvr: cvr
            }
        });
    }

    /**
     * Calculate ROAS (Return on Ad Spend)
     */
    async calculateROAS(campaignId: string) {
        const events = await prisma.adEvent.findMany({
            where: {
                creative: {
                    group: {
                        campaignId
                    }
                }
            }
        });

        const totalSpend = events
            .filter(e => e.type === 'CLICK')
            .reduce((sum, e) => sum + Number(e.cost), 0);

        const totalRevenue = events
            .filter(e => e.type === 'CONVERSION')
            .reduce((sum, e) => sum + Number(e.revenue), 0);

        const roas = totalSpend > 0 ? totalRevenue / totalSpend : 0;

        return {
            totalSpend,
            totalRevenue,
            roas,
            roasPercentage: roas * 100
        };
    }

    /**
     * Get campaign performance
     */
    async getCampaignPerformance(campaignId: string) {
        const campaign = await prisma.adCampaign.findUnique({
            where: { id: campaignId },
            include: {
                groups: {
                    include: {
                        creatives: {
                            include: {
                                events: true
                            }
                        }
                    }
                }
            }
        });

        if (!campaign) throw new Error('Campaign not found');

        // Aggregate metrics
        let totalImpressions = 0;
        let totalClicks = 0;
        let totalConversions = 0;
        let totalSpend = 0;
        let totalRevenue = 0;

        for (const group of campaign.groups) {
            for (const creative of group.creatives) {
                for (const event of creative.events) {
                    if (event.type === 'IMPRESSION') totalImpressions++;
                    if (event.type === 'CLICK') {
                        totalClicks++;
                        totalSpend += Number(event.cost);
                    }
                    if (event.type === 'CONVERSION') {
                        totalConversions++;
                        totalRevenue += Number(event.revenue);
                    }
                }
            }
        }

        const ctr = totalImpressions > 0 ? (totalClicks / totalImpressions) * 100 : 0;
        const cvr = totalClicks > 0 ? (totalConversions / totalClicks) * 100 : 0;
        const roas = totalSpend > 0 ? totalRevenue / totalSpend : 0;
        const cpc = totalClicks > 0 ? totalSpend / totalClicks : 0;

        return {
            campaign: {
                id: campaign.id,
                name: campaign.name,
                budget: Number(campaign.budget),
                status: campaign.status
            },
            metrics: {
                impressions: totalImpressions,
                clicks: totalClicks,
                conversions: totalConversions,
                ctr,
                cvr,
                totalSpend,
                totalRevenue,
                roas,
                roasPercentage: roas * 100,
                cpc
            }
        };
    }

    /**
     * Get all campaigns for brand
     */
    async getCampaigns(brandId: string) {
        return prisma.adCampaign.findMany({
            where: { brandId },
            include: {
                _count: {
                    select: {
                        groups: true
                    }
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Activate campaign
     */
    async activateCampaign(ctx: ServiceContext, campaignId: string) {
        return prisma.$transaction(async (tx) => {
            const campaign = await tx.adCampaign.update({
                where: { id: campaignId },
                data: { status: 'ACTIVE' }
            });

            await tx.auditLog.create({
                data: {
                    userId: ctx.userId,
                    brandId: ctx.brandId,
                    action: 'CAMPAIGN_ACTIVATE',
                    entityType: 'AD_CAMPAIGN',
                    entityId: campaignId
                }
            });

            return campaign;
        });
    }

    /**
     * Pause campaign
     */
    async pauseCampaign(ctx: ServiceContext, campaignId: string) {
        return prisma.adCampaign.update({
            where: { id: campaignId },
            data: { status: 'PAUSED' }
        });
    }
}

import { prisma } from '@/lib/prisma';
import { AuditAction, AuditSeverity } from '@prisma/client';

export interface AuditLogParams {
    userId: string;
    userName: string;
    userRole: string;
    action: AuditAction;
    entityType: string;
    entityId: string;
    brandId?: string;
    changes?: {
        before?: any;
        after?: any;
    };
    metadata?: any;
    severity?: AuditSeverity;
    ipAddress?: string;
    userAgent?: string;
}

export interface AuditLogFilters {
    userId?: string;
    brandId?: string;
    action?: AuditAction;
    entityType?: string;
    severity?: AuditSeverity;
    startDate?: Date;
    endDate?: Date;
    limit?: number;
}

export interface ActivitySummary {
    totalActions: number;
    actionsByType: Record<string, number>;
    actionsBySeverity: Record<string, number>;
    topUsers: Array<{ userId: string; userName: string; count: number }>;
    recentCritical: any[];
}

export interface Anomaly {
    type: 'UNUSUAL_AMOUNT' | 'OFF_HOURS' | 'RAPID_FIRE' | 'PRIVILEGE_ESCALATION' | 'FAILED_LOGIN';
    description: string;
    severity: AuditSeverity;
    userId?: string;
    brandId?: string;
    metadata: any;
    detectedAt: Date;
}

export class AuditService {
    /**
     * Log an audit event
     */
    async log(params: AuditLogParams): Promise<void> {
        try {
            await prisma.auditLog.create({
                data: {
                    userId: params.userId,
                    userName: params.userName,
                    userRole: params.userRole,
                    action: params.action,
                    entityType: params.entityType,
                    entityId: params.entityId,
                    brandId: params.brandId,
                    changes: params.changes || null,
                    metadata: params.metadata || null,
                    severity: params.severity || 'INFO',
                    ipAddress: params.ipAddress,
                    userAgent: params.userAgent,
                    timestamp: new Date()
                }
            });
        } catch (error) {
            console.error('Failed to create audit log:', error);
            // Don't throw - audit logging should never break the main flow
        }
    }

    /**
     * Get audit logs with filters
     */
    async getLogs(filters: AuditLogFilters = {}) {
        const where: any = {};

        if (filters.userId) where.userId = filters.userId;
        if (filters.brandId) where.brandId = filters.brandId;
        if (filters.action) where.action = filters.action;
        if (filters.entityType) where.entityType = filters.entityType;
        if (filters.severity) where.severity = filters.severity;

        if (filters.startDate || filters.endDate) {
            where.timestamp = {};
            if (filters.startDate) where.timestamp.gte = filters.startDate;
            if (filters.endDate) where.timestamp.lte = filters.endDate;
        }

        return await prisma.auditLog.findMany({
            where,
            include: {
                user: {
                    select: { id: true, name: true, email: true }
                },
                brand: {
                    select: { id: true, name: true, slug: true }
                }
            },
            orderBy: { timestamp: 'desc' },
            take: filters.limit || 100
        });
    }

    /**
     * Get logs for a specific entity
     */
    async getLogsByEntity(entityType: string, entityId: string) {
        return await prisma.auditLog.findMany({
            where: {
                entityType,
                entityId
            },
            include: {
                user: {
                    select: { id: true, name: true, email: true }
                }
            },
            orderBy: { timestamp: 'desc' }
        });
    }

    /**
     * Get logs for a specific user
     */
    async getLogsByUser(userId: string, startDate?: Date, endDate?: Date) {
        const where: any = { userId };

        if (startDate || endDate) {
            where.timestamp = {};
            if (startDate) where.timestamp.gte = startDate;
            if (endDate) where.timestamp.lte = endDate;
        }

        return await prisma.auditLog.findMany({
            where,
            include: {
                brand: {
                    select: { id: true, name: true }
                }
            },
            orderBy: { timestamp: 'desc' }
        });
    }

    /**
     * Get activity summary for a brand
     */
    async getActivitySummary(brandId: string, days: number = 30): Promise<ActivitySummary> {
        const startDate = new Date();
        startDate.setDate(startDate.getDate() - days);

        const logs = await prisma.auditLog.findMany({
            where: {
                brandId,
                timestamp: { gte: startDate }
            },
            include: {
                user: {
                    select: { id: true, name: true }
                }
            }
        });

        // Count by action type
        const actionsByType: Record<string, number> = {};
        logs.forEach(log => {
            actionsByType[log.action] = (actionsByType[log.action] || 0) + 1;
        });

        // Count by severity
        const actionsBySeverity: Record<string, number> = {};
        logs.forEach(log => {
            actionsBySeverity[log.severity] = (actionsBySeverity[log.severity] || 0) + 1;
        });

        // Top users
        const userCounts: Record<string, { name: string; count: number }> = {};
        logs.forEach(log => {
            if (!userCounts[log.userId]) {
                userCounts[log.userId] = { name: log.userName, count: 0 };
            }
            userCounts[log.userId].count++;
        });

        const topUsers = Object.entries(userCounts)
            .map(([userId, data]) => ({ userId, userName: data.name, count: data.count }))
            .sort((a, b) => b.count - a.count)
            .slice(0, 10);

        // Recent critical events
        const recentCritical = logs
            .filter(log => log.severity === 'CRITICAL' || log.severity === 'SECURITY')
            .slice(0, 10);

        return {
            totalActions: logs.length,
            actionsByType,
            actionsBySeverity,
            topUsers,
            recentCritical
        };
    }

    /**
     * Detect anomalies in audit logs
     */
    async detectAnomalies(brandId: string, hours: number = 24): Promise<Anomaly[]> {
        const anomalies: Anomaly[] = [];
        const startTime = new Date();
        startTime.setHours(startTime.getHours() - hours);

        const logs = await prisma.auditLog.findMany({
            where: {
                brandId,
                timestamp: { gte: startTime }
            },
            orderBy: { timestamp: 'desc' }
        });

        // 1. Detect off-hours activity (10 PM - 6 AM)
        const offHoursLogs = logs.filter(log => {
            const hour = log.timestamp.getHours();
            return hour >= 22 || hour < 6;
        });

        if (offHoursLogs.length > 5) {
            anomalies.push({
                type: 'OFF_HOURS',
                description: `${offHoursLogs.length} actions detected during off-hours (10 PM - 6 AM)`,
                severity: 'WARNING',
                brandId,
                metadata: { count: offHoursLogs.length, actions: offHoursLogs.slice(0, 5) },
                detectedAt: new Date()
            });
        }

        // 2. Detect rapid-fire actions (>10 actions in 1 minute)
        const userActionTimestamps: Record<string, Date[]> = {};
        logs.forEach(log => {
            if (!userActionTimestamps[log.userId]) {
                userActionTimestamps[log.userId] = [];
            }
            userActionTimestamps[log.userId].push(log.timestamp);
        });

        Object.entries(userActionTimestamps).forEach(([userId, timestamps]) => {
            timestamps.sort((a, b) => a.getTime() - b.getTime());
            for (let i = 0; i < timestamps.length - 10; i++) {
                const timeWindow = timestamps[i + 9].getTime() - timestamps[i].getTime();
                if (timeWindow < 60000) { // 1 minute
                    anomalies.push({
                        type: 'RAPID_FIRE',
                        description: `User performed 10+ actions in 1 minute`,
                        severity: 'WARNING',
                        userId,
                        brandId,
                        metadata: { timeWindow, actionCount: 10 },
                        detectedAt: new Date()
                    });
                    break;
                }
            }
        });

        // 3. Detect failed login patterns (if we track login attempts)
        const failedLogins = logs.filter(log =>
            log.action === 'USER_LOGIN' && log.metadata?.success === false
        );

        const failedLoginsByUser: Record<string, number> = {};
        failedLogins.forEach(log => {
            failedLoginsByUser[log.userId] = (failedLoginsByUser[log.userId] || 0) + 1;
        });

        Object.entries(failedLoginsByUser).forEach(([userId, count]) => {
            if (count >= 3) {
                anomalies.push({
                    type: 'FAILED_LOGIN',
                    description: `${count} failed login attempts detected`,
                    severity: 'SECURITY',
                    userId,
                    brandId,
                    metadata: { attemptCount: count },
                    detectedAt: new Date()
                });
            }
        });

        return anomalies;
    }

    /**
     * Export audit logs to CSV
     */
    async exportToCSV(filters: AuditLogFilters = {}): Promise<string> {
        const logs = await this.getLogs(filters);

        const headers = ['Timestamp', 'User', 'Action', 'Entity Type', 'Entity ID', 'Brand', 'Severity', 'IP Address'];
        const rows = logs.map(log => [
            log.timestamp.toISOString(),
            log.userName,
            log.action,
            log.entityType,
            log.entityId,
            log.brand?.name || 'N/A',
            log.severity,
            log.ipAddress || 'N/A'
        ]);

        const csvContent = [
            headers.join(','),
            ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
        ].join('\n');

        return csvContent;
    }

    /**
     * Get audit statistics
     */
    async getStatistics(brandId?: string, days: number = 30) {
        const startDate = new Date();
        startDate.setDate(startDate.getDate() - days);

        const where: any = {
            timestamp: { gte: startDate }
        };

        if (brandId) {
            where.brandId = brandId;
        }

        const [total, bySeverity, byAction] = await Promise.all([
            prisma.auditLog.count({ where }),
            prisma.auditLog.groupBy({
                by: ['severity'],
                where,
                _count: true
            }),
            prisma.auditLog.groupBy({
                by: ['action'],
                where,
                _count: true,
                orderBy: { _count: { action: 'desc' } },
                take: 10
            })
        ]);

        return {
            total,
            bySeverity: bySeverity.reduce((acc, item) => {
                acc[item.severity] = item._count;
                return acc;
            }, {} as Record<string, number>),
            topActions: byAction.map(item => ({
                action: item.action,
                count: item._count
            }))
        };
    }
}

import { prisma } from "@/lib/prisma";
import { getFinancialPulse } from "../intelligence/financeEngine";

export interface BudgetInput {
    brandId: string;
    fiscalYear: number;
    period: 'ANNUAL' | 'QUARTERLY' | 'MONTHLY';
    revenueTarget: number;
    expenseTarget: number;
    profitTarget: number;
    monthlyBreakdowns?: {
        month: number;
        revenueTarget: number;
        expenseTarget: number;
        profitTarget: number;
    }[];
}

export interface VarianceAnalysis {
    brandId: string;
    brandName: string;
    fiscalYear: number;
    period: string;

    revenue: {
        budget: number;
        actual: number;
        variance: number;
        variancePercent: number;
        status: 'good' | 'warning' | 'bad';
    };
    expense: {
        budget: number;
        actual: number;
        variance: number;
        variancePercent: number;
        status: 'good' | 'warning' | 'bad';
    };
    profit: {
        budget: number;
        actual: number;
        variance: number;
        variancePercent: number;
        status: 'good' | 'warning' | 'bad';
    };
}

export interface ForecastAdjustment {
    brandId: string;
    brandName: string;
    currentBudget: {
        revenue: number;
        expense: number;
        profit: number;
    };
    projectedYearEnd: {
        revenue: number;
        expense: number;
        profit: number;
    };
    recommendation: {
        shouldAdjust: boolean;
        reason: string;
        suggestedRevenue?: number;
        suggestedExpense?: number;
        suggestedProfit?: number;
    };
}

export class BudgetService {
    /**
     * Create new budget
     */
    async createBudget(data: BudgetInput) {
        try {
            // Check if budget already exists
            const existing = await prisma.budget.findUnique({
                where: {
                    brandId_fiscalYear_period: {
                        brandId: data.brandId,
                        fiscalYear: data.fiscalYear,
                        period: data.period
                    }
                }
            });

            if (existing) {
                return { success: false, error: 'Budget already exists for this period' };
            }

            const budget = await prisma.budget.create({
                data: {
                    brandId: data.brandId,
                    fiscalYear: data.fiscalYear,
                    period: data.period,
                    revenueTarget: data.revenueTarget,
                    expenseTarget: data.expenseTarget,
                    profitTarget: data.profitTarget,
                    createdBy: 'OWNER',
                    status: 'DRAFT',
                    monthlyBreakdowns: data.monthlyBreakdowns ? {
                        create: data.monthlyBreakdowns
                    } : undefined
                },
                include: {
                    brand: true,
                    monthlyBreakdowns: true
                }
            });

            return { success: true, data: budget };
        } catch (error: any) {
            return { success: false, error: error.message };
        }
    }

    /**
     * Approve budget
     */
    async approveBudget(budgetId: string, approvedBy: string) {
        try {
            const budget = await prisma.budget.update({
                where: { id: budgetId },
                data: {
                    status: 'APPROVED',
                    approvedBy,
                    approvedAt: new Date()
                },
                include: { brand: true }
            });

            return { success: true, data: budget };
        } catch (error: any) {
            return { success: false, error: error.message };
        }
    }

    /**
     * Get variance analysis for a brand
     */
    async getVarianceAnalysis(brandId: string, fiscalYear: number): Promise<VarianceAnalysis | null> {
        try {
            // Get budget
            const budget = await prisma.budget.findFirst({
                where: {
                    brandId,
                    fiscalYear,
                    status: { in: ['APPROVED', 'LOCKED'] }
                },
                include: { brand: true }
            });

            if (!budget) return null;

            // Get actual performance for the year
            const yearStart = new Date(fiscalYear, 0, 1);
            const yearEnd = new Date(fiscalYear, 11, 31);

            const actualData = await getFinancialPulse(brandId);
            const actual = {
                revenue: actualData.monthlyRevenue,
                totalExpenses: actualData.monthlyCOGS + actualData.monthlyLedgerExpenses,
                netProfit: actualData.monthlyNetProfit
            };

            // Calculate variances
            const revenueVariance = actual.revenue - Number(budget.revenueTarget);
            const revenueVariancePercent = (revenueVariance / Number(budget.revenueTarget)) * 100;

            const expenseVariance = actual.totalExpenses - Number(budget.expenseTarget);
            const expenseVariancePercent = (expenseVariance / Number(budget.expenseTarget)) * 100;

            const profitVariance = actual.netProfit - Number(budget.profitTarget);
            const profitVariancePercent = (profitVariance / Number(budget.profitTarget)) * 100;

            return {
                brandId,
                brandName: budget.brand.name,
                fiscalYear,
                period: budget.period,
                revenue: {
                    budget: Number(budget.revenueTarget),
                    actual: actual.revenue,
                    variance: revenueVariance,
                    variancePercent: revenueVariancePercent,
                    status: revenueVariancePercent >= 0 ? 'good' : revenueVariancePercent >= -10 ? 'warning' : 'bad'
                },
                expense: {
                    budget: Number(budget.expenseTarget),
                    actual: actual.totalExpenses,
                    variance: expenseVariance,
                    variancePercent: expenseVariancePercent,
                    status: expenseVariancePercent <= 0 ? 'good' : expenseVariancePercent <= 10 ? 'warning' : 'bad'
                },
                profit: {
                    budget: Number(budget.profitTarget),
                    actual: actual.netProfit,
                    variance: profitVariance,
                    variancePercent: profitVariancePercent,
                    status: profitVariancePercent >= 0 ? 'good' : profitVariancePercent >= -10 ? 'warning' : 'bad'
                }
            };
        } catch (error) {
            console.error('Error in getVarianceAnalysis:', error);
            return null;
        }
    }

    /**
     * Get AI forecast adjustment recommendation
     */
    async getAIForecastAdjustment(brandId: string, fiscalYear: number): Promise<ForecastAdjustment | null> {
        try {
            const budget = await prisma.budget.findFirst({
                where: {
                    brandId,
                    fiscalYear,
                    status: { in: ['APPROVED', 'LOCKED'] }
                },
                include: { brand: true }
            });

            if (!budget) return null;

            // Analyze last 3 months performance
            const now = new Date();
            const threeMonthsAgo = new Date(now.getFullYear(), now.getMonth() - 3, 1);

            const recentData = await getFinancialPulse(brandId);
            const recentPerformance = {
                revenue: recentData.monthlyRevenue,
                totalExpenses: recentData.monthlyCOGS + recentData.monthlyLedgerExpenses,
                netProfit: recentData.monthlyNetProfit
            };

            // Calculate monthly average
            const monthsElapsed = 3;
            const avgMonthlyRevenue = recentPerformance.revenue / monthsElapsed;
            const avgMonthlyExpense = recentPerformance.totalExpenses / monthsElapsed;
            const avgMonthlyProfit = recentPerformance.netProfit / monthsElapsed;

            // Project year-end
            const currentMonth = now.getMonth() + 1;
            const remainingMonths = 12 - currentMonth;

            const projectedRevenue = (avgMonthlyRevenue * currentMonth) + (avgMonthlyRevenue * remainingMonths);
            const projectedExpense = (avgMonthlyExpense * currentMonth) + (avgMonthlyExpense * remainingMonths);
            const projectedProfit = projectedRevenue - projectedExpense;

            // Calculate variance from budget
            const revenueVariancePercent = ((projectedRevenue - Number(budget.revenueTarget)) / Number(budget.revenueTarget)) * 100;
            const expenseVariancePercent = ((projectedExpense - Number(budget.expenseTarget)) / Number(budget.expenseTarget)) * 100;

            // Determine if adjustment is needed (>15% variance)
            const shouldAdjust = Math.abs(revenueVariancePercent) > 15 || Math.abs(expenseVariancePercent) > 15;

            let reason = '';
            if (shouldAdjust) {
                if (revenueVariancePercent > 15) {
                    reason = `Revenue trending ${revenueVariancePercent.toFixed(1)}% above budget. Consider increasing target.`;
                } else if (revenueVariancePercent < -15) {
                    reason = `Revenue trending ${Math.abs(revenueVariancePercent).toFixed(1)}% below budget. Consider reducing target or implementing growth initiatives.`;
                } else if (expenseVariancePercent > 15) {
                    reason = `Expenses trending ${expenseVariancePercent.toFixed(1)}% above budget. Review cost control measures.`;
                }
            } else {
                reason = 'Performance is within acceptable variance. No adjustment needed.';
            }

            return {
                brandId,
                brandName: budget.brand.name,
                currentBudget: {
                    revenue: Number(budget.revenueTarget),
                    expense: Number(budget.expenseTarget),
                    profit: Number(budget.profitTarget)
                },
                projectedYearEnd: {
                    revenue: projectedRevenue,
                    expense: projectedExpense,
                    profit: projectedProfit
                },
                recommendation: {
                    shouldAdjust,
                    reason,
                    suggestedRevenue: shouldAdjust ? projectedRevenue : undefined,
                    suggestedExpense: shouldAdjust ? projectedExpense : undefined,
                    suggestedProfit: shouldAdjust ? projectedProfit : undefined
                }
            };
        } catch (error) {
            console.error('Error in getAIForecastAdjustment:', error);
            return null;
        }
    }

    /**
     * Get budget utilization percentage
     */
    async getBudgetUtilization(brandId: string, fiscalYear: number) {
        try {
            const variance = await this.getVarianceAnalysis(brandId, fiscalYear);
            if (!variance) return null;

            return {
                revenue: (variance.revenue.actual / variance.revenue.budget) * 100,
                expense: (variance.expense.actual / variance.expense.budget) * 100,
                profit: variance.profit.budget !== 0 ? (variance.profit.actual / variance.profit.budget) * 100 : 0
            };
        } catch (error) {
            console.error('Error in getBudgetUtilization:', error);
            return null;
        }
    }

    /**
     * Get all budgets for a brand
     */
    async getBudgetsByBrand(brandId: string) {
        try {
            const budgets = await prisma.budget.findMany({
                where: { brandId },
                include: {
                    brand: true,
                    monthlyBreakdowns: true
                },
                orderBy: { fiscalYear: 'desc' }
            });

            return { success: true, data: budgets };
        } catch (error: any) {
            return { success: false, error: error.message };
        }
    }
}

import { prisma } from '@/lib/prisma';
import { AllocationStatus, RiskLevel } from '@prisma/client';

// ============================================================================
// INTERFACES
// ============================================================================

export interface CashPosition {
    brandId: string;
    brandName: string;
    cash: number;
    runway: number; // months
    burnRate: number; // monthly
    trend: 'INCREASING' | 'STABLE' | 'DECREASING';
}

export interface AllocationRecommendation {
    type: 'IC_LOAN' | 'INVESTMENT' | 'RESERVE' | 'DIVIDEND';
    fromBrand?: string;
    toBrand?: string;
    amount: number;
    reason: string;
    predictedROI: number;
    risk: RiskLevel;
    priority: number; // 1-10
}

export interface CashAnalysis {
    totalCash: number;
    positions: CashPosition[];
    averageRunway: number;
    criticalBrands: string[]; // Brands with <3 months runway
    excessCashBrands: string[]; // Brands with >12 months runway
}

export interface ROIPrediction {
    predicted: number;
    confidence: number;
    factors: {
        historical: number;
        benchmark: number;
        trend: number;
    };
}

export interface ICLoanSuggestion {
    fromBrandId: string;
    fromBrandName: string;
    toBrandId: string;
    toBrandName: string;
    amount: number;
    reason: string;
    urgency: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
}

export interface RiskAssessment {
    score: number; // 0-100
    level: RiskLevel;
    factors: Array<{
        factor: string;
        impact: number; // 0-100
        severity: 'LOW' | 'MEDIUM' | 'HIGH';
    }>;
}

// ============================================================================
// CAPITAL ALLOCATION ENGINE
// ============================================================================

export class CapitalAllocationEngine {
    /**
     * Generate AI-powered capital allocation recommendations
     */
    async generateRecommendations(userId: string): Promise<any> {
        // 1. Analyze current cash positions
        const cashAnalysis = await this.analyzeCashPositions();

        // 2. Generate recommendations
        const recommendations = await this.generateAllocationRecommendations(cashAnalysis);

        // 3. Calculate overall score and risk
        const overallScore = this.calculateOverallScore(recommendations);
        const riskLevel = this.determineRiskLevel(recommendations);

        // 4. Save to database
        const allocation = await prisma.capitalAllocation.create({
            data: {
                totalCashAvailable: cashAnalysis.totalCash,
                brandCashPositions: cashAnalysis.positions,
                recommendations,
                overallScore,
                riskLevel,
                validUntil: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 7 days
                confidence: this.calculateConfidence(cashAnalysis),
                status: 'PENDING'
            }
        });

        return allocation;
    }

    /**
     * Analyze cash positions across all brands
     */
    async analyzeCashPositions(): Promise<CashAnalysis> {
        const brands = await prisma.brand.findMany({
            where: { isActive: true },
            select: {
                id: true,
                name: true
            }
        });

        const positions: CashPosition[] = [];
        let totalCash = 0;

        for (const brand of brands) {
            const position = await this.getBrandCashPosition(brand.id, brand.name);
            positions.push(position);
            totalCash += position.cash;
        }

        const averageRunway = positions.reduce((sum, p) => sum + p.runway, 0) / positions.length;
        const criticalBrands = positions.filter(p => p.runway < 3).map(p => p.brandName);
        const excessCashBrands = positions.filter(p => p.runway > 12).map(p => p.brandName);

        return {
            totalCash,
            positions,
            averageRunway,
            criticalBrands,
            excessCashBrands
        };
    }

    /**
     * Get cash position for a specific brand
     */
    private async getBrandCashPosition(brandId: string, brandName: string): Promise<CashPosition> {
        // Get cash balance from ledger
        const cashAccount = await prisma.ledgerAccount.findFirst({
            where: {
                brandId,
                code: '1000', // Cash account
                isActive: true
            }
        });

        const cash = cashAccount ? Number(cashAccount.balance) : 0;

        // Calculate burn rate (average monthly expenses over last 3 months)
        const threeMonthsAgo = new Date();
        threeMonthsAgo.setMonth(threeMonthsAgo.getMonth() - 3);

        const expenses = await prisma.journalTransaction.aggregate({
            where: {
                brandId,
                date: { gte: threeMonthsAgo },
                status: 'POSTED',
                entries: {
                    some: {
                        account: {
                            type: 'EXPENSE'
                        }
                    }
                }
            },
            _sum: {
                // This is simplified - in production, sum entry amounts
            }
        });

        // Simplified burn rate calculation
        const burnRate = 25_000_000; // Default 25M/month (should calculate from actual data)

        // Calculate runway
        const runway = cash > 0 ? cash / burnRate : 0;

        // Determine trend (simplified)
        const trend: 'INCREASING' | 'STABLE' | 'DECREASING' =
            cash > burnRate * 6 ? 'INCREASING' :
                cash < burnRate * 3 ? 'DECREASING' : 'STABLE';

        return {
            brandId,
            brandName,
            cash,
            runway,
            burnRate,
            trend
        };
    }

    /**
     * Generate allocation recommendations based on cash analysis
     */
    private async generateAllocationRecommendations(
        analysis: CashAnalysis
    ): Promise<AllocationRecommendation[]> {
        const recommendations: AllocationRecommendation[] = [];

        // 1. IC Loan Recommendations (from excess cash brands to critical brands)
        const icLoans = await this.suggestICLoans(analysis);
        recommendations.push(...icLoans.map(loan => ({
            type: 'IC_LOAN' as const,
            fromBrand: loan.fromBrandId,
            toBrand: loan.toBrandId,
            amount: loan.amount,
            reason: loan.reason,
            predictedROI: 15, // Simplified
            risk: loan.urgency === 'CRITICAL' ? 'HIGH' : 'MEDIUM' as RiskLevel,
            priority: loan.urgency === 'CRITICAL' ? 10 : 7
        })));

        // 2. Investment Recommendations (for brands with good ROI potential)
        for (const position of analysis.positions) {
            if (position.runway > 6 && position.runway < 12 && position.trend === 'INCREASING') {
                const roi = await this.predictROI(position.brandId, 50_000_000, 'expansion');

                if (roi.predicted > 20) {
                    recommendations.push({
                        type: 'INVESTMENT',
                        toBrand: position.brandId,
                        amount: 50_000_000,
                        reason: `High growth potential detected. Historical ROI: ${roi.factors.historical.toFixed(1)}%`,
                        predictedROI: roi.predicted,
                        risk: 'MEDIUM',
                        priority: 8
                    });
                }
            }
        }

        // 3. Reserve Recommendations (for brands with low runway)
        for (const position of analysis.positions) {
            if (position.runway < 6) {
                recommendations.push({
                    type: 'RESERVE',
                    toBrand: position.brandId,
                    amount: position.burnRate * 3, // 3 months reserve
                    reason: `Low runway (${position.runway.toFixed(1)} months). Build reserve to 6 months.`,
                    predictedROI: 0,
                    risk: 'LOW',
                    priority: 9
                });
            }
        }

        // Sort by priority (descending)
        return recommendations.sort((a, b) => b.priority - a.priority);
    }

    /**
     * Suggest IC loans between brands
     */
    async suggestICLoans(analysis: CashAnalysis): Promise<ICLoanSuggestion[]> {
        const suggestions: ICLoanSuggestion[] = [];

        const excessBrands = analysis.positions.filter(p => p.runway > 12);
        const needyBrands = analysis.positions.filter(p => p.runway < 3);

        for (const needy of needyBrands) {
            for (const excess of excessBrands) {
                if (needy.brandId === excess.brandId) continue;

                // Calculate optimal loan amount
                const targetRunway = 6; // months
                const needed = (targetRunway - needy.runway) * needy.burnRate;
                const available = (excess.runway - 12) * excess.burnRate;

                if (available > 0 && needed > 0) {
                    const loanAmount = Math.min(needed, available);

                    suggestions.push({
                        fromBrandId: excess.brandId,
                        fromBrandName: excess.brandName,
                        toBrandId: needy.brandId,
                        toBrandName: needy.brandName,
                        amount: loanAmount,
                        reason: `${needy.brandName} has only ${needy.runway.toFixed(1)} months runway. ${excess.brandName} has excess cash (${excess.runway.toFixed(1)} months).`,
                        urgency: needy.runway < 2 ? 'CRITICAL' : needy.runway < 3 ? 'HIGH' : 'MEDIUM'
                    });
                }
            }
        }

        return suggestions;
