     */
    private calculateOverallScore(recommendations: AllocationRecommendation[]): number {
        if (recommendations.length === 0) return 0;

        const avgROI = recommendations.reduce((sum, r) => sum + r.predictedROI, 0) / recommendations.length;
        const avgPriority = recommendations.reduce((sum, r) => sum + r.priority, 0) / recommendations.length;

        // Score = (ROI * 0.6) + (Priority * 0.4)
        return Math.min(100, (avgROI * 0.6) + (avgPriority * 4));
    }

    /**
     * Determine overall risk level
     */
    private determineRiskLevel(recommendations: AllocationRecommendation[]): RiskLevel {
        const highRiskCount = recommendations.filter(r => r.risk === 'HIGH' || r.risk === 'CRITICAL').length;
        const totalCount = recommendations.length;

        if (totalCount === 0) return 'LOW';

        const riskRatio = highRiskCount / totalCount;

        if (riskRatio > 0.5) return 'HIGH';
        if (riskRatio > 0.25) return 'MEDIUM';
        return 'LOW';
    }

    /**
     * Calculate confidence score
     */
    private calculateConfidence(analysis: CashAnalysis): number {
        // Higher confidence if we have more data points
        const brandCount = analysis.positions.length;
        const baseConfidence = 60;
        const brandBonus = Math.min(30, brandCount * 10);

        return baseConfidence + brandBonus;
    }

    /**
     * Assess risk for a specific allocation
     */
    async assessRisk(allocation: AllocationRecommendation): Promise<RiskAssessment> {
        const factors = [];

        // Factor 1: Amount risk
        if (allocation.amount > 100_000_000) {
            factors.push({
                factor: 'Large allocation amount',
                impact: 70,
                severity: 'HIGH' as const
            });
        }

        // Factor 2: ROI uncertainty
        if (allocation.predictedROI < 10) {
            factors.push({
                factor: 'Low predicted ROI',
                impact: 50,
                severity: 'MEDIUM' as const
            });
        }

        // Factor 3: Type risk
        if (allocation.type === 'INVESTMENT') {
            factors.push({
                factor: 'Investment carries execution risk',
                impact: 40,
                severity: 'MEDIUM' as const
            });
        }

        const avgImpact = factors.length > 0
            ? factors.reduce((sum, f) => sum + f.impact, 0) / factors.length
            : 20;

        const level: RiskLevel =
            avgImpact > 70 ? 'HIGH' :
                avgImpact > 40 ? 'MEDIUM' : 'LOW';

        return {
            score: avgImpact,
            level,
            factors
        };
    }
}

import { prisma } from '@/lib/prisma';

// ============================================================================
// INTERFACES
// ============================================================================

export interface HistoricalCashFlow {
    date: Date;
    inflow: number;
    outflow: number;
    balance: number;
}

export interface HistoricalAnalysis {
    data: HistoricalCashFlow[];
    trend: TrendAnalysis;
    seasonality: SeasonalityPattern;
    volatility: number;
}

export interface TrendAnalysis {
    slope: number; // Growth rate per month
    intercept: number; // Baseline
    r2: number; // Goodness of fit (0-1)
}

export interface SeasonalityPattern {
    monthlyMultipliers: Record<number, number>; // 1-12
    hasSeasonality: boolean;
}

export interface CashFlowPrediction {
    date: Date;
    predictedInflow: number;
    predictedOutflow: number;
    predictedBalance: number;
    confidence: number;
    bestCase: number;
    worstCase: number;
    mostLikely: number;
    factors: {
        seasonality: number;
        trend: number;
        volatility: number;
    };
}

export interface AccuracyMetrics {
    mape: number; // Mean Absolute Percentage Error
    rmse: number; // Root Mean Square Error
    accuracy: number; // 100 - MAPE
}

// ============================================================================
// CASH FLOW FORECAST ENGINE
// ============================================================================

export class CashFlowForecastEngine {
    /**
     * Generate forecast for multiple months
     */
    async generateForecast(
        brandId: string,
        months: number = 12
    ): Promise<CashFlowPrediction[]> {
        // 1. Analyze historical data
        const analysis = await this.analyzeHistoricalCashFlow(brandId, 12);

        // 2. Generate predictions for each month
        const predictions: CashFlowPrediction[] = [];
        const today = new Date();

        for (let i = 1; i <= months; i++) {
            const targetDate = new Date(today);
            targetDate.setMonth(targetDate.getMonth() + i);

            const prediction = await this.predictCashFlow(brandId, targetDate, analysis);
            predictions.push(prediction);

            // Save to database
            await this.saveForecast(brandId, prediction);
        }

        return predictions;
    }

    /**
     * Analyze historical cash flow data
     */
    async analyzeHistoricalCashFlow(
        brandId: string,
        months: number = 12
    ): Promise<HistoricalAnalysis> {
        const startDate = new Date();
        startDate.setMonth(startDate.getMonth() - months);

        // Get historical journal transactions
        const transactions = await prisma.journalTransaction.findMany({
            where: {
                brandId,
                date: { gte: startDate },
            },
            include: {
                entries: {
                    include: {
                        account: true
                    }
                }
            },
            orderBy: { date: 'asc' }
        }) as any[];

        // Group by month
        const monthlyData: Record<string, { inflow: number; outflow: number }> = {};

        for (const tx of transactions) {
            const monthKey = `${tx.date.getFullYear()}-${String(tx.date.getMonth() + 1).padStart(2, '0')}`;

            if (!monthlyData[monthKey]) {
                monthlyData[monthKey] = { inflow: 0, outflow: 0 };
            }

            for (const entry of tx.entries) {
                const debit = Number(entry.debit);
                const credit = Number(entry.credit);

                // Inflow: Revenue (Credit) or Cash increase (Debit to account code 1000)
                if (entry.account.type === 'REVENUE') {
                    monthlyData[monthKey].inflow += credit;
                } else if (entry.account.code === '1000' && debit > 0) {
                    monthlyData[monthKey].inflow += debit;
                }

                // Outflow: Expense (Debit) or Cash decrease (Credit from account code 1000)
                if (entry.account.type === 'EXPENSE') {
                    monthlyData[monthKey].outflow += debit;
                } else if (entry.account.code === '1000' && credit > 0) {
                    monthlyData[monthKey].outflow += credit;
                }
            }
        }

        // Convert to array
        const data: HistoricalCashFlow[] = Object.entries(monthlyData).map(([key, value]) => {
            const [year, month] = key.split('-').map(Number);
            return {
                date: new Date(year, month - 1, 1),
                inflow: value.inflow,
                outflow: value.outflow,
                balance: value.inflow - value.outflow
            };
        });

        // Calculate trend
        const trend = this.calculateTrend(data);

        // Detect seasonality
        const seasonality = this.detectSeasonality(data);

        // Calculate volatility
        const volatility = this.calculateVolatility(data);

        return {
            data,
            trend,
            seasonality,
            volatility
        };
    }

    /**
     * Predict cash flow for a specific date
     */
    async predictCashFlow(
        brandId: string,
        targetDate: Date,
        analysis?: HistoricalAnalysis
    ): Promise<CashFlowPrediction> {
        // Get analysis if not provided
        if (!analysis) {
            analysis = await this.analyzeHistoricalCashFlow(brandId, 12);
        }

        const monthsAhead = this.getMonthsDifference(new Date(), targetDate);
        const targetMonth = targetDate.getMonth() + 1; // 1-12

        // Base prediction using trend
        const trendInflow = analysis.trend.intercept + (analysis.trend.slope * monthsAhead);

        // Apply seasonality
        const seasonalMultiplier = analysis.seasonality.monthlyMultipliers[targetMonth] || 1.0;
        const predictedInflow = trendInflow * seasonalMultiplier;

        // Predict outflow (simplified - assume 70% of inflow)
        const avgInflowOutflowRatio = this.calculateAvgInflowOutflowRatio(analysis.data);
        const predictedOutflow = predictedInflow * avgInflowOutflowRatio;

        // Predicted balance
        const predictedBalance = predictedInflow - predictedOutflow;

        // Calculate confidence (based on R² and volatility)
        const confidence = Math.max(0, Math.min(100,
            (analysis.trend.r2 * 100) - (analysis.volatility * 10)
        ));

        // Generate scenarios
        const volatilityFactor = analysis.volatility / 100;
        const bestCase = predictedBalance * (1 + volatilityFactor * 1.5);
        const worstCase = predictedBalance * (1 - volatilityFactor * 1.5);
        const mostLikely = predictedBalance;

        return {
            date: targetDate,
            predictedInflow,
            predictedOutflow,
            predictedBalance,
            confidence,
            bestCase,
            worstCase,
            mostLikely,
            factors: {
                seasonality: seasonalMultiplier,
                trend: analysis.trend.slope,
                volatility: analysis.volatility
            }
        };
    }

    /**
     * Calculate trend using linear regression
     */
    private calculateTrend(data: HistoricalCashFlow[]): TrendAnalysis {
        if (data.length < 2) {
            return { slope: 0, intercept: 0, r2: 0 };
        }

        const n = data.length;
        const x = data.map((_, i) => i); // 0, 1, 2, ...
        const y = data.map(d => d.inflow);

        // Calculate means
        const xMean = x.reduce((sum, val) => sum + val, 0) / n;
        const yMean = y.reduce((sum, val) => sum + val, 0) / n;

        // Calculate slope and intercept
        let numerator = 0;
        let denominator = 0;

        for (let i = 0; i < n; i++) {
            numerator += (x[i] - xMean) * (y[i] - yMean);
            denominator += Math.pow(x[i] - xMean, 2);
        }

        const slope = denominator !== 0 ? numerator / denominator : 0;
        const intercept = yMean - (slope * xMean);

        // Calculate R² (goodness of fit)
        let ssRes = 0;
        let ssTot = 0;

        for (let i = 0; i < n; i++) {
            const predicted = intercept + (slope * x[i]);
            ssRes += Math.pow(y[i] - predicted, 2);
            ssTot += Math.pow(y[i] - yMean, 2);
        }

        const r2 = ssTot !== 0 ? 1 - (ssRes / ssTot) : 0;

        return {
            slope,
            intercept,
            r2: Math.max(0, Math.min(1, r2))
        };
    }

    /**
     * Detect seasonality patterns
     */
    private detectSeasonality(data: HistoricalCashFlow[]): SeasonalityPattern {
        const monthlyAverages: Record<number, number[]> = {};

        // Group by month
        for (const item of data) {
            const month = item.date.getMonth() + 1; // 1-12
            if (!monthlyAverages[month]) {
                monthlyAverages[month] = [];
            }
            monthlyAverages[month].push(item.inflow);
        }

        // Calculate average for each month
        const monthlyMultipliers: Record<number, number> = {};
        const overallAvg = data.reduce((sum, d) => sum + d.inflow, 0) / data.length;

        for (let month = 1; month <= 12; month++) {
            if (monthlyAverages[month] && monthlyAverages[month].length > 0) {
                const monthAvg = monthlyAverages[month].reduce((sum, val) => sum + val, 0) / monthlyAverages[month].length;
                monthlyMultipliers[month] = overallAvg > 0 ? monthAvg / overallAvg : 1.0;
            } else {
                monthlyMultipliers[month] = 1.0;
            }
        }

        // Check if there's significant seasonality (variance > 10%)
        const multiplierValues = Object.values(monthlyMultipliers);
        const maxMultiplier = Math.max(...multiplierValues);
        const minMultiplier = Math.min(...multiplierValues);
        const hasSeasonality = (maxMultiplier - minMultiplier) > 0.1;

        return {
            monthlyMultipliers,
            hasSeasonality
        };
    }

    /**
     * Calculate volatility (standard deviation / mean)
     */
    private calculateVolatility(data: HistoricalCashFlow[]): number {
        if (data.length < 2) return 0;

        const balances = data.map(d => d.balance);
        const mean = balances.reduce((sum, val) => sum + val, 0) / balances.length;

        const variance = balances.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) / balances.length;
        const stdDev = Math.sqrt(variance);

        return mean !== 0 ? (stdDev / Math.abs(mean)) * 100 : 0;
    }

    /**
     * Calculate average inflow/outflow ratio
     */
    private calculateAvgInflowOutflowRatio(data: HistoricalCashFlow[]): number {
        if (data.length === 0) return 0.7; // Default 70%

        const ratios = data
            .filter(d => d.inflow > 0)
            .map(d => d.outflow / d.inflow);

        return ratios.length > 0
            ? ratios.reduce((sum, val) => sum + val, 0) / ratios.length
            : 0.7;
    }

    /**
     * Get months difference between two dates
     */
    private getMonthsDifference(date1: Date, date2: Date): number {
        return (date2.getFullYear() - date1.getFullYear()) * 12 +
            (date2.getMonth() - date1.getMonth());
    }

    /**
     * Save forecast to database
     */
    private async saveForecast(brandId: string, prediction: CashFlowPrediction): Promise<void> {
        await prisma.cashFlowForecast.upsert({
            where: {
                brandId_forecastDate: {
                    brandId,
                    forecastDate: prediction.date
                }
            },
            create: {
                brandId,
                forecastDate: prediction.date,
                predictedInflow: prediction.predictedInflow,
                predictedOutflow: prediction.predictedOutflow,
                predictedBalance: prediction.predictedBalance,
                confidence: prediction.confidence,
                bestCase: prediction.bestCase,
                worstCase: prediction.worstCase,
                mostLikely: prediction.mostLikely,
                factors: prediction.factors
            },
            update: {
                predictedInflow: prediction.predictedInflow,
                predictedOutflow: prediction.predictedOutflow,
                predictedBalance: prediction.predictedBalance,
                confidence: prediction.confidence,
                bestCase: prediction.bestCase,
                worstCase: prediction.worstCase,
                mostLikely: prediction.mostLikely,
                factors: prediction.factors,
                generatedAt: new Date()
            }
        });
    }

    /**
     * Calculate forecast accuracy (compare prediction vs actual)
     */
    async calculateAccuracy(brandId: string): Promise<AccuracyMetrics> {
        // Get forecasts from last month
        const lastMonth = new Date();
        lastMonth.setMonth(lastMonth.getMonth() - 1);

        const forecasts = await prisma.cashFlowForecast.findMany({
            where: {
                brandId,
                forecastDate: {
                    gte: lastMonth,
                    lte: new Date()
                }
            }
        });

        if (forecasts.length === 0) {
            return { mape: 0, rmse: 0, accuracy: 0 };
        }

        // Get actual data (simplified - would need actual implementation)
        // For now, return placeholder
        return {
            mape: 15, // 15% error
            rmse: 5000000, // 5M RMSE
            accuracy: 85 // 85% accuracy
        };
    }
}

import { prisma } from '@/lib/prisma';
import { ComplianceCategory, RuleType, ComplianceSeverity, ViolationStatus } from '@prisma/client';

export interface ComplianceRuleInput {
    name: string;
    description: string;
    category: ComplianceCategory;
    ruleType: RuleType;
    conditions: any; // JSON rule logic
    severity: ComplianceSeverity;
    brandId?: string; // null = applies to all brands
}

export interface ViolationInput {
    ruleId: string;
    brandId?: string;
    userId?: string;
    entityType: string;
    entityId: string;
    description: string;
    severity: ComplianceSeverity;
}

export interface ViolationFilters {
    brandId?: string;
    userId?: string;
    ruleId?: string;
    status?: ViolationStatus;
    severity?: ComplianceSeverity;
    startDate?: Date;
    endDate?: Date;
}

export interface ComplianceDashboard {
    overallScore: number; // 0-100
    totalRules: number;
    activeRules: number;
    totalViolations: number;
    openViolations: number;
    criticalViolations: number;
    violationsByCategory: Record<string, number>;
    recentViolations: any[];
    trend: 'IMPROVING' | 'STABLE' | 'DECLINING';
}

export class ComplianceService {
    /**
     * Create a new compliance rule
     */
    async createRule(input: ComplianceRuleInput) {
        return await prisma.complianceRule.create({
            data: {
                name: input.name,
                description: input.description,
                category: input.category,
                ruleType: input.ruleType,
                conditions: input.conditions,
                severity: input.severity,
                brandId: input.brandId,
                isActive: true
            }
        });
    }

    /**
     * Get all rules (optionally filtered by brand)
     */
    async getRules(brandId?: string, activeOnly: boolean = true) {
        const where: any = {};

        if (brandId) {
            where.OR = [
                { brandId },
                { brandId: null } // Global rules
            ];
        }

        if (activeOnly) {
            where.isActive = true;
        }

        return await prisma.complianceRule.findMany({
            where,
            include: {
                brand: {
                    select: { id: true, name: true }
                },
                violations: {
                    where: { status: 'OPEN' },
                    take: 5
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Evaluate a rule against context
     */
    async evaluateRule(ruleId: string, context: any): Promise<boolean> {
        const rule = await prisma.complianceRule.findUnique({
            where: { id: ruleId }
        });

        if (!rule || !rule.isActive) {
            return true; // Pass if rule doesn't exist or is inactive
        }

        const conditions = rule.conditions as any;

        // Evaluate based on rule type
        switch (rule.ruleType) {
            case 'THRESHOLD':
                return this.evaluateThreshold(conditions, context);

            case 'MANDATORY_FIELD':
                return this.evaluateMandatoryField(conditions, context);

            case 'WORKFLOW':
                return this.evaluateWorkflow(conditions, context);

            case 'TIMING':
                return this.evaluateTiming(conditions, context);

            case 'SEGREGATION':
                return this.evaluateSegregation(conditions, context);

            case 'LIMIT':
                return this.evaluateLimit(conditions, context);

            default:
                return true;
        }
    }

    /**
     * Record a compliance violation
     */
    async recordViolation(input: ViolationInput) {
        return await prisma.complianceViolation.create({
            data: {
                ruleId: input.ruleId,
                brandId: input.brandId,
                userId: input.userId,
                entityType: input.entityType,
                entityId: input.entityId,
                description: input.description,
                severity: input.severity,
                status: 'OPEN'
            },
            include: {
                rule: true,
                brand: true,
                user: true
            }
        });
    }

    /**
     * Get violations with filters
     */
    async getViolations(filters: ViolationFilters = {}) {
        const where: any = {};

        if (filters.brandId) where.brandId = filters.brandId;
        if (filters.userId) where.userId = filters.userId;
        if (filters.ruleId) where.ruleId = filters.ruleId;
        if (filters.status) where.status = filters.status;
        if (filters.severity) where.severity = filters.severity;

        if (filters.startDate || filters.endDate) {
            where.createdAt = {};
            if (filters.startDate) where.createdAt.gte = filters.startDate;
            if (filters.endDate) where.createdAt.lte = filters.endDate;
        }

        return await prisma.complianceViolation.findMany({
            where,
            include: {
                rule: true,
                brand: {
                    select: { id: true, name: true }
                },
                user: {
                    select: { id: true, name: true, email: true }
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Resolve a violation
     */
    async resolveViolation(violationId: string, resolvedBy: string, resolution: string) {
        return await prisma.complianceViolation.update({
            where: { id: violationId },
            data: {
                status: 'RESOLVED',
                resolvedBy,
                resolvedAt: new Date(),
                resolution
            }
        });
    }

    /**
     * Waive a violation
     */
    async waiveViolation(violationId: string, resolvedBy: string, reason: string) {
        return await prisma.complianceViolation.update({
            where: { id: violationId },
            data: {
                status: 'WAIVED',
                resolvedBy,
                resolvedAt: new Date(),
                resolution: `WAIVED: ${reason}`
            }
        });
    }

    /**
     * Calculate compliance score for a brand
     */
    async getComplianceScore(brandId: string, days: number = 30): Promise<number> {
        const startDate = new Date();
        startDate.setDate(startDate.getDate() - days);

        // Get total applicable rules
        const totalRules = await prisma.complianceRule.count({
            where: {
                isActive: true,
                OR: [
                    { brandId },
                    { brandId: null }
                ]
            }
        });

        if (totalRules === 0) return 100;

        // Get violations in period
        const violations = await prisma.complianceViolation.count({
            where: {
                brandId,
                createdAt: { gte: startDate },
                status: { in: ['OPEN', 'INVESTIGATING'] }
            }
        });

        // Score calculation: 100 - (violations / rules * weight)
        // Weight violations by severity
        const violationsBySeverity = await prisma.complianceViolation.groupBy({
            by: ['severity'],
            where: {
                brandId,
                createdAt: { gte: startDate },
                status: { in: ['OPEN', 'INVESTIGATING'] }
            },
            _count: true
        });

        let weightedViolations = 0;
        violationsBySeverity.forEach(v => {
            const weight = v.severity === 'CRITICAL' ? 10 :
                v.severity === 'HIGH' ? 5 :
                    v.severity === 'MEDIUM' ? 2 : 1;
            weightedViolations += v._count * weight;
        });

        const score = Math.max(0, 100 - (weightedViolations / totalRules * 10));
        return Math.round(score);
    }

    /**
     * Get compliance dashboard data
     */
    async getComplianceDashboard(brandId?: string): Promise<ComplianceDashboard> {
        const where: any = {};
        if (brandId) {
            where.OR = [
                { brandId },
                { brandId: null }
            ];
        }

        const [totalRules, activeRules, violations] = await Promise.all([
            prisma.complianceRule.count({ where }),
            prisma.complianceRule.count({ where: { ...where, isActive: true } }),
            prisma.complianceViolation.findMany({
                where: brandId ? { brandId } : {},
                include: {
                    rule: {
                        select: { category: true }
                    }
                }
            })
        ]);

        const openViolations = violations.filter(v => v.status === 'OPEN' || v.status === 'INVESTIGATING').length;
        const criticalViolations = violations.filter(v => v.severity === 'CRITICAL' && v.status === 'OPEN').length;

        // Group by category
        const violationsByCategory: Record<string, number> = {};
        violations.forEach(v => {
            const category = v.rule.category;
            violationsByCategory[category] = (violationsByCategory[category] || 0) + 1;
        });

        // Recent violations
        const recentViolations = violations
            .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())
            .slice(0, 10);

        // Calculate trend (compare last 7 days vs previous 7 days)
        const now = new Date();
        const last7Days = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        const prev7Days = new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000);

        const recentCount = violations.filter(v => v.createdAt >= last7Days).length;
        const previousCount = violations.filter(v => v.createdAt >= prev7Days && v.createdAt < last7Days).length;

        let trend: 'IMPROVING' | 'STABLE' | 'DECLINING';
        if (recentCount < previousCount * 0.8) trend = 'IMPROVING';
        else if (recentCount > previousCount * 1.2) trend = 'DECLINING';
        else trend = 'STABLE';

        const overallScore = brandId ? await this.getComplianceScore(brandId) : 100;

        return {
            overallScore,
            totalRules,
            activeRules,
            totalViolations: violations.length,
            openViolations,
            criticalViolations,
            violationsByCategory,
            recentViolations,
            trend
        };
    }

    /**
     * Initialize default compliance rules
     */
    async initializeDefaultRules(brandId?: string) {
        const defaultRules: ComplianceRuleInput[] = [
            {
                name: 'Approval Threshold - High Value Expenses',
                description: 'Expenses over Rp 5,000,000 require manager approval',
                category: 'APPROVAL_WORKFLOW',
                ruleType: 'THRESHOLD',
                conditions: {
                    field: 'amount',
                    operator: '>',
                    value: 5000000,
                    requiresApproval: true
                },
                severity: 'HIGH',
                brandId
            },
            {
                name: 'Segregation of Duties - IC Transactions',
                description: 'Creator and approver must be different people for IC transactions',
                category: 'APPROVAL_WORKFLOW',
                ruleType: 'SEGREGATION',
                conditions: {
                    entityType: 'ICTransaction',
                    creatorField: 'createdBy',
                    approverField: 'approvedBy',
                    mustDiffer: true
                },
                severity: 'CRITICAL',
                brandId
            },
            {
                name: 'Budget Compliance - Expense Limit',
                description: 'Actual expenses cannot exceed budget by more than 20%',
                category: 'FINANCIAL_POLICY',
                ruleType: 'THRESHOLD',
                conditions: {
                    field: 'expenseVariance',
                    operator: '<=',
                    value: 20,
                    unit: 'percent'
                },
                severity: 'HIGH',
                brandId
            },
            {
                name: 'Timely Month-End Close',
                description: 'Month-end journal entries must be posted by 5th of next month',
                category: 'OPERATIONAL',
                ruleType: 'TIMING',
                conditions: {
                    entityType: 'JournalEntry',
                    deadline: 5,
                    deadlineType: 'dayOfMonth'
                },
                severity: 'MEDIUM',
                brandId
            },
            {
                name: 'Invoice Documentation',
                description: 'All invoices over Rp 1,000,000 must have supporting documents',
                category: 'DATA_INTEGRITY',
                ruleType: 'MANDATORY_FIELD',
                conditions: {
                    entityType: 'Invoice',
                    amountThreshold: 1000000,
                    requiredField: 'attachments',
                    minCount: 1
                },
                severity: 'MEDIUM',
                brandId
            }
        ];

        const created = [];
        for (const rule of defaultRules) {
            try {
                const existing = await prisma.complianceRule.findFirst({
                    where: {
                        name: rule.name,
                        brandId: rule.brandId
                    }
                });

                if (!existing) {
                    const newRule = await this.createRule(rule);
                    created.push(newRule);
                }
            } catch (error) {
                console.error(`Failed to create rule: ${rule.name}`, error);
            }
        }

        return created;
    }

    // Private evaluation methods
    private evaluateThreshold(conditions: any, context: any): boolean {
        const value = context[conditions.field];
        const threshold = conditions.value;

        switch (conditions.operator) {
            case '>': return value <= threshold;
            case '>=': return value < threshold;
            case '<': return value >= threshold;
            case '<=': return value > threshold;
            case '==': return value === threshold;
            default: return true;
        }
    }

    private evaluateMandatoryField(conditions: any, context: any): boolean {
        const field = context[conditions.requiredField];
        if (conditions.minCount) {
            return Array.isArray(field) && field.length >= conditions.minCount;
        }
        return field !== null && field !== undefined && field !== '';
    }

    private evaluateWorkflow(conditions: any, context: any): boolean {
        // Check if required approvals are in place
        if (conditions.requiresApproval) {
            return context.approvedBy !== null && context.approvedBy !== undefined;
        }
        return true;
    }

    private evaluateTiming(conditions: any, context: any): boolean {
        const now = new Date();
        const deadline = new Date(now.getFullYear(), now.getMonth(), conditions.deadline);
        return context.createdAt <= deadline;
    }

    private evaluateSegregation(conditions: any, context: any): boolean {
        if (conditions.mustDiffer) {
            const creator = context[conditions.creatorField];
            const approver = context[conditions.approverField];
            return creator !== approver;
        }
        return true;
    }

    private evaluateLimit(conditions: any, context: any): boolean {
        const count = context[conditions.countField] || 0;
        return count < conditions.maxCount;
    }
}

import { prisma } from "@/lib/prisma";

type BrandFeatures = {
    loyalty: boolean;
    ads: boolean;
    subscriptions: boolean;
    blog: boolean;
};

type LoyaltyConfig = {
    earnRate: number;      // e.g. 0.001
    expiryDays: number;
    tiers: { name: string; threshold: number; multiplier: number }[];
};

const DEFAULT_LOYALTY: LoyaltyConfig = {
    earnRate: 0.001,
    expiryDays: 365,
    tiers: [
        { name: 'BRONZE', threshold: 0, multiplier: 1.0 },
        { name: 'SILVER', threshold: 1000, multiplier: 1.2 },
        { name: 'GOLD', threshold: 5000, multiplier: 1.5 }
    ]
};

export class ConfigService {

    /**
     * Get Full Configuration for a Brand
     * Caches should be implemented here in production (Redis/Memory)
     */
    async getConfig(brandId: string) {
        const config = await prisma.brandConfig.findUnique({
            where: { brandId }
        });

        return config;
    }

    /**
     * Check if a feature is enabled
     */
    async isFeatureEnabled(brandId: string, feature: keyof BrandFeatures): Promise<boolean> {
        const config = await this.getConfig(brandId);
        if (!config || !config.features) return false;

        const features = config.features as BrandFeatures;
        return !!features[feature];
    }

    /**
     * Get Loyalty Rules with Defaults
     */
    async getLoyaltyRules(brandId: string): Promise<LoyaltyConfig> {
        const config = await this.getConfig(brandId);
        if (!config || !config.loyaltyRules) return DEFAULT_LOYALTY;

        // Merge with defaults to ensure safety
        return { ...DEFAULT_LOYALTY, ...(config.loyaltyRules as any) };
    }

    /**
     * Get Pricing Strategy
     */
    async getPricingStrategy(brandId: string): Promise<string> {
        const config = await this.getConfig(brandId);
        return config?.pricingStrategy || "STANDARD";
    }
}

import { prisma } from '@/lib/prisma';
import { ConsolidationPeriod, ConsolidationStatus } from '@prisma/client';
import { InterCompanyService } from './InterCompanyService';

// Type Definitions
export interface ConsolidatedPL {
    totalRevenue: number;
    totalCOGS: number;
    totalExpenses: number;
    grossProfit: number;
    netProfit: number;
    byBrand: BrandPL[];
}

export interface BrandPL {
    brandId: string;
    brandName: string;
    revenue: number;
    cogs: number;
    expenses: number;
    netProfit: number;
}

export interface ConsolidatedBS {
    totalAssets: number;
    totalLiabilities: number;
    totalEquity: number;
    byBrand: BrandBS[];
}

export interface BrandBS {
    brandId: string;
    brandName: string;
    assets: number;
    liabilities: number;
    equity: number;
}

export interface ConsolidatedCF {
    operatingCashFlow: number;
    investingCashFlow: number;
    financingCashFlow: number;
    netCashFlow: number;
    byBrand: BrandCF[];
}

export interface BrandCF {
    brandId: string;
    brandName: string;
    operating: number;
    investing: number;
    financing: number;
}

export interface ICElimination {
    fromBrandId: string;
    toBrandId: string;
    amount: number;
    type: string;
    description: string;
}

export interface ValidationResult {
    isValid: boolean;
    errors: string[];
    warnings: string[];
}

export class ConsolidationEngine {
    private icService: InterCompanyService;

    constructor() {
        this.icService = new InterCompanyService();
    }

    /**
     * Main consolidation method - generates complete consolidated statement
     */
    async generateConsolidatedStatement(
        fiscalYear: number,
        period: ConsolidationPeriod,
        executedBy: string
    ) {
        // Create consolidation log
        const log = await prisma.consolidationLog.create({
            data: {
                fiscalYear,
                period,
                status: 'RUNNING',
                brandsProcessed: 0,
                icEliminated: 0,
                executedBy
            }
        });

        try {
            // Calculate date range
            const { startDate, endDate } = this.getDateRange(fiscalYear, period);

            // Get all active brands
            const brands = await prisma.brand.findMany({
                where: { isActive: true }
            });

            // Consolidate P&L
            const pl = await this.consolidateProfitAndLoss(brands, startDate, endDate);

            // Consolidate Balance Sheet
            const bs = await this.consolidateBalanceSheet(brands, endDate);

            // Consolidate Cash Flow
            const cf = await this.consolidateCashFlow(brands, startDate, endDate);

            // Get IC eliminations
            const icTransactions = await this.icService.getICTransactionsForPeriod(
                startDate,
                endDate
            );
            const icEliminations = await this.eliminateInterCompanyTransactions(icTransactions);

            // Calculate IC elimination amount
            const icEliminationAmount = icEliminations.reduce((sum, e) => sum + e.amount, 0);

            // Create consolidated statement
            const statement = await prisma.consolidatedStatement.create({
                data: {
                    fiscalYear,
                    period,
                    startDate,
                    endDate,

                    // P&L
                    totalRevenue: pl.totalRevenue,
                    totalCOGS: pl.totalCOGS,
                    totalExpenses: pl.totalExpenses,
                    netProfit: pl.netProfit,

                    // BS
                    totalAssets: bs.totalAssets,
                    totalLiabilities: bs.totalLiabilities,
                    totalEquity: bs.totalEquity,

                    // CF
                    operatingCashFlow: cf.operatingCashFlow,
                    investingCashFlow: cf.investingCashFlow,
                    financingCashFlow: cf.financingCashFlow,

                    // IC
                    icEliminationAmount,
                    icTransactionCount: icEliminations.length,

                    // Details
                    plDetails: pl,
                    bsDetails: bs,
                    cfDetails: cf,
                    icEliminations: icEliminations,

                    generatedBy: executedBy
                }
            });

            // Update log
            await prisma.consolidationLog.update({
                where: { id: log.id },
                data: {
                    status: 'COMPLETED',
                    completedAt: new Date(),
                    brandsProcessed: brands.length,
                    icEliminated: icEliminations.length,
                    statementId: statement.id
                }
            });

            return statement;
        } catch (error: any) {
            // Update log with error
            await prisma.consolidationLog.update({
                where: { id: log.id },
                data: {
                    status: 'FAILED',
                    completedAt: new Date(),
                    errors: { message: error.message, stack: error.stack }
                }
            });
            throw error;
        }
    }

    /**
     * Consolidate Profit & Loss across all brands
     */
    async consolidateProfitAndLoss(
        brands: any[],
        startDate: Date,
        endDate: Date
    ): Promise<ConsolidatedPL> {
        const brandPLs: BrandPL[] = [];
        let totalRevenue = 0;
        let totalCOGS = 0;
        let totalExpenses = 0;

        for (const brand of brands) {
            // Get journal entries for this brand in period
            const journals = await prisma.journalTransaction.findMany({
                where: {
                    brandId: brand.id,
                    date: {
                        gte: startDate,
                        lte: endDate
                    },
                    status: 'POSTED'
                },
                include: {
                    entries: {
                        include: {
                            account: true
                        }
                    }
                }
            });

            // Calculate P&L for this brand
            let revenue = 0;
            let cogs = 0;
            let expenses = 0;

            for (const journal of journals) {
                for (const entry of journal.entries) {
                    const amount = Number(entry.amount);
                    const accountType = entry.account.type;

                    if (accountType === 'REVENUE') {
                        revenue += entry.type === 'CREDIT' ? amount : -amount;
                    } else if (accountType === 'COGS') {
                        cogs += entry.type === 'DEBIT' ? amount : -amount;
                    } else if (accountType === 'EXPENSE') {
                        expenses += entry.type === 'DEBIT' ? amount : -amount;
                    }
                }
            }

            const netProfit = revenue - cogs - expenses;

            brandPLs.push({
                brandId: brand.id,
                brandName: brand.name,
                revenue,
                cogs,
                expenses,
                netProfit
            });

            totalRevenue += revenue;
            totalCOGS += cogs;
            totalExpenses += expenses;
        }

        // Get IC transactions to eliminate
        const icTransactions = await this.icService.getICTransactionsForPeriod(startDate, endDate);

        // Eliminate IC revenue/expenses
        for (const ic of icTransactions) {
            if (ic.type === 'SERVICE_FEE' || ic.type === 'MATERIAL_TRANSFER') {
                const amount = Number(ic.amount);
                totalRevenue -= amount; // Remove IC revenue
                totalExpenses -= amount; // Remove IC expense
            }
        }

        const grossProfit = totalRevenue - totalCOGS;
        const netProfit = totalRevenue - totalCOGS - totalExpenses;

        return {
            totalRevenue,
            totalCOGS,
            totalExpenses,
            grossProfit,
            netProfit,
            byBrand: brandPLs
        };
    }

    /**
     * Consolidate Balance Sheet across all brands
     */
    async consolidateBalanceSheet(
        brands: any[],
        asOfDate: Date
    ): Promise<ConsolidatedBS> {
        const brandBSs: BrandBS[] = [];
        let totalAssets = 0;
        let totalLiabilities = 0;

        for (const brand of brands) {
            // Get all accounts for this brand
            const accounts = await prisma.ledgerAccount.findMany({
                where: { brandId: brand.id },
                include: {
                    journalEntries: {
                        where: {
                            transaction: {
                                date: { lte: asOfDate },
                                status: 'POSTED'
                            }
                        }
                    }
                }
            });

            let assets = 0;
            let liabilities = 0;

            for (const account of accounts) {
                let balance = 0;
                for (const entry of account.journalEntries) {
                    const amount = Number(entry.amount);
                    balance += entry.type === 'DEBIT' ? amount : -amount;
                }

                if (account.type === 'ASSET') {
                    assets += balance;
                } else if (account.type === 'LIABILITY') {
                    liabilities += Math.abs(balance);
                }
            }

            const equity = assets - liabilities;

            brandBSs.push({
                brandId: brand.id,
                brandName: brand.name,
                assets,
                liabilities,
                equity
            });

            totalAssets += assets;
            totalLiabilities += liabilities;
        }

        // Eliminate IC receivables/payables
        const icBalances = await this.icService.getICBalances();
        for (const balance of icBalances) {
            const amount = Math.abs(Number(balance.balance));
            totalAssets -= amount; // Remove IC receivables
            totalLiabilities -= amount; // Remove IC payables
        }

        const totalEquity = totalAssets - totalLiabilities;

        return {
            totalAssets,
            totalLiabilities,
            totalEquity,
            byBrand: brandBSs
        };
    }

    /**
     * Consolidate Cash Flow across all brands (Indirect Method)
     */
    async consolidateCashFlow(
        brands: any[],
        startDate: Date,
        endDate: Date
    ): Promise<ConsolidatedCF> {
        const brandCFs: BrandCF[] = [];
        let totalOperating = 0;
        let totalInvesting = 0;
        let totalFinancing = 0;

        for (const brand of brands) {
            // For now, use simplified cash flow calculation
            // In production, this should use actual cash flow statement logic

            // Operating CF ≈ Net Profit + Depreciation - Working Capital changes
            const journals = await prisma.journalTransaction.findMany({
                where: {
                    brandId: brand.id,
                    date: { gte: startDate, lte: endDate },
                    status: 'POSTED'
                },
                include: {
                    entries: {
                        include: { account: true }
                    }
                }
            });

            let operating = 0;
            let investing = 0;
            let financing = 0;

            for (const journal of journals) {
                for (const entry of journal.entries) {
                    const amount = Number(entry.amount);
                    const debitAmount = entry.type === 'DEBIT' ? amount : -amount;

                    // Simplified classification
                    if (entry.account.type === 'ASSET' && entry.account.name.includes('Fixed')) {
                        investing += debitAmount;
                    } else if (entry.account.type === 'LIABILITY' && entry.account.name.includes('Loan')) {
                        financing += debitAmount;
                    } else {
                        operating += debitAmount;
                    }
                }
            }

            brandCFs.push({
                brandId: brand.id,
                brandName: brand.name,
                operating,
                investing,
                financing
            });

            totalOperating += operating;
            totalInvesting += investing;
            totalFinancing += financing;
        }

        return {
            operatingCashFlow: totalOperating,
            investingCashFlow: totalInvesting,
            financingCashFlow: totalFinancing,
            netCashFlow: totalOperating + totalInvesting + totalFinancing,
            byBrand: brandCFs
        };
    }

    /**
     * Eliminate inter-company transactions
     */
    async eliminateInterCompanyTransactions(
        transactions: any[]
    ): Promise<ICElimination[]> {
        const eliminations: ICElimination[] = [];

        for (const tx of transactions) {
            if (tx.status === 'APPROVED') {
                eliminations.push({
                    fromBrandId: tx.fromBrandId,
                    toBrandId: tx.toBrandId,
                    amount: Number(tx.amount),
                    type: tx.type,
                    description: tx.description
                });
            }
        }

        return eliminations;
    }

    /**
     * Validate consolidated statement
     */
    async validateConsolidation(statement: any): Promise<ValidationResult> {
        const errors: string[] = [];
        const warnings: string[] = [];

        // Validate Balance Sheet balances
        const bsBalance = statement.totalAssets - statement.totalLiabilities - statement.totalEquity;
        if (Math.abs(bsBalance) > 0.01) {
            errors.push(`Balance Sheet doesn't balance: Assets - Liabilities - Equity = ${bsBalance}`);
        }

        // Validate Cash Flow reconciliation
        const cfTotal = statement.operatingCashFlow + statement.investingCashFlow + statement.financingCashFlow;
        if (Math.abs(cfTotal) < 1) {
            warnings.push('Net cash flow is near zero, verify cash flow calculations');
        }

        // Validate IC eliminations
        if (statement.icTransactionCount === 0) {
            warnings.push('No inter-company transactions eliminated');
        }

        return {
            isValid: errors.length === 0,
            errors,
            warnings
        };
    }

    /**
     * Get date range for consolidation period
     */
    private getDateRange(fiscalYear: number, period: ConsolidationPeriod): { startDate: Date; endDate: Date } {
        let startDate: Date;
        let endDate: Date;

        switch (period) {
            case 'ANNUAL':
                startDate = new Date(fiscalYear, 0, 1);
                endDate = new Date(fiscalYear, 11, 31);
                break;
            case 'QUARTERLY':
                // Default to Q4
                startDate = new Date(fiscalYear, 9, 1);
                endDate = new Date(fiscalYear, 11, 31);
                break;
            case 'MONTHLY':
                // Default to December
                startDate = new Date(fiscalYear, 11, 1);
                endDate = new Date(fiscalYear, 11, 31);
                break;
            case 'YTD':
                startDate = new Date(fiscalYear, 0, 1);
                endDate = new Date();
                break;
        }

        return { startDate, endDate };
    }
}

import { prisma } from '@/lib/prisma';
import { startOfDay, endOfDay, subDays } from 'date-fns';

export interface DayMetrics {
    revenue: number;
    expenses: number;
    orders: number;
    inventory: Array<{ name: string; stock: number; minStock: number }>;
    topProducts: Array<{ name: string; quantity: number }>;
    peakHour: number | null;
}

export interface Anomaly {
    type: 'REVENUE' | 'EXPENSE' | 'STOCK' | 'ORDER';
    severity: 'HIGH' | 'MEDIUM' | 'LOW';
    message: string;
    changePercentage?: number;
}

export interface DailyData {
    today: DayMetrics;
    yesterday: DayMetrics;
    revenueChange: number;
    ordersChange: number;
    expenseChange: number;
}

export class DailyInsightsService {
    async collectDailyData(brandId: string): Promise<DailyData> {
        const today = new Date();
        const yesterday = subDays(today, 1);

        const currentMetrics = await this.getDayMetrics(brandId, today);
        const prevMetrics = await this.getDayMetrics(brandId, yesterday);

        const revenueChange = this.calculateChange(currentMetrics.revenue, prevMetrics.revenue);
        const ordersChange = this.calculateChange(currentMetrics.orders, prevMetrics.orders);
        const expenseChange = this.calculateChange(currentMetrics.expenses, prevMetrics.expenses);

        return {
            today: currentMetrics,
            yesterday: prevMetrics,
            revenueChange,
            ordersChange,
            expenseChange
        };
    }

    private async getDayMetrics(brandId: string, date: Date): Promise<DayMetrics> {
        const start = startOfDay(date);
        const end = endOfDay(date);

        // Revenue & Orders
        const orders = await prisma.order.findMany({
            where: {
                brandId,
                createdAt: { gte: start, lte: end },
                status: { in: ['COMPLETED', 'DIBAYAR', 'DIPESAN', 'DISIAPKAN', 'DIKIRIM'] }
            },
            include: {
                orderItems: { include: { frozenVariant: { include: { product: true } } } } as any
            }
        });


        // Top Products
        const productMap = new Map<string, { name: string; quantity: number }>();
        const hourMap = new Map<number, number>();

        for (const o of orders) {
            const hour = new Date(o.createdAt).getHours();
            hourMap.set(hour, (hourMap.get(hour) || 0) + 1);

            const items = (o as any).orderItems || [];
            for (const item of items) {
                const name = item.frozenVariant?.product?.name || item.name || 'Produk';
                const current = productMap.get(name) || { name, quantity: 0 };
                productMap.set(name, { name, quantity: current.quantity + item.quantity });
            }
        }

        const topProducts = Array.from(productMap.values())
            .sort((a, b) => b.quantity - a.quantity)
            .slice(0, 3);

        let peakHour: number | null = null;
        let maxOrders = 0;
        for (const [hour, count] of hourMap.entries()) {
            if (count > maxOrders) {
                maxOrders = count;
                peakHour = hour;
            }
        }

        const { FinancialReports } = await import('@/lib/intelligence/financialReports');
        const plData = await FinancialReports.getProfitLoss(brandId, { start, end });

        const revenue = orders.reduce((sum, o) => sum + Number(o.totalAmount || o.total || 0), 0);
        const expenses = plData.expenses.total + plData.cogs.total;

        // Inventory Critical Check (Only relevant for today's snapshot)
        // Find variants where stockOnHand <= minStock (assuming minStock exists on Variant or Product)
        // From schema check, I didn't see explicit FrozenVariant model but referenced in StockMutation.
        // FrozenService uses `prisma.frozenVariant`.
        // Let's assume minStock is on variant. If not, we might need Product.
        // Using `any` cast to avoid TS build error if definition is partial.

        let inventory: Array<{ name: string; stock: number; minStock: number }> = [];

        try {
            // Safe query leveraging typical structure
            const criticalVariants = await prisma.frozenVariant.findMany({
                where: {
                    // Start from Product to filter by Brand
                    product: {
                        category: { brandId }
                    },
                    // We want stock <= minStock
                    // Since specific fields are uncertain in generated client types vs schema,
                    // we fetch strict subset.
                    // stockOnHand: { lte: prisma.frozenVariant.fields.minStock } <- This is complex.
                    // Let's just fetch low stock items via simpler condition if possible
                },
                include: {
                    product: true
                }
            });

            // Filter manually in memory to be safe against schema mismatch type errors
            inventory = criticalVariants
                .filter((v: any) => v.stockOnHand <= (v.minStock || 5)) // Default 5 if minStock missing
                .map((v: any) => ({
                    name: v.product?.name || 'Unknown Item',
                    stock: v.stockOnHand,
                    minStock: v.minStock || 5
                }));

        } catch (e) {
            // Swallow inventory error to allow report generation
            // console.error("Inventory check failed", e);
        }

        return {
            revenue,
            expenses,
            orders: orders.length,
            inventory,
            topProducts,
            peakHour
        };
    }

    detectAnomalies(data: DailyData): Anomaly[] {
        const anomalies: Anomaly[] = [];

        // 1. Revenue Drop Severe (>40% drop)
        if (data.revenueChange < -40 && data.yesterday.revenue > 100000) {
            anomalies.push({
                type: 'REVENUE',
                severity: 'HIGH',
                message: `Revenue turun drastis ${Math.abs(data.revenueChange).toFixed(1)}% dibanding kemarin.`,
                changePercentage: data.revenueChange
            });
        }

        // 2. Expense Spike (>50% increase)
        if (data.expenseChange > 50 && data.today.expenses > 100000) {
            anomalies.push({
                type: 'EXPENSE',
                severity: 'HIGH',
                message: `Lonjakan biaya ${data.expenseChange.toFixed(1)}% hari ini.`,
                changePercentage: data.expenseChange
            });
        }

        // 3. Stock Critical
        if (data.today.inventory.length > 0) {
            anomalies.push({
                type: 'STOCK',
                severity: 'MEDIUM',
                message: `${data.today.inventory.length} produk stok kritis (di bawah minimum).`
            });
        }

        return anomalies;
    }

    private calculateChange(current: number, prev: number): number {
        if (prev === 0) return current > 0 ? 100 : 0;
        return ((current - prev) / prev) * 100;
    }
}

/**
 * Email Alert Service for Compliance Violations & Intelligence Leads
 * Sends email notifications for critical events
 */

import nodemailer from 'nodemailer';

export interface EmailAlert {
    to: string[];
    subject: string;
    body: string;
    priority: 'LOW' | 'NORMAL' | 'HIGH' | 'URGENT';
}

export class EmailAlertService {
    private transporter = nodemailer.createTransport({
        host: process.env.SMTP_HOST || 'smtp.gmail.com',
        port: Number(process.env.SMTP_PORT) || 587,
        secure: process.env.SMTP_SECURE === 'true',
        auth: {
            user: process.env.SMTP_USER,
            pass: process.env.SMTP_PASS,
        },
    });

    /**
     * Send email using configured provider
     */
    private async sendEmail(alert: EmailAlert): Promise<void> {
        try {
            await this.transporter.sendMail({
                from: `"${process.env.SMTP_FROM_NAME || 'Achiera Platform'}" <${process.env.SMTP_FROM || process.env.SMTP_USER}>`,
                to: alert.to.join(', '),
                subject: alert.subject,
