// ACHIERA Platform - Finance Service
// Double-entry ledger and financial reporting

import { prisma } from '@/lib/prisma';
import type { ServiceContext } from './WarehouseService';
import { Decimal } from '@prisma/client/runtime/library';

export type RecordRevenueInput = {
    orderId: string;
    amount: number;
    description?: string;
};

export type RecordExpenseInput = {
    amount: number;
    category: string; // COGS, MARKETING, OPERATIONS
    description: string;
    referenceId?: string;
};

export class FinanceService {
    /**
     * Record revenue from order (double-entry)
     */
    async recordRevenue(
        tx: any,
        brandId: string,
        input: RecordRevenueInput
    ) {
        // Get ledger accounts
        const cashAccount = await tx.ledgerAccount.findFirst({
            where: { brandId, code: '1000-CASH' }
        });

        const revenueAccount = await tx.ledgerAccount.findFirst({
            where: { brandId, code: '4000-REVENUE' }
        });

        if (!cashAccount || !revenueAccount) {
            throw new Error('Ledger accounts not configured. Please run setup.');
        }

        // Create transaction
        const transaction = await tx.journalTransaction.create({
            data: {
                brandId,
                referenceId: input.orderId,
                description: input.description || `Revenue from Order`,
                date: new Date()
            }
        });

        // Debit: Cash (increase asset)
        await tx.journalEntry.create({
            data: {
                transactionId: transaction.id,
                accountId: cashAccount.id,
                debit: input.amount,
                credit: 0
            }
        });

        // Credit: Revenue (increase revenue)
        await tx.journalEntry.create({
            data: {
                transactionId: transaction.id,
                accountId: revenueAccount.id,
                debit: 0,
                credit: input.amount
            }
        });

        return transaction;
    }

    /**
     * Record expense (double-entry)
     */
    async recordExpense(
        ctx: ServiceContext,
        input: RecordExpenseInput
    ) {
        return prisma.$transaction(async (tx) => {
            // Get accounts
            const cashAccount = await tx.ledgerAccount.findFirst({
                where: { brandId: ctx.brandId, code: '1000-CASH' }
            });

            let expenseAccountCode = '7000-EXPENSE'; // Default
            if (input.category === 'COGS') {
                expenseAccountCode = '6000-COGS';
            } else if (input.category === 'MARKETING') {
                expenseAccountCode = '7100-MARKETING';
            }

            const expenseAccount = await tx.ledgerAccount.findFirst({
                where: { brandId: ctx.brandId, code: expenseAccountCode }
            });

            if (!cashAccount || !expenseAccount) {
                throw new Error('Ledger accounts not configured');
            }

            // Create transaction
            const transaction = await tx.journalTransaction.create({
                data: {
                    brandId: ctx.brandId,
                    referenceId: input.referenceId,
                    description: input.description,
                    date: new Date()
                }
            });

            // Debit: Expense (increase expense)
            await tx.journalEntry.create({
                data: {
                    transactionId: transaction.id,
                    accountId: expenseAccount.id,
                    debit: input.amount,
                    credit: 0
                }
            });

            // Credit: Cash (decrease asset)
            await tx.journalEntry.create({
                data: {
                    transactionId: transaction.id,
                    accountId: cashAccount.id,
                    debit: 0,
                    credit: input.amount
                }
            });

            return transaction;
        });
    }

    /**
     * Generate P&L report
     */
    async generatePL(
        brandId: string,
        startDate: Date,
        endDate: Date
    ) {
        // Revenue
        const revenueEntries = await prisma.journalEntry.findMany({
            where: {
                account: {
                    brandId,
                    type: 'REVENUE'
                },
                transaction: {
                    date: {
                        gte: startDate,
                        lte: endDate
                    }
                }
            }
        });

        const revenue = revenueEntries.reduce(
            (sum, entry) => sum + Number(entry.credit),
            0
        );

        // COGS
        const cogsEntries = await prisma.journalEntry.findMany({
            where: {
                account: {
                    brandId,
                    code: { startsWith: '6' } // 6000-COGS
                },
                transaction: {
                    date: {
                        gte: startDate,
                        lte: endDate
                    }
                }
            }
        });

        const cogs = cogsEntries.reduce(
            (sum, entry) => sum + Number(entry.debit),
            0
        );

        // Operating Expenses
        const opexEntries = await prisma.journalEntry.findMany({
            where: {
                account: {
                    brandId,
                    code: { startsWith: '7' } // 7000-EXPENSE
                },
                transaction: {
                    date: {
                        gte: startDate,
                        lte: endDate
                    }
                }
            }
        });

        const opex = opexEntries.reduce(
            (sum, entry) => sum + Number(entry.debit),
            0
        );

        const grossProfit = revenue - cogs;
        const netProfit = grossProfit - opex;
        const grossMargin = revenue > 0 ? (grossProfit / revenue) * 100 : 0;
        const netMargin = revenue > 0 ? (netProfit / revenue) * 100 : 0;

        return {
            revenue,
            cogs,
            grossProfit,
            grossMargin,
            opex,
            netProfit,
            netMargin,
            period: {
                start: startDate,
                end: endDate
            }
        };
    }

    /**
     * Get ledger balance
     */
    async getLedgerBalance(brandId: string) {
        const accounts = await prisma.ledgerAccount.findMany({
            where: { brandId },
            include: {
                entries: true
            }
        });

        return accounts.map(account => {
            const totalDebit = account.entries.reduce(
                (sum, entry) => sum + Number(entry.debit),
                0
            );
            const totalCredit = account.entries.reduce(
                (sum, entry) => sum + Number(entry.credit),
                0
            );

            let balance = 0;
            if (account.type === 'ASSET' || account.type === 'EXPENSE') {
                balance = totalDebit - totalCredit;
            } else {
                balance = totalCredit - totalDebit;
            }

            return {
                code: account.code,
                name: account.name,
                type: account.type,
                balance
            };
        });
    }

    /**
     * Verify ledger integrity (debits = credits)
     */
    async verifyLedgerIntegrity(brandId: string) {
        const transactions = await prisma.journalTransaction.findMany({
            where: { brandId },
            include: {
                entries: true
            }
        });

        const errors: Array<{ transactionId: string; debit: number; credit: number }> = [];

        for (const transaction of transactions) {
            const totalDebit = transaction.entries.reduce(
                (sum, entry) => sum + Number(entry.debit),
                0
            );
            const totalCredit = transaction.entries.reduce(
                (sum, entry) => sum + Number(entry.credit),
                0
            );

            if (Math.abs(totalDebit - totalCredit) > 0.01) {
                errors.push({
                    transactionId: transaction.id,
                    debit: totalDebit,
                    credit: totalCredit
                });
            }
        }

        return {
            isValid: errors.length === 0,
            errors
        };
    }

    /**
     * Setup default ledger accounts for brand
     */
    async setupLedgerAccounts(brandId: string) {
        const defaultAccounts = [
            { code: '1000-CASH', name: 'Cash', type: 'ASSET' },
            { code: '1200-INVENTORY', name: 'Inventory', type: 'ASSET' },
            { code: '2000-PAYABLE', name: 'Accounts Payable', type: 'LIABILITY' },
            { code: '3000-EQUITY', name: 'Owner Equity', type: 'EQUITY' },
            { code: '4000-REVENUE', name: 'Sales Revenue', type: 'REVENUE' },
            { code: '6000-COGS', name: 'Cost of Goods Sold', type: 'EXPENSE' },
            { code: '7000-EXPENSE', name: 'Operating Expenses', type: 'EXPENSE' },
            { code: '7100-MARKETING', name: 'Marketing Expenses', type: 'EXPENSE' },
            { code: '7200-LOYALTY', name: 'Loyalty Costs', type: 'EXPENSE' }
        ];

        for (const account of defaultAccounts) {
            await prisma.ledgerAccount.upsert({
                where: {
                    brandId_code: {
                        brandId,
                        code: account.code
                    }
                },
                create: {
                    brandId,
                    ...account
                },
                update: {}
            });
        }

        return defaultAccounts;
    }

    /**
     * Get financial summary for dashboard
     */
    async getFinancialSummary(brandId: string) {
        const now = new Date();
        const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        const startOfLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0);

        const thisMonth = await this.generatePL(brandId, startOfMonth, now);
        const lastMonth = await this.generatePL(brandId, startOfLastMonth, endOfLastMonth);

        const revenueGrowth = lastMonth.revenue > 0
            ? ((thisMonth.revenue - lastMonth.revenue) / lastMonth.revenue) * 100
            : 0;

        return {
            thisMonth,
            lastMonth,
            revenueGrowth
        };
    }
}

import { prisma } from '@/lib/prisma';
import { ConsolidationPeriod } from '@prisma/client';
import { ConsolidationEngine } from './ConsolidationEngine';

export interface StatementComparison {
    current: any;
    previous: any;
    variance: {
        revenue: { amount: number; percentage: number };
        netProfit: { amount: number; percentage: number };
        assets: { amount: number; percentage: number };
        equity: { amount: number; percentage: number };
    };
}

export class FinancialStatementService {
    private consolidationEngine: ConsolidationEngine;
    private cacheExpiry = 24 * 60 * 60 * 1000; // 24 hours in ms

    constructor() {
        this.consolidationEngine = new ConsolidationEngine();
    }

    /**
     * Get brand-level P&L statement
     */
    async getBrandPL(brandId: string, startDate: Date, endDate: Date) {
        const journals = await prisma.journalTransaction.findMany({
            where: {
                brandId,
                date: { gte: startDate, lte: endDate },
                status: 'POSTED'
            },
            include: {
                entries: {
                    include: { account: true }
                }
            }
        });

        let revenue = 0;
        let cogs = 0;
        let expenses = 0;

        for (const journal of journals) {
            for (const entry of journal.entries) {
                const amount = Number(entry.amount);
                const accountType = entry.account.type;

                if (accountType === 'REVENUE') {
                    revenue += entry.type === 'CREDIT' ? amount : -amount;
                } else if (accountType === 'COGS') {
                    cogs += entry.type === 'DEBIT' ? amount : -amount;
                } else if (accountType === 'EXPENSE') {
                    expenses += entry.type === 'DEBIT' ? amount : -amount;
                }
            }
        }

        return {
            revenue,
            cogs,
            expenses,
            grossProfit: revenue - cogs,
            netProfit: revenue - cogs - expenses
        };
    }

    /**
     * Get brand-level Balance Sheet
     */
    async getBrandBS(brandId: string, asOfDate: Date) {
        const accounts = await prisma.ledgerAccount.findMany({
            where: { brandId },
            include: {
                journalEntries: {
                    where: {
                        transaction: {
                            date: { lte: asOfDate },
                            status: 'POSTED'
                        }
                    }
                }
            }
        });

        let assets = 0;
        let liabilities = 0;

        for (const account of accounts) {
            let balance = 0;
            for (const entry of account.journalEntries) {
                const amount = Number(entry.amount);
                balance += entry.type === 'DEBIT' ? amount : -amount;
            }

            if (account.type === 'ASSET') {
                assets += balance;
            } else if (account.type === 'LIABILITY') {
                liabilities += Math.abs(balance);
            }
        }

        return {
            assets,
            liabilities,
            equity: assets - liabilities
        };
    }

    /**
     * Get brand-level Cash Flow
     */
    async getBrandCF(brandId: string, startDate: Date, endDate: Date) {
        // Simplified cash flow - in production, use proper cash flow statement logic
        const pl = await this.getBrandPL(brandId, startDate, endDate);

        return {
            operating: pl.netProfit, // Simplified: operating CF ≈ net profit
            investing: 0, // Would need asset purchase/sale data
            financing: 0, // Would need loan/equity data
            netCashFlow: pl.netProfit
        };
    }

    /**
     * Get consolidated statement (with caching)
     */
    async getConsolidatedStatement(fiscalYear: number, period: ConsolidationPeriod) {
        // Check if statement exists and is fresh
        const existing = await prisma.consolidatedStatement.findUnique({
            where: {
                fiscalYear_period: {
                    fiscalYear,
                    period
                }
            }
        });

        if (existing) {
            const age = Date.now() - existing.generatedAt.getTime();
            if (age < this.cacheExpiry) {
                return existing;
            }
        }

        // Statement doesn't exist or is stale - return null
        // User must explicitly generate new statement
        return null;
    }

    /**
     * Generate new consolidated statement
     */
    async generateConsolidatedStatement(
        fiscalYear: number,
        period: ConsolidationPeriod,
        executedBy: string
    ) {
        // Delete existing statement if any
        await prisma.consolidatedStatement.deleteMany({
            where: { fiscalYear, period }
        });

        // Generate new statement
        return await this.consolidationEngine.generateConsolidatedStatement(
            fiscalYear,
            period,
            executedBy
        );
    }

    /**
     * Compare two statements
     */
    async compareStatements(
        currentYear: number,
        currentPeriod: ConsolidationPeriod,
        previousYear: number,
        previousPeriod: ConsolidationPeriod
    ): Promise<StatementComparison | null> {
        const [current, previous] = await Promise.all([
            this.getConsolidatedStatement(currentYear, currentPeriod),
            this.getConsolidatedStatement(previousYear, previousPeriod)
        ]);

        if (!current || !previous) {
            return null;
        }

        const calculateVariance = (current: number, previous: number) => {
            const amount = current - previous;
            const percentage = previous !== 0 ? (amount / previous) * 100 : 0;
            return { amount, percentage };
        };

        return {
            current,
            previous,
            variance: {
                revenue: calculateVariance(
                    Number(current.totalRevenue),
                    Number(previous.totalRevenue)
                ),
                netProfit: calculateVariance(
                    Number(current.netProfit),
                    Number(previous.netProfit)
                ),
                assets: calculateVariance(
                    Number(current.totalAssets),
                    Number(previous.totalAssets)
                ),
                equity: calculateVariance(
                    Number(current.totalEquity),
                    Number(previous.totalEquity)
                )
            }
        };
    }

    /**
     * Get all consolidated statements
     */
    async getAllStatements(limit: number = 10) {
        return await prisma.consolidatedStatement.findMany({
            orderBy: [
                { fiscalYear: 'desc' },
                { period: 'desc' }
            ],
            take: limit
        });
    }

    /**
     * Get consolidation logs
     */
    async getConsolidationLogs(limit: number = 20) {
        return await prisma.consolidationLog.findMany({
            orderBy: { startedAt: 'desc' },
            take: limit
        });
    }

    /**
     * Delete old statements (retention policy)
     */
    async cleanupOldStatements(yearsToKeep: number = 7) {
        const cutoffYear = new Date().getFullYear() - yearsToKeep;

        const deleted = await prisma.consolidatedStatement.deleteMany({
            where: {
                fiscalYear: { lt: cutoffYear }
            }
        });

        return deleted.count;
    }
}

import { prisma } from '@/lib/prisma';

export interface FlashSaleInfo {
    configId: string;
    name: string;
    discountPercentage: number;
    minPurchaseAmount: number;
    targetType?: string;
    targetItems?: string[];
    startDate?: string | null;
    endDate?: string | null;
    startTime: string;
    endTime: string;
    status: 'ACTIVE' | 'UPCOMING';
}

export class FlashSaleService {

    /**
     * Check if there is an active flash sale for a brand at the current moment.
     */
    static async getActiveFlashSale(brandId: string): Promise<FlashSaleInfo | null> {
        try {
            const config = await prisma.flashSaleConfig.findFirst({
                where: { brandId: brandId, isActive: true },
                include: { items: true }
            });

            console.log('[FlashSaleService] Config found:', config?.name || 'NONE');
            if (!config) return null;

            const now = new Date();
            // 1. Check Date Range (Compare using YYYY-MM-DD strings for timezone safety)
            const todayStr = now.toISOString().split('T')[0];
            // @ts-ignore
            const startStr = config.startDate ? new Date(config.startDate).toISOString().split('T')[0] : null;
            // @ts-ignore
            const endStr = config.endDate ? new Date(config.endDate).toISOString().split('T')[0] : null;

            if (startStr && todayStr < startStr) {
                console.log('[FlashSaleService] NOT ACTIVE: todayStr < startStr', todayStr, startStr);
                return null;
            }
            if (endStr && todayStr > endStr) {
                console.log('[FlashSaleService] NOT ACTIVE: todayStr > endStr', todayStr, endStr);
                return null;
            }

            // 2. Check Time Range
            // "11:00" -> HH:mm
            const [startHour, startMin] = config.startTime.split(':').map(Number);
            const [endHour, endMin] = config.endTime.split(':').map(Number);

            const currentHour = now.getHours();
            const currentMin = now.getMinutes();

            const currentMinutes = currentHour * 60 + currentMin;
            const startMinutes = startHour * 60 + startMin;
            const endMinutes = endHour * 60 + endMin;

            const configData = {
                configId: config.id,
                name: config.name,
                discountPercentage: Number(config.discountPercentage),
                minPurchaseAmount: Number(config.minPurchaseAmount || 0),
                targetType: config.targetType || 'ALL',
                // @ts-ignore
                targetItems: Array.isArray(config.targetIds) ? config.targetIds : [],
                // @ts-ignore
                startDate: config.startDate ? (config.startDate as any).toISOString() : null,
                // @ts-ignore
                endDate: config.endDate ? (config.endDate as any).toISOString() : null,
                startTime: config.startTime,
                endTime: config.endTime
            };

            if (currentMinutes >= startMinutes && currentMinutes < endMinutes) {
                console.log('[FlashSaleService] Flash Sale is ACTIVE');
                return { ...configData, status: 'ACTIVE' };
            }

            if (currentMinutes < startMinutes) {
                console.log('[FlashSaleService] Flash Sale is UPCOMING');
                return { ...configData, status: 'UPCOMING' };
            }

            console.log('[FlashSaleService] Flash Sale is NOT ACTIVE (Already Ended today)');
            return null;

        } catch (error) {
            console.error("Error Checking Flash Sale:", error);
            return null;
        }
    }

    static calculateDiscount(subtotal: number, flashSale: FlashSaleInfo, items: any[] = []): number {
        // If SPECIFIC target, only discount matching items (by product ID or variant ID)
        if (flashSale.targetType === 'SPECIFIC' && flashSale.targetItems) {
            const targetIds = new Set(flashSale.targetItems);
            let discountableTotal = 0;

            for (const item of items) {
                // Check if it matches a target product ID or variant ID
                const productId = item.productId || item.product?.id;
                const variantId = item.variantId || item.frozenVariantId;

                if (targetIds.has(productId) || targetIds.has(variantId)) {
                    const price = Number(item.price || item.basePrice || 0);
                    const qty = Number(item.quantity || 1);
                    discountableTotal += (price * qty);
                }
            }

            if (discountableTotal < flashSale.minPurchaseAmount) return 0;
            const discountAmount = discountableTotal * (flashSale.discountPercentage / 100);
            return Math.floor(discountAmount);
        }

        // Default ALL logic
        if (subtotal < flashSale.minPurchaseAmount) return 0;
        const discountAmount = subtotal * (flashSale.discountPercentage / 100);
        return Math.floor(discountAmount);
    }
}

// ACHIERA Platform - Frozen Product Service
// Product CRUD operations for Frozen Food module

import { prisma } from '@/lib/prisma';
import type { ServiceContext } from './WarehouseService';

export type CreateProductInput = {
    categoryId: string;
    name: string;
    slug: string;
    description?: string;
    image?: string;
    ingredients?: string;
    nutrition?: any;
    storageType: string;
    shelfLife?: number;
    variants: Array<{
        name: string;
        sku: string;
        price: number;
        weight: number;
    }>;
};

export type UpdateProductInput = Partial<CreateProductInput>;

export class FrozenProductService {
    /**
     * Create product with variants
     */
    async createProduct(ctx: ServiceContext, input: CreateProductInput) {
        return prisma.$transaction(async (tx) => {
            // 1. Verify category belongs to brand
            const category = await tx.frozenCategory.findUnique({
                where: { id: input.categoryId }
            });

            if (!category || category.brandId !== ctx.brandId) {
                throw new Error('Category not found or does not belong to brand');
            }

            // 2. Create product
            const product = await tx.frozenProduct.create({
                data: {
                    categoryId: input.categoryId,
                    name: input.name,
                    slug: input.slug,
                    description: input.description,
                    image: input.image,
                    ingredients: input.ingredients,
                    nutrition: input.nutrition,
                    storageType: input.storageType,
                    shelfLife: input.shelfLife
                }
            });

            // 3. Create variants
            for (const variant of input.variants) {
                await tx.frozenVariant.create({
                    data: {
                        productId: product.id,
                        name: variant.name,
                        sku: variant.sku,
                        price: variant.price,
                        weight: variant.weight
                    }
                });
            }

            // 4. Audit log
            await tx.auditLog.create({
                data: {
                    userId: ctx.userId,
                    brandId: ctx.brandId,
                    action: 'PRODUCT_CREATE',
                    entityType: 'FROZEN_PRODUCT',
                    entityId: product.id,
                    metadata: { name: product.name, slug: product.slug }
                }
            });

            return product;
        });
    }

    /**
     * Update product
     */
    async updateProduct(
        ctx: ServiceContext,
        productId: string,
        input: UpdateProductInput
    ) {
        return prisma.$transaction(async (tx) => {
            // 1. Verify product belongs to brand
            const product = await tx.frozenProduct.findUnique({
                where: { id: productId },
                include: { category: true }
            });

            if (!product || product.category.brandId !== ctx.brandId) {
                throw new Error('Product not found or does not belong to brand');
            }

            // 2. Update product
            const updated = await tx.frozenProduct.update({
                where: { id: productId },
                data: {
                    ...(input.name ? { name: input.name } : {}),
                    ...(input.slug ? { slug: input.slug } : {}),
                    ...(input.description !== undefined ? { description: input.description } : {}),
                    ...(input.image !== undefined ? { image: input.image } : {}),
                    ...(input.ingredients !== undefined ? { ingredients: input.ingredients } : {}),
                    ...(input.nutrition !== undefined ? { nutrition: input.nutrition } : {}),
                    ...(input.storageType ? { storageType: input.storageType } : {}),
                    ...(input.shelfLife !== undefined ? { shelfLife: input.shelfLife } : {})
                }
            });

            // 3. Audit log
            await tx.auditLog.create({
                data: {
                    userId: ctx.userId,
                    brandId: ctx.brandId,
                    action: 'PRODUCT_UPDATE',
                    entityType: 'FROZEN_PRODUCT',
                    entityId: productId,
                    metadata: { changes: input }
                }
            });

            return updated;
        });
    }

    /**
     * Get products for brand
     */
    async getProducts(brandId: string, categoryId?: string) {
        return prisma.frozenProduct.findMany({
            where: {
                category: { brandId },
                ...(categoryId ? { categoryId } : {})
            },
            include: {
                category: true,
                variants: {
                    orderBy: { price: 'asc' }
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Get single product with variants
     */
    async getProduct(productId: string) {
        return prisma.frozenProduct.findUnique({
            where: { id: productId },
            include: {
                category: true,
                variants: {
                    include: {
                        batches: {
                            where: {
                                quantity: { gt: 0 },
                                isExpired: false
                            },
                            orderBy: { expiryDate: 'asc' }
                        }
                    }
                }
            }
        });
    }

    /**
     * Get product by slug (public)
     */
    async getProductBySlug(slug: string) {
        return prisma.frozenProduct.findUnique({
            where: { slug },
            include: {
                category: {
                    include: {
                        brand: {
                            select: {
                                id: true,
                                slug: true,
                                name: true
                            }
                        }
                    }
                },
                variants: {
                    orderBy: { price: 'asc' }
                }
            }
        });
    }

    /**
     * Update variant price
     */
    async updateVariantPrice(
        ctx: ServiceContext,
        variantId: string,
        newPrice: number
    ) {
        return prisma.$transaction(async (tx) => {
            const variant = await tx.frozenVariant.findUnique({
                where: { id: variantId },
                include: {
                    product: {
                        include: { category: true }
                    }
                }
            });

            if (!variant || variant.product.category.brandId !== ctx.brandId) {
                throw new Error('Variant not found or does not belong to brand');
            }

            const oldPrice = variant.price;

            const updated = await tx.frozenVariant.update({
                where: { id: variantId },
                data: { price: newPrice }
            });

            // Audit log
            await tx.auditLog.create({
                data: {
                    userId: ctx.userId,
                    brandId: ctx.brandId,
                    action: 'PRICE_UPDATE',
                    entityType: 'FROZEN_VARIANT',
                    entityId: variantId,
                    metadata: {
                        oldPrice: oldPrice.toString(),
                        newPrice: newPrice.toString(),
                        sku: variant.sku
                    }
                }
            });

            return updated;
        });
    }

    /**
     * Get low stock variants
     */
    async getLowStockVariants(brandId: string, threshold: number = 10) {
        return prisma.frozenVariant.findMany({
            where: {
                product: {
                    category: { brandId }
                },
                stockOnHand: { lte: threshold }
            },
            include: {
                product: {
                    select: {
                        name: true,
                        category: {
                            select: { name: true }
                        }
                    }
                }
            },
            orderBy: { stockOnHand: 'asc' }
        });
    }

    /**
     * Create category
     */
    async createCategory(
        ctx: ServiceContext,
        data: {
            name: string;
            slug: string;
            image?: string;
        }
    ) {
        return prisma.frozenCategory.create({
            data: {
                brandId: ctx.brandId,
                name: data.name,
                slug: data.slug,
                image: data.image
            }
        });
    }

    /**
     * Get categories for brand
     */
    async getCategories(brandId: string) {
        return prisma.frozenCategory.findMany({
            where: { brandId },
            include: {
                _count: {
                    select: { products: true }
                }
            },
            orderBy: { name: 'asc' }
        });
    }
}

import { prisma } from "@/lib/prisma";
import { AccessControlError } from "@/lib/auth/rbac";

type ServiceContext = {
    brandId: string;
    userId?: string;
};

export class FrozenService {

    // --------------------------------------------------------
    // PRODUCT MANAGEMENT
    // --------------------------------------------------------

    /**
     * Get products with brand isolation
     */
    async getProducts(ctx: ServiceContext, categorySlug?: string) {
        return prisma.frozenProduct.findMany({
            where: {
                category: {
                    brandId: ctx.brandId,
                    ...(categorySlug ? { slug: categorySlug } : {})
                }
            },
            include: {
                variants: true,
                category: true
            }
        });
    }

    // --------------------------------------------------------
    // WAREHOUSE FIFO LOGIC
    // --------------------------------------------------------

    /**
     * Deducts stock using FIFO strategy (Oldest Expiry First)
     */
    async deductStock(ctx: ServiceContext, variantId: string, quantityToDeduct: number) {
        // 1. Verify Variant belongs to Brand
        const variant = await prisma.frozenVariant.findFirst({
            where: { id: variantId, product: { category: { brandId: ctx.brandId } } }
        });
        if (!variant) throw new Error("Variant not found or access denied");

        return prisma.$transaction(async (tx) => {
            // 2. Fetch batches sorted by Expiry (Oldest First)
            const batches = await tx.inventoryBatch.findMany({
                where: {
                    variantId,
                    quantity: { gt: 0 },
                    isExpired: false
                },
                orderBy: { expiryDate: 'asc' }
            });

            let remaining = quantityToDeduct;

            for (const batch of batches) {
                if (remaining <= 0) break;

                const deduction = Math.min(batch.quantity, remaining);

                // Update Batch
                await tx.inventoryBatch.update({
                    where: { id: batch.id },
                    data: { quantity: { decrement: deduction } }
                });

                remaining -= deduction;
            }

            if (remaining > 0) {
                throw new Error(`Insufficient stock for variant ${variant.name}. Missing: ${remaining}`);
            }

            // 3. Update Aggregate Stock
            await tx.frozenVariant.update({
                where: { id: variantId },
                data: { stockOnHand: { decrement: quantityToDeduct } }
            });

            return true; // Success
        });
    }

    // --------------------------------------------------------
    // SUBSCRIPTION LOGIC
    // --------------------------------------------------------

    /**
     * Creates an Order from a Subscription (Renewal)
     */
    async processSubscriptionRenewal(ctx: ServiceContext, subscriptionId: string) {
        const sub = await prisma.subscription.findUnique({
            where: { id: subscriptionId, brandId: ctx.brandId },
            include: { items: { include: { variant: true } }, user: true }
        });

        if (!sub || sub.status !== 'ACTIVE') throw new Error("Invalid Subscription");

        // Calculate Totals
        let subtotal = 0;
        const orderItemsData = sub.items.map(item => {
            const lineTotal = Number(item.variant.price) * item.quantity;
            subtotal += lineTotal;
            return {
                variantId: item.variantId,
                productId: item.variant.productId, // This field might need check if OrderItem has productId
                quantity: item.quantity,
                price: item.variant.price,
                total: lineTotal
            };
        });

        // Create Order
        const order = await prisma.order.create({
            data: {
                invoiceNo: `SUB-${Date.now()}`,
                quantity: sub.items.reduce((acc, i) => acc + i.quantity, 0),
                subtotal: subtotal,
                total: subtotal, // Add tax logic if needed
                customerName: sub.user.name,
                customerEmail: sub.user.email,
                customerPhone: "N/A", // Should fetch from profile
                status: 'WAITING_PAYMENT',
                // Link items (Note: OrderItem schema needs to support FrozenVariant connection)
                // For this demo, assuming standard OrderItem structure or adapting it
            }
        });

        // Setup Queue for FIFO deduction upon Payment...

        return order;
    }
}

import { prisma } from '@/lib/prisma';
import Anthropic from '@anthropic-ai/sdk';
