import { prisma } from "@/lib/prisma";
import { getFinancialPulse } from "../intelligence/financeEngine";

export interface RevenueKPIs {
    monthlyGrowthRate: number;
    yearlyGrowthRate: number;
    monthlyRecurringRevenue: number;
    revenuePerBrand: number;
    channelMix: { channel: string; percentage: number; revenue: number }[];
}

export interface ProfitabilityKPIs {
    grossProfitMargin: number;
    netProfitMargin: number;
    ebitda: number;
    roi: number;
}

export interface CustomerKPIs {
    customerAcquisitionCost: number;
    customerLifetimeValue: number;
    ltvToCacRatio: number;
    retentionRate: number;
    churnRate: number;
    averageOrderValue: number;
}

export interface OperationalKPIs {
    inventoryTurnover: number;
    avgOrderFulfillmentTime: number;
    productionEfficiency: number;
    orderFulfillmentRate: number;
}

export interface FinancialHealthKPIs {
    currentRatio: number;
    quickRatio: number;
    debtToEquityRatio: number;
    cashConversionCycle: number;
}

export interface KPIDashboard {
    brandId: string;
    brandName: string;
    period: { start: Date; end: Date };
    revenue: RevenueKPIs;
    profitability: ProfitabilityKPIs;
    customer: CustomerKPIs;
    operational: OperationalKPIs;
    financialHealth: FinancialHealthKPIs;
}

export class KPIService {
    /**
     * Get comprehensive KPI dashboard for a brand
     */
    async getKPIDashboard(brandId: string): Promise<KPIDashboard | null> {
        try {
            const brand = await prisma.brand.findUnique({
                where: { id: brandId },
                select: { name: true }
            });

            if (!brand) return null;

            const now = new Date();
            const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
            const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);

            const revenue = await this.getRevenueKPIs(brandId);
            const profitability = await this.getProfitabilityKPIs(brandId);
            const customer = await this.getCustomerKPIs(brandId);
            const operational = await this.getOperationalKPIs(brandId);
            const financialHealth = await this.getFinancialHealthKPIs(brandId);

            return {
                brandId,
                brandName: brand.name,
                period: { start: startOfMonth, end: endOfMonth },
                revenue,
                profitability,
                customer,
                operational,
                financialHealth
            };
        } catch (error) {
            console.error('Error in getKPIDashboard:', error);
            return null;
        }
    }

    /**
     * Calculate Revenue KPIs
     */
    async getRevenueKPIs(brandId: string): Promise<RevenueKPIs> {
        const now = new Date();
        const currentMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        const previousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        const previousMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);
        const lastYear = new Date(now.getFullYear() - 1, now.getMonth(), 1);
        const lastYearEnd = new Date(now.getFullYear() - 1, now.getMonth() + 1, 0);

        // Current month revenue
        const currentRevenue = await prisma.order.aggregate({
            where: {
                brandId,
                createdAt: { gte: currentMonth },
                status: { not: 'DIBATALKAN' }
            },
            _sum: { totalAmount: true, total: true }
        });
        const currentMonthRevenue = Number(currentRevenue._sum.totalAmount || currentRevenue._sum.total || 0);

        // Previous month revenue
        const previousRevenue = await prisma.order.aggregate({
            where: {
                brandId,
                createdAt: { gte: previousMonth, lte: previousMonthEnd },
                status: { not: 'DIBATALKAN' }
            },
            _sum: { totalAmount: true, total: true }
        });
        const previousMonthRevenue = Number(previousRevenue._sum.totalAmount || previousRevenue._sum.total || 0);

        // Last year same month revenue
        const lastYearRevenue = await prisma.order.aggregate({
            where: {
                brandId,
                createdAt: { gte: lastYear, lte: lastYearEnd },
                status: { not: 'DIBATALKAN' }
            },
            _sum: { totalAmount: true, total: true }
        });
        const lastYearMonthRevenue = Number(lastYearRevenue._sum.totalAmount || lastYearRevenue._sum.total || 0);

        // Growth rates
        const monthlyGrowthRate = previousMonthRevenue > 0
            ? ((currentMonthRevenue - previousMonthRevenue) / previousMonthRevenue) * 100
            : 0;

        const yearlyGrowthRate = lastYearMonthRevenue > 0
            ? ((currentMonthRevenue - lastYearMonthRevenue) / lastYearMonthRevenue) * 100
            : 0;

        // Channel mix
        const channelOrders = await prisma.order.groupBy({
            by: ['channel'],
            where: {
                brandId,
                createdAt: { gte: currentMonth },
                status: { not: 'DIBATALKAN' }
            },
            _sum: { totalAmount: true, total: true }
        });

        const channelMix = channelOrders.map(ch => ({
            channel: ch.channel || 'MANUAL',
            revenue: Number(ch._sum.totalAmount || ch._sum.total || 0),
            percentage: currentMonthRevenue > 0
                ? (Number(ch._sum.totalAmount || ch._sum.total || 0) / currentMonthRevenue) * 100
                : 0
        }));

        // Revenue per brand (for group-level calculation)
        const totalBrands = await prisma.brand.count({ where: { isActive: true } });
        const revenuePerBrand = totalBrands > 0 ? currentMonthRevenue / totalBrands : currentMonthRevenue;

        return {
            monthlyGrowthRate,
            yearlyGrowthRate,
            monthlyRecurringRevenue: currentMonthRevenue,
            revenuePerBrand,
            channelMix
        };
    }

    /**
     * Calculate Profitability KPIs
     */
    async getProfitabilityKPIs(brandId: string): Promise<ProfitabilityKPIs> {
        const financialData = await getFinancialPulse(brandId);

        const revenue = financialData.monthlyRevenue;
        const cogs = financialData.monthlyCOGS;
        const expenses = financialData.monthlyLedgerExpenses;

        const grossProfit = revenue - cogs;
        const netProfit = revenue - cogs - expenses;

        const grossProfitMargin = revenue > 0 ? (grossProfit / revenue) * 100 : 0;
        const netProfitMargin = revenue > 0 ? (netProfit / revenue) * 100 : 0;

        // EBITDA (simplified: net profit + depreciation)
        const depreciation = await prisma.assetDepreciation.aggregate({
            where: {
                asset: { brandId },
                createdAt: { gte: new Date(new Date().getFullYear(), new Date().getMonth(), 1) }
            },
            _sum: { amount: true }
        });
        const ebitda = netProfit + Number(depreciation._sum.amount || 0);

        // ROI (simplified: net profit / total assets)
        const assets = await prisma.businessAsset.aggregate({
            where: { brandId, status: 'ACTIVE' },
            _sum: { purchasePrice: true }
        });
        const totalAssets = Number(assets._sum.purchasePrice || 1);
        const roi = (netProfit / totalAssets) * 100;

        return {
            grossProfitMargin,
            netProfitMargin,
            ebitda,
            roi
        };
    }

    /**
     * Calculate Customer KPIs
     */
    async getCustomerKPIs(brandId: string): Promise<CustomerKPIs> {
        const now = new Date();
        const currentMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        const threeMonthsAgo = new Date(now.getFullYear(), now.getMonth() - 3, 1);

        // Total orders and revenue
        const orders = await prisma.order.findMany({
            where: {
                brandId,
                createdAt: { gte: threeMonthsAgo },
                status: { not: 'DIBATALKAN' }
            },
            select: {
                totalAmount: true,
                total: true,
                customerPhone: true,
                customerEmail: true,
                createdAt: true
            }
        });

        // Unique customers
        const uniqueCustomers = new Set(
            orders.map(o => o.customerPhone || o.customerEmail).filter(Boolean)
        );
        const totalCustomers = uniqueCustomers.size;

        // Total revenue
        const totalRevenue = orders.reduce((sum, o) => sum + Number(o.totalAmount || o.total || 0), 0);

        // Average Order Value
        const averageOrderValue = orders.length > 0 ? totalRevenue / orders.length : 0;

        // Customer Acquisition Cost (simplified: assume 10% of revenue spent on marketing)
        const estimatedMarketingSpend = totalRevenue * 0.1;
        const newCustomers = totalCustomers; // Simplified
        const customerAcquisitionCost = newCustomers > 0 ? estimatedMarketingSpend / newCustomers : 0;

        // Customer Lifetime Value (simplified: AOV * avg frequency * lifespan)
        const avgFrequency = totalCustomers > 0 ? orders.length / totalCustomers : 1;
        const avgLifespan = 12; // months
        const customerLifetimeValue = averageOrderValue * avgFrequency * avgLifespan;

        // LTV:CAC Ratio
        const ltvToCacRatio = customerAcquisitionCost > 0 ? customerLifetimeValue / customerAcquisitionCost : 0;

        // Retention Rate (simplified)
        const retentionRate = 75; // Placeholder - would need historical customer data
        const churnRate = 100 - retentionRate;

        return {
            customerAcquisitionCost,
            customerLifetimeValue,
            ltvToCacRatio,
            retentionRate,
            churnRate,
            averageOrderValue
        };
    }

    /**
     * Calculate Operational KPIs
     */
    async getOperationalKPIs(brandId: string): Promise<OperationalKPIs> {
        const now = new Date();
        const currentMonth = new Date(now.getFullYear(), now.getMonth(), 1);

        // Inventory Turnover = COGS / Average Inventory Value
        const financialData = await getFinancialPulse(brandId);
        const cogs = financialData.monthlyCOGS;

        // Simplified: Use a placeholder for inventory value
        // In a real implementation, you would calculate this from warehouse stock
        const avgInventoryValue = cogs * 0.5; // Assume inventory is 50% of monthly COGS
        const inventoryTurnover = avgInventoryValue > 0 ? cogs / avgInventoryValue : 0;

        // Average Order Fulfillment Time
        const completedOrders = await prisma.order.findMany({
            where: {
                brandId,
                createdAt: { gte: currentMonth },
                status: 'SELESAI'
            },
            select: { createdAt: true, updatedAt: true }
        });

        const totalFulfillmentTime = completedOrders.reduce((sum, o) => {
            const time = o.updatedAt.getTime() - o.createdAt.getTime();
            return sum + time;
        }, 0);
        const avgOrderFulfillmentTime = completedOrders.length > 0
            ? totalFulfillmentTime / completedOrders.length / (1000 * 60 * 60) // hours
            : 0;

        // Production Efficiency (simplified placeholder)
        // In a real implementation, this would come from production plan data
        const productionEfficiency = 95; // Placeholder: assume 95% efficiency

        // Order Fulfillment Rate
        const totalOrders = await prisma.order.count({
            where: { brandId, createdAt: { gte: currentMonth } }
        });
        const fulfilledOrders = completedOrders.length;
        const orderFulfillmentRate = totalOrders > 0 ? (fulfilledOrders / totalOrders) * 100 : 0;

        return {
            inventoryTurnover,
            avgOrderFulfillmentTime,
            productionEfficiency,
            orderFulfillmentRate
        };
    }

    /**
     * Calculate Financial Health KPIs
     */
    async getFinancialHealthKPIs(brandId: string): Promise<FinancialHealthKPIs> {
        // Get assets
        const assets = await prisma.ledgerAccount.findMany({
            where: { brandId, type: 'ASSET' },
            select: { balance: true, code: true }
        });

        const currentAssets = assets
            .filter(a => a.code.startsWith('1-1')) // Current assets
            .reduce((sum, a) => sum + Number(a.balance), 0);

        const inventory = assets
            .filter(a => a.code.includes('INVENTORY'))
            .reduce((sum, a) => sum + Number(a.balance), 0);

        // Get liabilities
        const liabilities = await prisma.ledgerAccount.findMany({
            where: { brandId, type: 'LIABILITY' },
            select: { balance: true, code: true }
        });

        const currentLiabilities = liabilities
            .filter(l => l.code.startsWith('2-1')) // Current liabilities
            .reduce((sum, l) => sum + Number(l.balance), 0);

        const totalLiabilities = liabilities.reduce((sum, l) => sum + Number(l.balance), 0);

        // Get equity
        const equity = await prisma.ledgerAccount.findMany({
            where: { brandId, type: 'EQUITY' },
            select: { balance: true }
        });
        const totalEquity = equity.reduce((sum, e) => sum + Number(e.balance), 0);

        // Calculate ratios
        const currentRatio = currentLiabilities > 0 ? currentAssets / currentLiabilities : 0;
        const quickRatio = currentLiabilities > 0 ? (currentAssets - inventory) / currentLiabilities : 0;
        const debtToEquityRatio = totalEquity > 0 ? totalLiabilities / totalEquity : 0;

        // Cash Conversion Cycle (simplified)
        const cashConversionCycle = 30; // Placeholder - would need detailed calculation

        return {
            currentRatio,
            quickRatio,
            debtToEquityRatio,
            cashConversionCycle
        };
    }

    /**
     * Get consolidated KPIs across all brands
     */
    async getConsolidatedKPIs(): Promise<any> {
        const brands = await prisma.brand.findMany({
            where: { isActive: true },
            select: { id: true, name: true }
        });

        const brandKPIs = await Promise.all(
            brands.map(brand => this.getKPIDashboard(brand.id))
        );

        const validKPIs = brandKPIs.filter(k => k !== null);

        // Aggregate KPIs
        const consolidated = {
            totalBrands: brands.length,
            avgMonthlyGrowthRate: validKPIs.reduce((sum, k) => sum + (k?.revenue.monthlyGrowthRate || 0), 0) / validKPIs.length,
            avgGrossProfitMargin: validKPIs.reduce((sum, k) => sum + (k?.profitability.grossProfitMargin || 0), 0) / validKPIs.length,
            avgNetProfitMargin: validKPIs.reduce((sum, k) => sum + (k?.profitability.netProfitMargin || 0), 0) / validKPIs.length,
            avgLtvToCacRatio: validKPIs.reduce((sum, k) => sum + (k?.customer.ltvToCacRatio || 0), 0) / validKPIs.length,
            avgCurrentRatio: validKPIs.reduce((sum, k) => sum + (k?.financialHealth.currentRatio || 0), 0) / validKPIs.length,
            brandKPIs: validKPIs
        };

        return consolidated;
    }
}

import { prisma } from '@/lib/prisma';
import { RiskSeverity, RiskType, AlertStatus } from '@prisma/client';
import { CashFlowForecastEngine } from './CashFlowForecastEngine';

export interface RiskScore {
    score: number; // 0-100
    severity: RiskSeverity;
    factors: RiskFactor[];
}

export interface RiskFactor {
    factor: string;
    impact: number; // 0-100
    weight: number;
}

export interface Recommendation {
    action: string;
    amount: number;
    priority: number; // 1-10
    description: string;
}

export class LiquidityRiskDetector {
    private forecastEngine: CashFlowForecastEngine;

    constructor() {
        this.forecastEngine = new CashFlowForecastEngine();
    }

    /**
     * Detect liquidity risks for a brand
     */
    async detectRisks(
        brandId: string,
        forecastMonths: number = 6
    ): Promise<any[]> {
        // Generate forecast
        const forecasts = await this.forecastEngine.generateForecast(brandId, forecastMonths);

        const risks: any[] = [];

        for (const forecast of forecasts) {
            // Check for various risk types
            const cashShortfall = await this.checkCashShortfall(brandId, forecast);
            if (cashShortfall) risks.push(cashShortfall);

            const negativeBalance = await this.checkNegativeBalance(brandId, forecast);
            if (negativeBalance) risks.push(negativeBalance);

            const lowRunway = await this.checkLowRunway(brandId, forecast);
            if (lowRunway) risks.push(lowRunway);
        }

        // Save risks to database
        for (const risk of risks) {
            await this.saveRisk(risk);
        }

        return risks;
    }

    /**
     * Check for cash shortfall
     */
    private async checkCashShortfall(brandId: string, forecast: any): Promise<any | null> {
        const monthlyBurnRate = 25_000_000; // Simplified - should calculate from actual data
        const minimumRequired = monthlyBurnRate * 1.5; // 1.5 months buffer

        if (forecast.predictedBalance < minimumRequired) {
            const shortfall = minimumRequired - forecast.predictedBalance;
            const severity = this.calculateSeverity(shortfall, monthlyBurnRate);

            return {
                brandId,
                riskDate: forecast.date,
                severity,
                type: 'CASH_SHORTFALL' as RiskType,
                projectedCash: forecast.predictedBalance,
                requiredCash: minimumRequired,
                shortfall,
                recommendations: await this.generateRecommendations({
                    type: 'CASH_SHORTFALL',
                    shortfall,
                    brandId
                }),
                status: 'ACTIVE' as AlertStatus
            };
        }

        return null;
    }

    /**
     * Check for negative balance
     */
    private async checkNegativeBalance(brandId: string, forecast: any): Promise<any | null> {
        if (forecast.worstCase < 0) {
            return {
                brandId,
                riskDate: forecast.date,
                severity: 'CRITICAL' as RiskSeverity,
                type: 'NEGATIVE_BALANCE' as RiskType,
                projectedCash: forecast.worstCase,
                requiredCash: 0,
                shortfall: Math.abs(forecast.worstCase),
                recommendations: await this.generateRecommendations({
                    type: 'NEGATIVE_BALANCE',
                    shortfall: Math.abs(forecast.worstCase),
                    brandId
                }),
                status: 'ACTIVE' as AlertStatus
            };
        }

        return null;
    }

    /**
     * Check for low runway
     */
    private async checkLowRunway(brandId: string, forecast: any): Promise<any | null> {
        const monthlyBurnRate = 25_000_000;
        const runway = forecast.predictedBalance / monthlyBurnRate;

        if (runway < 3) {
            return {
                brandId,
                riskDate: forecast.date,
                severity: runway < 2 ? 'HIGH' as RiskSeverity : 'MEDIUM' as RiskSeverity,
                type: 'LOW_RUNWAY' as RiskType,
                projectedCash: forecast.predictedBalance,
                requiredCash: monthlyBurnRate * 6, // Target 6 months
                shortfall: Math.max(0, (monthlyBurnRate * 6) - forecast.predictedBalance),
                recommendations: await this.generateRecommendations({
                    type: 'LOW_RUNWAY',
                    shortfall: (monthlyBurnRate * 6) - forecast.predictedBalance,
                    brandId
                }),
                status: 'ACTIVE' as AlertStatus
            };
        }

        return null;
    }

    /**
     * Calculate risk severity
     */
    private calculateSeverity(shortfall: number, monthlyBurnRate: number): RiskSeverity {
        const ratio = shortfall / monthlyBurnRate;

        if (ratio > 0.5) return 'CRITICAL';
        if (ratio > 0.25) return 'HIGH';
        if (ratio > 0.1) return 'MEDIUM';
        return 'LOW';
    }

    /**
     * Generate recommendations for a risk
     */
    async generateRecommendations(params: {
        type: string;
        shortfall: number;
        brandId: string;
    }): Promise<Recommendation[]> {
        const recommendations: Recommendation[] = [];

        switch (params.type) {
            case 'CASH_SHORTFALL':
            case 'NEGATIVE_BALANCE':
            case 'LOW_RUNWAY':
                // Recommend IC loan
                recommendations.push({
                    action: 'IC_LOAN',
                    amount: params.shortfall,
                    priority: 9,
                    description: `Request inter-company loan of ${this.formatCurrency(params.shortfall)} from brands with excess cash`
                });

                // Recommend expense reduction
                recommendations.push({
                    action: 'REDUCE_EXPENSES',
                    amount: params.shortfall * 0.3,
                    priority: 7,
                    description: `Reduce monthly expenses by ${this.formatCurrency(params.shortfall * 0.3)} (30% of shortfall)`
                });

                // Recommend revenue acceleration
                recommendations.push({
                    action: 'ACCELERATE_REVENUE',
                    amount: params.shortfall * 0.5,
                    priority: 8,
                    description: `Accelerate revenue collection or launch promotion to generate ${this.formatCurrency(params.shortfall * 0.5)}`
                });
                break;
        }

        return recommendations;
    }

    /**
     * Calculate overall risk score
     */
    async calculateRiskScore(brandId: string, date: Date): Promise<RiskScore> {
        const factors: RiskFactor[] = [];

        // Factor 1: Cash balance
        const forecast = await prisma.cashFlowForecast.findFirst({
            where: { brandId, forecastDate: date }
        });

        if (forecast) {
            const balanceScore = Math.max(0, 100 - (Number(forecast.confidence)));
            factors.push({
                factor: 'Cash Balance Uncertainty',
                impact: balanceScore,
                weight: 0.4
            });
        }

        // Factor 2: Volatility
        if (forecast && forecast.factors) {
            const volatility = (forecast.factors as any).volatility || 0;
            factors.push({
                factor: 'Cash Flow Volatility',
                impact: Math.min(100, volatility),
                weight: 0.3
            });
        }

        // Factor 3: Trend
        if (forecast && forecast.factors) {
            const trend = (forecast.factors as any).trend || 0;
            const trendScore = trend < 0 ? Math.abs(trend) * 10 : 0;
            factors.push({
                factor: 'Negative Trend',
                impact: Math.min(100, trendScore),
                weight: 0.3
            });
        }

        // Calculate weighted score
        const score = factors.reduce((sum, f) => sum + (f.impact * f.weight), 0);

        // Determine severity
        const severity: RiskSeverity =
            score > 70 ? 'CRITICAL' :
                score > 50 ? 'HIGH' :
                    score > 30 ? 'MEDIUM' : 'LOW';

        return {
            score,
            severity,
            factors
        };
    }

    /**
     * Save risk to database
     */
    private async saveRisk(risk: any): Promise<void> {
        await prisma.liquidityRisk.create({
            data: risk
        });
    }

    /**
     * Send risk alert (email/notification)
     */
    async sendRiskAlert(risk: any): Promise<void> {
        // TODO: Integrate with EmailAlertService
        console.log('[Liquidity Risk Alert]', {
            brandId: risk.brandId,
            severity: risk.severity,
            type: risk.type,
            shortfall: risk.shortfall
        });
    }

    /**
     * Format currency
     */
    private formatCurrency(amount: number): string {
        return new Intl.NumberFormat('id-ID', {
            style: 'currency',
            currency: 'IDR',
            maximumFractionDigits: 0
        }).format(amount);
    }
}

import { prisma } from '@/lib/prisma';
import { startOfMonth, endOfMonth, subMonths } from 'date-fns';

export interface MonthlyData {
    period: Date;
    financial: {
        revenue: number;
        profit: number;
        expenses: number;
        margin: number;
        growthRevenue: number;
        expenseBreakdown: Array<{ name: string; amount: number; percentage: number }>;
    };
    sales: {
        totalOrders: number;
        topProducts: Array<{ name: string; quantity: number; revenue: number }>;
        channelPerformance: Record<string, number>; // GoFood, GrabFood, etc
    };
    inventory: {
        totalWaste: number;
        wastePercentage: number;
        stockTurnover: number;
    };
    loyalty: {
        topCustomers: Array<{ name: string; count: number; total: number }>;
    };
    marketplace: {
        totalFees: number;
        netRevenue: number;
    };
    operational: {
        totalProduction: number;
        averageProcessingTime: number; // minutes
    };
}

export class MonthlyReportService {
    async collectMonthlyData(brandId: string, month: Date = new Date()): Promise<MonthlyData> {
        const start = startOfMonth(month);
        const end = endOfMonth(month);

        const previousStart = startOfMonth(subMonths(month, 1));
        const previousEnd = endOfMonth(subMonths(month, 1));

        // 1. Fetch Orders for current month
        const orders = await prisma.order.findMany({
            where: {
                brandId,
                createdAt: { gte: start, lte: end },
                status: { in: ['COMPLETED', 'DIBAYAR', 'DIPESAN', 'DISIAPKAN', 'DIKIRIM'] }
            },
            include: {
                orderItems: { include: { frozenVariant: { include: { product: true } } } } as any
            }
        });

        // 2. Fetch Orders for previous month (for growth calculation)
        const prevOrders = await prisma.order.findMany({
            where: {
                brandId,
                createdAt: { gte: previousStart, lte: previousEnd },
                status: { in: ['COMPLETED', 'DIBAYAR'] }
            }
        });

        const { FinancialReports } = await import('@/lib/intelligence/financialReports');
        const plData = await FinancialReports.getProfitLoss(brandId, { start, end });

        // Calculate Revenue and Fees from current month orders
        let totalRevenue = 0;
        let totalFees = 0;
        const brand = await prisma.brand.findUnique({ where: { id: brandId }, select: { paymentSettings: true } });
        const settings = (brand?.paymentSettings as any) || {};
        const platformFees = settings.marketplaceFees || {};
        const mdrFees = settings.mdrFees || {};

        const productSales = new Map<string, { name: string; quantity: number; revenue: number }>();
        const customerMap = new Map<string, { name: string; count: number; total: number }>();
        const channelPerformance: Record<string, number> = {};

        for (const order of orders) {
            const gross = Number(order.totalAmount || order.total || 0);
            totalRevenue += gross;

            const channelName = order.channel?.toUpperCase() || 'MANUAL';
            const commRate = (platformFees[channelName] !== undefined ? platformFees[channelName] / 100 : 0);
            const mdrRate = (mdrFees[channelName] !== undefined ? mdrFees[channelName] / 100 : 0);
            totalFees += gross * (commRate + mdrRate);

            // Channel stats
            channelPerformance[channelName] = (channelPerformance[channelName] || 0) + 1;

            // Customer stats
            const customerName = (order as any).customerName || 'Pelanggan';
            const customerId = (order as any).customerId || customerName;
            const currentC = customerMap.get(customerId) || { name: customerName, count: 0, total: 0 };
            customerMap.set(customerId, {
                name: customerName,
                count: currentC.count + 1,
                total: currentC.total + gross
            });

            // Product stats
            const items = (order as any).orderItems || [];
            for (const item of items) {
                const variantId = item.frozenVariantId || item.variantId;
                const price = Number(item.price || item.unitPrice || 0);
                const qty = item.quantity;
                const name = item.frozenVariant?.product?.name || item.name || 'Unknown Product';

                const currentP = productSales.get(variantId) || { name, quantity: 0, revenue: 0 };
                productSales.set(variantId, {
                    name,
                    quantity: currentP.quantity + qty,
                    revenue: currentP.revenue + (price * qty)
                });
            }
        }

        const previousRevenue = prevOrders.reduce((sum, o) => sum + Number(o.totalAmount || o.total || 0), 0);
        const growthRevenue = previousRevenue > 0 ? ((totalRevenue - previousRevenue) / previousRevenue) * 100 : 0;
        const expenses = plData.expenses.total + plData.cogs.total;

        // Prepare Expense Breakdown
        const allExpenses = [...plData.expenses.items, ...plData.cogs.items];
        const totalExp = allExpenses.reduce((sum, item) => sum + item.amount, 0);
        const expenseBreakdown = allExpenses
            .sort((a, b) => b.amount - a.amount)
            .map(item => ({
                name: item.name,
                amount: item.amount,
                percentage: totalExp > 0 ? (item.amount / totalExp) * 100 : 0
            }));

        // Inventory/Waste
        let totalWaste = 0;
        try {
            const wasteMutations = await prisma.stockMutation.findMany({
                where: {
                    warehouse: { brandId },
                    createdAt: { gte: start, lte: end },
                    type: { in: ['OUT', 'ADJUSTMENT', 'EXPIRED'] as any }
                }
            });
            totalWaste = wasteMutations
                .filter(m => (m.notes?.toLowerCase().includes('expired') || m.notes?.toLowerCase().includes('damaged') || m.notes?.toLowerCase().includes('waste')))
                .reduce((sum, m) => sum + Math.abs(m.quantity), 0);
        } catch (e) { }

        return {
            period: month,
            financial: {
                revenue: totalRevenue,
                profit: totalRevenue - expenses - totalFees,
                expenses,
                margin: totalRevenue > 0 ? ((totalRevenue - expenses - totalFees) / totalRevenue) * 100 : 0,
                growthRevenue,
                expenseBreakdown
            },
            sales: {
                totalOrders: orders.length,
                topProducts: Array.from(productSales.values()).sort((a, b) => b.quantity - a.quantity).slice(0, 5),
                channelPerformance
            },
            inventory: {
                totalWaste,
                wastePercentage: orders.length > 0 ? (totalWaste / orders.length) * 100 : 0,
                stockTurnover: 0
            },
            loyalty: {
                topCustomers: Array.from(customerMap.values()).sort((a, b) => b.count - a.count).slice(0, 5)
            },
            marketplace: {
                totalFees,
                netRevenue: totalRevenue - totalFees
            },
            operational: {
                totalProduction: 0,
                averageProcessingTime: 0
            }
        };
    }

    async getWeeklyTrends(brandId: string, date: Date = new Date()) {
        const { startOfWeek, endOfWeek, subWeeks } = await import('date-fns');
        const start = startOfWeek(date);
        const end = endOfWeek(date);
        const prevStart = startOfWeek(subWeeks(date, 1));
        const prevEnd = endOfWeek(subWeeks(date, 1));

        const currentOrders = await prisma.order.findMany({
            where: { brandId, createdAt: { gte: start, lte: end }, status: 'COMPLETED' },
            include: { orderItems: true }
        });

        const prevOrders = await prisma.order.findMany({
            where: { brandId, createdAt: { gte: prevStart, lte: prevEnd }, status: 'COMPLETED' }
        });

        const revenue = currentOrders.reduce((sum, o) => sum + Number(o.total), 0);
        const prevRevenue = prevOrders.reduce((sum, o) => sum + Number(o.total), 0);
        const growth = prevRevenue > 0 ? ((revenue - prevRevenue) / prevRevenue) * 100 : 0;

        // Channel Performance
        const channels: Record<string, number> = {};
        currentOrders.forEach(o => {
            const c = (o as any).channel || 'POS';
            channels[c] = (channels[c] || 0) + Number(o.total);
        });

        return {
            period: { start, end },
            revenue,
            growth,
            totalOrders: currentOrders.length,
            channels
        };
    }
}

import { prisma } from '@/lib/prisma';
import crypto from 'crypto';

export type OTPType =
    | 'OTP_LOGIN'
    | 'OTP_REGISTER'
    | 'OTP_FORGOT_PASSWORD'
    | 'OTP_PROFILE_UPDATE';

export class OTPService {
    /**
     * Generate a 6-digit OTP code
     */
    private static generateOTPCode(): string {
        return Math.floor(100000 + Math.random() * 900000).toString();
    }

    /**
     * Generate a unique token for the verification
     */
    private static generateToken(): string {
        return crypto.randomBytes(32).toString('hex');
    }

    /**
     * Create and store a new OTP
     * @param email - Email address to send OTP to
     * @param type - Type of OTP (login, register, forgot password, etc.)
     * @param userId - Optional user ID if user exists
     * @returns Object containing the OTP code and token
     */
    static async createOTP(email: string, type: OTPType, userId?: string) {
        const code = this.generateOTPCode();
        const token = this.generateToken();
        const expiresAt = new Date(Date.now() + 10 * 60 * 1000); // 10 minutes

        // Invalidate any existing unused OTPs for this email and type
        await prisma.verificationToken.updateMany({
            where: {
                email,
                type,
                used: false,
            },
            data: {
                used: true,
                usedAt: new Date(),
            },
        });

        // Create new OTP
        const verificationToken = await prisma.verificationToken.create({
            data: {
                email,
                type,
                code,
                token,
                expiresAt,
                userId,
            },
        });

        console.log(`[OTPService] Created OTP for ${email} (${type}): ${code}`);

        return {
            code,
            token,
            expiresAt,
            id: verificationToken.id,
        };
    }

    static async verifyOTP(email: string, code: string, type: OTPType) {
        const verificationToken = await prisma.verificationToken.findFirst({
            where: {
                email,
                type,
                used: false,
                expiresAt: {
                    gt: new Date(),
                },
            },
        });

        if (!verificationToken) {
            console.log(`[OTPService] No active OTP found for ${email} (${type})`);
            return {
                success: false,
                message: 'Kode OTP tidak ditemukan atau sudah kadaluarsa',
            };
        }

        // Check attempts
        if ((verificationToken as any).attempts >= 3) {
            // Invalidate the token
            await prisma.verificationToken.update({
                where: { id: verificationToken.id },
                data: { used: true, usedAt: new Date() }
            });
            return {
                success: false,
                message: 'Terlalu banyak percobaan salah. Silakan minta kode baru.',
            };
        }

        if (verificationToken.code !== code) {
            // Increment attempts
            await prisma.verificationToken.update({
                where: { id: verificationToken.id },
                data: { attempts: { increment: 1 } }
            });

            const remaining = 3 - ((verificationToken as any).attempts + 1);
            return {
                success: false,
                message: `Kode OTP salah. Sisa percobaan: ${remaining}`,
            };
        }

        // Mark as used
        await prisma.verificationToken.update({
            where: { id: verificationToken.id },
            data: {
                used: true,
                usedAt: new Date(),
            },
        });

        console.log(`[OTPService] OTP verified successfully for ${email} (${type})`);

        return {
            success: true,
            token: verificationToken.token,
            userId: verificationToken.userId,
        };
    }

    /**
     * Verify a token (for multi-step flows)
     * @param token - Token to verify
     * @param type - Type of verification
     * @returns Verification result
     */
    static async verifyToken(token: string, type: OTPType) {
        const verificationToken = await prisma.verificationToken.findFirst({
            where: {
                token,
                type,
                used: true, // Token should be marked as used after OTP verification
                expiresAt: {
                    gt: new Date(),
                },
            },
        });

        if (!verificationToken) {
            return {
                success: false,
                message: 'Token tidak valid atau sudah kadaluarsa',
            };
        }

        return {
            success: true,
            email: verificationToken.email,
            userId: verificationToken.userId,
        };
    }

    /**
     * Clean up expired tokens (should be run periodically)
     */
    static async cleanupExpiredTokens() {
        const result = await prisma.verificationToken.deleteMany({
            where: {
                expiresAt: {
                    lt: new Date(),
                },
            },
        });

        console.log(`[OTPService] Cleaned up ${result.count} expired tokens`);
        return result.count;
    }

    /**
     * Resend OTP (creates a new one)
     * @param email - Email address
     * @param type - Type of OTP
     * @param userId - Optional user ID
     * @returns New OTP details
     */
    static async resendOTP(email: string, type: OTPType, userId?: string) {
        // Check if there's a recent OTP (within last 1 minute) to prevent spam
        const recentOTP = await prisma.verificationToken.findFirst({
            where: {
                email,
                type,
                createdAt: {
                    gt: new Date(Date.now() - 60 * 1000), // Last 1 minute
                },
            },
            orderBy: {
                createdAt: 'desc',
            },
        });

        if (recentOTP) {
            return {
                success: false,
                message: 'Mohon tunggu 1 menit sebelum meminta kode baru',
                retryAfter: 60 - Math.floor((Date.now() - recentOTP.createdAt.getTime()) / 1000),
            };
        }

        // Create new OTP
        const otp = await this.createOTP(email, type, userId);

        return {
            success: true,
            ...otp,
        };
    }
}

import { prisma } from "@/lib/prisma";
import { BrandRole } from "@prisma/client";

type OnboardingParams = {
    name: string;
    slug: string;
    organizationId?: string; // Optional
    adminUserId: string;
};

export class OnboardingService {

    /**
     * Orchestrates the creation of a fully functional Brand
     */
    async onboardingBrand(params: OnboardingParams) {
        return prisma.$transaction(async (tx) => {
            // 1. Create Brand
            const brand = await tx.brand.create({
                data: {
                    name: params.name,
                    slug: params.slug,
                    organizationId: params.organizationId,
                    isActive: true
                }
            });

            // 2. Create Defaults Config
            await tx.brandConfig.create({
                data: {
                    brandId: brand.id,
                    features: {
                        loyalty: false,
                        ads: false,
                        subscriptions: false
                    },
                    pricingStrategy: 'STANDARD',
                    // Use system defaults for null fields (warehouseRules, loyaltyRules)
                }
            });

            // 3. Hydrate Ledger (Standard Chart of Accounts)
            const standardAccounts = [
                { code: '1000', name: 'Cash on Hand', type: 'ASSET' },
                { code: '3000', name: 'Owner Equity', type: 'EQUITY' },
                { code: '4000', name: 'Sales Revenue', type: 'REVENUE' },
                { code: '6000', name: 'COGS', type: 'EXPENSE' },
                { code: '6100', name: 'Marketing Expense', type: 'EXPENSE' },
            ];

            for (const acc of standardAccounts) {
                await tx.ledgerAccount.create({
                    data: {
                        brandId: brand.id,
                        code: acc.code,
                        name: acc.name,
                        type: acc.type
                    }
                });
            }

            // 4. Assign Creator as BRAND_ADMIN
            await tx.userBrandRole.create({
                data: {
                    userId: params.adminUserId,
                    brandId: brand.id,
                    role: 'BRAND_ADMIN'
                }
            });

            // 5. Initial Warehouse Setup (Optional Placeholder)
            // We don't create a warehouse *location* yet as our simplified schema uses 'InventoryBatch' per brand.
            // But we could create a default 'Uncategorized' Category if needed.

            return brand;
        });
    }

    /**
     * Migration Helper: Retroactively setup config for existing brands
     */
    async fixMissingConfigs() {
        const brands = await prisma.brand.findMany({
            where: { config: null },
            include: { config: true }
        });

        for (const brand of brands) {
            // Create default config if missing
            await prisma.brandConfig.create({
                data: {
                    brandId: brand.id,
                    features: {
                        loyalty: false,
                        ads: false,
                        subscriptions: false
                    },
                    pricingStrategy: 'STANDARD'
                }
            });
        }
        return `Fixed ${brands.length} brands`;
    }
}

// ACHIERA Platform - Order Service
// Order lifecycle management with payment and finance integration

import { prisma } from '@/lib/prisma';
import { OrderStatus, PaymentStatus, PaymentMethod } from '@prisma/client';
import { WarehouseService } from './WarehouseService';
import { LoyaltyService } from './LoyaltyService';
import type { ServiceContext } from './WarehouseService';

export type CreateOrderInput = {
    userId: string;
    customerName: string;
    customerEmail: string;
    customerPhone: string;
    shippingAddress: string;
    items: Array<{
        variantId: string;
        quantity: number;
        unitPrice: number;
    }>;
    shippingCost?: number;
    loyaltyPointsUsed?: number;
};

export type ProcessPaymentInput = {
    orderId: string;
    amount: number;
    method: PaymentMethod;
    transactionId?: string;
    proofImage?: string;
};

export class OrderService {
    private warehouseService = new WarehouseService();
    private loyaltyService = new LoyaltyService();

    /**
     * Create new order
     */
    async createOrder(ctx: ServiceContext, input: CreateOrderInput) {
        return prisma.$transaction(async (tx) => {
            // 1. Calculate totals
            const subtotal = input.items.reduce(
                (sum, item) => sum + item.unitPrice * item.quantity,
                0
            );

            const shippingCost = input.shippingCost || 0;
            const tax = subtotal * 0.11; // 11% VAT

            // Calculate loyalty discount
            let loyaltyDiscount = 0;
            if (input.loyaltyPointsUsed) {
                loyaltyDiscount = input.loyaltyPointsUsed; // 1 point = 1 IDR
            }

            const total = subtotal + shippingCost + tax - loyaltyDiscount;

            // 2. Generate order number
            const orderNumber = await this.generateOrderNumber(ctx.brandId);

            // 3. Create order
            const order = await tx.order.create({
                data: {
                    brandId: ctx.brandId,
                    userId: input.userId,
                    orderNumber,
                    customerName: input.customerName,
                    customerEmail: input.customerEmail,
                    customerPhone: input.customerPhone,
                    shippingAddress: input.shippingAddress,
                    subtotal,
                    shippingCost,
                    tax,
                    loyaltyDiscount,
                    total,
                    status: OrderStatus.PENDING,
                    paymentStatus: PaymentStatus.UNPAID
                }
            });

            // 4. Create order items
            for (const item of input.items) {
                const variant = await tx.productVariant.findUnique({
                    where: { id: item.variantId },
                    include: { product: true }
                });

                if (!variant) {
                    throw new Error(`Variant ${item.variantId} not found`);
                }

                await tx.orderItem.create({
                    data: {
                        orderId: order.id,
                        variantId: item.variantId,
                        productName: variant.product.name,
                        variantName: variant.name,
                        quantity: item.quantity,
                        unitPrice: item.unitPrice,
                        subtotal: item.unitPrice * item.quantity
                    }
                });
            }

            // 5. Redeem loyalty points if used
            if (input.loyaltyPointsUsed && input.loyaltyPointsUsed > 0) {
                await this.loyaltyService.redeemPoints(
                    tx,
                    input.userId,
                    ctx.brandId,
                    input.loyaltyPointsUsed,
                    order.id
                );
            }

            // 6. Audit log
            await tx.auditLog.create({
                data: {
                    userId: ctx.userId,
                    brandId: ctx.brandId,
                    action: 'ORDER_CREATE',
                    entityType: 'ORDER',
                    entityId: order.id,
                    metadata: { orderNumber, total }
                }
            });

            return order;
        });
    }

    /**
     * Process payment and fulfill order
     */
    async processPayment(ctx: ServiceContext, input: ProcessPaymentInput) {
        return prisma.$transaction(async (tx) => {
            const order = await tx.order.findUnique({
                where: { id: input.orderId },
                include: { items: true }
            });

            if (!order) {
                throw new Error('Order not found');
            }

            if (order.paymentStatus === PaymentStatus.PAID) {
                throw new Error('Order already paid');
            }

            // 1. Create payment record
            const payment = await tx.payment.create({
                data: {
                    orderId: input.orderId,
                    amount: input.amount,
                    method: input.method,
                    status: PaymentStatus.PAID,
                    transactionId: input.transactionId,
                    proofImage: input.proofImage,
                    paidAt: new Date(),
                    verifiedBy: ctx.userId
                }
            });

            // 2. Update order status
            await tx.order.update({
                where: { id: input.orderId },
                data: {
                    paymentStatus: PaymentStatus.PAID,
                    status: OrderStatus.PROCESSING,
                    paidAt: new Date()
                }
            });

            // 3. Deduct stock (FIFO)
            const defaultWarehouse = await tx.warehouse.findFirst({
                where: { brandId: ctx.brandId, isActive: true }
            });

            if (!defaultWarehouse) {
                throw new Error('No active warehouse found');
            }

            for (const item of order.items) {
                await this.warehouseService.deductStock(
                    ctx,
                    defaultWarehouse.id,
                    item.variantId,
                    item.quantity,
                    order.id
                );
            }

            // 4. Record revenue in ledger
            await this.recordRevenue(tx, ctx.brandId, order.id, input.amount);

            // 5. Award loyalty points
            await this.loyaltyService.awardPoints(
                tx,
                order.userId,
                ctx.brandId,
                order.total,
                order.id
            );

            // 6. Audit log
            await tx.auditLog.create({
                data: {
                    userId: ctx.userId,
                    brandId: ctx.brandId,
                    action: 'PAYMENT_PROCESSED',
                    entityType: 'ORDER',
                    entityId: order.id,
                    metadata: { amount: input.amount, method: input.method }
                }
            });

            return payment;
        });
    }

    /**
     * Cancel order
     */
    async cancelOrder(ctx: ServiceContext, orderId: string, reason: string) {
        return prisma.$transaction(async (tx) => {
            const order = await tx.order.findUnique({
                where: { id: orderId },
                include: { items: true }
            });

            if (!order) {
                throw new Error('Order not found');
            }

            if (order.status === OrderStatus.SHIPPED || order.status === OrderStatus.DELIVERED) {
                throw new Error('Cannot cancel shipped/delivered order');
            }

            // 1. Update order status
            await tx.order.update({
                where: { id: orderId },
                data: {
                    status: OrderStatus.CANCELLED,
                    cancelledAt: new Date()
                }
            });

            // 2. Restore stock if already deducted
            if (order.status === OrderStatus.PROCESSING) {
                const warehouse = await tx.warehouse.findFirst({
                    where: { brandId: ctx.brandId, isActive: true }
                });

                if (warehouse) {
                    for (const item of order.items) {
                        await tx.productVariant.update({
                            where: { id: item.variantId },
                            data: { stockOnHand: { increment: item.quantity } }
                        });

                        await tx.stockMutation.create({
                            data: {
                                warehouseId: warehouse.id,
                                variantId: item.variantId,
                                type: 'ADJUSTMENT',
                                quantity: item.quantity,
                                referenceId: orderId,
                                notes: `Order cancelled: ${reason}`,
                                createdBy: ctx.userId
                            }
                        });
                    }
                }
            }

            // 3. Refund loyalty points if used
            if (order.loyaltyDiscount > 0) {
                await this.loyaltyService.refundPoints(
                    tx,
                    order.userId,
                    ctx.brandId,
                    order.loyaltyDiscount,
                    orderId
                );
            }

            // 4. Audit log
            await tx.auditLog.create({
                data: {
                    userId: ctx.userId,
                    brandId: ctx.brandId,
                    action: 'ORDER_CANCELLED',
                    entityType: 'ORDER',
                    entityId: orderId,
                    metadata: { reason }
                }
            });
        });
    }

    /**
     * Record revenue in ledger (double-entry)
     */
    private async recordRevenue(
        tx: any,
        brandId: string,
        orderId: string,
        amount: number
    ) {
        // Get ledger accounts
        const cashAccount = await tx.ledgerAccount.findFirst({
            where: { brandId, code: '1000-CASH' }
        });

        const revenueAccount = await tx.ledgerAccount.findFirst({
            where: { brandId, code: '4000-REVENUE' }
        });

        if (!cashAccount || !revenueAccount) {
            throw new Error('Ledger accounts not found');
        }

        // Create transaction
        const transaction = await tx.ledgerTransaction.create({
            data: {
                brandId,
                description: `Revenue from Order`,
                referenceId: orderId
            }
        });

        // Debit: Cash (increase asset)
        await tx.ledgerEntry.create({
            data: {
                transactionId: transaction.id,
                accountId: cashAccount.id,
                debit: amount,
                credit: 0
            }
        });

        // Credit: Revenue (increase revenue)
        await tx.ledgerEntry.create({
            data: {
                transactionId: transaction.id,
                accountId: revenueAccount.id,
                debit: 0,
                credit: amount
            }
        });
    }

    /**
     * Generate unique order number
     */
    private async generateOrderNumber(brandId: string): Promise<string> {
        const brand = await prisma.brand.findUnique({
            where: { id: brandId },
            select: { slug: true }
        });

        const date = new Date();
        const year = date.getFullYear().toString().slice(-2);
        const month = (date.getMonth() + 1).toString().padStart(2, '0');
        const day = date.getDate().toString().padStart(2, '0');

        const count = await prisma.order.count({
            where: {
                brandId,
                createdAt: {
                    gte: new Date(date.getFullYear(), date.getMonth(), date.getDate())
                }
            }
        });

        const sequence = (count + 1).toString().padStart(4, '0');

        return `${brand?.slug.toUpperCase()}-${year}${month}${day}-${sequence}`;
    }

    /**
     * Get orders for brand
     */
    async getOrders(
        brandId: string,
        filters?: {
            status?: OrderStatus;
            userId?: string;
            startDate?: Date;
            endDate?: Date;
        }
    ) {
        return prisma.order.findMany({
            where: {
                brandId,
                ...(filters?.status ? { status: filters.status } : {}),
                ...(filters?.userId ? { userId: filters.userId } : {}),
                ...(filters?.startDate || filters?.endDate
                    ? {
                        createdAt: {
                            ...(filters.startDate ? { gte: filters.startDate } : {}),
                            ...(filters.endDate ? { lte: filters.endDate } : {})
                        }
                    }
                    : {})
            },
            include: {
                items: true,
                payments: true,
                user: {
                    select: { name: true, email: true }
                }
            },
            orderBy: { createdAt: 'desc' }
        });
    }
}

import { prisma } from "@/lib/prisma";

export interface DashboardStats {
    totalRevenue: number;
    totalCash: number;
    activeAlerts: number;
}

export interface BrandMetric {
    id: string; // [NEW] Added for reference
    name: string;
    slug: string;
    revenue: number;
    growth: number; // Percentage
    profitMargin: number; // Percentage
    cogsPercentage: number; // COGS as % of Revenue
    efficiency: 'HIGH' | 'MEDIUM' | 'LOW';
}

export interface RiskAlert {
    id: string;
    type: 'INVENTORY' | 'FINANCE' | 'SYSTEM';
    severity: 'HIGH' | 'MEDIUM' | 'LOW';
    message: string;
    brandName: string;
    date: Date;
}

export interface GlobalAssetPortfolio {
    totalValue: number;
    totalDepreciation: number;
    netValue: number;
    assetCount: number;
    byCategory: {
        category: string;
        value: number;
        count: number;
    }[];
    byBrand: {
        brandName: string;
        value: number;
        count: number;
    }[];
}

export interface ConsolidatedFinancials {
    netProfitMargin: number; // Percentage
    totalExpenses: number;
    totalCOGS: number;
    cashFlowTrend: {
        date: string;
        amount: number;
    }[];
}

export class OwnerService {
    /**
     * Get Top-Level Global Stats
     * Revenue = Sum of Credits - Debits for all accounts of type 'REVENUE'
     * Cash = Sum of Debits - Credits for all accounts with code containing 'CASH'
     */
    async getGlobalStats(): Promise<DashboardStats> {
        // 1. Calculate Total Revenue
        // Find all Revenue Accounts
        const revenueAccounts = await prisma.ledgerAccount.findMany({
            where: { type: 'REVENUE' },
            select: { id: true }
        });

        const revIds = revenueAccounts.map(a => a.id);

        // Aggregates
        const revAgg = await prisma.journalEntry.aggregate({
            where: { accountId: { in: revIds } },
            _sum: { credit: true, debit: true }
        });

        const totalRevenue = (Number(revAgg._sum.credit || 0) - Number(revAgg._sum.debit || 0));

        // 2. Calculate Total Cash
        const cashAccounts = await prisma.ledgerAccount.findMany({
            where: {
                OR: [
                    { code: { contains: 'CASH' } },
                    { name: { contains: 'CASH' } },
                    { code: { startsWith: '10' } }, // Common for cash (1000, 1010, etc)
                    { code: { startsWith: '11' } }  // Common for cash/bank
                ]
            },
            select: { id: true }
        });
        const cashIds = cashAccounts.map(a => a.id);

        const cashAgg = await prisma.journalEntry.aggregate({
            where: { accountId: { in: cashIds } },
            _sum: { credit: true, debit: true }
        });

        const totalCash = (Number(cashAgg._sum.debit || 0) - Number(cashAgg._sum.credit || 0));

        // 3. Count Active Risks
        // For now, just a placeholder or call getRisks().length
        const risks = await this.getRisks();

        return {
            totalRevenue,
            totalCash,
            activeAlerts: risks.length
        };
    }

    /**
     * Compare Brands with Enhanced Metrics
     */
    async getBrandComparison(): Promise<BrandMetric[]> {
        const brands = await prisma.brand.findMany({
            where: { isActive: true },
            select: { id: true, name: true, slug: true }
        });

        const metrics: BrandMetric[] = [];

        for (const brand of brands) {
            // Calculate Revenue
            const revenueAccounts = await prisma.ledgerAccount.findMany({
                where: { brandId: brand.id, type: 'REVENUE' },
                select: { id: true }
            });
            const revIds = revenueAccounts.map(a => a.id);

            const revAgg = await prisma.journalEntry.aggregate({
                where: { accountId: { in: revIds } },
                _sum: { credit: true, debit: true }
            });

            const revenue = (Number(revAgg._sum.credit || 0) - Number(revAgg._sum.debit || 0));

            // Calculate COGS
            const cogsAccounts = await prisma.ledgerAccount.findMany({
                where: { brandId: brand.id, code: { startsWith: '5-' }, type: 'EXPENSE' },
                select: { id: true }
            });
            const cogsIds = cogsAccounts.map(a => a.id);

            const cogsAgg = await prisma.journalEntry.aggregate({
                where: { accountId: { in: cogsIds } },
                _sum: { debit: true, credit: true }
            });

            const cogs = (Number(cogsAgg._sum.debit || 0) - Number(cogsAgg._sum.credit || 0));

            // Calculate Total Expenses
            const expenseAccounts = await prisma.ledgerAccount.findMany({
                where: { brandId: brand.id, type: 'EXPENSE' },
                select: { id: true }
            });
            const expIds = expenseAccounts.map(a => a.id);

            const expAgg = await prisma.journalEntry.aggregate({
                where: { accountId: { in: expIds } },
                _sum: { debit: true, credit: true }
            });

            const totalExpenses = (Number(expAgg._sum.debit || 0) - Number(expAgg._sum.credit || 0));

            // Calculate Metrics
            const netProfit = revenue - totalExpenses;
            const profitMargin = revenue > 0 ? (netProfit / revenue) * 100 : 0;
            const cogsPercentage = revenue > 0 ? (cogs / revenue) * 100 : 0;

            // Determine Efficiency
            let efficiency: 'HIGH' | 'MEDIUM' | 'LOW' = 'MEDIUM';
            if (profitMargin >= 25 && cogsPercentage <= 40) efficiency = 'HIGH';
            else if (profitMargin < 10 || cogsPercentage > 60) efficiency = 'LOW';

            metrics.push({
                id: brand.id,
                name: brand.name,
                slug: brand.slug,
                revenue,
                growth: await this.calculateMoM(brand.id, revenue),
                profitMargin,
                cogsPercentage,
                efficiency
            });
        }

        return metrics;
    }

    /**
     * Get Risks (Inventory, Finance)
     */
    async getRisks(): Promise<RiskAlert[]> {
        const alerts: RiskAlert[] = [];

        // 1. Frozen Inventory Expiry Check (Next 7 Days)
        const nextWeek = new Date();
        nextWeek.setDate(nextWeek.getDate() + 7);

        const expiringBatches = await prisma.inventoryBatch.findMany({
            where: {
                isExpired: false,
                quantity: { gt: 0 },
                expiryDate: { lte: nextWeek }
            },
            include: {
                variant: {
                    include: {
                        product: { include: { category: { include: { brand: true } } } }
                    }
                }
            }
        });

        for (const batch of expiringBatches) {
            alerts.push({
                id: `EXP-${batch.id}`,
                type: 'INVENTORY',
                severity: 'HIGH',
                message: `Batch ${batch.batchCode} of ${batch.variant.product.name} expires on ${batch.expiryDate.toISOString().split('T')[0]}`,
                brandName: batch.variant.product.category?.brand.name || 'Unknown',
                date: batch.expiryDate
            });
        }

        return alerts;
    }

    /**
     * Get Global Asset Portfolio
     */
    async getGlobalAssetPortfolio(): Promise<GlobalAssetPortfolio> {
        const assets = await prisma.businessAsset.findMany({
            where: { status: { not: 'DISPOSED' } },
            include: {
                brand: true,
                depreciations: true
            }
        });

        const totalValue = assets.reduce((sum, a) => sum + Number(a.purchasePrice), 0);
        const totalDepreciation = assets.reduce((sum, a) => {
            const assetDep = a.depreciations.reduce((dSum, d) => dSum + Number(d.amount), 0);
            return sum + assetDep;
        }, 0);
        const netValue = totalValue - totalDepreciation;

        // Group by category
        const categoryMap = new Map<string, { value: number; count: number }>();
        assets.forEach(asset => {
            const assetDep = asset.depreciations.reduce((dSum, d) => dSum + Number(d.amount), 0);
            const netAssetValue = Number(asset.purchasePrice) - assetDep;
            const existing = categoryMap.get(asset.category) || { value: 0, count: 0 };
            existing.value += netAssetValue;
            existing.count += 1;
            categoryMap.set(asset.category, existing);
        });

        // Group by brand
        const brandMap = new Map<string, { value: number; count: number }>();
        assets.forEach(asset => {
            const assetDep = asset.depreciations.reduce((dSum, d) => dSum + Number(d.amount), 0);
            const netAssetValue = Number(asset.purchasePrice) - assetDep;
            const existing = brandMap.get(asset.brand.name) || { value: 0, count: 0 };
            existing.value += netAssetValue;
            existing.count += 1;
            brandMap.set(asset.brand.name, existing);
        });

        return {
            totalValue,
            totalDepreciation,
            netValue,
            assetCount: assets.length,
            byCategory: Array.from(categoryMap.entries()).map(([category, data]) => ({
                category,
                value: data.value,
                count: data.count
            })),
            byBrand: Array.from(brandMap.entries()).map(([brandName, data]) => ({
                brandName,
                value: data.value,
                count: data.count
            }))
        };
    }

    /**
     * Get Consolidated Financials
     */
    async getConsolidatedFinancials(): Promise<ConsolidatedFinancials> {
        // Calculate Global Revenue
        const revenueAccounts = await prisma.ledgerAccount.findMany({
            where: { type: 'REVENUE' },
            select: { id: true }
        });
        const revIds = revenueAccounts.map(a => a.id);

        const revAgg = await prisma.journalEntry.aggregate({
            where: { accountId: { in: revIds } },
            _sum: { credit: true, debit: true }
        });
        const totalRevenue = (Number(revAgg._sum.credit || 0) - Number(revAgg._sum.debit || 0));

        // Calculate Global Expenses
        const expenseAccounts = await prisma.ledgerAccount.findMany({
            where: { type: 'EXPENSE' },
            select: { id: true }
        });
        const expIds = expenseAccounts.map(a => a.id);

        const expAgg = await prisma.journalEntry.aggregate({
            where: { accountId: { in: expIds } },
            _sum: { debit: true, credit: true }
        });
        const totalExpenses = (Number(expAgg._sum.debit || 0) - Number(expAgg._sum.credit || 0));

        // Calculate Global COGS
        const cogsAccounts = await prisma.ledgerAccount.findMany({
            where: { code: { startsWith: '5-' }, type: 'EXPENSE' },
            select: { id: true }
        });
        const cogsIds = cogsAccounts.map(a => a.id);

        const cogsAgg = await prisma.journalEntry.aggregate({
            where: { accountId: { in: cogsIds } },
            _sum: { debit: true, credit: true }
        });
        const totalCOGS = (Number(cogsAgg._sum.debit || 0) - Number(cogsAgg._sum.credit || 0));

        // Calculate Net Profit Margin
        const netProfit = totalRevenue - totalExpenses;
        const netProfitMargin = totalRevenue > 0 ? (netProfit / totalRevenue) * 100 : 0;

        // Cash Flow Trend (Last 30 days)
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

        const cashAccounts = await prisma.ledgerAccount.findMany({
            where: { code: { contains: 'CASH' } },
            select: { id: true }
        });
        const cashIds = cashAccounts.map(a => a.id);

        const cashEntries = await prisma.journalEntry.findMany({
            where: {
                accountId: { in: cashIds },
                createdAt: { gte: thirtyDaysAgo }
            },
            orderBy: { createdAt: 'asc' },
            select: {
                createdAt: true,
                debit: true,
                credit: true
            }
        });

        // Group by date
        const dailyFlow = new Map<string, number>();
        cashEntries.forEach(entry => {
            const date = entry.createdAt.toISOString().split('T')[0];
            const flow = Number(entry.debit) - Number(entry.credit);
            dailyFlow.set(date, (dailyFlow.get(date) || 0) + flow);
        });

        const cashFlowTrend = Array.from(dailyFlow.entries())
            .map(([date, amount]) => ({ date, amount }))
            .sort((a, b) => a.date.localeCompare(b.date));

        return {
            netProfitMargin,
            totalExpenses,
            totalCOGS,
            cashFlowTrend
        };
    }

    /**
     * Get Recent Interactions (Contact leads, etc.)
     */
    async getRecentInteractions() {
        const events = await prisma.analyticsEvent.findMany({
            where: {
                type: 'HERO_CTA_CLICK'
            },
            take: 10,
            orderBy: { createdAt: 'desc' },
            include: { brand: { select: { name: true } } } as any
        });

        return events.map((e: any) => ({
            id: e.id,
            brandName: e.brand?.name || 'Unknown',
            timestamp: e.createdAt,
            data: e.metadata as any
        }));
