import { prisma } from '@/lib/prisma';
import { waEngine } from '@/lib/whatsapp/engine';

export class WhatsAppProcessor {
    private static isRunning = false;
    private static intervalId: NodeJS.Timeout | null = null;

    /**
     * Start the background processor.
     * It polls the database every 10 seconds for pending messages.
     */
    static start() {
        if (this.intervalId) return;

        console.log('[WhatsAppProcessor] Background worker started.');
        this.intervalId = setInterval(() => this.processNext(), 10000); // 10s polling
    }

    static stop() {
        if (this.intervalId) {
            clearInterval(this.intervalId);
            this.intervalId = null;
        }
    }

    /**
     * Fetch the next pending message and send it.
     */
    private static async processNext() {
        if (this.isRunning) return;
        this.isRunning = true;

        try {
            // Fetch next pending message based on priority and schedule
            const queueItem = await (prisma as any).whatsAppQueue.findFirst({
                where: {
                    status: 'PENDING',
                    scheduledFor: { lte: new Date() }
                },
                orderBy: [
                    { priority: 'asc' },
                    { createdAt: 'asc' }
                ]
            });

            if (!queueItem) {
                this.isRunning = false;
                return;
            }

            // Mark as processing
            await (prisma as any).whatsAppQueue.update({
                where: { id: queueItem.id },
                data: { status: 'PROCESSING' }
            });

            console.log(`[WhatsAppProcessor] Processing message for ${queueItem.phone} (Pri: ${queueItem.priority})`);

            try {
                // Send via engine
                await waEngine.sendMessage(queueItem.phone, queueItem.text, queueItem.priority);

                // Success
                await (prisma as any).whatsAppQueue.update({
                    where: { id: queueItem.id },
                    data: {
                        status: 'SENT',
                        sentAt: new Date(),
                        attempts: queueItem.attempts + 1
                    }
                });

                console.log(`[WhatsAppProcessor] Successfully sent to ${queueItem.phone}`);

                // HUMAN DELAY: Wait 15-45 seconds before next message to avoid ban
                const delay = Math.floor(Math.random() * (45000 - 15000 + 1) + 15000);
                console.log(`[WhatsAppProcessor] Throttling for ${delay / 1000}s...`);
                setTimeout(() => {
                    this.isRunning = false;
                }, delay);

            } catch (error: any) {
                console.error(`[WhatsAppProcessor] Failed to send to ${queueItem.phone}:`, error.message);

                // Handle Failure & Retries
                const isRetryable = queueItem.attempts < 3;
                await (prisma as any).whatsAppQueue.update({
                    where: { id: queueItem.id },
                    data: {
                        status: isRetryable ? 'PENDING' : 'FAILED',
                        errorMessage: error.message,
                        attempts: queueItem.attempts + 1,
                        scheduledFor: new Date(Date.now() + (queueItem.attempts + 1) * 60000) // Backoff
                    }
                });
                this.isRunning = false;
            }

        } catch (error) {
            console.error('[WhatsAppProcessor] Critical Error:', error);
            this.isRunning = false;
        }
    }
}

// ACHIERA Platform - Enhanced Security Middleware
// Server-side RBAC enforcement with role escalation prevention

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { getToken } from 'next-auth/jwt';
import { prisma } from '@/lib/prisma';
import { GlobalRole, BrandRole } from '@prisma/client';

const SECURITY_HEADERS = {
    'X-Frame-Options': 'DENY',
    'X-Content-Type-Options': 'nosniff',
    'X-XSS-Protection': '1; mode=block',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
    'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
    'Strict-Transport-Security': 'max-age=31536000; includeSubDomains'
};

// Rate limiting store (use Redis in production)
const rateLimitStore = new Map<string, { count: number; resetAt: number }>();

/**
 * Security middleware with comprehensive protection
 */
export async function securityMiddleware(request: NextRequest) {
    const response = NextResponse.next();

    // 1. Add security headers
    Object.entries(SECURITY_HEADERS).forEach(([key, value]) => {
        response.headers.set(key, value);
    });

    // 2. Rate limiting
    const ip = request.ip || request.headers.get('x-forwarded-for') || 'unknown';
    const rateLimitKey = `${ip}:${request.nextUrl.pathname}`;

    if (!isRateLimitOk(rateLimitKey)) {
        return new NextResponse('Too Many Requests', {
            status: 429,
            headers: {
                'Retry-After': '60'
            }
        });
    }

    // 3. CSRF protection for mutations
    if (['POST', 'PUT', 'DELETE', 'PATCH'].includes(request.method)) {
        const origin = request.headers.get('origin');
        const host = request.headers.get('host');

        if (origin && !isValidOrigin(origin, host)) {
            await logSecurityEvent({
                type: 'CSRF_ATTEMPT',
                ip,
                origin,
                path: request.nextUrl.pathname
            });

            return new NextResponse('Forbidden', { status: 403 });
        }
    }

    // 4. Authentication check for protected routes
    if (isProtectedRoute(request.nextUrl.pathname)) {
        const token = await getToken({
            req: request,
            secret: process.env.NEXTAUTH_SECRET
        });

        if (!token) {
            await logSecurityEvent({
                type: 'UNAUTHORIZED_ACCESS',
                ip,
                path: request.nextUrl.pathname
            });

            return NextResponse.redirect(new URL('/login', request.url));
        }

        // 5. Brand access verification
        const brandSlug = extractBrandSlug(request.nextUrl.pathname);
        if (brandSlug && brandSlug !== 'owner') {
            const hasAccess = await verifyBrandAccess(
                token.userId as string,
                brandSlug,
                token.globalRole as GlobalRole
            );

            if (!hasAccess) {
                await logSecurityEvent({
                    type: 'UNAUTHORIZED_BRAND_ACCESS',
                    userId: token.userId as string,
                    brandSlug,
                    ip,
                    path: request.nextUrl.pathname
                });

                return new NextResponse('Access Denied', { status: 403 });
            }
        }

        // 6. Owner-only routes
        if (request.nextUrl.pathname.startsWith('/owner')) {
            if (token.globalRole !== 'OWNER') {
                await logSecurityEvent({
                    type: 'OWNER_ROUTE_ACCESS_DENIED',
                    userId: token.userId as string,
                    globalRole: token.globalRole as string,
                    ip,
                    path: request.nextUrl.pathname
                });

                return new NextResponse('Owner Access Required', { status: 403 });
            }
        }
    }

    return response;
}

/**
 * Rate limiting check
 */
function isRateLimitOk(key: string): boolean {
    const now = Date.now();
    const limit = rateLimitStore.get(key);

    if (!limit || now > limit.resetAt) {
        rateLimitStore.set(key, {
            count: 1,
            resetAt: now + 60000 // 1 minute window
        });
        return true;
    }

    if (limit.count >= 100) { // 100 requests per minute
        return false;
    }

    limit.count++;
    return true;
}

/**
 * Validate origin for CSRF protection
 */
function isValidOrigin(origin: string, host: string | null): boolean {
    if (!host) return false;

    const allowedOrigins = [
        `https://${host}`,
        `http://${host}`,
        process.env.NEXTAUTH_URL
    ].filter(Boolean);

    return allowedOrigins.some(allowed => origin.startsWith(allowed as string));
}

/**
 * Check if route requires authentication
 */
function isProtectedRoute(pathname: string): boolean {
    const protectedPrefixes = [
        '/dashboard',
        '/owner',
        '/api/admin',
        '/api/auth/session'
    ];

    return protectedPrefixes.some(prefix => pathname.startsWith(prefix));
}

/**
 * Extract brand slug from pathname
 */
function extractBrandSlug(pathname: string): string | null {
    const match = pathname.match(/^\/dashboard\/([^\/]+)/);
    return match ? match[1] : null;
}

/**
 * Verify user has access to brand
 */
async function verifyBrandAccess(
    userId: string,
    brandSlug: string,
    globalRole: GlobalRole
): Promise<boolean> {
    // OWNER bypass
    if (globalRole === 'OWNER') {
        return true;
    }

    // Check brand access
    const brand = await prisma.brand.findUnique({
        where: { slug: brandSlug },
        select: { id: true }
    });

    if (!brand) return false;

    const userRole = await prisma.userBrandRole.findUnique({
        where: {
            userId_brandId: {
                userId,
                brandId: brand.id
            }
        }
    });

    return !!userRole;
}

/**
 * Log security events
 */
async function logSecurityEvent(event: {
    type: string;
    userId?: string;
    brandSlug?: string;
    globalRole?: string;
    ip: string;
    origin?: string;
    path: string;
}) {
    try {
        await prisma.auditLog.create({
            data: {
                userId: event.userId || null,
                brandId: null,
                action: `SECURITY_${event.type}`,
                entityType: 'SECURITY',
                entityId: 'SYSTEM',
                metadata: {
                    type: event.type,
                    ip: event.ip,
                    path: event.path,
                    origin: event.origin,
                    globalRole: event.globalRole,
                    brandSlug: event.brandSlug,
                    timestamp: new Date().toISOString()
                }
            }
        });
    } catch (error) {
        console.error('Failed to log security event:', error);
    }
}

/**
 * Middleware config
 */
export const config = {
    matcher: [
        '/dashboard/:path*',
        '/owner/:path*',
        '/api/:path*'
    ]
};

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { getToken } from 'next-auth/jwt';

export async function middleware(request: NextRequest) {
    const token = await getToken({
        req: request,
        secret: process.env.NEXTAUTH_SECRET,
    });

    const isAuthPage = request.nextUrl.pathname.startsWith('/login');
    const isDashboard = request.nextUrl.pathname.startsWith('/dashboard');

    // Redirect to login if accessing dashboard without auth
    if (isDashboard) {
        if (!token) {
            return NextResponse.redirect(new URL('/login', request.url));
        }

        // BLOCK 'USER' ROLE FROM DASHBOARD
        // Customers/Subscribers should never see the admin dashboard
        if (token.globalRole === 'USER') {
            return NextResponse.redirect(new URL('/rasa-ibu/profile', request.url));
        }
    }

    // Redirect to dashboard if already logged in and trying to access login
    if (isAuthPage && token) {
        return NextResponse.redirect(new URL('/dashboard', request.url));
    }

    // Brand-specific dashboard access control
    if (isDashboard && token) {
        const pathParts = request.nextUrl.pathname.split('/');

        // If accessing /dashboard/[brandSlug]/...
        if (pathParts.length >= 3 && pathParts[1] === 'dashboard' && pathParts[2]) {
            const brandSlug = pathParts[2];
            const brands = (token.brands as any[]) || [];
            const globalRole = token.globalRole as string;

            // OWNER always has access, or check specific brand roles for others
            const hasAccess = globalRole === 'OWNER' || brands.some((br: any) => br.brandSlug === brandSlug);

            if (!hasAccess) {
                // Redirect to first brand they have access to
                if (brands.length > 0) {
                    return NextResponse.redirect(
                        new URL(`/dashboard/${brands[0].brandSlug}`, request.url)
                    );
                }
                // No brand access at all - redirect to login
                return NextResponse.redirect(new URL('/login', request.url));
            }
        }
    }

    return NextResponse.next();
}

export const config = {
    matcher: ['/dashboard/:path*', '/login'],
};

import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

async function reconcileStock() {
    const brandSlug = 'rasa-ibu';
    const brand = await prisma.brand.findUnique({ where: { slug: brandSlug } });
    if (!brand) return console.log('Brand not found');

    const warehouse = await prisma.warehouse.findFirst({ where: { brandId: brand.id, isDefault: true } });
    if (!warehouse) return console.log('Warehouse not found');

    const variants = await prisma.frozenVariant.findMany({
        where: { product: { category: { brandId: brand.id } } },
