// ACHIERA Platform - Data Integrity Validation Script
// Run this to verify data consistency across the system

import { prisma } from '@/lib/prisma';
import { verifyLedgerIntegrity } from '@/lib/hardening/ledger-integrity';

interface IntegrityIssue {
    severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';
    category: string;
    description: string;
    affectedRecords: number;
    details?: any;
}

/**
 * Check for orphan records (records without required parent)
 */
async function checkOrphanRecords(): Promise<IntegrityIssue[]> {
    const issues: IntegrityIssue[] = [];

    // Orphan orders (no brand)
    const orphanOrders = await prisma.order.count({
        where: { brand: null }
    });
    if (orphanOrders > 0) {
        issues.push({
            severity: 'CRITICAL',
            category: 'ORPHAN_RECORDS',
            description: 'Orders without brand reference',
            affectedRecords: orphanOrders
        });
    }

    // Orphan order items (no order)
    const orphanOrderItems = await prisma.orderItem.count({
        where: { order: null }
    });
    if (orphanOrderItems > 0) {
        issues.push({
            severity: 'HIGH',
            category: 'ORPHAN_RECORDS',
            description: 'Order items without order reference',
            affectedRecords: orphanOrderItems
        });
    }

    // Orphan payments (no order)
    const orphanPayments = await prisma.payment.count({
        where: { order: null }
    });
    if (orphanPayments > 0) {
        issues.push({
            severity: 'CRITICAL',
            category: 'ORPHAN_RECORDS',
            description: 'Payments without order reference',
            affectedRecords: orphanPayments
        });
    }

    return issues;
}

/**
 * Check for negative stock
 */
async function checkNegativeStock(): Promise<IntegrityIssue[]> {
    const issues: IntegrityIssue[] = [];

    const negativeStock = await prisma.frozenVariant.findMany({
        where: { stockOnHand: { lt: 0 } },
        select: { id: true, name: true, stockOnHand: true }
    });

    if (negativeStock.length > 0) {
        issues.push({
            severity: 'CRITICAL',
            category: 'STOCK_INTEGRITY',
            description: 'Variants with negative stock',
            affectedRecords: negativeStock.length,
            details: negativeStock
        });
    }

    return issues;
}

/**
 * Verify ledger balance for all brands
 */
async function checkLedgerBalance(): Promise<IntegrityIssue[]> {
    const issues: IntegrityIssue[] = [];

    const brands = await prisma.brand.findMany();

    for (const brand of brands) {
        const result = await verifyLedgerIntegrity(brand.id);

        if (!result.isValid) {
            issues.push({
                severity: 'CRITICAL',
                category: 'LEDGER_INTEGRITY',
                description: `Ledger imbalance for brand: ${brand.name}`,
                affectedRecords: result.errors.length,
                details: result.errors
            });
        }
    }

    return issues;
}

/**
 * Check for missing required accounts
 */
async function checkRequiredAccounts(): Promise<IntegrityIssue[]> {
    const issues: IntegrityIssue[] = [];
    const requiredAccounts = ['1000-CASH', '4000-REVENUE', '5000-COGS'];

    const brands = await prisma.brand.findMany();

    for (const brand of brands) {
        const accounts = await prisma.ledgerAccount.findMany({
            where: { brandId: brand.id },
            select: { code: true }
        });

        const accountCodes = accounts.map(a => a.code);
        const missing = requiredAccounts.filter(code => !accountCodes.includes(code));

        if (missing.length > 0) {
            issues.push({
                severity: 'HIGH',
                category: 'MISSING_ACCOUNTS',
                description: `Brand "${brand.name}" missing required accounts`,
                affectedRecords: missing.length,
                details: { brandId: brand.id, missingAccounts: missing }
            });
        }
    }

    return issues;
}

/**
 * Check stock vs inventory batch consistency
 */
async function checkStockBatchConsistency(): Promise<IntegrityIssue[]> {
    const issues: IntegrityIssue[] = [];

    const variants = await prisma.frozenVariant.findMany({
        include: {
            batches: true
        }
    });

    for (const variant of variants) {
        const batchTotal = variant.batches.reduce((sum, batch) => sum + batch.quantity, 0);

        if (batchTotal !== variant.stockOnHand) {
            issues.push({
                severity: 'HIGH',
                category: 'STOCK_BATCH_MISMATCH',
                description: `Stock mismatch for variant: ${variant.name}`,
                affectedRecords: 1,
                details: {
                    variantId: variant.id,
                    stockOnHand: variant.stockOnHand,
                    batchTotal
                }
            });
        }
    }

    return issues;
}

/**
 * Check for duplicate idempotency keys (should never happen)
 */
async function checkIdempotencyDuplicates(): Promise<IntegrityIssue[]> {
    const issues: IntegrityIssue[] = [];

    const duplicates = await prisma.$queryRaw<Array<{ key: string; count: number }>>`
        SELECT "key", COUNT(*) as count
        FROM "idempotency_records"
        GROUP BY "key"
        HAVING COUNT(*) > 1
    `;

    if (duplicates.length > 0) {
        issues.push({
            severity: 'CRITICAL',
            category: 'IDEMPOTENCY_VIOLATION',
            description: 'Duplicate idempotency keys detected',
            affectedRecords: duplicates.length,
            details: duplicates
        });
    }

    return issues;
}

/**
 * Main validation function
 */
export async function validateDataIntegrity(): Promise<{
    isValid: boolean;
    issues: IntegrityIssue[];
    summary: {
        critical: number;
        high: number;
        medium: number;
        low: number;
    };
}> {
    console.log('Starting data integrity validation...\n');

    const allIssues: IntegrityIssue[] = [];

    // Run all checks
    const checks = [
        { name: 'Orphan Records', fn: checkOrphanRecords },
        { name: 'Negative Stock', fn: checkNegativeStock },
        { name: 'Ledger Balance', fn: checkLedgerBalance },
        { name: 'Required Accounts', fn: checkRequiredAccounts },
        { name: 'Stock-Batch Consistency', fn: checkStockBatchConsistency },
        { name: 'Idempotency Duplicates', fn: checkIdempotencyDuplicates }
    ];

    for (const check of checks) {
        console.log(`Running: ${check.name}...`);
        const issues = await check.fn();
        allIssues.push(...issues);
        console.log(`  Found ${issues.length} issues\n`);
    }

    // Summarize by severity
    const summary = {
        critical: allIssues.filter(i => i.severity === 'CRITICAL').length,
        high: allIssues.filter(i => i.severity === 'HIGH').length,
        medium: allIssues.filter(i => i.severity === 'MEDIUM').length,
        low: allIssues.filter(i => i.severity === 'LOW').length
    };

    console.log('Validation Complete\n');
    console.log('Summary:');
    console.log(`  CRITICAL: ${summary.critical}`);
    console.log(`  HIGH: ${summary.high}`);
    console.log(`  MEDIUM: ${summary.medium}`);
    console.log(`  LOW: ${summary.low}`);
    console.log(`  Total: ${allIssues.length}\n`);

    if (allIssues.length > 0) {
        console.log('Issues Found:');
        allIssues.forEach((issue, index) => {
            console.log(`\n${index + 1}. [${issue.severity}] ${issue.category}`);
            console.log(`   ${issue.description}`);
            console.log(`   Affected Records: ${issue.affectedRecords}`);
            if (issue.details) {
                console.log(`   Details: ${JSON.stringify(issue.details, null, 2)}`);
            }
        });
    }

    return {
        isValid: summary.critical === 0 && summary.high === 0,
        issues: allIssues,
        summary
    };
}

// CLI execution
if (require.main === module) {
    validateDataIntegrity()
        .then(result => {
            process.exit(result.isValid ? 0 : 1);
        })
        .catch(error => {
            console.error('Validation failed:', error);
            process.exit(1);
        });
}

// ACHIERA Platform - Restore Verification Script
// Verifies database integrity after restore

import { prisma } from '@/lib/prisma';
import { verifyLedgerIntegrity } from '@/lib/hardening/ledger-integrity';
import { validateDataIntegrity } from './validate-data-integrity';

interface VerificationResult {
    passed: boolean;
    checks: Array<{
        name: string;
        status: 'PASS' | 'FAIL' | 'WARN';
        details?: any;
    }>;
}

/**
 * Verify database restore
 */
export async function verifyRestore(): Promise<VerificationResult> {
    console.log('Starting restore verification...\n');

    const checks: VerificationResult['checks'] = [];

    // 1. Table count
    try {
        const tables = await prisma.$queryRaw<Array<any>>`SHOW TABLES`;
        const tableCount = tables.length;

        checks.push({
            name: 'Table Count',
            status: tableCount >= 25 ? 'PASS' : 'FAIL',
            details: { count: tableCount, expected: '≥25' }
        });
    } catch (error) {
        checks.push({
            name: 'Table Count',
            status: 'FAIL',
            details: { error: (error as Error).message }
        });
    }

    // 2. Record counts
    try {
        const brands = await prisma.brand.count();
        const orders = await prisma.order.count();
        const users = await prisma.user.count();

        checks.push({
            name: 'Record Counts',
            status: 'PASS',
            details: { brands, orders, users }
        });
    } catch (error) {
        checks.push({
            name: 'Record Counts',
            status: 'FAIL',
            details: { error: (error as Error).message }
        });
    }

    // 3. Ledger integrity for all brands
    try {
        const brands = await prisma.brand.findMany();
        let allValid = true;
        const ledgerResults: any[] = [];

        for (const brand of brands) {
            const ledgerCheck = await verifyLedgerIntegrity(brand.id);
            ledgerResults.push({
                brandId: brand.id,
                brandName: brand.name,
                valid: ledgerCheck.isValid,
                errors: ledgerCheck.errors.length
            });

            if (!ledgerCheck.isValid) {
                allValid = false;
            }
        }

        checks.push({
            name: 'Ledger Integrity',
            status: allValid ? 'PASS' : 'FAIL',
            details: ledgerResults
        });
    } catch (error) {
        checks.push({
            name: 'Ledger Integrity',
            status: 'FAIL',
            details: { error: (error as Error).message }
        });
    }

    // 4. Data integrity
    try {
        const integrityCheck = await validateDataIntegrity();

        checks.push({
            name: 'Data Integrity',
            status: integrityCheck.isValid ? 'PASS' : 'FAIL',
            details: {
                critical: integrityCheck.summary.critical,
                high: integrityCheck.summary.high,
                total: integrityCheck.issues.length
            }
        });
    } catch (error) {
        checks.push({
            name: 'Data Integrity',
            status: 'FAIL',
            details: { error: (error as Error).message }
        });
    }

    // 5. Foreign key constraints
    try {
        const orphanOrders = await prisma.order.count({
            where: { brand: null }
        });
        const orphanPayments = await prisma.payment.count({
            where: { order: null }
        });

        checks.push({
            name: 'Foreign Key Integrity',
            status: (orphanOrders === 0 && orphanPayments === 0) ? 'PASS' : 'FAIL',
            details: { orphanOrders, orphanPayments }
        });
    } catch (error) {
        checks.push({
            name: 'Foreign Key Integrity',
            status: 'FAIL',
            details: { error: (error as Error).message }
        });
    }

    // 6. Index integrity
    try {
        // Verify critical indexes exist
        const indexes = await prisma.$queryRaw<Array<any>>`
            SELECT DISTINCT TABLE_NAME, INDEX_NAME
            FROM INFORMATION_SCHEMA.STATISTICS
            WHERE TABLE_SCHEMA = DATABASE()
            AND INDEX_NAME != 'PRIMARY'
        `;

        checks.push({
            name: 'Index Integrity',
            status: indexes.length > 0 ? 'PASS' : 'WARN',
            details: { indexCount: indexes.length }
        });
    } catch (error) {
        checks.push({
            name: 'Index Integrity',
            status: 'WARN',
            details: { error: (error as Error).message }
        });
    }

    // Summary
    const passed = checks.every(c => c.status === 'PASS' || c.status === 'WARN');
    const failed = checks.filter(c => c.status === 'FAIL');

    console.log('\nVerification Results:');
    console.log('='.repeat(50));

    checks.forEach(check => {
        const icon = check.status === 'PASS' ? '✅' : check.status === 'WARN' ? '⚠️' : '❌';
        console.log(`${icon} ${check.name}: ${check.status}`);
        if (check.details) {
            console.log(`   ${JSON.stringify(check.details, null, 2)}`);
        }
    });

    console.log('='.repeat(50));
    console.log(`\nOverall: ${passed ? '✅ PASSED' : '❌ FAILED'}`);

    if (failed.length > 0) {
        console.log(`\nFailed Checks (${failed.length}):`);
        failed.forEach(f => console.log(`  - ${f.name}`));
    }

    return { passed, checks };
}

// CLI execution
if (require.main === module) {
    verifyRestore()
        .then(result => {
            process.exit(result.passed ? 0 : 1);
        })
        .catch(error => {
            console.error('Verification failed:', error);
            process.exit(1);
        });
}

/**
 * Detects the number of distinct colors in an image.
 * Uses a distance threshold to group similar colors (handling anti-aliasing/compression artifacts).
 */
export async function detectColors(imageSrc: string): Promise<{ count: number, colors: string[] }> {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.src = imageSrc;

        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            if (!ctx) {
                resolve({ count: 1, colors: ['#000000'] });
                return;
            }

            // Downscale for performance (max 500px dimension)
            const MAX_SIZE = 500;
            let width = img.width;
            let height = img.height;

            if (width > height) {
                if (width > MAX_SIZE) {
                    height *= MAX_SIZE / width;
                    width = MAX_SIZE;
                }
            } else {
                if (height > MAX_SIZE) {
                    width *= MAX_SIZE / height;
                    height = MAX_SIZE;
                }
            }

            canvas.width = width;
            canvas.height = height;
            ctx.drawImage(img, 0, 0, width, height);

            const imageData = ctx.getImageData(0, 0, width, height);
            const data = imageData.data;
            const uniqueColors: { r: number, g: number, b: number }[] = [];
            const THRESHOLD = 30; // Delta E or RGB distance threshold

            for (let i = 0; i < data.length; i += 4) {
                const r = data[i];
                const g = data[i + 1];
                const b = data[i + 2];
                const a = data[i + 3];

                // Ignore transparent pixels
                if (a < 128) continue;

                // Check if color is similar to any existing unique color
                let isNewColor = true;
                for (const color of uniqueColors) {
                    const dist = Math.sqrt(
                        Math.pow(r - color.r, 2) +
                        Math.pow(g - color.g, 2) +
                        Math.pow(b - color.b, 2)
                    );

                    if (dist < THRESHOLD) {
                        isNewColor = false;
                        break;
                    }
                }

                if (isNewColor) {
                    uniqueColors.push({ r, g, b });
                }

                // Safety break for performance/spam
                if (uniqueColors.length > 20) {
                    break;
                }
            }

            // Convert to Hex
            const hexColors = uniqueColors.map(c =>
                "#" + ((1 << 24) + (c.r << 16) + (c.g << 8) + c.b).toString(16).slice(1).toUpperCase()
            );

            resolve({
                count: uniqueColors.length,
                colors: hexColors
            });
        };

        img.onerror = (err) => {
            console.error("Error loading image for color detection", err);
            resolve({ count: 1, colors: [] });
        };
    });
}

